(131554, 'zhTW', '耶！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(131553, 'zhTW', '謝謝你！', '', 25549),
(131552, 'zhTW', '我愛你。', '', 25549),
(131551, 'zhTW', '<梟獸寶寶跟你在一起似乎很開心。>', '', 25549),
(131550, 'zhTW', '使用靈藥。', '使用靈藥。', 25549),
(131549, 'zhTW', '…', '', 25549),
(131548, 'zhTW', '救我。', '', 25549),
(131547, 'zhTW', '救救我。', '', 25549),
(131546, 'zhTW', '救命…', '', 25549),
(131545, 'zhTW', '呃…', '', 25549),
(131538, 'zhTW', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s開始施放|cFFFF0000|Hspell:244509|h[薩格萊羈絆]|h|r。', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s開始施放|cFFFF0000|Hspell:244509|h[薩格萊羈絆]|h|r。', 25549),
(131537, 'zhTW', '礦坑現在無法佔領。', '', 25549),
