INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(130514, 'zhTW', '部隊音效', '', 25549),
(130513, 'zhTW', 'Sound effect for troops', 'Sound effect for troops', 25549),
(130512, 'zhTW', '我想參與時尚大考驗！', '我想參與時尚大考驗！', 25549),
(130511, 'zhTW', '只要你能盡快帶回生產所需的資源，我們就能馬上為你取得神兵知識。', '只要你能盡快帶回生產所需的資源，我們就能馬上為你取得神兵知識。', 25549),
(130510, 'zhTW', '我想要塑形我的裝備。', '我想要塑形我的裝備。', 25549),
(130509, 'zhTW', '我有全副工具，你想怎麼調整你的武器或護具外觀都行。\n\n要開始了嗎？', '', 25549),
(130508, 'zhTW', '大法師卡德加發現能繼續研究神兵知識的方法。去破碎海岸的審判角找他吧。', '大法師卡德加發現能繼續研究神兵知識的方法。去破碎海岸的審判角找他吧。', 25549),
(130507, 'zhTW', '我們已經達到目前的神兵知識上限了。', '我們已經達到目前的神兵知識上限了。', 25549),
(130506, 'zhTW', '職業組織開始共享資源，你不需要再研究神兵知識了。我們每週都會獲得進一步的神兵知識。', '職業組織開始共享資源，你不需要再研究神兵知識了。我們每週都會獲得進一步的神兵知識。', 25549),
(130505, 'zhTW', '為什麼我不能再研究神兵知識了？', '為什麼我不能再研究神兵知識了？', 25549),
(130504, 'zhTW', '無論如何，我們都要團結。', '', 25549),
(130503, 'zhTW', '鮮肉自己送上門了！', '', 25549),
(130502, 'zhTW', '我要拿你的屍體來填坑！', '', 25549),
(130501, 'zhTW', '鎖鏈會打爛你的血肉！', '', 25549),
(130500, 'zhTW', '不屈服，就受死吧！', '', 25549),
(130499, 'zhTW', '軟弱的蟲子！竟敢闖進我們的地盤？', '', 25549),
(130498, 'zhTW', '我要吃你們的血肉來填飽肚子！', '', 25549),
(130497, 'zhTW', '你們的骨頭好脆。真美味！', '', 25549),
(130496, 'zhTW', '我要吞噬你們的靈魂！', '', 25549),
(130483, 'zhTW', '放肆的凡人！過來受死吧！', '', 25549),
(130482, 'zhTW', '過來這裡。不要被發現了。', '', 25549),
(130481, 'zhTW', '沒錯…今天的比賽沒有主題。你想穿什麼都可以！', '', 25549),
(130480, 'zhTW', '嶄新的白色長袍和發光的護甲是今天最時尚的裝扮！', '', 25549),
(130479, 'zhTW', '大家都知道，史詩級護甲都是紫色的。用彩虹的最後一個顏色來妝點自己吧！', '', 25549),
(130478, 'zhTW', '你會扮成農夫？廚師？科學家？還是海盜？喔…我等不及要看各位的扮相了！', '', 25549),
(130477, 'zhTW', '你想代表塞拉摩？還是祈倫托？穿上最吸睛的外袍吧！', '', 25549),
(130476, 'zhTW', '大玩一場，來個最瘋狂的打扮吧！', '', 25549),
(130475, 'zhTW', '擦亮你的護甲，準備擺出最迷人的姿勢！', '', 25549),
(130474, 'zhTW', '披上野獸的毛皮或是用藤蔓裹住自己！秀出你野性的一面吧。', '', 25549),
(130473, 'zhTW', '為了部落！為了聯盟！秀出你陣營的色彩吧。', '', 25549),
(130472, 'zhTW', '用你的穿搭來展現邪惡氛圍吧！', '', 25549),
(130471, 'zhTW', '時尚就是要有對比，但這樣的對比真的時尚嗎？', '', 25549),
(130470, 'zhTW', '玩一點創意，做出最花俏的打扮！', '', 25549),
(130469, 'zhTW', '我心跳得好快啊！露出你的肌膚，不要害羞！', '', 25549),
(130468, 'zhTW', '卸掉臉上的妝，塗上戰爭顏料吧！', '', 25549),
(130467, 'zhTW', '穿暖一點！我們來看看在北裂境的冰凍海岸上要怎麼穿搭！', '', 25549),
(130466, 'zhTW', '', '今天的比賽主題是…即興發揮！', 25549),
(130465, 'zhTW', '', '今天的比賽主題是…聖光勇士！', 25549),
(130464, 'zhTW', '', '今天的比賽主題是…紫色史詩！', 25549),
(130463, 'zhTW', '', '今天的比賽主題是…英雄日常！', 25549),
(130462, 'zhTW', '', '今天的比賽主題是…長袍時間！', 25549),
(130461, 'zhTW', '', '今天的比賽主題是…製造笑果！', 25549),
(130460, 'zhTW', '', '今天的比賽主題是…艾澤拉斯的英雄！', 25549),
(130459, 'zhTW', '', '今天的比賽主題是…原始風格！', 25549),
(130458, 'zhTW', '', '今天的比賽主題是…陣營之光！', 25549),
(130457, 'zhTW', '', '今天的比賽主題是…黑暗又致命！', 25549),
(130456, 'zhTW', '', '今天的比賽主題是…寒冰烈火！', 25549),
(130455, 'zhTW', '', '今天的比賽主題是…視覺大衝突！', 25549),
(130454, 'zhTW', '', '今天的比賽主題是…活潑性感風！', 25549),
(130453, 'zhTW', '', '今天的比賽主題是…戰地英姿！', 25549),
(130452, 'zhTW', '', '今天的比賽主題是…冬季穿搭！', 25549),
(130450, 'zhTW', '好！你不可以忘記喔！', '', 25549),
(130449, 'zhTW', '弟弟別擔心，如果我們打贏了，等你再長大一點，我就告訴你父親教我的用刀技巧。好不好？', '', 25549),
(130448, 'zhTW', '可是，為什麼麥卡就可以去！', '', 25549),
(130447, 'zhTW', '', '歐洛二世，待在那裡！要是你出了什麼事，你父親會傷心死的。', 25549),
(130446, 'zhTW', '別這樣，讓我一起作戰！', '', 25549),
(130445, 'zhTW', '如果我死了，誰來照顧我的家人？', '如果我死了，誰來照顧我的家人？', 25549),
(130444, 'zhTW', '我不能死…拜託誰來幫幫我…', '我不能死…拜託誰來幫幫我…', 25549),
(130443, 'zhTW', '拜託…停止這場夢魘！', '拜託…停止這場夢魘！', 25549),
(130442, 'zhTW', '這是哪裡？我想不起來這是哪裡…', '這是哪裡？我想不起來這是哪裡…', 25549),
(130441, 'zhTW', '我不想死…', '我不想死…', 25549),
(130440, 'zhTW', '我怎麼了？我的身體在哪裡？', '我怎麼了？我的身體在哪裡？', 25549),
(130439, 'zhTW', '', '今天就到此為止。我們下次再會！', 25549),
(130438, 'zhTW', '', '其他人，繼續努力吧。下一個冠軍就是你。', 25549),
(130437, 'zhTW', '', '最後要宣布這場塑形大賽的冠軍。讓我們以最熱烈的掌聲歡迎$n！', 25549),
(130436, 'zhTW', '第二名的得主是…$n！你看起來真是美呆了！', '', 25549),
(130435, 'zhTW', '', '第三名的得主是…$n！恭喜你，$n！', 25549),
(130434, 'zhTW', '而右邊這位，是無與倫比的$n！', '', 25549),
(130433, 'zhTW', '感謝你的仁慈。我會永遠記得…', '感謝你的仁慈。我會永遠記得…', 25549),
(130432, 'zhTW', '能效忠暴風城…效忠國王是我的榮幸！', '能效忠暴風城…效忠國王是我的榮幸！', 25549),
(130431, 'zhTW', '', '左邊這位，是美到不行的$n！', 25549),
(130430, 'zhTW', '看到了…我看到聖光了…感謝你。', '看到了…我看到聖光了…感謝你。', 25549),
(130429, 'zhTW', '吾王，我很榮幸能為你效力…', '吾王，我很榮幸能為你效力…', 25549),
(130428, 'zhTW', '終於，這場夢魘結束了…', '終於，這場夢魘結束了…', 25549),
(130427, 'zhTW', '謝謝你。我不會忘記你的仁慈…', '謝謝你。我不會忘記你的仁慈…', 25549),
(130426, 'zhTW', '拜託…不要忘記我們。永遠記得我們做出的犧牲…', '拜託…不要忘記我們。永遠記得我們做出的犧牲…', 25549),
(130425, 'zhTW', '', '燃燒軍團正在逼近艾澤拉斯。我們每個人都要盡力而為！', 25549),
(130424, 'zhTW', '|TInterface\\Icons\\ABILITY_WARLOCK_INFERNO.BLP:20|t%s的|cFFFF0000|Hspell:238430|h[懼焰爆發]|h|r鎖定你了！', '|TInterface\\Icons\\ABILITY_WARLOCK_INFERNO:20|t%s的|cFFFF0000|Hspell:238430|h[懼焰爆發]|h|r鎖定你了！', 25549),
(130423, 'zhTW', '我準備好了！', '我準備好了！', 25549),
(130422, 'zhTW', '', '$ct，最近這一帶的怒魔鍊金師越來越大膽。他們前陣子偷走了我們一批藥劑。更糟的是他們還修改了配方，變成能對他們產生強化效果，用擴散水晶來噴灑！\n\n一定要阻止他們，但是沒有幫手就不好辦。還好美猴王願意出借他的跳躍法杖。用它來跳到他們上空，讓死亡對他們從天而降吧！\n\n你願意幫忙嗎？', 25549),
(130421, 'zhTW', '比賽會在兩分鐘後開始。祝各位帥哥美女好運！', '', 25549),
(130420, 'zhTW', '', '如果你想要整理髮型的話，我們還準備了美容椅。', 25549),
(130419, 'zhTW', '', '請利用接下來的一點時間好好打扮。', 25549),
(130418, 'zhTW', '喔，穿上好的短褲就是會有好心情。', '', 25549),
(130417, 'zhTW', '', '今天的比賽主題是…夏日風情！', 25549),
(130416, 'zhTW', '希望你們全都有備而來，今天這場比賽應該會相當激烈！', '', 25549),
(130415, 'zhTW', '', '高階審判官，快！敵人追上來了！', 25549),
(130414, 'zhTW', '', '歡迎光臨時尚大考驗：艾澤拉斯最頂尖的時尚總站！', 25549),
(130413, 'zhTW', '我們要一起打倒這個怪物。', '', 25549),
(130412, 'zhTW', '看啊，多麼輝煌美麗！這是一定會發生的事，逃避也沒有用。', '看啊，多麼輝煌美麗！這是一定會發生的事，逃避也沒有用。', 25549),
(130411, 'zhTW', '張開雙眼，$n！這裡只有謊言。天空才是真理所在！', '張開雙眼，$n！這裡只有謊言。天空才是真理所在！', 25549),
(130410, 'zhTW', '這地方只有空洞的承諾！財富救不了任何人！', '這地方只有空洞的承諾！財富救不了任何人！', 25549),
(130409, 'zhTW', '財產根本沒有意義！看看天空！末日來了！', '財產根本沒有意義！看看天空！末日來了！', 25549),
(130408, 'zhTW', '物質財產救不了你，$n！', '物質財產救不了你，$n！', 25549),
(130406, 'zhTW', '真理展現在我們眼前！', '真理展現在我們眼前！', 25549),
(130405, 'zhTW', '看看天空！偉大的命運在我們眼前展開！', '看看天空！偉大的命運在我們眼前展開！', 25549),
(130404, 'zhTW', '張開雙手，擁抱眼前的真理！', '張開雙手，擁抱眼前的真理！', 25549),
(130403, 'zhTW', '時候終於到了！最後的旅程展開了！', '時候終於到了！最後的旅程展開了！', 25549),
(130402, 'zhTW', '我一直都夢想著這一天的到來，但從來沒想過會這麼…美麗。', '我一直都夢想著這一天的到來，但從來沒想過會這麼…美麗。', 25549),
(130401, 'zhTW', '最近有沒有做出什麼有趣的不死生物啊？', '最近有沒有做出什麼有趣的不死生物啊？', 25549),
(130400, 'zhTW', '尋寶大師伊克斯睿吉對你做了個不雅的手勢。', '', 25549),
(130399, 'zhTW', '|TInterface\\ICONS\\INV_Artifact_PoweroftheDarkSide.blp:20|t墮落化身召喚出|cFFFF0404|Hspell:242017|h[黑風]|h|r!', '|TInterface\\ICONS\\INV_Artifact_PoweroftheDarkSide.blp:20|t墮落化身召喚出|cFFFF0404|Hspell:242017|h[黑風]|h|r!', 25549),
(130398, 'zhTW', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE:20|t%s開始施放|cFFFF0000|Hspell:240910|h[末日降臨]|h|r！', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE:20|t%s開始施放|cFFFF0000|Hspell:240910|h[末日降臨]|h|r！', 25549),
(130397, 'zhTW', '|TInterface\\Icons\\Ability_Socererking_arcanemines:20|t%s造出一個|cFFFF0000|Hspell:235059|h[破裂奇異點]|h|r！', '|TInterface\\Icons\\Ability_Socererking_arcanemines:20|t%s造出一個|cFFFF0000|Hspell:235059|h[破裂奇異點]|h|r！', 25549),
(130396, 'zhTW', '有沒有發現什麼稀有物品？', '有沒有發現什麼稀有物品？', 25549),
(130395, 'zhTW', '我什麼都不知道。', '我什麼都不知道。', 25549),
(130394, 'zhTW', '你的袋子裡有稀有的惡魔飾品嗎？', '你的袋子裡有稀有的惡魔飾品嗎？', 25549),
(130393, 'zhTW', '朋友，進入聖光吧。該是你好好休息的時候了。', '朋友，進入聖光吧。該是你好好休息的時候了。', 25549),
(130392, 'zhTW', '不，我不能死！我還有家人…不能就這樣留下他們！沒有我，他們該怎麼活下去？', '不，我不能死！我還有家人…不能就這樣留下他們！沒有我，他們該怎麼活下去？', 25549),
(130391, 'zhTW', '這是哪裡？我原本在破碎海岸上作戰…你聽得到我說話嗎？天啊…我…死了嗎？', '這是哪裡？我原本在破碎海岸上作戰…你聽得到我說話嗎？天啊…我…死了嗎？', 25549),
(130390, 'zhTW', '我…我找不到身體。我原本困在靈魂引擎裡面，現在…到哪裡去了？我發生了什麼事？！', '我…我找不到身體。我原本困在靈魂引擎裡面，現在…到哪裡去了？我發生了什麼事？！', 25549),
(130380, 'zhTW', '啊！箱子裡面有什麼？！到底有什麼？！', '', 25549),
(130379, 'zhTW', '哈哈！你太遲了，凡人！', '', 25549),
(130378, 'zhTW', '又是你？你休想拿走我的寶物！', '', 25549),
(130377, 'zhTW', '太遲了！好東西已經被我拿走了！', '', 25549),
(130376, 'zhTW', '破碎海岸。', '破碎海岸。', 25549),
(130375, 'zhTW', '%s不斷地痛苦掙扎。', '%s不斷地痛苦掙扎。', 25549),
(130374, 'zhTW', '%s痛苦地翻來覆去。', '%s痛苦地翻來覆去。', 25549),
(130373, 'zhTW', 'Pheta vi hylas (聖光會照看我們)。', '', 25549),
(130371, 'zhTW', 'Krona ki cristorr (燃燒軍團必敗)！', '', 25549),
(130370, 'zhTW', '我們的意志…不會動搖。', '', 25549),
(130369, 'zhTW', '痛苦…只是暫時的。', '', 25549),
(130368, 'zhTW', '你…別想…打敗我們…', '', 25549),
(130367, 'zhTW', '破碎海岸竟然如此殘破荒涼。我現在終於明白，親眼看見這一幕有多麼重要。', '', 25549),
(130362, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t墮落化身開始施放|cFFFF0404|Hspell:234418|h[毀滅之雨]|h|r！', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t墮落化身開始施放|cFFFF0404|Hspell:234418|h[毀滅之雨]|h|r！', 25549),
(130360, 'zhTW', '燃燒軍團的刺客死了。你暫時安全了。', '燃燒軍團的刺客死了。你暫時安全了。', 25549),
(130359, 'zhTW', '', '原諒我，費倫。有時間的話我會跟你解釋。', 25549),
(130358, 'zhTW', '艾蘭里亞？', '', 25549),
(130357, 'zhTW', '', '你在這裡不安全，快，我們快走。', 25549),
(130356, 'zhTW', '', '預言者！', 25549),
(130355, 'zhTW', '|TInterface\\Icons\\spell_hunter_lonewolf:20|t%s開始發出|cFFFF0404|Hspell:241772|h[詭異嚎叫]|h|r！', '', 25549),
(130354, 'zhTW', '|TInterface\\Icons\\SPELL_WARLOCK_SOULBURN:20|t%s準備對你施放|cFFFF0000|Hspell:236011|h[折磨號哭]|h|r！', '', 25549),
(130351, 'zhTW', '好呀，請給我破碎群島探路者，第一部和第二部成就，以及職業坐騎最後的任務！', '好呀，請給我破碎群島探路者，第一部和第二部成就，以及職業坐騎最後的任務！', 25549),
(130350, 'zhTW', '嗨！對，就是你，可以幫我們測試破碎群島的飛行功能嗎？\n\n我可以幫你開啟職業坐騎任務，你說呢！\n\n怎麼樣，要不要幫忙呀？', '', 25549),
(130349, 'zhTW', '我愛死這個冷凍背包了！哈哈！', '', 25549),
(130348, 'zhTW', '巨魔冰棒！哈！', '', 25549),
(130347, 'zhTW', '哈哈！結冰的笨巨魔。', '', 25549),
(130346, 'zhTW', '你確定這是你要製作的嗎？這個護甲師的表揚令只能讓你打造一件傳說級物品。', '你確定這是你要製作的嗎？這個護甲師的表揚令只能讓你打造一件傳說級物品。', 25549),
(130345, 'zhTW', '我想製作鎧甲腰帶。\n|TINTERFACE\\ICONS\\INV_Plate_DraenorCrafted_D_01Buckle.blp:32|t\n|Hitem:146667:0:0:0:0:0:0:0:110:0|h[瑞蘇的不敗勇氣]|h', '我想製作鎧甲腰帶。\n|TINTERFACE\\ICONS\\INV_Plate_DraenorCrafted_D_01Buckle.blp:32|t\n|Hitem:146667:0:0:0:0:0:0:0:110:0|h[瑞蘇的不敗勇氣]|h', 25549),
(130344, 'zhTW', '我想製作鎖鍊手套。\n|TINTERFACE\\ICONS\\INV_GAUNTLETS_PLATE_RAIDPALADIN_I_01.BLP:32|t\n|Hitem:146668:0:0:0:0:0:0:0:110:0|h[戒守之棲]|h', '我想製作鎖鍊手套。\n|TINTERFACE\\ICONS\\INV_GAUNTLETS_PLATE_RAIDPALADIN_I_01.BLP:32|t\n|Hitem:146668:0:0:0:0:0:0:0:110:0|h[戒守之棲]|h', 25549),
(130343, 'zhTW', '我想製作皮靴。\n|TINTERFACE\\ICONS\\INV_Leather_RaidDemonHunterMythic_Q_02Boots.blp:32|t\n|Hitem:146669:0:0:0:0:0:0:0:110:0|h[哨兵的永恆庇護]|h', '我想製作皮靴。\n|TINTERFACE\\ICONS\\INV_Leather_RaidDemonHunterMythic_Q_02Boots.blp:32|t\n|Hitem:146669:0:0:0:0:0:0:0:110:0|h[哨兵的永恆庇護]|h', 25549),
(130342, 'zhTW', '我想製作訂製護肩。\n|TINTERFACE\\ICONS\\INV_SHOULDER_CLOTH_RAIDWARLOCK_L_01.BLP:32|t\n|Hitem:146666:0:0:0:0:0:0:0:110:0|h[瑟蘭博拉，暗夜歧路]|h', '我想製作訂製護肩。\n|TINTERFACE\\ICONS\\INV_SHOULDER_CLOTH_RAIDWARLOCK_L_01.BLP:32|t\n|Hitem:146666:0:0:0:0:0:0:0:110:0|h[瑟蘭博拉，暗夜歧路]|h', 25549),
(130341, 'zhTW', '聽好，最重要的一點，我們得決定你要打造的是哪種護甲。謹慎選擇，你的表揚令只能換得一個課程。', '', 25549),
(130338, 'zhTW', '其他人通通回教室去吧。你們顯然還需要好幾百年的高等教育。', '', 25549),
(130337, 'zhTW', '', '呵…我一直都很欣賞雕銘師。別忘了…保持聯絡。', 25549),
(130336, 'zhTW', '應該給你點什麼！來，這個給你，希望對你有幫助。', '', 25549),
(130335, 'zhTW', '感謝伊露恩！英雄，謝謝你！', '', 25549),
(130334, 'zhTW', '漂亮的小鳥，想要閃亮的金幣嗎？', '漂亮的小鳥，想要閃亮的金幣嗎？', 25549),
(130333, 'zhTW', '有什麼東西可以賣給我嗎？', '有什麼東西可以賣給我嗎？', 25549),
(130332, 'zhTW', '', '喔，你是雕銘師？要是有人能幫我寫下我的…調教紀錄，那就太棒了。我或許知道一個秘密。一個壞壞的秘密。', 25549),
(130331, 'zhTW', '我一定會重獲自由！精靈，你敢羞辱我，我會讓你付出代價！', '', 25549),
(130319, 'zhTW', '', '<擠眉弄眼。>', 25549),
(130316, 'zhTW', '', '嗚…我好冷喔。幫我個忙，點燃你自己好嗎？', 25549),
(130314, 'zhTW', '', '喔，你的道德感迷死我了。', 25549),
(130312, 'zhTW', '', '喔，你真可愛，可是我已經跟別人綁定契約了。', 25549),
(130311, 'zhTW', '', '嗯…？嗯…', 25549),
(130292, 'zhTW', '嗯，我應該知道在哪。卡拉贊失守以前，我和卡德加在我的書房研究火焰稜碟，現在應該還放在那裡。可惜當時時間有限，研究沒什麼進展。$b$b如果是以前，要去書房很容易，但現在這裡已經被惡魔侵占了。$b$b只能一路打過去了，前往書房的傳送門在地窖另一端。火焰稜碟應該就在書房裡。', '', 25549),
(130281, 'zhTW', '請問你知道火焰稜碟現在在哪裡嗎？', '請問你知道火焰稜碟現在在哪裡嗎？', 25549),
(130257, 'zhTW', '這是一點心意，請收下吧。', '這是一點心意，請收下吧。', 25549),
(130256, 'zhTW', '謝…謝謝你…我…我沒事了，謝謝！', '謝…謝謝你…我…我沒事了，謝謝！', 25549),
(130255, 'zhTW', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s開始施放|cFFFF0000|Hspell:233983|h[迴盪苦痛]|h|r！', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s開始施放|cFFFF0000|Hspell:233983|h[迴盪苦痛]|h|r！', 25549),
(130254, 'zhTW', '先等等，$n。我們先把還在製作的東西完成。', '', 25549),
(130253, 'zhTW', '太好了！那我們就開始吧。我會把你夢寐以求的傳說護具製作方法全部都教給你！', '', 25549),
(130252, 'zhTW', '我帶了護甲師的表揚令給你。', '我帶了護甲師的表揚令給你。', 25549),
(130250, 'zhTW', '測試', '', 25549),
(130249, 'zhTW', '時間到了。出發前往阿古斯。', '', 25549),
(130248, 'zhTW', '歡迎登上艾克索達。', '', 25549),
(130247, 'zhTW', '走吧。', '', 25549),
(130244, 'zhTW', '敵人發現你了，而且還派出了殺手。', '敵人發現你了，而且還派出了殺手。', 25549),
(130243, 'zhTW', '', '謝謝你！這個寶箱就送你吧，這是你應得的！', 25549),
(130242, 'zhTW', '', '救命！它們在搶我的補給品！', 25549),
(130241, 'zhTW', '克索諾斯…永遠不敗…', '', 25549),
(130240, 'zhTW', '恐懼戰馬是我的…是我的！', '', 25549),
(130239, 'zhTW', '我會把你像蟲子一樣踩扁！', '', 25549),
(130238, 'zhTW', '術士，敢來這裡就得付出代價！', '', 25549),
(130237, 'zhTW', '', '毫無疑問，你擊退了侵襲這座樹林的怪物。但要是我們能直接從水裡取出更加…黏稠的…腐化物質，那也會是一場大勝利！建議你用釣竿試試。', 25549),
(130236, 'zhTW', '', '<她噁心地偏過頭，然後伸出手取走水珠。>\n\n謝謝你。終於能摧毀這個東西了。', 25549),
(130235, 'zhTW', '', '腐化汙染了水域並且殺死了棲息在裡面的自然生物。我們一定要反擊！', 25549),
(130234, 'zhTW', '', '首先，這裡的鯉魚太多了。如果你能幫我把小鯉釣起來，我就可以帶到河裡放生。\n\n但要小心麥基克斯，海生館的守護者。', 25549),
(130233, 'zhTW', '', '太好了！快，放進魔法水球，接下來就交給我吧。\n\n<夏蕾斯渾然忘我看著小魚。>', 25549),
(130232, 'zhTW', '', '我被放逐以前是海生館管理員。我對那裡的水中生物有責任，不能拋棄牠們！', 25549),
(130231, 'zhTW', '烏鴉看著腳邊發亮的小石頭，然後看向水。你明確感覺到有釣竿就能找到它們。', '', 25549),
(130230, 'zhTW', '柯爾賓開心地嘎嘎叫。', '', 25549),
(130229, 'zhTW', '烏鴉歪著頭看著你。', '', 25549),
(130228, 'zhTW', '我打算收集那個當初可能已被打成幾千片的圖騰碎片。用釣竿可能有機會找到一些。', '', 25549),
(130227, 'zhTW', '<阿庫爾仔細檢視這塊碎片。>\n\n沒錯，這的確是那個圖騰的一部分。非常感謝你，$c。', '', 25549),
(130226, 'zhTW', '好幾年前有個儀式圖騰在這片水域中被閃電擊毀了。我想重建一番，榮耀我的祖先。', '', 25549),
(130225, 'zhTW', '用釣竿釣海草！海草給英普斯！沒有利潤！', '', 25549),
(130224, 'zhTW', '英普斯覺得手下做得很好。', '', 25549),
(130223, 'zhTW', '再會。', '', 25549),
(130221, 'zhTW', '英普斯要造船。你幫忙！', '', 25549),
(130220, 'zhTW', '朋友，謝謝你！拿走我的一點力量做為獎賞。希望這能幫你擊敗敵人。', '', 25549),
(130219, 'zhTW', '', '我百發百中！', 25549),
(130218, 'zhTW', '', '你躲不過我的箭雨！', 25549),
(130217, 'zhTW', '集中火力攻擊。我來引開它的注意。', '', 25549),
(130216, 'zhTW', '為了納薩拉斯！', '為了納薩拉斯！', 25549),
(130215, 'zhTW', '守夜者，站穩腳跟！敵人要來了！', '守夜者，站穩腳跟！敵人要來了！', 25549),
(130214, 'zhTW', 'Bandu Thoribas! (準備受死！)', 'Bandu Thoribas! (準備受死！)', 25549),
(130213, 'zhTW', '守夜者絕對不會放棄崗位！', '守夜者絕對不會放棄崗位！', 25549),
(130212, 'zhTW', '守夜者，準備戰鬥！燃燒軍團來了！', '守夜者，準備戰鬥！燃燒軍團來了！', 25549),
(130211, 'zhTW', '殲滅！', '', 25549),
(130210, 'zhTW', '天哪！課程大綱沒寫到會出現這種狀況！', '', 25549),
(130209, 'zhTW', '你願意跟我一起冒險…永遠永遠在一起嗎？', '', 25549),
(130208, 'zhTW', '別拖拖拉拉的，你打算讓我們等一輩子嗎？', '', 25549),
(130207, 'zhTW', '嘿，那位同學，過來幫大家示範一下。', '', 25549),
(130206, 'zhTW', '如果大家有乖乖抄筆記，就應該知道該用什麼咒語，才能讓這傢伙燒成大火球。', '', 25549),
(130205, 'zhTW', '各位同學別擔心，這個惡魔關在秘法矩陣裡，相當安全。', '', 25549),
(130204, 'zhTW', '呃…那個咒語是什麼？奴…夏羅拉…呃，然後好像是…阿布拉喀達布拉！', '呃…那個咒語是什麼？奴…夏羅拉…呃，然後好像是…阿布拉喀達布拉！', 25549),
(130203, 'zhTW', '老師，可是…', '老師，可是…', 25549),
(130201, 'zhTW', '<傳送門的能量嗡嗡作響，從另一端傳來尖叫和各種可怕的聲響。>\n\n等你找到更多虛空裂片再回來這裡找我。', '', 25549),
(130200, 'zhTW', '', '$n，謝謝你！這正是我需要的。', 25549),
(130199, 'zhTW', '帶我去參加時尚大考驗！', '帶我去參加時尚大考驗！', 25549),
(130198, 'zhTW', '', '很美，對吧？你能感覺到它的力量在你的身體裡面流動，並且散發出足以干擾周遭世界的波動嗎？只要你願意，我能操控這股力量…', 25549),
(130197, 'zhTW', '', '保護法術已經開始崩解、失效。雖然聽起來很怪，但或許你能用魚竿幫我把這些法術碎片釣起來，收集回來。', 25549),
(130196, 'zhTW', '你想做什麼？', '', 25549),
(130195, 'zhTW', '需要我幫忙嗎？', '需要我幫忙嗎？', 25549),
(130194, 'zhTW', '勇士，我帶來法隆迪斯親王的禮物。這個法術會讓你在時效內變得堅強、敏銳、強大。過來收禮物吧。', '勇士，我帶來法隆迪斯親王的禮物。這個法術會讓你在時效內變得堅強、敏銳、強大。過來收禮物吧。', 25549),
(130193, 'zhTW', '勇士，我帶來埃伊爾的恩典！過來接受埃伊爾的祝福吧。', '勇士，我帶來埃伊爾的恩典！過來接受埃伊爾的祝福吧。', 25549),
(130192, 'zhTW', '對不起，我沒辦法…', '對不起，我沒辦法…', 25549),
(130191, 'zhTW', '當然好呀！', '當然好呀！', 25549),
(130190, 'zhTW', '我也做了跟你一模一樣的夢！', '我也做了跟你一模一樣的夢！', 25549),
(130189, 'zhTW', '希望你能找到那個人。', '希望你能找到那個人。', 25549),
(130188, 'zhTW', '…', '…', 25549),
(130187, 'zhTW', '$n在烏瑞恩之殞啟動了不穩定的虛空傳送門！', '$n在烏瑞恩之殞啟動了不穩定的虛空傳送門！', 25549),
(130186, 'zhTW', '$n在暗影裂谷啟動了不穩定的虛空傳送門！', '$n在暗影裂谷啟動了不穩定的虛空傳送門！', 25549),
(130185, 'zhTW', '$n在悲泣露臺啟動了不穩定的虛空傳送門！', '$n在悲泣露臺啟動了不穩定的虛空傳送門！', 25549),
(130184, 'zhTW', '$n在扭曲之地啟動了不穩定的虛空傳送門！', '$n在扭曲之地啟動了不穩定的虛空傳送門！', 25549),
(130183, 'zhTW', '$n在蜘蛛岩洞啟動了不穩定的虛空傳送門！', '$n在蜘蛛岩洞啟動了不穩定的虛空傳送門！', 25549),
(130182, 'zhTW', '$n在濱岸絕地啟動了不穩定的虛空傳送門！', '$n在濱岸絕地啟動了不穩定的虛空傳送門！', 25549),
(130181, 'zhTW', '$n在靈魂遺跡啟動了不穩定的虛空傳送門！', '$n在靈魂遺跡啟動了不穩定的虛空傳送門！', 25549),
(130180, 'zhTW', '$n在士兵蒙難處啟動了不穩定的虛空傳送門！', '$n在士兵蒙難處啟動了不穩定的虛空傳送門！', 25549),
(130179, 'zhTW', '$n在尖嘯山崖啟動了不穩定的虛空傳送門！', '$n在尖嘯山崖啟動了不穩定的虛空傳送門！', 25549),
(130178, 'zhTW', '$n在苦難之路啟動了不穩定的虛空傳送門！', '$n在苦難之路啟動了不穩定的虛空傳送門！', 25549),
(130177, 'zhTW', '$n在月光高地啟動了不穩定的虛空傳送門！', '$n在月光高地啟動了不穩定的虛空傳送門！', 25549),
(130176, 'zhTW', '$n在鋸齒海灣啟動了不穩定的虛空傳送門！', '$n在鋸齒海灣啟動了不穩定的虛空傳送門！', 25549),
(130175, 'zhTW', '$n在鬼愁之地啟動了不穩定的虛空傳送門！', '$n在鬼愁之地啟動了不穩定的虛空傳送門！', 25549),
(130174, 'zhTW', '$n在惡魔要塞啟動了不穩定的虛空傳送門！', '$n在惡魔要塞啟動了不穩定的虛空傳送門！', 25549),
(130173, 'zhTW', '$n在腐惡海岸啟動了不穩定的虛空傳送門！', '$n在腐惡海岸啟動了不穩定的虛空傳送門！', 25549),
(130172, 'zhTW', '$n在魔誓洞窟啟動了不穩定的虛空傳送門！', '$n在魔誓洞窟啟動了不穩定的虛空傳送門！', 25549),
(130171, 'zhTW', '$n在魔怒海岸啟動了不穩定的虛空傳送門！', '$n在魔怒海岸啟動了不穩定的虛空傳送門！', 25549),
(130170, 'zhTW', '$n在魔火隘口啟動了不穩定的虛空傳送門！', '$n在魔火隘口啟動了不穩定的虛空傳送門！', 25549),
(130169, 'zhTW', '$n在魔塵洞穴啟動了不穩定的虛空傳送門！', '$n在魔塵洞穴啟動了不穩定的虛空傳送門！', 25549),
(130168, 'zhTW', '$n在魔裂谷地啟動了不穩定的虛空傳送門！', '$n在魔裂谷地啟動了不穩定的虛空傳送門！', 25549),
(130167, 'zhTW', '$n在死木灘啟動了不穩定的虛空傳送門！', '$n在死木灘啟動了不穩定的虛空傳送門！', 25549),
(130166, 'zhTW', '$n在黑暗監獄啟動了不穩定的虛空傳送門！', '$n在黑暗監獄啟動了不穩定的虛空傳送門！', 25549),
(130165, 'zhTW', '$n在弦月遺跡啟動了不穩定的虛空傳送門！', '$n在弦月遺跡啟動了不穩定的虛空傳送門！', 25549),
(130164, 'zhTW', '$n在苦痛海灣啟動了不穩定的虛空傳送門！', '$n在苦痛海灣啟動了不穩定的虛空傳送門！', 25549),
(130163, 'zhTW', '$n在灰燼徑道啟動了不穩定的虛空傳送門！', '$n在灰燼徑道啟動了不穩定的虛空傳送門！', 25549),
(130162, 'zhTW', '我不知道該說什麼…我太高興了！我們一起去冒險吧！', '', 25549),
(130161, 'zhTW', '我…我大概可以理解。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(130160, 'zhTW', '所以你…就是你吧！我有好多好多事情想跟你分享！該從何說起呢？\n\n第一次冒險結束後，我做什麼事情都心不在焉，一直在想不知道什麼時候可以再去冒險。我的朋友都說你不是真的，都說我快瘋了，你只是夢裡的人。但他們都錯了！這些感覺太真實，不只是夢！\n\n我們經歷過這麼多冒險，殺了這麼多敵人，說了這麼多話…現在只有一個問題想問你…', '', 25549),
(130159, 'zhTW', '我一直在等，我相信那個人一定會來的！', '', 25549),
(130158, 'zhTW', '其實我根本不知道這個人長什麼樣子，第一次夢見時長得像夜精靈，第二次卻長得像牛頭人，第三次又變回夜精靈。我們在夢裡到處冒險，去了艾澤拉斯、德拉諾好多地方，我們一起對抗惡魔、龍、古神，還有魚人！\n\n我從來沒做過這種夢。太真實了。所以我最後一次做夢請對方到這裡碰面。', '', 25549),
(130157, 'zhTW', '是你嗎？！那個我夢見的人？！', '', 25549),
(130156, 'zhTW', '<肖恩神情複雜看著你>', '', 25549),
(130155, 'zhTW', '這裡的情況很不對勁，光憑我的力量恐怕無法應對。', '', 25549),
(130154, 'zhTW', '是的，預言者。', '是的，預言者。', 25549),
(130153, 'zhTW', '朋友，你準備好要繼續了嗎？', '', 25549),
(130152, 'zhTW', '我…我看不見…', '', 25549),
(130151, 'zhTW', '<費倫急促地呼吸。>', '', 25549),
(130150, 'zhTW', '如此可怕的黑暗！', '', 25549),
(130149, 'zhTW', '<費倫大喊出聲。>', '', 25549),
(130148, 'zhTW', '太…太黑暗了！', '', 25549),
(130147, 'zhTW', '<痛苦的呻吟。>', '', 25549),
(130146, 'zhTW', 'Acheon phetar，請賜我清明的雙眼。讓我看見它們在哪！', '', 25549),
(130145, 'zhTW', '<吃力的呼吸聲。>', '', 25549),
(130144, 'zhTW', '我不明白，為什麼我感覺不到？', '', 25549),
(130143, 'zhTW', '<聽不清楚的祈禱聲。>', '', 25549),
(130142, 'zhTW', '願聖光指引我的雙眼。Pheta vi acahachi! (聖光賜我力量！)', '', 25549),
(130141, 'zhTW', '接下來就沒有屏障保護了。朋友，小心謹慎。', '', 25549),
(130139, 'zhTW', '很久以前，我就是站在這個位置號召我的德萊尼同胞。我要在這裡找到其他的聖物。', '', 25549),
(130138, 'zhTW', '只要我們重新得到三傑聖物，就能避免面臨和瑟納達爾相同的命運。', '', 25549),
(130137, 'zhTW', '我的兄弟們在薩格拉斯降臨的時候捨棄了他們的聖物。聖物還在這裡，在麥克艾瑞。', '', 25549),
(130136, 'zhTW', '三傑聖物是個媒介，它是一股合而為一的力量，我們三個人各持有一個聖物。', '', 25549),
(130135, 'zhTW', '費了好一番功夫，我們總算幫你的勇士取得一件最高品質的裝備。\n\n但是很遺憾，我們的物資非常有限，所以必須嚴格控管發送的數量。', '', 25549),
(130134, 'zhTW', '英雄，大地之母與你同在！站到這些圖騰中間吧，接受大地之母的祝福。', '英雄，大地之母與你同在！站到這些圖騰中間吧，接受大地之母的祝福。', 25549),
(130133, 'zhTW', '戰鬥領主，等你準備好要離開，可以用這個傳送門回擎天堡。', '', 25549),
(130129, 'zhTW', '劫奪者抵達了！', '劫奪者抵達了！', 25549),
(130128, 'zhTW', '我踢！我打！我燒！', '', 25549),
(130127, 'zhTW', '那個，其實我真的很期待你的表演。', '那個，其實我真的很期待你的表演。', 25549),
(130126, 'zhTW', '可以請你安靜一點嗎？', '可以請你安靜一點嗎？', 25549),
(130125, 'zhTW', '警告：發現敵人', '警告：發現敵人', 25549),
(130124, 'zhTW', '怎麼又是你？\n\n你覺得我會跑去你家，教你怎麼當個好$c嗎？不會嘛！那你怎麼不快滾？', '', 25549),
(130123, 'zhTW', '讓我看看你賣什麼。', '讓我看看你賣什麼。', 25549),
(130122, 'zhTW', '我只跟最傑出的精英鬥士交易。', '我只跟最傑出的精英鬥士交易。', 25549),
(130118, 'zhTW', '絕對…不要…放棄！', '', 25549),
(130117, 'zhTW', '我沒事，多虧了我們這位朋友。艾蘭里亞…有件事你得聽我說。', '', 25549),
(130116, 'zhTW', '烈焰僕從！吞噬他們的血肉！', '', 25549),
(130115, 'zhTW', '喂，這位朋友，你這樣打斷表演對嗎？', '', 25549),
(130114, 'zhTW', '只有消滅這些害蟲，這片海岸才有機會重獲新生。英雄，謝謝你。', '', 25549),
(130113, 'zhTW', '<狗的毛皮光亮，看起來很健康。布芮妮費了不少心思照顧。>\n\n<但狗到底怎麼跑來的？>', '', 25549),
(130112, 'zhTW', '<把來自達拉然街道的石頭拿給狗看。>', '<把來自達拉然街道的石頭拿給狗看。>', 25549),
(130111, 'zhTW', '<狗嗅完石頭後，放心地舔舔你的手。>', '', 25549),
(130110, 'zhTW', '<狗坐在地上搖尾巴，顯然在努力克制跳到你身上的衝動。牠太久沒看到你了，見到你非常開心。>', '', 25549),
(130109, 'zhTW', '看看德萊尼的驕傲，艾克索達！', '', 25549),
(130108, 'zhTW', '我的大工藝師早就已經有所準備。', '', 25549),
(130107, 'zhTW', '燃燒軍團的攻擊這麼猛烈，我們要怎麼安全抵達阿古斯？', '', 25549),
(130106, 'zhTW', '路拉…', '', 25549),
(130105, 'zhTW', '我準備好了。', '我準備好了。', 25549),
(130104, 'zhTW', '我的族人一直在等待這一天。', '', 25549),
(130103, 'zhTW', '我的族人一直在等待這一天。', '', 25549),
(130102, 'zhTW', '', '但是請小心，$n。要是從魔巡號來太多援軍，你可能會應付不過來…', 25549),
(130101, 'zhTW', '', '不過，如果你想找人打架，或是需要更多的虛空裂片，那麼使用這些信標或許不是什麼壞主意。', 25549),
(130100, 'zhTW', '', '信標會把需要援軍的要求直接發送到魔巡號。這樣做可能會很危險。', 25549),
(130098, 'zhTW', '哈！搞定了！這樣做會不會太過火？人總是要想辦法保持樂觀。做得好，英雄，你一向靠得住。', '', 25549),
(130097, 'zhTW', '燃燒軍團想盡辦法要讓戰火蔓延。我們會很感謝你伸出援手撲滅這股威脅的，指揮官。', '', 25549),
(130095, 'zhTW', '使用|TInterface\\Icons\\SPELL_SHADOW_ENSLAVEDEMON.BLP:20|t|cFFFF0000|Hspell:111771|h[奴役惡魔]|h|r讓憤怒戰馬屈服！', '用|TInterface\\Icons\\spell_warlock_demonicportal_green.blp:20|t|cFFFF0000|Hspell:111771|h[惡魔之門]|h|r來穿越埃瑞丁的屏障！', 25549),
(130094, 'zhTW', '我們派了米奈娃先去偵察。通過死亡之門，和她在城塞碰面吧。', '', 25549),
(130092, 'zhTW', '把自己奉獻給燃燒軍團。', '把自己奉獻給燃燒軍團。', 25549),
(130091, 'zhTW', '我願意為惡魔之力獻上靈魂！', '我願意為惡魔之力獻上靈魂！', 25549),
(130090, 'zhTW', '我樂意效忠燃燒軍團。', '我樂意效忠燃燒軍團。', 25549),
(130089, 'zhTW', '', '納迦必勝…', 25549),
(130088, 'zhTW', '', '燃燒軍團承諾給予我們力量！而且是遠強過艾薩拉女王的力量！', 25549),
(130087, 'zhTW', '讓他們身首異處！', '', 25549),
(130086, 'zhTW', '', '燃燒軍團別想擊敗我們！', 25549),
(130085, 'zhTW', '', '我們受到來自地面和空中的攻擊，注意上面！', 25549),
(130084, 'zhTW', '我想挑戰曦格琳。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰曦格琳。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130083, 'zhTW', '我想挑戰卡魯歐。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰卡魯歐。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130082, 'zhTW', '我想挑戰雷斯特。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰雷斯特。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130080, 'zhTW', '我想挑戰賽倫。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰賽倫。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130078, 'zhTW', '帶我去找亞加薩…|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '帶我去找亞加薩…|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130077, 'zhTW', '帶我去找亞加薩…(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '帶我去找亞加薩…(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130076, 'zhTW', '暗影會贏得勝利！', '', 25549),
(130074, 'zhTW', '放棄吧！屈服吧！', '', 25549),
(130073, 'zhTW', '陷入黑暗吧！', '', 25549),
(130072, 'zhTW', '把我傳送到影歌。|cFFFF0000(100個虛空裂片 |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '把我傳送到影歌。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130071, 'zhTW', '阿古斯！我心愛的家園…它們到底做了什麼？', '', 25549),
(130070, 'zhTW', '我想挑戰圖加‧血圖騰。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰圖加‧血圖騰。|cFFFF0000(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130069, 'zhTW', '挑戰『無悔者』加索。', '挑戰『無悔者』加索。', 25549),
(130068, 'zhTW', '今晚吃凡人的血肉！', '', 25549),
(130067, 'zhTW', '', '$c，你好。我得完成這個研究。\n\n你可以幫我嗎？', 25549),
(130066, 'zhTW', '納迦應該要知道不管跟燃燒軍團做什麼交易，都不會有好下場。', '', 25549),
(130065, 'zhTW', '這些納迦的領袖和燃燒軍團立下約定，用她子民的性命來交換力量。這些傻瓜自投羅網，不知道自己會有什麼下場。讓他們看看吧。', '', 25549),
(130064, 'zhTW', '你們的靈魂會煙消雲散！', '', 25549),
(130063, 'zhTW', '我手中有無限的毀滅力量！', '', 25549),
(130062, 'zhTW', '讓混沌吞噬你！', '', 25549),
(130061, 'zhTW', '把這些凡人殺光，我要看到支離破碎的屍體！', '', 25549),
(130060, 'zhTW', '英雄，我會送你們到船艦那邊！消滅船艦，別讓欺詐者的力量變強！', '', 25549),
(130059, 'zhTW', '放棄吧！現在還有機會加入我們，服侍主人！', '', 25549),
(130058, 'zhTW', '你們的下場會和其他世界一樣！', '', 25549),
(130057, 'zhTW', '燃燒軍團來收割靈魂了！', '', 25549),
(130056, 'zhTW', '每個抵抗我們的世界都淪陷了。', '', 25549),
(130055, 'zhTW', '費倫當年的反抗，種下了你們今天滅亡的種子。', '', 25549),
(130054, 'zhTW', '你們只是渺小又卑賤的廢物！我們永垂不朽！', '', 25549),
(130053, 'zhTW', '預言者，可以出發了。', '', 25549),
(130052, 'zhTW', '接受你的命運！', '', 25549),
(130051, 'zhTW', '向你的恐懼和欲望屈服吧！', '', 25549),
(130050, 'zhTW', '小心，$ct。惡魔在那裡到處橫行。', '小心，$ct。惡魔在那裡到處橫行。', 25549),
(130049, 'zhTW', '我要親手殺了你！', '', 25549),
(130048, 'zhTW', '誰會跟你一樣悲慘呢？', '', 25549),
(130047, 'zhTW', '吞噬他們！', '', 25549),
(130046, 'zhTW', '燒吧！受苦吧！', '', 25549),
(130045, 'zhTW', '死亡降臨！', '', 25549),
(130044, 'zhTW', '灰飛煙滅！', '', 25549),
(130043, 'zhTW', '跟我來，勇士，我會讓你們看得見！', '', 25549),
(130042, 'zhTW', '勇士們，小心！好好看著這未來的景象！', '', 25549),
(130041, 'zhTW', 'Tor ilisar''thera''nal! (威震敵軍！)', 'Tor ilisar''thera''nal! (威震敵軍！)', 25549),
(130040, 'zhTW', 'Bandu thoribas! (準備受死！)', 'Bandu thoribas! (準備受死！)', 25549),
(130039, 'zhTW', '我要用尖牙和利爪，阻止他們！', '我要用尖牙和利爪，阻止他們！', 25549),
(130038, 'zhTW', '惡魔絕對過不了我們這一關！為了大自然！', '惡魔絕對過不了我們這一關！為了大自然！', 25549),
(130037, 'zhTW', '燃燒軍團來了！我們一定要保護家園！', '燃燒軍團來了！我們一定要保護家園！', 25549),
(130036, 'zhTW', '標記一個敵人，我來解決他！', '', 25549),
(130035, 'zhTW', '你們的遠征到此為止！', '', 25549),
(130034, 'zhTW', '確認封鎖設施。開始處理威脅。', '', 25549),
(130033, 'zhTW', '這是你最後一次戰鬥！', '', 25549),
(130029, 'zhTW', '', '圖拉揚，你沒事吧？', 25549),
(130028, 'zhTW', '聖光之子，敬禮！', '', 25549),
(130027, 'zhTW', '', '我已經習慣把你從惡魔手裡救出來了。', 25549),
(130026, 'zhTW', '', '左邊！', 25549),
(130025, 'zhTW', '不使用', '', 25549),
(130024, 'zhTW', '等你準備好了，就去卡薩斯平臺和艾澤拉斯最強的勇士們集合。', '', 25549),
(130023, 'zhTW', '來吧。就算我們注定要死在扭曲虛空，也絕對要拉欺詐者來陪葬！', '', 25549),
(130022, 'zhTW', '我同意，這是唯一的辦法。去吧，勇士！去另一邊幫助費倫，然後在傳送門關閉前趕回來。', '', 25549),
(130021, 'zhTW', '親手掌握命運的時刻到了。我們要通過傳送門跟著欺詐者踏入深淵。這是唯一的辦法！', '', 25549),
(130020, 'zhTW', '關閉傳送門是沒有用的，大法師。管他是幾十年還是幾千年，燃燒軍團都會捲土重來。它們會一次又一次，戰到我們沒有能力抵抗為止。', '', 25549),
(130019, 'zhTW', '費倫！住手！', '', 25549),
(130018, 'zhTW', '不行！我們不再逃亡！不再躲藏！我要結束這一切！', '', 25549),
(130017, 'zhTW', '', '%s以迅雷不及掩耳的速度把箭搭上弓弦。', 25549),
(130016, 'zhTW', '|TINTERFACE\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t你受到|cFFFF0000|Hspell:235271|h[注入]|h|r！', '|TINTERFACE\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t戒守聖女開始施放|cFFFF0000|Hspell:235271|h[注入]|h|r！', 25549),
(130015, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t你受到|cFFFF0000|Hspell:240209|h[靈魂動盪]|h|r影響！', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t你受到|cFFFF0000|Hspell:235117|h[靈魂動盪]|h|r影響！', 25549),
(130014, 'zhTW', '惡魔，今天就是你的末日！', '', 25549),
(130013, 'zhTW', '聖光請賜我力量！', '', 25549),
(130012, 'zhTW', '我想傳送到基爾加丹。', '我想傳送到基爾加丹。', 25549),
(130011, 'zhTW', '我想傳送到墮落化身。', '我想傳送到墮落化身。', 25549),
(130010, 'zhTW', '我想傳送到戒守聖女。', '我想傳送到戒守聖女。', 25549),
(130009, 'zhTW', '我想傳送到惡魔審判官。', '我想傳送到惡魔審判官。', 25549),
(130008, 'zhTW', '我想傳送到荒寂聚合體。', '我想傳送到荒寂聚合體。', 25549),
(130007, 'zhTW', '我想傳送到月光議會。', '我想傳送到月光議會。', 25549),
(130006, 'zhTW', '我想傳送到薩絲茵女士。', '我想傳送到薩絲茵女士。', 25549),
(130005, 'zhTW', '我想傳送到哈亞潭。', '我想傳送到哈亞潭。', 25549),
(130004, 'zhTW', '喔，你好，我們還沒開始。\n\n如果你喜歡比牛頭大佬更死金一點的音樂，可以來聽聽。\n\n幫我們宣傳一下吧？我們的音樂很酷的！', '', 25549),
(130002, 'zhTW', '你的族人…你的家園…都會毀滅。', '', 25549),
(130001, 'zhTW', '艾蘭里亞！你來得正是時候。', '', 25549),
(130000, 'zhTW', '', '伊露恩會幫助那些願意抵抗燃燒軍團的人。到月光底下來吧，英雄，接受伊露恩的祝福。', 25549),
(129999, 'zhTW', '不使用', '', 25549),
(129997, 'zhTW', '你敵不過我們的力量！', '', 25549),
(129996, 'zhTW', '我想去薩格拉斯之墓(團隊)。', '我想去薩格拉斯之墓(團隊)。', 25549),
(129995, 'zhTW', '我想去永夜聖殿(地城)。', '我想去永夜聖殿(地城)。', 25549),
(129994, 'zhTW', '不留活口！立刻消滅這個怪物！', '', 25549),
(129992, 'zhTW', '惡魔，我跟你們打了一千年。就算你們誇口，最後還是會死！', '', 25549),
(129991, 'zhTW', '你們太脆弱了！一碰就碎！', '', 25549),
(129990, 'zhTW', '你們就這點戰力？真是少得可憐…', '', 25549),
(129989, 'zhTW', '你想知道打敗燃燒軍團的秘訣嗎？\n\n就是建築物。\n\n建築物！建築物！建築物！', '', 25549),
(129988, 'zhTW', '我準備好要跟你一起作戰了。', '我準備好要跟你一起作戰了。', 25549),
(129987, 'zhTW', '除非萬不得已，我們不該在此久留。', '', 25549),
(129985, 'zhTW', '舉起你的武器。', '', 25549),
(129984, 'zhTW', '你的靈魂會燃燒！', '', 25549),
(129982, 'zhTW', '勇士，阿古斯遠征隊需要你。我們要進攻燃燒軍團的世界。', '', 25549),
(129977, 'zhTW', '我上次在這裡時，滿腦子只想著怎麼逃走。塔爾加斯，我最信任的諫言者，竟然背叛了我。', '', 25549),
(129976, 'zhTW', '她沒跟上來。但我還是能感覺到她…歌聲變得痛苦而扭曲。', '', 25549),
(129975, 'zhTW', '我還記得那魯的戰爭之歌，當時有個那魯為我們維持通道。', '', 25549),
(129974, 'zhTW', '是那天犧牲者的…靈魂。', '', 25549),
(129973, 'zhTW', '等等…情況不對。', '', 25549),
(129972, 'zhTW', '這裡原本是進步的希望…卻引來宇宙間的邪惡勢力無情襲擊。', '', 25549),
(129971, 'zhTW', '麥克艾瑞曾經是埃雷達爾文明的首要之地。', '', 25549),
(129970, 'zhTW', '<費倫瞪視著前方，似乎沒有察覺到你來了。>', '', 25549),
(129936, 'zhTW', '|TINTERFACE\\ICONS\\ability_fixated_state_red.blp:20|t一名剃顎鬥士鎖定你了！', '', 25549),
(129935, 'zhTW', '薩絲茵女士召喚了暗鱗監工！', '', 25549),
(129934, 'zhTW', '你讓我們的部隊免於悲慘的命運。聖光感謝你，英雄。', '', 25549),
(129933, 'zhTW', '勇士，我們的部隊被燃燒軍團俘虜，甚至折磨至死。救救他們…聖光就快消失了！', '', 25549),
(129932, 'zhTW', '我想把黃金小鯉全部送給你。', '我想把黃金小鯉全部送給你。', 25549),
(129931, 'zhTW', '我們在阿古斯跟燃燒軍團進行最後一戰的時候，就知道生存機會渺茫。瑟納達爾被擊中的時候，我以為一切都完了。', '', 25549),
(129930, 'zhTW', '我們已經下定決心，這次絕對要消滅燃燒軍團…我們會奮戰到死。', '', 25549),
(129929, 'zhTW', '聖光軍團和燃燒軍團奮戰了千百年，經歷過無數的對戰、混戰和惡戰。', '', 25549),
(129928, 'zhTW', '嗨，可愛的小鳥，想要這些發亮的小東西嗎？', '嗨，可愛的小鳥，想要這些發亮的小東西嗎？', 25549),
(129927, 'zhTW', '我好像找到你說的那些黏答答的腐化物質了。', '我好像找到你說的那些黏答答的腐化物質了。', 25549),
(129926, 'zhTW', '做得好！消滅海怪以後，我們就可以專心對付燃燒軍團了。', '', 25549),
(129925, 'zhTW', '我找到很多塊圖騰碎片，應該是你的。拿去吧。', '我找到很多塊圖騰碎片，應該是你的。拿去吧。', 25549),
(129924, 'zhTW', '好吧。拿走我所有被褻瀆的海草吧。', '好吧。拿走我所有被褻瀆的海草吧。', 25549),
(129923, 'zhTW', '我會擊敗你的！', '我會擊敗你的！', 25549),
(129922, 'zhTW', '誰都阻止不了我們！', '誰都阻止不了我們！', 25549),
(129921, 'zhTW', '你會死在我的劍下！', '你會死在我的劍下！', 25549),
(129920, 'zhTW', '你的末日到了！', '你的末日到了！', 25549),
(129919, 'zhTW', '魔能會吞噬你！', '魔能會吞噬你！', 25549),
(129918, 'zhTW', '為了燃燒軍團！', '為了燃燒軍團！', 25549),
(129917, 'zhTW', '哈亞潭發出|cFFFF0404|Hspell:232192|h[號令咆哮]|h|r吸引附近的魚人！', '', 25549),
(129916, 'zhTW', '我承認自己還蠻喜歡魚人的。不過…魔化以後…就不太喜歡了。', '', 25549),
(129915, 'zhTW', '魔化…魚人？有什麼是燃燒軍團不想腐化的嗎？請你處理一下，好嗎？', '', 25549),
(129914, 'zhTW', '我一直不懂，為什麼有人會喜歡這種噁心的生物。我們趕快回去處理重要的事吧。', '', 25549),
(129913, 'zhTW', '燃燒軍團竟然連這些魚人也不放過。別讓它們繼續腐化魚人！', '', 25549),
(129912, 'zhTW', '你的亮晶晶東西，快給！', '', 25549),
(129911, 'zhTW', '我們的地盤，你滾！', '', 25549),
(129910, 'zhTW', '這是杜其亞的地盤！', '', 25549),
(129909, 'zhTW', '山頭是我的，你去死！', '', 25549),
(129908, 'zhTW', '沒用！真是浪費時間。有了薩格拉斯之墓的力量，我就能殺光你們！', '', 25549),
(129907, 'zhTW', '你跟這個世界的其他人一樣，都想對付我？那就來吧。', '', 25549),
(129906, 'zhTW', '%s啟動了古老的防護法術！', '%s啟動了古老的防護法術！', 25549),
(129905, 'zhTW', '', '蘇拉瑪爾的魚都是我的朋友。', 25549),
(129904, 'zhTW', '', '我想把這片水域清乾淨。', 25549),
(129903, 'zhTW', '烏鴉疑惑地看著你。', '', 25549),
(129902, 'zhTW', '河水在對我說話。', '', 25549),
(129901, 'zhTW', '英普斯不清楚他為什麼會出現在這裡。', '', 25549),
(129900, 'zhTW', '', '殺光他們！', 25549),
(129899, 'zhTW', '有意思。', '', 25549),
(129898, 'zhTW', '我跟這些水說一下…', '', 25549),
(129897, 'zhTW', '來吧，我們去岸邊走走。', '', 25549),
(129896, 'zhTW', '空無…', '', 25549),
(129895, 'zhTW', '勇士，我派了烏鴉協助你登上指揮艦。', '', 25549),
(129894, 'zhTW', '穿刺！', '', 25549),
(129893, 'zhTW', '$p宗師，謝謝你的幫忙，但很遺憾班盧已經離開這裡了。我上次看到他往北走，但走去哪裡就不知道了。', '', 25549),
(129892, 'zhTW', '就是你！', '', 25549),
(129891, 'zhTW', '標記！', '', 25549),
(129890, 'zhTW', '這些水晶塔一次能傳送的部隊不多，不過這樣應該暫時夠了。', '', 25549),
(129889, 'zhTW', '烈焰！', '', 25549),
(129888, 'zhTW', '我們得快點行動。燃燒軍團知道我們在這裡，很快他們就會全力攻打過來。', '', 25549),
(129887, 'zhTW', '我應該要警告你，有時候「打」蛋器不會使卵爆炸，反而會讓它孵化。要使用這麼方便的科技，這是可以承擔的風險，對吧？', '', 25549),
(129886, 'zhTW', '不過…我不會剝奪你死在這個古老聖殿的機會。就讓這個化身了結你的性命吧！', '', 25549),
(129885, 'zhTW', '你看到的這個軀殼原本蘊含薩格拉斯的力量，但我們要的是這整座聖殿！只要得到聖殿，就能把你們的世界燒成灰燼！', '', 25549),
(129884, 'zhTW', '你就是喜歡裝出道貌岸然的樣子吧，費倫？就算接下了預言者的重任，你卻根本看不見這個世界…或者所有世界無可避免的命運。', '', 25549),
(129875, 'zhTW', '|CFFF00000警告|R這樣做會召喚一名危險的敵人，需要好幾個英雄才能擊敗。摧毀這個傳送門會消耗100個虛空裂片。', '|CFFF00000警告|R這樣做會召喚一名危險的敵人，需要好幾個英雄才能擊敗。摧毀這個傳送門會消耗100個虛空裂片。', 25549),
(129874, 'zhTW', '我可以幫你清除煞。', '我可以幫你清除煞。', 25549),
(129873, 'zhTW', '', '我是恐怖圖騰部族的瑪加薩·恐怖圖騰，領導我這一族的長者。$b$b雖然貝恩把我從雷霆崖放逐，但我才是牛頭人需要的領袖。他們只會呆坐在帳篷裡等聯盟和燃燒軍團過來殺死他們。我跟我的族人拒絕這麼做。我們要奮力一搏。$b$b燃燒軍團已經展開攻擊。恐怖圖騰需要我。你要幫我，還是要妨礙我？', 25549),
(129872, 'zhTW', '清得差不多了。', '清得差不多了。', 25549),
(129871, 'zhTW', '用虛空裂片[100]超載', '用虛空裂片[100]超載', 25549),
(129870, 'zhTW', '<傳送門的能量嗡嗡作響，從另一端傳來尖叫和各種可怕的聲響。>', '', 25549),
(129869, 'zhTW', '剩下的煞清得怎麼樣了？', '', 25549),
(129868, 'zhTW', '宗師，你真的清掉好多煞，謝謝你幫忙。', '', 25549),
(129867, 'zhTW', '$n宗師，你能過來真好。我們最近想把這附近的煞清乾淨。$b$b如果你願意伸出援手，或許我們可以互相幫忙。你說呢？', '', 25549),
(129866, 'zhTW', '我是陶土議會的先知。你是誰？', '我是陶土議會的先知。你是誰？', 25549),
(129865, 'zhTW', '', '這裡由你指揮嗎？', 25549),
(129864, 'zhTW', '這是我幫你釣到的法術碎片，全部拿走吧。', '這是我幫你釣到的法術碎片，全部拿走吧。', 25549),
(129863, 'zhTW', '', '我是恐怖圖騰部族的瑪加薩，這裡由我做主！', 25549),
(129862, 'zhTW', '惡魔困不了我們太久的。', '惡魔困不了我們太久的。', 25549),
(129861, 'zhTW', '我必須到營地回報！', '我必須到營地回報！', 25549),
(129860, 'zhTW', '謝謝你救了我!', '謝謝你救了我!', 25549),
(129859, 'zhTW', '攀爬中', '攀爬中', 25549),
(129858, 'zhTW', '那我們就這麼辦，大主教。', '', 25549),
(129857, 'zhTW', '不過外頭有幾千個惡魔，我們要先削減它們的數量，才有辦法活著抵達瑟納達爾。', '', 25549),
(129856, 'zhTW', '老朋友，艾蘭里亞一定還在某個地方，也一定還有其他的生還者。', '', 25549),
(129855, 'zhTW', '我最後一次看到她，是在瑟納達爾上。有人在…看守她。', '', 25549),
(129854, 'zhTW', '艾蘭里亞呢？難道她…', '', 25549),
(129853, 'zhTW', '圖拉揚！很高興看到你沒有讓燃燒軍團得逞。', '', 25549),
(129852, 'zhTW', 'This is a test broadcast for gender token testing, $gbrother:sister;! (Do not translate)', '', 25549),
(129851, 'zhTW', '啟動中', '啟動中', 25549),
(129850, 'zhTW', '', '遵命，牧師。', 25549),
(129849, 'zhTW', '', '走吧！', 25549),
(129848, 'zhTW', '好啊，我願意試試看。應該不可能出差錯吧？', '好啊，我願意試試看。應該不可能出差錯吧？', 25549),
(129847, 'zhTW', '你好啊，$ct！\n\n你或許已經知道了，這裡不只是船艦墳場…還是個大型的海怪溫床！你看看這些卵！太驚奇了…或許也有一點危險。\n\n既然你是來摧毀這些卵的，或許會喜歡我最新、最酷、而且還算有點安全的新發明：\n\n它叫做…「打」蛋器！\n\n它大多數的時候用起來都沒問題！要不要試試看？', '', 25549),
(129846, 'zhTW', '', '謝謝你，我們不會忘記你的恩情！', 25549),
(129845, 'zhTW', '', '是你救了我和姊妹們的生命。我們有的東西不多，但你可以從補給品中任意挑選想要的拿走。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129844, 'zhTW', '', '勇士，願伊露恩祝福你。看來這片森林沒辦法繼續保護我們免於燃燒軍團的傷害了。', 25549),
(129843, 'zhTW', '燃燒軍團想藉由褻瀆聖殿來瓦解我們的意志。你的作為證明了我們的意志不會被擊潰！', '', 25549),
(129842, 'zhTW', '基爾加丹喜歡派手下來褻瀆聖殿。讓這個噁心的傢伙從世界上消失吧。', '', 25549),
(129841, 'zhTW', '那個審判官喜歡把目標折磨到死。殺了這個傢伙，給他一點報應吧。', '', 25549),
(129840, 'zhTW', '有個審判官潛伏在聖殿裡，利用陣亡的盟友來對付我們。讓這個傢伙滾回扭曲虛空吧。', '', 25549),
(129839, 'zhTW', '殺得好。那個臃腫的傢伙再也無法召喚其他惡魔了。', '', 25549),
(129838, 'zhTW', '我感覺到燃燒軍團之中有股邪惡的力量。消滅它，別讓它們繼續控制聖殿。', '', 25549),
(129837, 'zhTW', '你們殺死怪物了。很好！馬上就輪到基爾加丹了。', '', 25549),
(129836, 'zhTW', '燃燒軍團召喚了一隻專門獵食凡人的凶猛怪物。殺掉牠，不能讓牠被放出來！', '', 25549),
(129835, 'zhTW', '做得好。欺詐者失去對聖殿的控制，一定氣得跳腳。', '', 25549),
(129834, 'zhTW', '基爾加丹派了一個將領負責監視永夜聖殿。去把她收拾掉吧。', '', 25549),
(129833, 'zhTW', '', '我準備好前往斯寇亞胥了。\n\n該出發了嗎？', 25549),
(129832, 'zhTW', '可愛的寵物，飛吧！耶！', '', 25549),
(129831, 'zhTW', '嚐嚐痛苦的滋味！', '嚐嚐痛苦的滋味！', 25549),
(129830, 'zhTW', '燃燒軍團之命，不可違抗。', '燃燒軍團之命，不可違抗。', 25549),
(129829, 'zhTW', '大膽！', '大膽！', 25549),
(129828, 'zhTW', '在我的力量下凋零吧！', '在我的力量下凋零吧！', 25549),
(129827, 'zhTW', '你會死得又快又慘。', '你會死得又快又慘。', 25549),
(129826, 'zhTW', '你們的世界需要淨化！', '你們的世界需要淨化！', 25549),
(129825, 'zhTW', '我一定要復仇！', '我一定要復仇！', 25549),
(129824, 'zhTW', '啊…終於。', '啊…終於。', 25549),
(129823, 'zhTW', '怎麼…可能…', '怎麼…可能…', 25549),
(129822, 'zhTW', '結束我的痛苦！', '結束我的痛苦！', 25549),
(129821, 'zhTW', '準備受死吧！', '準備受死吧！', 25549),
(129820, 'zhTW', '加入亡者的行列…', '加入亡者的行列…', 25549),
(129819, 'zhTW', '死亡只是個開始。', '死亡只是個開始。', 25549),
(129818, 'zhTW', '你們無處可逃！', '你們無處可逃！', 25549),
(129817, 'zhTW', '靈魂交給我！', '靈魂交給我！', 25549),
(129816, 'zhTW', '', '那些惡魔以為自己能束縛元素。蠢貨！它們總算得到教訓了！', 25549),
(129815, 'zhTW', '', '這些埃雷達爾居然想充內行，用能量核心讓元素服從。給他們一點教訓，這種能量不容他們染指！', 25549),
(129814, 'zhTW', '被我束縛的人都是自找的！', '', 25549),
(129813, 'zhTW', '怎麼…可能…', '', 25549),
(129812, 'zhTW', '你會向燃燒軍團屈服的。我保證！', '', 25549),
(129811, 'zhTW', '', '我死了，束縛也不會解除！', 25549),
(129810, 'zhTW', '', '這些靈魂屬於燃燒軍團！', 25549),
(129809, 'zhTW', '走吧。', '', 25549),
(129808, 'zhTW', '結果不會改變。', '結果不會改變。', 25549),
(129807, 'zhTW', '安杜因！', '', 25549),
(129806, 'zhTW', '我的命運早已注定。', '我的命運早已注定。', 25549),
(129805, 'zhTW', '那裡！', '', 25549),
(129804, 'zhTW', '死亡中沒有安寧。', '死亡中沒有安寧。', 25549),
(129803, 'zhTW', '我的苦痛永無終結！', '我的苦痛永無終結！', 25549),
(129802, 'zhTW', '亡域之中，我仍然受縛…', '亡域之中，我仍然受縛…', 25549),
(129801, 'zhTW', '我沒有選擇！', '我沒有選擇！', 25549),
(129800, 'zhTW', '我身不由己。', '我身不由己。', 25549),
(129799, 'zhTW', '你不該來這裡。', '你不該來這裡。', 25549),
(129798, 'zhTW', '離開這裡，$c！', '離開這裡，$c！', 25549),
(129797, 'zhTW', '你確定達到19級後，就不想繼續獲得經驗值嗎？', '你確定達到19級後，就不想繼續獲得經驗值嗎？', 25549),
(129796, 'zhTW', '等我達到19級，就不想再獲得任何經驗值。', '等我達到19級，就不想再獲得任何經驗值。', 25549),
(129795, 'zhTW', '真巧。她也不喜歡你。\n\n快點開始吧，免得另一邊的埃雷達爾發現了我在做什麼，然後把傳送門給封了。', '', 25549),
(129794, 'zhTW', '我不喜歡這個惡魔。', '我不喜歡這個惡魔。', 25549),
(129793, 'zhTW', '聽說你有「惡魔出租」？', '聽說你有「惡魔出租」？', 25549),
(129792, 'zhTW', '走吧。', '', 25549),
(129791, 'zhTW', '父親…', '', 25549),
(129790, 'zhTW', '', '敵人接近了…動作快！', 25549),
(129789, 'zhTW', '', '繼續前進！這裡不安全…', 25549),
(129788, 'zhTW', '', '外來者，我們動作要快！', 25549),
(129787, 'zhTW', '我太天真了…', '', 25549),
(129786, 'zhTW', '這裡既可怕又令人哀傷。', '', 25549),
(129785, 'zhTW', '英雄，過來這裡。', '', 25549),
(129784, 'zhTW', '', '別再多說了！殺死他們！', 25549),
(129783, 'zhTW', '我不會手下留情！', '我不會手下留情！', 25549),
(129782, 'zhTW', '', '月樹，女神很滿意！', 25549),
(129781, 'zhTW', '', '女神祝福你的箭矢！', 25549),
(129780, 'zhTW', '', '射得真準，姊妹！', 25549),
(129779, 'zhTW', '', '你浪費太多時間了。消滅他們！', 25549),
(129778, 'zhTW', '', '夜之戰士會引導你，姊妹！', 25549),
(129777, 'zhTW', '', '看我的利刃！', 25549),
(129776, 'zhTW', '', '你妨礙到我了！', 25549),
(129775, 'zhTW', '', '正中目標！', 25549),
(129774, 'zhTW', '', '你不夠格！', 25549),
(129773, 'zhTW', '', '告解！懺悔！', 25549),
(129772, 'zhTW', '', '女神，揭露他們的罪惡！', 25549),
(129771, 'zhTW', '', '異端就該受到懲罰！', 25549),
(129770, 'zhTW', '', '見證她的榮耀！', 25549),
(129769, 'zhTW', '', '女神，燒死這些異端！', 25549),
(129768, 'zhTW', '', '把你的利爪埋進他們的血肉裡！', 25549),
(129767, 'zhTW', '', '我從不失手！', 25549),
(129766, 'zhTW', '', '我看見你了！', 25549),
(129765, 'zhTW', '', '我瞄準你了！', 25549),
(129764, 'zhTW', '', '審判從天而降！', 25549),
(129763, 'zhTW', '', '伊露恩之光直達天際！', 25549),
(129762, 'zhTW', '', '姊妹，交給我吧。我的武器等不及了！', 25549),
(129761, 'zhTW', '', '雅賽，我來收拾這些異端！', 25549),
(129760, 'zhTW', '', '別浪費時間了，卡絲佩蕾！我一定會贏！', 25549),
(129759, 'zhTW', '', '伊露恩…原諒我們…', 25549),
(129758, 'zhTW', '', '不！我…應該…要贏的…', 25549),
(129757, 'zhTW', '', '讓女神…失望了…', 25549),
(129756, 'zhTW', '', '下次我要第一個出手！', 25549),
(129755, 'zhTW', '', '神殿安全了。各位姊妹，打得好！', 25549),
(129754, 'zhTW', '', '女神讓我們獲得勝利！', 25549),
(129753, 'zhTW', '', '沒效率…但有效果。', 25549),
(129752, 'zhTW', '', '你對女神無比虔誠，姊妹！', 25549),
(129751, 'zhTW', '', '你應該信仰女神的！', 25549),
(129750, 'zhTW', '', '女神祝福你的弓，姊妹！', 25549),
(129749, 'zhTW', '', '殺得漂亮，姊妹！', 25549),
(129748, 'zhTW', '', '獵物倒下了！', 25549),
(129747, 'zhTW', '', '女神很滿意，姊妹！', 25549),
(129746, 'zhTW', '', '這次下手沒這麼俐落啊，姊妹！', 25549),
(129745, 'zhTW', '', '你的狩獵結束了！', 25549),
(129744, 'zhTW', '', '卡絲佩蕾，你老是這麼衝動。', 25549),
(129743, 'zhTW', '', '女神會指引你！', 25549),
(129742, 'zhTW', '', '姊妹們，我來打頭陣！', 25549),
(129741, 'zhTW', '', '卡絲佩蕾，我隨時都能動手。', 25549),
(129740, 'zhTW', '', '姊妹們！提高戒備！', 25549),
(129739, 'zhTW', '', '骯髒的生物！把他們從伊露恩的神殿裡趕出去！', 25549),
(129734, 'zhTW', '好！讓他們來吧！他們的屍體正好讓這個世界燒得更旺！', '', 25549),
(129733, 'zhTW', '做得好。這下子惡魔可就元氣大傷了。', '', 25549),
(129732, 'zhTW', '殺死惡魔，摧毀它們的防禦！', '', 25549),
(129731, 'zhTW', '獨自前往破碎海岸太危險了。我們一定要趕快找到安杜因！', '', 25549),
(129730, 'zhTW', '我馬上去準備船！', '', 25549),
(129729, 'zhTW', '現在輪到我了。帶我去父親壯烈犧牲的地方，我要親眼看一看。', '', 25549),
(129728, 'zhTW', '我能平安無事，都是英雄們的鮮血換來的。提里奧、伯瓦爾…還有我父親。', '', 25549),
(129727, 'zhTW', '我歷代先王向來御駕親征，與士兵並肩作戰，捍衛暴風城的自由。', '', 25549),
(129726, 'zhTW', '我的曾祖父拜瑞森國王，還有我的祖父萊恩王，都因此犧牲了性命。', '', 25549),
(129725, 'zhTW', '父親不是第一個因為燃燒軍團而死的暴風城國王。', '', 25549),
(129724, 'zhTW', '我一次又一次地，從遠處看著暴風城的英雄，為艾澤拉斯的和平犧牲。', '', 25549),
(129723, 'zhTW', '在母親死後，我是父親唯一的慰藉。', '', 25549),
(129722, 'zhTW', '父親不希望我參戰，堅持要我留在後方，因為暴風城不能沒有烏瑞恩家的人坐鎮。但我在他的眼裡發現了真相…他害怕失去我。', '', 25549),
(129721, 'zhTW', '狀況比我想的還要慘烈。', '', 25549),
(129720, 'zhTW', '來吧，我們繼續前進。', '', 25549),
(129719, 'zhTW', '這地方殘破又荒涼，在此犧牲性命真讓人遺憾。', '', 25549),
(129718, 'zhTW', '我們的部隊就是在這裡登陸破碎海岸的嗎。', '', 25549),
(129717, 'zhTW', '', '這樣應該夠了！現在呢…卡提拉希…還是要唸卡提拉斯？管他的！', 25549),
(129716, 'zhTW', '我打算躲在這裡，直到這一切結束。', '', 25549),
(129715, 'zhTW', '你找到了？真的好險！我實在想不到能代替的禮物…', '', 25549),
(129714, 'zhTW', '英雄！我飛越這裡的時候，出了點差錯。我掉了幾枚特別的硬幣，那是要給…呃，沒事。如果你能幫我找回來，我會很感謝你的！', '', 25549),
(129713, 'zhTW', '我需要休息…你先走吧！', '我需要休息…你先走吧！', 25549),
(129712, 'zhTW', '嗯呃…', '嗯呃…', 25549),
(129711, 'zhTW', '傷口太嚴重…我需要治療…', '傷口太嚴重…我需要治療…', 25549),
(129710, 'zhTW', '%s召喚了一名惡魔副官！', '%s召喚了一名惡魔副官！', 25549),
(129709, 'zhTW', '%s強化了惡魔傳送門！', '%s強化了惡魔傳送門！', 25549),
(129708, 'zhTW', '%s延長了惡魔傳送門的持續時間！', '%s延長了惡魔傳送門的持續時間！', 25549),
(129707, 'zhTW', '%s召喚了惡魔傳送門！', '%s召喚了惡魔傳送門！', 25549),
(129706, 'zhTW', '', '燃燒軍團永存不滅…', 25549),
(129705, 'zhTW', '', '你那些盟友的屍體，我的孩子會大口享用！', 25549),
(129704, 'zhTW', '|TInterface\\Icons\\inv_egg_01:20|t孵育中的蛋要|cFFFF0404|Hspell:240319|h[孵化]|h|r了！', '', 25549),
(129703, 'zhTW', '蜘…蜘…蜘蛛…', '蜘…蜘…蜘蛛…', 25549),
(129702, 'zhTW', '我…終於又能呼吸了。', '我…終於又能呼吸了。', 25549),
(129701, 'zhTW', '我感覺到血液裡的毒素消退了。謝謝你！', '我感覺到血液裡的毒素消退了。謝謝你！', 25549),
(129699, 'zhTW', '勇士，我們腳下的土地正在不斷腐化，這種情況已經擴散得到處都是。趕快清除腐化的生物！', '', 25549),
(129698, 'zhTW', '', '親愛的科里安…沒有你我該怎麼辦？', 25549),
(129697, 'zhTW', '', '陌生人，謝謝你！那群小鬼突然出現，我不知道該怎麼辦！我沒有值錢的東西，但應該要獎勵你的。請隨意看看補給品中有沒有用得上的東西。', 25549),
(129696, 'zhTW', '', '塵歸塵，土歸土。', 25549),
(129695, 'zhTW', '', '那些自大的埃雷達爾還是以為能讓艾澤拉斯的大地俯首稱臣？懲罰他們！', 25549),
(129694, 'zhTW', '要繼續嗎？', '要繼續嗎？', 25549),
(129693, 'zhTW', '我已經說不出離開這裡有多久了。突然湧現好多回憶…$b$b\n<費倫皺著眉頭，陷入深思。>', '', 25549),
(129692, 'zhTW', '我們所有人都要團結，才有機會擊敗燃燒軍團。', '', 25549),
(129691, 'zhTW', '哈圖恩，我不想跟你打。但我也不會讓你的怨恨阻礙我們對抗燃燒軍團。', '', 25549),
(129690, 'zhTW', '末日來臨…', '末日來臨…', 25549),
(129689, 'zhTW', '…在黑暗中。', '…在黑暗中。', 25549),
(129688, 'zhTW', '<不斷顫抖。>', '<不斷顫抖。>', 25549),
(129687, 'zhTW', '<聽不出來在說什麼。>', '<聽不出來在說什麼。>', 25549),
(129686, 'zhTW', '<胡言亂語。>', '<胡言亂語。>', 25549),
(129685, 'zhTW', '圖拉揚大主教…終於見面了。', '', 25549),
(129684, 'zhTW', '該怎麼跟小孩解釋？', '該怎麼跟小孩解釋？', 25549),
(129683, 'zhTW', '放下武器！預言者和他的盟友不是我們的敵人。', '', 25549),
(129682, 'zhTW', '有什麼是我們能做的嗎？', '有什麼是我們能做的嗎？', 25549),
(129681, 'zhTW', '夠了！', '', 25549),
(129680, 'zhTW', '這絕對不是末日！不可能的！', '這絕對不是末日！不可能的！', 25549),
(129679, 'zhTW', '我們跟阿古斯一起轉變了。除了努力忍受，我們還有什麼選擇？', '', 25549),
(129678, 'zhTW', '那個聲音…是哈圖恩？你是怎麼在這種地方撐這麼久的？', '', 25549),
(129677, 'zhTW', '我已經不知道該怎麼辦了！', '我已經不知道該怎麼辦了！', 25549),
(129676, 'zhTW', '末日到了嗎？這就是騷動的原因嗎？我還有很多事想做…', '末日到了嗎？這就是騷動的原因嗎？我還有很多事想做…', 25549),
(129675, 'zhTW', '天空從來沒有這麼黑暗過！難道沒有希望了嗎？', '天空從來沒有這麼黑暗過！難道沒有希望了嗎？', 25549),
(129673, 'zhTW', '預言者，你背棄了自己的同胞跟家園。你這麼做，應該以死謝罪。', '', 25549),
(129672, 'zhTW', '費倫，你終於回到這個被你遺棄的地方了。', '', 25549),
(129671, 'zhTW', '馬上現身！', '', 25549),
(129670, 'zhTW', '如果城市被進攻呢？到時候要怎麼辦？', '如果城市被進攻呢？到時候要怎麼辦？', 25549),
(129669, 'zhTW', '這代表什麼？末日到了嗎？', '這代表什麼？末日到了嗎？', 25549),
(129668, 'zhTW', '我們最好開始準備，勇士！去告訴卡德加我們發現了什麼。祝你好運！', '', 25549),
(129667, 'zhTW', '只要大家團結，一定會有辦法。', '', 25549),
(129666, 'zhTW', '這個地方…好熟悉。', '', 25549),
(129665, 'zhTW', '這是命令。<絞死他。>', '這是命令。<絞死他。>', 25549),
(129664, 'zhTW', '別落單了，有人在監視我們。', '', 25549),
(129663, 'zhTW', '', '喔，別擔心，先知…我們會盯著末日石。', 25549),
(129659, 'zhTW', '她受到燃燒軍團…還有古神的影響。不只這樣…還有更深的…黑暗…', '', 25549),
(129658, 'zhTW', '和世界之魂對話跟凡人間的對話不同。所以她才會需要找人擔任代言者。', '', 25549),
(129657, 'zhTW', '沒有她，你會更好！', '', 25549),
(129656, 'zhTW', '別相信她！在這裡，只有我才有真正的力量！', '', 25549),
(129655, 'zhTW', '', '記得回來。說不定我還有任務要給你。', 25549),
(129654, 'zhTW', '純淨美好的夢想…真可笑！這個世界充滿了痛苦，孩子。', '', 25549),
(129653, 'zhTW', '哼！我跟潮石或者其他那些老掉牙的聖物一樣強大！', '', 25549),
(129652, 'zhTW', '她就連殘響都還這麼囉嗦！你現在知道我當初有多痛苦了吧？', '', 25549),
(129651, 'zhTW', '你找我嗎，奈普圖隆？', '你找我嗎，奈普圖隆？', 25549),
(129650, 'zhTW', '啊…只不過是她力量的殘響罷了。沒什麼好擔心的，孩子。', '', 25549),
(129649, 'zhTW', '你親眼見證了末日石的毀滅力量有多巨大。你是艾澤拉斯可靠的守護者，但就算在你手中，這股力量還是為你的人民帶來了混亂與恐慌。想想看，如果它被不懷好意的人取走會有多可怕…$b$b絕對不能讓這種事發生。$b$b我們在等你清醒的這段時間不斷討論該如何處置這個聖物。我們打算把它放到其中一個元素界域，但是不論是哪個界域都有潛在風險。$b$b沒有其他地方會比把它放在艾澤拉斯之心安全。陶土議會將負責看管，確保再也不會有人能使用它。把它放在這個石臺上，這就是它最後的歸宿。', '', 25549),
(129648, 'zhTW', '她還活著？不！我不會再讓她控制我！', '', 25549),
(129647, 'zhTW', '你好啊，先知。你恢復體力了嗎？', '', 25549),
(129646, 'zhTW', '欺詐者！你們對艾澤拉斯的侵略到此為止。叫你們的主人死了這條心吧！', '', 25549),
(129645, 'zhTW', '你們的骨灰是我的佳餚！', '', 25549),
(129644, 'zhTW', '魔能賜我力量！', '', 25549),
(129643, 'zhTW', '混沌會吞噬你！', '', 25549),
(129642, 'zhTW', '你們的現實會崩裂！', '', 25549),
(129641, 'zhTW', '你們居然還活著！無所謂。看看燃燒軍團偉大的力量！你們絕望吧，凡人！這個世界就是你們的墳墓！', '', 25549),
(129640, 'zhTW', '基爾加丹會從這些船艦汲取力量！', '', 25549),
(129639, 'zhTW', '你們抵抗也沒用！無窮無盡的大軍會給我力量！', '', 25549),
(129638, 'zhTW', '你無法抵抗自己的黑暗面。', '', 25549),
(129637, 'zhTW', '我感覺到你內心的腐化。', '', 25549),
(129636, 'zhTW', '面對自身的黑暗吧！', '', 25549),
(129635, 'zhTW', '為什麼？你們明明充滿懷疑，充滿恐懼，為什麼還不肯屈服？', '', 25549),
(129634, 'zhTW', '鼓起勇氣面對我的手下，不是什麼了不起的事。你們有辦法展現勇氣，去面對自己靈魂的黑暗嗎？', '', 25549),
(129633, 'zhTW', '伊克薩侖，過來殺光他們！', '', 25549),
(129632, 'zhTW', '全部燒死！', '', 25549),
(129631, 'zhTW', '嘗嘗我的怒火！', '', 25549),
(129630, 'zhTW', '燒吧！燒吧！然後去死！', '', 25549),
(129629, 'zhTW', '還在抵抗！我來回敬你的傲慢自大！', '', 25549),
(129628, 'zhTW', '掙扎也沒用！燃燒軍團一定會拿下艾澤拉斯！', '', 25549),
(129627, 'zhTW', '放肆的凡人！你們的命運在踏進扭曲虛空的那一刻就已經注定！', '', 25549),
(129626, 'zhTW', '死在我的戰刃下！', '', 25549),
(129625, 'zhTW', '該死的惡魔！', '', 25549),
(129624, 'zhTW', '英雄！好好選擇你的目標！', '', 25549),
(129623, 'zhTW', '我們來看看你會不會打仗！鎖定敵人！', '', 25549),
(129622, 'zhTW', '別失去信心！', '', 25549),
(129621, 'zhTW', '你還不能死！', '', 25549),
(129620, 'zhTW', '聖光會治療你們！', '', 25549),
(129619, 'zhTW', '死吧，英雄！', '', 25549),
(129618, 'zhTW', '無法逃離的宿命！', '', 25549),
(129617, 'zhTW', '魔誓者，把憤怒轉向他們！', '', 25549),
(129616, 'zhTW', '術士，燒死這群廢物！', '', 25549),
(129615, 'zhTW', '魔裔，讓他們看看反抗的下場！', '', 25549),
(129614, 'zhTW', '埃雷達爾，讓費倫的走狗知道拼死抵抗有多愚蠢！', '', 25549),
(129613, 'zhTW', '現在誰會來救你啊？', '', 25549),
(129612, 'zhTW', '在主人面前屈服吧！', '', 25549),
(129611, 'zhTW', '你們竟然蠢到追過來！', '', 25549),
(129606, 'zhTW', '不！你別想離間我們，欺詐者。我們會攜手合作、一起戰鬥。只要團結一心，就能粉碎你們的陰謀！', '', 25549),
(129605, 'zhTW', '你無用的憤怒只是害這群盟友陪你送死。好好欣賞無窮無盡的燃燒軍團怎麼宰殺他們吧！', '', 25549),
(129604, 'zhTW', '啊啊啊啊啊！', '', 25549),
(129603, 'zhTW', '聖光拯救你兒子了嗎？拉克許死前那一刻，眼睛裡閃耀的是信仰的光芒嗎？還是…對遺棄他的父親充滿恨意？', '', 25549),
(129602, 'zhTW', '你對聖光失去了信心。只要我們一起，就能抵抗薩格拉斯，拯救這個世界！', '', 25549),
(129601, 'zhTW', '那是因為你缺乏遠見！是你不願意接受燃燒軍團必定獲勝的事實！', '', 25549),
(129600, 'zhTW', '你追殺自己的同胞，讓我們在星際間逃亡。我受夠了！', '', 25549),
(129599, 'zhTW', '大領主，我們出發去救盟友吧。', '大領主，我們出發去救盟友吧。', 25549),
(129598, 'zhTW', '大領主，能跟你一同奮戰是我的榮耀。', '大領主，能跟你一同奮戰是我的榮耀。', 25549),
(129597, 'zhTW', '大領主，與你並肩戰鬥是我的榮幸。', '大領主，與你並肩戰鬥是我的榮幸。', 25549),
(129596, 'zhTW', '大領主，我隨時可以出發！', '大領主，我隨時可以出發！', 25549),
(129595, 'zhTW', '我會和你並肩作戰。', '我會和你並肩作戰。', 25549),
(129594, 'zhTW', '勇士，做好準備，我們被包圍了。', '', 25549),
(129593, 'zhTW', '我準備好要去找生還者了。', '我準備好要去找生還者了。', 25549),
(129592, 'zhTW', '這裡已經不是我記憶中的阿古斯了。', '', 25549),
(129591, 'zhTW', '請大家保持冷靜，耐心等候進一步的消息。', '請大家保持冷靜，耐心等候進一步的消息。', 25549),
(129590, 'zhTW', '我們是到這裡來協助大家的。千萬不要驚慌，請記得隨時遵守秩序。', '我們是到這裡來協助大家的。千萬不要驚慌，請記得隨時遵守秩序。', 25549),
(129589, 'zhTW', '如果你注意到可疑行動或是怪異舉止，請立刻告知我們。', '如果你注意到可疑行動或是怪異舉止，請立刻告知我們。', 25549),
(129588, 'zhTW', '由於突然湧進大批的顧客，請大家保持冷靜、遵守秩序。', '由於突然湧進大批的顧客，請大家保持冷靜、遵守秩序。', 25549),
(129587, 'zhTW', '請所有人保持冷靜，遵守排隊的秩序。只要一有空位，銀行職員就會立刻協助你。', '請所有人保持冷靜，遵守排隊的秩序。只要一有空位，銀行職員就會立刻協助你。', 25549),
(129586, 'zhTW', '', '希望我們家裡的箱子連世界末日都擋得住。', 25549),
(129585, 'zhTW', '', '世界末日？呸！我是想拿走我們的錢，可是這些傢伙的動作慢得跟蝸牛一樣！', 25549),
(129584, 'zhTW', '', '到底要怎樣才能在這裡找到幫手啊？我們想把東西安全帶回家，以免…嗯，你知道的。', 25549),
(129583, 'zhTW', '', '別動！我們可不希望寶物倒下來，對吧？', 25549),
(129582, 'zhTW', '', '你沒看過別人保護自己的財產嗎？$B$B快走開啦！', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129581, 'zhTW', '', '你想幹嘛？', 25549),
(129580, 'zhTW', '', '聽著，我們敢保證貨物在這裡絕對「安全」，只是何必冒險呢？', 25549),
(129579, 'zhTW', '這也有可能是個陷阱。', '', 25549),
(129578, 'zhTW', '勇士，保持警戒。燃燒軍團可是詭計多端。', '', 25549),
(129577, 'zhTW', '傳送門要關了！我們要關閉燃燒軍團傳送門，讓它們不能再攻擊。', '', 25549),
(129576, 'zhTW', '不！我們絕對不會罷休！你就享受小小的勝利吧。我們會一次又一次地回來，不管要花多少時間，我們一定會粉碎你！', '', 25549),
(129575, 'zhTW', '', '就是這樣！順從那股力量！', 25549),
(129574, 'zhTW', '到此…為止…', '', 25549),
(129573, 'zhTW', '', '小夥子，撐下去！這樣就不行了嗎？', 25549),
(129572, 'zhTW', '', '這力量…多麼瘋狂！', 25549),
(129571, 'zhTW', '這力量太強了，你根本沒辦法控制！', '', 25549),
(129570, 'zhTW', '我奪走了這個世界的火焰力量，它們現在聽我的！', '', 25549),
(129569, 'zhTW', '薩格拉斯讓你看的景象都是謊言，基爾加丹。快投降！到此為止！', '', 25549),
(129568, 'zhTW', '你輸了這麼多次，還是沒學到教訓嗎，欺詐者？', '', 25549),
(129567, 'zhTW', '你還在反抗我們！還想拒絕必然的宿命！你不斷抵抗，讓我非常憤怒！你為什麼不肯屈服？', '', 25549),
(129566, 'zhTW', '都…結束了…', '', 25549),
(129565, 'zhTW', '凡人…必敗。', '', 25549),
(129564, 'zhTW', '主人…必勝。', '', 25549),
(129563, 'zhTW', '…在暗影中，聖光不會熄滅。', '…在暗影中，聖光不會熄滅。', 25549),
(129562, 'zhTW', '修復工作快要完成了。', '修復工作快要完成了。', 25549),
(129561, 'zhTW', '我們一定能重拾榮耀。', '我們一定能重拾榮耀。', 25549),
(129560, 'zhTW', '雖然最近發生的事很讓人擔心，但在黑暗之後就是黎明。', '雖然最近發生的事很讓人擔心，但在黑暗之後就是黎明。', 25549),
(129559, 'zhTW', '準備工作快做好了，偉大的旅程就要開始。', '準備工作快做好了，偉大的旅程就要開始。', 25549),
(129558, 'zhTW', '聖光保佑，新的旅程開始了。', '聖光保佑，新的旅程開始了。', 25549),
(129557, 'zhTW', '死了！', '', 25549),
(129556, 'zhTW', '', '那個惡魔不只殘害你的人民，就連大地也遭殃！如果你在等待使用末日石的最佳時機…那就是現在！', 25549),
(129555, 'zhTW', '死吧！', '', 25549),
(129554, 'zhTW', '', '一定要清除腐化！', 25549),
(129553, 'zhTW', '守衛者…', '', 25549),
(129552, 'zhTW', '我砍！', '', 25549),
(129551, 'zhTW', '詛咒！', '', 25549),
(129550, 'zhTW', '混亂！', '', 25549),
(129549, 'zhTW', '燒吧！', '', 25549),
(129548, 'zhTW', '凡人…去死！', '', 25549),
(129547, 'zhTW', '宰了…你們！', '', 25549),
(129546, 'zhTW', '祝你好運，先知。相信你不會讓我失望。', '', 25549),
(129545, 'zhTW', '掙脫束縛！用盡全力！把這個世界徹底粉碎！', '', 25549),
(129544, 'zhTW', '哈，你的傀儡不受控制了，基爾加丹！', '', 25549),
(129543, 'zhTW', '該死的凡人！你們像蟲子一樣鑽進這個墓穴，殺死我的手下，還以為自己能跟燃燒軍團平起平坐。什麼英雄…勇士…都是蠢貨！', '', 25549),
(129542, 'zhTW', '通道已經打開了。你知道的一切、在乎的一切，全都會毀滅。', '', 25549),
(129541, 'zhTW', '因為你，你的世界會在主人的火焰中燒毀。', '', 25549),
(129540, 'zhTW', '無所謂。早就已經開始了。', '', 25549),
(129539, 'zhTW', '蠢貨！你所知道的，只是燃燒軍團的一小部分。', '', 25549),
(129538, 'zhTW', '徹底…粉碎…', '', 25549),
(129537, 'zhTW', '戰況越來越不利。殺死它們的指揮官，不然我們就完了！', '', 25549),
(129536, 'zhTW', '不用道歉。你們沒有做錯什麼。我們只是要確定你們兩個在街上都平安無事。', '不用道歉。你們沒有做錯什麼。我們只是要確定你們兩個在街上都平安無事。', 25549),
(129535, 'zhTW', '這種時候小孩子不應該在外面到處亂跑。待會就會有人來照顧你們，直到確定情況安全為止。', '這種時候小孩子不應該在外面到處亂跑。待會就會有人來照顧你們，直到確定情況安全為止。', 25549),
(129534, 'zhTW', '孩子，不能怪你們，但是這種時候在外面亂跑，真的很不安全。', '孩子，不能怪你們，但是這種時候在外面亂跑，真的很不安全。', 25549),
(129533, 'zhTW', '你的爸媽呢？這種時候不應該在城裡到處亂跑。', '你的爸媽呢？這種時候不應該在城裡到處亂跑。', 25549),
(129532, 'zhTW', '拜託！有人看到他們的爸媽嗎？這種時候在城裡亂跑真的很不應該，太危險了。', '拜託！有人看到他們的爸媽嗎？這種時候在城裡亂跑真的很不應該，太危險了。', 25549),
(129531, 'zhTW', '議會一定會及時發布消息的，我敢保證。', '', 25549),
(129530, 'zhTW', '我們應該聽從領導者的指引，而不是城裡的閒話。我們會及時得知消息的。', '', 25549),
(129529, 'zhTW', '', '不知道什麼時候才會平靜下來。自從發生狀況以後，城裡就鬧哄哄的。', 25549),
(129528, 'zhTW', '', '先前我走在路上，聽到各種臆測，耳朵都快長繭了。最近城裡的氣氛好不安定。', 25549),
(129527, 'zhTW', '', '我們應該保持正面的態度。大家要處理的事已經夠多了，我們要當大家的榜樣。', 25549),
(129526, 'zhTW', '', '我完全相信領導者。我們不該聽那些無聊的八卦，弄得大家人心惶惶。每個人面對壓力的方式都不一樣。', 25549),
(129525, 'zhTW', '我準備好了。', '我準備好了。', 25549),
(129524, 'zhTW', '我們就來偷走夜裔裁縫的秘密吧？', '', 25549),
(129523, 'zhTW', '抬頭看看天空！真相終於明朗了！', '抬頭看看天空！真相終於明朗了！', 25549),
(129522, 'zhTW', '末日即將來臨！', '末日即將來臨！', 25549),
(129521, 'zhTW', '跟我說說你對時尚風格的見解吧。', '跟我說說你對時尚風格的見解吧。', 25549),
(129520, 'zhTW', '在我為你解說如何打造傳說級物品之前，你需要先了解有關格調與風采的基礎哲理。這沒有商量的餘地！你準備好開始了嗎？', '', 25549),
(129519, 'zhTW', '', '我們恐怖圖騰的人就算淪為俘虜也會奮戰到底。你們陶土議會…就是懦弱。', 25549),
(129518, 'zhTW', '', '孩子，你聽到風在說什麼嗎？風在苦苦求救，想擺脫燃燒軍團的控制。', 25549),
(129517, 'zhTW', '', '想想大地的力量…多麼穩固、堅實、難以撼動。但只要小小的震顫，就有驚人的毀滅力量。', 25549),
(129516, 'zhTW', '', '水是最弱、最柔和的元素，它的力量多半用來治療。燃燒軍團究竟有什麼企圖？', 25549),
(129515, 'zhTW', '', '燃燒軍團有魔化火焰，就以為自己能控制艾澤拉斯的火元素。大錯特錯！', 25549),
(129514, 'zhTW', '', '手上有這麼強大的神器卻不敢用，到底意義何在？末日石要是交給我，會更有用處。', 25549),
(129513, 'zhTW', '', '你知道嗎，只要你肯用末日石，這一切很快就會結束了。', 25549),
(129512, 'zhTW', '', '竟然想掌控艾澤拉斯的大地？愚蠢的埃雷達爾！', 25549),
(129511, 'zhTW', '這片天空屬於燃燒軍團！', '這片天空屬於燃燒軍團！', 25549),
(129510, 'zhTW', '我們的翅膀會遮住你的天空！', '我們的翅膀會遮住你的天空！', 25549),
(129509, 'zhTW', '正好拿你的屍體來餵坐騎。', '正好拿你的屍體來餵坐騎。', 25549),
(129508, 'zhTW', '', '如果你以為能把末日石從我眼前帶走，那就大錯特錯了。開始行動吧。', 25549),
(129507, 'zhTW', '', '正好拿你的屍體來餵坐騎。', 25549),
(129506, 'zhTW', '', '這片天空屬於燃燒軍團！', 25549),
(129505, 'zhTW', '', '我們的翅膀會遮住你的天空！', 25549),
(129504, 'zhTW', '這片天空屬於燃燒軍團！', '', 25549),
(129503, 'zhTW', '正好拿你的屍體來餵坐騎。', '', 25549),
(129502, 'zhTW', '我們的翅膀會遮住你的天空！', '', 25549),
(129501, 'zhTW', '', '這陣子充滿魔法氣息的可不是只有天空！放鬆一下，進來看看我們最新的商品吧。', 25549),
(129500, 'zhTW', '', '嗨，$n！議會發布新消息了嗎？', 25549),
(129499, 'zhTW', '送我去四風王座吧。', '送我去四風王座吧。', 25549),
(129498, 'zhTW', '', '我們在這裡覺得越來越不安了。有任何新消息嗎？', 25549),
(129497, 'zhTW', '', '有消息嗎，$n？', 25549),
(129496, 'zhTW', '', '$n，現在外面在談論什麼？', 25549),
(129495, 'zhTW', '', '請你盡量小聲一點。這裡的野獸最近一直躁動。', 25549),
(129494, 'zhTW', '', '好了，好了，我美麗的野獸！一切很快就會恢復正常的…希望如此。', 25549),
(129493, 'zhTW', '', '小心一點。寵物這陣子出現異常的舉動。建議你暫時別太靠近獸欄。', 25549),
(129492, 'zhTW', '', '抱歉，最近寵物的狀況不太好。牠們不知道為什麼，變得非常焦躁。', 25549),
(129491, 'zhTW', '%s變得很不安。', '%s變得很不安。', 25549),
(129490, 'zhTW', '這裡不歡迎你！！滾回去！', '', 25549),
(129489, 'zhTW', '', '小心腳步，$n！對了，最近議會有什麼消息嗎？', 25549),
(129488, 'zhTW', '', '到底發生什麼事？外面的吵雜聲越來越大。希望能趕快知道這是怎麼回事。', 25549),
(129487, 'zhTW', '', '歡迎光臨！我跟魯西安正在討論最近發生的事情。能告訴我們一點新消息嗎？', 25549),
(129486, 'zhTW', '', '$n，外面情況怎麼樣？一整天好多人來來去去，但是大家知道的都不多。', 25549),
(129485, 'zhTW', '', '有新消息嗎？已經很久沒有消息了。', 25549),
(129484, 'zhTW', '', '只能在這裡乾等，我真的快崩潰了。', 25549),
(129483, 'zhTW', '', '希望趕快有新的消息。上一次收到消息已經過好久了。', 25549),
(129482, 'zhTW', '', '有時候我懷疑我們是否會有得知真相的一天…', 25549),
(129481, 'zhTW', '', '希望你一切都好，$n。至於我，唉…', 25549),
(129480, 'zhTW', '', '喔，不！我又灑了一杯飲料。最近這裡狀況好多，我的手抖個不停。', 25549),
(129479, 'zhTW', '', '啊，$n！或許你能為我們解決這件事。我跟艾立爾正在爭論議會到底討論出結果了沒有。有任何消息嗎？', 25549),
(129478, 'zhTW', '', '坐下來，放鬆一下。既然進了門，就把外頭的煩心事給忘了吧。', 25549),
(129477, 'zhTW', '', '艾立爾，別這樣！有客人在呢。我們還不知道實際狀況，沒必要胡思亂想。', 25549),
(129476, 'zhTW', '', '勇士，謝謝你們。希望你們能淨化這座被黑暗籠罩的神殿。', 25549),
(129475, 'zhTW', '', '我嘗試抵抗，卻失敗了。至少我現在自由了。', 25549),
(129474, 'zhTW', '', '我應該要更堅強的。告訴泰蘭妲…我很抱歉。', 25549),
(129473, 'zhTW', '', '引擎會吞噬一切！', 25549),
(129472, 'zhTW', '', '凡人的靈魂…真軟弱，真可悲！', 25549),
(129471, 'zhTW', '', '伊露恩在這裡沒有力量。這座墓地屬於燃燒軍團！', 25549),
(129470, 'zhTW', '', '吞噬吧，靈魂引擎！', 25549),
(129469, 'zhTW', '', '我為主人殺戮！', 25549),
(129468, 'zhTW', '', '你的靈魂是我的！', 25549),
(129467, 'zhTW', '', '不要抗拒主人的意志！', 25549),
(129466, 'zhTW', '', '這座神殿是你們的墳墓！', 25549),
(129465, 'zhTW', '', '跟我一樣臣服吧！', 25549),
(129464, 'zhTW', '我們會獲勝！', '', 25549),
(129463, 'zhTW', '你們再怎麼掙扎都沒用！', '', 25549),
(129462, 'zhTW', '你沒希望了！', '', 25549),
(129461, 'zhTW', '任務…必須繼續…', '', 25549),
(129460, 'zhTW', '引擎…失靈了…', '', 25549),
(129459, 'zhTW', '功虧…一簣…', '', 25549),
(129458, 'zhTW', '引擎在渴望吞噬！', '', 25549),
(129457, 'zhTW', '靈魂讓我們變強！', '', 25549),
(129456, 'zhTW', '真是場大豐收！', '', 25549),
(129455, 'zhTW', '更多燃料！', '', 25549),
(129454, 'zhTW', '又得到一個了！', '', 25549),
(129453, 'zhTW', '又收割了一個！', '', 25549),
(129452, 'zhTW', '你們的靈魂只配當燃料！', '', 25549),
(129451, 'zhTW', '你們是引擎的燃料！', '', 25549),
(129450, 'zhTW', '撕裂你的靈魂！', '', 25549),
(129449, 'zhTW', '你的苦難是我們的糧食！', '', 25549),
(129448, 'zhTW', '你逃不出我們的手掌心！', '', 25549),
(129447, 'zhTW', '釋放我們的憤怒！', '', 25549),
(129446, 'zhTW', '相信你可以應付得很好。希望其他人也一樣。', '', 25549),
(129445, 'zhTW', '空虛…荒蕪…', '', 25549),
(129444, 'zhTW', '你們的靈魂只有絕望！', '', 25549),
(129443, 'zhTW', '黑暗會吞噬你！', '', 25549),
(129442, 'zhTW', '', '你感覺到死亡逼近了嗎？', 25549),
(129441, 'zhTW', '', '啊，這束縛！', 25549),
(129440, 'zhTW', '', '生命總是伴隨著死亡！', 25549),
(129439, 'zhTW', '', '你會感受他們的痛苦！', 25549),
(129438, 'zhTW', '', '讓他們的痛苦淹沒你！', 25549),
(129437, 'zhTW', '', '聽聽絕望的呼喊！', 25549),
(129436, 'zhTW', '我很想要保持樂觀，但我實在不知道未來會怎麼樣。', '我很想要保持樂觀，但我實在不知道未來會怎麼樣。', 25549),
(129435, 'zhTW', '今天有什麼新消息嗎？', '今天有什麼新消息嗎？', 25549),
(129434, 'zhTW', '我一直回來這裡，想聽到最新消息，但答案總是一樣。', '我一直回來這裡，想聽到最新消息，但答案總是一樣。', 25549),
(129433, 'zhTW', '這代表什麼呢？我從來沒看過這種狀況。', '這代表什麼呢？我從來沒看過這種狀況。', 25549),
(129432, 'zhTW', '我聽到的都是舊消息，$n。你呢？', '我聽到的都是舊消息，$n。你呢？', 25549),
(129431, 'zhTW', '我只想知道答案。', '我只想知道答案。', 25549),
(129430, 'zhTW', '我想知道到底發生什麼事了。', '我想知道到底發生什麼事了。', 25549),
(129429, 'zhTW', '我想知道答案。你有聽到新消息嗎？', '我想知道答案。你有聽到新消息嗎？', 25549),
(129428, 'zhTW', 'The final stage of the scenario is not yet complete. You''ll destroy the legion ship and it will be awesome. Please send any feedback you have so far!', 'The final stage of the scenario is not yet complete. You''ll destroy the legion ship and it will be awesome. Please send any feedback you have so far!', 25549),
(129427, 'zhTW', '我們一起通過了許多考驗，$n。', '', 25549),
(129426, 'zhTW', '我已經準備好發動攻擊。', '我已經準備好發動攻擊。', 25549),
(129425, 'zhTW', '', '$n，你在這裡很安全。自從騷動開始以後，安戴魯就一直緊張地盯著門看，不過我完全不擔心。', 25549),
(129424, 'zhTW', '', '$n，這家店永遠歡迎你。希望店裡面的氣氛比外頭平靜。', 25549),
(129423, 'zhTW', '', '$n，很高興再看到你。你是來聊天的嗎？還是需要補給品？還是只想休息一下…躲一下外面發生的…事情。', 25549),
(129422, 'zhTW', '', '歡迎光臨！議會發布任何消息了嗎，$n？', 25549),
(129421, 'zhTW', '', '$n，真高興看到你！最近發生的事你有新消息嗎？', 25549),
(129420, 'zhTW', '現在看見星星是正常的嗎？', '現在看見星星是正常的嗎？', 25549),
(129419, 'zhTW', '我只想要恢復正常的自己。', '我只想要恢復正常的自己。', 25549),
(129418, 'zhTW', '我快受不了了，我怕會撐不下去。', '我快受不了了，我怕會撐不下去。', 25549),
(129417, 'zhTW', '他們說這只是想像出來的，但這次…這次不一樣。我發誓！', '他們說這只是想像出來的，但這次…這次不一樣。我發誓！', 25549),
(129416, 'zhTW', '不能再這樣下去，我快受不了了。', '不能再這樣下去，我快受不了了。', 25549),
(129415, 'zhTW', '求求你。一定要幫幫我們。', '求求你。一定要幫幫我們。', 25549),
(129414, 'zhTW', '我覺得它又要來了…', '我覺得它又要來了…', 25549),
(129413, 'zhTW', '我...覺得不太舒服。', '我...覺得不太舒服。', 25549),
(129412, 'zhTW', '', '$n，你好。你知道王家水池原本有全艾蘇納最大最美的魚嗎？那些皇親貴族常常來水池附近散心，只要看著優雅自在的魚就可以忘記所有煩惱。\n\n但現在…開始出問題了！', 25549),
(129411, 'zhTW', '', '$n，我從來沒看過這種狀況。我們會繼續提供協助，請把出現類似症狀的人送來我這裡。', 25549),
(129410, 'zhTW', '', '希望狀況趕快平息，人們一直驚慌地湧進來。', 25549),
(129409, 'zhTW', '', '我們很快就得請大家去其他地方了。這裡的物資快不夠了，秩序會開始大亂的。', 25549),
(129408, 'zhTW', '', '$n，你有任何消息嗎？症狀依然沒有消退，我完全找不出原因！', 25549),
(129407, 'zhTW', '', '我們快要沒有容納病人的空間了。我不知道還能撐多久。', 25549),
(129406, 'zhTW', '', '$n，我不知道還能撐多久，補給品快不夠用了。', 25549),
(129405, 'zhTW', '', '我們找了幫手來，很快就會輪到你的，請稍安勿躁。', 25549),
(129404, 'zhTW', '', '如果這裡太多人，請往外面移動。我們增設了幾個服務站，也增派人員提供協助。', 25549),
(129403, 'zhTW', '', '$n！來的人越來越多！我從沒看過這種情況。', 25549),
(129402, 'zhTW', '', '請保持冷靜。我們會幫你們每個人治療，請大家耐心等候。', 25549),
(129401, 'zhTW', '它們什麼都不會，只會激怒元素而已！', '它們什麼都不會，只會激怒元素而已！', 25549),
(129400, 'zhTW', '沒有能量核心，它們就會失去控制！', '沒有能量核心，它們就會失去控制！', 25549),
(129399, 'zhTW', '燃燒軍團竟然逼艾澤拉斯的元素服從…太過分了！', '燃燒軍團竟然逼艾澤拉斯的元素服從…太過分了！', 25549),
(129398, 'zhTW', '', '如果再有市民出現這些症狀，我們就會需要訓練額外的人手。', 25549),
(129397, 'zhTW', '', '$n，你是來幫忙的嗎？我還沒辦法做出診斷，他們身上各種症狀都有。', 25549),
(129396, 'zhTW', '喔，你想知道怎麼去艾克索達的入口。我忘記新來的人都對這空蕩蕩的大廳不熟。在那魯之座的上層有個能通往地面的坡道。', '喔，你想知道怎麼去艾克索達的入口。我忘記新來的人都對這空蕩蕩的大廳不熟。在那魯之座的上層有個能通往地面的坡道。', 25549),
(129395, 'zhTW', '離開這裡，前往藍謎島', '離開這裡，前往藍謎島', 25549),
(129394, 'zhTW', '聖壇被燃燒軍團腐化了！', '聖壇被燃燒軍團腐化了！', 25549),
(129393, 'zhTW', '「我們握有的力量，會讓敵人聞風喪膽。」', '「我們握有的力量，會讓敵人聞風喪膽。」', 25549),
(129392, 'zhTW', '「風迅捷無懼。」', '「風迅捷無懼。」', 25549),
(129391, 'zhTW', '「萬物皆蘊含真理。」', '「萬物皆蘊含真理。」', 25549),
(129390, 'zhTW', '「堅韌來自於腳下的大地中。」', '「堅韌來自於腳下的大地中。」', 25549),
(129389, 'zhTW', '其他大陸', '其他大陸', 25549),
(129388, 'zhTW', '東部王國的暴風城或鐵爐堡', '東部王國的暴風城或鐵爐堡', 25549),
(129387, 'zhTW', '外域的地獄火半島', '外域的地獄火半島', 25549),
(129386, 'zhTW', '達納蘇斯', '達納蘇斯', 25549),
(129385, 'zhTW', '如果你想去我們在外域的家園，可以用聖光地窖中的傳送門前往地獄火半島。', '如果你想去我們在外域的家園，可以用聖光地窖中的傳送門前往地獄火半島。', 25549),
(129384, 'zhTW', '在聖光地窖中有個通往夜精靈主城達納蘇斯的傳送門。', '在聖光地窖中有個通往夜精靈主城達納蘇斯的傳送門。', 25549),
(129383, 'zhTW', '如果要去暴風城，只有透過航海。先去藍謎島，然後再從那裡找路前往瓦拉船台。從瓦拉船台最遠可以抵達魯瑟蘭村，你可以從那裡搭船前往暴風城和東部王國的其他地點。如果你不知道該怎麼到陸地上，我也可以為你指引出入口的方向。', '如果要去暴風城，只有透過航海。先去藍謎島，然後再從那裡找路前往瓦拉船台。從瓦拉船台最遠可以抵達魯瑟蘭村，你可以從那裡搭船前往暴風城和東部王國的其他地點。如果你不知道該怎麼到陸地上，我也可以為你指引出入口的方向。', 25549),
(129382, 'zhTW', '議會希望大家先冷靜下來，等他們做出完善的評估。', '議會希望大家先冷靜下來，等他們做出完善的評估。', 25549),
(129381, 'zhTW', '如果發現任何異常行為，無論是否與魔法有關，都請盡速回報。', '如果發現任何異常行為，無論是否與魔法有關，都請盡速回報。', 25549),
(129380, 'zhTW', '我們要保持冷靜，等議會成員完成調查工作。', '我們要保持冷靜，等議會成員完成調查工作。', 25549),
(129379, 'zhTW', '我們會跟議會成員保持密切合作，直到目前的情況恢復正常為止。', '我們會跟議會成員保持密切合作，直到目前的情況恢復正常為止。', 25549),
(129378, 'zhTW', '我們比較晚才來到這個世界，不過已經著手跟聯盟的重鎮建立關係。\n\n你打算去哪個地方？', '我們比較晚才來到這個世界，不過已經著手跟聯盟的重鎮建立關係。\n\n你打算去哪個地方？', 25549),
(129377, 'zhTW', '議會成員知道現在的狀況。他們希望我們冷靜下來，等他們做出完善的評估。', '議會成員知道現在的狀況。他們希望我們冷靜下來，等他們做出完善的評估。', 25549),
(129376, 'zhTW', '請保持冷靜，很快就會有答案了。', '請保持冷靜，很快就會有答案了。', 25549),
(129375, 'zhTW', '我們要答案！我們要知道會發生什麼事。', '我們要答案！我們要知道會發生什麼事。', 25549),
(129374, 'zhTW', '大家都在做什麼？小孩都被嚇到了。', '大家都在做什麼？小孩都被嚇到了。', 25549),
(129373, 'zhTW', '我們應該擔心嗎？', '我們應該擔心嗎？', 25549),
(129372, 'zhTW', '這是什麼意思？', '這是什麼意思？', 25549),
(129371, 'zhTW', '我們向來與世隔絕，所以不太接觸外界的事物。不過我們跟部落有盟約，會提供前往其他城市或地區的途徑。\n\n你想去哪裡？', '我們向來與世隔絕，所以不太接觸外界的事物。不過我們跟部落有盟約，會提供前往其他城市或地區的途徑。\n\n你想去哪裡？', 25549),
(129370, 'zhTW', '有什麼最新的消息嗎？', '有什麼最新的消息嗎？', 25549),
(129369, 'zhTW', '我們只是想要一個答案。', '我們只是想要一個答案。', 25549),
(129368, 'zhTW', '要是真的出事怎麼辦？', '要是真的出事怎麼辦？', 25549),
(129367, 'zhTW', '發生什麼事了？有我們不知道的事嗎？', '發生什麼事了？有我們不知道的事嗎？', 25549),
(129366, 'zhTW', '幽暗城或奧格瑪', '幽暗城或奧格瑪', 25549),
(129365, 'zhTW', '外域的地獄火半島', '外域的地獄火半島', 25549),
(129364, 'zhTW', '如果要去幽暗城然後再前往奧格瑪或卡林多，你需要使用位於日怒尖塔的傳送器。', '如果要去幽暗城然後再前往奧格瑪或卡林多，你需要使用位於日怒尖塔的傳送器。', 25549),
(129363, 'zhTW', '有個通往外域地獄火半島的傳送門。就在日怒尖塔。', '有個通往外域地獄火半島的傳送門。就在日怒尖塔。', 25549),
(129362, 'zhTW', '其他大陸', '其他大陸', 25549),
(129361, 'zhTW', '做得好，宗師！我們暫時…擋住敵人了。', '', 25549),
(129360, 'zhTW', '宗師！我聽說怒魔準備再度攻擊。請在他們開始行動之前，想辦法阻止他們！', '', 25549),
(129359, 'zhTW', '朋友，祝福你！武僧們欠你一份情。', '', 25549),
(129358, 'zhTW', '英雄，我聽說怒魔準備再度攻擊。請在他們開始行動之前，想辦法阻止他們！', '', 25549),
(129357, 'zhTW', '先知，你的力量讓我印象深刻，我相信你沒看錯桑德蘭。我願意對他效忠。', '', 25549),
(129356, 'zhTW', '先知，今日的風眷顧著你。我會考慮對桑德蘭效忠。', '', 25549),
(129355, 'zhTW', '看來準備工作都完成了。', '', 25549),
(129354, 'zhTW', '', '應該讓卡德加知道這件事。', 25549),
(129353, 'zhTW', '', '光靠創世之柱是沒有用的，只有團結一心、智勇兼備的軍隊才能阻止燃燒軍團。等你和你們的部隊準備好面對最後一戰，我的影像會回來幫忙。艾澤拉斯的命運就交給你們了。', 25549),
(129352, 'zhTW', '|TInterface\\ICONS\\Spell_Arcane_PortalDarnassus.blp20|t%s開始施放|cFFFF0404|Hspell:234676|h[扭曲反射]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t%s開始施放|cFFFF0404|Hspell:234423|h[吸取生命]|h|r！', 25549),
(129351, 'zhTW', '', '別放棄，還有希望。只要讓創世之柱各歸其位，就能修復結界，趕走入侵者。你們必須前往薩格拉斯之墓底層，在那裡使用阿曼蘇爾之眼。這樣一來就能平息魔化風暴，而燃燒軍團與艾澤拉斯之間的連結也會消失。', 25549),
(129350, 'zhTW', '', '我是提里斯法守護者艾格文，你們看到這個影像，就表示我為了保護墓地而設置的結界，已經失效了。果然沒錯，我感覺到燃燒軍團的首領，想盡辦法要得到這裡的東西。', 25549),
(129349, 'zhTW', '', '從前，這面盾為年輕的世界之魂抵擋瘋狂的攻擊和腐化。現在，它會成為捍衛艾澤拉斯的助力。', 25549),
(129348, 'zhTW', '', '這怎麼可能？守護者！', 25549),
(129347, 'zhTW', '這是什麼？', '', 25549),
(129346, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CURSEOFMANNOROTH.BLP:20|t%s開始施放|cFFFF0404|Hspell:236572|h[殲滅]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t%s開始施放|cFFFF0404|Hspell:234423|h[吸取生命]|h|r！', 25549),
(129345, 'zhTW', '', '這種粗糙的武器比不上鋒利的戰刃，不過應該能派上用場。', 25549),
(129344, 'zhTW', '', '盟友說他們在船艦上加裝了強大的武器。來試試看它們的威力吧！', 25549),
(129343, 'zhTW', '就剩你們了。', '', 25549),
(129342, 'zhTW', '天空就交給我，你們去拿盾！', '', 25549),
(129341, 'zhTW', '', '啊，死亡的冰冷擁抱。真暢快！', 25549),
(129340, 'zhTW', '', '伊利丹，要是不小心砍到你還真是抱歉。這裡這麼多惡魔，每個都長得跟你差不多。', 25549),
(129339, 'zhTW', '', '我們的死亡騎士放出了一群不死飛龍轟炸這裡。想加入嗎？', 25549),
(129338, 'zhTW', '讓它們來吧，我和瑪翼夫會守住下面的樓梯。', '', 25549),
(129337, 'zhTW', '我們失敗了。燃燒軍團擊潰防線，把我們逼出來。神盾只能靠你們保護了。燃燒軍團打過來了！', '', 25549),
(129336, 'zhTW', '', '議會派我來檢查新發現的灼痕。應該是最近才發生的事。', 25549),
(129335, 'zhTW', '', '$n，別太靠近。這地方剛剛遭受攻擊，還不安全。', 25549),
(129334, 'zhTW', '', '好極了！', 25549),
(129333, 'zhTW', '惡魔腐化在海岸蔓延。牧道會需要你的協助。', '', 25549),
(129332, 'zhTW', '', '丹密爾在等著你，死亡領主。準備讓死亡從天而降了嗎？', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129331, 'zhTW', '', '這些灼痕看起來很新。$n，在我們處理好之前別靠太近。我不想看你受傷。', 25549),
(129330, 'zhTW', '看到我稱號裡有「歷史學家」這四個字嗎？我必須維持某種低調的學者風華。$b$b但既然你誠心誠意發問了，我就大發慈悲告訴你，你所謂的無趣長袍可是微纖維多層疊紡做的，不但耐用、吸濕、防皺、防縮水，還有保護表層和自然殺菌功能，你看到這些絨毛嗎，這可是客製的精緻長袍。$b$b這樣你懂了嗎？$b$b附帶一提，看到我皮膚的光澤嗎？保濕效果也是一流的。', '', 25549),
(129329, 'zhTW', '', '這下應該就能暫時阻止他們的計畫了。謝謝你幫忙！', 25549),
(129328, 'zhTW', '', '燃燒軍團打算從這座營地攻擊我們的先祖。幫我們破壞他們的計畫！', 25549),
(129327, 'zhTW', '這樣就能阻止惡魔腐化在這個地方繼續擴散。', '', 25549),
(129326, 'zhTW', '', '我們的人已經在底層和燃燒軍團開戰了。趕快把盾放到塔裡，否則傷亡只會越來越慘重。', 25549),
(129325, 'zhTW', '惡魔腐化在海岸蔓延。接受我的贈禮，淨化這片土地。', '', 25549),
(129324, 'zhTW', '', '愚蠢的惡魔。它們就是學不會。它們別想打倒我們！', 25549),
(129323, 'zhTW', '', '惡魔打算要攻擊先祖！讓這群怪物知道，別跟大自然作對！', 25549),
(129322, 'zhTW', '請你解釋一下，以你對時尚的理解，為什麼會穿這麼無趣的長袍出門？', '請你解釋一下，以你對時尚的理解，為什麼會穿這麼無趣的長袍出門？', 25549),
(129321, 'zhTW', '只有讓這群惡魔看到將領冷冰冰的屍體，它們才會安靜下來。做得好！', '', 25549),
(129320, 'zhTW', '厄爾多瓦是燃燒軍團最殘暴的戰士，常常吹噓自己的戰績。殺了這個自大狂！', '', 25549),
(129319, 'zhTW', '做得好，要讓燃燒軍團知道，毀滅的命運是無法逃避的。', '', 25549),
(129318, 'zhTW', '卓薩諾斯混在納迦裡面。一定要把這個惡魔找出來殺了，如果有誰敢阻擋你，就一起殺掉！', '', 25549),
(129317, 'zhTW', '燃燒軍團讓牠愛上血肉的滋味。這種怪物還是殺了吧！', '', 25549),
(129316, 'zhTW', '空氣中有臭味代表恐怖潛獵者就在附近。如果想奪回聖殿，就得先殺掉這隻燃燒軍團的噁心寵物。', '', 25549),
(129315, 'zhTW', '貪婪的巨人就該有這種下場。做得好！', '', 25549),
(129314, 'zhTW', '做得太好了，戰鬥領主。我就知道你一定辦得到。', '', 25549),
(129313, 'zhTW', '薩格拉斯之墓的力量吸引來的不只是燃燒軍團。貪婪而強大的海巨人「藻拳」也想把聖殿裡的聖物據為己有。我們一定要阻止他！', '', 25549),
(129312, 'zhTW', '戰鬥領主！魔怒納迦和那些斯闊格走狗又在耍一樣的花招了。給他們一點顏色瞧瞧！', '', 25549),
(129311, 'zhTW', '傳說中的深齒凶殘無比。幸好我們也有傳說中的英雄來消滅這個威脅！', '', 25549),
(129310, 'zhTW', '燃燒軍團驚動了古老的多頭蛇「深齒」。殺死這隻怪物，千萬別讓牠有機會興風作浪。', '', 25549),
(129309, 'zhTW', '做得好，英雄。督軍達爾嘉一死，就能削弱納迦在這裡的勢力了。', '', 25549),
(129308, 'zhTW', '魔裔的魔法確實有…獨到之處。可惜他們加以濫用。這就是他們該有的下場。', '', 25549),
(129307, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t%s開始施放|cFFFF0404|Hspell:234423|h[吸取生命]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t%s開始施放|cFFFF0404|Hspell:234423|h[吸取生命]|h|r！', 25549),
(129306, 'zhTW', '潮石吸引了艾薩拉女王的狂熱追隨者，包括神出鬼沒的督軍達爾嘉。這是消滅他這個威脅的絕佳機會。', '', 25549),
(129305, 'zhTW', '', '做得好！這樣就能讓萊由好好安息了。', 25549),
(129304, 'zhTW', '', '萊由生前是個令人敬畏的戰士。現在卻變成和我們作對的恐怖怪物。讓他在墳墓裡安息吧。', 25549),
(129303, 'zhTW', '', '經過了這麼久，奈莎終於能夠安息了。我很感謝你。', 25549),
(129302, 'zhTW', '希望這是值得的。', '希望這是值得的。', 25549),
(129301, 'zhTW', '', '奈莎原本是我信任的朋友，為了守護聖殿犧牲生命。她的遺體遭到褻瀆，變成女妖在這裡徘徊不去。讓她從折磨中解脫吧！', 25549),
(129300, 'zhTW', '你不懂我要傳遞給你的珍貴訊息。這個哲理是多數人過完一輩子也不會發現的，$n。$b$b<嘆氣>聽好，重點是，別人會不斷以你的穿著來評判你，而你在得到我的研究與教導後，就能製造出會讓你鶴立雞群的傳說級物品。我們開始吧。', '', 25549),
(129299, 'zhTW', '', '太棒了！他們都被你迷得暈頭轉向！', 25549),
(129298, 'zhTW', '', '我們的盜賊需要一些協助來完成洞穴裡的任務。這些昏迷炸彈正好可以讓他們佔上風！', 25549),
(129297, 'zhTW', '伊利丹，你說得對，你我都曾是基爾加丹和燃燒軍團的手下敗將。但要是我們聯手，一定還有機會拯救艾澤拉斯，我敢保證！', '', 25549),
(129296, 'zhTW', '年輕人就是沉不住氣。$b$b工匠的價值完全在於他所打造的物品，說到底，你目前為止穿戴的那些垃圾，就是為什麼你看起來像個暴風城的會計而不是傳奇英雄的原因。$b$b你想想，如果有人為你作畫，你身上的衣服和護甲就會永垂不朽。這不正是你要的？', '', 25549),
(129295, 'zhTW', '基爾加丹追得我們在星際間不斷逃亡，但我們不想再逃了。絕對不能饒恕他對我們的世界…還有我兒子做過的事。', '', 25549),
(129294, 'zhTW', '我真希望我選了別的專業技能。', '我真希望我選了別的專業技能。', 25549),
(129293, 'zhTW', '', '剛才的爆炸效果應該比上一次好！瑟希斯會很滿意的。', 25549),
(129292, 'zhTW', '', '影尊，我們的密探發現這個洞穴已經被惡魔入侵。我們準備了適當的物品，你知道該怎麼做！', 25549),
(129291, 'zhTW', '大法師，魔裔在悲泣露臺囚禁法力刃豹。要是能救出來，這些魔法生物說不定會幫助我們！', '', 25549),
(129290, 'zhTW', '卡德加，你口氣很大，但想獲勝可不是光靠你逞一時之勇。你們聯盟和部落的軍隊在踏上破碎海岸前都很勇敢…卻慘遭燃燒軍團蹂躪。欺詐者會利用你們的恐懼和猜忌來對付你們。', '', 25549),
(129289, 'zhTW', '艾格文，我們會阻止基爾加丹。我們這次絕對不會失敗。', '', 25549),
(129288, 'zhTW', '', '精靈把這座聖殿蓋在具有古老力量的泰坦遺址上，我以為薩格拉斯的軀殼能安全存放在這裡。這個黑暗泰坦竟然利用手下，要以更強大的姿態重返這世界！', 25549),
(129287, 'zhTW', '你快說完了嗎？', '你快說完了嗎？', 25549),
(129286, 'zhTW', '', '太好了！對了，跟惡魔獵人一樣在空中飛的感覺怎麼樣啊，英雄？', 25549),
(129285, 'zhTW', '那都是細枝末節的事！想想你浪費了多少成就，多少才華！$b$b當然這不是你的錯，但你顯然太注重成效，不夠注意個人風格。幸好我發明了「錘鬚風格與品味系統」，只要有這個系統，你就能修正這些錯誤，你就有機會成為傳說。$b$b當然，這個過程會很辛苦。', '', 25549),
(129284, 'zhTW', '', '創世之柱都就定位了。先回永夜聖殿吧，我會告訴你們聖殿隱藏的秘密。', 25549),
(129283, 'zhTW', '', '英雄！我們的船需要動力，用能量核心吸取魔化噴泉的能量。這對破破爛爛的翅膀應該對你有幫助。可以在空中使用！', 25549),
(129282, 'zhTW', '我不知道他到底在說什麼，不過聽起來不大妙。他不是這禮拜第一個這樣的！', '', 25549),
(129281, 'zhTW', '你看我的手看得真仔細。', '你看我的手看得真仔細。', 25549),
(129280, 'zhTW', '你的雙手細瘦但是強大，剛硬但是靈巧。你應該完全信任這雙手絕對打造得出足以配得上英雄的衣物和護甲。$b$b我們小時候讀過的故事和傳說，往往不太重視法術和武器，但卻在英雄的服飾上大肆著墨！這也是為什麼這些故事到現在還能流傳。$b$b很多人不知道這個道理，但是你現在知道了！', '', 25549),
(129279, 'zhTW', '嘿，嘿！來吧！進來就別想那麼多，準備好再回到崗位確保我們還能見到明天的太陽。', '', 25549),
(129278, 'zhTW', '喂，你！啊，當我沒說。我們以為你也是…呃…那種人。', '', 25549),
(129277, 'zhTW', '', '這些純淨美麗的淚水是這個美好世界的夢想。現在，它會淨化你們的心靈，迎向未來的戰鬥。', 25549),
(129276, 'zhTW', '', '這個潮石是河流和大海的源頭，是艾澤拉斯的生命起源。現在，它要用來洗淨傷害這個世界的黑暗。', 25549),
(129275, 'zhTW', '', '英雄，我的影像只能指引你們到這裡了。生前，我什麼事都是一肩扛起，自負的代價太大了。你們一定要團結一心，才有可能擊敗黑暗勢力。再會了。', 25549),
(129274, 'zhTW', '噢噢。', '噢噢。', 25549),
(129273, 'zhTW', '我這個具有專利的錘鬚風格與品味系統是時尚的自然哲學。它在經過我親自精細研究、改良與測試之後，現在將用來做為你所有課程的理論基礎。$b$b前途充滿了危險，$n，但是豐碩的獎勵也遠超過你目前所能想像！', '', 25549),
(129272, 'zhTW', '', '這把錘子曾經造就古老的世界奇觀，具有改變世界的力量。現在我們用它來對抗命運，阻止末日到來。', 25549),
(129271, 'zhTW', '外面的人狀況還好嗎？', '', 25549),
(129270, 'zhTW', '外面發生什麼事，有任何消息嗎？', '', 25549),
(129269, 'zhTW', '有關於天空的消息嗎，$n？', '', 25549),
(129268, 'zhTW', '很少人能理解我為什麼要利用納迦取得薩格拉斯之眼。這是必要的策略，只有這樣才能保護艾澤拉斯。別讓任何人，干擾我們必須做的事！', '', 25549),
(129267, 'zhTW', '準備應戰。困在這裡的靈魂或許不太友善…應該說還沒放下…', '', 25549),
(129266, 'zhTW', '我已經很久沒踏進這座聖殿了。我做了該做的事，但也付出慘痛的代價。', '', 25549),
(129265, 'zhTW', '朋友，先喘口氣，恢復體力。接下來還有很多考驗。', '', 25549),
(129264, 'zhTW', '英雄，繼續前進，用創世之柱解開結界。千萬不能讓燃燒軍團拿到薩格拉斯的化身。', '', 25549),
(129263, 'zhTW', '那我們動作要快。', '', 25549),
(129262, 'zhTW', '你好，$n。你在破碎群島的事蹟已經在暴風城傳開了。你為聯盟帶來了莫大的榮耀。', '', 25549),
(129261, 'zhTW', '', '我能感覺到燃燒軍團想讓薩格拉斯的化身復甦。如果基爾加丹能在那個軀殼裡，注入黑暗泰坦的力量。這個世界恐怕沒有任何事物能擋得住他了。', 25549),
(129260, 'zhTW', '', '商店和銀行有好多人不停來來去去，到底發生了什麼事？我開始緊張了。', 25549),
(129259, 'zhTW', '', '有人要吃糕餅嗎？發生壞事的時候，只要吃點新鮮美味的點心就能振作起來。', 25549),
(129258, 'zhTW', '', '$n，我在這裡！如果你聽到最新消息，請讓我知道。打包貨物會佔用我很多時間。', 25549),
(129257, 'zhTW', '告訴我吧。', '告訴我吧。', 25549),
(129256, 'zhTW', '', '你們如果現在想下去，就會被我的結界擋住。每個結界都需要一個創世之柱才能解開。小心，惡魔一定會想盡辦法阻止你們前進。', 25549),
(129255, 'zhTW', '', '為了防止所有入侵者進入聖殿的深處，我把聖殿的每一層都封起來了。但我從來沒想到燃燒軍團還是有辦法闖進最底層。', 25549),
(129254, 'zhTW', '', '做好準備總沒錯，$n。只要一點代價，就能帶走我的貨物。', 25549),
(129253, 'zhTW', '我老實告訴你，$n，你到目前為止所學到的專業技能都非常淺顯。毫無挑戰、粗淺、低級而且俗氣！$b$b聽好，我不只是研究時尚歷史的學者，年輕人，我還是哲學家，而且不諱言地說，在這些領域裡面我更是大家的時尚指標。', '', 25549),
(129252, 'zhTW', '', '$n，準備得怎麼樣了？你的盟友狀況好像不太好。', 25549),
(129251, 'zhTW', '守護者艾格文的影像出現了，就像先前在聖殿那樣。', '', 25549),
(129250, 'zhTW', '燃燒軍團這次帶了新的惡魔過來。不知道它們流出來的血是什麼顏色。', '', 25549),
(129249, 'zhTW', '一個都別放過！如果失敗，艾澤拉斯就完了。', '', 25549),
(129248, 'zhTW', '快，加把勁！一定要攻進去！', '', 25549),
(129247, 'zhTW', '', '$n，天色暗了。希望你準備好了。', 25549),
(129246, 'zhTW', '我知道在這種時候很難放鬆，不過請盡量放寬心，沉醉在神秘和驚奇的世界當中吧！', '', 25549),
(129245, 'zhTW', '$n，歡迎光臨！我們只有一條規則：保持樂觀！別讓外面的騷亂影響你的心情。', '', 25549),
(129244, 'zhTW', '玩點玩具，最能轉移注意力了。隨意逛逛吧！', '', 25549),
(129243, 'zhTW', '', '$n，快進來！進來就別再擔心了。守衛跟我們保證過，一切都會沒事的。', 25549),
(129242, 'zhTW', '你好，$n。', '', 25549),
(129241, 'zhTW', '', '嗯？哪有什麼問題？走開啦！', 25549),
(129240, 'zhTW', '', '我會把這些都儲存起來。再次謝謝你，斬魔者！', 25549),
(129239, 'zhTW', '', '斬魔者，魔錘號的能量快用完了。薩格拉斯之墓周圍的魔化能量可以幫我們充能。站到魔化噴泉上，利用它的力量上去。', 25549),
(129238, 'zhTW', '奧格瑪或東部王國', '奧格瑪或東部王國', 25549),
(129237, 'zhTW', '外域的地獄火半島', '外域的地獄火半島', 25549),
(129236, 'zhTW', '在莫高雷這裡，旅行的方式很有限，但我會盡力幫助你。\n\n你要去哪？', '在莫高雷這裡，旅行的方式很有限，但我會盡力幫助你。\n\n你要去哪？', 25549),
(129235, 'zhTW', '其他大陸', '其他大陸', 25549),
(129234, 'zhTW', '靈魂高地下方的洞穴裡有個通往外域地獄火半島那片荒蕪之地的傳送門。', '靈魂高地下方的洞穴裡有個通往外域地獄火半島那片荒蕪之地的傳送門。', 25549),
(129233, 'zhTW', '在達納蘇斯的月神殿內有個能通往地獄火半島的傳送門。按照我的指示進入前往達納蘇斯的傳送門。等你到了，可以問那裡的哨兵怎麼去月神殿。', '在達納蘇斯的月神殿內有個能通往地獄火半島的傳送門。按照我的指示進入前往達納蘇斯的傳送門。等你到了，可以問那裡的哨兵怎麼去月神殿。', 25549),
(129232, 'zhTW', '可以建造虛空干擾裝置了。快捐出你的補給品。', '可以建造虛空干擾裝置了。快捐出你的補給品。', 25549),
(129231, 'zhTW', '虛空干擾裝置受到攻擊！無法讓我們使用了！', '虛空干擾裝置受到攻擊！無法讓我們使用了！', 25549),
(129230, 'zhTW', '虛空干擾裝置建造完成！你可以開始使用了。', '虛空干擾裝置建造完成！你可以開始使用了。', 25549),
(129229, 'zhTW', '可以建造指揮所了。快捐出你們的補給品。', '可以建造指揮所了。快捐出你的補給品。', 25549),
(129228, 'zhTW', '指揮所受到攻擊！無法讓我們使用了！', '指揮所受到攻擊！無法讓我們使用了！', 25549),
(129227, 'zhTW', '指揮所建造完成！你可以開始使用了。', '指揮所建造完成！你可以開始使用了。', 25549),
(129226, 'zhTW', '外域的地獄火半島', '外域的地獄火半島', 25549),
(129225, 'zhTW', '東部王國的暴風城', '東部王國的暴風城', 25549),
(129224, 'zhTW', '其他大陸', '其他大陸', 25549),
(129223, 'zhTW', '如果要前往外域的地獄火半島那片荒蕪之地，可以從月神殿內的傳送門過去。', '如果要前往外域的地獄火半島那片荒蕪之地，可以從月神殿內的傳送門過去。', 25549),
(129222, 'zhTW', '艾克索達，德萊尼的太空船與家園。前往艾克索達的傳送門就在月神殿內。', '艾克索達，德萊尼的太空船與家園。前往艾克索達的傳送門就在月神殿內。', 25549),
(129221, 'zhTW', '開往艾克索達的船就在西邊的碼頭。', '開往艾克索達的船就在西邊的碼頭。', 25549),
(129220, 'zhTW', '艾克索達', '艾克索達', 25549),
(129219, 'zhTW', '開往暴風城的船就在南邊的碼頭。', '開往暴風城的船就在南邊的碼頭。', 25549),
(129218, 'zhTW', '要去暴風城的話，你必須先到城裡使用傳送門去魯瑟蘭村。抵達泰達希爾底部之後，再去南邊的碼頭搭船。', '要去暴風城的話，你必須先到城裡使用傳送門去魯瑟蘭村。抵達泰達希爾底部之後，再去南邊的碼頭搭船。', 25549),
(129217, 'zhTW', '我們在島上的生活，要仰賴大海和魔法之力才能存活。\n\n你打算去哪裡？', '我們在島上的生活，要仰賴大海和魔法之力才能存活。\n\n你打算去哪裡？', 25549),
(129216, 'zhTW', '', '我設好鐐銬了，英雄！讓惡魔踏進來，就可以消滅它！', 25549),
(129215, 'zhTW', '', '為接下來的戰鬥磨利戰刃！伊利達瑞必定獲勝！', 25549),
(129214, 'zhTW', '', '有斬魔者帶領我們，一定能擊敗燃燒軍團！現在花一點時間慶祝我們的成就吧！', 25549),
(129213, 'zhTW', '吉恩和費倫似乎在談論我，不過我聽不太清楚…', '', 25549),
(129212, 'zhTW', '我們聲音要放低，裝得自然一點，否則會被聽到我們在交談…', '', 25549),
(129211, 'zhTW', '暴風城和其他聯盟主城', '暴風城和其他聯盟主城', 25549),
(129210, 'zhTW', '北裂境的凜風峽灣', '北裂境的凜風峽灣', 25549),
(129209, 'zhTW', '外域的地獄火半島', '外域的地獄火半島', 25549),
(129208, 'zhTW', '鐵爐堡不像暴風城一樣有港口，但交通還是滿方便的，可以通往其他大陸。\n\n你想去哪？', '鐵爐堡不像暴風城一樣有港口，但交通還是滿方便的，可以通往其他大陸。\n\n你想去哪？', 25549),
(129207, 'zhTW', '我準備好要作戰了。', '我準備好要作戰了。', 25549),
(129206, 'zhTW', '你跟瑪加薩一起來的？我就知道她會來救我們。', '你跟瑪加薩一起來的？我就知道她會來救我們。', 25549),
(129205, 'zhTW', '請接受我的謝意和我的釘錘。', '請接受我的謝意和我的釘錘。', 25549),
(129204, 'zhTW', '復仇的時刻到了。', '復仇的時刻到了。', 25549),
(129203, 'zhTW', '', '我想我應該去看看魔錘號修復得怎麼樣了。到時候見了，斬魔者。', 25549),
(129202, 'zhTW', '你說北裂境的凜風峽灣？那可遠了。去找格萊斯‧瑟登，他是獅鷲獸管理員，可以幫你安排去米奈希爾港的行程。然後北矛號會由米奈希爾港出發，前往瓦爾加德。', '你說北裂境的凜風峽灣？那可遠了。去找格萊斯‧瑟登，他是獅鷲獸管理員，可以幫你安排去米奈希爾港的行程。然後北矛號會由米奈希爾港出發，前往瓦爾加德。', 25549),
(129201, 'zhTW', '這就是你的世界末日！', '', 25549),
(129200, 'zhTW', '你逃不掉的！我們的力量無遠弗屆！', '', 25549),
(129199, 'zhTW', '等到薩格拉斯全面掌控你的世界之後，再來享受心痛的感覺吧！', '', 25549),
(129198, 'zhTW', '脆弱的白骨和血肉…你根本比不上燃燒軍團的力量！', '', 25549),
(129197, 'zhTW', '喔，地獄火半島…那個遠在外域，被燒成廢土的地方。總之，那群法師已經幫你開好傳送門了，可以把你送到秘法區的秘法大廳。', '喔，地獄火半島…那個遠在外域，被燒成廢土的地方。總之，那群法師已經幫你開好傳送門了，可以把你送到秘法區的秘法大廳。', 25549),
(129196, 'zhTW', '你的世界會完全瓦解，凡人。沒人能阻止我們！', '', 25549),
(129195, 'zhTW', '弱小的凡人，向燃燒軍團的力量屈服吧！', '', 25549),
(129194, 'zhTW', '其他大陸', '其他大陸', 25549),
(129193, 'zhTW', '我恨你…', '', 25549),
(129192, 'zhTW', '', '那個會發光的東西？我弄丟了。', 25549),
(129191, 'zhTW', '真的嗎？！只要把束縛裂片交給我，法術就會解除了！', '', 25549),
(129190, 'zhTW', '', '好啊！要怎麼做？', 25549),
(129189, 'zhTW', '你到底要不要放我走？', '', 25549),
(129188, 'zhTW', '好啊。就下星期。', '', 25549),
(129187, 'zhTW', '', '所以…是下星期？', 25549),
(129186, 'zhTW', '我在遠古時代在虛空的最深處被賦予這個悲慘的生命。', '', 25549),
(129185, 'zhTW', '', '喂，伊克斯睿吉。你的生日是什麼時候？我們應該來辦派對！', 25549),
(129184, 'zhTW', '永遠飄在笨蛋哥布林設置的牢房裡？好玩得不得了…', '', 25549),
(129183, 'zhTW', '', '一直飄浮在半空中好像很好玩。', 25549),
(129182, 'zhTW', '', '我猜答案是會。', 25549),
(129181, 'zhTW', '你敢靠近我，我就咬掉你的手。', '', 25549),
(129180, 'zhTW', '', '惡魔會怕癢嗎？', 25549),
(129179, 'zhTW', '東部王國的銀月城', '東部王國的銀月城', 25549),
(129178, 'zhTW', '卡林多的奧格瑪', '卡林多的奧格瑪', 25549),
(129177, 'zhTW', '北裂境的凜風峽灣', '北裂境的凜風峽灣', 25549),
(129176, 'zhTW', '外域的地獄火半島', '外域的地獄火半島', 25549),
(129175, 'zhTW', '東部王國的荊棘谷', '東部王國的荊棘谷', 25549),
(129174, 'zhTW', '會法術的人開啟了通往外域地獄火半島的傳送門。傳送門就在法師區。', '會法術的人開啟了通往外域地獄火半島的傳送門。傳送門就在法師區。', 25549),
(129173, 'zhTW', '閃閃發光的精靈會在幽暗城上方的廢墟設置球狀傳送器。碰觸它，你就能前往他們的家園銀月城。', '閃閃發光的精靈會在幽暗城上方的廢墟設置球狀傳送器。碰觸它，你就能前往他們的家園銀月城。', 25549),
(129172, 'zhTW', '米菲會帶你前往寒冷的北裂境。她的熱氣球會從位在羅德隆廢墟北邊的左塔升空。你要去凜風峽灣的復仇要塞對付維酷人。', '米菲會帶你前往寒冷的北裂境。她的熱氣球會從位在羅德隆廢墟北邊的左塔升空。你要去凜風峽灣的復仇要塞對付維酷人。', 25549),
(129171, 'zhTW', '不知道。', '', 25549),
(129170, 'zhTW', '', '其實你根本不知道它的用途，對吧？', 25549),
(129169, 'zhTW', '這是很久之前就因為秘密原因而被秘密保守者所保守的秘密。', '', 25549),
(129168, 'zhTW', '', '為什麼你這麼喜歡虛空裂片？', 25549),
(129167, 'zhTW', '', '$n，外頭狀況如何？有那麼多顧客上門，我處理訂單就快忙不過來了。希望一切都平安。', 25549),
(129166, 'zhTW', '', '我們的顧客喜歡這間店的商品。我有信心等時間一到，他們絕對會毫不猶豫…喔，$n，歡迎光臨。', 25549),
(129165, 'zhTW', '', '伊克斯，不要杞人憂天。猜測是沒有意義的。振作一點，有客人上門了。', 25549),
(129164, 'zhTW', '戰爭讓我心力交瘁，我甚至連哀悼的時間都沒有。', '', 25549),
(129163, 'zhTW', '父親的紀念碑移到雄獅陵園後，我就不曾踏進這裡了。', '', 25549),
(129162, 'zhTW', '這裡能釣的都釣光了，但現在在打仗，離開城市實在太危險了。', '', 25549),
(129161, 'zhTW', '奧格瑪是部落中樞，交通發達，可以到艾澤拉斯各處，甚至艾澤拉斯以外的地方。\n\n你想去哪裡？', '奧格瑪是部落中樞，交通發達，可以到艾澤拉斯各處，甚至艾澤拉斯以外的地方。\n\n你想去哪裡？', 25549),
(129160, 'zhTW', '詛咒之地和德拉諾傳送門', '詛咒之地和德拉諾傳送門', 25549),
(129159, 'zhTW', '外域的地獄火半島', '外域的地獄火半島', 25549),
(129158, 'zhTW', '因為大災變出現的區域', '因為大災變出現的區域', 25549),
(129157, 'zhTW', '破碎群島上方的達拉然', '破碎群島上方的達拉然', 25549),
(129156, 'zhTW', '潘達利亞的甘露村', '潘達利亞的甘露村', 25549),
(129155, 'zhTW', '東部王國的荊棘谷', '東部王國的荊棘谷', 25549),
(129154, 'zhTW', '莫高雷的雷霆崖', '莫高雷的雷霆崖', 25549),
(129153, 'zhTW', '北裂境的北風凍原', '北裂境的北風凍原', 25549),
(129152, 'zhTW', '東部王國的幽暗城或銀月城', '東部王國的幽暗城或銀月城', 25549),
(129151, 'zhTW', '我們在潘達利亞的盟友讓我們在翠玉林的甘露村設置了傳送門。它位於榮譽谷中央。', '我們在潘達利亞的盟友讓我們在翠玉林的甘露村設置了傳送門。它位於榮譽谷中央。', 25549),
(129150, 'zhTW', '祈倫托在暗影裂口設置了傳送門，幫助玩家前往破碎群島上方的達拉然。', '祈倫托在暗影裂口設置了傳送門，幫助玩家前往破碎群島上方的達拉然。', 25549),
(129149, 'zhTW', '%s收起他的武器。', '', 25549),
(129148, 'zhTW', '不要動！啊！這種事到底還要發生多少次？先是守衛過來確認一切都沒事，現在又是你…唉，選擇不多，但你還是隨意看看吧。', '', 25549),
(129147, 'zhTW', '把手放在我看得見的地方！啊！又是你啊。我最近常常要趕跑無賴，已經不知道該怎麼辦才好了。', '', 25549),
(129146, 'zhTW', '我們的法師在暗影裂口開啟了傳送門，讓玩家可以先去詛咒之地，然後再前往德拉諾。', '我們的法師在暗影裂口開啟了傳送門，讓玩家可以先去詛咒之地，然後再前往德拉諾。', 25549),
(129145, 'zhTW', '站住別動！喔，$n，是你嗎？這裡整天都有該死的盜匪出沒！請隨意看看，不過動作要快。', '', 25549),
(129144, 'zhTW', '有個通往外域地獄火半島的傳送門。就在奧格瑪底下的暗影裂口。', '有個通往外域地獄火半島的傳送門。就在奧格瑪底下的暗影裂口。', 25549),
(129143, 'zhTW', '', '等一下！等一下！$n，有最新消息嗎？這裡有不少人都很擔心。', 25549),
(129142, 'zhTW', '', '$n，抱歉打擾你，你有聽說什麼消息嗎？我看到守衛跑來跑去的，可是他們都不願意說什麼。', 25549),
(129141, 'zhTW', '', '$n，過來這裡！有新的消息嗎？我聽到的不多，但這附近有些人行為變得怪怪的。', 25549),
(129140, 'zhTW', '就算走在熟悉的街道上，我還是覺得無所適從。', '', 25549),
(129139, 'zhTW', '暴風城一直都是我的家。我對這裡的商店和街道熟到不能再熟了。', '', 25549),
(129138, 'zhTW', '如果要去北裂境的北風凍原，就要搭強風號這艘飛艇。去西飛艇塔找格利伯‧瑞姆洛基，問問看什麼時候會去戰歌堡。', '如果要去北裂境的北風凍原，就要搭強風號這艘飛艇。去西飛艇塔找格利伯‧瑞姆洛基，問問看什麼時候會去戰歌堡。', 25549),
(129137, 'zhTW', '街道的氣氛變得和天空一樣灰暗，但希望還是能照亮所有人。', '', 25549),
(129136, 'zhTW', '去奧格瑪中央高原上的西飛艇塔找思娜克·迅扣。她是荊棘谷的飛艇管理員，會告訴你什麼時候有飛艇前往我們在東部王國南邊的格羅姆高營地。', '去奧格瑪中央高原上的西飛艇塔找思娜克·迅扣。她是荊棘谷的飛艇管理員，會告訴你什麼時候有飛艇前往我們在東部王國南邊的格羅姆高營地。', 25549),
(129135, 'zhTW', '如果要去幽暗城或銀月城，就要去奧格瑪中央高原上的東飛艇塔找弗雷薩。他會告訴你什麼時候會有飛艇去提里斯法林地的布瑞爾，它位於幽暗城的北邊。在幽暗城的入口處有個可以去銀月城的傳送器。', '如果要去幽暗城或銀月城，就要去奧格瑪中央高原上的東飛艇塔找弗雷薩。他會告訴你什麼時候會有飛艇去提里斯法林地的布瑞爾，它位於幽暗城的北邊。在幽暗城的入口處有個可以去銀月城的傳送器。', 25549),
(129134, 'zhTW', '如果要去卡林多中部的雷霆崖，就要去奧格瑪中央高原上的西飛艇塔搭乘飛艇。去那裡找飛艇管理員齊里‧熱噴嘴，就能得到更多資訊。', '如果要去卡林多中部的雷霆崖，就要去奧格瑪中央高原上的西飛艇塔搭乘飛艇。去那裡找飛艇管理員齊里‧熱噴嘴，就能得到更多資訊。', 25549),
(129133, 'zhTW', '$n，風帶給我們不少消息。這陣子你感應到什麼了嗎？', '', 25549),
(129132, 'zhTW', '別讓其他人的行為影響你。面對未知的狀況，我們一定要沉著冷靜。', '', 25549),
(129131, 'zhTW', '別讓其他人影響到你。面對未知的狀況，我們一定要沉著冷靜。', '', 25549),
(129130, 'zhTW', '記住，急著下結論的人會第一個獲得解答，但得到的解答可能只會讓人痛苦。', '', 25549),
(129125, 'zhTW', '', '|TInterface\\Icons\\inv_misc_horn_03:20|t%s |cFFFF0000|Hspell:237937|h[強化]|h|r她所有的議會成員！', 25549),
(129124, 'zhTW', '', '|TInterface\\Icons\\inv_misc_horn_03:20|t%s |cFFFF0000|Hspell:237937|h[強化]|h|r自己和她的一名盟友！', 25549),
(129123, 'zhTW', '', '|TInterface\\Icons\\inv_misc_horn_03:20|t%s |cFFFF0000|Hspell:237937|h[強化]|h|r$n！', 25549),
(129122, 'zhTW', '有生還者！我們會守住這裡，你必須在燃燒軍團發現以前搶先找到他們。', '', 25549),
(129121, 'zhTW', '這種東西要是再來一個，我們就撐不住了。必須重整部隊。', '', 25549),
(129120, 'zhTW', '在這裡殺掉惡魔，它們就不能復活。全力攻擊。', '', 25549),
(129118, 'zhTW', '惡魔在蠢蠢欲動。', '', 25549),
(129117, 'zhTW', '我們這裡支撐不了多久。', '', 25549),
(129115, 'zhTW', '這個術士會解讀敵人的魔法，確實幫了我們很大的忙。\n\n他也好幾次差點害死我們，不過這個風險在我決定跟這傢伙合作時就知道了。\n\n雖然他有他的缺點，但是他也好幾次救過我的命。不管是好是壞，我們都會一起努力奮戰到最後。', '', 25549),
(129114, 'zhTW', '聽好，傳送門不會自己改變目的地。我需要時間才能把它弄好，免得你出現在燃燒軍團的熔爐或是深淵領主的肚子裡。\n\n你想傳送到深淵領主的肚子裡嗎？喔，或許一開始你會以為這是很高明的襲擊方式，但是等到惡魔的胃液開始消化你的時候，你就會悔不當初了。\n\n不要打擾我工作。', '', 25549),
(129113, 'zhTW', '艾澤拉斯的英雄，每個職業組織在經過破碎群島戰役之後都變得相當強大。現在，我們需要大家拿出力量和勇氣。團結一致，把燃燒軍團趕出艾澤拉斯的時候到了！', '', 25549),
(129112, 'zhTW', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t其中一個符文|cFFFF0000|Hspell:237908|h[引爆]|h|r了！', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t其中一個符文|cFFFF0000|Hspell:237908|h[引爆]|h|r了！', 25549),
(129111, 'zhTW', '因為大災變出現的區域', '因為大災變出現的區域', 25549),
(129110, 'zhTW', '北裂境的北風凍原', '北裂境的北風凍原', 25549),
(129109, 'zhTW', '卡林多的泰達希爾或艾克索達', '卡林多的泰達希爾或艾克索達', 25549),
(129108, 'zhTW', '詛咒之地和德拉諾傳送門', '詛咒之地和德拉諾傳送門', 25549),
(129107, 'zhTW', '外域的地獄火半島', '外域的地獄火半島', 25549),
(129106, 'zhTW', '破碎群島上方的達拉然', '破碎群島上方的達拉然', 25549),
(129105, 'zhTW', '潘達利亞的坡東村', '潘達利亞的坡東村', 25549),
(129104, 'zhTW', '鐵爐堡', '鐵爐堡', 25549),
(129103, 'zhTW', '燃燒軍團會消滅你…', '', 25549),
(129102, 'zhTW', '補給品是燃燒軍團的！', '', 25549),
(129100, 'zhTW', '死亡騎士，你這種行為讓人很難把你當盟友。', '', 25549),
(129099, 'zhTW', '死亡使者，那個東西你找不到的。總之這座神殿不歡迎你，滾吧！', '', 25549),
(129098, 'zhTW', '我不知道你在說什麼。如果你沒有其他事的話，我要先去忙了。有問題就找管理者說吧。', '', 25549),
(129097, 'zhTW', '聽說在寒冰皇冠北方，曾經有一條偉大的龍在冰河倒下，你知道些什麼嗎？', '聽說在寒冰皇冠北方，曾經有一條偉大的龍在冰河倒下，你知道些什麼嗎？', 25549),
(129096, 'zhTW', '你竟敢把不死惡臭帶進生命神殿，早點滾出去。', '', 25549),
(129095, 'zhTW', '暴風城是聯盟中樞，交通發達，可以到艾澤拉斯各處，甚至艾澤拉斯以外的地方。\n\n你想去哪裡？', '暴風城是聯盟中樞，交通發達，可以到艾澤拉斯各處，甚至艾澤拉斯以外的地方。\n\n你想去哪裡？', 25549),
(129094, 'zhTW', '如果想去鐵爐堡，搭礦道地鐵是最快的方法了。你可以在矮人區找到地鐵入口。', '如果想去鐵爐堡，搭礦道地鐵是最快的方法了。你可以在矮人區找到地鐵入口。', 25549),
(129092, 'zhTW', '我們在潘達利亞的新盟友讓我們在翠玉林的坡東村裡設了傳送門。你可以從暴風要塞附近的湖泊西岸找到傳送門。', '我們在潘達利亞的新盟友讓我們在翠玉林的坡東村裡設了傳送門。你可以從暴風要塞附近的湖泊西岸找到傳送門。', 25549),
(129091, 'zhTW', '你很幸運，達拉然目前位於破碎群島上方，而且祈倫托在暴風要塞中設置了傳送門。', '你很幸運，達拉然目前位於破碎群島上方，而且祈倫托在暴風要塞中設置了傳送門。', 25549),
(129090, 'zhTW', '你想怎麼評斷阿薩斯都無所謂，但你得承認，這位前巫妖王對付燃燒軍團的確有一套。', '', 25549),
(129089, 'zhTW', '有個能通往外域地獄火半島的傳送門。它位在法師塔最上方的巫師聖所。', '有個能通往外域地獄火半島的傳送門。它位在法師塔最上方的巫師聖所。', 25549),
(129088, 'zhTW', '法師在法師塔中開啟了傳送門，協助玩家前往詛咒之地然後進入德拉諾。你會看到法師亮火站在傳送門旁邊。', '法師在法師塔中開啟了傳送門，協助玩家前往詛咒之地然後進入德拉諾。你會看到法師亮火站在傳送門旁邊。', 25549),
(129087, 'zhTW', '能離開亞榭洛，用新鮮的屍體和骸骨堆土法煉鋼進行研究，感覺真好。', '', 25549),
(129086, 'zhTW', '如果燃燒軍團使用的是這種類型的死靈法術，那我們就有對付他們的希望了。', '', 25549),
(129085, 'zhTW', '如果要去卡林多的艾克索達或泰達希爾，就去找奈攸拉吧。她是勇氣號的碼頭管理員，就在暴風港最南端的碼頭。', '如果要去卡林多的艾克索達或泰達希爾，就去找奈攸拉吧。她是勇氣號的碼頭管理員，就在暴風港最南端的碼頭。', 25549),
(129084, 'zhTW', '要前往北裂境的話，就去找莉夏‧坦稜拜，她是海怪號的碼頭管理員。在暴風港的北端碼頭搭乘海怪號可以前往北風凍原的驍勇要塞。', '要前往北裂境的話，就去找莉夏‧坦稜拜，她是海怪號的碼頭管理員。在暴風港的北端碼頭搭乘海怪號可以前往北風凍原的驍勇要塞。', 25549),
(129083, 'zhTW', '', '很抱歉，我有點緊張。歡迎光臨我的店。', 25549),
(129082, 'zhTW', '哪種協助？', '哪種協助？', 25549),
(129081, 'zhTW', '克塔，我相信議會早有萬全的準備。振作一點，有客人上門了。', '', 25549),
(129080, 'zhTW', '進來吧！我跟克塔正在聊最近發生的事情。我想知道你有什麼看法。', '', 25549),
(129079, 'zhTW', '歡迎光臨。這陣子我們的存貨不太夠。自從…最近的狀況發生，我們就忙著供貨，沒有間斷過。', '', 25549),
(129078, 'zhTW', '不，克塔，我不覺得有什麼好擔心的。專心點，別讓客人等太久。', '', 25549),
(129077, 'zhTW', '旅行者，歡迎光臨！外面的狀況如何？', '', 25549),
(129076, 'zhTW', '燃燒軍團還想繼續製造他們的傑作，天譴軍團。\n\n這任務交給了懂得利用屍骸造出傀儡僕從的納斯雷茲姆。\n\n而他們則找上了這些墮落的靈行者，因為他們熟悉這一類的魔法。\n\n我為黯刃騎士團而來，負責觀察和做出必要的決斷。並且在你需要的時候提供協助，英雄。', '', 25549),
(129075, 'zhTW', '只要不抬頭看，就沒有任何問題。慢慢逛！', '', 25549),
(129074, 'zhTW', '朋友，別多管閒事。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129073, 'zhTW', '$n，末日要到了！至少大家都這麼說。至少還有時間打扮一下。', '', 25549),
(129072, 'zhTW', '你或許不以為然，但我可不要穿著平凡的法師裝束就去見造物主。', '', 25549),
(129071, 'zhTW', '我絕對不當燃燒軍團的工具。', '', 25549),
(129070, 'zhTW', '末日就該打扮時尚，花多少錢都無所謂。我的錢全花光了…反正很快就無所謂了。', '', 25549),
(129069, 'zhTW', '我…我自由了。謝謝你。', '', 25549),
(129068, 'zhTW', '$n，是什麼風把$c給吹來了？想不想在世界毀滅之前換一套光鮮亮麗的衣服啊？', '', 25549),
(129067, 'zhTW', '兄弟，只有靠自己才能擺脫痛苦。別放棄！', '', 25549),
(129066, 'zhTW', '啊，$n。我正想找你這個$c呢。你喜歡我的新裝扮嗎？欸，我到底在想什麼？反正很快就沒有意義了。', '', 25549),
(129065, 'zhTW', '朋友，別被腐化了！', '', 25549),
(129064, 'zhTW', '兄弟，好好睡吧…你辛苦了。', '', 25549),
(129063, 'zhTW', '建議你丟掉那身破布，換成更時髦的打扮。迎接末日的時候，還是穿得好看一點吧。', '', 25549),
(129062, 'zhTW', '有東西在裡面作怪！可憐的小兔子…我得幫牠們！', '', 25549),
(129061, 'zhTW', '我們得先解決那個惡魔，再對付厄德里斯！', '', 25549),
(129060, 'zhTW', '大人，別擔心。我能喚醒更多士兵。', '', 25549),
(129059, 'zhTW', '我的士兵還沒復原，惡魔就開始攻擊了！', '', 25549),
(129058, 'zhTW', '', '怎麼搞的，我的雞怎麼了？', 25549),
(129057, 'zhTW', '…說到這個，就必須順便談談那五大浮冰：北方浮冰、南方浮冰、東方浮冰、西方非典型冰河小浮冰，說到這個，我又想到…', '', 25549),
(129056, 'zhTW', '', '他頭撞得可不輕啊。但斬魔者很堅強的，孩子。你看！', 25549),
(129055, 'zhTW', '', '斬魔者昏迷很久了。我擔心萬一…', 25549),
(129054, 'zhTW', '如果依照生成次序說明環繞在大型北方冰河周圍的其他冰河，有中型東北方冰河、小型南方冰河、極小型西南方冰河、極小型西南南冰河、極小型東南南冰河、極小型最南方冰河，當然還有極小型北方飄忽不定一號冰河和二號冰河…', '', 25549),
(129053, 'zhTW', '好好！我說！在寒冰皇冠北方…有很大的…冰河…那些東西多年前就隨著冰河漂走了…我知道的就這些了，真的！還有問題就去問…去問泰瑞歐！', '', 25549),
(129052, 'zhTW', '<崔瑟姆瞇起眼睛看著你。>\n\n像你這樣的死亡使者為什麼會對這種資訊有興趣？', '', 25549),
(129051, 'zhTW', '嗨，你好！很高興又見到你。\n\n等等，你第一次來嗎？\n\n今天到底星期幾？', '', 25549),
(129050, 'zhTW', '不，我記不起來。很抱歉，我還在悼念伊瑟拉，沒有心思想其他事情。你問過青銅龍軍團了嗎？他們記性一向很好。', '', 25549),
(129049, 'zhTW', '', '看看惡魔的力量！', 25549),
(129048, 'zhTW', '聽說在北方，曾經有一條強大的龍在冰河倒下，你知道些什麼嗎？', '聽說在北方，曾經有一條強大的龍在冰河倒下，你知道些什麼嗎？', 25549),
(129047, 'zhTW', '', '沒辦法了。大家準備！', 25549),
(129046, 'zhTW', '<利希卡斯看起來心不在焉。>\n\n喔，有事嗎？我不知道你在這。\n\n<利希卡斯打了一個哈欠。>', '', 25549),
(129045, 'zhTW', '', '我馬上就會殺掉你！', 25549),
(129044, 'zhTW', '', '會嗎？他要怎麼抵抗無窮無盡的惡魔大軍？要怎麼保護每個人的生命安全？', 25549),
(129043, 'zhTW', '珍妮，恐懼會讓人胡思亂想，快休息吧。', '', 25549),
(129042, 'zhTW', '我們一定能想出辦法。如果哪天需要展開行動，我們的盟友也一定有所準備。', '我們一定能想出辦法。如果哪天需要展開行動，我們的盟友也一定有所準備。', 25549),
(129041, 'zhTW', '不管在做什麼，我都會忍不住一直抬頭看天空。', '不管在做什麼，我都會忍不住一直抬頭看天空。', 25549),
(129040, 'zhTW', '你有經過急救商店嗎？排隊排到街上去了。', '你有經過急救商店嗎？排隊排到街上去了。', 25549),
(129039, 'zhTW', '你不可能察覺不到。看看四周，就連世界都要懷疑自己了。', '你不可能察覺不到。看看四周，就連世界都要懷疑自己了。', 25549),
(129038, 'zhTW', '我們的世界是不是快要崩毀了？', '我們的世界是不是快要崩毀了？', 25549),
(129037, 'zhTW', '你們才摧毀幾艘船艦就以為勝利了。趁現在好好享受吧，下次見面就是你們的末日！', '', 25549),
(129036, 'zhTW', '又有愚蠢的凡人想挑戰我？來吧！', '', 25549),
(129035, 'zhTW', '閉嘴！', '', 25549),
(129034, 'zhTW', '來吧。我正好需要一點消遣！', '', 25549),
(129033, 'zhTW', '天空每天都變得越來越近。什麼時候才會停止呢？', '天空每天都變得越來越近。什麼時候才會停止呢？', 25549),
(129032, 'zhTW', '伊利丹，帶著阿格拉瑪之盾前往永夜聖殿。我會跟卡德加一起深入薩格拉斯之墓獵殺那個怪物。基爾加丹的恐怖統治就要結束了！', '', 25549),
(129031, 'zhTW', '梅菲斯托！', '', 25549),
(129030, 'zhTW', '或許吧。但不會是今天，惡魔！', '', 25549),
(129029, 'zhTW', '別再吵了！保持專注！', '', 25549),
(129028, 'zhTW', '聖光亦然。', '', 25549),
(129027, 'zhTW', '我…我控制不了。我盡量忙別的事情轉移注意力，可是這種感覺一直湧上來…這個…我已經不知道該怎麼形容了。', '我…我控制不了。我盡量忙別的事情轉移注意力，可是這種感覺一直湧上來…這個…我已經不知道該怎麼形容了。', 25549),
(129026, 'zhTW', '你們註定要失敗！', '', 25549),
(129025, 'zhTW', '你們凡人光用漂亮的武器就想阻止我們？', '', 25549),
(129024, 'zhTW', '這些派得上用場。把它們安裝在船艦各處，準備好我就能從這裡引爆。', '', 25549),
(129023, 'zhTW', '', '你太輕易相信伊利丹了，預言者。我會盯著他完成任務。', 25549),
(129022, 'zhTW', '', '伊利丹，你終於來了啊！看守者，正事我們來做，就讓伊利丹的惡魔獵人繼續騎蝙蝠閒晃吧。', 25549),
(129021, 'zhTW', '', '又有傳送門？！援軍怎麼還沒來？', 25549),
(129020, 'zhTW', '', '看守者與你同在，勇士。', 25549),
(129019, 'zhTW', '雖然今天獲勝了，但接下來還要面對更大的挑戰。燃燒軍團的主人還沒出手呢。', '', 25549),
(129018, 'zhTW', '術士奪走了你的世界，納斯雷茲姆！真不知道你的傲慢是從哪裡來的。', '', 25549),
(129016, 'zhTW', '好。大家都收到命令了。一路順風。', '', 25549),
(129015, 'zhTW', '它是怎麼跑到那裡的？又不可能憑空出現。', '它是怎麼跑到那裡的？又不可能憑空出現。', 25549),
(129014, 'zhTW', '啊，勇士！原來你在這裡。我還擔心是不是太早引爆炸彈了。', '', 25549),
(129013, 'zhTW', '做好準備。我要救你們出來，然後引爆炸彈！', '', 25549),
(129012, 'zhTW', '敵方只剩指揮艦了。一定要在達拉然失守前打下它！黑穫議會幫我們開了傳送門。勇士，你來帶領大家吧！', '', 25549),
(129011, 'zhTW', '驚懼指揮官亞岡諾斯帶領的部隊在東北方盤據。我們得在戰線崩潰前關閉傳送門。', '', 25549),
(129010, 'zhTW', '看來你註定要失敗，凱戈洛茲領主。', '', 25549),
(129009, 'zhTW', '弓箭手！全部朝它們放箭！', '', 25549),
(129008, 'zhTW', '你看到了嗎？那些走來走去、自言自語的傢伙？', '你看到了嗎？那些走來走去、自言自語的傢伙？', 25549),
(129007, 'zhTW', '啊！打下一艘了。', '', 25549),
(129006, 'zhTW', '帶領部隊到西部山丘上。有個埃雷達爾率領手下在那鎮守。你知道該怎麼做。', '', 25549),
(129005, 'zhTW', '很好！它們自以為勝券在握，不過，它們可不知道艾澤拉斯的部隊這麼團結！', '', 25549),
(129004, 'zhTW', '必須先奪下海灘，才有辦法進攻西邊的遺跡。', '', 25549),
(129003, 'zhTW', '燃燒軍團今天別想得逞。我們會讓它們見識團結的力量。為了艾澤拉斯！', '', 25549),
(129002, 'zhTW', '我們必須佔領島嶼西邊的遺跡。在那裡才能集中所有部隊，攻擊靈魂引擎上方的中央船艦。', '', 25549),
(129001, 'zhTW', '你必須領導部隊作戰。這些船艦就交給我！', '', 25549),
(129000, 'zhTW', '我們在南邊灘地的進攻行動遇到困難了。', '', 25549),
(128999, 'zhTW', '請快一點，勇士，前線需要你！', '', 25549),
(128998, 'zhTW', '不，該不會…不可能的！', '不，該不會…不可能的！', 25549),
(128997, 'zhTW', '我們會分散部隊，從四面同時包夾敵人。', '', 25549),
(128996, 'zhTW', '我在想這代表什麼。', '我在想這代表什麼。', 25549),
(128995, 'zhTW', '歡迎你，勇士。我們可以開始進攻了。', '', 25549),
(128994, 'zhTW', '我最好不要再回答任何問題了。最近對自己的回答越來越沒把握了。', '我最好不要再回答任何問題了。最近對自己的回答越來越沒把握了。', 25549),
(128993, 'zhTW', '這是哪裡？你是誰？', '這是哪裡？你是誰？', 25549),
(128992, 'zhTW', '怎麼回事…我怎麼了？', '怎麼回事…我怎麼了？', 25549),
(128991, 'zhTW', '是水…警告其他人不要喝水！', '是水…警告其他人不要喝水！', 25549),
(128990, 'zhTW', '我想停下來，卻做不到…我就像個傀儡。', '我想停下來，卻做不到…我就像個傀儡。', 25549),
(128989, 'zhTW', '他們控制了我的頭腦…佔據了我的心智！', '他們控制了我的頭腦…佔據了我的心智！', 25549),
(128988, 'zhTW', '我…我控制不了自己。', '我…我控制不了自己。', 25549),
(128987, 'zhTW', '最近很多人都怪怪的…希望不是什麼奇怪的傳染病。', '', 25549),
(128986, 'zhTW', '你看起來很累，今天很辛苦吧？', '', 25549),
(128985, 'zhTW', '你的臉色好糟，還好嗎？', '', 25549),
(128984, 'zhTW', '等到有更多資訊，議會一定會向大家說明。在此之前，要記住時窮節乃見，這種時候最考驗人的本性。', '等到有更多資訊，議會一定會向大家說明。在此之前，要記住時窮節乃見，這種時候最考驗人的本性。', 25549),
(128983, 'zhTW', '如果對議會失去信心，城市就會分崩離析。我們一定要團結，不能因為還沒發生的事情就陷入恐慌。', '如果對議會失去信心，城市就會分崩離析。我們一定要團結，不能因為還沒發生的事情就陷入恐慌。', 25549),
(128982, 'zhTW', '', '宗師，請你快一點。振虎會的命運就靠你了！', 25549),
(128981, 'zhTW', '先知$p，你打得很好。桑德蘭很有選擇勇士的眼光。我會對他效忠。', '', 25549),
(128980, 'zhTW', '如果是末日該怎麼辦？', '如果是末日該怎麼辦？', 25549),
(128979, 'zhTW', '不對！你才要聽我說。我告訴你…我們得馬上離開這裡！', '不對！你才要聽我說。我告訴你…我們得馬上離開這裡！', 25549),
(128978, 'zhTW', '啊…宗師，愛瑪伊和白蘭琪在村子裡等你。我想先…休息…一下。', '', 25549),
(128977, 'zhTW', '天曉得。我抬頭看到的第一樣東西，就是那個徘徊不去的龐然大物。', '天曉得。我抬頭看到的第一樣東西，就是那個徘徊不去的龐然大物。', 25549),
(128976, 'zhTW', '…是沒錯，但有些人對未來充滿不安。這種時候領導者更應該以身作則、當人民的榜樣。', '…是沒錯，但有些人對未來充滿不安。這種時候領導者更應該以身作則、當人民的榜樣。', 25549),
(128975, 'zhTW', '我跟你說過了，我不知道他們在說什麼，不過他們看起來…很擔心。', '我跟你說過了，我不知道他們在說什麼，不過他們看起來…很擔心。', 25549),
(128974, 'zhTW', '這些玄鴉衛士剛被喚醒，可能還沒完全腐化。或許還有救！', '', 25549),
(128973, 'zhTW', '我不確定他在做什麼，但他樣子有點…噢。別聽我亂說。沒事。什麼事都沒有！\n', '我不確定他在做什麼，但他樣子有點…噢。別聽我亂說。沒事。什麼事都沒有！', 25549),
(128972, 'zhTW', '不要因為謠言就氣餒沮喪，越是這種時候我們越要堅強。', '不要因為謠言就氣餒沮喪，越是這種時候我們越要堅強。', 25549),
(128971, 'zhTW', '不要太害怕不確定的未來。我們還不知道未來會發生什麼事。', '不要太害怕不確定的未來。我們還不知道未來會發生什麼事。', 25549),
(128970, 'zhTW', '你說的沒錯。我們還不知道未來會發生什麼事。但如果黑暗勢力真的降臨，我們會一起面對。', '你說的沒錯。我們還不知道未來會發生什麼事。但如果黑暗勢力真的降臨，我們會一起面對。', 25549),
(128969, 'zhTW', '達拉然是照亮世界的一盞明燈。就算黑暗匯聚，我們的盟軍一定有所準備。我敢保證。', '達拉然是照亮世界的一盞明燈。就算黑暗匯聚，我們的盟軍一定有所準備。我敢保證。', 25549),
(128968, 'zhTW', '我能感覺到你身上充滿穢邪能量。喚醒這頭龍，證明牠屬於你。', '', 25549),
(128967, 'zhTW', '你竊取了巨龍的生命能量。現在，想辦法好好利用吧。用黑暗力量污染牠。', '', 25549),
(128966, 'zhTW', '我感覺到附近有許多不死生物。牠們在吞噬生命能量。搶回能量，殺光牠們。', '', 25549),
(128965, 'zhTW', '你越來越靠近了，我感覺到前方有生命跡象。你會為這個失落之地帶來腐化。', '', 25549),
(128964, 'zhTW', '當然，要是你死了，我就會重新掌控亞榭洛。阿薩斯對這座堡壘有復仇計畫…但我有別的想法。', '', 25549),
(128963, 'zhTW', '就在這裡…我能感覺到。你的補給品被凍住了，不死生物也被埋藏在冰雪之中。看來考驗你意志力的時候到了。', '', 25549),
(128961, 'zhTW', '別放開韁繩。', '', 25549),
(128960, 'zhTW', '死亡領主，繼續向北，進入漫天風雪之中。', '', 25549),
(128958, 'zhTW', '往北方飛吧，尋找冰河…尋找你的命運。', '', 25549),
(128957, 'zhTW', '你跟我一樣，內心一片空無。', '', 25549),
(128956, 'zhTW', '我們要找的歷史紀錄一定就在聖所的某個地方。至於這些紅龍的生殺大權…就在你手裡。', '', 25549),
(128955, 'zhTW', '他已經先通風報信了，紅龍會等著你。', '', 25549),
(128954, 'zhTW', '紅龍一定知道些什麼。牠們把秘密都藏在龍眠神殿底下的晶紅聖所裡。', '', 25549),
(128953, 'zhTW', '找隻青銅龍問問看吧，保護歷史是他們的責任。不用太仁慈。', '', 25549),
(128952, 'zhTW', '但這裡只剩一片茫茫大海，我也感覺不到不死生物。', '', 25549),
(128951, 'zhTW', '這些骸骨來自於最古老的龍，牠的力量強到無法想像。', '', 25549),
(128950, 'zhTW', '在前面…看到了嗎？', '', 25549),
(128949, 'zhTW', '我就是在這裡看見不死大軍穿過整片冰原，尋找著阿薩斯覬覦的寶物。', '', 25549),
(128946, 'zhTW', '去吧，到寒冰皇冠北邊去，我會讓你看看我見到的幻象。', '', 25549),
(128945, 'zhTW', '當我試著連結到寒冰的深處，卻發現自己什麼也感覺不到。', '', 25549),
(128944, 'zhTW', '我看見幻象…成千上萬的不死生物踏遍整個北裂境，只為了尋找一股強大的力量。', '', 25549),
(128943, 'zhTW', '死亡領主，統御頭盔讓我看到很多事情。', '', 25549),
(128942, 'zhTW', '厄德里斯？連你也被腐化了？看到你不能好好安息…真令人難過。', '', 25549),
(128941, 'zhTW', '反抗燃燒軍團就是死路一條！', '反抗燃燒軍團就是死路一條！', 25549),
(128940, 'zhTW', '為了燃燒軍團！', '為了燃燒軍團！', 25549),
(128939, 'zhTW', '你看不出來嗎？燃燒軍團早就贏了！', '你看不出來嗎？燃燒軍團早就贏了！', 25549),
(128938, 'zhTW', '沒用的…我們完了！我們都完了！', '沒用的…我們完了！我們都完了！', 25549),
(128937, 'zhTW', '沒有人可以逃離燃燒軍團！', '沒有人可以逃離燃燒軍團！', 25549),
(128936, 'zhTW', '主人萬歲！燃燒軍團萬歲！', '主人萬歲！燃燒軍團萬歲！', 25549),
(128935, 'zhTW', '好…累…', '', 25549),
(128932, 'zhTW', '向戰鬥領主致敬！', '', 25549),
(128931, 'zhTW', '擎天堡。', '擎天堡。', 25549),
(128930, 'zhTW', '我會陪你去雄獅陵園。', '我會陪你去雄獅陵園。', 25549),
(128929, 'zhTW', '禱告的時間結束了。我現在該做的，是去傾聽人民的心聲。', '', 25549),
(128928, 'zhTW', '不走運嗎？葛雷邁恩國王也不怎麼高興，不過我想你已經盡力了。', '', 25549),
(128927, 'zhTW', '我必須知道。跟我一起去要塞。', '', 25549),
(128926, 'zhTW', '我受夠了！揍人的時候到了！', '', 25549),
(128925, 'zhTW', '你想招惹這個星球的代言者？這個星球啊！', '', 25549),
(128924, 'zhTW', '我的熔岩要爆發了！', '', 25549),
(128923, 'zhTW', '你鬧夠了沒有！', '', 25549),
(128922, 'zhTW', '認真點！', '', 25549),
(128921, 'zhTW', '為了艾澤拉斯！', '', 25549),
(128920, 'zhTW', '為世界而戰！', '', 25549),
(128919, 'zhTW', '這些岩石裡藏著許多故事。', '', 25549),
(128918, 'zhTW', '你好！', '', 25549),
(128917, 'zhTW', '我代艾澤拉斯發言！', '', 25549),
(128916, 'zhTW', '手下！吃下這個。', '', 25549),
(128915, 'zhTW', '啊！我的召喚勇士法術成功了。手下！我們要到前面去跟我另一個前主人打。快去吧！', '', 25549),
(128914, 'zhTW', '太神奇了！我們這麼頻繁召喚元素生物和惡魔，我竟然從來沒想過通道可能是雙向的。', '', 25549),
(128913, 'zhTW', '勇士，營地附近出現能量波動，似乎特別跟你有所感應。你可以去調查一下嗎？', '', 25549),
(128912, 'zhTW', '', '喂！看看這裡的寶藏！', 25549),
(128911, 'zhTW', '', '唉呀！原來這個東西的用途是這樣啊！抱歉啦。', 25549),
(128910, 'zhTW', '啊啊啊！你做了什麼？永遠被綁在這個空間？沒有比這更慘的事了！', '', 25549),
(128909, 'zhTW', '不！你好大膽子！我才不會對笨蛋生物低頭！', '', 25549),
(128908, 'zhTW', '', '遠古束縛裂片開始發出強大的力量。', 25549),
(128907, 'zhTW', '我是尋寶大師伊克斯睿吉！等等…你手上拿的是什麼？', '', 25549),
(128906, 'zhTW', '', '喔，嗨。你是誰？', 25549),
(128905, 'zhTW', '', '喂，混蛋！你給我的這個東西有問題。我已經用石頭敲過了，沒有用啊！', 25549),
(128904, 'zhTW', '無所謂，再過一會兒我就要帶著所有寶物離開了！', '', 25549),
(128903, 'zhTW', '入侵者！你怎麼找到這裡的！', '', 25549),
(128902, 'zhTW', '多瑪崔斯撕開了惡魔傳送門！', '多瑪崔斯撕開了惡魔傳送門！', 25549),
(128901, 'zhTW', '來吧，勇士，讓敵人溺死在正義的浪潮裡！', '', 25549),
(128900, 'zhTW', '我的水被汙染變成綠色了。或許該好好過濾一下。', '', 25549),
(128899, 'zhTW', '死在正義的浪潮之下吧！', '', 25549),
(128898, 'zhTW', '你擋不住潮水的！', '', 25549),
(128897, 'zhTW', '死吧，惡魔！', '', 25549),
(128896, 'zhTW', '看我的！', '', 25549),
(128895, 'zhTW', '你的魔焰被澆熄了！', '', 25549),
(128894, 'zhTW', '讓水流淨化一切！', '', 25549),
(128893, 'zhTW', '溺死吧！輸家！', '', 25549),
(128892, 'zhTW', '還好有你，勇士。這裡差點就水深火熱了！', '', 25549),
(128891, 'zhTW', '奈普圖隆派出最厲害的勇士來協助我們，而且指名要找你。我很期待你們兩位能對敵人造成多少傷害。', '', 25549),
(128890, 'zhTW', '不！燃燒軍團…會摧毀…這個世界…', '', 25549),
(128889, 'zhTW', '我會殺光你們的先祖！', '', 25549),
(128888, 'zhTW', '光榮的一戰！正好給那些水裡的害蟲一個教訓。', '', 25549),
(128887, 'zhTW', '英雄！魔怒納迦和那些斯闊格走狗騷擾我們夠久了。該給他們的惡行一點教訓了！', '', 25549),
(128886, 'zhTW', '大法師，請你解救被困在悲泣露臺的魔縛法力刃豹！囚禁牠們的防護師很強大，一有機會就使用你的竊取法術！', '', 25549),
(128885, 'zhTW', '表現得真英勇，撲滅了邪惡的火焰，也澆息了惡魔的野心。$b$b以陸地生物而言，你做得還算不錯。', '', 25549),
(128884, 'zhTW', '', '我們在幻夢之林見，大德魯伊。謝謝你帶我來！', 25549),
(128883, 'zhTW', '我…還活著？朋友，謝謝你！太感謝了！', '我…還活著？朋友，謝謝你！太感謝了！', 25549),
(128882, 'zhTW', '非常感謝你！', '非常感謝你！', 25549),
(128881, 'zhTW', '我再也不離開納薩拉斯啦！', '我再也不離開納薩拉斯啦！', 25549),
(128880, 'zhTW', '英雄，謝謝你！我還以為完蛋了！', '英雄，謝謝你！我還以為完蛋了！', 25549),
(128879, 'zhTW', '我覺得好虛弱，快被這些網給吸乾了。', '我覺得好虛弱，快被這些網給吸乾了。', 25549),
(128878, 'zhTW', '謝謝你，陌生人！', '謝謝你，陌生人！', 25549),
(128877, 'zhTW', '', '你…不懂…', 25549),
(128876, 'zhTW', '我會回到幻夢之林。謝謝你！', '我會回到幻夢之林。謝謝你！', 25549),
(128875, 'zhTW', '一定要阻止那個指揮官。我相信你辦得到！', '一定要阻止那個指揮官。我相信你辦得到！', 25549),
(128874, 'zhTW', '謝謝你，大德魯伊。我還以為死定了。', '謝謝你，大德魯伊。我還以為死定了。', 25549),
(128872, 'zhTW', '我不會讓這件事發生。', '我不會讓這件事發生。', 25549),
(128871, 'zhTW', '凡人！我受奈普圖隆之命，要為入侵我們世界的惡魔蠢貨帶來毀滅和審判。$b$b跟我一起作戰，我們攜手撲滅這場邪惡的火焰。', '', 25549),
(128867, 'zhTW', '', '我要殺了那個指揮官！', 25549),
(128866, 'zhTW', '你們的世界很快就會失去生命的脈動！', '', 25549),
(128862, 'zhTW', '你的勇氣微不足道。', '', 25549),
(128860, 'zhTW', '肉體的疼痛很短暫。真正的苦痛是永恆的。', '', 25549),
(128859, 'zhTW', '', '來吃點心囉！', 25549),
(128858, 'zhTW', '', '來吧，孩子！點心時間到了！', 25549),
(128857, 'zhTW', '看看死亡的真實面貌，瞭解你們的末日降臨了！', '', 25549),
(128854, 'zhTW', '', '在你來之前，我已經從這個惡魔身上問出來了。我知道它們的指揮官在哪裡！', 25549),
(128845, 'zhTW', '跟我一起去召喚平台，儀式已經準備好了。', '', 25549),
(128843, 'zhTW', '阿格拉瑪之盾的能量已經耗盡了！', '', 25549),
(128842, 'zhTW', '制住野獸，我會召喚議會過來…', '', 25549),
(128841, 'zhTW', '清掉天上的東西，否則我們永遠無法摧毀導引裝置！', '清掉天上的東西，否則我們永遠無法摧毀導引裝置！', 25549),
(128840, 'zhTW', '要是不切斷連結，艾澤拉斯就完了！', '要是不切斷連結，艾澤拉斯就完了！', 25549),
(128839, 'zhTW', '再撐一下！我們絕對不能夠失敗！', '再撐一下！我們絕對不能夠失敗！', 25549),
(128838, 'zhTW', '這東西散發的能量太驚人了。', '這東西散發的能量太驚人了。', 25549),
(128837, 'zhTW', '不要停手，直到切斷連結！', '不要停手，直到切斷連結！', 25549),
(128836, 'zhTW', '集中攻擊！我們必須切斷連結！', '集中攻擊！我們必須切斷連結！', 25549),
(128835, 'zhTW', '', '你聽到了！我們必須找出是誰在指揮這場攻擊行動！快點！', 25549),
(128834, 'zhTW', '我先找安全的地方休養。你們一定要找出敵人的領袖，殺了他！', '', 25549),
(128833, 'zhTW', '小時不讀書…', '', 25549),
(128832, 'zhTW', '三思…而…後行…', '', 25549),
(128831, 'zhTW', '拳頭夠硬，幹嘛讀書！', '', 25549),
(128830, 'zhTW', '哈！誰比較聰明啊？', '', 25549),
(128829, 'zhTW', '學乖了沒？', '', 25549),
(128828, 'zhTW', '死了一個笨蛋！', '', 25549),
(128827, 'zhTW', '弱者才讀書！', '', 25549),
(128826, 'zhTW', '放馬過來！', '', 25549),
(128825, 'zhTW', '有種就來啊！', '', 25549),
(128824, 'zhTW', '廢物，別跑！', '', 25549),
(128823, 'zhTW', '踩扁你們！', '', 25549),
(128822, 'zhTW', '我一定要去破碎海岸，看看父親所做的犧牲。', '', 25549),
(128821, 'zhTW', '碾死你們這些笨蛋！', '', 25549),
(128820, 'zhTW', '你們自以為比燃燒軍團聰明？別傻了！', '', 25549),
(128819, 'zhTW', '朋友，謝謝你。我知道該怎麼做才能承擔父親留給我的責任了。', '', 25549),
(128818, 'zhTW', '年輪…已經…預告結局了…', '', 25549),
(128817, 'zhTW', '輪到我…滋養…大地了…', '', 25549),
(128816, 'zhTW', '凡人不懂真正的美麗。', '', 25549),
(128815, 'zhTW', '他們不懂得尊重大自然。', '', 25549),
(128814, 'zhTW', '拿去餵蟲子！', '', 25549),
(128813, 'zhTW', '廢物就該當肥料！', '', 25549),
(128812, 'zhTW', '你們真是煞風景！', '', 25549),
(128811, 'zhTW', '這裡不歡迎你們！', '', 25549),
(128810, 'zhTW', '根鬚要你的命！', '', 25549),
(128809, 'zhTW', '身為君王，要知道自己的一言一行會有什麼後果。光是一個羅盤就一蹶不振，那惡魔打到城裡的時候怎麼辦？', '', 25549),
(128808, 'zhTW', '我會壓死你們！', '', 25549),
(128807, 'zhTW', '我們需要的不只是信心，他也一樣。安杜因當時不在破碎海岸，也沒有親眼看過我們在這段期間犧牲有多慘痛。', '', 25549),
(128806, 'zhTW', '這是你最後一口氣！', '', 25549),
(128805, 'zhTW', '喉嚨變緊了嗎？', '', 25549),
(128804, 'zhTW', '沒錯，只有惡魔力量才能展現我們的美麗。', '', 25549),
(128803, 'zhTW', '安杜因身上的聖光很強。他會是個英明的國王。我們要有信心。', '', 25549),
(128802, 'zhTW', '光看幻象是打不贏的。這孩子心地善良，但沒經歷過考驗。', '', 25549),
(128801, 'zhTW', '這位年輕的國王會是偉大的領袖。我可以預見。', '', 25549),
(128800, 'zhTW', '我聽到人民的心聲了，但父親的參謀們又怎麼想呢？恐怕他們沒有那麼信任我。', '', 25549),
(128799, 'zhTW', '人民喜歡我、尊重我…但是他們不信任我。他們信任的是我父親。', '', 25549),
(128798, 'zhTW', '可憐的靈魂！沒想到有人比我還殘酷…', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128797, 'zhTW', '你把父親的羅盤帶回來給我後，我就向聖光祈求指引，並詢問他是否得到安息。聖光卻沒有回答我。', '', 25549),
(128796, 'zhTW', '你會付出代價！', '', 25549),
(128795, 'zhTW', '我的作品…毀了！', '', 25549),
(128794, 'zhTW', '看看這個靈魂，多麼渴望服從！', '', 25549),
(128793, 'zhTW', '聽好了，凡人！服從的靈魂會效忠燃燒軍團！', '', 25549),
(128792, 'zhTW', '痛苦…不只…這樣…', '', 25549),
(128791, 'zhTW', '失敗的陰影…不會消失…', '', 25549),
(128790, 'zhTW', '他們的肉體崩潰了！是我贏了！', '', 25549),
(128789, 'zhTW', '凡人的心智太脆弱。真是無聊。', '', 25549),
(128788, 'zhTW', '那個傢伙崩潰了！', '', 25549),
(128787, 'zhTW', '弱者就要淘汰！', '', 25549),
(128786, 'zhTW', '意志軟弱！', '', 25549),
(128785, 'zhTW', '你是我的了！', '', 25549),
(128784, 'zhTW', '我無法反對那孩子的選擇。我父親犧牲一切來保護他的人民。他是個偉大的國王。', '', 25549),
(128783, 'zhTW', '對耶，我爸也這樣說。好吧，我是瓦里安國王，惡魔要遭殃了！', '', 25549),
(128782, 'zhTW', '', '別選安杜因，你應該選瓦里安！他比較強。', 25549),
(128781, 'zhTW', '求饒吧，凡人！', '', 25549),
(128780, 'zhTW', '你會崩潰！', '', 25549),
(128779, 'zhTW', '我是安杜因國王！我要殺光惡魔，見一個殺一個！', '', 25549),
(128778, 'zhTW', '抵抗只會更痛苦！', '', 25549),
(128777, 'zhTW', '我會燒到你屈服！', '', 25549),
(128776, 'zhTW', '何必忍受這種痛苦？效忠燃燒軍團吧！', '', 25549),
(128775, 'zhTW', '我能緩解你的痛苦！聽從我的話吧！', '', 25549),
(128774, 'zhTW', '我們的苦難…會很…璀璨…', '', 25549),
(128773, 'zhTW', '讓主人…失望…好痛苦…', '', 25549),
(128772, 'zhTW', '他們的靈魂會永遠受到恥辱的折磨！', '', 25549),
(128771, 'zhTW', '對他們來說死了反而輕鬆。', '', 25549),
(128770, 'zhTW', '撐不住了嗎？', '', 25549),
(128769, 'zhTW', '脆弱的凡人！', '', 25549),
(128768, 'zhTW', '又摧毀一個！', '', 25549),
(128767, 'zhTW', '他們會害怕是正常的。如果不能在破碎海岸阻止燃燒軍團，惡魔就會打來這裡，踏進我們的家園。', '', 25549),
(128766, 'zhTW', '我保證…會很痛！', '', 25549),
(128765, 'zhTW', '你能撐多久呢？', '', 25549),
(128764, 'zhTW', '你會受到無盡的痛苦！', '', 25549),
(128763, 'zhTW', '', '奇怪，我好像聽到…唉，一定是我在胡思亂想吧。', 25549),
(128762, 'zhTW', '讓我聽聽你的叫聲！', '', 25549),
(128761, 'zhTW', '我會狠很地切開你！', '', 25549),
(128760, 'zhTW', '至少我們在暴風城裡還很安全。烏瑞恩國王一定會守住這座城的。', '', 25549),
(128759, 'zhTW', '椎心刺骨！', '', 25549),
(128758, 'zhTW', '痛苦！極度的痛苦！', '', 25549),
(128757, 'zhTW', '', '上個禮拜，他們把我親戚的遺體從破碎海岸帶回來了。我想一定還有很多犧牲者。', 25549),
(128756, 'zhTW', '比想像中快，但也無所謂。換我們上工了！', '', 25549),
(128755, 'zhTW', '呸！那是因為我造成的苦痛才…等等！那些凡人來了！苟洛斯那個蠢蛋又失敗了！', '', 25549),
(128754, 'zhTW', '折磨肉體？呸！折磨心靈才管用。我們不就是這樣制伏拉克許的嗎？', '', 25549),
(128753, 'zhTW', '承認我是對的吧！摧毀肉體，精神也會跟著崩潰。', '', 25549),
(128752, 'zhTW', '絕對要讓燃燒軍團付出代價！', '絕對要讓燃燒軍團付出代價！', 25549),
(128751, 'zhTW', '你應該趕快解決那些小鬼。它們雖然力量不強，但只要數量一多就難以抵擋！', '', 25549),
(128750, 'zhTW', '醒醒啊，戈德林。', '醒醒啊，戈德林。', 25549),
(128749, 'zhTW', '<魔化能量消散之後，戈德林平靜地沉眠。>', '', 25549),
(128748, 'zhTW', '我知道該用哪個法術。跟我來。', '', 25549),
(128747, 'zhTW', '我需要喬裝一下才能在城裡避人耳目。', '', 25549),
(128746, 'zhTW', '葛雷邁恩國王說過你會來。請，快請進。', '', 25549),
(128745, 'zhTW', '', '它…它們想腐化戈德林！大德魯伊，快點！', 25549),
(128744, 'zhTW', '', '這樣惡魔就不能通過傳送門了！', 25549),
(128743, 'zhTW', '', '給它們好看！', 25549),
(128742, 'zhTW', '', '你能想像惡魔衝出來，結果一頭撞上藤蔓嗎？真好笑！', 25549),
(128741, 'zhTW', '', '傳送門應該就在這附近…保持警戒！', 25549),
(128740, 'zhTW', '我知道他想為父親哀悼，但國王該盡自己的本份。守住破碎海岸才是第一要務。想辦法勸勸安杜因吧！', '', 25549),
(128739, 'zhTW', '安杜因不吃也不睡，大家勸他回宮殿，他也不理。不管我說什麼都無法安慰他。', '', 25549),
(128738, 'zhTW', '我們的客人來了。這樣或許有機會讓國王振作起來。', '', 25549),
(128737, 'zhTW', '謝謝你把父親的羅盤帶給我。睹物思人，讓我好想他。', '', 25549),
(128736, 'zhTW', '自從跟燃燒軍團開戰以後，我就沒有時間思考或喘息…也沒有時間哀傷。或許現在該是時候了。', '', 25549),
(128735, 'zhTW', '我訂做了這個羅盤給父親當生日禮物。我在前往潘達利亞的幾個月前送給了他。感覺像上輩子的事了…', '', 25549),
(128734, 'zhTW', '', '走吧！我們得去救戈德林！', 25549),
(128732, 'zhTW', '', '快！幫我！', 25549),
(128730, 'zhTW', '喔，你又回來看魔術啦？等一下別忘了給小費啊！', '', 25549),
(128729, 'zhTW', '不喜歡我的表演？那你怎麼不來咬我滑溜又迷人的屁股！', '', 25549),
(128728, 'zhTW', '你繼續下去只是自取滅亡。把武器放下，在你的主人面前跪下！', '', 25549),
(128727, 'zhTW', '謝謝你做的一切。雖然需要時間，但這片土地一定會復原。英雄，做得好！', '', 25549),
(128726, 'zhTW', '哈哈！再見，提里斯「護髮」！', '', 25549),
(128725, 'zhTW', '我感覺到附近有一群骯髒的惡魔。勇士，交給你了，殺光它們！', '', 25549),
(128724, 'zhTW', '再見啦，你們這些無聊…呃，無趣的…木頭法師！', '', 25549),
(128723, 'zhTW', '太好了！我去拿行李，擺脫這些蠢蛋吧。', '', 25549),
(128722, 'zhTW', '稍等一下，我馬上把你弄出來。', '', 25549),
(128721, 'zhTW', '呼，真驚險。這些兔子可不便宜啊！', '', 25549),
(128720, 'zhTW', '那匹狼是怎麼進來的？！別站著不動，快把狼殺掉啊！', '', 25549),
(128719, 'zhTW', '兄弟，你在裡面到處找找，看兔子到底發生什麼事。', '', 25549),
(128718, 'zhTW', '搞什麼鬼？！', '', 25549),
(128717, 'zhTW', '來，你試試看。', '', 25549),
(128716, 'zhTW', '接著在裡面塞滿兔子，然後…碰！', '', 25549),
(128715, 'zhTW', '好，第一件事就是準備一頂帽子，帽子裡裝上攜帶式次元傳送門。', '', 25549),
(128714, 'zhTW', '先回守護者殿堂吧，我準備了一些謝禮要給你。', '', 25549),
(128713, 'zhTW', '好了，不用再試啦。該想想要怎麼量產了！', '', 25549),
(128712, 'zhTW', '別擔心那些測試對象，他們在這裡住這麼久，早就習慣了。', '', 25549),
(128711, 'zhTW', '很不賴吧！你看他們有模有樣的！', '', 25549),
(128710, 'zhTW', '喂！過來！有件事想跟你商量！', '', 25549),
(128709, 'zhTW', '我們一直找不到自願進入那座邪惡巢穴的勇者。如果你的鞋子黏滿蜘蛛絲，需要買雙新的，我和達拉然的商人關係還不錯，可以幫你打折！', '', 25549),
(128708, 'zhTW', '英雄，做得好！只要燃燒軍團還在這個世界，我們就必須保持警戒。', '', 25549),
(128707, 'zhTW', '英雄，我感覺到布瑞登溪有股邪惡的力量。找出燃燒軍團的手下，消滅它們！', '', 25549),
(128706, 'zhTW', '有個困難的任務要交給你，勇士。有一道複雜的咒語，需要蒐集蜘蛛岩洞怪物身上的絲。你能幫個忙嗎？', '', 25549),
(128705, 'zhTW', '我對付過凶惡的納迦、憤怒的惡靈和狡詐的惡魔。但是蜘蛛…無法忍受！', '', 25549),
(128704, 'zhTW', '', '沒時間了，大德魯伊！我等不及要多殺幾個惡魔了！', 25549),
(128703, 'zhTW', '', '哇…艾維娜…', 25549),
(128702, 'zhTW', '你一定要摧毀所有看得到的蜘蛛卵。不能讓這些怪物離開此地！', '', 25549),
(128701, 'zhTW', '噁…蜘蛛！燃燒軍團要派什麼魔物都可以，但為什麼偏偏是蜘蛛？', '', 25549),
(128700, 'zhTW', '', '艾維娜！', 25549),
(128699, 'zhTW', '', '傷害我孩子的人會付出代價！', 25549),
(128698, 'zhTW', '我們走吧。', '我們走吧。', 25549),
(128697, 'zhTW', '我要宰了你！', '', 25549),
(128690, 'zhTW', '', '對象：艾澤拉斯。測量到輕微的心律不整，不過生命跡象介於可接受的範圍內。已更新事件報告。', 25549),
(128689, 'zhTW', '', '已消滅威脅跡象。防禦裝置尚餘百分之74.39，正在修復中。', 25549),
(128688, 'zhTW', '未偵測到鄰近威脅。啟動感激協助程序。', '', 25549),
(128687, 'zhTW', '威脅解除。啟動修復系統。', '', 25549),
(128686, 'zhTW', '', '喔！我是在泰爾亞諾發現他的，當時他全身一絲不掛地被某個鷹身人給困住！哈！\n\n鷹身人在跟一個女妖吵誰才能先跟他玩，所以完全沒有注意到我。\n\n他看起來非常不自在，所以我就出手了。其他的你都知道了！', 25549),
(128685, 'zhTW', '薩…格…拉斯…', '', 25549),
(128684, 'zhTW', '', '艾維娜，你的禽鳥能帶來艾澤拉斯各地的消息。求求你幫我們找出惡魔的目標！我們要為死去的同胞報仇！', 25549),
(128683, 'zhTW', '我們能幫上什麼忙嗎？', '我們能幫上什麼忙嗎？', 25549),
(128682, 'zhTW', '烈焰沖天。黑暗中…有把劍…傷口…在燃燒…', '', 25549),
(128681, 'zhTW', '', '想到我的兄弟姊妹們竟然死在惡魔的詭計之下…無法接受！', 25549),
(128680, 'zhTW', '你怎麼遇到埃薩的？', '你怎麼遇到埃薩的？', 25549),
(128679, 'zhTW', '沙地…充滿痛苦。河流…滿是鮮血。', '', 25549),
(128678, 'zhTW', '', '我一直認為魔法很美妙，所有形態都是。現在護盾消失了，我等不及要鑽研所有的魔法了！', 25549),
(128677, 'zhTW', '她的情緒亂糟糟的。我需要專注，讓她的想法通過…呃啊！', '', 25549),
(128676, 'zhTW', '', '艾維娜！你的子民需要幫助。燃燒軍團正在殘殺猛禽德魯伊！', 25549),
(128675, 'zhTW', '黑暗泰坦來了！我們必須阻止他！燃燒軍團的大本營…她說我們注定要到阿古斯去。', '', 25549),
(128674, 'zhTW', '', '要是讓長老知道我跟外來者攪和，我會被放逐的…說不定更慘。', 25549),
(128673, 'zhTW', '好姑娘，跟我說話。告訴我你在氣什麼…', '', 25549),
(128672, 'zhTW', '', '夏多雷世世代代都與世隔絕。我們很難敞開心胸接受新的思考方式。', 25549),
(128671, 'zhTW', '這些魅影一定是她的夢…她的惡夢。只要幫她克服這些恐懼，艾澤拉斯就能對我們傳遞訊息。', '', 25549),
(128670, 'zhTW', '', '我不確定這有沒有用，但總得試試看…後退一點！', 25549),
(128669, 'zhTW', '有東西觸發防禦系統了！小心，有敵人來了！', '', 25549),
(128668, 'zhTW', '她最近…不太對勁。思緒很紛亂。希望你能幫我突破她的心防。', '', 25549),
(128667, 'zhTW', '這些泰坦建築的作用是保護世界之魂。我從這個房間就能聽到她的聲音，像鑽石一樣清晰。', '', 25549),
(128666, 'zhTW', '搞定了。傳送器會帶你到地底深處。幾千年以來都沒有凡人來過的地方…共融大廳！下來吧，我有很多東西要給你看。', '', 25549),
(128665, 'zhTW', '啊，你快到了。來東邊高山裡的造物者瞰臺這邊。我會跟你說怎麼進來。', '', 25549),
(128664, 'zhTW', '勇士！艾澤拉斯需要我們。', '', 25549),
(128663, 'zhTW', '你們都瞎了眼。我會讓你們看清楚。', '', 25549),
(128662, 'zhTW', '你成功了！惡夢控制住了。繼續前進，我在下一個房間。', '', 25549),
(128661, 'zhTW', '我感覺到她的恐懼…還有困惑。我們必須幫助她！看樣子有些防禦系統癱瘓了。要是能夠重新啟動，或許能鼓勵她振作起來！', '', 25549),
(128660, 'zhTW', '重啟修復模式。外來協助評估結果：感謝。', '', 25549),
(128659, 'zhTW', '重啟程序完成。啟動哨衛程序。', '', 25549),
(128658, 'zhTW', '發現異常。啟動G.T.F.O.防禦程序。', '', 25549),
(128657, 'zhTW', '夠了！我要親自消滅你！', '', 25549),
(128656, 'zhTW', '可惜布萊恩沒有跟你一起來。我弟弟最喜歡打開泰坦建築的門了！', '', 25549),
(128655, 'zhTW', '到北裂境的休拉薩盆地找我。我們一起探探究竟。', '', 25549),
(128654, 'zhTW', '她想傳遞訊息給我…應該是個警告。但她似乎不太對勁。', '', 25549),
(128653, 'zhTW', '太好了，你還活著。既然惡夢已經結束，我們就能仔細聽聽她想說的話了。想開始就說一聲吧。', '', 25549),
(128652, 'zhTW', '', '我去前面跟你會合。', 25549),
(128651, 'zhTW', '我是意外發現她…呃，我的意思是她發現我的。\n\n我不小心惹上一點…小狀況…有一個鷹身人，一個女妖，還有…等等，這不是重點。\n\n重點是，萊恩娜用超厲害的法術把我救出來，然後要求加入提里斯護法。\n\n我怎麼能說不？', '', 25549),
(128650, 'zhTW', '我想知道關於秘法師萊恩娜的事。', '我想知道關於秘法師萊恩娜的事。', 25549),
(128649, 'zhTW', '', '做得好！疫病好像控制住了。', 25549),
(128648, 'zhTW', '', '死木灘受到疫病侵襲。在這座島嶼上出沒的鷹身人就是帶原者。不能讓腐化繼續散播下去！', 25549),
(128647, 'zhTW', '', '魔化疫病又擴散到死木灘了，大祭司。我們一定要想辦法阻止疫病繼續蔓延下去。', 25549),
(128646, 'zhTW', '這一戰真精彩！這艘船隨時都會炸成碎片。哈哈！不用緊張！戰鷹會接你到安全的地方！', '', 25549),
(128645, 'zhTW', '好驚險，謝謝你幫忙。', '', 25549),
(128644, 'zhTW', '', '英雄，快點，拉桑需要幫助！', 25549),
(128643, 'zhTW', '你們就這點能耐嗎？還真弱。就沒有一個能打的嗎？', '', 25549),
(128642, 'zhTW', '', '魔裔陷捕者用扭曲的魔法傷害這裡的野生動物。帶著這個法力之根藥膏，幫受傷的動物敷上。快，否則就沒救了！', 25549),
(128641, 'zhTW', '呃啊！', '', 25549),
(128640, 'zhTW', '你負責破壞燃燒軍團船艦和拯救盟友。惡魔指揮官讓我來對付！', '', 25549),
(128639, 'zhTW', '這些戰鷹會送我們到目的地。準備好了就上去吧！', '', 25549),
(128638, 'zhTW', '', '登船以後盡可能救出所有俘虜。等我的族人都安全了，就開始裝炸藥，然後…快逃！', 25549),
(128637, 'zhTW', '', '繼續前進！', 25549),
(128636, 'zhTW', '', '小心！', 25549),
(128635, 'zhTW', '', '知道了。各位英雄，我們到集合點去吧。', 25549),
(128634, 'zhTW', '我們隨時可以攻擊燃燒軍團的船艦。梅拉、各位勇士，我們在雷霆圖騰外集合。給它們好看！', '', 25549),
(128633, 'zhTW', '', '英雄，做得好。雖然只封住兩個通道，但還是很有幫助。', 25549),
(128632, 'zhTW', '', '英雄…解決這個…惡魔…', 25549),
(128631, 'zhTW', '', '呃啊！', 25549),
(128630, 'zhTW', '', '納瓦羅格的地卜師正在封鎖通道，阻止燃燒軍團繼續湧入。盡全力保護他！', 25549),
(128629, 'zhTW', '你背叛了我們的族人，才會跟這些惡魔的信徒為伍！', '', 25549),
(128628, 'zhTW', '', '各位勇士，燃燒軍團打算從地面入侵雷霆圖騰，擊退它們！', 25549),
(128627, 'zhTW', '', '我的戰士奉獻了生命，勇士。接受這份禮物，奮戰下去！', 25549),
(128626, 'zhTW', '', '你是大自然真正的守護者。我很感謝你。', 25549),
(128625, 'zhTW', '雷霆圖騰遭受攻擊！我們先去救盟友，再把那艘惡魔船艦打下來。', '', 25549),
(128624, 'zhTW', '', '就算首領死了，這些魔裔陷捕者也不肯罷手！帶著這個法力之根藥膏，幫受傷的動物敷上，盡量想辦法救牠們！', 25549),
(128623, 'zhTW', '', '魔火隘口到處都是對燃燒軍團效忠的神秘學者。別讓他們拿下這裡！', 25549),
(128622, 'zhTW', '', '你展現出強大的實力！那些神秘學者一定很後悔跟我們作對！', 25549),
(128621, 'zhTW', '', '雖然坎瑞薩德已經回來了，但這些神秘學者還是向燃燒軍團效忠。不能再讓他們拿下魔火隘口。殺掉他們，再吸取他們的能量。', 25549),
(128620, 'zhTW', '強大的燃燒軍團發動猛烈的攻勢，我們快要抵擋不住了。', '', 25549),
(128619, 'zhTW', '說吧。', '說吧。', 25549),
(128618, 'zhTW', '破壞者來自於部落…確切說起來，是我們奪日者的人。\n\n六法議會中有人非常反對我們加入祈倫托。這些人可以用這件事大作文章，再一次把我們趕走。\n\n要是發生了這種事情，艾澤拉斯一定會分裂，也就沒辦法團結抵抗燃燒軍團了。', '', 25549),
(128617, 'zhTW', '你收到的命令是立刻投入戰場！解決那些攻擊我們前線的惡魔！', '', 25549),
(128616, 'zhTW', '為什麼燃燒軍團有辦法使用達拉然的武器？', '為什麼燃燒軍團有辦法使用達拉然的武器？', 25549),
(128615, 'zhTW', '盟友好像擋住敵人了…保持警戒。', '', 25549),
(128614, 'zhTW', '我們在武器核心發現破壞者的屍體。他的靈魂被吸乾了…呃，這種死法真的很慘。\n\n看來，事情恐怕比我想的更糟。', '', 25549),
(128613, 'zhTW', '', '如果它們只是聲東擊西，那攻擊的主力在哪裡？我們得去問艾維娜，她一定知道！', 25549),
(128612, 'zhTW', '我曾經墮入黑暗之中…千萬別學我啊。', '', 25549),
(128611, 'zhTW', '你這身打扮，永遠也當不了真正的法師。', '', 25549),
(128610, 'zhTW', '學徒？門生？接班人？嗯，就這個…', '', 25549),
(128609, 'zhTW', '等等…我忘了關掉火之試煉嗎？我應該有關掉吧…', '', 25549),
(128608, 'zhTW', '哼，記得多讀點書。', '', 25549),
(128607, 'zhTW', '等等，你說你是誰？', '', 25549),
(128606, 'zhTW', '走吧，然後…找點事情做！', '', 25549),
(128605, 'zhTW', '盡量別死啊！', '', 25549),
(128604, 'zhTW', '我真的在這裡…還是幻象呢？', '', 25549),
(128603, 'zhTW', '你喜歡…試煉嗎？', '', 25549),
(128602, 'zhTW', '學徒永遠不嫌多。', '', 25549),
(128601, 'zhTW', '你好啊。', '', 25549),
(128600, 'zhTW', '我只不過是個願意站出來捍衛艾澤拉斯的人罷了。', '', 25549),
(128599, 'zhTW', '我跟弟弟一起經歷過許許多多的戰爭和試煉。', '', 25549),
(128598, 'zhTW', '小心龍族。別相信牠們！', '', 25549),
(128597, 'zhTW', '我會擊潰敵人！', '', 25549),
(128596, 'zhTW', '我的盾，供您差遣。', '', 25549),
(128595, 'zhTW', '我會守護這裡。', '', 25549),
(128594, 'zhTW', '願聖光賜你力量。', '', 25549),
(128593, 'zhTW', '需要我幫忙嗎？', '', 25549),
(128592, 'zhTW', '聖光祝福你，旅行者。', '', 25549),
(128591, 'zhTW', '你好，冒險者。', '', 25549),
(128590, 'zhTW', '幸會。', '', 25549),
(128589, 'zhTW', '', '魔火長矛現在正好能派上用場…', 25549),
(128588, 'zhTW', '', '你知道嗎？綠色跟我還蠻搭的…', 25549),
(128587, 'zhTW', '', '就連燃燒軍團都沒像你這麼煩！', 25549),
(128586, 'zhTW', '', '我的族人是出了名的壞脾氣。', 25549),
(128585, 'zhTW', '', '我父親對你的看法或許是對的。', 25549),
(128584, 'zhTW', '', '快住手。', 25549),
(128583, 'zhTW', '', '我不會再被獵殺了。', 25549),
(128582, 'zhTW', '', '外來者，以榮耀而戰。', 25549),
(128581, 'zhTW', '', '眾神與你同在。', 25549),
(128580, 'zhTW', '', '我絕不會退縮。', 25549),
(128579, 'zhTW', '', '我意志堅定。', 25549),
(128578, 'zhTW', '', '我的盾從不懈怠。', 25549),
(128577, 'zhTW', '', '你為何而來？', 25549),
(128576, 'zhTW', '', '你好，外來者。', 25549),
(128575, 'zhTW', '', '愚蠢的德魯伊…我們只是聲東擊西！', 25549),
(128574, 'zhTW', '為什麼我都不能留一匹恐懼戰馬？', '', 25549),
(128573, 'zhTW', '你不去收集材料或什麼的嗎？', '', 25549),
(128572, 'zhTW', '你帶了更多血來嗎？', '', 25549),
(128571, 'zhTW', '惡魔的足蹄迅捷如風。', '', 25549),
(128570, 'zhTW', '惡魔會向我們臣服。', '', 25549),
(128569, 'zhTW', '克索諾斯在呼喚。', '', 25549),
(128568, 'zhTW', '恐懼戰馬是我們的。', '', 25549),
(128567, 'zhTW', '今天要召喚些什麼呢？', '', 25549),
(128566, 'zhTW', '需要我的協助嗎？', '', 25549),
(128565, 'zhTW', '要我召喚什麼？', '', 25549),
(128564, 'zhTW', '嗯？', '', 25549),
(128563, 'zhTW', '', '墮入黑爾海姆的深淵吧！', 25549),
(128562, 'zhTW', '', '快來，大德魯伊！我們需要幫助！', 25549),
(128561, 'zhTW', '很好。到蕾茉薩女士的高塔附近找我，我會召喚傳送門。', '', 25549),
(128560, 'zhTW', '記住，千萬不要靠近正在吸取能量的夜裔靈魂石！', '', 25549),
(128559, 'zhTW', '', '這位法師會把你傳送過來。這件事不容易。做好準備！', 25549),
(128558, 'zhTW', '', '等你一到，我們會重新開啟傳送門，進入惡魔的領域，徹底消滅他！', 25549),
(128557, 'zhTW', '', '預言者已經準備好咒語，我也冥想夠久了。卡魯歐必須死。', 25549),
(128556, 'zhTW', '我把我的位置告訴你們的法師了。等你來到這裡，我們就進去圖加的洞穴，殺死他。', '', 25549),
(128555, 'zhTW', '我們要殺死他跟那隻噁心的寵物，阻止他們攻擊雷霆圖騰。這項任務，可沒那麼容易。', '', 25549),
(128554, 'zhTW', '圖加‧血圖騰在高嶺出現，還跟著一隻充滿魔化能量的巨大蠕蟲。', '', 25549),
(128553, 'zhTW', '來吧，英雄。我們要殺了厄德里斯…永絕後患。', '', 25549),
(128552, 'zhTW', '有兩個從布瑞登溪來的勇猛鬥士堅持要加入我們。不過就算有他們協助，眼前的戰鬥還是充滿凶險。', '', 25549),
(128551, 'zhTW', '時候到了。我已經找到厄德里斯‧刺棘。他就在玄鴉堡高塔的頂層，計畫建立一支亡靈軍團！', '', 25549),
(128550, 'zhTW', '', '大法師$n，我們在守護者殿堂見。', 25549),
(128549, 'zhTW', '你很想被我在身上戳幾個洞嗎？', '', 25549),
(128548, 'zhTW', '我可是北郡的瑪克西米利安，女士救援專家。你這是什麼態度！', '', 25549),
(128547, 'zhTW', '你曉得自己在跟誰說話嗎？', '', 25549),
(128546, 'zhTW', '再見吧。', '', 25549),
(128545, 'zhTW', '走開！我還得去屠龍呢！', '', 25549),
(128544, 'zhTW', '嗯哼。', '', 25549),
(128543, 'zhTW', '有我可以效勞的嗎？', '', 25549),
(128542, 'zhTW', '嗯？', '', 25549),
(128541, 'zhTW', '嘿呦！', '', 25549),
(128540, 'zhTW', '我們出發吧！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128539, 'zhTW', '我們一起去殺強大的怪獸！', '', 25549),
(128538, 'zhTW', '嘿呦！', '', 25549),
(128537, 'zhTW', '嘿，侍從，你好呀！', '', 25549),
(128536, 'zhTW', '汝等在我劍下死去吧！', '', 25549),
(128535, 'zhTW', '為了朵莉亞！', '', 25549),
(128534, 'zhTW', '好奇怪的龍！但沒在怕的！', '', 25549),
(128533, 'zhTW', '土中劍！攻擊！', '', 25549),
(128532, 'zhTW', '看我用超強的劍殺掉你！', '', 25549),
(128531, 'zhTW', '哈，真輕鬆啊。', '', 25549),
(128530, 'zhTW', '強大的我又擊敗了一個怪物！', '', 25549),
(128529, 'zhTW', '侍從，你看清楚我剛才怎麼贏的嗎？', '', 25549),
(128528, 'zhTW', '我要求…暫停…', '', 25549),
(128527, 'zhTW', '快幫我！', '', 25549),
(128526, 'zhTW', '侍從，這個就交給你啦。', '', 25549),
(128525, 'zhTW', '宗師，別擔心我。我有帶水下呼吸藥劑。', '', 25549),
(128524, 'zhTW', '啊，游泳好舒服…我還記得有一次一口氣游到凱贊。那時羅庫宗師的腳掌變得皺巴巴，他快氣死了！', '', 25549),
(128523, 'zhTW', '我跟你說過那個猴人跟奶油派的故事嗎？呃…還是下次再說吧。', '', 25549),
(128522, 'zhTW', '聰明的釀酒大師知道什麼時候該喝點酒…更重要的是，知道什麼時候不該喝。', '', 25549),
(128521, 'zhTW', '宗師，別太在意失敗。重點是失敗後有沒有爬起來。', '', 25549),
(128520, 'zhTW', '如果想種一棵樹，最好的時機是五十年前。第二好的時機就是現在。', '', 25549),
(128519, 'zhTW', '有智慧的武僧會自己創造流派，這種東西可不是投票決定的。', '', 25549),
(128518, 'zhTW', '宗師，別忘了，風箏總是逆風飛行。', '', 25549),
(128517, 'zhTW', '一直說要改變卻不行動，就像在地上挖洞以為能抓到雲蛟。', '', 25549),
(128516, 'zhTW', '就算想嘲笑鱷魚有口臭，也要記得先過河再笑！', '', 25549),
(128515, 'zhTW', '宗師，我們快到了嗎？', '', 25549),
(128514, 'zhTW', '宗師，別忘了，無所事事難成大事。', '', 25549),
(128513, 'zhTW', '宗師，記得仔細聆聽所有的聲音。如果身邊的人總是同意你的意見，就沒辦法成長了。', '', 25549),
(128512, 'zhTW', '晚起的犛牛髒兮兮。', '', 25549),
(128511, 'zhTW', '再見囉！', '', 25549),
(128510, 'zhTW', '宗師，祝你好運！', '', 25549),
(128509, 'zhTW', '宗師，你最近應該少吃一點法力餐包…', '', 25549),
(128508, 'zhTW', '宗師，見到你真好。', '', 25549),
(128507, 'zhTW', '宗師，我們今天去哪裡？', '', 25549),
(128506, 'zhTW', '', '我準備好帶你前往英靈殿了。等你集合部隊並且做好準備，就跟我說一聲。', 25549),
(128505, 'zhTW', '我們放棄吧！不然會被燃燒軍團毀滅！', '', 25549),
(128504, 'zhTW', '誰也阻止不了我們！', '', 25549),
(128503, 'zhTW', '我們一起回漂流島吧…走！', '', 25549),
(128502, 'zhTW', '宗師，你果然武藝高強！能與你相伴是我的榮幸，我會像先前陪伴其他偉大的宗師一樣，一直追隨你。', '', 25549),
(128501, 'zhTW', '你具備身為宗師的智慧、品格和韌性。現在只剩下最後一個試煉…證明給我看，你的身手配得上宗師稱號！', '', 25549),
(128500, 'zhTW', '我看到你對卜大師的耐心，維護咕嚕摩的榮耀，對影潘盡心盡責，對錦魚人懷有信心。', '', 25549),
(128499, 'zhTW', '想著想著竟然出現一個影像，是個我沒見過但有意思的人…就是你！', '', 25549),
(128498, 'zhTW', '高宗師過世讓我太痛苦了，所以我在潘達利亞四處旅遊、冥想。', '', 25549),
(128497, 'zhTW', '班盧不在這裡？你確定？宗師，睜大眼睛看清楚…', '', 25549),
(128496, 'zhTW', '宗師！你找到班盧了嗎？', '', 25549),
(128495, 'zhTW', '宗師，我有個想法…', '', 25549),
(128494, 'zhTW', '線索到這裡就斷了。讓我想一下該怎麼辦。', '', 25549),
(128493, 'zhTW', '宗師，要繼續去找班盧了嗎？', '', 25549),
(128492, 'zhTW', '你去哪裡啦？喔，你在那裡…等我一下。謝謝，你對老人家真有耐心。', '', 25549),
(128491, 'zhTW', '不好意思，可以慢一點嗎？老人家動作總是比較慢。', '', 25549),
(128490, 'zhTW', '拜託，等等我！我這把老骨頭已經不比從前了。', '', 25549),
(128489, 'zhTW', '呼！這趟旅程很有趣，但也很累。抱歉，請讓我喘口氣。也許你可以問問這些咕嚕摩有沒有看過班盧。', '', 25549),
(128488, 'zhTW', '這裡有些掌印！嗯，會往什麼地方去呢…', '', 25549),
(128487, 'zhTW', '你找到什麼了？讓我看看…', '', 25549),
(128486, 'zhTW', '讓我們找找看有沒有班盧的蹤跡。', '', 25549),
(128485, 'zhTW', '宗師！請來這裡。', '', 25549),
(128484, 'zhTW', '如果我們去寂靜峰一趟，或許可以知道他在哪裡。', '', 25549),
(128483, 'zhTW', '自從燃燒軍團攻擊寂靜峰以後，就沒有人見過班盧了。他看到傷亡如此慘重…非常難過。', '', 25549),
(128482, 'zhTW', '數百年來，班盧一直是歷代宗師的專屬坐騎。這是他備感榮耀的職務！', '', 25549),
(128481, 'zhTW', '雪怒，也就是四位聖獸天尊之一的白虎，他有個兒子叫班盧。', '', 25549),
(128480, 'zhTW', '宗師！你能撥空聽老人家說個故事嗎？', '', 25549),
(128479, 'zhTW', '', '在那一夜之後，就剩我了。我是最後的血脈。', 25549),
(128478, 'zhTW', '', '我只能安慰自己，他們總有一天會受到諸神的制裁。', 25549),
(128477, 'zhTW', '', '他們每次都從我眼前溜走。我現在要專心處理手上的任務。', 25549),
(128476, 'zhTW', '', '他們又來了！亮出武器！', 25549),
(128475, 'zhTW', '', '沒用的懦夫！我要把你們一個一個全部殺光，然後找出背後的主使者。', 25549),
(128474, 'zhTW', '', '我永遠忘不了那個夜晚。母親在我面前被殺死。我在逃走之前，看到他們圍住了我弟弟。', 25549),
(128473, 'zhTW', '', '看來我還是無法逃避我的過去。', 25549),
(128472, 'zhTW', '', '先警告你，他們可能還在追殺我。', 25549),
(128471, 'zhTW', '', '我上一次來這裡，是為了躲避追殺我家人的刺客。', 25549),
(128470, 'zhTW', '', '樹上有動靜！小心！', 25549),
(128469, 'zhTW', '', '我會在瓦迪司陀等你。我們應該可以從那裡抵達斯寇亞胥。', 25549),
(128468, 'zhTW', '戰鬥領主，很榮幸跟你並肩作戰。我會到擎天堡回報。到時候見！', '', 25549),
(128467, 'zhTW', '<享受歡樂的夜晚，然後在神獵廳醒來。>', '<享受歡樂的夜晚，然後在神獵廳醒來。>', 25549),
(128466, 'zhTW', '美好的狩獵！這才是荒野的精神！今晚就盡情玩樂吧，有什麼事明天再想！', '', 25549),
(128465, 'zhTW', '%s在你靠近時大聲嘎嘎叫。', '', 25549),
(128464, 'zhTW', '乖，艾維希，別緊張。$n是我們的盟友。', '', 25549),
(128463, 'zhTW', '', '蔑潮的命運就在你手中。外來者，願諸神與你同在！', 25549),
(128462, 'zhTW', '', '你們祈倫托似乎有辦法把人直接送進歐丁的殿堂。快去！希望還來得及讓曦格琳恢復理智！', 25549),
(128461, 'zhTW', '', '外來者！曦格琳怒氣沖沖地跑去英靈殿找歐丁了，她這樣氣昏頭根本是找死！', 25549),
(128460, 'zhTW', '', '如果希望能合得天衣無縫，這個東西也得是夜裔製造的才行…還必須是新鑄的，不能有任何附件，拖泥帶水的最麻煩了。\n\n話說，埃薩應該能幫忙。他好像收了一個漂亮的夜裔學徒！嘖嘖嘖…\n\n請他介紹你們認識吧。', 25549),
(128459, 'zhTW', '要去哪裡找這種東西？', '要去哪裡找這種東西？', 25549),
(128458, 'zhTW', '', '他會回來的！他會統治…一切…', 25549),
(128457, 'zhTW', '', '到此結束了！千萬別讓…他…醒來…', 25549),
(128456, 'zhTW', '', '你就帶著世界的希望去死吧！', 25549),
(128455, 'zhTW', '', '我會繼續看守，但…這是為了誰呢？', 25549),
(128454, 'zhTW', '', '血肉很脆弱！', 25549),
(128453, 'zhTW', '', '必然的結果。', 25549),
(128452, 'zhTW', '', '不要破壞主人的傑作！', 25549),
(128451, 'zhTW', '', '底下的東西不是凡人該看的！', 25549),
(128450, 'zhTW', '', '絕對不可動搖的使命遇到無法抗衡的力量，我找到了…新的使命。', 25549),
(128449, 'zhTW', '', '數千年以來，我一直守著這裡…從不懈怠。然後，我聽到他的聲音。', 25549),
(128448, 'zhTW', '', '我不是第一個在聖殿設下防禦措施的人，但我擔心這些古老的泰坦看守者已經被人…動過了。萬事小心，我只能盡量保護你。', 25549),
(128447, 'zhTW', '', '凡人，殺了我吧！別讓欺詐者得逞！', 25549),
(128446, 'zhTW', '', '我的身體…還有心智…被控制了。我對不起造物者！', 25549),
(128444, 'zhTW', '我準備好參加盛宴了。', '我準備好參加盛宴了。', 25549),
(128443, 'zhTW', '', '歐丁和那些最偉大的獵人都在永獵之原等你。', 25549),
(128442, 'zhTW', '歡迎來到魔翼岩臺，斬魔者$p。懷惡族母在西邊的訓練區等你。', '', 25549),
(128441, 'zhTW', '', '你的惡魔靈視能幫你追蹤血跡。', 25549),
(128440, 'zhTW', '做得好！有你這樣的勇士守護世界，末日就不會降臨！', '', 25549),
(128439, 'zhTW', '勇士，你好。你來執行歐丁的任務嗎？', '', 25549),
(128438, 'zhTW', '風暴之怒在我體內翻騰！你做好準備了嗎？', '', 25549),
(128437, 'zhTW', '你躲得過我的斧頭嗎？！', '', 25549),
(128436, 'zhTW', '', '父親的血賦予我力量！', 25549),
(128435, 'zhTW', '準備好了就說一聲，勇士，我們一起翱翔天際。', '', 25549),
(128434, 'zhTW', '勇士，惡魔雜碎污染了這個地方。我們一定要消滅它！', '', 25549),
(128433, 'zhTW', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s開始引導|cFFFF0000|Hspell:237945|h[君父之血]|h|r！', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s開始引導|cFFFF0000|Hspell:237945|h[君父之血]|h|r！', 25549),
(128432, 'zhTW', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t附近地面出現數個|cFFFF0000|Hspell:237908|h[符文]|h|r。', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t附近地面出現數個|cFFFF0000|Hspell:237908|h[符文]|h|r。', 25549),
(128431, 'zhTW', '|TInterface\\Icons\\ABILITY_WHIRLWIND.BLP:20|t%s施展|cFFFF0000|Hspell:237866|h[劍刃風暴]|h|r !', '|TInterface\\Icons\\ABILITY_WHIRLWIND.BLP:20|t%s施展|cFFFF0000|Hspell:237866|h[劍刃風暴]|h|r !', 25549),
(128430, 'zhTW', '|TInterface\\Icons\\ABILITY_WARRIOR_RAMPAGE.BLP:20|t%s獲得|cFFFF0000|Hspell:237947|h[狂戰士之怒]|h|r！', '|TInterface\\Icons\\ABILITY_WARRIOR_RAMPAGE.BLP:20|t%s獲得|cFFFF0000|Hspell:237947|h[狂戰士之怒]|h|r！', 25549),
(128429, 'zhTW', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s施展|cFFFF0000|Hspell:237952|h[遠祖知識]|h|r！', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s施展|cFFFF0000|Hspell:237952|h[遠祖知識]|h|r！', 25549),
(128428, 'zhTW', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_SVALASORROWGRAVE.BLP:20|t幾個黑暗華爾琪列隊在戰場上|cFFFF0000|Hspell:237761|h[衝鋒]|h|r！', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_SVALASORROWGRAVE.BLP:20|t幾個黑暗華爾琪列隊在戰場上|cFFFF0000|Hspell:237761|h[衝鋒]|h|r！', 25549),
(128427, 'zhTW', '德雷克雅絕不投降！', '', 25549),
(128426, 'zhTW', '我的祖先會賦予我力量！', '', 25549),
(128425, 'zhTW', '', '好多寶藏，我怎麼能空手而回！', 25549),
(128424, 'zhTW', '', '我號令千軍萬馬，凡人！', 25549),
(128423, 'zhTW', '我準備好要開始了。', '我準備好要開始了。', 25549),
(128422, 'zhTW', '燃燒軍團會想辦法削弱我們，它們會像洪水沖刷峽谷一樣侵蝕我們，但是我們絕不投降。戰到最後一刻，直到再次見到陽光，是我們與生俱來的使命。', '', 25549),
(128421, 'zhTW', '別忘了好好研究符文。我不敢想像萬一失敗會發生什麼事！', '', 25549),
(128418, 'zhTW', '', '我們那裡見。快點，希望還來得及！', 25549),
(128417, 'zhTW', '', '大德魯伊！我需要你！', 25549),
(128416, 'zhTW', '', '祈倫托的法師能暫時開啟通往那裡的傳送門。你一定要結束這場混亂…不過我求你，可以的話，請饒他一命！', 25549),
(128415, 'zhTW', '', '在那裡，賽倫可以使用聚源虹膜對艾澤拉斯的地脈造成極大的破壞。', 25549),
(128414, 'zhTW', '', '我跟賽倫的其他學徒一起合作，尋找他的所在位置。我相信他就在永恆之眼！', 25549),
(128413, 'zhTW', '她平靜下來了，但還是很不安。我應該能連結到她。$b$b$n，你準備好了嗎？', '', 25549),
(128412, 'zhTW', '', '各位德魯伊，我們贏了！艾維娜塑像安全了。大德魯伊，希望有這個榮幸請你把塑像放回它該放的位置。', 25549),
(128411, 'zhTW', '', '好了，我們把塑像送回幻夢之林吧。', 25549),
(128410, 'zhTW', '到此為止！', '', 25549),
(128409, 'zhTW', '', '艾維娜，求求你！救救我們！', 25549),
(128408, 'zhTW', '', '這邊！', 25549),
(128407, 'zhTW', '', '可惡！', 25549),
(128406, 'zhTW', '小德魯伊，你太遲了！我們會好好利用德魯伊的飛行力量去毀滅達拉然！', '', 25549),
(128405, 'zhTW', '', '你錯囉！惡魔，去死吧！', 25549),
(128404, 'zhTW', '燃燒軍團！有了這個塑像，就連浮空之城都沒辦法保護那些膽小的凡人了！', '', 25549),
(128403, 'zhTW', '', '我們來看看怎麼回事…小聲一點！', 25549),
(128402, 'zhTW', '', '大德魯伊，我們艾蘇納見。', 25549),
(128401, 'zhTW', '', '這是怎…不能用飛行形態？失去塑像害我們也失去了飛行的能力！立刻傳送離開，幻夢之林集合！', 25549),
(128400, 'zhTW', '', '聖壇失守了。德魯伊，起飛！撤退！', 25549),
(128399, 'zhTW', '', '可惡！', 25549),
(128398, 'zhTW', '', '你這卑劣的…糟了！塑像！', 25549),
(128397, 'zhTW', '在燃燒軍團面前顫抖吧！', '', 25549),
(128396, 'zhTW', '', '死吧，惡魔敗類！', 25549),
(128395, 'zhTW', '', '你聽到了嗎？聖壇那邊有慘叫聲！我們得立刻趕回去！', 25549),
(128394, 'zhTW', '', '去你的前線，我要繞到後方去消滅它們的施法者和火砲。歡迎你一起來！', 25549),
(128393, 'zhTW', '', '大德魯伊！艾維娜聖壇又被攻擊了，到處都有敵人冒出來！先祖需要我們幫助！', 25549),
(128392, 'zhTW', '聽聽她想說什麼吧，麥格尼。', '聽聽她想說什麼吧，麥格尼。', 25549),
(128391, 'zhTW', '她的惡夢…還有恐懼…我們義不容辭！', '', 25549),
(128390, 'zhTW', '不要擔心。我們會保護你，絕對會！', '', 25549),
(128389, 'zhTW', '要是毀滅者還活著，她就危險了。難怪她這麼不安…', '', 25549),
(128388, 'zhTW', '懷惡族母，我準備好了。', '懷惡族母，我準備好了。', 25549),
(128387, 'zhTW', '願你安息，釀酒大師。', '', 25549),
(128386, 'zhTW', '', '愛瑪伊，我離開這個世界的時候到了。相信你已經成長很多，不再是個平凡的釀酒師了。', 25549),
(128385, 'zhTW', '宗師，你就是那道光！希望你在對抗燃燒軍團的時候堅持到底！', '', 25549),
(128384, 'zhTW', '我見到了幻象。燃燒軍團像海嘯般襲來…所有光都熄滅了…只剩一道光。', '', 25549),
(128383, 'zhTW', '我整個人，連靈魂…都在燃燒…', '', 25549),
(128382, 'zhTW', '鐵胴彭舒虛弱地咳著。', '', 25549),
(128381, 'zhTW', '我需要前往魔翼岩臺。', '我需要前往魔翼岩臺。', 25549),
(128380, 'zhTW', '向戰鬥領主致敬！Lok-tar!(勝利！)', '', 25549),
(128379, 'zhTW', '戰鬥領主，能跟你並肩作戰是我的榮幸。我們擎天堡見。', '', 25549),
(128378, 'zhTW', '', '他雖然很老，身體卻很強壯！他能撐過去的…對吧？', 25549),
(128377, 'zhTW', '', '我的力量可以拯救你！', 25549),
(128376, 'zhTW', '', '我的結界可以擋住她的魔法！', 25549),
(128375, 'zhTW', '', '我的結界可以保護你們！', 25549),
(128374, 'zhTW', '希望你順利擊敗亞加薩。祝你好運…', '', 25549),
(128373, 'zhTW', '看來法姆巴找到了你那位失蹤的法師。我現在要把他帶回來。', '', 25549),
(128372, 'zhTW', '|TINTERFACE\\ICONS\\Ability_BossFelLord_FelSpike.blp:20|t多瑪崔斯開始施展|cFFFF0404|Hspell:234107|h[混沌能量]|h|r！快躲起來！', '|TINTERFACE\\ICONS\\Ability_BossFelLord_FelSpike.blp:20|t多瑪崔斯開始施展|cFFFF0404|Hspell:234107|h[混沌能量]|h|r！', 25549),
(128371, 'zhTW', '法姆巴什麼線索都沒找到…', '', 25549),
(128370, 'zhTW', '法姆巴有發現了…', '', 25549),
(128369, 'zhTW', '我…很不舒服…', '', 25549),
(128368, 'zhTW', '很好…一等他們通過，那什麼愚蠢的「軍團之殞」就一點機會都沒有了。他們必死無疑。', '', 25549),
(128367, 'zhTW', '我等等就通知召喚師。等我下令，他們就會開啟傳送門。', '', 25549),
(128366, 'zhTW', '開戰的時刻快到了。你集結好部隊了嗎？', '', 25549),
(128365, 'zhTW', '保持戒備，勇士！我們要提防敵人，就像敵人也在提防我們！', '', 25549),
(128364, 'zhTW', '吃吧，多吃一點！敬荒野之夜！敬偉大的野獸！敬神獵手！', '', 25549),
(128363, 'zhTW', '哈哈，獵人，牠很喜歡你！從現在開始，你們無論在這裡或是真實世界都緊緊相連。我們先回去吃點東西，有什麼事明天早上再說！', '', 25549),
(128362, 'zhTW', '你願意讓狼鷹陪伴你嗎？', '', 25549),
(128361, 'zhTW', '你知道這個故事背後的意義嗎？我們因為有這些夥伴，才能變得比自己一個人時更強大。', '', 25549),
(128360, 'zhTW', '回來暖暖身子，優秀的獵人，今晚就盡情享受吧！', '', 25549),
(128359, 'zhTW', '只要她與你靈魂相連，霍肯沃尼爾在這世界上的所有子嗣都會聽從你的命令。', '', 25549),
(128358, 'zhTW', '連她都認可你，看來今晚霍肯沃尼爾的靈魂與我們同在！', '', 25549),
(128357, 'zhTW', '霍肯沃尼爾感受到你的狩獵能力，也知道你是野獸的同伴。去吧，獵人，她會考驗你。', '', 25549),
(128356, 'zhTW', '是霍肯沃尼爾，她從創世之初就在荒野間漫步了！', '', 25549),
(128355, 'zhTW', '這是什麼？最稀有、最高貴的靈魂過來了，這個靈魂已經好久沒有在荒野中出現了。', '', 25549),
(128354, 'zhTW', '看！是族母法瑞基和威武的維索尼爾，大地之霸和天空之王都出現了。', '', 25549),
(128353, 'zhTW', '神獵手，這些靈魂對你的評價很高！今晚出現的野獸都是傳說中最有名的。這確實是我所見過最光榮的荒野之夜！', '', 25549),
(128352, 'zhTW', '赫伯洛克生前敗在尖嘯淵獄之王拉努夫手下。看來今晚拉努夫的靈魂與我們同在！', '', 25549),
(128351, 'zhTW', '你頭頂上的巨鴞叫赫伯洛克。她的利爪讓所有野獸害怕，一到夜晚就紛紛躲起來，深怕被她發現。', '', 25549),
(128350, 'zhTW', '殘暴屠殺之王托爾獵殺過凱特林格。看來今晚托爾的靈魂與我們同在！', '', 25549),
(128349, 'zhTW', '前面那隻巨貓正在喝水，她叫凱特林格，動作敏捷，是凶猛的獵食者。小心她的利爪和尖牙！', '', 25549),
(128348, 'zhTW', '黑色風暴之王畢雍殺了蓋洛斯。看來今晚畢雍的靈魂與我們同在！', '', 25549),
(128347, 'zhTW', '這是巨大蟲母蓋洛斯的蹤跡。她生養的子孫繁多，挖的地道又深又長。', '', 25549),
(128346, 'zhTW', '赫提爾原本是巨岩絕壁之王海多爾的獵物。看來今晚海多爾的靈魂與我們同在！', '', 25549),
(128345, 'zhTW', '偉大的雄鹿赫提爾出現了！赫提爾的速度最快，頭上的角比長矛還尖銳。獵人，祝你好運！', '', 25549),
(128344, 'zhTW', '要在黑暗中找到這些靈敏的野獸並不容易，但真正的獵人總是有辦法追蹤獵物。', '', 25549),
(128343, 'zhTW', '獵人，等你吃飽就可以先行離席了。到荒野去吧，獵物在等著你！', '', 25549),
(128342, 'zhTW', '宴會現在開始！', '', 25549),
(128341, 'zhTW', '舉起酒杯，敬神獵手，敬野獸獵人！', '', 25549),
(128340, 'zhTW', '這個人必須獵殺傳說中的野獸，讓這些高貴的靈魂安息。', '', 25549),
(128339, 'zhTW', '必須在我們之中選出一個人，走進黑暗的荒野。', '', 25549),
(128338, 'zhTW', '在今晚，會有許多傳說野獸的靈魂在這片荒野中甦醒。', '', 25549),
(128337, 'zhTW', '各位朋友，又到荒野之夜了。', '', 25549),
(128336, 'zhTW', '燃燒軍團派出全知之眼來監視我們的軍事行動。太過份了！千萬別讓它們得到任何有用的情報。', '', 25549),
(128335, 'zhTW', '什麼都瞞不過燃燒軍團的。', '', 25549),
(128334, 'zhTW', '你聽到了嗎？是從這裡傳出來的！', '', 25549),
(128333, 'zhTW', '有人？快現身！', '', 25549),
(128332, 'zhTW', '%s的魔化炸彈爆炸了！', '%s的魔化炸彈爆炸了！', 25549),
(128331, 'zhTW', '', '我差點就沒命了…宗師，我永遠感激你！', 25549),
(128330, 'zhTW', '', '噁！沒想到我喝下這麼可怕的東西還會覺得開心！', 25549),
(128329, 'zhTW', '', '我剛才好虛弱…謝謝你幫助我！', 25549),
(128328, 'zhTW', '', '宗師，我祝福你！', 25549),
(128327, 'zhTW', '我差點就沒命了…宗師，我永遠感激你！', '', 25549),
(128326, 'zhTW', '噁！沒想到我喝下這麼可怕的東西還會覺得開心！', '', 25549),
(128325, 'zhTW', '我剛才好虛弱…謝謝你幫助我！', '', 25549),
(128324, 'zhTW', '宗師，我祝福你！', '', 25549),
(128323, 'zhTW', '', '嗯…真不錯啊…', 25549),
(128322, 'zhTW', '', '亞加薩…會很高興吧…', 25549),
(128321, 'zhTW', '', '真的嗎？上次的一點都不好玩。', 25549),
(128320, 'zhTW', '', '$c，一起玩呀！', 25549),
(128319, 'zhTW', '', '厄莉雅，別擔心…這個小東西看起來挺有活力的。$G他:她;應該能撐久一點。', 25549),
(128318, 'zhTW', '', '好！完成了。', 25549),
(128317, 'zhTW', '', '後退一點，要把草藥灌進酒裡了…', 25549),
(128316, 'zhTW', '你和盟友努力奮戰，讓我們士氣大振。你們證明了只要同心協力，就能拯救艾澤拉斯！', '', 25549),
(128315, 'zhTW', '', '唷，快來看亞加薩帶來的小東西，好像很好玩。', 25549),
(128314, 'zhTW', '燃燒軍團抵擋不了聖光的力量。尤其是像你這樣的勇士！', '', 25549),
(128313, 'zhTW', '英雄，今天你救了許多性命。我向你的英勇行為致上謝意。', '', 25549),
(128312, 'zhTW', '你為黑暗帶來了光明。謝謝你。', '', 25549),
(128311, 'zhTW', '勇士！聖光需要你！', '', 25549),
(128310, 'zhTW', '聖光保佑我們！盟友有麻煩了。拜託你，勇士，幫幫他們！', '', 25549),
(128309, 'zhTW', '集合部隊，英雄。你要拿出所有的本事面對接下來的威脅！', '', 25549),
(128308, 'zhTW', '你和你的盟友戰力相當驚人。我們只要團結合作，燃燒軍團必敗無疑！', '', 25549),
(128307, 'zhTW', '再次感謝你。我在想，看起來你也很習慣做這種事了！', '', 25549),
(128306, 'zhTW', '做得好！看你的好身手，讓我想到年輕時的自己。非常、非常年輕的自己。', '', 25549),
(128305, 'zhTW', '勇士，你救了許多人的性命。為此感到驕傲吧！', '', 25549),
(128304, 'zhTW', '做得好！我們暫時…逼退燃燒軍團了。', '', 25549),
(128303, 'zhTW', '集合部隊，勇士。出現了可怕的威脅，我們需要英雄！', '', 25549),
(128302, 'zhTW', '這裡！馬上過來！', '', 25549),
(128301, 'zhTW', '往這裡，勇士！', '', 25549),
(128300, 'zhTW', '斥候回報附近有非常危險的敵人。該發動攻擊了！', '', 25549),
(128299, 'zhTW', '勇士，附近的盟友遇上麻煩了。請你幫助他們！', '', 25549),
(128298, 'zhTW', '英雄！敵人已經入侵這個區域。要靠你才能解決他們！', '', 25549),
(128297, 'zhTW', '%s啐了一口唾沫。', '%s啐了一口唾沫。', 25549),
(128296, 'zhTW', '你擋不住我！', '', 25549),
(128295, 'zhTW', '我們來考驗你們的決心！', '', 25549),
(128294, 'zhTW', '我會毀了你們！', '', 25549),
(128293, 'zhTW', '你膽敢挑戰我？', '', 25549),
(128292, 'zhTW', '感受痛苦吧！', '', 25549),
(128291, 'zhTW', '給我站住！', '', 25549),
(128290, 'zhTW', '站好！', '', 25549),
(128289, 'zhTW', '不許動！', '', 25549),
(128288, 'zhTW', '把你砸成碎片！', '', 25549),
(128287, 'zhTW', '把你打爛！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128286, 'zhTW', '我會碾碎你！', '', 25549),
(128285, 'zhTW', '燒吧！在我的烈焰中燃燒吧！', '', 25549),
(128284, 'zhTW', '你會有…更多…苦難…', '', 25549),
(128283, 'zhTW', '主人會很高興的。', '', 25549),
(128282, 'zhTW', '我贏了榮耀…還讓這些凡人一敗塗地。', '', 25549),
(128281, 'zhTW', '又死了一個！', '', 25549),
(128280, 'zhTW', '可悲的凡人！', '', 25549),
(128279, 'zhTW', '不堪一擊！', '', 25549),
(128278, 'zhTW', '面對你的末日吧！', '', 25549),
(128277, 'zhTW', '我很高興看到你受苦！', '', 25549),
(128276, 'zhTW', '嚐嚐痛苦的滋味！', '', 25549),
(128275, 'zhTW', '入侵者！殺了你，我就能贏回主人的信任！', '', 25549),
(128274, 'zhTW', '', '這裡的能量充滿惡意。我們走！', 25549),
(128273, 'zhTW', '', '你是不是在找東西？我可以幫忙嗎？', 25549),
(128272, 'zhTW', '有東西要炸嗎？伊克斯的法杖可以派上用場！', '', 25549),
(128271, 'zhTW', '你們打了一場漂亮的仗，在接下來的戰鬥中，這種決心很重要。', '', 25549),
(128270, 'zhTW', '打倒這麼強大的敵人，可以提升士氣…也能讓惡魔嘗到恐懼的滋味。', '', 25549),
(128269, 'zhTW', '看來除了武力之外，還有其他方法可以重挫燃燒軍團。做得好！', '', 25549),
(128268, 'zhTW', '打得漂亮。看來燃燒軍團知道要怕你了！', '', 25549),
(128267, 'zhTW', '勇士，該你們上場了，集合部隊！', '', 25549),
(128266, 'zhTW', '附近有個可怕的敵人。讓它知道我們的恨意有多深！', '', 25549),
(128265, 'zhTW', '我們不是朋友嗎！你怎麼能這樣對我？這樣對我的家人？', '我們不是朋友嗎！你怎麼能這樣對我？這樣對我的家人？', 25549),
(128264, 'zhTW', '看來，我最後還是被魔毒害死了…', '看來，我最後還是被魔毒害死了…', 25549),
(128263, 'zhTW', '真想睡一整天。', '真想睡一整天。', 25549),
(128262, 'zhTW', '<打哈欠>又要上工了？', '<打哈欠>又要上工了？', 25549),
(128261, 'zhTW', '盟友需要你幫忙，勇士。我們要立刻行動！', '', 25549),
(128260, 'zhTW', '到底在哪裡？！', '到底在哪裡？！', 25549),
(128259, 'zhTW', '我沒記錯的話，應該是掉在這附近…', '我沒記錯的話，應該是掉在這附近…', 25549),
(128258, 'zhTW', '乾脆來找找看有什麼東西可以回收利用。', '乾脆來找找看有什麼東西可以回收利用。', 25549),
(128257, 'zhTW', '勇士！我們需要你的力量！準備戰鬥！', '', 25549),
(128256, 'zhTW', '$c，歡迎光臨雕銘師禮拜堂。要不要買些卷軸呀？', '', 25549),
(128255, 'zhTW', '燃燒軍團狠狠地蹂躪過這裡，一個活口也沒留下。', '燃燒軍團狠狠地蹂躪過這裡，一個活口也沒留下。', 25549),
(128254, 'zhTW', '又一個！不該跟這些「惡魔」結盟的。', '又一個！不該跟這些「惡魔」結盟的。', 25549),
(128253, 'zhTW', '<嘆氣>又少一個哨兵。', '<嘆氣>又少一個哨兵。', 25549),
(128252, 'zhTW', '<嘆氣>他走得太早了。', '<嘆氣>他走得太早了。', 25549),
(128251, 'zhTW', '孩子，願伊露恩指引你的靈魂。', '孩子，願伊露恩指引你的靈魂。', 25549),
(128250, 'zhTW', '他們絕對不會發現埋在這裡…', '他們絕對不會發現埋在這裡…', 25549),
(128249, 'zhTW', '等你到了，你會收到一件禮物，表示我的感激。希望禮物能派上用場。', '', 25549),
(128248, 'zhTW', '先知，我會送你回艾澤拉斯之心。謝謝你幫忙。', '', 25549),
(128247, 'zhTW', '要是分裂，我們會隨風四散。但是合作，就擁有颶風之力。讓這個議會永遠凝聚在一起吧。', '', 25549),
(128246, 'zhTW', '我現在是你們的馭風者，但你們卻在我的領域說三道四。算了，我們別再破壞這個議會的氣氛了。', '', 25549),
(128245, 'zhTW', '看來你們都受到先知啟迪，願意為我效忠了。很好。讓我來消除你們心中的疑慮吧。', '', 25549),
(128244, 'zhTW', '一旦他們發現你想做什麼，就會想盡辦法除掉你。我會給你一種有時效的祝福你，讓他們沒辦法這麼做。', '', 25549),
(128243, 'zhTW', '多說無益，惡魔。見識一下正牌指揮官軍隊的威力！', '', 25549),
(128242, 'zhTW', '哈哈哈哈哈！', '', 25549),
(128241, 'zhTW', '他們認為薩爾撒倫才是王位繼承者，真是愚蠢。我需要你去幫我說服他們。', '', 25549),
(128240, 'zhTW', '風能把我的意志吹拂到各個角落，但即使是我，也無法隨時出現在各處。在天空之牆，我的某些僕人還沒完全臣服於我的權威。', '', 25549),
(128239, 'zhTW', '攻擊！', '', 25549),
(128237, 'zhTW', '感謝你的協助，先知。相信你一定很快就能解決這個問題。', '', 25549),
(128236, 'zhTW', '先知$p，你還有任務在身，我不想耽誤你。', '', 25549),
(128235, 'zhTW', '', '我還有點事情要辦，待會再回到魔錘號碰面，斬魔者$p。', 25549),
(128234, 'zhTW', '', '讓我們先打理一下這隻蝙蝠，再帶到魔錘號去給你。和厄德里斯談談，他會把你送回船上。', 25549),
(128233, 'zhTW', '', '斬魔者，看來你已經完全馴服牠了。我要恭喜你！', 25549),
(128232, 'zhTW', '厄德里斯…你的魔法太弱了！我們…會…反抗！', '', 25549),
(128231, 'zhTW', '|TInterface\\Icons\\INV_SPEAR_08.BLP:20|t%s將|cFFFF0000|Hspell:235933|h[苦痛長矛]|h|r對準|cFFFF0000$n|r！', '', 25549),
(128230, 'zhTW', '', '有點…不對勁。這是哪裡？', 25549),
(128229, 'zhTW', '這是什麼感覺？一股黑暗力量…深入我的腦海…', '', 25549),
(128228, 'zhTW', '|TInterface\\Icons\\Ability_Rogue_BloodyEye:20|t痛咬的|cFFFF0000|Hspell:237726|h[厭惡凝視]|h|r鎖定了|cFFFF0000$n|r！', '|TInterface\\Icons\\Ability_Rogue_BloodyEye:20|t痛咬的|cFFFF0000|Hspell:237726|h[厭惡凝視]|h|r鎖定了|cFFFF0000$n|r！', 25549),
(128227, 'zhTW', '他一定會派手下阻止我們。我需要集中所有力量才能維持住傳送門。所以，你要幫我擋住他們。', '', 25549),
(128225, 'zhTW', '我會開啟傳送門。打開後，我需要你放置召喚石，把亞瑞克薩斯和憤怒戰馬引過來。', '', 25549),
(128224, 'zhTW', '', '你的靈視能力應該可以很容易追蹤到牠。但如果牠跑回繁殖地，要抓回來就會有點棘手了。蝙蝠這種生物有時候…精力太旺盛了。', 25549),
(128223, 'zhTW', '', '斬魔者，抱歉，牠逃走了。不過…你看，有血跡。這樣就好辦了。', 25549),
(128222, 'zhTW', '', '快，壓制住牠！', 25549),
(128221, 'zhTW', '', '要馴服這種強硬的生物，就要讓牠知道誰才是老大。當然，我是這方面的專家…這隻嘛…我覺得揍到牠懂就可以了。', 25549),
(128220, 'zhTW', '', '幾天前，這隻魔化蝙蝠攻擊了我們的營地。我們很少抓到成年的魔化蝙蝠，所以我堅持要留牠活口，沒有殺掉。', 25549),
(128219, 'zhTW', '', '伊利達瑞，把牠帶過來！', 25549),
(128218, 'zhTW', '', '斬魔者$p，歡迎來到魔化蝙蝠的棲地。今天有很優秀的樣本讓你使用。$b$b準備好的時候告訴我就行了。', 25549),
(128217, 'zhTW', '|TInterface\\ICONS\\Ability_FelArakkoa_FelDetonation_Green:20|t小心！想待在船上就別被|cFFFF0404|Hspell:238005|h[災變新星]|h|r擊中！', '', 25549),
(128216, 'zhTW', '', '我覺得充滿「活力」！', 25549),
(128215, 'zhTW', '', '丹密爾三兩下就解決了。你剛剛有聽到尖叫聲嗎？真是太好聽了！', 25549),
(128214, 'zhTW', '', '那些惡魔在四騎士面前根本沒轍。', 25549),
(128213, 'zhTW', '', '又死一群！送它們進棺材吧！', 25549),
(128212, 'zhTW', '', '你看到四騎士了嗎？他們居然能對抗這麼多惡魔。', 25549),
(128211, 'zhTW', '', '燃燒軍團會在丹密爾的陰影下發抖。當死亡從天而降，它們會開口求饒！', 25549),
(128210, 'zhTW', '', '這麼多惡魔…哼！沒關係，只要能控制丹密爾和她的幼龍，我們就沒什麼好怕的。', 25549),
(128209, 'zhTW', '', '準備讓秘密武器上場了嗎？', 25549),
(128208, 'zhTW', '惡魔，你們阻止不了我！士兵，起來！', '', 25549),
(128207, 'zhTW', '我等得夠久了。', '', 25549),
(128206, 'zhTW', '克索諾斯祭儀師開始施放災變！', '', 25549),
(128205, 'zhTW', '', '我不會讓卡魯歐的手下通過的。苦難與你同在。', 25549),
(128204, 'zhTW', '', '我應該能重新啟動傳送門。這裡有很多靈魂可以用。', 25549),
(128203, 'zhTW', '', '|TInterface\\Icons\\INV_Misc_Herb_Arrowbloom.blp:20|t%s將|cFFFF0000|Hspell:236304|h[無形箭]|h|r對準你！', 25549),
(128202, 'zhTW', '', '宗師，我跟你走。我們時間不多了！', 25549),
(128201, 'zhTW', '真是厲害。要是每支部隊都像你一樣優秀就好了。快點撤退，以免被敵方援軍抓到。', '', 25549),
(128200, 'zhTW', '馬里斯和他的寵物術士成功反轉了一道惡魔傳送門。通過傳送門，看看能造成什麼破壞。', '', 25549),
(128199, 'zhTW', '愛瑪伊，這…不是你的錯！但…我們得快點…找到解藥。已經有人倒下了…', '', 25549),
(128198, 'zhTW', '', '那個驚懼領主攻擊我，在慶典佳釀裡下毒，還偷走我的…', 25549),
(128194, 'zhTW', '', '我們需要回五晨寺！等你準備好就讓我知道！', 25549),
(128193, 'zhTW', '就算遇到危險心生膽怯，不要覺得自己是弱者，不要覺得這是缺點，這是再次回到戰場的機會。', '就算遇到危險心生膽怯，不要覺得自己是弱者，不要覺得這是缺點，這是再次回到戰場的機會。', 25549),
(128192, 'zhTW', '', '我閉著眼睛也能釀酒。可是織霧對我來說就很有挑戰性了。希望我有天也能很會織霧。', 25549),
(128191, 'zhTW', '', '四風峽的生活很平靜，對大多數的人來說這是好事，可是對我來說卻很無聊。我希望偶爾能發生點刺激的事。', 25549),
(128190, 'zhTW', '', '我的家族世世代代都在釀酒，所以我當然很厲害囉！可是，我一直很想嘗試做點別的東西。', 25549),
(128189, 'zhTW', '狂風再怎麼怒吼，終究有停下來的一天。別忘記你受過的訓練。', '狂風再怎麼怒吼，終究有停下來的一天。別忘記你受過的訓練。', 25549),
(128188, 'zhTW', '別鬆懈！讓盟友記得我們是誰，別讓那些惡魔瞧不起！', '別鬆懈！讓盟友記得我們是誰，別讓那些惡魔瞧不起！', 25549),
(128187, 'zhTW', '年輕的戰士，把頭抬起來。我們的旅程才剛開始。', '年輕的戰士，把頭抬起來。我們的旅程才剛開始。', 25549),
(128186, 'zhTW', '我們要堅持下去。', '我們要堅持下去。', 25549),
(128185, 'zhTW', '我知道傷口很痛，但許多年後我們回過頭來看，會想起為什麼而戰，想起付出的一切，正是這一切成就了我們。', '我知道傷口很痛，但許多年後我們回過頭來看，會想起為什麼而戰，想起付出的一切，正是這一切成就了我們。', 25549),
(128184, 'zhTW', '在這場風暴中很多戰士都找安全的地方躲起來了，但現在不是該躲起來的時候。我們必須舉起武器，直搗核心。', '在這場風暴中很多戰士都找安全的地方躲起來了，但現在不是該躲起來的時候。我們必須舉起武器，直搗核心。', 25549),
(128183, 'zhTW', '他們身體強壯，滿腔熱血比夏天的陽光還燙，只要休養一陣子就沒事了。但我們不能鬆懈！必須回到戰場！族人需要我們！', '他們身體強壯，滿腔熱血比夏天的陽光還燙，只要休養一陣子就沒事了。但我們不能鬆懈！必須回到戰場！族人需要我們！', 25549),
(128182, 'zhTW', '', '我的職責是…確保…你們都會消失！', 25549),
(128181, 'zhTW', '', '凡人哪會明白我的職責。這是神聖的使命，全心全意…服務主人！', 25549),
(128180, 'zhTW', '我們出發吧。', '我們出發吧。', 25549),
(128179, 'zhTW', '就是現在！這是你的命運！', '', 25549),
(128178, 'zhTW', '起身！沒錯…起身！', '', 25549),
(128177, 'zhTW', '力量在你體內流動！殺光惡魔！', '', 25549),
(128176, 'zhTW', '聽從指揮官的命令！', '', 25549),
(128175, 'zhTW', '起來，士兵們！', '', 25549),
(128174, 'zhTW', '這就是你們最強的獵人？那還真是完蛋了！', '', 25549),
(128173, 'zhTW', '又要來自討苦吃了嗎？我的獵犬會把你撕成碎片！', '', 25549),
(128172, 'zhTW', '我不怕任何野獸！燃燒軍團無窮無盡！', '', 25549),
(128171, 'zhTW', '我想離開死亡礦坑。', '我想離開死亡礦坑。', 25549),
(128170, 'zhTW', '', '釀酒大師！不！', 25549),
(128169, 'zhTW', '', '什麼…發生什麼事了？她在說什麼？宗師，我們得立刻回去！等你準備好就告訴我！', 25549),
(128168, 'zhTW', '我的工作完成了，小武僧…振虎會已經被消滅了！', '', 25549),
(128166, 'zhTW', '', '結果你看看…', 25549),
(128165, 'zhTW', '', '愛瑪伊，你真是傻得可愛。可惜你必須死！', 25549),
(128164, 'zhTW', '', '釀酒大師？你在說什麼？我們到處都找不到你！', 25549),
(128163, 'zhTW', '', '宗師，你比我想像的還厲害。看來我得親自對付你了！', 25549),
(128162, 'zhTW', '', '風暴蜜酒太神奇了！難怪燃燒軍團這麼怕它！', 25549),
(128161, 'zhTW', '', '我無法選擇命運…你們也是！', 25549),
(128160, 'zhTW', '', '感受靈魂分裂的痛苦吧！', 25549),
(128159, 'zhTW', '來吧，這個世界的勇士，過來讓我一刀砍死你！', '', 25549),
(128158, 'zhTW', '魔織者！解決這些入侵者！', '', 25549),
(128157, 'zhTW', '敵人首領倒下了，護盾也已經解除，藍龍隨時可以發動攻擊。他們會先去接你，然後再開始攻擊。', '', 25549),
(128156, 'zhTW', '這裡，快！我們現在就解決它們！', '', 25549),
(128155, 'zhTW', '飛龍會載我們前往燃燒軍團的船艦對付這一個區域的指揮官。解決他之後，牠們會在發動大規模攻擊前把你接回來。', '', 25549),
(128154, 'zhTW', '這一區的蒼藍龍承諾要協助我們抵抗燃燒軍團，但牠們需要你的協助。盡你所能幫助牠們吧。', '', 25549),
(128153, 'zhTW', '該前往破碎海岸了，丹密爾。', '該前往破碎海岸了，丹密爾。', 25549),
(128152, 'zhTW', '', '<丹密爾向你點點頭，眼神空泛。>', 25549),
(128151, 'zhTW', '', '燒毀你心愛的世界！', 25549),
(128150, 'zhTW', '為了高嶺的榮耀，我準備好了！[加入事件佇列]', '為了高嶺的榮耀，我準備好了！[加入事件佇列]', 25549),
(128149, 'zhTW', '我們最好動作快。天空到處都是這些噁心的怪獸。\n\n眼前就是直搗燃燒軍團核心的機會。我們要立刻趕往前線。', '', 25549),
(128148, 'zhTW', '做得好，英雄。你的偉大事蹟將在英靈殿內歌頌不絕！', '', 25549),
(128147, 'zhTW', '$ct，祝你一路順風。我們在那裡見。', '', 25549),
(128146, 'zhTW', '摧毀他們的大砲，粉碎他們的屏障！讓勇敢的華爾拉亞用真正的戰鬥精神和它們決戰！', '', 25549),
(128145, 'zhTW', '這些懦弱的惡魔只會躲在屏障後面。帶著我的祝福之錘，殺光它們！', '', 25549),
(128144, 'zhTW', '你以為躲在這間小酒坊就能脫身嗎？燃燒軍團什麼都知道！', '', 25549),
(128143, 'zhTW', '你再掙扎也沒有用，可悲的東西…', '', 25549),
(128142, 'zhTW', '', '燃燒軍團怎麼會知道風暴蜜酒？我們一直都很小心的…', 25549),
(128141, 'zhTW', '我不太喜歡魚人，但就算是魚人也不應該淪為燃燒軍團的工具。英雄，謝謝你。', '', 25549),
(128140, 'zhTW', '真是墮落！這些惡魔吸取無辜的靈魂，當作惡魔法術的能量。英雄，不能讓它們得逞！', '', 25549),
(128139, 'zhTW', '做得好！每一場勝利都非常重要。', '', 25549),
(128138, 'zhTW', '海岸上出現了魔化火焰！趕快攻擊，別讓危險繼續蔓延。', '', 25549),
(128137, 'zhTW', '大亂一場吧…', '', 25549),
(128136, 'zhTW', '哈…真是諷刺！惡魔這麼快就開始自相殘殺了！', '', 25549),
(128135, 'zhTW', '', '放肆的害蟲！你們努力也沒用！', 25549),
(128134, 'zhTW', '戰況對我們很有利！你去懸崖解決那個帶頭的惡魔，我守住天空以後就跟你會合。', '', 25549),
(128133, 'zhTW', '我是，呃…我們是…', '', 25549),
(128132, 'zhTW', '不准你把我的盟友變成毫無意志的奴隸！', '', 25549),
(128131, 'zhTW', '我要把索林尼爾復活成我的士兵，下一個就是丹密爾。', '我要把索林尼爾復活成我的士兵，下一個就是丹密爾。', 25549),
(128130, 'zhTW', '歡迎來到我的山峰，$ct。$b$b我是德雷克雅最後一個遠古看守者。許多盟友犧牲了性命，捍衛我們的盟約。我駐守在這裡，守護他們神聖的遺體。斯寇瓦德破壞了我們跟索林尼爾之間的結盟，但還是有人不聽從他的命令。$b$b一直到今天，索林尼爾還在為我們共同的目標而犧牲。每當他們的身軀在雪中倒下，這是我唯一能為他們做的。丹密爾是我的夥伴，我們用生命在守護這些遺體。', '', 25549),
(128129, 'zhTW', '', '我去拿火。這真令人期待啊！', 25549),
(128128, 'zhTW', '嗚哇！我先溜了！', '嗚哇！我先溜了！', 25549),
(128127, 'zhTW', '虛無黑暗啊，這是什麼東西…？', '虛無黑暗啊，這是什麼東西…？', 25549),
(128126, 'zhTW', '很痛耶！', '很痛耶！', 25549),
(128125, 'zhTW', '沒禮貌！', '沒禮貌！', 25549),
(128124, 'zhTW', '嗚！你為什麼這樣對我？', '嗚！你為什麼這樣對我？', 25549),
(128123, 'zhTW', '我休息一下就好…', '我休息一下就好…', 25549),
(128122, 'zhTW', '我看得見了！', '我看得見了！', 25549),
(128121, 'zhTW', '這…是哪裡？', '這…是哪裡？', 25549),
(128120, 'zhTW', '黑暗消散了！謝謝你，英雄。', '黑暗消散了！謝謝你，英雄。', 25549),
(128119, 'zhTW', '|TInterface\\ICONS\\Ability_IronMaidens_ConvulsiveShadows.blp:20|t墮落化身將|cFFFF0404|Hspell:236604|h[暗影之刃]|h|r對準你了！', '|TInterface\\ICONS\\Ability_IronMaidens_ConvulsiveShadows.blp:20|t墮落化身將|cFFFF0404|Hspell:236604|h[暗影之刃]|h|r對準你了！', 25549),
(128118, 'zhTW', '我想挑戰曦格琳。(免費)', '我想挑戰曦格琳。(免費)', 25549),
(128117, 'zhTW', '我想挑戰卡魯歐。(免費)', '我想挑戰卡魯歐。(免費)', 25549),
(128116, 'zhTW', '我想挑戰雷斯特。(免費)', '我想挑戰雷斯特。(免費)', 25549),
(128115, 'zhTW', '我想挑戰賽倫。(免費)', '我想挑戰賽倫。(免費)', 25549),
(128114, 'zhTW', '', '宗師，能跟你見面是我的榮幸。希望很快能再見到你！', 25549),
(128113, 'zhTW', '帶我去找亞加薩…(免費)', '帶我去找亞加薩…(免費)', 25549),
(128112, 'zhTW', '我會說 - ', '我會說 - ', 25549),
(128111, 'zhTW', '讓我 - ', '讓我 - ', 25549),
(128110, 'zhTW', '喂，你，快救我！', '喂，你，快救我！', 25549),
(128109, 'zhTW', '啊！', '啊！', 25549),
(128108, 'zhTW', '誰來救我！', '誰來救我！', 25549),
(128107, 'zhTW', '我的骨頭！', '我的骨頭！', 25549),
(128106, 'zhTW', '住手！', '住手！', 25549),
(128105, 'zhTW', '我不 - ', '我不 - ', 25549),
(128104, 'zhTW', '嗚啊啊啊！！！', '嗚啊啊啊！！！', 25549),
(128103, 'zhTW', '我覺得身上的肉快和骨頭分開了！', '我覺得身上的肉快和骨頭分開了！', 25549),
(128102, 'zhTW', '東西都變綠了，我什麼都看不到！', '東西都變綠了，我什麼都看不到！', 25549),
(128101, 'zhTW', '嗚啊啊啊！燒起來啦，燒起來啦！', '嗚啊啊啊！燒起來啦，燒起來啦！', 25549),
(128100, 'zhTW', '把我傳送到影歌。(免費)', '把我傳送到影歌。(免費)', 25549),
(128099, 'zhTW', '我想挑戰圖加‧血圖騰。(免費)', '我想挑戰圖加‧血圖騰。(免費)', 25549),
(128098, 'zhTW', '咕嚕嘎嗚咯咕！！', '', 25549),
(128097, 'zhTW', '咕嚕嘎莫咯咕！', '', 25549),
(128096, 'zhTW', '莫咕嚕嘎！', '', 25549),
(128095, 'zhTW', '咕嚕嘎咕莫咕嚕嘎卜！？', '', 25549),
(128094, 'zhTW', '咕嚕嘎咕嘎！', '', 25549),
(128093, 'zhTW', '莫嚕咕嚕咕嚕莫嚕咕嚕！', '', 25549),
(128092, 'zhTW', '咕嚕莫嚕咕嚕！？', '', 25549),
(128090, 'zhTW', '我想挑戰曦格琳。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰曦格琳。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(128089, 'zhTW', '', '抱歉，$n！先前你幫忙延緩的災難，有一些又開始形成威脅了。請來找我。', 25549),
(128088, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t你受到|cFFFF0000|Hspell:235117|h[靈魂動盪]|h|r影響！', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t你受到|cFFFF0000|Hspell:235117|h[靈魂動盪]|h|r影響！', 25549),
(128087, 'zhTW', '你要去哪裡？', '', 25549),
(128086, 'zhTW', '別想！', '', 25549),
(128085, 'zhTW', '不可能的！', '', 25549),
(128084, 'zhTW', '有我在，別想通過！', '', 25549),
(128083, 'zhTW', '不能讓你拿走我的船！鳥去操作大砲！猴子去操作帆！', '', 25549),
(128082, 'zhTW', '我能給的禮物，就是讓他們一無所知。他們要到最後才會明白這份禮物的代價。木已成舟，希望我做了正確的決定。', '', 25549),
(128081, 'zhTW', '這個決定壓得我喘不過氣，但每天看到他們無憂無慮的笑容，壓力就減輕了一點。', '', 25549),
(128080, 'zhTW', '他們可能永遠不會原諒我的決定，但至少他們會平安無事。我的家人暫時還很安全。', '', 25549),
(128079, 'zhTW', '啊，這是老家的天空！我還以為再也看不到了。', '', 25549),
(128078, 'zhTW', '欺詐者在我活著的時候不把我當一回事，走著瞧吧，看看到底誰才是贏家！', '', 25549),
(128077, 'zhTW', '小心！力量還在這個古老魔像裡面迴盪。趕快摧毀它，別讓燃燒軍團進一步強化。', '', 25549),
(128076, 'zhTW', '噁！這裡都是泰坦的臭味！', '', 25549),
(128075, 'zhTW', '它們運用靈魂能量的方式很有意思。要是能好好發揮，一定能達到很高的成就。', '', 25549),
(128074, 'zhTW', '我討厭幽靈！老是在講生前的事情。吞噬它們的靈魂，就不會再聽到它們囉唆了！', '', 25549),
(128073, 'zhTW', '納迦是被腐化的種族。他們雖然有秘法技能，但不像我們這樣天生靈巧。', '', 25549),
(128072, 'zhTW', '', '確實如此，叔叔。但至少，這是個開始…', 25549),
(128071, 'zhTW', '我知道我罪孽深重。', '', 25549),
(128070, 'zhTW', '', '惡魔！全都是惡魔！', 25549),
(128069, 'zhTW', '這傢伙把我當成收割力量的道具。這種短視近利的蠢蛋已經付出了代價！', '', 25549),
(128068, 'zhTW', '', '怎麼…會這樣？我的血好像在沸騰…我…我…', 25549),
(128067, 'zhTW', '%s眨了眨眼，看起來很疑惑。他的眼睛散發著魔化能量。', '', 25549),
(128066, 'zhTW', '惡魔的…信徒？', '', 25549),
(128065, 'zhTW', '啊，那是我以前的主人！可以報仇了！', '', 25549),
(128064, 'zhTW', '這個惡魔很強，但是很笨。抓來當手下也沒什麼用。', '', 25549),
(128063, 'zhTW', '我知道一些古老的咒語，能取得這個世界的生命之血。這裡就是釋放這股力量的最佳地點。', '', 25549),
(128062, 'zhTW', '你感覺到了嗎？這個世界的生命之血，就在這地表下流動。', '', 25549),
(128061, 'zhTW', '我們到了，這裡就是笨蛋送死的地方。記住，勇氣是不能取代力量的。', '', 25549),
(128060, 'zhTW', '你比我們剛見面的時候進步很多。再鍛鍊個幾千年，你就能跟我最優秀的學徒平起平坐了。', '', 25549),
(128059, 'zhTW', '這裡跟阿古斯好像…殘缺、破爛又扭曲。害我現在很想家！', '', 25549),
(128058, 'zhTW', '你上次差點就死在這裡了。這次有我在算你好運。', '', 25549),
(128057, 'zhTW', '你聞到血肉燒焦的味道了嗎？啊，這是家的味道！', '', 25549),
(128056, 'zhTW', '這裡只是燃燒軍團的一點點兵力而已。可怕的還在後頭呢。', '', 25549),
(128055, 'zhTW', '燃燒軍團征服了這片海岸，而我們很快就會征服燃燒軍團！', '', 25549),
(128054, 'zhTW', '', '你可以用我的死亡之門，或者自己開一個。總之，亞榭洛見。', 25549),
(128053, 'zhTW', '', '我還有點昏昏沉沉的，但戰鬥…沒有問題。', 25549),
(128052, 'zhTW', 'Alana be''lendor! (你的末日到了！)', '', 25549),
(128051, 'zhTW', '美麗的女王要你死！', '', 25549),
(128050, 'zhTW', '我想挑戰卡魯歐。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰卡魯歐。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(128049, 'zhTW', '哈亞潭…打得…不好…', '', 25549),
(128048, 'zhTW', '哈亞潭…讓女王…失望了…', '', 25549),
(128047, 'zhTW', '開打啦！', '', 25549),
(128046, 'zhTW', 'Ash''thero sanguine！', '', 25549),
(128045, 'zhTW', '快！小朋友，快打！', '', 25549),
(128044, 'zhTW', 'Bal, lamer zhita! (死吧，地表的污穢生物！)', '', 25549),
(128043, 'zhTW', '', '死吧！殺啊！', 25549),
(128042, 'zhTW', '', '喂！你去幫我拿潮石！', 25549),
(128041, 'zhTW', '', '趕快去幫哈亞潭！', 25549),
(128040, 'zhTW', '', '來人！上啊！', 25549),
(128039, 'zhTW', '', '沒用的東西！搞不懂女王怎麼會這麼喜歡他！', 25549),
(128038, 'zhTW', '', '閉嘴，笨蛋！殺了他們！', 25549),
(128037, 'zhTW', '', '哈亞潭！打爛他們的骨頭！', 25549),
(128036, 'zhTW', '', '夠了，到此為止！看看納迦真正的力量吧！', 25549),
(128035, 'zhTW', '', '沒用的傢伙！難道我真的得弄髒自己的手嗎？', 25549),
(128034, 'zhTW', '', '廢物！你竟然讓女王失望？', 25549),
(128033, 'zhTW', '', '殺死入侵者！搶回我們的東西！', 25549),
(128032, 'zhTW', '', '這些蠢貨…自己把潮石送上來！女王早就預料到了！', 25549),
(128031, 'zhTW', '我想挑戰雷斯特。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰雷斯特。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(128030, 'zhTW', '我想挑戰賽倫。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰賽倫。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128028, 'zhTW', '做得好。惡魔死了，補給品也拿回來了，我們很快就能攻下破碎海岸。', '', 25549),
(128027, 'zhTW', '渺小的凡人，努力也沒用！你們還是要跪下…或倒下！', '', 25549),
(128026, 'zhTW', '', '我的寵物會把你整個吞掉！', 25549),
(128025, 'zhTW', '', '深海會吞噬你！', 25549),
(128024, 'zhTW', '', '你的靈魂屬於深海！', 25549),
(128023, 'zhTW', '', '感受深海的寒冷！', 25549),
(128022, 'zhTW', '', '你死到臨頭了！', 25549),
(128021, 'zhTW', '', '大海充滿力量！', 25549),
(128020, 'zhTW', '', '吃光血肉！', 25549),
(128019, 'zhTW', '', '吞噬他們！', 25549),
(128018, 'zhTW', '', '這種死法…不值得…', 25549),
(128017, 'zhTW', '', '噢！真丟臉…', 25549),
(128016, 'zhTW', '', '艾薩拉女王的統治，絕對屹立不搖！', 25549),
(128015, 'zhTW', '', '都過了一萬年了，凡人還是一樣…可悲！', 25549),
(128014, 'zhTW', '', '當魚餌吧你！', 25549),
(128013, 'zhTW', '', '拿去餵魚剛好！', 25549),
(128012, 'zhTW', '', '去死吧，凡人雜碎！', 25549),
(128011, 'zhTW', '', '我以艾薩拉之名，要你的命！', 25549),
(128010, 'zhTW', '掃蕩岸上的惡魔大軍，拿回那些補給品，補充我們的備用物資。', '', 25549),
(128009, 'zhTW', '在上次突襲行動留下的殘骸裡，可以找到能用來對抗燃燒軍團的重要物資。', '', 25549),
(128008, 'zhTW', '我很抱歉，德菈絲。我不敢請求你原諒，但我懇求你一定要幫助我。', '', 25549),
(128007, 'zhTW', '', '這…這是你造成的？你怎麼能…', 25549),
(128006, 'zhTW', '他們的靈魂被燃燒軍團控制，被迫聽從惡魔的指揮。', '', 25549),
(128005, 'zhTW', '結果，我立下的誓約卻讓祖先受到比死亡還悲慘的詛咒。', '', 25549),
(128004, 'zhTW', '聽我解釋！我只是想保護我的家人…', '', 25549),
(128003, 'zhTW', '', '奈洛斯？叔叔，請你解釋！', 25549),
(128002, 'zhTW', '我終於自由了！', '', 25549),
(128001, 'zhTW', '終於等到了！報仇…我能報仇了！', '', 25549),
(128000, 'zhTW', '你的靈魂好頑強，竟然能抵抗惡魔法術！', '你的靈魂好頑強，竟然能抵抗惡魔法術！', 25549),
(127999, 'zhTW', '遭譴者之顎在你接近欺詐者時開始拉扯。', '遭譴者之顎在你接近欺詐者時開始拉扯。', 25549),
(127998, 'zhTW', '', '英雄，謝謝你所做的一切。高嶺的人民感謝你。', 25549),
(127997, 'zhTW', '', '魔化圖騰就是在這裡接受惡魔的指令。消滅洞窟裡的邪惡生物，把它們的主人趕回扭曲虛空！', 25549),
(127996, 'zhTW', '', '是我的錯。看來這位傲慢的「女神」還是這裡的主人。唉呀…', 25549),
(127995, 'zhTW', '', '看守者，在盟友繼續向墓地推進時，我們得守住永夜聖殿！', 25549),
(127994, 'zhTW', '', '伊利丹，要是不小心砍到你還真是抱歉。這裡這麼多惡魔，每個都長得跟你差不多。', 25549),
(127993, 'zhTW', '', '背叛者，在我殺你之前，別被宰了！', 25549),
(127992, 'zhTW', '瑪翼夫，還活著嗎？', '', 25549),
(127991, 'zhTW', '這邊交給我。典獄官，沒有我在身邊，你撐得下去嗎？', '', 25549),
(127990, 'zhTW', '這個世界…屬於…燃燒軍團…', '', 25549),
(127989, 'zhTW', '我會燒光你的血肉！', '', 25549),
(127988, 'zhTW', '這就是燃燒軍團真正的力量！', '', 25549),
(127987, 'zhTW', '他們沒盾了！全部殺光！', '', 25549),
(127986, 'zhTW', '煉獄火！快打亂他們！', '', 25549),
(127985, 'zhTW', '惡魔，突破那面盾！', '', 25549),
(127984, 'zhTW', '燃燒軍團，把敵人全燒光！', '', 25549),
(127983, 'zhTW', '我的斧頭想砍人！', '', 25549),
(127982, 'zhTW', '', '在這座殘破的神殿裡還遺留著力量。一定要搶過來！快，進去裡面，得到力量。', 25549),
(127981, 'zhTW', '', '幽暗人影從大鍋中取出一瓶黏液。', 25549),
(127980, 'zhTW', '這傢伙…很強韌。無所謂，這些靈魂都會服侍主人。', '', 25549),
(127979, 'zhTW', '', '超強力跳躍！', 25549),
(127978, 'zhTW', '', '我沒有時間在這裡說廢話。我要閃亮退場了。', 25549),
(127977, 'zhTW', '', '你最好祈禱我們不會再見面。', 25549),
(127976, 'zhTW', '', '沒關係，我的目的已經達到了。', 25549),
(127975, 'zhTW', '', '那就是我！', 25549),
(127974, 'zhTW', '', '再說，要是你敢傷了我親愛的牛頭人一根寒毛，絕對會有人找你報仇…', 25549),
(127973, 'zhTW', '', '這麼弱小的傢伙怎麼可能阻止我們…', 25549),
(127972, 'zhTW', '', '你又要來破壞我們的計畫嗎？哈！', 25549),
(127971, 'zhTW', '', '喂，你！你是那個牛頭人提到的傢伙！', 25549),
(127970, 'zhTW', '你們竟然特地把盾送過來。我替基爾加丹道謝。', '', 25549),
(127969, 'zhTW', '', '你必須在欺詐者的地盤對付他，他的弱點在那裡。走，我們去嚐嚐他的靈魂吧！', 25549),
(127968, 'zhTW', '', '讓我助你一臂之力，擊敗這個對手。雖然它只有黑暗泰坦一小部分的力量，但要是沒有我，你必死無疑。', 25549),
(127967, 'zhTW', '', '入侵者腐化其他的入侵者…真老套。你不覺得哄他們去走對的路會更有用嗎？', 25549),
(127966, 'zhTW', '', '這些傲慢的上古精靈竟然這麼重視自己的靈魂。很高興能羞辱他們！', 25549),
(127965, 'zhTW', '', '看到強敵的神殿，被他自己信徒的靈魂糟蹋成這樣，真讓我覺得痛快。', 25549),
(127964, 'zhTW', '', '有時候納迦似乎對燃燒軍團搖尾乞憐。但他們效忠的女王，卻有更大的野心。', 25549),
(127963, 'zhTW', '', '深淵領主一向都是又大、又笨。燃燒軍團卻總是有辦法讓它們變得更大、更笨。', 25549),
(127962, 'zhTW', '', '這傢伙在你們的世界作亂很久了。他的詭計未必都順利成功。一旦奏效，總是會造成大災難。', 25549),
(127961, 'zhTW', '', '燃燒軍團的小卒把無價的知識破壞殆盡…很意外嗎？', 25549),
(127960, 'zhTW', '', '我能感受到世界的脈動在加快。世界之血很快就會淹沒一切。', 25549),
(127959, 'zhTW', '', '你的盟友覺得我對你造成了不良影響。但路都是你自己選的，我只是推了你一把。', 25549),
(127958, 'zhTW', '', '聖光希望你們乖乖聽話、停滯不前。但我給你自由和力量。別忘記我對你有多大方。', 25549),
(127957, 'zhTW', '', '你是個可造之材。之前持有我的人都不會像你這樣殺遍各地。我真的很佩服你的毅力。', 25549),
(127956, 'zhTW', '', '這個世界一直都不平靜，大災變、大崩裂、大肅清…你根本無從想像。', 25549),
(127955, 'zhTW', '', '在大崩裂之後，我花了很長的時間才回到地面上。納迦對各種神器真的非常執著。', 25549),
(127954, 'zhTW', '', '這些衝突只是泰坦在遠古的紛紛擾擾中留下來的餘波。無數軍隊在永無止盡的戰役中倒下。不過對你們來說，這點小打小鬧就很了不起了。', 25549),
(127953, 'zhTW', '', '這些微不足道的衝突只是要分散注意力而已。真正的戰鬥很快就會到來。', 25549),
(127952, 'zhTW', '我們…才是最後的…贏家…', '', 25549),
(127951, 'zhTW', '', '很久以前，深淵之神就是在這裡的一場大戰中輸給了七首之神。不過，對恩若司來說，就算輸了，他還是能從中掌握優勢。', 25549),
(127950, 'zhTW', '', '那座矗立在此地的惡魔建築，完全比不上這片土地以往的輝煌。', 25549),
(127949, 'zhTW', '', '這裡一直以來都是個充滿力量的地方。艾格文為此前來，在她之前還有精靈，在精靈之前，是食人妖。在更早之前…', 25549),
(127948, 'zhTW', '把盾交出來，我就讓你們死得痛快！', '', 25549),
(127947, 'zhTW', '真感謝你們幫我把盾送來啊！', '', 25549),
(127946, 'zhTW', '我玩膩了！沒有那個小玩意的話，看你們怎麼辦！', '', 25549),
(127945, 'zhTW', '看你們受苦的感覺真好！', '', 25549),
(127944, 'zhTW', '你們別想抵擋燃燒軍團的力量！', '', 25549),
(127943, 'zhTW', '小心暗影！', '', 25549),
(127942, 'zhTW', '逃？蠢蛋！你們掉進我的陷阱了！', '', 25549),
(127941, 'zhTW', '', '在喀丹斯戰役之後，似乎就沒有這種規模的屠殺了。那是很久以前的事了…', 25549),
(127940, 'zhTW', '', '這不就是你們凡人丟盡顏面的地方嗎？希望你這次的表現會好一點…', 25549),
(127939, 'zhTW', '', '這裡都是死亡…和強大的力量！', 25549),
(127938, 'zhTW', '你無處可逃了，惡魔！', '', 25549),
(127937, 'zhTW', '好大的脾氣啊，瑪翼夫。無所謂，你就盡你所能，乖乖跟著我走吧。', '', 25549),
(127936, 'zhTW', '', '伊利丹，你以為甩得掉我嗎？再亂跑我就拿鐐銬拴住你這頭野獸。', 25549),
(127935, 'zhTW', '我來找驚懼領主。你們來處理剩下的雜碎。', '', 25549),
(127934, 'zhTW', '惡魔擋住了前面的路，但他們擋不住我們的怒火。', '', 25549),
(127933, 'zhTW', '', '我繼續去追伊利丹。你們來對付這些怪物。', 25549),
(127932, 'zhTW', '', '伊利丹留下一堆爛攤子！別落單了…我們得殺掉惡魔清出一條路。', 25549),
(127931, 'zhTW', '', '伊利丹！這個自以為是的混帳！', 25549),
(127930, 'zhTW', '我們的貴賓終於到了。背叛者，我一直很想把你那兩支角從頭上拔下來！', '', 25549),
(127929, 'zhTW', '惡魔，無論你逃到哪裡，我都會找到你！', '', 25549),
(127928, 'zhTW', '成功了嗎？', '', 25549),
(127923, 'zhTW', '大法師，做得好！我一直都相信你會成功。向大法師致敬！向提里斯護法致敬！', '', 25549),
(127922, 'zhTW', '生意很好。$b$b真的很好。$b$b<納爾果收了幾個硬幣到口袋裡。>$b$b諾格弗格先生一定會很滿意。繼續好好努力！', '', 25549),
(127921, 'zhTW', '靈魂石已經放好了。試著用秘法矩陣來啟動防禦設施看看！', '', 25549),
(127920, 'zhTW', '', '啊，算了。等莫格萊尼看到我們飛上天，他會起雞皮疙瘩的！', 25549),
(127919, 'zhTW', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_LORDMARROWGAR:20|t%s一陣顫慄，吐出荒寂聚合體使靈魂導體超載！', '', 25549),
(127918, 'zhTW', '說得也是。', '說得也是。', 25549),
(127917, 'zhTW', '獸群奔竄到底是什麼引起的？', '獸群奔竄到底是什麼引起的？', 25549),
(127916, 'zhTW', '接下來的計畫是什麼？', '接下來的計畫是什麼？', 25549),
(127915, 'zhTW', '我看起來像術士嗎？我哪知道為什麼。可能是某種季節性狂奔吧，恐懼戰馬要遷移、或是繁衍的季節、或者要逃離什麼…$b$b說不定就只是想跑過這裡，妨礙我們輕易遞送美酒！', '', 25549),
(127914, 'zhTW', '簡單！你騎著酒桶下去就行了$b$b只要在步伐上下點功夫，就能躲過奔竄的野獸，把酒送到！我的師父以前總是說：「如果能在酒桶上躲過一批馬，就一定能躲過敵人的拳頭。」$b$b我受到的訓練比較…特殊。反正，跳到桶子上，一路滾下去就可以找到他們。路上小心別被馬匹撞到！', '', 25549),
(127913, 'zhTW', '真高興看到你啊！我們的兄弟姊妹正在底下奮戰，但他們快沒酒了！$b$b這些該死的野獸到處奔竄，害我們沒辦法直接把酒桶滾下去…$b$b我有個主意…', '', 25549),
(127912, 'zhTW', '', '|TInterface\\Icons\\Spell_Deathknight_Defile:20|t靈魂國度裡面沒有靈魂的時候，%s會施展|cFFFF0000|Hspell:236507|h[滅魂之影]|h|r！', 25549),
(127911, 'zhTW', '|TInterface\\Icons\\Spell_Deathknight_Defile:20|t實體國度裡面沒有靈魂的時候，%s會施展|cFFFF0000|Hspell:236507|h[滅魂之影]|h|r！', '', 25549),
(127910, 'zhTW', '', '同心協力，我們會擊碎無數惡魔的骨頭！', 25549),
(127909, 'zhTW', '', '|TInterface\\Icons\\SPELL_SHADOW_SHADESOFDARKNESS:20|t%s開始釋放大批的|cFFFF0000|Hspell:236075|h[哀嚎之魂]|h|r！', 25549),
(127908, 'zhTW', '', '|TInterface\\Icons\\ABILITY_WARLOCK_SOULLINK:20|t%s用|cFFFF0000|Hspell:236449|h[生死交織]|h|r鎖住生命精華！', 25549),
(127907, 'zhTW', '|TInterface\\Icons\\SPELL_WARLOCK_SOULBURN:20|t%s開始發出一連串的|cFFFF0000|Hspell:236011|h[折磨號哭]|h|r！', '', 25549),
(127906, 'zhTW', '', '|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|t%s召喚出強大的薩魯凱，命令牠以|cFFFF0000|Hspell:234621|h[巨顎噬敵]|h|r！', 25549),
(127905, 'zhTW', '', '|TInterface\\Icons\\Ability_Butcher_Whirl.blp:20|t%s開始施放|cFFFF0000|Hspell:232722|h[削切龍捲風]|h|r！', 25549),
(127904, 'zhTW', '擎天堡的華爾拉亞！為我們的英雄歡呼，讓聲音響徹雲霄吧！', '', 25549),
(127903, 'zhTW', '總算能喘口氣了。我手下的伊利達瑞可以接手防禦。', '', 25549),
(127902, 'zhTW', '我們需要所有人都上前線支援。又有一波惡魔來襲！', '', 25549),
(127901, 'zhTW', '', '燃燒軍團太輕敵，低估了大自然…還有你的韌性和毅力！', 25549),
(127900, 'zhTW', '', '高嶺的野生動物開始反抗惡魔了！消滅煉獄火，找出惡魔是從哪裡入侵的。', 25549),
(127899, 'zhTW', '為了雷霆圖騰！我的騎士會守護天空，地面交給你。', '', 25549),
(127898, 'zhTW', '', '打得好！我們的部隊獲…', 25549),
(127897, 'zhTW', '', '燃燒軍團朝高嶺進攻了！各處的盟友都遭到惡魔襲擊！勇士，你必須直搗燃燒軍團的核心，才能扭轉戰局。', 25549),
(127891, 'zhTW', '法師塔被摧毀了，但馬上就會修好。', '法師塔被摧毀了，但馬上就會修好。', 25549),
(127890, 'zhTW', '法師塔遭到攻擊！', '法師塔遭到攻擊！', 25549),
(127889, 'zhTW', '法師塔建造中。', '法師塔建造中。', 25549),
(127869, 'zhTW', '我會一路追到這些食人妖的巢穴，把風暴戰錘烈酒找回來！', '', 25549),
(127868, 'zhTW', '索林，快去找出偷走塞拉摩淡啤酒的野豬！', '', 25549),
(127867, 'zhTW', '喬娜、喬連，快去追回地精淡啤酒！有群可惡的傢伙把酒搶走了！', '', 25549),
(127866, 'zhTW', '他們把酒搶走了！', '', 25549),
(127865, 'zhTW', '我最多只能帶你到這裡。希望你的夥伴能助你通過接下來的考驗。', '', 25549),
(127864, 'zhTW', '怎麼回事…我怎麼了？', '', 25549),
(127863, 'zhTW', '我…好想吐。', '', 25549),
(127862, 'zhTW', '那個東西…它入侵我的腦袋。我阻止不了它！', '', 25549),
(127861, 'zhTW', '我…我在哪裡？', '', 25549),
(127860, 'zhTW', '我的頭…發生了什麼事？', '', 25549),
(127859, 'zhTW', '發…發生什麼事了？這裡不是神獵廳！', '', 25549),
(127858, 'zhTW', '接好了！', '', 25549),
(127857, 'zhTW', '來了！', '', 25549),
(127856, 'zhTW', '看！', '', 25549),
(127855, 'zhTW', '來囉！', '', 25549),
(127854, 'zhTW', '再閃啊！', '', 25549),
(127853, 'zhTW', '死亡礦坑裡面出現不尋常的動靜。\n\n我猜裡面被各種生物給佔據了。要不要去調查一下？', '', 25549),
(127852, 'zhTW', '帶我進入死亡礦坑。', '帶我進入死亡礦坑。', 25549),
(127836, 'zhTW', '我想捐獻戰爭物資來建造法師塔。', '我想捐獻戰爭物資來建造法師塔。', 25549),
(127835, 'zhTW', '有什麼能為你效勞的嗎？', '有什麼能為你效勞的嗎？', 25549),
(127834, 'zhTW', '你怎麼那麼小！這簡直像是跟兔子玩耍。', '', 25549),
(127833, 'zhTW', '我才不在乎你是什麼流派，對我而言都沒差。你馬上就會被我打倒了。', '', 25549),
(127832, 'zhTW', '真有趣，你明知道自己會輸，卻還是繼續戰鬥。', '', 25549),
(127831, 'zhTW', '把我傳送到下一個旅店。', '把我傳送到下一個旅店。', 25549),
(127830, 'zhTW', '今天真幸運，我們找到珠寶了！', '', 25549),
(127829, 'zhTW', '把飲料喝完！我們馬上就要走了！', '把飲料喝完！我們馬上就要走了！', 25549),
(127828, 'zhTW', '我完成修練了。', '我完成修練了。', 25549),
(127827, 'zhTW', '接下來就交給這些騎士吧。勇士，繼續戰鬥。', '', 25549),
(127826, 'zhTW', '我們的騎士在空中對抗燃燒軍團。去幫助那些被擊倒的人，我們必須守住這裡！', '', 25549),
(127825, 'zhTW', '', '你的勝利帶給大家希望。燃燒軍團別想佔領我們的土地！', 25549),
(127824, 'zhTW', '', '相信我，我會做好該做的事。', 25549),
(127823, 'zhTW', '', '我的意志不屈不撓！', 25549),
(127822, 'zhTW', '', '這只是小小的挫折。', 25549),
(127821, 'zhTW', '', '別管我。我等等跟你會合。', 25549),
(127820, 'zhTW', '', '弱者只能死。', 25549),
(127819, 'zhTW', '', '你只有死路一條。', 25549),
(127818, 'zhTW', '', '這就是你的命運。', 25549),
(127817, 'zhTW', '', '這下有意思了！', 25549),
(127816, 'zhTW', '', '我會親手殺死你！', 25549),
(127815, 'zhTW', '', '想跑就跑吧，你跑不了多遠的！', 25549),
(127814, 'zhTW', '', '我們一起保衛這片土地。', 25549),
(127813, 'zhTW', '', '我來這裡與你並肩作戰。', 25549),
(127812, 'zhTW', '', '神獵手，小心。我們不知道附近隱藏著什麼樣的危險。', 25549),
(127811, 'zhTW', '', '馬上住手，不然別怪迪賓不客氣了。', 25549),
(127810, 'zhTW', '', '你就快踩到我的底線了！', 25549),
(127809, 'zhTW', '', '你就只會這幾招嗎？', 25549),
(127808, 'zhTW', '', '你還真頑固啊。', 25549),
(127807, 'zhTW', '', '我比較喜歡你安靜的時候。', 25549),
(127806, 'zhTW', '', '你說，我在聽。', 25549),
(127805, 'zhTW', '', '萬事小心。', 25549),
(127804, 'zhTW', '', '保持警戒。', 25549),
(127803, 'zhTW', '', '再會。', 25549),
(127802, 'zhTW', '', '有什麼事嗎？', 25549),
(127801, 'zhTW', '', '有什麼我能幫忙的？', 25549),
(127800, 'zhTW', '', '嗯？', 25549),
(127799, 'zhTW', '以黑穫議會之名，我會做好該做的事。', '', 25549),
(127798, 'zhTW', '見識我的力量！', '', 25549),
(127797, 'zhTW', '我不想拖累你。', '', 25549),
(127796, 'zhTW', '我沒有力量…', '', 25549),
(127795, 'zhTW', '讓我恢復一下力量。', '', 25549),
(127794, 'zhTW', '真是太簡單了。', '', 25549),
(127793, 'zhTW', '我們變強了！', '', 25549),
(127792, 'zhTW', '我們的力量無以倫比。', '', 25549),
(127791, 'zhTW', '這就是你的末日！', '', 25549),
(127790, 'zhTW', '你敵不過我們的力量！', '', 25549),
(127789, 'zhTW', '感受黑穫議會的力量！', '', 25549),
(127788, 'zhTW', '殺死敵人！', '', 25549),
(127787, 'zhTW', '這世界還有好多力量等我去吸取。', '', 25549),
(127786, 'zhTW', '能跟強者一起戰鬥是我的榮幸。', '', 25549),
(127785, 'zhTW', '裘貝卡應該把你放逐的。', '', 25549),
(127784, 'zhTW', '你真的想喚醒惡魔嗎？', '', 25549),
(127783, 'zhTW', '我可不是好惹的！', '', 25549),
(127782, 'zhTW', '黑穫議會的領袖可不會這樣浪費時間！', '', 25549),
(127781, 'zhTW', '你到底有什麼問題？', '', 25549),
(127780, 'zhTW', '下次見了。', '', 25549),
(127779, 'zhTW', '保重。', '', 25549),
(127778, 'zhTW', '一路順風。', '', 25549),
(127777, 'zhTW', '嗯？', '', 25549),
(127776, 'zhTW', '需要我幫忙嗎？', '', 25549),
(127775, 'zhTW', '你好。', '', 25549),
(127774, 'zhTW', '', '沒想到還有比羅蘭更煩的人。', 25549),
(127773, 'zhTW', '', '我不會輕易放過你的。', 25549),
(127772, 'zhTW', '', '滾出我的視線！', 25549),
(127771, 'zhTW', '', '滾！', 25549),
(127770, 'zhTW', '', '你以為自己很聰明嗎？', 25549),
(127769, 'zhTW', '', '你快讓我失去耐性了。', 25549),
(127768, 'zhTW', '', '再見。', 25549),
(127767, 'zhTW', '', '願暗影籠罩著你。', 25549),
(127766, 'zhTW', '', '保重。', 25549),
(127765, 'zhTW', '', '需要我幫忙嗎？', 25549),
(127764, 'zhTW', '', '你需要什麼嗎？', 25549),
(127763, 'zhTW', '', '嗯？', 25549),
(127762, 'zhTW', '', '這應該很有意思…', 25549),
(127761, 'zhTW', '', '這只是一時的挫折。', 25549),
(127760, 'zhTW', '', '真是…沒想到…', 25549),
(127759, 'zhTW', '', '給我一點時間。', 25549),
(127758, 'zhTW', '', '別再掙扎了。', 25549),
(127757, 'zhTW', '', '這是你自找的。', 25549),
(127756, 'zhTW', '', '回歸虛無吧。', 25549),
(127755, 'zhTW', '', '從這個世界消失吧！', 25549),
(127754, 'zhTW', '', '見識我的怒火吧！', 25549),
(127753, 'zhTW', '', '你的死期到了！', 25549),
(127752, 'zhTW', '', '暗影會吞沒我們的敵人！', 25549),
(127751, 'zhTW', '', '我來幫忙了。', 25549),
(127750, 'zhTW', '', '你不需要獨自作戰。', 25549),
(127749, 'zhTW', '', '接下來有什麼驚喜呢？', 25549),
(127748, 'zhTW', '快點住手。', '', 25549),
(127747, 'zhTW', '這樣不好玩。', '', 25549),
(127746, 'zhTW', '我的罪孽這麼深重嗎？', '', 25549),
(127745, 'zhTW', '你沒有其他事情要做嗎？', '', 25549),
(127744, 'zhTW', '難道這就是我的報應嗎？', '', 25549),
(127743, 'zhTW', 'Ande''thoras-ethil (願你忘憂無慮。)', '', 25549),
(127742, 'zhTW', 'Elune-Adore (願伊露恩與你同在。)', '', 25549),
(127741, 'zhTW', '一路順風。', '', 25549),
(127740, 'zhTW', '很高興見到你。', '', 25549),
(127739, 'zhTW', '你好啊，朋友。', '', 25549),
(127738, 'zhTW', 'Ishnu-alah (祝你好運。)', '', 25549),
(127737, 'zhTW', '', '要是你不肯，我就讓你好看！勇士，幫我解決掉這個無賴！', 25549),
(127736, 'zhTW', '', '你不願意跟我一對一決鬥嗎？我們的祖先若地下有知，絕對不會容忍這種事！', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(127735, 'zhTW', '蠢女孩。這些骸骨聽從的是我，不是你那虛假的榮耀！', '', 25549),
(127734, 'zhTW', '我會做好該做的事。', '', 25549),
(127733, 'zhTW', '我為大領主而戰！', '', 25549),
(127732, 'zhTW', '你先走，不用擔心我。', '', 25549),
(127731, 'zhTW', '我要休息一下。', '', 25549),
(127730, 'zhTW', '我有點虛弱…', '', 25549),
(127729, 'zhTW', '我們意志堅定。', '', 25549),
(127728, 'zhTW', '我們會贏的。', '', 25549),
(127727, 'zhTW', '審判必須又快又準。', '', 25549),
(127726, 'zhTW', 'Bandu thoribas! (準備受死！)', '', 25549),
(127725, 'zhTW', '我不會手下留情！', '', 25549),
(127724, 'zhTW', '接受審判吧！', '', 25549),
(127723, 'zhTW', '我會證明自己的價值。', '', 25549),
(127722, 'zhTW', '大領主，與你同行是我的榮幸。', '', 25549),
(127721, 'zhTW', '我一定要贖罪。', '', 25549),
(127720, 'zhTW', '', '事實上，還真的有。\n\n有個流浪的女盾侍最近剛來到這裡，她在城鎮外設置了營地。她在買完補給品之後就離開了，而且完全避免跟任何人有眼神接觸。\n\n我原本打算去找她，問清楚她的來意，但很歡迎你替我去做這件事。她的營地就在東邊的海岸上。', 25549),
(127719, 'zhTW', '有看到奇怪的維酷人經過這裡嗎？', '有看到奇怪的維酷人經過這裡嗎？', 25549),
(127718, 'zhTW', '', '我會盯著你，外來者。', 25549),
(127717, 'zhTW', '', '我對法卓汀的華爾琪拉預言瞭若指掌，但是沒有讀過文本。讓我看看你找到的卷軸。\n\n<布蘭娜仔細閱讀卷軸上的文字。>\n\n如果卷軸說的是真的，這就代表斯寇瓦德的繼承人就在這裡！不管華爾琪拉相信什麼，把她從這裡趕出去，就是幫我們一個大忙。\n\n去俯瞰整座城鎮的高塔找茵維爾德。她監視著往返詹德維克的一切事物，應該會知道最近是否有可疑人士來到這裡。', 25549),
(127716, 'zhTW', '司洛迪說，你能幫忙找這些卷軸所提到的維酷人。', '司洛迪說，你能幫忙找這些卷軸所提到的維酷人。', 25549),
(127715, 'zhTW', '', '我聽到司洛迪的號角了。我想你就是他宣告會來到此地的外來者？', 25549),
(127714, 'zhTW', '噢，可憐的幼狼！至少牠們不會變成燃燒軍團的奴隸了。勇士，謝謝你。', '', 25549),
(127713, 'zhTW', '我不知道你為什麼要研究維酷人的預言，不過你身上的卷軸似乎真的有點來頭。\n\n女祭司布蘭娜是村子裡最博學的人。或許你該去找她問問？', '', 25549),
(127712, 'zhTW', '我對預言知道的不多，但是在斯寇瓦德死後，詹德維克出現了不少新面孔。\n\n你應該去找女祭司布蘭娜談話。她就住在城鎮中心。或許她知道你所說的這個預言。', '', 25549),
(127711, 'zhTW', '我正在尋找卷軸中提到的那名維酷人。', '我正在尋找卷軸中提到的那名維酷人。', 25549),
(127710, 'zhTW', '小心行事，$c。詹德維克的維酷人很提防外來者。', '', 25549),
(127709, 'zhTW', '$c，你好。\n\n我知道托莉爾的敕令，我不會傷害你。', '', 25549),
(127708, 'zhTW', '燃燒軍團正在腐化嚎風丘陵的狼，任由牠們攻擊天角。快去打斷儀式！', '', 25549),
(127707, 'zhTW', '你竟敢打擾我？', '', 25549),
(127706, 'zhTW', '你好像…哪裡…怪怪的。', '', 25549),
(127705, 'zhTW', '別想偷東西。我們會盯著。我們隨時都在盯著。', '', 25549),
(127704, 'zhTW', '$ct，你好。我對燃燒軍團的怒火永無止盡！', '', 25549),
(127703, 'zhTW', '你是不是想偷偷帶走什麼東西？', '', 25549),
(127702, 'zhTW', '快回去工作，否則我派你去刷坑洞裡的籠子。', '', 25549),
(127701, 'zhTW', '你竟敢跟我說話？', '', 25549),
(127700, 'zhTW', '你要懂得分寸，不然我給你好看。', '', 25549),
(127699, 'zhTW', '回去工作。', '', 25549),
(127698, 'zhTW', '啊，$n，我就知道你會來。我快準備好了，一起對抗燃燒軍團吧。', '', 25549),
(127697, 'zhTW', '我已經兩次差點被惡魔殺掉了。絕對不會再有下一次。', '', 25549),
(127696, 'zhTW', '', '影尊，你不會後悔的。無論是燃燒軍團的惡魔或走狗，擋我路的，全都得死！', 25549),
(127695, 'zhTW', '準備受死吧！', '準備受死吧！', 25549),
(127694, 'zhTW', '你的努力都白費了。', '你的努力都白費了。', 25549),
(127693, 'zhTW', '你竟敢干擾燃燒軍團的僕從！', '你竟敢干擾燃燒軍團的僕從！', 25549),
(127692, 'zhTW', '你的死期到了。', '你的死期到了。', 25549),
(127691, 'zhTW', '你的寶物又小又不起眼。你應該全部交給我，好讓我「丟掉它們」。', '', 25549),
(127690, 'zhTW', '誰派你來的？是布啃嗎？跟他說他的亮晶晶是落牙拿走的，不是我！', '', 25549),
(127689, 'zhTW', '', '恐怖圖騰一定會再次變強，沒有人能阻止我們！', 25549),
(127688, 'zhTW', '偷唇和佻舌被送入迷宮後，就再也沒有消息。快走，不然審查者會把我們兩個也送進去。', '', 25549),
(127687, 'zhTW', '你的臉是怎麼回事？', '', 25549),
(127686, 'zhTW', '噓…別讓審查者聽見。', '', 25549),
(127685, 'zhTW', '別碰我的寶物！', '', 25549),
(127684, 'zhTW', '你的鼻子紅到讓人好想咬一口。', '', 25549),
(127683, 'zhTW', '才扛這點東西就算多嗎？哈！隨便什麼雜碎爛貨扛得都比你還多。', '', 25549),
(127682, 'zhTW', '', '我覺得煩了。有話快說，不然就死吧。', 25549),
(127681, 'zhTW', '', '說！', 25549),
(127680, 'zhTW', '', '我受夠了這些兒戲。不說，就準備受死。', 25549),
(127679, 'zhTW', '', '惡魔，他們打算做什麼？', 25549),
(127678, 'zhTW', '', '不許違抗我。快說。', 25549),
(127677, 'zhTW', '', '你一定會交出我要的情報，惡魔。', 25549),
(127676, 'zhTW', '', '想對付燃燒軍團，你毫無勝算！', 25549),
(127675, 'zhTW', '', '我跟我的獵犬能輕易殺死你！', 25549),
(127674, 'zhTW', '因為我比你更了解惡魔的移動方式。繼續加油吧。', '', 25549),
(127673, 'zhTW', '你怎麼會比我先通過傳送門？', '你怎麼會比我先通過傳送門？', 25549),
(127672, 'zhTW', '變身？', '變身？', 25549),
(127671, 'zhTW', '原來那些該死的小偷是把偷走的玩意兒藏在這裡。$b$b既然我們都來了，乾脆拿回一點東西吧。我替你準備了一張偷竊清單。\n\n這時候通常會需要幻術師施展魔法，把你的外型變得像它們一樣。哼！幻象，外行的作法。\n\n我要把你直接「變成」那些東西。你融入角色的演技如何？', '', 25549),
(127670, 'zhTW', '做得很好。我們必須召開議會。只有結合大家的力量，才能制住力量這麼強的野獸。', '', 25549),
(127669, 'zhTW', '快，在憤怒戰馬逃走前駕馭牠！', '', 25549),
(127668, 'zhTW', '不可能…', '', 25549),
(127667, 'zhTW', '你休想得到憤怒戰馬，凡人！', '', 25549),
(127666, 'zhTW', '我要親手殺了你！', '', 25549),
(127665, 'zhTW', '你只不過解決了沒用的手下，我是不會讓你得逞的。', '', 25549),
(127664, 'zhTW', '他們瘋了嗎？！這樣會殺死所有人！', '', 25549),
(127663, 'zhTW', '侍僧們正在圍成儀式的法陣。無論如何，不能讓他們湊到足夠的人完成法陣！', '', 25549),
(127662, 'zhTW', '亞瑞克薩斯在用魔化護盾保護侍僧！你要先驅散護盾才能消滅他們！', '', 25549),
(127661, 'zhTW', '侍僧！快燒死這隻蟲子！', '', 25549),
(127660, 'zhTW', '術士，小心！凡人對惡魔獵犬的劇毒沒有抵抗力。不過這對你的惡魔來說不是問題！', '', 25549),
(127659, 'zhTW', '我的獵犬會撕下你們的血肉！', '', 25549),
(127658, 'zhTW', '什麼？！竟敢召喚我的戰馬？', '', 25549),
(127657, 'zhTW', '通道打開了，術士！啟動召喚石！', '', 25549),
(127656, 'zhTW', '怎麼回事？有凡人想窺探我的領域？', '', 25549),
(127655, 'zhTW', '啊，真高興再見到你，$n。', '', 25549),
(127654, 'zhTW', '目標，克索諾斯！', '', 25549),
(127653, 'zhTW', 'Rak-ath varus mir''enon！', '', 25549),
(127652, 'zhTW', '現在，一起撕開扭曲虛空，拿走屬於我們的東西！', '', 25549),
(127651, 'zhTW', '', '赫爾努拉斯會獵殺你，$c…', 25549),
(127650, 'zhTW', '', '我要拿你餵恐懼戰馬！', 25549),
(127649, 'zhTW', '等等…我在做什麼？祖麗娃會宰了我的！你快走開！', '等等…我在做什麼？祖麗娃會宰了我的！你快走開！', 25549),
(127648, 'zhTW', '去找祖麗娃…她從塔裡…監視著。', '去找祖麗娃…她從塔裡…監視著。', 25549),
(127647, 'zhTW', '你想找…我們首領？你說了算…沒問題…', '你想找…我們首領？你說了算…沒問題…', 25549),
(127646, 'zhTW', '…我在說什麼？死吧，術士！', '…我在說什麼？死吧，術士！', 25549),
(127645, 'zhTW', '…不…我不會…背叛燃燒軍團！', '…不…我不會…背叛燃燒軍團！', 25549),
(127644, 'zhTW', '…夠了！我會殺了你，惡魔！', '…夠了！我會殺了你，惡魔！', 25549),
(127643, 'zhTW', '首領嗎？我什麼都聽你的…', '首領嗎？我什麼都聽你的…', 25549),
(127642, 'zhTW', '什麼？你認為我不配當首領嗎？', '什麼？你認為我不配當首領嗎？', 25549),
(127641, 'zhTW', '我們的首領…？我不知道…', '我們的首領…？我不知道…', 25549),
(127640, 'zhTW', '嗯…你這樣說也沒錯啦…', '嗯…你這樣說也沒錯啦…', 25549),
(127639, 'zhTW', '天哪…你的足蹄…好美喔…', '天哪…你的足蹄…好美喔…', 25549),
(127638, 'zhTW', '喔…太棒了…等等，你想做什麼…？', '喔…太棒了…等等，你想做什麼…？', 25549),
(127637, 'zhTW', '有了你所收集的東西，我們就快做好捕捉憤怒戰馬的準備了。\n\n在我們建造傳送門的時候，你應該專心尋找能吸引亞瑞克薩斯和憤怒戰馬通過傳送門的誘餌。', '', 25549),
(127636, 'zhTW', '為了引出亞瑞克薩斯，我們需要製造一個能穩定連結克索諾斯的傳送門。這比開啟一般的傳送門要困難許多，我們會需要大量的資源。', '', 25549),
(127635, 'zhTW', '現在，我們得去準備一下。', '', 25549),
(127634, 'zhTW', '太好了。我就知道你不會讓我失望。', '', 25549),
(127633, 'zhTW', '憤怒戰馬是我的！', '憤怒戰馬是我的！', 25549),
(127632, 'zhTW', '雖然在蟲舌魔身上問不出這種戰馬的情報，不過顯然赫爾努拉斯只造出一隻。他把牠送給他最厲害的將軍，魔化騎士亞瑞克薩斯。難辦的是，亞瑞克薩斯幾乎不離開克索諾斯，只從遠遠的地方坐鎮指揮。\n\n不過，我認為可以引他出來。這就是我需要你幫忙的地方。\n\n你準備好接受這個挑戰了嗎？', '', 25549),
(127631, 'zhTW', '繼續說…', '繼續說…', 25549),
(127630, 'zhTW', '我就說重點了：\n\n自從我在燃燒平原被黑石獸人「請走」之後，我就繼續在暗中研究克索諾斯的恐懼戰馬。我在某一次的儀式中抓到一隻奇怪的惡魔，在這裡我們叫它「蟲舌魔」。\n\n經過好幾個星期的審問，這隻惡魔說出赫爾努拉斯領主想為克索諾斯的魔化騎士製造出更強大的戰駒。\n\n這種戰駒的名字是憤怒戰馬。', '', 25549),
(127629, 'zhTW', '你找我有什麼事？', '你找我有什麼事？', 25549),
(127628, 'zhTW', '很高興認識你，虛空領主。', '', 25549),
(127627, 'zhTW', '到懼痕裂隙找我，我會跟你解釋。', '', 25549),
(127626, 'zhTW', '從我們上次探索克索諾斯到現在已經過了很久，現在又有機會重返這個恐懼戰馬的世界。', '', 25549),
(127625, 'zhTW', '你好，術士。我來找你，是因為你一定會想知道我發現了什麼。', '', 25549),
(127623, 'zhTW', '好好看著這群惡魔眼神裡的憤怒如何轉變成恐懼。我們會擊潰它們！', '', 25549),
(127622, 'zhTW', '這惡魔死一千次都不嫌多。它的邪惡主人不會輕易放過它的。', '', 25549),
(127621, 'zhTW', '燃燒軍團逃不了的。一定要把他們殺光！', '', 25549),
(127620, 'zhTW', '贏得漂亮。你展現出堅定的決心。', '', 25549),
(127619, 'zhTW', '好好享受消滅燃燒軍團走狗的滋味吧！', '', 25549),
(127618, 'zhTW', '這場遊戲很快就會結束。燃燒軍團一定會滅亡。', '', 25549),
(127617, 'zhTW', '每攻擊燃燒軍團一次，就更接近擊敗它們的那一天。', '', 25549),
(127616, 'zhTW', '你的力量有驚人的成長。燃燒軍團知道你的名字…而且感到懼怕。', '', 25549),
(127615, 'zhTW', '又來一波燃燒軍團的手下。消滅它們！', '', 25549),
(127614, 'zhTW', '沒錯，這種臭味一定是燃燒軍團那群雜碎。找出源頭，消滅它們！', '', 25549),
(127613, 'zhTW', '我感覺到附近有敵人。趕快攻擊！', '', 25549),
(127612, 'zhTW', '邪惡的敵人來了！做你該做的事！', '', 25549),
(127611, 'zhTW', '目標接近了。把這雜碎送回扭曲虛空吧！', '', 25549),
(127610, 'zhTW', '這個燃燒軍團的走狗低估了你的力量。讓它知道自己錯了。', '', 25549),
(127609, 'zhTW', '燃燒軍團又派出一群手下。立刻消滅這股威脅。', '', 25549),
(127608, 'zhTW', '這裡到處都是該死的惡魔。有個主要目標出現了！', '', 25549),
(127607, 'zhTW', '', '很好，又少了一個威脅！', 25549),
(127606, 'zhTW', '', '勝利一點一滴累積起來，就能擊退燃燒軍團。做得好！', 25549),
(127605, 'zhTW', '', '幹得好！你的能力比燃燒軍團的任何武器都強。', 25549),
(127604, 'zhTW', '', '漂亮！那個怪物完全不是對手。', 25549),
(127603, 'zhTW', '', '剛剛對那個怪物太仁慈了。換下一個目標！', 25549),
(127602, 'zhTW', '', '這是我們的警告！', 25549),
(127601, 'zhTW', '', '卑劣的入侵者就該有這種下場。', 25549),
(127600, 'zhTW', '', '做得好，勇士。千萬別鬆懈。', 25549),
(127599, 'zhTW', '', '有個強大的威脅就在附近。把它找出來殺掉。', 25549),
(127598, 'zhTW', '', '惡魔就像老鼠一樣越生越多。殺了這個惡魔，不要讓它召喚同類！', 25549),
(127597, 'zhTW', '', '前面…有個新目標。讓它哭著逃回扭曲虛空吧！', 25549),
(127596, 'zhTW', '', '我們的斥候報告說這一區有危險生物。把它解決掉！', 25549),
(127595, 'zhTW', '', '還有很多事要做。趕快解決這個惡魔。', 25549),
(127594, 'zhTW', '', '該給燃燒軍團一個警告了。讓這傢伙死無全屍！', 25549),
(127593, 'zhTW', '', '目標接近了。解決他。', 25549),
(127592, 'zhTW', '', '必須解決這個目標。動作快點。', 25549),
(127591, 'zhTW', '你要找指揮官？先過我這關，你這廢物！', '', 25549),
(127590, 'zhTW', '被魔能腐化的野獸，絕對是越少越好。', '', 25549),
(127589, 'zhTW', '深淵領主。哼！一群傲慢的傢伙。這些惡魔的精華說不定會在接下來的戰事中派上用場。', '', 25549),
(127588, 'zhTW', '斬魔者，前線需要你的支援。惡魔正從薩格拉斯之墓湧出！撕裂它們的靈魂精華，再用強化的靈魂能量把深淵領主劈成兩半！', '', 25549),
(127587, 'zhTW', '這種燃燒軍團的大型機械根本不適合這裡的地形。它們應該做點功課的！', '', 25549),
(127586, 'zhTW', '', '誰也阻止不了我們！', 25549),
(127585, 'zhTW', '', '我們聯手就能擊退燃燒軍團、保護家園。', 25549),
(127584, 'zhTW', '小心了，卡朗克會把你打得咔啷作響！', '', 25549),
(127583, 'zhTW', '', '小心了，卡朗克會把你打得咔啷作響！', 25549),
(127582, 'zhTW', '', '我和迪賓先回神獵廳，需要幫忙就來找我。', 25549),
(127572, 'zhTW', '不准干擾我們的工作！這裡是燃燒軍團的地盤！', '', 25549),
(127571, 'zhTW', '這片土地再也無法恢復了…', '', 25549),
(127570, 'zhTW', '你們這些聖騎士還真容易摸透。來吧，我們來看看這把劍真正的能耐…', '', 25549),
(127567, 'zhTW', '藥膏有用？呃，我是說…太好了，當然有用。做得好，勇士。', '', 25549),
(127566, 'zhTW', '我們派人探查這裡，他們卻遭到了石化蜥蜴的攻擊！這裡有些魔法藥膏，幫被石化的人塗上吧。', '', 25549),
(127565, 'zhTW', '我再也不會靠近石化蜥蜴了！', '我再也不會靠近石化蜥蜴了！', 25549),
(127564, 'zhTW', '謝謝你，$ct。我要回去營地！', '謝謝你，$ct。我要回去營地！', 25549),
(127563, 'zhTW', '我被困住多久了？', '我被困住多久了？', 25549),
(127562, 'zhTW', '', '最好別考驗我的耐性！風暴會回應我的呼喚！', 25549),
(127561, 'zhTW', '', '你的腦袋難道跟酒杯一樣空嗎？', 25549),
(127560, 'zhTW', '', '別再弄了，謝謝。', 25549),
(127559, 'zhTW', '', '願你喝遍各種美酒，朋友！', 25549),
(127558, 'zhTW', '', '總會有意想不到的驚喜！', 25549),
(127557, 'zhTW', '', '什麼都比不上跟好友共飲美酒。', 25549),
(127556, 'zhTW', '', '沒喝過的酒一定要找機會試試。', 25549),
(127555, 'zhTW', '為什麼黏液能跑得那麼快？', '', 25549),
(127554, 'zhTW', '', '有滿滿的愛才能釀出美酒。', 25549),
(127553, 'zhTW', '回來！我需要你的核心碎片！', '', 25549),
(127552, 'zhTW', '噁心的東西！別跑！', '', 25549),
(127551, 'zhTW', '', '你今天喝過酒了嗎？', 25549),
(127550, 'zhTW', '我學了一招，叫做「直搗蜂窩」！要在你身上示範嗎？', '', 25549),
(127549, 'zhTW', '你讓我無法專心掌握思緒了，小傢伙。', '', 25549),
(127548, 'zhTW', '拜託你，走開。我在冥想。', '', 25549),
(127547, 'zhTW', '在擊敗燃燒軍團之前，我們絕不鬆懈。', '', 25549),
(127546, 'zhTW', '只要心靈純淨，邪惡就無法滋長。', '', 25549),
(127545, 'zhTW', '我們為艾澤拉斯效力。', '', 25549),
(127544, 'zhTW', '我們是平息驚濤駭浪的力量。', '', 25549),
(127543, 'zhTW', '你是黑暗中的明燈。', '', 25549),
(127542, 'zhTW', '在這混亂的時刻堅持下去。', '', 25549),
(127541, 'zhTW', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡拉孟開始最後一次追逐你！', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡拉孟開始最後一次追逐你！', 25549),
(127540, 'zhTW', '', '[OLD DNT]伊利丹大人，你總算來了…看守者，我們上工了，蝙蝠就交給惡魔獵人去玩吧。', 25549),
(127539, 'zhTW', '去解決驚懼指揮官亞岡諾斯！剩下的交給我們。', '', 25549),
(127538, 'zhTW', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_GENERALVEZAX_01.BLP:20|t召喚符文喚出一隻|cFFFF0000|Hspell:236461|h[夢魘造物]|h|r來追擊你！', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_GENERALVEZAX_01.BLP:20|t召喚符文喚出一隻|cFFFF0000|Hspell:236461|h[夢魘造物]|h|r來追擊你！', 25549),
(127537, 'zhTW', '|TInterface\\Icons\\SPELL_MAGE_RUNEOFPOWER.BLP:20|t瑞斯特在附近製造了一個|cFFFF0000|Hspell:236460|h[召喚符文]|h|r！', '|TInterface\\Icons\\SPELL_MAGE_RUNEOFPOWER.BLP:20|t瑞斯特在附近製造了一個|cFFFF0000|Hspell:236460|h[召喚符文]|h|r！', 25549),
(127536, 'zhTW', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡拉孟開始再次追逐你！', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡拉孟開始再次追逐你！', 25549),
(127535, 'zhTW', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_05.BLP:20|t來自虛空的魔手開始施放|cFFFF0000|Hspell:235578|h[虛空之握]|h|r！', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_05.BLP:20|t來自虛空的魔手開始施放|cFFFF0000|Hspell:235578|h[虛空之握]|h|r！', 25549),
(127534, 'zhTW', '|TInterface\\Icons\\INV_MISC_SHADOWEGG.BLP:20|t瑞斯特|cFFFF0000|Hspell:235446|h[撕開]|h|r通往虛空的裂隙！', '|TInterface\\Icons\\INV_MISC_SHADOWEGG.BLP:20|t瑞斯特|cFFFF0000|Hspell:235446|h[撕開]|h|r通往虛空的裂隙！', 25549),
(127533, 'zhTW', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡拉孟開始追逐你！', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡拉孟開始追逐你！', 25549),
(127532, 'zhTW', '你配不上太陽的光芒！', '', 25549),
(127531, 'zhTW', '你有已經準備好的神兵武器研究筆記嗎？', '你有已經準備好的神兵武器研究筆記嗎？', 25549),
(127530, 'zhTW', '太多樂子了！哈哈哈！', '', 25549),
(127529, 'zhTW', '該去哪裡呢…', '', 25549),
(127528, 'zhTW', '有好多好多的東西要燒！嘿嘿嘿！', '', 25549),
(127527, 'zhTW', '終於自由了！', '', 25549),
(127526, 'zhTW', '快克制不住了…我不要再壓抑了！', '', 25549),
(127525, 'zhTW', '我的怒火越燒越烈…', '', 25549),
(127524, 'zhTW', '有什麼事？', '', 25549),
(127523, 'zhTW', '我的利爪隨時準備要殺敵。', '', 25549),
(127522, 'zhTW', '為了聯盟。', '', 25549),
(127521, 'zhTW', '保持堅定。', '', 25549),
(127520, 'zhTW', '你需要什麼嗎？', '', 25549),
(127519, 'zhTW', '你好。', '', 25549),
(127518, 'zhTW', '有麻煩了嗎？', '', 25549),
(127517, 'zhTW', '我一定會成功的，戰鬥領主。', '', 25549),
(127516, 'zhTW', '你會死在我狂怒的利爪底下！', '', 25549),
(127515, 'zhTW', '我的怒火…暫時…熄滅了…', '', 25549),
(127514, 'zhTW', '戰鬥領主，我…讓你失望了…', '', 25549),
(127513, 'zhTW', '我的爪子…不夠鋒利…', '', 25549),
(127512, 'zhTW', '你的死讓我更加憤怒！', '', 25549),
(127511, 'zhTW', '我的利爪沾滿你的鮮血！', '', 25549),
(127510, 'zhTW', '為了聯盟！', '', 25549),
(127509, 'zhTW', '我要用你來磨爪子！', '', 25549),
(127508, 'zhTW', '我要把你撕成碎片！', '', 25549),
(127507, 'zhTW', '呃啊啊啊！', '', 25549),
(127506, 'zhTW', '嚐嚐我的怒火！', '', 25549),
(127505, 'zhTW', '我要殺了你！', '', 25549),
(127504, 'zhTW', '團結起來，我們就能消滅敵人！', '', 25549),
(127503, 'zhTW', '我們誓死保衛艾澤拉斯！', '', 25549),
(127502, 'zhTW', '你好，戰鬥領主。我準備好要戰鬥了！', '', 25549),
(127500, 'zhTW', '不要惹我生氣！', '', 25549),
(127499, 'zhTW', '我的斧頭越來越飢渴了。', '', 25549),
(127498, 'zhTW', '怎樣？', '', 25549),
(127497, 'zhTW', '再見。', '', 25549),
(127496, 'zhTW', '隨時做好準備。', '', 25549),
(127495, 'zhTW', '勇敢向前。', '', 25549),
(127494, 'zhTW', '你好，朋友。', '', 25549),
(127493, 'zhTW', '嗯？', '', 25549),
(127492, 'zhTW', 'Throm-Ka! (你好！)', '', 25549),
(127491, 'zhTW', '我不會讓你失望的，戰鬥領主。', '', 25549),
(127490, 'zhTW', '在我的怒火下顫抖吧！', '', 25549),
(127489, 'zhTW', '我會再度舉起斧頭…', '', 25549),
(127488, 'zhTW', '我變虛弱了…', '', 25549),
(127487, 'zhTW', '我的憤怒…平息了…', '', 25549),
(127486, 'zhTW', '', '你確定需要我幫忙嗎？', 25549),
(127485, 'zhTW', '太簡單了。', '', 25549),
(127484, 'zhTW', '我的憤怒永不止息！', '', 25549),
(127483, 'zhTW', '勝利的滋味！', '', 25549),
(127482, 'zhTW', '啊啊啊啊！', '', 25549),
(127481, 'zhTW', 'Lok-tar Ogar!(不勝即亡！)', '', 25549),
(127480, 'zhTW', '為了部落！', '', 25549),
(127479, 'zhTW', '我的斧頭渴望鮮血！', '', 25549),
(127478, 'zhTW', '我們必須消滅這股邪惡。', '', 25549),
(127477, 'zhTW', '我們的怒火會拯救艾澤拉斯！', '', 25549),
(127476, 'zhTW', '戰鬥領主，我會為你而戰。', '', 25549),
(127475, 'zhTW', '提里斯護法的敵人去死！', '', 25549),
(127474, 'zhTW', '不要再胡鬧了！', '', 25549),
(127473, 'zhTW', '你覺得打擾我很有趣嗎？', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(127472, 'zhTW', '有什麼事？', '', 25549),
(127471, 'zhTW', '我會盡我所能，大法師。', '', 25549),
(127470, 'zhTW', 'Anar''alah belore (以太陽之光)，燒死你！', '', 25549),
(127469, 'zhTW', '我盡力了…但還不夠…', '', 25549),
(127468, 'zhTW', '我要…休息一下。', '', 25549),
(127467, 'zhTW', '必須恢復…力量…', '', 25549),
(127466, 'zhTW', '進入暗無天日的世界吧！', '', 25549),
(127465, 'zhTW', '低等生物。', '', 25549),
(127464, 'zhTW', '你一無是處。', '', 25549),
(127463, 'zhTW', '沒用的東西。', '', 25549),
(127462, 'zhTW', '燒吧！', '', 25549),
(127461, 'zhTW', 'Diel fin''al! (送你上路！)', '', 25549),
(127460, 'zhTW', '你的隊伍投票通過，將舒諾茲踢出熱氣球！', '', 25549),
(127459, 'zhTW', '該來點火了！', '', 25549),
(127458, 'zhTW', '又一個目標！', '', 25549),
(127457, 'zhTW', '我們會燒盡這片黑暗！', '', 25549),
(127456, 'zhTW', '同心協力，就能拯救艾澤拉斯！', '', 25549),
(127455, 'zhTW', '我們會協助提里斯護法！', '', 25549),
(127454, 'zhTW', 'Bal''a dash(你好)，大法師。我們齊心作戰！', '', 25549),
(127453, 'zhTW', '等到有三名乘客，熱氣球就會起飛。', '等到有三名乘客，熱氣球就會起飛。', 25549),
(127452, 'zhTW', '', '可能…我真的不是…這塊料…', 25549),
(127451, 'zhTW', '', '喂，住手！不然我要拿你練習迴旋踢了！', 25549),
(127450, 'zhTW', '', '好了，好了…夠了！', 25549),
(127449, 'zhTW', '', '哈哈哈！住手！會癢啦！', 25549),
(127448, 'zhTW', '', '我能跟你一起走嗎？', 25549),
(127447, 'zhTW', '', '祝你好運！', 25549),
(127446, 'zhTW', '', '改天一起來喝酒吧！', 25549),
(127445, 'zhTW', '', '我已經做好準備了！', 25549),
(127444, 'zhTW', '', '你好啊，英雄！', 25549),
(127443, 'zhTW', '', '想不想來點我的特製佳釀啊？', 25549),
(127442, 'zhTW', '', '哇！我會盡力的，宗師！', 25549),
(127441, 'zhTW', '', '不想死就滾開！喔…哇…哇…啊！', 25549),
(127440, 'zhTW', '', '很抱歉讓你失望了，宗師…', 25549),
(127439, 'zhTW', '', '結束之後，我需要找個替身…', 25549),
(127438, 'zhTW', '', '好痛！我當初真不該離開酒坊的…', 25549),
(127437, 'zhTW', '', '你剛剛真的盡力了嗎？', 25549),
(127436, 'zhTW', '', '哈，我越來越厲害了！', 25549),
(127435, 'zhTW', '', '真不該浪費真氣來對付你！', 25549),
(127434, 'zhTW', '', '看我的！', 25549),
(127433, 'zhTW', '', '喔，太好了！我需要更多戰鬥練習！', 25549),
(127432, 'zhTW', '', '我要把你打昏！', 25549),
(127431, 'zhTW', '', '我敢說你沒看過我這種迴旋踢！', 25549),
(127430, 'zhTW', '', '你無法逃出我的迷霧！', 25549),
(127429, 'zhTW', '', '我敢說你對美酒一竅不通！', 25549),
(127428, 'zhTW', '', '我一定會好好保護你的，宗師！', 25549),
(127427, 'zhTW', '', '宗師，我來支援你！', 25549),
(127426, 'zhTW', '', '捲起袖子來辦事啦！', 25549),
(127425, 'zhTW', '', '我願意…為你這麼做。', 25549),
(127424, 'zhTW', '', '我要把你丟進水裡淹死！', 25549),
(127423, 'zhTW', '', '我不能接受…這種結局…', 25549),
(127422, 'zhTW', '', '你得靠自己…我不行了…', 25549),
(127421, 'zhTW', '', '這…這不可能…', 25549),
(127419, 'zhTW', '', '誰都擋不住考斯卡。', 25549),
(127417, 'zhTW', '', '把你變成魚餌！', 25549),
(127416, 'zhTW', '', '你應該要學游泳的。', 25549),
(127415, 'zhTW', '', '你讓我覺得很無聊。', 25549),
(127414, 'zhTW', '', '嘗嘗考斯卡的厲害！', 25549),
(127413, 'zhTW', '', '我們這次能做點有趣的事嗎？', 25549),
(127412, 'zhTW', '', '斬魔者，看來我有時間幫你。', 25549),
(127411, 'zhTW', '', '你確定需要我幫忙嗎？', 25549),
(127410, 'zhTW', '', '死活看自己！', 25549),
(127409, 'zhTW', '', '淹死你！', 25549),
(127408, 'zhTW', '', '一下子就能解決。', 25549),
(127407, 'zhTW', '', '你死了，伊利丹大人會很高興的！', 25549),
(127406, 'zhTW', '', '我和你層次不同。', 25549),
(127405, 'zhTW', '鬧夠了沒有！有膽就過來找我！', '', 25549),
(127404, 'zhTW', '燃燒軍團會征服一切！你那可憐的英靈殿會灰飛煙滅。', '', 25549),
(127403, 'zhTW', '', '…反正我都死了，還在乎什麼。', 25549),
(127402, 'zhTW', '', '就算沒嚇死，我也會用斧頭把它們砍死。怎樣都好，我不在乎！', 25549),
(127401, 'zhTW', '', '等惡魔看到我們的龍群，保證它們會嚇死！', 25549),
(127400, 'zhTW', '', '別誤會…四騎士是很厲害。但跟巨大的不死龍群相比…', 25549),
(127399, 'zhTW', '', '丹密爾跟那些幼龍已經屬於我們，情勢要翻轉了！', 25549),
(127398, 'zhTW', '', '你好，$n。你知道今天有個祈倫托贊助的旅店大拼酒活動嗎？我可以把你傳送到大家現在聚集的旅店。', 25549),
(127397, 'zhTW', '漂亮的勝利，勇士。你的英勇事蹟會在英靈殿傳頌不絕。', '', 25549),
(127396, 'zhTW', '你打倒指揮官了，做得好！維瑟的飛龍會護送你離開。飛船就交給我來解決吧！', '', 25549),
(127395, 'zhTW', '我們必須摧毀燃燒軍團的空中堡壘！這些飛龍可以把你們帶到惡魔的空中堡壘，要怎麼大肆破壞就看你們的了。', '', 25549),
(127394, 'zhTW', '英雄，到我這裡來。維瑟的飛龍來幫我們消滅入侵者了。飛上天空，擊敗入侵者！', '', 25549),
(127393, 'zhTW', '維瑟的龍群又被抓走了！把牠們救出來，讓牠們幫忙反擊禦敵。', '', 25549),
(127392, 'zhTW', '', '等她下來。這一定會是精彩的戰鬥！', 25549),
(127391, 'zhTW', '', '我愛死你的眼鏡了。好復古。', 25549),
(127390, 'zhTW', '[OLD DNT]讓我們打敗燃燒軍團！就在今天！為了艾澤拉斯！', '', 25549),
(127389, 'zhTW', '[OLD DNT]我們得拿下島嶼西面。從那裡可以全力攻擊靈魂引擎！', '', 25549),
(127388, 'zhTW', '[OLD DNT]我需要你幫我帶領部隊，我得去其他前線幫忙！', '', 25549),
(127387, 'zhTW', '[OLD DNT]$n，我們在南灘地進攻行動遇到困難。', '', 25549),
(127386, 'zhTW', '破碎樓梯的舞會大廳門打開了。', '破碎樓梯的舞會大廳門打開了。', 25549),
(127385, 'zhTW', '就差一點點而已。下次再來吧。', '就差一點點而已。下次再來吧。', 25549),
(127384, 'zhTW', '呃…感謝你勇於嘗試？', '呃…感謝你勇於嘗試？', 25549),
(127383, 'zhTW', '你輸了！什麼都拿不到！', '你輸了！什麼都拿不到！', 25549),
(127382, 'zhTW', '真可惜，真是遺憾！', '真可惜，真是遺憾！', 25549),
(127381, 'zhTW', '我是不是聞到勝利的味道啊？', '我是不是聞到勝利的味道啊？', 25549),
(127380, 'zhTW', '哼。你們之中絕對不只一個人沒在專心。', '哼。你們之中絕對不只一個人沒在專心。', 25549),
(127379, 'zhTW', '格鬥結束了…英雄們奪得冠軍！所有參加的人都能獲得優渥的金幣獎勵。', '格鬥結束了…英雄們奪得冠軍！所有參加的人都能獲得優渥的金幣獎勵。', 25549),
(127378, 'zhTW', '我簡直不敢相信…居然贏了！這是奇蹟！開玩笑的啦，其實常這樣。', '我簡直不敢相信…居然贏了！這是奇蹟！開玩笑的啦，其實常這樣。', 25549),
(127377, 'zhTW', '', '她完全長大，準備好大戰一場了。雖然她現在看起來像隻可愛的小貓，但等她被逼急了你就知道。讓開！下一個格鬥者梅颯靈要上場了！', 25549),
(127376, 'zhTW', '', '打不贏他，就加入他吧！你的大腦、尊嚴，和酒精飲料全部都會被他搶走！準備好面對破心者格薩基！', 25549),
(127375, 'zhTW', '', '你不需要擊敗這些生物，你只要活下來就好了。對了，我們還要拿走你所有裝備跟經驗。好好享受荊棘叢林狂奔吧！', 25549),
(127374, 'zhTW', '', '河馬就是死亡的代名詞！小心別被下一個格鬥者給踩扁了，歡迎森亞！', 25549),
(127373, 'zhTW', '', '這三個熊貓人準備向你挑戰…比對手先將啤酒車拉到場地中央，就算獲勝。勝利的人就能把酒喝光！', 25549),
(127372, 'zhTW', '', '今天的格鬥者是一群遠從北裂境寒冷極地來的氣派企鵝。絕對不要小看滑溜溜大軍！', 25549),
(127371, 'zhTW', '', '今天的格鬥者是個健壯的哺乳動物，急切地想要報仇。牠不想幫助你…牠想殺死你。請熱烈歡迎憎恨麋鹿，悲嘆看守者！', 25549),
(127370, 'zhTW', '她完全長大，準備好大戰一場了。雖然她現在看起來像隻可愛的小貓，但等她被逼急了你就知道。讓開！下一個格鬥者梅颯靈要上場了！', '', 25549),
(127369, 'zhTW', '打不贏他，就加入他吧！你的大腦、尊嚴，和酒精飲料全部都會被他搶走！準備好面對破心者格薩基！', '', 25549),
(127368, 'zhTW', '你不需要擊敗這些生物，你只要活下來就好了。對了，我們還要拿走你所有裝備跟經驗。好好享受荊棘叢林狂奔吧！', '', 25549),
(127367, 'zhTW', '河馬就是死亡的代名詞！小心別被下一個格鬥者給踩扁了，歡迎森亞！', '', 25549),
(127366, 'zhTW', '這三個熊貓人準備向你挑戰…比對手先將啤酒車拉到場地中央，就算獲勝。勝利的人就能把酒喝光！', '', 25549),
(127365, 'zhTW', '今天的格鬥者是一群遠從北裂境寒冷極地來的氣派企鵝。絕對不要小看滑溜溜大軍！', '', 25549),
(127364, 'zhTW', '今天的格鬥者是個健壯的哺乳動物，急切地想要報仇。牠不想幫助你…牠想殺死你。請熱烈歡迎憎恨麋鹿，悲嘆看守者！', '', 25549),
(127363, 'zhTW', '', '你們會被無比強大的力量燒毀！', 25549),
(127362, 'zhTW', '', '你們就從世界上消失吧！', 25549),
(127361, 'zhTW', '|TInterface\\Icons\\INV_Misc_Food_Legion_gooOil_multi.blp:20|t瀝青池開始|cFFFF0000|Hspell:236333|h[爆發]|h|r了！', '', 25549),
(127360, 'zhTW', '%s身旁的土地中開始滲出瀝青…', '', 25549),
(127359, 'zhTW', '惡魔劫奪者碎裂的核心引來了一大群怪物！蒐集那些核心碎片，別讓燃燒軍團回收利用了！', '', 25549),
(127358, 'zhTW', '做得好！就算燃燒軍團留下來的傷還在，但總會癒合的。', '', 25549),
(127357, 'zhTW', '燃燒軍團碰過的東西都腐化了！摧毀它們的魔化散佈水晶，千萬不要讓斯鐸海姆淪陷！', '', 25549),
(127356, 'zhTW', '歐丁，我準備好開始試煉了。', '歐丁，我準備好開始試煉了。', 25549),
(127355, 'zhTW', '幫我傳送到旅店大拼酒活動。', '幫我傳送到旅店大拼酒活動。', 25549),
(127354, 'zhTW', '我可以去擎天堡了。', '我可以去擎天堡了。', 25549),
(127353, 'zhTW', '你帶了什麼過來？', '你帶了什麼過來？', 25549),
(127352, 'zhTW', '戰鬥領主，能跟你來這裡是我的榮幸。希望你在試煉中每戰必勝。', '', 25549),
(127351, 'zhTW', '', '歡迎參加祈倫托旅店大拼酒，$n。請盡情享用免費的食物跟飲料。過幾分鐘我們就會出發前往下一個旅店。', 25549),
(127350, 'zhTW', '戰鬥領主，如果你想離開，我可以送你到擎天堡。', '', 25549),
(127349, 'zhTW', '戰鬥領主，如果你想離開，我可以送你到擎天堡。', '', 25549),
(127348, 'zhTW', '呵，我心情好一點了。謝謝你們特地來陪陪我這個老獵人啊！', '', 25549),
(127347, 'zhTW', '哈哈。我自己就是矮人，而且還是獵人，所以才能開這種玩笑！', '', 25549),
(127346, 'zhTW', '因為手短拉不開弓箭！', '', 25549),
(127345, 'zhTW', '你們猜猜矮人獵人為什麼都用槍？', '', 25549),
(127344, 'zhTW', '有人知道什麼好笑話嗎？我先來講一個好了…', '', 25549),
(127343, 'zhTW', '搞得我都惆悵了起來。', '', 25549),
(127342, 'zhTW', '我可以搭你的熱氣球嗎？', '我可以搭你的熱氣球嗎？', 25549),
(127341, 'zhTW', '我可以出發了。請幫我召喚傳送門。', '我可以出發了。請幫我召喚傳送門。', 25549),
(127340, 'zhTW', '$n，你能做到的。結束這一切吧。', '', 25549),
(127339, 'zhTW', '連繫終於切斷了！動作要快，勇士。我們在法隆谷地集合。終於到這一步了。', '', 25549),
(127338, 'zhTW', '蠢貨！抬頭看看天空，這就是世界末日了！', '', 25549),
(127337, 'zhTW', '', '我…我竟然輸了。也許本來就輪不到我晉升…', 25549),
(127336, 'zhTW', '', '只要打贏你，晉升的機會就多一些。', 25549),
(127335, 'zhTW', '戰鬥領主是否有能耐擊倒這位受到埃伊爾眷顧的挑戰者呢？', '', 25549),
(127334, 'zhTW', '埃伊爾派出她最得意的弟子來當戰鬥領主最後的挑戰者。我在此歡迎…志士賽黎！', '', 25549),
(127333, 'zhTW', '大家慶賀這位勇士的勝利吧！為戰鬥領主歡呼！', '', 25549),
(127332, 'zhTW', '戰鬥領主擊敗了所有挑戰者！試煉完成了！', '', 25549),
(127331, 'zhTW', '戰鬥領主，等你準備好面對最後的挑戰者，就站到符文上。', '', 25549),
(127330, 'zhTW', '難得一見的精彩搏鬥！艾絲蕾向來縱橫試煉場，大家都認為她所向無敵。看來驕兵必敗是不變的道理！', '', 25549),
(127329, 'zhTW', '鋼蹄名不符實的防禦在戰鬥領主手下瓦解了！但是，戰鬥領主能不能擊敗下一個挑戰者呢？', '', 25549),
(127328, 'zhTW', '精彩的第一回合！看來丹魯爾低估了戰鬥領主的能耐。', '', 25549),
(127327, 'zhTW', '在時間靜止的同時，法師塔劈啪作響！', '在時間靜止的同時，法師塔劈啪作響！', 25549),
(127325, 'zhTW', '燃燒軍團開始腐化野獸了。有隻野獸跟魚人一起住在洞穴裡。一定要消滅牠！', '', 25549),
(127324, 'zhTW', '部隊沒有淪為惡魔的祭品，並且恢復了戰力，這真是最好的結果。', '', 25549),
(127323, 'zhTW', '一定要找到厄德里斯。我先去偵察玄鴉堡，等到可以攻擊了再通知你。英雄，待會見。', '', 25549),
(127322, 'zhTW', '卑鄙的惡魔用我們受傷的盟友當作誘餌！前線需要每一個士兵的支援。快去協助他們重回戰場…小心隱藏的敵人。', '', 25549),
(127321, 'zhTW', '趁現在好好慶祝吧。我已經看透你的戰術…知道你的弱點。我會在玄鴉堡準備一支完全聽我號令的軍隊！', '', 25549),
(127320, 'zhTW', '厲害。只要有正確的工具，就連最強大的魔法都能解除。', '', 25549),
(127319, 'zhTW', '神獵手，準備好照明彈。燃燒軍團的暗影怪物佔領了重要的據點。讓這些怪物現形，我們的弓箭手才能把它們全部消滅。', '', 25549),
(127318, 'zhTW', '來…起來…反抗「燃燒軍團」！', '', 25549),
(127317, 'zhTW', '全體士兵聽令！我需要你們的力量！', '', 25549),
(127316, 'zhTW', '「領主大人」，把你的士兵喚醒！我能讓他們變得更加強大。', '', 25549),
(127315, 'zhTW', '你就要死了。', '', 25549),
(127314, 'zhTW', '戰鬥領主，我輸了。你顯然已經證明身為戰士，你比我厲害多了。', '', 25549),
(127313, 'zhTW', '厄德里斯剛剛說出了幾個要先處理的名字。他們應該在農地附近。我們走！', '', 25549),
(127312, 'zhTW', '等等！別打了，我…我不行了。你真的比較強，卜魯。', '', 25549),
(127311, 'zhTW', '蒂莎、奈梭斯、泰爾索斯！列隊！我要把這裡的髒東西通通清掉！', '', 25549),
(127310, 'zhTW', '我想參加最後的攻擊行動。[加入事件佇列]', '我想參加最後的攻擊行動。[加入事件佇列]', 25549),
(127309, 'zhTW', '燃燒軍團必敗無疑！', '', 25549),
(127308, 'zhTW', '我…失敗了。', '', 25549),
(127307, 'zhTW', '我來開傳送門。', '', 25549),
(127306, 'zhTW', '只要同心協力，一定能打垮燃燒軍團！', '', 25549),
(127303, 'zhTW', '謝謝你，勇士。請你也去救救其他人！', '謝謝你，勇士。請你也去救救其他人！', 25549),
(127302, 'zhTW', '謝謝你，勇士。請你也去救救其他人！', '謝謝你，勇士。請你也去救救其他人！', 25549),
(127300, 'zhTW', '', '我的武器很久沒喝到血了。不知道你的好不好喝…', 25549),
(127299, 'zhTW', '她的劍刃在試煉場上擊倒了許多戰士。戰鬥領主有辦法獲得勝利嗎？', '', 25549),
(127298, 'zhTW', '戰鬥領主的下一個對手是蘇拉瑪爾驕傲的夜裔精靈，艾絲蕾‧月刃。', '', 25549),
(127297, 'zhTW', '', '我才不會輸給你這種平民！！！', 25549),
(127296, 'zhTW', '', '$r，你好傻，但如果只有死亡才能讓你學乖，也只好這樣了。', 25549),
(127295, 'zhTW', '', '這種試煉我參加過幾千次了，每一次我都讓歐丁知道，他選出來的戰士根本不配和我交手。', 25549),
(127290, 'zhTW', '凡人，你不懂自己面對的是什麼力量！不屈服，那就去死吧！', '', 25549),
(127285, 'zhTW', '|TInterface\\Icons\\SPELL_SHADOW_SOULLEECH_1.BLP:20|t%s開始|cFFFF0000|Hspell:236133|h[綻放]|h|r！', '', 25549),
(127284, 'zhTW', '老兄…', '', 25549),
(127283, 'zhTW', '面對燃燒軍團的力量還不跪下！凡人，你再努力也沒用！', '', 25549),
(127282, 'zhTW', '惡魔的力量已經減少了，但絕對不能鬆懈。我先到神廟外面等你。換我們進攻了。', '', 25549),
(127281, 'zhTW', '蠻力是燃燒軍團的武器，智力卻不是。', '', 25549),
(127280, 'zhTW', '燃燒軍團想用某種不穩定的儀式修理惡魔劫奪者。想辦法打斷儀式，利用它們的能量反攻。', '', 25549),
(127279, 'zhTW', '水晶被摧毀時，其中的魔化能量也隨之消散。這下威脅應該解除了。', '', 25549),
(127278, 'zhTW', '燃燒軍團把蘊藏邪惡力量的寶石交給了魔裔精靈。從他們手中奪取寶石，然後銷毀。那些精靈要殺要剮隨便你。', '', 25549),
(127277, 'zhTW', '', '這輪$n請客！接下來兩分鐘內飲料免費！', 25549),
(127276, 'zhTW', '畢茲摩的貴賓室已經向所有鬥士開放，$n向您致意！', '', 25549),
(127275, 'zhTW', '', '$n砸下重金打破競技場的規則。和保鏢交談就能挑戰隨機的打鬥者！', 25549),
(127274, 'zhTW', '簡單來說，雖然你沒有贏得進入貴賓室的資格，但有個心地比你善良的人付我錢要讓你進去。\n\n沒問題，你進來吧。可別把這地方弄亂了。', '', 25549),
(127273, 'zhTW', '你是第8階，對吧？\n\n你蠻厲害的，進來吧。', '', 25549),
(127272, 'zhTW', '畢茲摩和他的手下在礦道地鐵這裡鑿出這間酒吧的時候，承擔了很大的風險。他花了很多錢才把這地方蓋好。\n\n所以他才蓋了這間房間，當作貴賓室。從這裡看比賽的視野好、高級酒飲應有盡有。最重要的，是可以享受這種會員專屬俱樂部的獨特優越感。因為只有第8階以上的人才能進入。\n\n想進貴賓室的話，就努力打贏比賽吧，年輕人。', '', 25549),
(127271, 'zhTW', '<拿出貴賓室租用表單。>', '<拿出貴賓室租用表單。>', 25549),
(127270, 'zhTW', '燃燒軍團往艾蘇納前進了！要削減惡魔的數量，才能暴露它們的要害。', '', 25549),
(127269, 'zhTW', '能受到歐丁邀請是我的榮幸，我一定會證明自己的實力，不會辜負期待。', '', 25549),
(127268, 'zhTW', '就算你倒下了也別太自責，我本來就無懈可擊。', '', 25549),
(127267, 'zhTW', '我等不及要把你打爛了。', '', 25549),
(127266, 'zhTW', '來打一場，我向你挑戰！', '來打一場，我向你挑戰！', 25549),
(127265, 'zhTW', '不一起來練練嗎？', '', 25549),
(127264, 'zhTW', '在我盾前倒下的戰士不知道有多少，我才不相信區區一個$r有辦法穿破它。', '', 25549),
(127263, 'zhTW', '就來看看戰鬥領主高明的技巧能否突破鋼蹄的護盾吧！', '', 25549),
(127262, 'zhTW', '戰鬥領主的下一個挑戰者，是高嶺部族的歐瑪納庫‧鋼蹄。', '', 25549),
(127261, 'zhTW', '要不是你，我們很可能就撐不住了。非常感謝你！', '要不是你，我們很可能就撐不住了。非常感謝你，$c。', 25549),
(127260, 'zhTW', '這啤酒泡沫很綿密，正是我需要的提神飲料。', '這啤酒泡沫很綿密，正是我需要的提神飲料。', 25549),
(127259, 'zhTW', '啊！冰涼的新鮮啤酒！', '啊！冰涼的新鮮啤酒！', 25549),
(127258, 'zhTW', '惡魔要為它們犯下的罪付出千百倍的代價。繼續奮戰！', '', 25549),
(127257, 'zhTW', '對燃燒軍團是一記沉重的打擊！', '', 25549),
(127256, 'zhTW', '每一次勝利都能提振我們的軍心、強化我方的戰力。謝謝你，勇士。', '', 25549),
(127255, 'zhTW', '巡邏兵在這附近發現一個強大的敵人。要是能擊倒它，就能重挫這裡的燃燒軍團。', '', 25549),
(127254, 'zhTW', '燃燒軍團在某個強大的敵人附近聚集。我們一定要阻止它們壯大勢力！', '', 25549),
(127253, 'zhTW', '燃燒軍團在這裡的勢力很強大。勇士，做好準備。聖光必勝！', '', 25549),
(127252, 'zhTW', '不論燃燒軍團在哪裡出現，我們都會擊潰它們，直到把它們徹底趕走為止。', '', 25549),
(127251, 'zhTW', '每殺一個，都會再冒出一個。千萬不要鬆懈。', '', 25549),
(127250, 'zhTW', '他們還沒準備好！', '', 25549),
(127249, 'zhTW', '這些烏合之眾竟敢再次踏足艾澤拉斯。就用它們對待無數其他世界的方式來迎接它們：殺無赦！', '', 25549),
(127248, 'zhTW', '有個燃燒軍團的走狗在偷偷摸摸地做些什麼，讓它知道我們的厲害！', '', 25549),
(127247, 'zhTW', '我感覺到附近有強大的敵人。發洩你的怒氣，讓它從世界上消失！', '', 25549),
(127246, 'zhTW', '今天在戰鬥場上的打鬥相當激烈。我個人覺得比平常還要血腥。我剛剛好像被顆斷牙打到了呢。', '', 25549),
(127245, 'zhTW', '我並不想重新加入黑穫議會，但能見到老朋友真好。', '', 25549),
(127244, 'zhTW', '$n想知道：你覺得自己幸運嗎？來找溫尼費德‧布朗尼領主就能試試你的…賺錢潛力。', '', 25549),
(127243, 'zhTW', '軍團之殞又獲得了一場漂亮的勝利。我們絕不能浪費這樣的優勢！', '', 25549),
(127242, 'zhTW', '謝謝你，勇士。你在敵人無盡的攻勢中給了我們稍微喘息的空間。', '', 25549),
(127241, 'zhTW', '做得好，就跟大法師一樣！嗯，這麼說好像怪怪的…', '', 25549),
(127240, 'zhTW', '這個敵人對我們來說是一大威脅。擊敗它，為我們爭取更多準備時間！', '', 25549),
(127239, 'zhTW', '我要扯爛你這個破布娃娃，$r！', '', 25549),
(127238, 'zhTW', '這附近有危險的燃燒軍團成員。你必須擊敗它們，絕對不能漠視這個威脅！', '', 25549),
(127236, 'zhTW', '根據回報，這附近有個特別強大的惡魔。我們應該趕快消滅它！', '', 25549),
(127235, 'zhTW', '', '他還活著嗎？', 25549),
(127234, 'zhTW', '第一場由勇猛的戰鬥領主對上惡名昭彰的卓格巴，『強者』丹魯爾！', '', 25549),
(127233, 'zhTW', '', '喔，你是想要我當壞人嗎？', 25549),
(127232, 'zhTW', '', '別煩我！', 25549),
(127231, 'zhTW', '', '走開！', 25549),
(127230, 'zhTW', '', '還有很多事要做。', 25549),
(127229, 'zhTW', '', '別再逗留。', 25549),
(127228, 'zhTW', '戰士們，歡迎來到怒氣試煉！', '', 25549),
(127227, 'zhTW', '', '別掉以輕心。', 25549),
(127226, 'zhTW', '', '我活在陰影之中。', 25549),
(127225, 'zhTW', '', '我的刀刃永遠鋒利。', 25549),
(127224, 'zhTW', '', '你需要什麼？', 25549),
(127223, 'zhTW', '', '虛空領主，你做到了！你救了坎瑞薩德。', 25549),
(127222, 'zhTW', '', '我該為你挖墳墓嗎？', 25549),
(127221, 'zhTW', '', '有人說，越美麗的女人越是要命。', 25549),
(127220, 'zhTW', '', '別再煩我！', 25549),
(127219, 'zhTW', '', '不死國度永不止息。', 25549),
(127218, 'zhTW', '', '沒事了嗎？', 25549),
(127217, 'zhTW', '', '苦難與你同在。', 25549),
(127216, 'zhTW', '', '我的斧頭餓了。', 25549),
(127215, 'zhTW', '', '歡迎來到不死國度。', 25549),
(127214, 'zhTW', '', '嗯？', 25549),
(127213, 'zhTW', '', '我殺過勇士和酋長！你根本就微不足道！', 25549),
(127212, 'zhTW', '', '做得好！我們的部隊應該可以繼續堅持，撐到戰鬥結束為止。', 25549),
(127211, 'zhTW', '', '有個巡邏隊被困在大軍裡面了！我們要帶風暴蜜酒過去提振士氣。該怎麼做才好…', 25549),
(127210, 'zhTW', '', '我一根手指就比得上你全身的力量！', 25549),
(127209, 'zhTW', '', '孩子，別煩我。', 25549),
(127208, 'zhTW', '', '恐怖圖騰一定會再度強盛。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(127207, 'zhTW', '', '別單獨行動啊…', 25549),
(127206, 'zhTW', '', '孩子，滾一邊去。', 25549),
(127205, 'zhTW', '', '你找老瑪加薩做什麼？', 25549),
(127204, 'zhTW', '', '你需要什麼？', 25549),
(127203, 'zhTW', '', '我對蠢蛋沒什麼耐心。', 25549),
(127202, 'zhTW', '', '別讓他們吸取他的能量！', 25549),
(127201, 'zhTW', '', '你們別想干擾儀式！', 25549),
(127200, 'zhTW', '', '坎瑞薩德的力量屬於燃燒軍團！', 25549),
(127199, 'zhTW', '我傷口很深，不過我受過更重的傷也撐過來了。我很快就會向燃燒軍團復仇！', '', 25549),
(127198, 'zhTW', '', '要在你脖子上插一把刀嗎？我很樂意。', 25549),
(127197, 'zhTW', '', '別這樣好嗎？', 25549),
(127196, 'zhTW', '', '別吵了！', 25549),
(127195, 'zhTW', '', '不要放棄希望！', 25549),
(127194, 'zhTW', '', '願風眷顧你。', 25549),
(127193, 'zhTW', '', '後會有期！', 25549),
(127192, 'zhTW', '', '你幫我，我也會幫你。', 25549),
(127191, 'zhTW', '', '你好嗎？', 25549),
(127190, 'zhTW', '', '有危險嗎？我應付得了！', 25549),
(127189, 'zhTW', '我準備好了！派我去英靈之門吧。[加入事件佇列]', '我準備好了！派我去英靈之門吧。[加入事件佇列]', 25549),
(127188, 'zhTW', '', '你準備好回應這榮耀的召喚了嗎，$c？', 25549),
(127187, 'zhTW', '在援軍抵達前我們無法繼續推進。聽好了，撤退！', '', 25549),
(127186, 'zhTW', '', '你們都聽到了！全部撤退！', 25549),
(127185, 'zhTW', '', '%s絕望地跪倒在地上。', 25549),
(127184, 'zhTW', '', '%s的眼神變得迷茫，獵槍掉落在地上。', 25549),
(127183, 'zhTW', '', '白髮人…不應該送黑髮人…', 25549),
(127182, 'zhTW', '', '亞羅德！他…他死了。我們必須撤退等援軍趕到！', 25549),
(127181, 'zhTW', '', '先讓…先讓我…坐下來歇歇…', 25549),
(127180, 'zhTW', '', '我…不行了…', 25549),
(127179, 'zhTW', '戰鬥領主！這裡！', '', 25549),
(127178, 'zhTW', '戰鬥領主，希望你準備好了。我帶了一些補給品，以備不時之需。', '', 25549),
(127177, 'zhTW', '準備好了，就去挑戰『強者』丹魯爾吧。只要站在符文上就可以開戰。', '', 25549),
(127176, 'zhTW', '準備好了，就去挑戰『強者』丹魯爾吧。只要站在符文上就可以開戰。', '', 25549),
(127175, 'zhTW', '戰鬥領主，希望你準備好了。我帶了一些補給品以備不時之需。', '', 25549),
(127174, 'zhTW', '戰鬥領主！這裡！', '', 25549),
(127173, 'zhTW', '戰士，謝謝你。', '', 25549),
(127172, 'zhTW', '我現在才聽懂那個薩滿的預言…我今天學會了謙卑，我會因此變得更強。', '', 25549),
(127171, 'zhTW', '戰士，我很想跟你交手，但前提是前面的人沒把你殺掉。', '', 25549),
(127170, 'zhTW', '我看你志在必得，但我比你更想贏，意志也更堅定。', '', 25549),
(127169, 'zhTW', '我跟族裡的薩滿聊過，他說我今天一定能贏。小戰士，我看你還是趁早退出好了。', '', 25549),
(127168, 'zhTW', '卜魯，沒想到你的力氣這麼大。我本來以為大小有差，是我錯了。', '', 25549),
(127167, 'zhTW', '想回去沒關係，通常我的對手只要看我一眼就認輸了。', '', 25549),
(127166, 'zhTW', '是可以陪你練習啦，可是我的舉重器材就跟你差不多大了。你先練壯一點再來。', '', 25549),
(127165, 'zhTW', '小不點，你的力量跟體型差不多吧。', '', 25549),
(127164, 'zhTW', '', '你如果失敗了，還有人會記得你的名字嗎…', 25549),
(127163, 'zhTW', '', '這不是你該來的地方，這是我們的地盤，只有我們才夠格參加試煉！', 25549),
(127162, 'zhTW', '', '光想到你失敗時他會多難堪，就覺得很有趣。', 25549),
(127161, 'zhTW', '', '歐丁派你當勇士真是太蠢了。', 25549),
(127160, 'zhTW', '', '絕對不能讓燃燒軍團得逞。', 25549),
(127159, 'zhTW', '誰也阻止不了我們！', '', 25549),
(127158, 'zhTW', '別想破壞我們的計畫。燃燒軍團一定會得到坎瑞薩德的力量！在我們面前倒下吧！', '', 25549),
(127157, 'zhTW', '聖光必勝！', '', 25549),
(127156, 'zhTW', '兄弟會勇往直前！', '', 25549),
(127155, 'zhTW', '見證聖光！', '', 25549),
(127154, 'zhTW', '啊，留一點給我殺。', '', 25549),
(127153, 'zhTW', '我必須撤退。', '', 25549),
(127152, 'zhTW', '我會…回來的…', '', 25549),
(127151, 'zhTW', '備感榮幸。', '', 25549),
(127150, 'zhTW', '我們一同前進吧。', '', 25549),
(127149, 'zhTW', '我來了。', '', 25549),
(127148, 'zhTW', '臣服在聖光之下吧！', '', 25549),
(127147, 'zhTW', '為了兄弟會！', '', 25549),
(127146, 'zhTW', '看我的厲害！', '', 25549),
(127145, 'zhTW', '掃蕩這片土地的黑暗吧。', '', 25549),
(127144, 'zhTW', '兄弟會一體同心！', '', 25549),
(127143, 'zhTW', '我們一起戰鬥。', '', 25549),
(127142, 'zhTW', '殺死暴風之盾入侵者：$1i', '', 25549),
(127141, 'zhTW', '殺死艾克索達入侵者：$1i', '', 25549),
(127140, 'zhTW', '殺死達納蘇斯入侵者：$1i', '', 25549),
(127139, 'zhTW', '殺死鐵爐堡入侵者：$1i', '', 25549),
(127138, 'zhTW', '殺死暴風城入侵者：$1i', '', 25549),
(127137, 'zhTW', '殺死戰爭之矛入侵者：$1i', '', 25549),
(127136, 'zhTW', '殺死銀月城入侵者：$1i', '', 25549),
(127135, 'zhTW', '殺死幽暗城入侵者：$1i', '', 25549),
(127134, 'zhTW', '殺死雷霆崖入侵者：$1i', '', 25549),
(127133, 'zhTW', '傳奇暴風之盾防衛者', '', 25549),
(127132, 'zhTW', '英雄暴風之盾防衛者', '', 25549),
(127131, 'zhTW', '暴風之盾防衛者', '', 25549),
(127130, 'zhTW', '傳奇艾克索達防衛者', '', 25549),
(127129, 'zhTW', '英雄艾克索達防衛者', '', 25549),
(127128, 'zhTW', '艾克索達防衛者', '', 25549),
(127127, 'zhTW', '傳奇達納蘇斯防衛者', '', 25549),
(127126, 'zhTW', '英雄達納蘇斯防衛者', '', 25549),
(127125, 'zhTW', '達納蘇斯防衛者', '', 25549),
(127124, 'zhTW', '傳奇鐵爐堡防衛者', '', 25549),
(127123, 'zhTW', '英雄鐵爐堡防衛者', '', 25549),
(127122, 'zhTW', '鐵爐堡防衛者', '', 25549),
(127121, 'zhTW', '傳奇暴風城防衛者', '', 25549),
(127120, 'zhTW', '英雄暴風城防衛者', '', 25549),
(127119, 'zhTW', '暴風城防衛者', '', 25549),
(127118, 'zhTW', '傳奇戰爭之矛防衛者', '', 25549),
(127117, 'zhTW', '英雄戰爭之矛防衛者', '', 25549),
(127116, 'zhTW', '戰爭之矛防衛者', '', 25549),
(127115, 'zhTW', '傳奇銀月城防衛者', '', 25549),
(127114, 'zhTW', '英雄銀月城防衛者', '', 25549),
(127113, 'zhTW', '銀月城防衛者', '', 25549),
(127112, 'zhTW', '傳奇幽暗城防衛者', '', 25549),
(127111, 'zhTW', '英雄幽暗城防衛者', '', 25549),
(127110, 'zhTW', '幽暗城防衛者', '', 25549),
(127109, 'zhTW', '傳奇雷霆崖防衛者', '', 25549),
(127108, 'zhTW', '英雄雷霆崖防衛者', '', 25549),
(127107, 'zhTW', '雷霆崖防衛者', '', 25549),
(127106, 'zhTW', '傳奇奧格瑪防衛者', '', 25549),
(127105, 'zhTW', '英雄奧格瑪防衛者', '', 25549),
(127104, 'zhTW', '疫病會吞噬你！', '', 25549),
(127103, 'zhTW', '誰都阻擋不了燃燒軍團！', '', 25549),
(127102, 'zhTW', '你別想活著離開這裡！', '', 25549),
(127101, 'zhTW', '奧格瑪防衛者', '', 25549),
(127100, 'zhTW', '殺死奧格瑪入侵者：$1i', '', 25549),
(127099, 'zhTW', '雖然雷斯特逃走了，但是我們會找到他的。希望那個時候你會再幫我一次。', '', 25549),
(127097, 'zhTW', '', '明智的決定。我們聯手會厲害很多。', 25549),
(127096, 'zhTW', '不管惡魔做了什麼，我們都不能退縮。', '不管惡魔做了什麼，我們都不能退縮。', 25549),
(127095, 'zhTW', '我…我沒辦法控制自己…', '我…我沒辦法控制自己…', 25549),
(127094, 'zhTW', '我的頭…別…別靠近那個東西！', '我的頭…別…別靠近那個東西！', 25549),
(127093, 'zhTW', '發…發生什麼事？', '發…發生什麼事？', 25549),
(127092, 'zhTW', '', '別洩氣，羅蘭。看來你的救星到了。', 25549),
(127091, 'zhTW', '|TInterface\\Icons\\ABILITY_HUNTER_PET_RAPTOR.BLP:20|t%s |cFFFF0000|Hspell:235886|h[呼喚]|h|r她的龍群！', '', 25549),
(127090, 'zhTW', '', '嗯，太美妙了…就像是黑暗裡的一把刀！你的最後一個目標在暴風城。這會是難度最高的目標！', 25549),
(127089, 'zhTW', '', '就是他，靠牆的那個。聽說這懦夫以為光靠護甲就能保住小命。給他一點顏色瞧瞧！', 25549),
(127088, 'zhTW', '', '死前的吶喊…真是悅耳！我們發現下一個目標在鐵爐堡，就躲在矮人議會廳的暗處。', 25549),
(127087, 'zhTW', '', '你的目標在戰士區附近開花園派對。要小心！她的朋友都是厲害的施法者，而她也不例外。小心那些守衛。', 25549),
(127086, 'zhTW', '', '啊，做得好…太美妙了！你的下一個目標在達納蘇斯。建議你從泰達希爾下方的村莊進去。', 25549),
(127085, 'zhTW', '', '你的第一個目標是假扮的牧師，他會在城市裡面到處走動。小心他的水晶魔像！可以的話把魔像引開…最好別被發現。', 25549),
(127084, 'zhTW', '', '記住…雖然你是在幫他們，但聯盟會以為你在攻擊他們的成員。', 25549),
(127083, 'zhTW', '', '我們不能讓你在盟友的城市裡進行暗殺活動，但在艾克索達就不會有人懷疑你了。那個目標交給你，銀月城我來負責。', 25549),
(127082, 'zhTW', '', '真可憐！他們根本逃不過暗影的追擊。來吧，去見見你的同事。拉文霍德領主有禮物要送你。', 25549),
(127081, 'zhTW', '', '那裡！就在人潮最多的拍賣場裡。別發出聲音，一招致命，然後趕快消失！', 25549),
(127080, 'zhTW', '', '嗯，太美妙了…就像是黑暗裡的一把刀！你的最後一個目標在奧格瑪。這會是難度最高的目標！', 25549),
(127079, 'zhTW', '', '就是他，營火旁邊那個。聽說這懦夫以為光靠護甲就能保住小命。給他一點顏色瞧瞧！', 25549),
(127078, 'zhTW', '', '死前的吶喊…真是悅耳！我們發現下一個目標在雷霆崖，就躲在牛頭人長老背後呢。', 25549),
(127077, 'zhTW', '', '你的目標在盜賊區上方的露臺開茶會。小心！她的朋友都是厲害的施法者，而她也不例外。你得想個辦法上去。', 25549),
(127076, 'zhTW', '', '啊，做得好…太美妙了！你的下一個目標在幽暗城。建議你從西邊的下水道進去。', 25549),
(127075, 'zhTW', '', '你的第一個目標是有錢的貴族，他會在城市裡到處走動。小心他的秘法魔像！可以的話先把魔像引開…千萬別被發現。', 25549),
(127074, 'zhTW', '', '記住…雖然你是在幫他們，但部落會以為你在攻擊他們的成員。', 25549),
(127073, 'zhTW', '', '我們不能讓你在盟友的城市裡進行暗殺活動，但在銀月城就不會有人懷疑你了。那個目標交給你，艾克索達我來負責。', 25549),
(127072, 'zhTW', '', '我們的密探在銀月城和艾克索達發現了可疑的惡魔人偶。', 25549),
(127071, 'zhTW', '', '惡魔知道自己混進來會被伊利達瑞發現，所以它們派了這些…惡魔人偶。', 25549),
(127070, 'zhTW', '', '看來燃燒軍團的驚懼領主已經打造出栩栩如生的不死族手下，連我都很難看出破綻！　', 25549),
(127069, 'zhTW', '', '他講話很有條理，而且他的皮膚…還真好。但還是有幾個小地方露出了馬腳。', 25549),
(127068, 'zhTW', '', '不該有這樣的反應，而且絕對不會是這種顏色。', 25549),
(127067, 'zhTW', '', '你看，從這裡切開的話…', 25549),
(127066, 'zhTW', '', '我自認是個厲害的不死族剋星，但就連我一開始也沒發現。', 25549),
(127065, 'zhTW', '', '影尊！這裡！', 25549),
(127064, 'zhTW', '|TInterface\\Icons\\SPELL_NATURE_UNRELENTINGSTORM.BLP:20|t%s開始施放|cFFFF0000|Hspell:235766|h[閃電新星]|h|r！', '', 25549),
(127063, 'zhTW', '', '來吧，羅蘭。離開這個邪惡的地方，不然你又要生病了。', 25549),
(127062, 'zhTW', '世界已經夠黑暗了，容不下更多陰影。謝謝你，勇士。', '', 25549),
(127061, 'zhTW', '埃雷達爾咒術師正從虛無之中召喚黑暗勢力。快阻止他們！', '', 25549),
(127060, 'zhTW', '', '這個地方是不是會讓你想家啊？', 25549),
(127059, 'zhTW', '', '羅蘭，你不用去其他地方嗎？', 25549),
(127058, 'zhTW', '', '羅蘭，你一定要靠這麼近嗎？', 25549),
(127057, 'zhTW', '', '躲好，英雄們！', 25549),
(127056, 'zhTW', '我們會開啟傳送門通往他的所在地，但無法維持太久。一定要阻止雷斯特！', '', 25549),
(127055, 'zhTW', '卡拉孟堅持要早你一步過去，不過我擔心他一個人會應付不來。', '', 25549),
(127054, 'zhTW', '我們知道的情報很有限，但看來他似乎有辦法利用扭曲虛空的能量來強化他的死靈魔法。', '', 25549),
(127053, 'zhTW', '勇士！我們的法師找到雷斯特‧法哲理在扭曲虛空裡的位置了！', '', 25549),
(127052, 'zhTW', '打倒那個大傢伙！一定要守住這裡！', '打倒那個大傢伙！一定要守住這裡！', 25549),
(127051, 'zhTW', '我要先去其他地方了。我幫你準備一份…送別禮物！', '', 25549),
(127050, 'zhTW', '我最好回去作戰。', '我最好回去作戰。', 25549),
(127049, 'zhTW', '牧師，我欠你一命。', '牧師，我欠你一命。', 25549),
(127048, 'zhTW', '我會記住你這份恩情。', '我會記住你這份恩情。', 25549),
(127047, 'zhTW', '我欠你人情。', '我欠你人情。', 25549),
(127046, 'zhTW', '霧氣終於消散了…', '霧氣終於消散了…', 25549),
(127045, 'zhTW', '痛苦減輕了。謝謝你，$n。', '痛苦減輕了。謝謝你，$n。', 25549),
(127044, 'zhTW', '十分感謝。', '十分感謝。', 25549),
(127039, 'zhTW', '我們得先把阿格拉瑪之盾放好。各位英雄，準備好就開始吧！', '', 25549),
(127038, 'zhTW', '準備戰鬥！惡魔要來了！', '準備戰鬥！惡魔要來了！', 25549),
(127037, 'zhTW', '砲手注意，炸掉這個凡人雜碎！用地獄烈火殺光他們！', '', 25549),
(127032, 'zhTW', '我們準備好了。', '我們準備好了。', 25549),
(127031, 'zhTW', '準備應戰！沒拿到盾以前，燃燒軍團不會善罷干休。', '準備應戰！沒拿到盾以前，燃燒軍團不會善罷干休。', 25549),
(127030, 'zhTW', '冰霜十字是無比強大的物品。瘋子才會輕易嘗試要在同時間持有兩個。等你派出冰霜巨龍之後，我們就能開始進行下一個召喚儀式。', '', 25549),
(127029, 'zhTW', '我們為什麼不能開始進行下一個儀式？', '我們為什麼不能開始進行下一個儀式？', 25549),
(127028, 'zhTW', '看來你削減了這些怪物的數量。很好！絕對不能讓牠們蔓延到海岸線以外的地方。', '', 25549),
(127027, 'zhTW', '', '我們目前沒有辦法同時擁有兩個裂隙核心。你身上還有一個。等你釋放完了之後，我們才能開始為下一個充能。', 25549),
(127026, 'zhTW', '鷹身人已經夠討厭了，居然還對燃燒軍團效忠？無法忍受！勇士，快想辦法控制局面。', '', 25549),
(127025, 'zhTW', '為什麼我們無法為裂隙核心充能？', '為什麼我們無法為裂隙核心充能？', 25549),
(127024, 'zhTW', '太遲了，凡人！我的指揮艦來了！', '', 25549),
(127023, 'zhTW', '', '達拉然之力無法連續引導。你身上似乎仍有一枚水晶法器。等你釋放了之後，我的法師就能再幫你製作一個。', 25549),
(127022, 'zhTW', '我們為什麼無法把法力聚集在下一個水晶上？', '我們為什麼無法把法力聚集在下一個水晶上？', 25549),
(127021, 'zhTW', '', '煉獄火非常強大、不易控制。召喚時必須非常小心。你身上還有一個骨匣，想要再取得一個並非明智之舉。', 25549),
(127020, 'zhTW', '我們為什麼沒辦法再召喚一個煉獄火？', '我們為什麼沒辦法再召喚一個煉獄火？', 25549),
(127019, 'zhTW', '', '抱歉，在你指派目前的部隊出擊前，我們無法再號召新的突擊部隊。', 25549),
(127018, 'zhTW', '為什麼我無法號召華爾琪？', '為什麼我無法號召華爾琪？', 25549),
(127017, 'zhTW', '旅行者，前面不安全。那個地方有傳染病。', '旅行者，前面不安全。那個地方有傳染病。', 25549),
(127016, 'zhTW', '', '嗯，真令人遺憾。但像你這麼優秀的牧師應該能把他救活吧？', 25549),
(127015, 'zhTW', '很抱歉，但以我們目前的軍隊數量，一次只有辦法籌備一個先鋒部隊。等你下達指令之後，我們就能號召下一個。', '', 25549),
(127014, 'zhTW', '為什麼我沒辦法號召下一個先鋒部隊？', '為什麼我沒辦法號召下一個先鋒部隊？', 25549),
(127013, 'zhTW', '', '別吵了！趕快去救船艦！', 25549),
(127012, 'zhTW', '', '我的小絲瑟諾，現在不是追究的時候。牠們一開始就把武器打壞了。如果你能幫忙對付這些邪惡的生物，我們就可以開始進行維修！', 25549),
(127011, 'zhTW', '', '懷惡族母，根本就不該讓它們靠近的。為什麼魔錘號沒有對敵人開火？', 25549),
(127010, 'zhTW', '', 'Cue awesome scene of the Fel Hammer destroying one of the Legion ships and the others jumping away!', 25549),
(127009, 'zhTW', '', '絲瑟諾，你說得沒錯。我們必須承擔風險，否則必死無疑。斬魔者，我們必須前往樓上的主控臺！', 25549),
(127006, 'zhTW', '', '大領主，謝謝你讓我的祖先安息。', 25549),
(127005, 'zhTW', '', '大領主，只有你的武器能釋放這些魔縛靈魂。摧毀我祖先們的墜飾，解除這個古老的詛咒。', 25549),
(127004, 'zhTW', '', '做得好，勇士。願他們的靈魂能得到安息。', 25549),
(127003, 'zhTW', '', '廢墟裡的靈魂因為古老的誓約，被迫服從燃燒軍團。讓他們得到安息吧。', 25549),
(127002, 'zhTW', '如果你需要新的肩膀附魔，記得再來找我。我幫你想辦法。', '', 25549),
(127001, 'zhTW', '太神奇了！在魔法消失之前好好享受吧。', '', 25549),
(127000, 'zhTW', '你有病最好去看醫生。', '你有病最好去看醫生。', 25549),
(126999, 'zhTW', '謠傳埋在這座廢墟中的骸骨具有特殊的魔法屬性。我們就來看看傳說是不是真的！帶回那些古老的骸骨，把它們放在那座祭壇上。', '', 25549),
(126998, 'zhTW', '可惡！我要成立自己的法師議會…要有爐石…還有魅魔！算了，議會無聊死了！', '', 25549),
(126997, 'zhTW', '希望你不介意我抽成。', '', 25549),
(126996, 'zhTW', '我要多收額外費用…', '', 25549),
(126995, 'zhTW', '喂！別打我！打那個英雄！', '', 25549),
(126994, 'zhTW', '我會找到比你更好的人。', '我會找到比你更好的人。', 25549),
(126993, 'zhTW', '我們絕對絕對分定了。', '我們絕對絕對分定了。', 25549),
(126992, 'zhTW', '我就是沒那麼喜歡你。', '我就是沒那麼喜歡你。', 25549),
(126991, 'zhTW', '我本來以為會是你！', '我本來以為會是你！', 25549),
(126990, 'zhTW', '就只有那一次而已。', '就只有那一次而已。', 25549),
(126989, 'zhTW', '你要賠我…醫藥費。', '', 25549),
(126988, 'zhTW', '就只有那一次而已。', '就只有那一次而已。', 25549),
(126987, 'zhTW', '這就是不給小費的下場！', '', 25549),
(126986, 'zhTW', '我真的要按照屍體數來收費了。', '', 25549),
(126985, 'zhTW', '我們分手吧。', '我們分手吧。', 25549),
(126984, 'zhTW', '耶，我就是這麼厲害。', '', 25549),
(126983, 'zhTW', '對不起，你是個好人。', '對不起，你是個好人。', 25549),
(126982, 'zhTW', '這工作有危險加給嗎…', '', 25549),
(126981, 'zhTW', '我們還是能繼續當朋友。', '我們還是能繼續當朋友。', 25549),
(126980, 'zhTW', '哦，我有個適合你的魔術表演！', '', 25549),
(126979, 'zhTW', '你也想變成毛絨絨的兔子嗎？', '', 25549),
(126978, 'zhTW', '', '可惡！快走！', 25549),
(126977, 'zhTW', '需要幫忙嗎？', '', 25549),
(126976, 'zhTW', '選張牌！隨便一張都行！', '', 25549),
(126975, 'zhTW', '歡迎，歡迎！自己拿點免費的食物飲料，別客氣。', '歡迎，歡迎！自己拿點免費的食物飲料，別客氣。', 25549),
(126974, 'zhTW', '最後一次點餐囉！我要開傳送門去下一家旅店了！', '最後一次點餐囉！我要開傳送門去下一家旅店了！', 25549),
(126973, 'zhTW', '大家出發囉！去下一家旅店！', '大家出發囉！去下一家旅店！', 25549),
(126972, 'zhTW', '今天收集到的聖物應該夠多了。讓那些幽靈恢復平靜吧。好好享受你的戰利品！', '', 25549),
(126971, 'zhTW', '我藏了一張王牌！', '', 25549),
(126970, 'zhTW', '這樣古老的廢墟裡到處都是讓收藏家眼睛一亮的珍寶。去那裡盡量收集聖物，但是要小心那些遊蕩的幽靈！', '', 25549),
(126969, 'zhTW', '魔術大師阿卡贊札拉克出場啦！', '', 25549),
(126968, 'zhTW', '想要我秀幾手就拿出你的金幣！', '', 25549),
(126967, 'zhTW', '好，讓這群笨蛋見識一下我的厲害。', '', 25549),
(126966, 'zhTW', '你好啊，$c，你想研究更多關於神兵武器的知識嗎？\n\n我很想幫助你，但你身上好像有神兵武器研究筆記，閱讀以後就可以提升知識。', '你好啊，$c，你想研究更多關於神兵武器的知識嗎？\n\n我很想幫助你，但你身上好像有神兵武器研究筆記，閱讀以後就可以提升知識。', 25549),
(126965, 'zhTW', '先喘口氣吧，英雄。這是你應得的。', '', 25549),
(126964, 'zhTW', '勇士！抵擋燃燒軍團的部隊。幫助前線的盟軍，堅守陣地！', '', 25549),
(126962, 'zhTW', '燃燒軍團耍詐！它們攻擊只是為了引開我們，好讓它們專心在盾息之島上建立據點！', '', 25549),
(126961, 'zhTW', '燃燒軍團竟敢攻擊斯鐸海姆！勇士，殺光那些邪惡的生物，你會得到無盡的榮耀！', '', 25549),
(126958, 'zhTW', '嗯，要不要再試一次？', '嗯，要不要再試一次？', 25549),
(126957, 'zhTW', '你進步了。', '你進步了。', 25549),
(126956, 'zhTW', '這招不錯。', '這招不錯。', 25549),
(126955, 'zhTW', '別放棄。', '別放棄。', 25549),
(126954, 'zhTW', '加油。', '加油。', 25549),
(126953, 'zhTW', '再一次！', '再一次！', 25549),
(126952, 'zhTW', '你好像準備好了。', '你好像準備好了。', 25549),
(126951, 'zhTW', '可憐。', '可憐。', 25549),
(126950, 'zhTW', '我們開始吧。', '我們開始吧。', 25549),
(126949, 'zhTW', '感謝你幫忙，我們現在可以製造出有用的解藥了。', '', 25549),
(126948, 'zhTW', '我們的人被亞蘭希抓去餵牠們骯髒的孩子了！殺死這些蜘蛛怪物，收集牠們的毒囊，我們可以用來製造解毒劑。', '', 25549),
(126947, 'zhTW', '我們的部隊平安回到營地了。最重要的是，大家中的毒都解了。做得很好！', '', 25549),
(126946, 'zhTW', '亞蘭希把我們的人抓去餵她那些殘暴的孩子。宗師，我們得靠你的力量去殺死那個惡魔，還要想辦法幫俘虜解毒！', '', 25549),
(126945, 'zhTW', '我要離開這裡了！', '我要離開這裡了！', 25549),
(126944, 'zhTW', '我剛剛差點就不行了！謝謝你。', '我剛剛差點就不行了！謝謝你。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126943, 'zhTW', '謝謝你，宗師。', '謝謝你，宗師。', 25549),
(126942, 'zhTW', '你吵醒幽靈了！', '你吵醒幽靈了！', 25549),
(126941, 'zhTW', '這樣頂多只能拖延攻勢。做好準備，敵人不會只有這些。', '', 25549),
(126940, 'zhTW', '打垮敵人！粉碎它們在這裡的據點！趕盡殺絕，不留活口！', '', 25549),
(126939, 'zhTW', '夠了！', '', 25549),
(126938, 'zhTW', '燃燒軍團正在撤退！趕快離開飛船！角鷹獸會接住你的！', '', 25549),
(126937, 'zhTW', '又來了，你知道把護甲穿回去要花多少時間嗎？哼。', '又來了，你知道把護甲穿回去要花多少時間嗎？哼。', 25549),
(126936, 'zhTW', '艾拉得，我把材料帶來了。', '艾拉得，我把材料帶來了。', 25549),
(126935, 'zhTW', '雖然說耐心是美德，但現在情況不允許我們這麼做。做好準備吧。', '', 25549),
(126934, 'zhTW', '', '你覺得你的夥伴準備好要一起攻擊了嗎？', 25549),
(126933, 'zhTW', '', '如果不好好訓練就等著被淘汰吧，很多事情沒有第二次機會。', 25549),
(126932, 'zhTW', '如果格雷森知道我們做了什麼，應該會很高興。幫我向他問好。', '', 25549),
(126931, 'zhTW', '完成了！不是我在說，這個作品我真的很滿意！拿去吧。', '', 25549),
(126930, 'zhTW', '最後，再嵌上重要的珠寶！', '', 25549),
(126929, 'zhTW', '然後用力敲打脈石這裡…還有這裡…', '', 25549),
(126928, 'zhTW', '首先，我得把礦熔了…', '', 25549),
(126927, 'zhTW', '好，我們來改造護具吧！', '', 25549),
(126926, 'zhTW', '我…我還活著，但是已經不能戰鬥了。勇士，快一點，你一定要阻止他！', '', 25549),
(126925, 'zhTW', '做得好。反過來利用那些大塊頭的力量對付他們，真是…太有破壞力了！', '', 25549),
(126924, 'zhTW', '納迦對我們的計畫是一大阻礙。我們制伏了一個納迦蠻卒，騎著它上戰場，攻擊納迦！', '', 25549),
(126923, 'zhTW', '把我傳送到影歌。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '把我傳送到影歌。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(126922, 'zhTW', '格雷森，我準備好要回去了。', '格雷森，我準備好要回去了。', 25549),
(126921, 'zhTW', '大領主，準備回職業大廳就跟我說一聲吧。我會把你安全送回去的。', '', 25549),
(126920, 'zhTW', '準備好離開的時候跟我說，我會想辦法讓我們平安回去。', '', 25549),
(126919, 'zhTW', '我們到聖光會堂集合，在那裡可以安全地幫這野獸裝上護具。', '', 25549),
(126918, 'zhTW', '大領主，抓到野獸了！聖光真是眷顧我們！', '', 25549),
(126916, 'zhTW', '那匹馬！快，抓住牠！', '', 25549),
(126915, 'zhTW', '你們這些可憐的雜兵，馬上就要加入我的不死大軍了！', '', 25549),
(126914, 'zhTW', '你們這些可憐的雜兵，馬上就要加入我的不死大軍了！', '', 25549),
(126913, 'zhTW', '你在找什麼嗎？！哈哈哈！', '', 25549),
(126912, 'zhTW', '被拿走了！這下不好了…', '', 25549),
(126911, 'zhTW', '他的屍體呢？！應該在這裡的！', '', 25549),
(126910, 'zhTW', '他們會在我們對付瑞文戴爾的時候，替我們守住後方。', '', 25549),
(126909, 'zhTW', '聖騎士，上坐騎！前進！', '', 25549),
(126908, 'zhTW', '完成了。護具準備好了。現在就去瑞文戴爾的墓穴對抗他的幽靈。', '', 25549),
(126907, 'zhTW', '我會把聖水灑在護具上。剩下的，就看你和這把武器了，大領主。', '', 25549),
(126906, 'zhTW', '收集聖水的任務做得很好，大領主。你還救了我的聖騎士，感激不盡。', '', 25549),
(126905, 'zhTW', '沒事了？！我在做夢嗎？大領主，是你…我…我應該能找到回去的路。謝謝你。', '沒事了？！我在做夢嗎？大領主，是你…我…我應該能找到回去的路。謝謝你。', 25549),
(126904, 'zhTW', '感覺好像靈魂被撕裂，慢慢從身體裡扯出來。那個死靈法師，他…我得去找格雷森。', '感覺好像靈魂被撕裂，慢慢從身體裡扯出來。那個死靈法師，他…我得去找格雷森。', 25549),
(126903, 'zhTW', '我們被包圍了。我…我想抵抗，但是…大領主，謝謝你救我。', '我們被包圍了。我…我想抵抗，但是…大領主，謝謝你救我。', 25549),
(126902, 'zhTW', '腐嘴，把他們的內臟吃光！', '', 25549),
(126901, 'zhTW', '吸吧！吸完帕斯楚侖的氣體就可以加入我的大軍了！', '', 25549),
(126900, 'zhTW', '奧瑟因會給你一個痛快！', '', 25549),
(126898, 'zhTW', '聖騎士，你救不了那些盟友了。我會用他們的靈魂讓軍隊變得更強…', '', 25549),
(126897, 'zhTW', '死亡才是這座城市的主宰！馬上也會是你的主宰！', '', 25549),
(126896, 'zhTW', '聖騎士，你這是在浪費力氣！死亡會吞沒這整座城市…', '', 25549),
(126895, 'zhTW', '或許像你這樣強大的人能幫忙取回聖水。帶我的兩個聖騎士一起去吧。外面還有什麼東西誰也說不準。', '', 25549),
(126894, 'zhTW', '我派了三個最厲害的手下去找，卻沒有人回來，我擔心他們出事了。', '', 25549),
(126893, 'zhTW', '歡迎，大領主。我正在為護具的淨化儀式做準備。但我們一直到現在都無法取得聖水。', '', 25549),
(126892, 'zhTW', '我們去對付指揮官坎托馬斯。(需要強能鑰石)', '我們去對付指揮官坎托馬斯。(需要強能鑰石)', 25549),
(126891, 'zhTW', '我們去對付指揮官厄德里斯。(使用亞羅德給的鑰石。)', '我們去對付指揮官厄德里斯。(使用亞羅德給的鑰石。)', 25549),
(126890, 'zhTW', '$n，艱難而危險的任務在等著我們。這兩位堅持要跟來「確保我們圓滿達成」。他們完全沒有這麼做的必要。', '', 25549),
(126889, 'zhTW', '', '你會…付出代價！你會…付出…', 25549),
(126888, 'zhTW', '', '不…我的寶貝！', 25549),
(126887, 'zhTW', '你讓我們的部隊不再受到惱人的空襲。嗯，或許伊利達瑞用得上你抓到的魔化幼蝠…', '', 25549),
(126886, 'zhTW', '', '不過，我要先處罰你奪走我的小寵物。', 25549),
(126885, 'zhTW', '', '此時，我的薩亞德迷惑了你那些意志軟弱的法師。你的盟友會很樂意向燃燒軍團屈服！', 25549),
(126884, 'zhTW', '', '太遲了，英雄！蕾薇亞的力量是我的了！有了她的知識，我的手下就能混進祈倫托，從內部瓦解他們！', 25549),
(126883, 'zhTW', '魔化蝙蝠！我討厭有翅膀的惡魔！牠們不只騷擾部隊，還繁殖得很快。我們要削減牠們的數量！', '', 25549),
(126882, 'zhTW', '', '一定要阻止鬼母！祝你好運，勇士。', 25549),
(126881, 'zhTW', '', '她的藏身處有重兵防守，不過祈倫托的法師可以開一個通往她位置的臨時傳送門。', 25549),
(126880, 'zhTW', '', '她大概已經能駕馭從蕾薇亞那裡偷來的力量了。這樣的話，沒人知道她會做出什麼事。', 25549),
(126879, 'zhTW', '', '勇士，很高興找到你。維朵莉亞想必已經告訴你，我們找到鬼母亞加薩了。', 25549),
(126878, 'zhTW', '', '動作快！我們快擋不住燃燒軍團了！', 25549),
(126877, 'zhTW', '', '有空多來布瑞登溪看看，這裡可以讓你盡情打鳥！', 25549),
(126876, 'zhTW', '', '和你共事是我的榮幸！謝謝你救了我們。', 25549),
(126875, 'zhTW', '英雄，謝謝你。我們成功阻止了燃燒軍團的計畫。祈倫托知道的話一定很高興。他們給了我一樣東西，方便讓你回去找他們。', '', 25549),
(126874, 'zhTW', '希望你能安息，指揮官。', '', 25549),
(126873, 'zhTW', '城堡…失守了…', '', 25549),
(126872, 'zhTW', '靈魂能承受很大的痛苦，但慢慢被惡魔能量吞噬，是超乎凡人想像的恐怖折磨。', '', 25549),
(126871, 'zhTW', '燃燒軍團的船艦墜毀時，釋放出一些用來建造它的靈魂。這些靈魂在哀嚎，困在永恆的折磨裡無法解脫。拜託你，結束它們的苦難。', '', 25549),
(126870, 'zhTW', '士兵們起來吧！接受我的禮物，阻止燃燒軍團！', '', 25549),
(126869, 'zhTW', '我不會讓你繼續為非作歹，厄德里斯！', '', 25549),
(126868, 'zhTW', '開始行動吧。', '', 25549),
(126867, 'zhTW', '勇士，小心，有個東西從傳送門裡出現了…強大的東西！', '', 25549),
(126866, 'zhTW', '見識惡魔法術的力量！', '', 25549),
(126864, 'zhTW', '大家先喘口氣吧，馬上要行動了。', '', 25549),
(126863, 'zhTW', '準備好了。厄德里斯已經被燃燒軍團腐化，看誰都是敵人。', '', 25549),
(126862, 'zhTW', '感謝伊露恩！你成功了！我們差點就撐不住了。', '', 25549),
(126861, 'zhTW', '感謝你，俘虜重獲自由，也沒有生命危險。做得好。', '', 25549),
(126860, 'zhTW', '附近關了很多俘虜。請你想辦法放了他們，勇士！', '', 25549),
(126859, 'zhTW', '他們奉獻生命，應該好好安息。你做得很好。', '', 25549),
(126858, 'zhTW', '魔化圖騰牛頭人在褻瀆死者的遺體。沒有人該受到這種對待，讓他們好好安息吧，勇士。', '', 25549),
(126857, 'zhTW', '可笑的凡人！你真的以為，要打倒燃燒軍團很容易嗎？', '', 25549),
(126856, 'zhTW', '敢阻擋蕾瑟拉，她絕不手下留情！', '', 25549),
(126855, 'zhTW', '<示意要蝌蚪跟著你。>', '<示意要蝌蚪跟著你。>', 25549),
(126854, 'zhTW', '真可憐！希蕊妮竟然吩咐外來者替她做事？', '', 25549),
(126853, 'zhTW', '你別想阻止我們！', '', 25549),
(126852, 'zhTW', '', '替我向莫德菈致意。還有…謝謝你。', 25549),
(126851, 'zhTW', '', '後…後面…', 25549),
(126850, 'zhTW', '哥哥，我又在幫你收拾殘局了！', '', 25549),
(126849, 'zhTW', '沒用！走開，哥哥，你辦不到的事我來做。', '', 25549),
(126848, 'zhTW', '咕咕莫咯姆爾姆？', '', 25549),
(126847, 'zhTW', '[OLD DNT]$ct，請快一點，前線需要你！', '', 25549),
(126846, 'zhTW', '有人混進城裡了！', '有人混進城裡了！', 25549),
(126845, 'zhTW', '我完蛋了！', '我完蛋了！', 25549),
(126844, 'zhTW', '救命啊！救命啊！', '救命啊！救命啊！', 25549),
(126843, 'zhTW', '這裡有燃燒軍團的間諜！', '這裡有燃燒軍團的間諜！', 25549),
(126842, 'zhTW', '大壞蛋，我一定反抗到底！', '大壞蛋，我一定反抗到底！', 25549),
(126841, 'zhTW', '有刺客！', '有刺客！', 25549),
(126840, 'zhTW', '有誰能幫幫我！', '有誰能幫幫我！', 25549),
(126839, 'zhTW', '救命！我被攻擊了！', '救命！我被攻擊了！', 25549),
(126838, 'zhTW', '啊！這個樣本真好，死亡領主。拿去，這應該能派上用場。', '', 25549),
(126837, 'zhTW', '', '原諒我，大領主。我…我需要一個人靜一靜。', 25549),
(126836, 'zhTW', '沒想到死靈法術能這樣用。真有趣…黑暗法術還真是有其用處。', '', 25549),
(126835, 'zhTW', '你手下的巫妖表示有個計劃需要用到魔能祭品的骸骨。如果你覺得對我們有幫助，就協助他吧。但你最好管住那個…東西。', '', 25549),
(126834, 'zhTW', '被火海淹沒吧！', '', 25549),
(126833, 'zhTW', '燃燒軍團隨時都在想方設法，扭曲它們所佔領的世界。', '', 25549),
(126832, 'zhTW', '被折磨的死者聽從惡魔主人的號召。趕快擊退他們！', '', 25549),
(126831, 'zhTW', '', '你不會後悔的，大德魯伊！隨時準備行動！', 25549),
(126830, 'zhTW', '雖然把卡斯拉納提爾的牢籠當作達拉然武器的能源，只是權宜之計。但惡魔的精華沒有漏出來真的讓我鬆了一口氣。來吧，我們先回守護者殿堂。', '', 25549),
(126828, 'zhTW', '', '天殺的！', 25549),
(126827, 'zhTW', '抓到你了！', '', 25549),
(126826, 'zhTW', '', '啊啊！我的頭…', 25549),
(126825, 'zhTW', '門要關了…小心！', '', 25549),
(126824, 'zhTW', '這邊！', '', 25549),
(126823, 'zhTW', '裡面一定還有更多守軍。黑羽堡主死了，我敢打賭厄德里斯已經把堡主的房間佔為己有。他一直都很自以為是。', '', 25549),
(126822, 'zhTW', '', '什麼…鬼東西啊！？', 25549),
(126821, 'zhTW', '', '我要殺了你！給我記住！', 25549),
(126820, 'zhTW', '', '你破壞了我的幻象！可惡的混蛋！', 25549),
(126819, 'zhTW', '做得好！摧毀惡魔劫奪者，等於是給燃燒軍團一記沉重的打擊。', '', 25549),
(126818, 'zhTW', '要是不解決這個惡魔劫奪者，盟友恐怕會有生命危險。', '', 25549),
(126817, 'zhTW', '', '不！不可能！', 25549),
(126816, 'zhTW', '', '哇，你很強。殺了你一定很有意思！', 25549),
(126815, 'zhTW', '', '不！你做了什麼！你要付出代價！', 25549),
(126814, 'zhTW', '大法師，聽說你已經把卡斯拉納提爾這個惡魔困在夜裔靈魂石裡了。你還做了一個護盾，可以安全地使用他的惡魔力量，真是了不起！', '', 25549),
(126813, 'zhTW', '', '來呀，英雄，來玩玩吧。', 25549),
(126812, 'zhTW', '', '雖然我對蕾薇亞很滿意，不過不收禮物就太沒禮貌了。', 25549),
(126811, 'zhTW', '', '祈倫托是想多送幾個玩具給我嗎？', 25549),
(126810, 'zhTW', '黑羽堡主會擅離職守，我可不會。士兵們，進攻！', '', 25549),
(126809, 'zhTW', '', '與其讓他們踩爛田地，不如在這裡殺了他們！快開始吧，精靈。', 25549),
(126808, 'zhTW', '', '我才不要袖手旁觀！我不想看到村子再受到攻擊！', 25549),
(126807, 'zhTW', '你們真會挑時間，這裡隨時都可能受到攻擊。趁現在還來得及，請兩位趕緊回布瑞登溪吧，這場戰爭跟你們無關。', '', 25549),
(126806, 'zhTW', '福咻菇凋零了。願她的孢子永遠在贊格的風中飄揚！', '', 25549),
(126805, 'zhTW', '福咻菇來了！', '', 25549),
(126804, 'zhTW', '福咻菇沒有幫助的話，無法在地面上存活太久。我們需要治療者、醫護人員，還有香菇修補者來保護她！', '', 25549),
(126803, 'zhTW', '各位孢子人、各位榮譽孢子人，請注意！請仔細看好福咻菇奇蹟般的生長！', '', 25549),
(126802, 'zhTW', '法姆巴發現蕾薇亞的蹤跡了！', '', 25549),
(126801, 'zhTW', '法姆巴，去找蕾薇亞！', '法姆巴，去找蕾薇亞！', 25549),
(126800, 'zhTW', '法姆巴耐心待命，要追蹤蕾薇亞。', '', 25549),
(126799, 'zhTW', '', '我們會把這群海鶴帶去安全的地方。等到破碎海岸再也沒有惡魔，牠們的後代就能回來這裡。', 25549),
(126798, 'zhTW', '好想…睡。', '', 25549),
(126797, 'zhTW', '我厭倦跟活人打交道了。', '', 25549),
(126796, 'zhTW', '夠了！我要回去睡覺！', '', 25549),
(126795, 'zhTW', '', '鋸齒海灣的鱷魚正在攻擊一群海鶴。幫我集合那群可憐的海鶴，然後帶到安全的地方去！', 25549),
(126794, 'zhTW', '', '可惡！惡魔摧毀了破碎海岸的許多棲息地，害野生動物無家可歸了！', 25549),
(126793, 'zhTW', '', '趁小鬼僕從還沒有強化亞加薩，趕緊殺死小鬼僕從！', 25549),
(126792, 'zhTW', '', '謝謝你們支援！那些惡魔對戈德林算不上威脅，但數量這麼多，誰知道會發生什麼事…', 25549),
(126791, 'zhTW', '', '戈德林需要我們！有個惡魔耍詐帶了幫手。我們一定要讓他自作自受！', 25549),
(126790, 'zhTW', '', '太好了。你真厲害，大德魯伊！', 25549),
(126789, 'zhTW', '', '戈德林把獵物逼進了死角，我們應該去助他一臂…呃…一「爪」之力…只要是尖的都可以！', 25549),
(126787, 'zhTW', '法姆巴認得味道。到傳送門另一邊跟他碰面，他會帶你找到失蹤的法師。', '', 25549),
(126786, 'zhTW', '', '孩子啊，保護我！我會給你們力量！', 25549),
(126785, 'zhTW', '裘貝卡，你在嗎？別讓它們把我帶走！我無法接受這種結局！', '', 25549),
(126784, 'zhTW', '別再耍花招了！', '', 25549),
(126783, 'zhTW', '送我到露臺去。', '送我到露臺去。', 25549),
(126782, 'zhTW', '[PH] A Legion ship materializes in the distance.', '[PH] A Legion ship materializes in the distance.', 25549),
(126781, 'zhTW', '這些補給品一定能派上用場。勇士，幹得好。', '', 25549),
(126780, 'zhTW', '勇士！我們找到了部落飛船的殘骸。在燃燒軍團開始掠奪之前搶先行動。', '', 25549),
(126779, 'zhTW', '勇士，你讓燃燒軍團損失慘重。清除惡魔的行動開始了。我們會再見面的。', '', 25549),
(126778, 'zhTW', '|TInterface\\Icons\\spell_fire_felrainoffire:20|t燃燒軍團船艦開始發動|cFFFF0404|Hspell:235085|h[魔化轟炸]|h|r！小心！', '', 25549),
(126777, 'zhTW', '想！', '想！', 25549),
(126776, 'zhTW', '氣球節快樂！想搭熱氣球到處看看嗎？', '氣球節快樂！想搭熱氣球到處看看嗎？', 25549),
(126775, 'zhTW', '', '這一刻我等很久了，殘獵者！情勢現在逆轉了！', 25549),
(126774, 'zhTW', '', '你知道嗎，這個鞭子不只是好看而已。只要說出那個關鍵字，打破我的契約，我就會給你驚奇的體驗…', 25549),
(126773, 'zhTW', '', '你應該在我沒有契約束縛的時候再回來找我。喔，我會讓你大開眼界…', 25549),
(126772, 'zhTW', '', '你們這些凡人真以為贏得了燃燒軍團？真是不可思議。你們就像是一群可愛的小老鼠，渾然不知背後有個巨大的掠食者等著要撲殺你們。', 25549),
(126771, 'zhTW', '', '呃，我討厭這些船。鎖鏈太少，好無聊。', 25549),
(126770, 'zhTW', '', '要是你在這邊看見卡薩麗安，跟我說一下。他跟我還有些舊的帳要…算清楚。', 25549),
(126769, 'zhTW', '', '泰德答應過，我們可以把這裡燒成灰燼。', 25549),
(126768, 'zhTW', '', '這雖然是燃燒軍團的船艦，但是一點也不溫暖。', 25549),
(126767, 'zhTW', '', '我好冷。我身上的打扮比較適合充滿烈焰的煉獄。', 25549),
(126766, 'zhTW', '', '如果這傢伙身上有披風，我想要。', 25549),
(126765, 'zhTW', '', '哎呀…你投降啦？', 25549),
(126764, 'zhTW', '', '嗯。早知道應該先說定安全暗號的。', 25549),
(126763, 'zhTW', '', '喔，這個倒挺兇的。', 25549),
(126762, 'zhTW', '', '這些個惡魔連輕輕鞭幾下都挨不了…', 25549),
(126761, 'zhTW', '', '唉，現在的惡魔沒有以前那麼耐打了。', 25549),
(126760, 'zhTW', '', '死了。真可惜。原本還想可以多玩幾下的。', 25549),
(126759, 'zhTW', '', '動起來啊！只有我在忙是怎樣？', 25549),
(126758, 'zhTW', '', '我的「主人」命令我幫你，你可別隨便就死了啊。', 25549),
(126757, 'zhTW', '小心！', '', 25549),
(126756, 'zhTW', '$ct，我們需要你！燃燒軍團快攻破我們的防線了！', '', 25549),
(126755, 'zhTW', '送我去露臺。', '送我去露臺。', 25549),
(126754, 'zhTW', '啊！', '', 25549),
(126753, 'zhTW', '等等…不太對勁！我控制…不了…', '', 25549),
(126752, 'zhTW', '符文啟動了。讓傳送門維持穩定。', '符文啟動了。讓傳送門維持穩定。', 25549),
(126751, 'zhTW', '時間不多了！你弄懂這些符文了嗎？', '', 25549),
(126750, 'zhTW', '完成了。', '', 25549),
(126749, 'zhTW', '符文生效了！惡魔的能量正在消散…', '', 25549),
(126748, 'zhTW', '好吧，我會盡量穩定傳送門。希望你知道自己在做什麼！', '', 25549),
(126747, 'zhTW', '我可以讓它繼續開著，但需要你幫忙維持穩定…', '', 25549),
(126746, 'zhTW', '好了！裂隙正在消失，可是傳送門還不夠穩，不能使用。', '', 25549),
(126745, 'zhTW', '帶我去玄鴉堡頂端。', '帶我去玄鴉堡頂端。', 25549),
(126744, 'zhTW', '必須…逃出來！一定要…警告你…', '必須…逃出來！一定要…警告你…', 25549),
(126743, 'zhTW', '你必須阻止他們…', '你必須阻止他們…', 25549),
(126742, 'zhTW', '你拯救的靈魂正在英靈殿為你高歌。做得太好了！', '', 25549),
(126741, 'zhTW', '這些靈魂在哭泣，燃燒軍團不斷吸取他們的生命精華。釋放它們，讓它們不再受苦，然後殺光燃燒軍團的走狗！', '', 25549),
(126740, 'zhTW', '我準備好要走了。', '我準備好要走了。', 25549),
(126739, 'zhTW', '大領主，你好，格雷森大人正在裡頭等你。$b$b他正在監督坐騎護具的淨化儀式。$b$b等你準備好了，我就帶你進去。', '', 25549),
(126738, 'zhTW', '', '我們需要一名受害者…呃…自願者穿過傳送門，清理另一邊的惡魔。去找泰德談談，他可以借你一隻惡魔，讓你開始進行任務。', 25549),
(126737, 'zhTW', '今天就到此為止了。感謝你們搭乘…下次記得先做好功課！', '', 25549),
(126736, 'zhTW', '你這樣推測還算有道理。但正確答案是「是幻象！你在隱藏什麼？」。', '', 25549),
(126735, 'zhTW', '最後一個問題，考考$n。蘇拉瑪爾城內傳統的打招呼用語是什麼？', '', 25549),
(126734, 'zhTW', '很接近！正確答案是「皮膚」。', '', 25549),
(126733, 'zhTW', '$n。夜裔精靈的哪一個身體特徵因為大量吸食法力而受到最顯著的「強化」？', '', 25549),
(126732, 'zhTW', '大量吸食法力已經對夜裔精靈的身體產生很深的影響。', '', 25549),
(126731, 'zhTW', '他們使用的物質當然就是法力。', '', 25549),
(126730, 'zhTW', '$n，你知道夜裔想要放鬆時，習慣吸取哪一種影響心智的物質嗎？', '', 25549),
(126729, 'zhTW', '夜裔精靈不友善的性格，也是廣為人知。', '', 25549),
(126728, 'zhTW', '我得承認，魔裔的魔法很有…爆發力。只可惜他們濫用這種能力，這下場是他們應得的。', '', 25549),
(126727, 'zhTW', '大家都知道，蘇拉瑪爾是夜裔精靈的故鄉。', '', 25549),
(126726, 'zhTW', '你們還真是健談啊。繼續囉！', '', 25549),
(126725, 'zhTW', '好的。名單上的最後一位是$n。就是你，對吧？', '', 25549),
(126724, 'zhTW', '好。接下來，請問今天有一位$n在場嗎？', '', 25549),
(126723, 'zhTW', '請答「有」就好了。', '', 25549),
(126722, 'zhTW', '$n？$n有出席嗎？', '', 25549),
(126721, 'zhTW', '但首先我要來點名。', '', 25549),
(126720, 'zhTW', '今天我們要搭乘熱氣球參訪古老的蘇拉瑪爾城各處的名勝。', '', 25549),
(126719, 'zhTW', '大家好！請輕輕踏進來…這趟搭乘熱氣球的知識之旅絕對會讓你大開眼界。', '', 25549),
(126718, 'zhTW', '', '好啦，熱氣球旅程結束了！超好玩的！', 25549),
(126717, 'zhTW', '', '好，我的回合結束了。換下一位！', 25549),
(126716, 'zhTW', '', '這樣就只好跟$n結婚了！還不算太差啦。', 25549),
(126715, 'zhTW', '', '嗯…我一定會殺了$n。原因很明顯不用解釋吧？', 25549),
(126714, 'zhTW', '', '$n，你的臉蛋很漂亮，而且看起來這群人中只有你會刷牙。我親你好了。', 25549),
(126713, 'zhTW', '', '我先好了！我看看喔…', 25549),
(126712, 'zhTW', '', '規則很簡單。你只要在其他三個人裡選一個你想親的人、一個想跟他結婚的人，再選一個想把他殺掉的人。', 25549),
(126711, 'zhTW', '', '啊，啊！我想到了！叫做親一個，娶一個，殺一個。', 25549),
(126710, 'zhTW', '', '嗯…你們會玩什麼熱氣球派對遊戲嗎？', 25549),
(126709, 'zhTW', '', '不好意思，我沒什麼當導遊的經驗。', 25549),
(126708, 'zhTW', '', '看到下面那些了嗎？那是…呃…就是斯鐸海姆。', 25549),
(126707, 'zhTW', '', '歡迎光臨！今天我會擔任導遊，帶著各位看看斯鐸海姆。', 25549),
(126706, 'zhTW', '從來沒有一趟熱氣球旅行，讓我產生這種心靈淨化的感覺。而且還蠻有趣的。謝謝你們所有人！', '', 25549),
(126705, 'zhTW', '我可沒忘記你，$n。告訴我們你的秘密吧。我們不會批評你。這裡是安全的熱氣球空間。', '', 25549),
(126704, 'zhTW', '你呢，$n？你有什麼讓自己內心不安的黑暗秘密嗎？', '', 25549),
(126703, 'zhTW', '$n，你先試試看。跟我們說你從來沒跟別人說過的事。來吧。', '', 25549),
(126702, 'zhTW', '現在你們都知道我的秘密了。那你們呢？', '', 25549),
(126701, 'zhTW', '能說出來，真是放下我心頭的大石。我從來沒跟任何人說過。', '', 25549),
(126700, 'zhTW', '哇！', '', 25549),
(126699, 'zhTW', '…呼。', '', 25549),
(126698, 'zhTW', '這樣行了嗎，老爸？嗯？你現在覺得驕傲了嗎？！', '', 25549),
(126697, 'zhTW', '我討厭熱氣球。一輩子都討厭熱氣球。我從小就只想當薩滿，但就是不行！我家人總是說「我們體內流著熱氣球手的血液」。', '', 25549),
(126696, 'zhTW', '有件事我要跟你們三個坦承。', '', 25549),
(126695, 'zhTW', '管他的。知道嗎，我受夠了！', '', 25549),
(126694, 'zhTW', '下方右手邊的是潘家莊。記得要特別小心…', '', 25549),
(126693, 'zhTW', '', '沒錯，沒錯！這就對了！燃燒軍團的雜碎，這樣的下場很不好受吧！', 25549),
(126692, 'zhTW', '<唉…>', '', 25549),
(126691, 'zhTW', '這個氣球將飛往半丘。請勿將頭手伸出氣球外。', '', 25549),
(126690, 'zhTW', '又有熱氣球乘客來了？好吧，進來吧。', '', 25549),
(126689, 'zhTW', '我先讓你們三個自己聊聊。我必須小心別讓熱氣球撞上達拉然。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126688, 'zhTW', '$n，你呢？你最珍惜哪些冒險的回憶？', '', 25549),
(126687, 'zhTW', '$n，那你呢？', '', 25549),
(126686, 'zhTW', '你呢，$n？你去過哪些風景獨特的地方？', '', 25549),
(126685, 'zhTW', '', '虛空領主，我們的術士打開了傳送門，可以通往載滿惡魔的燃燒軍團母艦。希望您讓這群害蟲明白，當個任人擺布的傀儡不會有好下場！', 25549),
(126684, 'zhTW', '提里斯護法的法師需要你幫忙調查佔據悲泣露臺的魔裔。這把魔杖可以解除他們的魔法。', '', 25549),
(126683, 'zhTW', '哎呀，我話多了一點，請你們別介意。你們自己的冒險故事一定更加豐富有趣吧！', '', 25549),
(126682, 'zhTW', '我雖然走遍千山萬水，那一天的事情還是最讓我難忘。', '', 25549),
(126681, 'zhTW', '休拉薩盆地就在那座山脊的另一側。我在那裡遇到了獾狼怪和魚人神諭者部族。真是奇特的生物！', '', 25549),
(126680, 'zhTW', '啊…但我在北裂境的時光還是留下了許多美好的回憶。', '', 25549),
(126679, 'zhTW', '我旅行在外多年，但很可惜沒能多花點時間待在這裡。我也說不上為什麼。', '', 25549),
(126678, 'zhTW', '下方現在是水晶之歌森林。', '', 25549),
(126677, 'zhTW', '歡迎光臨。請務必放輕鬆，盡情享受這趟旅程。', '', 25549),
(126676, 'zhTW', '哎呀…看起來好像差一點點就會撞上去。大家快朝雷霆圖騰部族揮揮手！', '', 25549),
(126675, 'zhTW', '$n，你也行。誰都好，逗我開心啊！', '', 25549),
(126674, 'zhTW', '或是你說也行，$n。', '', 25549),
(126673, 'zhTW', '$n，你會講笑話嗎？', '', 25549),
(126672, 'zhTW', '就算從熱氣球裡開槍射動物，也還是開心不起來。', '', 25549),
(126671, 'zhTW', '但是最近…唉，我也不知道。心情總是不太好。打獵好像沒有像以前一樣那麼讓我開心。', '', 25549),
(126670, 'zhTW', '賣我這個熱氣球的是個小哥布林。他說很適合拿來獵麋鹿！', '', 25549),
(126669, 'zhTW', '朋友們，歡迎來到奈辛瓦里的高嶺熱氣球導覽！', '', 25549),
(126668, 'zhTW', '你說什麼？朗歌，你又搞砸了啦！！！！', '', 25549),
(126667, 'zhTW', '搞定了，老大。我聽你的話，把煙火放到烤肉爐上了。', '', 25549),
(126666, 'zhTW', '現在，每個人請繳28,542枚金幣，不包含小費。不乖乖拿出來的話，朗歌會打斷你們的腿。', '', 25549),
(126665, 'zhTW', '秘訣就是，等客人已經在氣球裡跑不掉，才跟他們講價錢！', '', 25549),
(126664, 'zhTW', '你們或許很疑惑，我砸下重金經營這麼豪華的熱氣球，怎麼還有辦法賺錢呢？我現在就來告訴你們。', '', 25549),
(126663, 'zhTW', '沒問題，老大。', '', 25549),
(126662, 'zhTW', '朗歌，你去把烤肉爐點起來，然後把煙火準備好。', '', 25549),
(126661, 'zhTW', '需要熱毛巾嗎？這是提供給尊榮客戶的特別服務！', '', 25549),
(126660, 'zhTW', '現在在我們下方的是納薩拉斯學院。據說是一座上古時期的法師學校。', '', 25549),
(126659, 'zhTW', '有人想要來點魚子醬嗎？我們這裡只提供最頂級的商品！', '', 25549),
(126658, 'zhTW', '今天我們要飛越艾蘇納上空。那裡可是整個破碎群島最美麗的珍寶。', '', 25549),
(126657, 'zhTW', '想來點免費的飲料嗎？給你！', '', 25549),
(126656, 'zhTW', '我們家可是全艾澤拉斯最豪華的熱氣球！不信你可以到處問問，絕對不會有人否認！', '', 25549),
(126655, 'zhTW', '各位熱氣球新手，歡迎上來！有人想要熱氣球貼紙嗎？這個給你。', '', 25549),
(126654, 'zhTW', '', '家鄉才是最好的時光，家鄉才是最好的時光，家鄉才是最好的時光…', 25549),
(126653, 'zhTW', '', '還是時光旅行到未來呢？我總是搞不太懂。不管怎樣，這真是太恐怖了！我想回去！', 25549),
(126652, 'zhTW', '', '太不可思議了！我們回到過去了！', 25549),
(126651, 'zhTW', '', '我們到納葛蘭了？我們到納葛蘭了！', 25549),
(126650, 'zhTW', '', '這裡好像不是納葛蘭。', 25549),
(126649, 'zhTW', '', '呃…糟糕…', 25549),
(126648, 'zhTW', '', '我用超便宜的價錢買了一台時空加速器裝在熱氣球上。時光真的會呼嘯而過！一定沒問題的！', 25549),
(126647, 'zhTW', '', '你們這些傢伙可真走運。這可不是一般枯燥乏味、慢到不行的熱氣球旅程。', 25549),
(126646, 'zhTW', '', '歡迎歡迎！', 25549),
(126645, 'zhTW', '希望在對抗燃燒軍團的戰爭結束以後，陶土議會能為這片傷痕累累的土地，恢復平衡。', '', 25549),
(126644, 'zhTW', '英雄，陶土議會的薩滿正在努力消除惡魔詛咒對這片土地造成的嚴重傷害。他們需要你去戰鬥，才能完成淨化的儀式。', '', 25549),
(126643, 'zhTW', '做得好，先知。讓你手下的薩滿接手吧。', '', 25549),
(126641, 'zhTW', '先知！魔化火焰組成的元素怪物正以詛咒之火燒灼大地！拜託你，快去淨化這些怪物的魔法，協助與它們對戰的勇士。', '', 25549),
(126640, 'zhTW', '快去堡壘北邊！玄鴉堡上方有某種邪惡的勢力！', '', 25549),
(126639, 'zhTW', '玄鴉堡裡竟然有惡魔要塞？消滅那些惡魔！', '', 25549),
(126638, 'zhTW', '這是我的命運！', '', 25549),
(126637, 'zhTW', '守夜人非常了解如何追蹤獵物。暮色森林中，每個陰暗的角落都有恐怖的野獸。$b$b有時候你可以感覺到牠們在暗中用圓滾滾的小眼睛盯著你。$b$b<達努瑟打了一個冷顫，但仍故作鎮定，顯然不想讓你發現。>$b$b例如前幾天，我穿過森林時就覺得有個奇怪的生物躲在陰影中跟蹤我。', '', 25549),
(126636, 'zhTW', '很好。接下來這一個小時大家都給我安靜坐好。', '', 25549),
(126635, 'zhTW', '這趟熱氣球之旅將會非常順利，所有人都要好好享受。聽到沒？', '', 25549),
(126634, 'zhTW', '以上是這裡的規矩。不遵守的人，皮都給我繃緊一點。', '', 25549),
(126633, 'zhTW', '嚴禁胡鬧嬉戲！', '', 25549),
(126632, 'zhTW', '不准說話、不准跳出熱氣球外、不准故意搖晃熱氣球。', '', 25549),
(126631, 'zhTW', '在熱氣球這裡的規矩非常嚴格。', '', 25549),
(126630, 'zhTW', '請所有人先注意一下我這裡。', '', 25549),
(126629, 'zhTW', '我得去恢復一下力量。勇士，小心點！', '', 25549),
(126628, 'zhTW', '我們不會輸！', '', 25549),
(126627, 'zhTW', '在聖光中，我們合而為一。', '', 25549),
(126626, 'zhTW', '感受聖光的力量！', '', 25549),
(126625, 'zhTW', '織夢者會借角鷹獸給我們，帶我們飛到燃燒軍團的船上。只要殺掉指揮官，那些懦弱的惡魔就會逃走。各位勇士，祝你們好運！', '', 25549),
(126624, 'zhTW', '想攻下這座塔就必須殺死它們的首領。我們一定要拿下這座塔！', '', 25549),
(126623, 'zhTW', '屏障解除了，但空中還有燃燒軍團在盤旋。要是我們攻下塔頂，織夢者應該能想辦法把我們送上惡魔的船艦。', '', 25549),
(126622, 'zhTW', '我想你有來自破碎海岸的壞消息。我們會在紫羅蘭城塞等你。', '', 25549),
(126621, 'zhTW', '', '我找回阿利卡拉了，你找到末日石了嗎？', 25549),
(126620, 'zhTW', '我想辦法穩住傳送門！在我完成前擋住這些惡魔！', '', 25549),
(126619, 'zhTW', '那個笨蛋！她的傳送門超載了，還撕開了扭曲虛空的裂隙！', '', 25549),
(126618, 'zhTW', '有一道魔化能量屏障擋住了看守者之塔的入口。你帶人去摧毀屏障的能量來源。我們會在這裡留守。', '', 25549),
(126617, 'zhTW', '去死吧，惡魔！', '', 25549),
(126616, 'zhTW', '趕走燃燒軍團！', '', 25549),
(126615, 'zhTW', '防衛者，進攻！換我們主動攻擊燃燒軍團！', '', 25549),
(126614, 'zhTW', '不能讓燃燒軍團褻瀆這片古老的森林。下達命令吧，英雄！我們隨時會為維爾薩拉而戰！', '', 25549),
(126613, 'zhTW', '歐丁祝福你，陌生人！', '', 25549),
(126612, 'zhTW', '我不要再被獵犬啃了！', '', 25549),
(126611, 'zhTW', '謝謝你，陌生人！希望我們會在英靈殿見面！', '', 25549),
(126610, 'zhTW', '我終於自由了！', '', 25549),
(126609, 'zhTW', '死亡…是大家最終的結局。', '', 25549),
(126608, 'zhTW', '釋放我，陌生人。我寧願永遠待在黑爾海姆，也不要在這裡受這種苦！', '', 25549),
(126607, 'zhTW', '這些獵犬會把我們都吃掉！', '', 25549),
(126606, 'zhTW', '救我脫離苦難！', '', 25549),
(126602, 'zhTW', '呃…我不覺得他會這麼小。', '', 25549),
(126601, 'zhTW', '你好啊。我們帶了一些玩具讓你借用。祝你好運。', '', 25549),
(126600, 'zhTW', '格雷森，這是聖水。', '格雷森，這是聖水。', 25549),
(126599, 'zhTW', '%s對你使用恐龍魔精，使你獲得一種隨機的適者生存效果。', '%s對你使用恐龍魔精，使你獲得一種隨機的適者生存效果。', 25549),
(126598, 'zhTW', '嗯…勞倫斯…我看看…\n\n有，她前陣子來過。她在找一把非常特殊的法杖。有趣的是，通常只有術士才會想買這種法杖。\n\n我花了好幾天才找到，法杖已經照她說的，先送去戲法旅舍了。', '', 25549),
(126597, 'zhTW', '我能幫你嗎？', '', 25549),
(126596, 'zhTW', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_03.BLP:32|t梅菲斯托施展|cFFFF0000|Hspell:233206|h[黑暗漸隱]|h|r藏匿自己的蹤跡！', '', 25549),
(126595, 'zhTW', '梅菲斯托，你躲不了的！', '', 25549),
(126594, 'zhTW', '燃燒軍團只是白費力氣。', '', 25549),
(126593, 'zhTW', '準備發動攻擊。', '準備發動攻擊。', 25549),
(126592, 'zhTW', '不惜一切代價阻止敵人！', '', 25549),
(126591, 'zhTW', '', '孩子啊，你們都聽到$ct的命令了。去聯絡其他職業，請他們幫忙！願元素指引你們。', 25549),
(126590, 'zhTW', '%s開始引導|cFFFF0404|Hspell:234728|h[秘法滅殺]|h|r！', '', 25549),
(126589, 'zhTW', '聯絡其他職業吧，我們要去破碎海岸了。', '聯絡其他職業吧，我們要去破碎海岸了。', 25549),
(126588, 'zhTW', '我會開個傳送門，直接通往秘法師萊恩娜的所在地。', '', 25549),
(126587, 'zhTW', '', '$ct，願眾靈指引你。', 25549),
(126586, 'zhTW', '高階巫士，我需要你幫忙說服其他職業組織一起來對抗燃燒軍團。', '高階巫士，我需要你幫忙集結其他職業組織一起來對抗燃燒軍團。', 25549),
(126585, 'zhTW', '你好！你不覺得這個地方很適合進行秘法冥想嗎？', '', 25549),
(126584, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t墮落化身開始施放|cFFFF0404|Hspell:234724|h[殲滅]|h|r！', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t墮落化身開始施放|cFFFF0404|Hspell:234724|h[殲滅]|h|r！', 25549),
(126583, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_FEL_ELEMENTALDEVASTATION:20|t腐化的守護者開始施放|cFFFF0404|Hspell:233856|h[淨化程序]|h|r！', '|TINTERFACE\\ICONS\\SPELL_FEL_ELEMENTALDEVASTATION:20|t腐化的守護者開始施放|cFFFF0404|Hspell:233856|h[淨化程序]|h|r！', 25549),
(126582, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t化身開始施放|cFFFF0404|Hspell:239132|h[崩解現實]|h|r！', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t化身開始施放|cFFFF0404|Hspell:239132|h[崩解現實]|h|r！', 25549),
(126581, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELFIRENOVA:20|t墮落化身對你施放|cFFFF0404|Hspell:234059|h[無縛混沌]|h|r！', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELFIRENOVA:20|t墮落化身對你施放|cFFFF0404|Hspell:234059|h[無縛混沌]|h|r！', 25549),
(126580, 'zhTW', '葛朗苟打扁你！', '', 25549),
(126579, 'zhTW', '', '想來點爆爆？那就來吧，笨蛋！', 25549),
(126578, 'zhTW', '滾下我的船，聯盟廢物！', '', 25549),
(126577, 'zhTW', '滾下我的船，部落廢物！', '', 25549),
(126576, 'zhTW', '', '呃！', 25549),
(126575, 'zhTW', '不想被煙火炸臉，就給我閃遠一點！', '', 25549),
(126574, 'zhTW', '做得好，勇士。但在獲勝之前還有很多事要做。', '', 25549),
(126573, 'zhTW', '你收到一艘免費的小船，讓你今天可以在水面上暢遊。行船小心！', '你收到一艘免費的小船，讓你今天可以在水面上暢遊。行船小心！', 25549),
(126572, 'zhTW', '唉…我還希望能打打排球說…', '', 25549),
(126571, 'zhTW', '他們亂丟的垃圾全都聚集在湖的這個角落。我們絕對不能容許這種藐視大自然的行為。', '', 25549),
(126570, 'zhTW', '其他種族肆無忌憚地享樂，對這片土地的環境造成了非常嚴重的後果。', '', 25549),
(126569, 'zhTW', '嗯…我敢打賭那邊那些海盜身上一定有酒可以喝…', '', 25549),
(126568, 'zhTW', '對不起。', '', 25549),
(126567, 'zhTW', '我們大老遠跑來慶祝鬥船節，你居然忘記帶最重要的酒！', '', 25549),
(126566, 'zhTW', '呃！我簡直不敢相信！', '', 25549),
(126565, 'zhTW', '', '喂！你們好啊！你們這些水手想來點樂子嗎？', 25549),
(126564, 'zhTW', '<驚呼！>真不敢相信你居然這樣血口噴人。今天可是鬥船節啊！', '', 25549),
(126563, 'zhTW', '慢著點，老兄。我會偷你們的炸彈是因為你和你的肉腳團隊先偷了我們的！', '', 25549),
(126562, 'zhTW', '每次都這樣！我才一分鐘沒注意，你的手下就來把我們的炸藥偷走了！', '', 25549),
(126561, 'zhTW', '效率真高。小鬼下次要再囂張想必會更小心。', '', 25549),
(126560, 'zhTW', '燃燒軍團開啟了傳送門，湧出一大群小鬼。勇士，你必須消滅這群小惡魔！', '', 25549),
(126559, 'zhTW', '這些邪惡生物的死亡，會引發燃燒軍團的怒火。快，去玄鴉堡，我們必須趕快攻擊！', '', 25549),
(126558, 'zhTW', '壞消息是，海巨人要搶這些補給品。殺死那些巨人，拿回我們在殘骸中遺失的補給品。', '', 25549),
(126557, 'zhTW', '許多補給品在第一次突襲行動中遺落在海底。這些東西對我們打這場仗會很有用處。', '', 25549),
(126556, 'zhTW', '燃燒軍團就像瘟疫，不斷傷害這片大地。把惡魔殺光，別讓它們繼續蔓延！', '', 25549),
(126555, 'zhTW', '惡魔先是侵略我們的領土，現在連天空都淪陷了。', '', 25549),
(126554, 'zhTW', '戰鬥領主，很榮幸跟你並肩作戰。我會到審判角回報。到時候見！', '', 25549),
(126553, 'zhTW', '戰鬥領主，你身懷榮耀作戰。我會到審判角回報。到時候見。', '', 25549),
(126552, 'zhTW', '各位騎士！$ct需要我們！起飛！', '', 25549),
(126551, 'zhTW', '遵命，$ct。我們立刻出發。', '', 25549),
(126550, 'zhTW', '把其他職業都找來吧，我們要去破碎海岸了。', '把其他職業都找來吧，我們要去破碎海岸了。', 25549),
(126549, 'zhTW', '$ct，我能幫什麼忙？', '', 25549),
(126548, 'zhTW', '這個有羽毛的傢伙毫無忠誠可言。雖然啄啄鳥讓我失望，但是沒有合適的夥伴，我也就當不了稱職的船長！南納斯是我的新夥伴，他幫了我許多忙！$b$b反正誰需要鳥呢？南納斯是個更有用的船員。', '', 25549),
(126547, 'zhTW', '猴人是怎麼一回事？', '猴人是怎麼一回事？', 25549),
(126546, 'zhTW', '唷喝，$n。我可是很期待壯觀的爆炸！', '', 25549),
(126545, 'zhTW', '黑爾雅…我讓你失望了…', '', 25549),
(126544, 'zhTW', '我要為主人報仇！只要我還活著，就不會讓可惡的外來者控制科瓦迪爾！', '', 25549),
(126543, 'zhTW', '快，送我上前線！[加入事件佇列]', '快，送我上前線！[加入事件佇列]', 25549),
(126542, 'zhTW', '這些惡魔會為它們的惡行付出代價。我發誓！', '', 25549),
(126541, 'zhTW', '啄啄鳥！我以為你是我的好夥伴！太讓我心碎了！', '', 25549),
(126540, 'zhTW', '', '謝謝你幫我們爭取寶貴的時間來面對這個威脅。', 25549),
(126539, 'zhTW', '', '卡魯歐回來了？我們得準備好攻擊惡魔巢穴。卡連恩，把我們能分的補給品都分給伊利達瑞。', 25549),
(126537, 'zhTW', '呸！這些維酷人以為偷了我們的火藥還能全身而退嗎？那就大錯特錯了！', '', 25549),
(126536, 'zhTW', '什麼？！火藥被鷹身人搶走了？我必須立即召集手下前往高嶺！', '', 25549),
(126535, 'zhTW', '在擂臺的另一個角落，這位英勇的矮人帶著他完全忠實的夥伴。這隻猛獸絕對不可能做任何傷害牠主人的事情。絕對不會。', '', 25549),
(126534, 'zhTW', '謝謝你解決那些巨人！你收集的這些補給對我們的作戰大有幫助。', '', 25549),
(126533, 'zhTW', '冷卻時間跟減益效果已經重置了。', '', 25549),
(126532, 'zhTW', '', '在擂臺的另一個角落，這位英勇的矮人帶著他完全忠實的夥伴。這隻猛獸絕對不可能做任何傷害牠主人的事情。絕對不會。', 25549),
(126531, 'zhTW', '她不見了。她一定又被抓走了！', '', 25549),
(126530, 'zhTW', '', '克麗莎，別吵！', 25549),
(126529, 'zhTW', '', '喂，朵莉亞，這傢伙在找你。', 25549),
(126528, 'zhTW', '', '呃，那個戴著面具的不就是她嗎？喔，等等，當我沒說，沒事，我沒見到她。', 25549),
(126527, 'zhTW', '你比戴著兩塊眼罩的海賊還瞎。', '', 25549),
(126526, 'zhTW', '', '太好了！這件事只有你能辦到。我們會告訴你有哪些已知的敵人。', 25549),
(126525, 'zhTW', '我通常不會干預大自然，但…要是能避免同時面對海怪和燃燒軍團的話，那就再好不過了！', '', 25549),
(126524, 'zhTW', '因為嫉妒，她和那些科瓦迪爾劫走我不少驍勇善戰的靈魂。釋放它們，至少讓它們能重回英靈殿。', '', 25549),
(126523, 'zhTW', '體積太大的蛋會有問題…呃，問題不在於蛋本身，而是蛋會孵化出海怪。', '', 25549),
(126522, 'zhTW', '聯盟的勇士！我們有任務了！', '', 25549),
(126521, 'zhTW', '你好，戰鬥領主。你是我們在急難當頭時可以倚靠的強者。', '', 25549),
(126520, 'zhTW', '達瑞亞斯領主，我需要你集合其他職業的勇士，組成對抗燃燒軍團的聯軍。', '達瑞亞斯領主，我需要你集合其他職業的勇士，組成對抗燃燒軍團的聯軍。', 25549),
(126519, 'zhTW', '你好，戰鬥領主。你是我們在急難當頭時可以倚靠的強者。', '', 25549),
(126514, 'zhTW', '你看！有線索！噢…只是灰塵。', '', 25549),
(126513, 'zhTW', '嗯，也許她就在這後面…', '', 25549),
(126512, 'zhTW', '先生，不好意思，請問你有看到我家朵莉亞嗎？', '', 25549),
(126511, 'zhTW', '部落的勇士，出發！', '', 25549),
(126510, 'zhTW', '親愛的，我救到你了！等等…事情不太對勁。', '', 25549),
(126509, 'zhTW', '伊崔格，我需要你集合其他職業的勇士，組成對抗燃燒軍團的聯軍。', '伊崔格，我需要你集合其他職業的勇士，組成對抗燃燒軍團的聯軍。', 25549),
(126507, 'zhTW', '', '祈倫托抓到卡魯歐以後，把心臟鎖在達拉然重重防護，以免落入燃燒軍團手裡。', 25549),
(126506, 'zhTW', '侍從，來吧！我們去爬那座很高很高的山。', '', 25549),
(126505, 'zhTW', '親愛的，別害怕，我們會找到這些壞蛋，把你救出來！', '', 25549),
(126504, 'zhTW', '', '瑪克西米利安？你怎麼找到我的？', 25549),
(126503, 'zhTW', '朵莉亞，親愛的！我終於找到你了！你沒事吧？', '', 25549),
(126502, 'zhTW', '保險庫被打開了！', '保險庫被打開了！', 25549),
(126501, 'zhTW', '勇士們，靠過來！用盾保護我，我要把這個驚懼領主撕成碎片！', '', 25549),
(126499, 'zhTW', '下蛋的怪獸在洞窟裡！去上層看看！', '', 25549),
(126498, 'zhTW', '你殺夠多怪獸了，現在專心處理蛋就好。', '', 25549),
(126497, 'zhTW', '牠注意到你了！要過來了！', '', 25549),
(126496, 'zhTW', '', '我來告訴你燃燒軍團在找什麼 - 我的底線！親愛的，軍團級保護結界很貴的好嗎！', 25549),
(126495, 'zhTW', '', '噢，真是一場災難！這是什麼世道！人心不古呀！$B$B<貪婪妮亞偷瞄你一眼，確認你有在看。>$B$B也許聞到十枚金幣和藹可親的味道，我的記憶就會恢復了！$B$B不要有刮痕記號的，謝謝。', 25549),
(126494, 'zhTW', '那個惡魔好像趁亂通過傳送門了。塊頭很大，有兩個牛頭人那麼大…大概三個吧！', '', 25549),
(126493, 'zhTW', '我…絕不…屈服…', '我…絕不…屈服…', 25549),
(126492, 'zhTW', '拜託…讓我走。家人在等我。', '拜託…讓我走。家人在等我。', 25549),
(126491, 'zhTW', '為什麼？你為什麼要這麼做？', '為什麼？你為什麼要這麼做？', 25549),
(126490, 'zhTW', '我什麼都不知道…', '我什麼都不知道…', 25549),
(126489, 'zhTW', '滾…出…我…的…腦袋！', '滾…出…我…的…腦袋！', 25549),
(126488, 'zhTW', '我的腦袋…快滾出我的…腦袋。', '我的腦袋…快滾出我的…腦袋。', 25549),
(126487, 'zhTW', '住手！拜託，快住手！', '住手！拜託，快住手！', 25549),
(126486, 'zhTW', '歐索，快張開嘴巴，我才能開火！', '', 25549),
(126485, 'zhTW', '每從魔化熔爐奪回一個靈魂，就能減少敵人獲得的能源。做得好。', '', 25549),
(126484, 'zhTW', '惡魔從蘇拉瑪爾運來了更多無助的難民。幫助潛影議會的盜賊拯救難民，別讓他們成為魔能的犧牲品。', '', 25549),
(126483, 'zhTW', '從魔化熔爐奪回的每個靈魂都能削弱敵人。做得很好。', '', 25549),
(126482, 'zhTW', '影尊，惡魔從蘇拉瑪爾運來了更多無助的難民。你必須率領同伴一起救出難民，別讓他們成為魔能的祭品。', '', 25549),
(126481, 'zhTW', '泰茵‧鋼革', '泰茵‧鋼革', 25549),
(126480, 'zhTW', '梅爾亨‧光怒', '梅爾亨‧光怒', 25549),
(126479, 'zhTW', '娜倫‧奪心', '娜倫‧奪心', 25549),
(126478, 'zhTW', '古爾達克‧石盾', '古爾達克‧石盾', 25549),
(126477, 'zhTW', '艾拉娃‧智擁', '艾拉娃‧智擁', 25549),
(126476, 'zhTW', '拉項‧光落', '拉項‧光落', 25549),
(126475, 'zhTW', '如果你砸爛的蛋夠多，下蛋的怪獸就會出來找你算帳！', '', 25549),
(126474, 'zhTW', '就是這個地方。殺掉這些怪獸，順便砸爛所有你看到的蛋！', '', 25549),
(126473, 'zhTW', '白銀之手的聖騎士要在魔火隘口進行神聖儀式，但是燃燒軍團步步進逼。殺死惡魔領袖，讓我們來淨化這裡。', '', 25549),
(126472, 'zhTW', '做得好，你替大家爭取到時間，讓我們能完成任務。', '', 25549),
(126471, 'zhTW', '謝謝你的協助。我們總算能完成工作，紀念提里奧所做出的犧牲。', '', 25549),
(126470, 'zhTW', '我們想要淨化提里奧不幸陣亡之處，但燃燒軍團逼退了我們。我們需要你幫忙，大領主。', '', 25549),
(126469, 'zhTW', '對力量的渴望確實很可怕，很多人都因此屈服。那些術士讓我們除了消滅這威脅以外，別無選擇。', '', 25549),
(126468, 'zhTW', '效忠燃燒軍團的強大術士在魔火隘口集結。我們要阻止術士，還有它們瘋狂的主人，別讓它們變得更強。', '', 25549),
(126467, 'zhTW', '至少這次沒有超大的雷射光束，對吧？', '', 25549),
(126466, 'zhTW', '英雄，做得好！善後工作就交給德魯伊吧。', '', 25549),
(126465, 'zhTW', '看到這片古老的大地被如此邪惡的生物侵犯，讓我痛心不已。別讓它們繼續擴散！', '', 25549),
(126464, 'zhTW', '這次會有很多敵人。小心機器的光束。', '', 25549),
(126463, 'zhTW', '', '我發誓，再也不要跟姓銅鬚的一起冒險了！', 25549),
(126462, 'zhTW', '還沒結束呢！', '', 25549),
(126461, 'zhTW', '大祭司，想回去的時候就告訴我一聲。', '', 25549),
(126460, 'zhTW', '我做好回達拉然的準備了。', '我做好回達拉然的準備了。', 25549),
(126459, 'zhTW', '大祭司，你準備好要離開了嗎？跟我說一聲，我就讓潛水艇航向達拉然。', '', 25549),
(126454, 'zhTW', '', '你想移除哪一個聖騎士？', 25549),
(126453, 'zhTW', '', '這座城市的不死族也只有現在能躲在暗處了。$b$b我等你發號施令。', 25549),
(126452, 'zhTW', '', '在這種邪惡的地方，我們就是光。$b$b有什麼我可以幫忙嗎？', 25549),
(126451, 'zhTW', '', '大領主，你好，我隨時為你效勞。', 25549),
(126450, 'zhTW', '我…輸了？這…不可能…', '', 25549),
(126449, 'zhTW', '弟弟…為什麼？', '', 25549),
(126448, 'zhTW', '', '加利斯小親親，你應該用我教你的那個法術！你可不准失敗！', 25549),
(126447, 'zhTW', '', '要幫你的刀刃淬毒嗎？', 25549),
(126446, 'zhTW', '', '我對蠢蛋沒什麼耐心。', 25549),
(126445, 'zhTW', '', '你以為光靠自己就辦得到嗎？', 25549),
(126444, 'zhTW', '', '我需要治療之水。', 25549),
(126443, 'zhTW', '', '我需要…喘口氣。', 25549),
(126442, 'zhTW', '', '我這把老骨頭需要休息。', 25549),
(126441, 'zhTW', '', '感受恐怖圖騰的怒火！', 25549),
(126440, 'zhTW', '', '我只要動動指頭就能殺了你！', 25549),
(126439, 'zhTW', '', '你竟然笨到來惹我！', 25549),
(126438, 'zhTW', '', '根本不是元素的對手！', 25549),
(126437, 'zhTW', '', '我連一滴汗都沒流。', 25549),
(126436, 'zhTW', '', '我最受不了蠢蛋。', 25549),
(126435, 'zhTW', '賽希雅‧橡棘', '賽希雅‧橡棘', 25549),
(126434, 'zhTW', '菲利普‧斯鐸威爾', '菲利普‧斯鐸威爾', 25549),
(126433, 'zhTW', '克洛岡‧光鬍', '克洛岡‧光鬍', 25549),
(126432, 'zhTW', '復仇者愛德莉', '復仇者愛德莉', 25549),
(126431, 'zhTW', '復仇者卓納恩', '復仇者卓納恩', 25549),
(126430, 'zhTW', '菲優娜‧斯鐸威爾', '菲優娜‧斯鐸威爾', 25549),
(126429, 'zhTW', '', '照我說的話做，孩子。', 25549),
(126428, 'zhTW', '你想移除哪一個聖騎士？', '', 25549),
(126427, 'zhTW', '', '想要我去殺誰啊？', 25549),
(126426, 'zhTW', '這座城市的不死族也只有現在能躲在暗處了。$b$b我等你發號施令。', '', 25549),
(126425, 'zhTW', '在這種邪惡的地方，我們就是光。$b$b有什麼我可以幫忙嗎？', '', 25549),
(126424, 'zhTW', '', '你先走吧…我會趕上。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126423, 'zhTW', '', '能幫我處理一下嗎？', 25549),
(126422, 'zhTW', '', '墓地在呼喚我回去…', 25549),
(126421, 'zhTW', '大領主，你好，我隨時為你效勞。', '', 25549),
(126420, 'zhTW', '', '我的斧頭餓壞了！', 25549),
(126419, 'zhTW', '', '來大鬧一場！', 25549),
(126418, 'zhTW', '', '你以為好玩的都給你嗎？', 25549),
(126417, 'zhTW', '', '殺死這些敵人！', 25549),
(126416, 'zhTW', '', '死亡在等著你！', 25549),
(126415, 'zhTW', '', '受死吧！', 25549),
(126414, 'zhTW', '', '啊，死亡的甜美氣息。', 25549),
(126413, 'zhTW', '', '墓地歡迎你！', 25549),
(126412, 'zhTW', '', '儘管流血吧！', 25549),
(126411, 'zhTW', '你擋不住這股力量的！', '你擋不住這股力量的！', 25549),
(126410, 'zhTW', '主人，給我你的力量吧！', '主人，給我你的力量吧！', 25549),
(126409, 'zhTW', '沒有人可以阻止我！', '沒有人可以阻止我！', 25549),
(126408, 'zhTW', '不！說好的！', '不！說好的！', 25549),
(126407, 'zhTW', '', '別擔心…我會復原的。', 25549),
(126406, 'zhTW', '', '繼續，別管我！', 25549),
(126405, 'zhTW', '', '別管我…', 25549),
(126404, 'zhTW', '', '受死吧！', 25549),
(126403, 'zhTW', '', '你不是我的對手！', 25549),
(126402, 'zhTW', '', '我來替你送終吧。', 25549),
(126401, 'zhTW', '', '死了以後每個人都是孤獨的！', 25549),
(126400, 'zhTW', '', '化為骸骨和灰燼吧！', 25549),
(126399, 'zhTW', '', '背上插一把刀的感覺如何啊！？', 25549),
(126398, 'zhTW', '', '我訓練有素！', 25549),
(126397, 'zhTW', '', '換我來救你了！', 25549),
(126396, 'zhTW', '', '我從陰影中現身。', 25549),
(126395, 'zhTW', '', '該結束了！', 25549),
(126394, 'zhTW', '我…呃…真的得走了！再見！', '', 25549),
(126393, 'zhTW', '', '別拖拖拉拉的，該動手了！', 25549),
(126392, 'zhTW', '', '需要我的…技術嗎？', 25549),
(126391, 'zhTW', '', '看來你需要我幫忙。', 25549),
(126390, 'zhTW', '', '一點挑戰都沒有。', 25549),
(126389, 'zhTW', '', '喔，你已經死了。', 25549),
(126388, 'zhTW', '', '千萬別惹帶著匕首的公主。', 25549),
(126387, 'zhTW', '', '我要撤退了！', 25549),
(126386, 'zhTW', '', '你繼續前進！', 25549),
(126385, 'zhTW', '', '去完成任務！', 25549),
(126384, 'zhTW', '', '別擔心，你馬上就會死了。', 25549),
(126383, 'zhTW', '', '和我的匕首打聲招呼！', 25549),
(126382, 'zhTW', '', '該來解決你了！', 25549),
(126381, 'zhTW', '', '交給我！', 25549),
(126380, 'zhTW', '這…這跟我沒有關係！加利斯‧米爾莫爾才不會被區區一個魅魔給迷惑！', '', 25549),
(126379, 'zhTW', '我的頭…啊…發生什麼事？', '', 25549),
(126378, 'zhTW', '非常樂意，大人。', '', 25549),
(126377, 'zhTW', '瓦里茲，殺掉這個傢伙。', '', 25549),
(126376, 'zhTW', '別這麼急…', '', 25549),
(126375, 'zhTW', '', '嘗嘗我的爪子！', 25549),
(126374, 'zhTW', '', '我會保護你，大德魯伊！', 25549),
(126373, 'zhTW', '', '快離開這裡！', 25549),
(126372, 'zhTW', '', '哈！你對付不了我們！', 25549),
(126371, 'zhTW', '', '利爪染血的感覺真好！', 25549),
(126370, 'zhTW', '', '讓你吃不完兜著走！', 25549),
(126369, 'zhTW', '', '啊！好痛啊！', 25549),
(126368, 'zhTW', '加利斯昏倒了。', '', 25549),
(126367, 'zhTW', '', '我…需要喘口氣。', 25549),
(126366, 'zhTW', '', '我要先撤退。你繼續！', 25549),
(126365, 'zhTW', '', '見識我的利爪吧！', 25549),
(126364, 'zhTW', '', '爪子有點癢癢的！', 25549),
(126363, 'zhTW', '', '來搞點破壞吧！', 25549),
(126362, 'zhTW', '', '我來對付他們！', 25549),
(126361, 'zhTW', '末日石太不穩定了。我們得捨棄它，用大漩渦隔離它，讓它遠離其他東西。把它帶去給諾柏多，他會處理。', '', 25549),
(126360, 'zhTW', '進去神廟裡面！快！把帶頭攻擊的惡魔找出來，殺了它。', '', 25549),
(126359, 'zhTW', '我需要你的輔助！', '我需要你的輔助！', 25549),
(126358, 'zhTW', '我需要你幫忙攻擊！', '我需要你幫忙攻擊！', 25549),
(126357, 'zhTW', '我需要你的護盾！', '我需要你的護盾！', 25549),
(126356, 'zhTW', '我準備好接受召喚了。', '我準備好接受召喚了。', 25549),
(126355, 'zhTW', '', '如果你願意帶領大家，黑穫議會就能得到前所未有的力量。', 25549),
(126354, 'zhTW', '我想挑戰圖加‧血圖騰。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', '我想挑戰圖加‧血圖騰。(100個虛空裂片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(126352, 'zhTW', '', '燃燒軍團的威脅無孔不入，我的經驗或許對你有幫助。這些任務很艱難，希望你準備好了。$b$b我們需要虛空裂片才能穿透燃燒軍團的防禦措施，虛空裂片同時能用來加強你的防禦，幫你抵擋可怕的攻擊。我可以幫你準備虛空裂片，但不會一直都有，有時候你得看情況自己準備。', 25549),
(126348, 'zhTW', '你打斷了燃燒軍團的生產線。或許只能拖延一下，但在這片黑暗中，每場勝利都有價值。', '', 25549),
(126347, 'zhTW', '這些傢伙需要礦石來打造武器。我們每從它們手中奪走一個碎塊，就能減少它們一分力量。', '', 25549),
(126337, 'zhTW', '我…服從。', '', 25549),
(126336, 'zhTW', '殺死這個入侵者，哥哥！', '', 25549),
(126335, 'zhTW', '什麼？你在做什麼？不！', '', 25549),
(126334, 'zhTW', '殺了我？不，哥哥。我會好好利用你的劍術！', '', 25549),
(126333, 'zhTW', '雷斯特，我不能讓你對艾澤拉斯釋放力量。要是你不住手，就是在逼我殺了你！', '', 25549),
(126332, 'zhTW', '你不該追來的，哥哥。我能從扭曲虛空吸收能量。我已經變得比你所想像的還要更強大！', '', 25549),
(126331, 'zhTW', '祈倫托之前交給我一枚傳送門水晶。我想他們一定迫不及待想聽到你任務成功的消息。英雄，謝謝你。我們後會有期。', '', 25549),
(126330, 'zhTW', '儘管如此，我還是會繼續監視這些惡魔，直到它們的燃燒軍團主人倒下為止。', '', 25549),
(126329, 'zhTW', '要是沒有圖加，魔化圖騰就再也不是威脅了。', '', 25549),
(126328, 'zhTW', '我來啦！我要把…怎麼回事？圖加被打倒了！你怎麼沒等我一起玩！', '', 25549),
(126327, 'zhTW', '這不會改變…任何事。燃燒軍團…會獲勝…', '', 25549),
(126326, 'zhTW', '這是我最偉大的作品！有了燃燒軍團的力量，我一定能消滅雷霆圖騰！', '', 25549),
(126325, 'zhTW', '你準備好受死了嗎，$rt。我已經一週沒讓這頭熊吃東西了，他會把你生吞活剝！', '', 25549),
(126324, 'zhTW', '掙扎是沒有用的。跟我來你就知道了…', '', 25549),
(126321, 'zhTW', '你要怎麼取得淨化儀式要用的東西，就全都看你的了。$b$b或許你可以順便看看，是什麼把這裡的不死族喚醒的。', '', 25549),
(126320, 'zhTW', '你只是在做無謂的掙扎！我的惡魔野獸又變得更強了！', '', 25549),
(126319, 'zhTW', '蠢蛋！你能找到我，是因為我想被找到！我現在要報復雷霆圖騰…還有你！', '', 25549),
(126317, 'zhTW', '', '集合部隊！為雷霆圖騰而戰！我們會獲得勝利！', 25549),
(126316, 'zhTW', '', '你們的部族那麼弱小，根本比不上燃燒軍團！', 25549),
(126315, 'zhTW', '控制自己，不要造成毀滅！', '', 25549),
(126314, 'zhTW', '先知！快住手！元素界域要被你撕裂了！', '', 25549),
(126313, 'zhTW', '怎麼回事？！你…無法…打倒我！', '', 25549),
(126312, 'zhTW', '是火牆！啊啊啊！你先去阻止圖加，我會盡快跟你會合！', '', 25549),
(126311, 'zhTW', '', '好幫手非常難找。我只好…親自下海。', 25549),
(126310, 'zhTW', '小薩滿，你手上拿了什麼？你拿著一顆小石頭就想對付我？', '', 25549),
(126309, 'zhTW', '呃啊！', '', 25549),
(126308, 'zhTW', '親愛的沒錯，不能讓他們毀了我們今晚的約會！', '', 25549),
(126307, 'zhTW', '', '加利斯小親親，這些入侵者打擾了我們獨處的時間！解決他們！', 25549),
(126306, 'zhTW', '任你差遣，寶貝！', '', 25549),
(126305, 'zhTW', '帶我到破碎海岸。', '帶我到破碎海岸。', 25549),
(126304, 'zhTW', '我準備好去大漩渦了。', '我準備好去大漩渦了。', 25549),
(126303, 'zhTW', '我們認為失落的泰坦遺址位在大漩渦的東北方。這一點很快就能確認。\n\n大祭司，你準備好了嗎？', '', 25549),
(126302, 'zhTW', '', '或許我們可以這麼做。$n宗師，你的臉色好差，你應該回寂靜峰！', 25549),
(126301, 'zhTW', '等你要面對末日守衛時讓我知道。我會透過末日石，把我的力量傳遞給你。', '', 25549),
(126300, 'zhTW', '', '我有最後一個請求，凡人。桑德蘭需要你的協助。', 25549),
(126299, 'zhTW', '', '我想跟你一起作戰，可是這座洞穴的大小只容得下凡人。用你的末日石來引導我的力量，粉碎我們的敵人！', 25549),
(126298, 'zhTW', '瑟拉贊恩在附近的洞穴裡需要你的幫助。快過去！', '', 25549),
(126297, 'zhTW', '掌控我的怒氣，先知！用火焰之王的力量燒盡燃燒軍團！', '', 25549),
(126296, 'zhTW', '斯莫德隆請你去山脊上協助他，先知。', '', 25549),
(126295, 'zhTW', '用末日石引導我的力量，摧毀那些魔能擴散水晶！', '', 25549),
(126294, 'zhTW', '真美味的靈魂啊！我還要！', '', 25549),
(126293, 'zhTW', '', '被遺忘的泰坦遺址…而且保存良好？這可是重大的發現！喂，你覺得這些泡泡裡面有什麼？', 25549),
(126292, 'zhTW', '|TInterface\\Icons\\SPELL_FIRE_FELIMMOLATION:20|t%s開始施放|cFFFF0000|Hspell:233062|h[煉獄燃燒]|h|r。快躲！', '', 25549),
(126291, 'zhTW', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONINFERNAL:20|t%s將|cFFFF0000|Hspell:233272|h[崩碎之星]|h|r對準你了！快躲起來！', '', 25549),
(126290, 'zhTW', '|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERSGREEN:20|t%s將|cFFFF0000|Hspell:232249|h[魔化彗星]|h|r對準你了！', '', 25549),
(126289, 'zhTW', '是誰打擾我的饗宴？', '', 25549),
(126288, 'zhTW', '我會好好看著你們燃燒的。再見了，凡人！', '', 25549),
(126287, 'zhTW', '你摧毀了我的船艦，但不會再讓你得逞了！', '', 25549),
(126286, 'zhTW', '夠了！我沒時間玩這種把戲！', '', 25549),
(126285, 'zhTW', '這棵樹看起來很糟，但樹裡的魔法對我們有用！', '這棵樹看起來很糟，但樹裡的魔法對我們有用！', 25549),
(126284, 'zhTW', '這棵樹的心材還可以用！', '這棵樹的心材還可以用！', 25549),
(126283, 'zhTW', '燃燒軍團的力量變弱了，我們得乘勝追擊！', '', 25549),
(126282, 'zhTW', '我準備好切斷能量來源了。', '我準備好切斷能量來源了。', 25549),
(126281, 'zhTW', '算我活該。', '', 25549),
(126280, 'zhTW', '英雄不死，他們會復活！', '', 25549),
(126279, 'zhTW', '馬上到外面找我！該是斬斷燃燒軍團的魔爪，解救艾蘇納的時候了！', '', 25549),
(126278, 'zhTW', '這…只是個開始…', '', 25549),
(126277, 'zhTW', '我們無窮無盡！這個破爛的世界我們才不放在眼裡。', '', 25549),
(126276, 'zhTW', '', '魔化圖騰抓走了我的族人，想同化他們。絕對不能讓這種可怕的事情發生！', 25549),
(126275, 'zhTW', '為什麼你賣的物品這麼昂貴？', '為什麼你賣的物品這麼昂貴？', 25549),
(126274, 'zhTW', '我要怎麼協助進行戰備？', '我要怎麼協助進行戰備？', 25549),
(126273, 'zhTW', '身分勳章和領袖之戒確實都很昂貴，任何一個人都不可能獨自購買。$b$b我建議你和其他冒險者共組隊伍並選出一名勇士。只需要一枚勳章和戒指就能召喚深淵議會的高階成員，但需要許多英雄同心協力才有可能擊敗他們。$b$b祝你好運。', '', 25549),
(126272, 'zhTW', '進攻暮光之錘的營地，並擊潰高階深淵議會！\n\n殺死居住在三個異種蠍巢穴中的巨大異種蠍。\n\n為我們的陣營收集希利蘇斯紅塵，一種珍貴的紅色香料。\n\n進入安其拉探險，挑戰其中的其拉部隊與古神爪牙！\n\n連不想要戰鬥的冒險者也可以捐獻肉品做為戰爭物資，參與貢獻。', '', 25549),
(126271, 'zhTW', '許多年前的今日，一位名叫卡拉哈德的英雄敲響甲蟲之鑼，開啟安其拉的大門，一場卡林多歷史上前所未見的大戰就此展開。$b$b今天，我們要透過回到希利蘇斯重現當時的情況，來慶祝過往冒險者的英勇事蹟。$b$b另外，這將是一場部落與聯盟的競賽。在接下來24小時內獲得較高積分的陣營將有資格在今年於甲蟲之鑼旁高掛陣營旗幟。', '', 25549),
(126270, 'zhTW', '', '沒錯。大祭司，給我們一點時間記錄這些事蹟。我們在虛空之光神殿碰頭。', 25549),
(126269, 'zhTW', '就是你，大祭司。', '', 25549),
(126268, 'zhTW', '她早就料到虛無會佔據這個地方。她也知道誰會為了聖光，來保護並「運用」這些『追尋者』。', '', 25549),
(126267, 'zhTW', '不，你錯了。這就是為什麼艾澤拉斯要我…要我們來這裡。', '', 25549),
(126266, 'zhTW', '', '這樣就沒有人照顧追尋者了！', 25549),
(126265, 'zhTW', '', '嗯，管理員不動了。能量可能被這個房間耗光了。', 25549),
(126264, 'zhTW', '終於清掉最後一隻了。希望這是最後一次遇到這種狀況了…', '', 25549),
(126263, 'zhTW', '我就知道，最大隻的一定會活過來。大家自己小心！', '', 25549),
(126262, 'zhTW', '我感應到腐化的現象。你們最好小心一點。', '', 25549),
(126261, 'zhTW', '', '這是聖光的產物，不屬於這個世界。或許可以驅散。', 25549),
(126260, 'zhTW', '真是幫了一個大忙！好吧，只能上了！', '', 25549),
(126259, 'zhTW', '無法執行。無法中止清理程序。無法確認訪客是否遭到汙染。各位貴賓如果聽見來源不明的聲音，請自行踏入高溫光線當中。', '', 25549),
(126258, 'zhTW', '呃…請停止。好嗎？', '', 25549),
(126257, 'zhTW', '喔！當然！還不只一次！你可是偉大的『代言者』呢，能把這個東西關掉嗎？', '', 25549),
(126256, 'zhTW', '又來了？你以前遇過這種事嗎？', '', 25549),
(126255, 'zhTW', '不會吧！又來了！', '', 25549),
(126254, 'zhTW', '注意！發現虛無能量。啟動清理程序。', '', 25549),
(126253, 'zhTW', '這些高貴的生物在我們知道如何保護自己以前，就在保護我們了…', '', 25549),
(126252, 'zhTW', '從這個星球誕生以來，各方邪惡勢力都想入侵這裡，許多『追尋者』也因此在戰鬥中接連犧牲。現在剩下的『追尋者』就只有這些了。', '', 25549),
(126251, 'zhTW', '呃，那他們發生什麼事了？', '', 25549),
(126250, 'zhTW', '', '這裡只有三個『追尋者』？', 25549),
(126249, 'zhTW', '計算中…目前已知『追尋者』數量：三。', '', 25549),
(126248, 'zhTW', '獸群？可是我們一隻都沒看到！現在到底還剩幾隻？', '', 25549),
(126247, 'zhTW', '稱號：『追尋者』。這是『塑造者』灌注聖光的生物，從獸群中挑選最佳目標，加強訓練以達到服務看守者之需求，可依汙染管理程序將其移動到汙染地點。', '', 25549),
(126246, 'zhTW', '讓我向你展示。', '', 25549),
(126245, 'zhTW', '', '呃，管理員先生，到底這個『追尋者』又是什麼？', 25549),
(126244, 'zhTW', '『追尋者』…對，艾澤拉斯要我來這裡一定是這個意思。她要我們去找『追尋者』。', '', 25549),
(126243, 'zhTW', '發現『代言者』。歡迎，請問『代言者』是否來找回『追尋者』？', '', 25549),
(126242, 'zhTW', '這是什麼意思？誰不必要？我嗎？你才不必要，你這混蛋…', '', 25549),
(126241, 'zhTW', '未發現必要生物體。重新掃描。', '', 25549),
(126240, 'zhTW', '噢，我知道接下來會發生什麼事！拿起武器！', '', 25549),
(126239, 'zhTW', '正在掃描生命體。', '', 25549),
(126238, 'zhTW', '系統啟動。發現訪客。', '', 25549),
(126237, 'zhTW', '它們要同時全部啟動才可以。大祭司，你能幫忙嗎？', '', 25549),
(126236, 'zhTW', '唉，真可惜。', '', 25549),
(126235, 'zhTW', '', '哈，布萊恩，看來你不用找控制桿和開關了！', 25549),
(126234, 'zhTW', 'Revola ruk maez amir.', '', 25549),
(126233, 'zhTW', '天啊，這門好大！應該有控制桿可以拉吧。每次都一定會有個控制桿！', '', 25549),
(126232, 'zhTW', '準備上岸的事吧。', '', 25549),
(126231, 'zhTW', '', '我們好像來到泰坦遺址的入口了。', 25549),
(126230, 'zhTW', '那感覺就像…日出。', '', 25549),
(126229, 'zhTW', '呃…艾澤拉斯就這樣讓你「感覺」到你應該過來？', '', 25549),
(126228, 'zhTW', '嗯，想像一下，如果你是一個世界的靈魂，會有什麼感覺？有時候你會覺得像是山崩地裂，有時候會覺得和大海一樣深沉？我不知道究竟該怎麼形容。', '', 25549),
(126227, 'zhTW', '', '你到底在說什麼？', 25549),
(126226, 'zhTW', '不太像真的在說話。比較像…一種感覺…但這種感覺是我們不曾體驗過的。', '', 25549),
(126225, 'zhTW', '老哥，所以…艾澤拉斯這個星球，突然就對你開口…叫你來這裡？', '', 25549),
(126224, 'zhTW', '', '雖然我們離大漩渦這麼近，但大海目前很平靜。', 25549),
(126223, 'zhTW', '我從探險者協會借了一艘小潛水艇。大祭司，等你準備好，我們就可以前往艾蘇納的海岸了。', '', 25549),
(126222, 'zhTW', '', '大祭司！我有重要的事要向你報告。', 25549),
(126221, 'zhTW', '我很榮幸能執行這個任務。我不會讓你失望的，$n宗師。', '', 25549),
(126220, 'zhTW', '我需要你說服其他的職業組織加入我們一起對抗燃燒軍團。大家必須團結起來！', '我需要你說服其他的職業組織加入我們一起對抗燃燒軍團。大家必須團結起來！', 25549),
(126219, 'zhTW', '燃燒軍團步步進逼艾澤拉斯。我們都得出一分力。', '', 25549),
(126218, 'zhTW', '今天，我們要慶祝敲響甲蟲之鑼的紀念日。希利蘇斯四處都會舉辦各種慶祝活動。$b$b其中一項傳統是要從三個異種蠍的巢穴中召喚巨大的昆蟲。我們需要肉才能完成。堆積如山的肉。$b$b你能幫個忙嗎？', '', 25549),
(126217, 'zhTW', '', '我好累，好累。可是我不能休息，一定要確保大家都平安無事。', 25549),
(126216, 'zhTW', '有你領導，再加上風暴蜜酒，我們一定獲勝！', '', 25549),
(126215, 'zhTW', '我要對付贊德拉爾。帶我上去！', '我要對付贊德拉爾。帶我上去！', 25549),
(126214, 'zhTW', '我們必須淨化燃燒軍團的腐化！', '', 25549),
(126209, 'zhTW', '', '看來卡魯歐的嘍囉剛來過這裡。', 25549),
(126208, 'zhTW', '<回想古爾丹之死>', '<回想古爾丹之死>', 25549),
(126207, 'zhTW', '自由萬歲！', '', 25549),
(126206, 'zhTW', '歐丁祝福你。', '', 25549),
(126205, 'zhTW', '願英靈殿的大門為你敞開。', '', 25549),
(126204, 'zhTW', '感謝歐丁，還以為我死定了！', '', 25549),
(126203, 'zhTW', '', '喔，你知道的…\n\n他們就在附近。\n\n快去吧！', 25549),
(126202, 'zhTW', '其他人呢？', '其他人呢？', 25549),
(126201, 'zhTW', '', '沒錯，我的確少了王冠。謝謝你注意到這一點。\n\n<特使開心地對你露出微笑。>', 25549),
(126200, 'zhTW', '', '又是灰白的石頭和綠色的火焰。', 25549),
(126199, 'zhTW', '', '早知道我會被派來這裡。', 25549),
(126198, 'zhTW', '', '為什麼總會是惡魔呢？', 25549),
(126197, 'zhTW', '', '你追得太緊了，英雄。我的寶貝小鬼們會懲罰你，讓你痛不欲生。', 25549),
(126196, 'zhTW', '', '你這樣讓我很煩躁。我的寶貝小鬼們，快保護我！', 25549),
(126195, 'zhTW', '送我去破碎海岸！', '送我去破碎海岸！', 25549),
(126194, 'zhTW', '你展現出非凡的戰鬥能力。可惜你的本職並非戰士！不過沒有凡人是完美的。', '', 25549),
(126193, 'zhTW', '還有殘存的怒魔維酷人不知道他們的神御之王早已倒下。加入我的華爾拉亞討伐他們，送這些蠢蛋去見他們死去的領導者！', '', 25549),
(126192, 'zhTW', '為了華爾拉亞！', '', 25549),
(126191, 'zhTW', '戰鬥領主！還有一些殘存的怒魔維酷人，不知道他們的神御之王已經死了。送這些傢伙去跟他們的主人團圓。', '', 25549),
(126190, 'zhTW', '打擾我用餐是你致命的錯誤，凡人！', '', 25549),
(126189, 'zhTW', '我的電腦！你…怎麼猜到我的密碼的？！我明明用了很多符號跟大小寫！', '', 25549),
(126188, 'zhTW', '', '她以後就知道自己選錯邊了。只有燃燒軍團才是我們的盟友！', 25549),
(126187, 'zhTW', '各位注意。本船艦即將啟動自動毀滅程序。請以最快的速度離開本船艦。', '', 25549),
(126186, 'zhTW', '', '希蕊妮派你來的？她寧願跟外來者聯手，也不肯跟自己的族人合作？', 25549),
(126185, 'zhTW', '', '你的罪行只能用命來償還！', 25549),
(126184, 'zhTW', '', '蕾瑟拉，你真可恥！你答應過會保護我們的城市！', 25549),
(126183, 'zhTW', '', '我們回頭見。', 25549),
(126182, 'zhTW', '', '被困在這艘破船上好幾個月…我都快悶到發瘋了。再說，當時的情況需要我的特殊專長…\n\n或許我應該先召喚一個分身。', 25549),
(126181, 'zhTW', '你為什麼拋下其他人？', '你為什麼拋下其他人？', 25549),
(126180, 'zhTW', '經歷數年的烹飪訓練，讓你有能力辨認這奇怪的花朵。食用它非常安全，甚至能為你的盟友帶來助益！', '經歷數年的烹飪訓練，讓你有能力辨認這奇怪的花朵。食用它非常安全，甚至能為你的盟友帶來助益！', 25549),
(126179, 'zhTW', '身為熊貓人，你能辨認這朵可食用的花。趕快吃了它吧！', '身為熊貓人，你能辨認這朵可食用的花。趕快吃了它吧！', 25549),
(126178, 'zhTW', '', '很高興你遵守了諾言，斬魔者$n。或許我錯看你了。', 25549),
(126177, 'zhTW', '學習草藥學讓你對於各種天然食材都相當熟悉。這個絕對可以食用！', '學習草藥學讓你對於各種天然食材都相當熟悉。這個絕對可以食用！', 25549),
(126176, 'zhTW', '身為德魯伊，你有能力辨認用來烹調這些食物的植物與食材。食用上應該很安全。', '身為德魯伊，你有能力辨認用來烹調這些食物的植物與食材。食用上應該很安全。', 25549),
(126175, 'zhTW', '$n淨化了魔化火球，使大家的致命一擊機率提高！', '$n淨化了魔化火球，使大家的致命一擊機率提高！', 25549),
(126174, 'zhTW', '$n摧毀了魔化火球，使大家的致命一擊機率提高！', '$n摧毀了魔化火球，使大家的致命一擊機率提高！', 25549),
(126173, 'zhTW', '無所謂！你們必須付出代價…我要吞噬你的靈魂！', '', 25549),
(126172, 'zhTW', '可惡的凡人！你對我的船艦做了什麼？！', '', 25549),
(126171, 'zhTW', '$n從煉獄秘典吸取魔力，使大家受到的傷害降低！', '$n從煉獄秘典吸取魔力，使大家受到的傷害降低！', 25549),
(126170, 'zhTW', '成為惡魔獵人的訓練讓你早有準備應付這樣的情況。取出煉獄秘典內的力量。', '成為惡魔獵人的訓練讓你早有準備應付這樣的情況。取出煉獄秘典內的力量。', 25549),
(126169, 'zhTW', '身為術士，這一點惡魔魔法對你根本不構成威脅。吸收煉獄秘典的力量。', '身為術士，這一點惡魔魔法對你根本不構成威脅。吸收煉獄秘典的力量。', 25549),
(126168, 'zhTW', '牧師一眼就看出這是個邪惡之物，必須摧毀。', '牧師一眼就看出這是個邪惡之物，必須摧毀。', 25549),
(126167, 'zhTW', '身為神聖的聖騎士，你必須淨化這惡魔腐化。', '身為神聖的聖騎士，你必須淨化這惡魔腐化。', 25549),
(126166, 'zhTW', '掀了這片土地！一個凡人也別放過！他們的靈魂全是我的！', '', 25549),
(126165, 'zhTW', '', '我一個人也沒問題的…謝謝你。', 25549),
(126164, 'zhTW', '', '啊，斬魔者。既然都來了，就幫點忙吧。', 25549),
(126163, 'zhTW', '餵給魔能的靈魂越多越好！我還要更多！', '', 25549),
(126162, 'zhTW', '穆倫對著瑪加薩腳邊吐口水，滿臉嫌惡。', '', 25549),
(126161, 'zhTW', '還要…我還要更多靈魂！', '', 25549),
(126160, 'zhTW', '她批評我們的紀律以後就自己走了。之後我就沒有再看到她。', '', 25549),
(126159, 'zhTW', '不會讓她在這裡亂來的，我向你保證。', '', 25549),
(126158, 'zhTW', '但與其讓她四處恣意妄為，倒不如把她拉在身邊還比較安全。', '', 25549),
(126157, 'zhTW', '穆倫，我知道你很生氣，我知道其他牛頭人看到她在這裡都很生氣。', '', 25549),
(126156, 'zhTW', '爛酋長？！先知，快把她踢出去！我不能接受！', '', 25549),
(126155, 'zhTW', '', '笨蛋，別囉嗦。死一個爛酋長有差嗎，現在有更嚴重的事。', 25549),
(126154, 'zhTW', '你想讓這個怪物踏進聖地？她殺了我們的酋長！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126153, 'zhTW', '如果你想回守護者殿堂，就跟我說一聲。', '', 25549),
(126152, 'zhTW', '我跟安東尼達斯不熟，但我相信他會為你今天所做的一切為榮，大法師。', '', 25549),
(126151, 'zhTW', '', '惡魔，我見識過你所謂的「禮物」會導致什麼後果。我絕對不會加入你們！', 25549),
(126150, 'zhTW', '抵抗也沒有用！你不加入我們，我就剝你的皮來會當披風！', '', 25549),
(126149, 'zhTW', '', '喂！幫我解開這副鐐銬！', 25549),
(126148, 'zhTW', '', '感謝你，小傢伙。', 25549),
(126147, 'zhTW', '', '謝謝你，要不是我被鍊起來，一定會親自去打死那個醜八怪！', 25549),
(126146, 'zhTW', '又有肉可以烤了！', '', 25549),
(126145, 'zhTW', '燃燒軍團會殺死你！', '', 25549),
(126144, 'zhTW', '踩碎你的骨頭！', '', 25549),
(126143, 'zhTW', '壓扁你！', '', 25549),
(126142, 'zhTW', '幫我修理護甲，葛魯。', '幫我修理護甲，葛魯。', 25549),
(126141, 'zhTW', '葛魯不太知道要怎麼用小小的鐵砧。\n\n<莫阿格蠻卒低頭盯著自己的腳。>', '', 25549),
(126140, 'zhTW', '擂台的對角上，是一位會打致命嘴砲的海盜！敲響雙手鐵鉤，熱烈歡迎黑腮鬍！', '', 25549),
(126139, 'zhTW', '現在來享受一點來自地下音樂界的撼魂重低音，請熱烈歡迎搖滾重擊和他的勁爆舞團！', '', 25549),
(126138, 'zhTW', '在擂臺的另一邊，是鬥陣特攻隊的恐怖三人組：赫斯頓、砲彈鼠和米卡利！', '', 25549),
(126137, 'zhTW', '請熱情歡迎這個會讓你熱血沸騰的巨靈，我說真的你的血會沸騰，開心火登場！', '', 25549),
(126136, 'zhTW', '接下來這個挑戰者花了我們好多好多錢啊…請掌聲歡迎瑞德‧提爾！', '', 25549),
(126135, 'zhTW', '在擂臺另一邊，站著一名獵人，他渾身散發一股無法言喻的閃亮超帥光輝！請熱烈歡迎『棒透了』強尼！', '', 25549),
(126134, 'zhTW', '另一位挑戰者是個嚴重喜愛玩火的笨蟲！卡爾，你不知道這樣玩下去會死人嗎？', '', 25549),
(126133, 'zhTW', '現在要進入競技場的是…能演奏美妙音樂的優雅機械。', '', 25549),
(126132, 'zhTW', '在擂臺另一邊站的是，不只一個、不只兩個，而是三個強大矮人所組成的戰錘議會！', '', 25549),
(126131, 'zhTW', '請先投幣，才能開始與帕庫大師對戰！', '', 25549),
(126130, 'zhTW', '在擂臺另一端…是一隻很大很大的恐龍！', '', 25549),
(126129, 'zhTW', '在擂臺另一端，是古老到沒有人記得他真正名字的挑戰者。我們就叫他…遠古靈蛇吧！', '', 25549),
(126128, 'zhTW', '在擂臺另一端，是一位同時精通暗影和室內照明的超級大師…暗影大師亞銘！', '', 25549),
(126127, 'zhTW', '隆重介紹瘋狂執著於收集寵物的德萊尼…小志‧卡啾！', '', 25549),
(126126, 'zhTW', '今天的挑戰者則是死亡照護師，『清潔工』比爾！等等…什麼？比爾！你在那裡幹嘛？', '', 25549),
(126125, 'zhTW', '對這…東西來說，顯然天天都是萬鬼節。大家盡情尖叫歡迎烏利斯吧！', '', 25549),
(126124, 'zhTW', '快看那頭巨大的海牛！ 牠絕對不會手下牛情，請掌聲歡迎末日鰭！', '', 25549),
(126123, 'zhTW', '那是巨大的蘑菇嗎！看來事情會變得非常奇怪。', '', 25549),
(126122, 'zhTW', '擂臺另一邊的是…一隻海鷗？他以為這裡是艾薩拉之眼嗎？', '', 25549),
(126121, 'zhTW', '這位戰鬥者從暮色森林的幽暗小徑遠道而來，請熱烈歡迎縫合怪！', '', 25549),
(126120, 'zhTW', '那就帶我去大漩渦，不然我要把它帶走。', '那就帶我去大漩渦，不然我要把它帶走。', 25549),
(126119, 'zhTW', '', '混蛋！不准你碰我的末日石！', 25549),
(126118, 'zhTW', '我認為把它交給諾柏多最安全。', '我認為把它交給諾柏多最安全。', 25549),
(126117, 'zhTW', '', '末日石，趕快給我！', 25549),
(126115, 'zhTW', '', '擂臺的對角上，是一位會打致命嘴砲的海盜！敲響雙手鐵鉤，熱烈歡迎黑腮鬍！', 25549),
(126114, 'zhTW', '', '現在來享受一點來自地下音樂界的撼魂重低音，請熱烈歡迎搖滾重擊和他的勁爆舞團！', 25549),
(126113, 'zhTW', '', '在擂臺的另一邊，是鬥陣特攻隊的恐怖三人組：赫斯頓、砲彈鼠和米卡利！', 25549),
(126112, 'zhTW', '', '請熱情歡迎這個會讓你熱血沸騰的巨靈，我說真的你的血會沸騰，開心火登場！', 25549),
(126111, 'zhTW', '', '接下來這個挑戰者花了我們好多好多錢啊…請掌聲歡迎瑞德‧提爾！', 25549),
(126110, 'zhTW', '', '在擂臺另一邊，站著一名獵人，他渾身散發一股無法言喻的閃亮超帥光輝！請熱烈歡迎『棒透了』強尼！', 25549),
(126109, 'zhTW', '', '另一位挑戰者是個嚴重喜愛玩火的笨蟲！卡爾，你不知道這樣玩下去會死人嗎？', 25549),
(126108, 'zhTW', '', '同時要進入競技場的是…一隻會發出音樂聲的醜八怪地精玩意兒。', 25549),
(126107, 'zhTW', '', '在擂臺另一邊站的是，不只一個、不只兩個，而是三個強大矮人所組成的戰錘議會！', 25549),
(126106, 'zhTW', '', '請先投幣，才能開始與帕庫大師對戰！', 25549),
(126105, 'zhTW', '', '在擂臺另一端…是一隻很大很大的恐龍！', 25549),
(126104, 'zhTW', '', '在擂臺另一端，是一位古老到沒有人記得他真正名字的挑戰者。我們就叫他…遠古靈蛇吧！', 25549),
(126103, 'zhTW', '', '在擂臺另一端，是一位同時精通暗影和室內照明的超級大師…暗影大師亞銘！', 25549),
(126102, 'zhTW', '', '隆重介紹瘋狂執著於收集寵物的德萊尼…小志‧卡啾！', 25549),
(126101, 'zhTW', '瑪加薩，我不會把末日石交給你。', '瑪加薩，我不會把末日石交給你。', 25549),
(126100, 'zhTW', '', '今天的挑戰者則是死亡照護師，『清潔工』比爾！等等…什麼？比爾！你在那裡幹嘛？', 25549),
(126099, 'zhTW', '', '快看那頭巨大的海牛！ 牠絕對不會手下牛情，請掌聲歡迎末日鰭！', 25549),
(126098, 'zhTW', '', '那是巨大的蘑菇嗎！看來事情會變得非常奇怪。', 25549),
(126097, 'zhTW', '', '這位戰鬥者遠道從暮色森林的幽暗小徑而來，請熱烈歡迎縫合怪！', 25549),
(126096, 'zhTW', '', '對這…東西來說，顯然天天都是萬鬼節。大家盡情尖叫歡迎烏利斯吧！', 25549),
(126095, 'zhTW', '太好了！你辦到了！全部的稜碟可以合而為一了！', '', 25549),
(126094, 'zhTW', '', '擂臺另一邊的是…一隻海鷗？他以為這裡是艾薩拉之眼嗎？', 25549),
(126093, 'zhTW', '', '別把我當成你的手下。你對我而言根本只是小孩。', 25549),
(126092, 'zhTW', '大法師，別分心！只剩一個稜碟要處理了。記住，我的學徒可以幫你的忙。', '', 25549),
(126091, 'zhTW', '大法師，做得好！淨化以後，這個稜碟就算靠近其他的，也不會產生劇烈的反應。其他兩個稜碟應該可以比照處理。', '', 25549),
(126089, 'zhTW', '瓦解它們的防禦。殺掉這些惡魔！', '', 25549),
(126088, 'zhTW', '我想去闇盲沼澤地幫忙。', '我想去闇盲沼澤地幫忙。', 25549),
(126087, 'zhTW', '我們必須立刻解除這個威脅。', '', 25549),
(126086, 'zhTW', '', '蠢東西，你連傳送門都不會開，竟然還想控制末日石的力量？別傻了。', 25549),
(126085, 'zhTW', '', '你從這裡向前走，我走另一邊。我們之後再碰頭。', 25549),
(126084, 'zhTW', '你別想阻止…燃燒軍團…', '', 25549),
(126083, 'zhTW', '薩滿，你要末日石嗎？有本事就來啊！', '', 25549),
(126082, 'zhTW', '為雷霆圖騰而戰！', '為雷霆圖騰而戰！', 25549),
(126081, 'zhTW', '撐住！', '撐住！', 25549),
(126080, 'zhTW', '快去幫其他人！', '快去幫其他人！', 25549),
(126079, 'zhTW', '擋住他們！', '擋住他們！', 25549),
(126078, 'zhTW', '$n，別放棄！', '$n，別放棄！', 25549),
(126076, 'zhTW', '大法師，歡迎你。希望你已經準備好了。', '', 25549),
(126075, 'zhTW', '斯寇瓦德的血脈必須死！', '', 25549),
(126074, 'zhTW', '', '走吧，孩子。一定要拯救我的族人。', 25549),
(126073, 'zhTW', '', '別浪費時間！你的先知在哪裡？', 25549),
(126072, 'zhTW', '你大概知道處理這些秘法能量會發生什麼事了，跟其他稜碟差不多。注意別讓它任意生長，別讓情況變得不可收拾。', '', 25549),
(126071, 'zhTW', '這些生物活得越久，力量就越強。盡快燒死牠們，並且隨時干擾，別讓牠們有機會成長。', '', 25549),
(126070, 'zhTW', '終於要處理冰霜能量了。回想一下目前看過的狀況，善用你的知識。', '', 25549),
(126069, 'zhTW', '這個稜碟所產生的東西會拖慢你的速度，然後毀掉你。反制它們的法術，同時注意別被它們擊中。', '', 25549),
(126068, 'zhTW', '大法師，快結束了。如果你還記得先前敵人的特性，一定能應付接下來的事情。', '', 25549),
(126067, 'zhTW', '大法師$p，你做得不錯，記得把目標聚集起來用範圍技攻擊。', '', 25549),
(126066, 'zhTW', '', '迪賓！你聽得見我的聲音嗎？等我逃出去以後，就要殺光所有把我們害成這樣的人！', 25549),
(126065, 'zhTW', '你的出現讓我眼睛一亮，戰鬥領主！', '', 25549),
(126064, 'zhTW', '但如果你真的想把稜碟找回來，我猜一定在奧特蘭克廢墟某處。那些巨魔住在那裡。', '', 25549),
(126063, 'zhTW', '別太擔心，連我都不知道該怎麼幫安東尼達斯，那些巨魔一定也拿稜碟沒轍。', '', 25549),
(126062, 'zhTW', '都是那些巨魔的錯，真是齷齪的怪物。他們前陣子來搶東西，把冰霜稜碟搶走了。', '', 25549),
(126061, 'zhTW', '嗯，沒錯，我知道。我的意思是我以前知道。這東西被搶走了。', '', 25549),
(126060, 'zhTW', '你的眉毛還在嗎？其他試過那個法術的學徒，可就不像你這麼幸運了！', '', 25549),
(126059, 'zhTW', '大法師賽卓克，我正在找安東尼達斯交給你的稜碟。稜碟在你手上嗎？', '大法師賽卓克，我正在找安東尼達斯交給你的稜碟。稜碟在你手上嗎？', 25549),
(126058, 'zhTW', '你的提里斯護法火占師，已經開始掃蕩岩洞裡殺不完的蜘蛛了。曼納斯頓先生願意提供一道特別的法術，他說你是個「老朋友」。', '', 25549),
(126057, 'zhTW', '當時跟我一起研究火焰稜碟的是大法師艾特羅斯，他可能比較清楚那東西現在在哪。你可以在卡拉贊外找到艾特羅斯。', '', 25549),
(126056, 'zhTW', '你在說火焰稜碟吧。沒錯，他交給我了，但那是很久以前的事。當時我還在卡拉贊當學徒。', '', 25549),
(126055, 'zhTW', '卡德加，我正在找一個稜碟，是安東尼達斯很久以前交給你的。', '卡德加，我正在找一個稜碟，是安東尼達斯很久以前交給你的。', 25549),
(126054, 'zhTW', '', '我會永遠記住你。總有一天，所有蔑潮族人都會知道你的事蹟。', 25549),
(126053, 'zhTW', '', '看來你是對的，外來者。謝謝你幫我找到屬於我的路。', 25549),
(126052, 'zhTW', '$n！你看過戰場了嗎？我們正在盡力阻止惡魔！', '$n！你看過戰場了嗎？我們正在盡力阻止惡魔！', 25549),
(126051, 'zhTW', '別讓惡魔蹂躪我們的家園！', '別讓惡魔蹂躪我們的家園！', 25549),
(126050, 'zhTW', '如果你還能戰鬥，就來幫助雷霆圖騰吧！我們必須守住這裡！', '如果你還能戰鬥，就來幫助雷霆圖騰吧！我們必須守住這裡！', 25549),
(126049, 'zhTW', '小心！燃燒軍團一定會繼續攻擊。', '小心！燃燒軍團一定會繼續攻擊。', 25549),
(126048, 'zhTW', '$n！我們遭受攻擊，現在傷亡慘重！你只要願意幫忙，雷霆圖騰就能撐下去！', '$n！我們遭受攻擊，現在傷亡慘重！你只要願意幫忙，雷霆圖騰就能撐下去！', 25549),
(126047, 'zhTW', '', '如果你能完成安東尼達斯未完成的工作，就拿去吧。大法師$n，祝你好運。', 25549),
(126046, 'zhTW', '', '安東尼達斯死了以後，我決定把稜碟藏起來。我沒有理由繼續研究它了。', 25549),
(126045, 'zhTW', '', '我已經很久沒想那件事了…以前有朋友提過，問完沒多久就死了。', 25549),
(126044, 'zhTW', '戰鬥領主！很高興你找到我了。', '', 25549),
(126043, 'zhTW', '我正在找安東尼達斯的秘法稜碟，在你手裡嗎？', '我正在找安東尼達斯的秘法稜碟，在你手裡嗎？', 25549),
(126042, 'zhTW', '$n，你好。有什麼我可以幫忙的嗎？', '', 25549),
(126041, 'zhTW', '', '哼！我會親自解決你！', 25549),
(126040, 'zhTW', '勇敢的$c，你說的沒錯。大家必須團結一心！', '勇敢的$c，你說的沒錯。大家必須團結一心！', 25549),
(126039, 'zhTW', '燃燒軍團！你必須警告大家！', '燃燒軍團！你必須警告大家！', 25549),
(126038, 'zhTW', '我沒事了，請你多照顧其他人！', '我沒事了，請你多照顧其他人！', 25549),
(126037, 'zhTW', '謝謝。感謝你幫忙。', '謝謝。感謝你幫忙。', 25549),
(126036, 'zhTW', '$n，從你所說的話可以聽出你很勇敢。保重。', '$n，從你所說的話可以聽出你很勇敢。保重。', 25549),
(126035, 'zhTW', '我們會去確認惡魔真的都死了。等你有時間，回潛影之廳聽取簡報。', '', 25549),
(126034, 'zhTW', '', '我們的故事會流傳下去，大家會唱關於我們的歌，今天即將發生的事情，會成為歷史的榮光。', 25549),
(126033, 'zhTW', '', '只要團結所有軍隊，燃燒軍團必敗無疑！', 25549),
(126032, 'zhTW', '自由了！我馬上…', '', 25549),
(126031, 'zhTW', '可惜你都看不到了。去死吧！', '', 25549),
(126030, 'zhTW', '如果有一整隊這種怪物，我就能打穿岩石，毀滅雷霆圖騰！', '', 25549),
(126029, 'zhTW', '我找到一種能承受惡魔力量的生物。', '', 25549),
(126028, 'zhTW', '我們成功領先了！為了聯盟！', '', 25549),
(126027, 'zhTW', '你好！部落領先了！', '', 25549),
(126026, 'zhTW', '', '今天，我們要慶祝敲響甲蟲之鑼的紀念日。希利蘇斯四處都會舉辦各種慶祝活動。$b$b其中一項傳統是要從三個異種蠍的巢穴中召喚巨大的昆蟲。我們需要肉才能完成。堆積如山的肉。$b$b你能幫個忙嗎？', 25549),
(126025, 'zhTW', '', '別浪費時間，影尊。走吧。', 25549),
(126024, 'zhTW', '剛剛的情況還真是無比火熱啊，不過你也火速解決了。', '', 25549),
(126023, 'zhTW', '勇士，提里斯護法的法師需要你幫忙掃蕩蜘蛛岩洞，殺掉裡面的蜘蛛。他們的火占師會放火焰幫助你。', '', 25549),
(126022, 'zhTW', '', '好了，利用垂降點，開始吧！', 25549),
(126021, 'zhTW', '', '等等…那個笨蛋酒鬼忘了，是吧？你給我想辦法點燃火藥。我不許這個任務失敗！', 25549),
(126020, 'zhTW', '我已經準備好前往永恆之眼。', '我已經準備好前往永恆之眼。', 25549),
(126019, 'zhTW', '', '好，差不多完成了。離開洞穴，用瑟希斯給你的火柴點燃火藥。', 25549),
(126018, 'zhTW', '', '對了，還有一件事。在附近多放點炸藥，讓爆炸再猛烈一點。', 25549),
(126017, 'zhTW', '', '很好。下一步很簡單，離開洞穴，別被發現。剩下的，就交給火藥。', 25549),
(126016, 'zhTW', '', '對了，最好別被發現，否則背上很可能會被砍一刀。', 25549),
(126015, 'zhTW', '', '到地面後會看到一個桶子。裡面是你之前拿到的…魔能灌注火藥。', 25549),
(126014, 'zhTW', '我想挑戰圖加。(需要強能鑰石)', '我想挑戰圖加。(需要強能鑰石)', 25549),
(126013, 'zhTW', '我想挑戰圖加。(使用納瓦羅格的強能鑰石)', '我想挑戰圖加。(使用納瓦羅格的強能鑰石)', 25549),
(126012, 'zhTW', '只能直接打爛圖加和他身邊的小蟲了！你準備好我就帶你過去。', '', 25549),
(126011, 'zhTW', '', '你曾經幫我保護這片土地，現在換我來幫你。來吧，我們先找一個方便說話的地方。', 25549),
(126010, 'zhTW', '$c，我永遠感謝你。', '$c，我永遠感謝你。', 25549),
(126009, 'zhTW', '英雄，謝謝你。你救我逃離可怕的命運。', '英雄，謝謝你。你救我逃離可怕的命運。', 25549),
(126008, 'zhTW', '戰鬥領主，謝謝你。為了聯盟！', '戰鬥領主，謝謝你。為了聯盟！', 25549),
(126007, 'zhTW', '你來得正是時候。我覺得牠們想把我吃掉…', '你來得正是時候。我覺得牠們想把我吃掉…', 25549),
(126006, 'zhTW', '*哽咽*那實在…太美了…', '', 25549),
(126005, 'zhTW', '英雄，謝謝你。你救我逃離可怕的命運。', '英雄，謝謝你。你救我逃離可怕的命運。', 25549),
(126004, 'zhTW', '戰鬥領主，我永遠感謝你。', '戰鬥領主，我永遠感謝你。', 25549),
(126003, 'zhTW', '戰鬥領主，謝謝你。為了部落！', '戰鬥領主，謝謝你。為了部落！', 25549),
(126002, 'zhTW', '你來得正是時候。我覺得牠們想把我吃掉…', '你來得正是時候。我覺得牠們想把我吃掉…', 25549),
(126001, 'zhTW', '', '等等…他忘了，對吧？我就知道。看來你得想別的辦法點燃火藥了！', 25549),
(126000, 'zhTW', '', '快完成了。現在離開洞穴，用瑟希斯給你的火柴點燃火藥。', 25549),
(125999, 'zhTW', '蠢蛋，太遲了！我已經拿到可以摧毀雷霆圖騰的東西了！', '', 25549),
(125998, 'zhTW', '', '建議你在路上多放點炸藥。我們最好別讓瑟希斯失望，對吧？', 25549),
(125997, 'zhTW', '', '很好，你沿路留下的火藥派得上用場。現在想辦法離開洞穴吧。', 25549),
(125996, 'zhTW', '', '還有，最好別被發現。這些惡魔非常殘暴！', 25549),
(125995, 'zhTW', '', '你之前拿到的火藥就放在底下。記得，先去把那些火藥拿起來。', 25549),
(125994, 'zhTW', '', '利用那個垂降點進入洞穴。進去以後我再告訴你怎麼做。', 25549),
(125993, 'zhTW', '', '我們到了！他們很快就會知道我們的厲害。', 25549),
(125992, 'zhTW', '我準備好了。', '我準備好了。', 25549),
(125991, 'zhTW', '', '在我接下王位之前，為了我的家人，我要先完成弟弟的要求。\n\n如果埃伊爾知道誰是謀殺我家人的主使者，我一定要從她口中聽到。\n\n等你準備好了就告訴我。', 25549),
(125990, 'zhTW', '有提里斯護法領軍，我們的聯軍一定能一舉終結燃燒軍團！', '', 25549),
(125989, 'zhTW', '我敢打賭，這些防護師身上一定有強大的法力。聰明的法師會把法力偷過來！', '', 25549),
(125988, 'zhTW', '', '啊，我們到了！', 25549),
(125987, 'zhTW', '誰去…警告圖加…', '', 25549),
(125986, 'zhTW', '圖加會替我報仇。', '', 25549),
(125985, 'zhTW', '你太遲了…圖加必勝…', '', 25549),
(125984, 'zhTW', '我準備好前往營地了。', '我準備好前往營地了。', 25549),
(125982, 'zhTW', '', '影尊，時間不多了。我們趕快到上面去吧！', 25549),
(125981, 'zhTW', '好極了！最難的已經解決了，接下來只要摧毀指揮艦就好！', '', 25549),
(125980, 'zhTW', '$n，我有好消息！傳送門沒問題！你看你的手腳都在，對吧？', '', 25549),
(125979, 'zhTW', '', '迪賓，你還活著！親愛的朋友，我本來已經絕望了。', 25549),
(125976, 'zhTW', '顫抖吧！看看這可悲的世界跟燃燒軍團的威力相比，是多麼渺小！', '', 25549),
(125975, 'zhTW', '', '主人，別離太遠。', 25549),
(125974, 'zhTW', '', '如果梅菲斯托大人願意，我可以陪你去導航室的指揮臺。', 25549),
(125973, 'zhTW', '', '主人，很抱歉，請自行輸入自動毀滅程序指令。', 25549),
(125972, 'zhTW', '', '很可惜，我沒有下達這種指令的權限。', 25549),
(125971, 'zhTW', '', '解除護盾產生器之後，就能用自動毀滅程序摧毀船艦。', 25549),
(125970, 'zhTW', '我讓護盾產生器超載了，接下來該怎麼做？', '我讓護盾產生器超載了，接下來該怎麼做？', 25549),
(125967, 'zhTW', '別急，瑟希斯，別亂跑。', '', 25549),
(125965, 'zhTW', '對呀，我好興奮啊！我好想看看爆炸的樣子！', '', 25549),
(125964, 'zhTW', '那裡！殺了它們，別讓它們召喚更多惡魔！', '', 25549),
(125963, 'zhTW', '來點特別奇怪的吧！', '', 25549),
(125962, 'zhTW', '正在拾取', '正在拾取', 25549),
(125957, 'zhTW', '我用聚源虹膜把法力還回去了。艾澤拉斯的地脈應該能回復原狀。', '', 25549),
(125956, 'zhTW', '', '結束這場鬧劇！', 25549),
(125955, 'zhTW', '', '魚有晚餐吃了！', 25549),
(125954, 'zhTW', '', '聽從大海的呼喚！', 25549),
(125953, 'zhTW', '', '海潮會吞沒你！', 25549),
(125952, 'zhTW', '', '海底也是有風暴的…', 25549),
(125951, 'zhTW', '', '把骨頭啃乾淨！', 25549),
(125950, 'zhTW', '', '要是你乖乖把潮石交出來，或許可以不用死…', 25549),
(125949, 'zhTW', '', '女王命令我掌管整片大海！', 25549),
(125948, 'zhTW', '', '面對翻湧海潮的力量！', 25549),
(125947, 'zhTW', '', '我讓女王…失望了…', 25549),
(125945, 'zhTW', '', '拉桑的騎士起飛了。你可以召喚他的戰鷹來幫忙防守雷霆圖騰！', 25549),
(125944, 'zhTW', '沒錯，瓊安娜，還好有這位勇士。', '', 25549),
(125943, 'zhTW', '', '…而且你的內心不再黑暗了！', 25549),
(125942, 'zhTW', '', '大法師賽倫！你回來了…', 25549),
(125941, 'zhTW', '帶我飛往破碎海岸！', '帶我飛往破碎海岸！', 25549),
(125940, 'zhTW', '', '希望它…炸得你滿臉…', 25549),
(125930, 'zhTW', '我先去偵察魔化圖騰。等你準備好就把圖騰帶來給我。', '', 25549),
(125926, 'zhTW', '', '費倫在我們被炸飛之前把大家送到了安全地點。卡魯歐就沒這麼幸運了。', 25549),
(125925, 'zhTW', '', '你醒了！我還擔心爆炸讓你長眠了呢。', 25549),
(125924, 'zhTW', '不能讓黑暗控制我！', '', 25549),
(125923, 'zhTW', '我會治療你的傷口。永遠記得追尋聖光。', '', 25549),
(125922, 'zhTW', '唉…好吧。', '唉…好吧。', 25549),
(125921, 'zhTW', '哈哈哈！什麼螃蟹！顯然你根本不懂惡魔！快快，我們來修練吧，侍從的教育不能等！', '', 25549),
(125920, 'zhTW', '呃，我只看到兩隻死螃蟹。這就是你說的惡魔屍體？', '呃，我只看到兩隻死螃蟹。這就是你說的惡魔屍體？', 25549),
(125919, 'zhTW', '侍從，沒錯！正如你所見，我攻上海岸，從燃燒軍團手裡搶回海灘，但還有好多事要做。昨晚它們想破壞防線，被我擋下來了。你看，那裡還有惡魔的屍體，別看太久，我怕嚇到你。', '', 25549),
(125918, 'zhTW', '修練？', '修練？', 25549),
(125917, 'zhTW', '侍從？是你嗎？天啊，我都快認不出你了，你老好多！不過沒差，就算老了還是得繼續修練！', '', 25549),
(125916, 'zhTW', '我準備好要離開了。', '我準備好要離開了。', 25549),
(125915, 'zhTW', '瑪克西米利安，你好呀。', '瑪克西米利安，你好呀。', 25549),
(125914, 'zhTW', '', '主人，注意安全！', 25549),
(125913, 'zhTW', '', '如果你想摧毀船艦，超載發電機可以對引擎造成嚴重傷害。', 25549),
(125912, 'zhTW', '%s昏倒在地上了！', '%s昏倒在地上了！', 25549),
(125911, 'zhTW', '', '覆寫完成。主人，我還順便為你解鎖了引擎室。', 25549),
(125910, 'zhTW', '他想讓自己的力量超載！小心！', '', 25549),
(125909, 'zhTW', '見識卡魯歐的怒火！', '', 25549),
(125908, 'zhTW', '放馬過來。你們活不了多久了。', '', 25549),
(125907, 'zhTW', '', '請稍待片刻，讓我解除防禦系統…', 25549),
(125906, 'zhTW', '', '沒問題。為了你什麼都行，梅菲斯托大人，務必讓你滿意。', 25549),
(125905, 'zhTW', '這…不…可能！', '', 25549),
(125904, 'zhTW', '你的聖光消散了，預言者。受死吧。', '', 25549),
(125903, 'zhTW', '我的屏障快撐不住了。趕快做個了結！', '', 25549),
(125902, 'zhTW', '你想來拿韁繩？哈！那就試試看！', '', 25549),
(125901, 'zhTW', '沒錯，那樣會讓我非常滿意。就這麼做吧。', '沒錯，那樣會讓我非常滿意。就這麼做吧。', 25549),
(125900, 'zhTW', '', '我們…絕不…屈服！', 25549),
(125899, 'zhTW', '', '如果我解除這艘船上所有的應急與防禦系統，我的黑暗領主會感到滿意嗎？', 25549),
(125898, 'zhTW', '我們力量無限，數量更是無窮無盡。在燃燒軍團的面前屈服吧！', '', 25549),
(125897, 'zhTW', '', '梅菲斯托大人，如你所知，這艘船艦為了應付嚴重失靈的狀況，配備了各種防禦系統。', 25549),
(125896, 'zhTW', '哈！只剩下你們了。你們必死無疑，蠢貨。', '', 25549),
(125895, 'zhTW', '哈囉！歡迎，疲倦的旅人，快來我的營火旁坐下吧。別擔心，這海岸有我在，已經安全了，燃燒軍團的威脅很快就結束了！', '', 25549),
(125894, 'zhTW', '堅持下去，勇士。不要放棄！', '', 25549),
(125893, 'zhTW', '', '啊啊啊！', 25549),
(125892, 'zhTW', '孤立無援的是你，卡魯歐！你的死期到了。', '', 25549),
(125891, 'zhTW', '我會粉碎你們的世界。', '', 25549),
(125890, 'zhTW', '沒有人會來救你。', '', 25549),
(125889, 'zhTW', '韁繩…', '', 25549),
(125888, 'zhTW', '吃掉他們，快！', '', 25549),
(125887, 'zhTW', '', '薩格拉斯，惡魔與獄火之神，在提克迪奧斯敗給伊利丹·怒風的這個奇恥大辱後，欽點你來領導納斯雷茲姆。', 25549),
(125886, 'zhTW', '', '沒問題，主人。你是梅菲斯托，是最強、最有智慧的納斯雷茲姆。', 25549),
(125885, 'zhTW', '好，帶我回去吧。', '好，帶我回去吧。', 25549),
(125884, 'zhTW', '我可以把你送回蒼穹殿。你想回去嗎？', '我可以把你送回蒼穹殿。你想回去嗎？', 25549),
(125883, 'zhTW', '', '你想讓我在這裡凍死嗎？哈哈，別傻了。趕快走吧！', 25549),
(125882, 'zhTW', '我只要用一點點力量，就能消滅你們。', '', 25549),
(125881, 'zhTW', '', '讓我們帶你去不死的國度！', 25549),
(125880, 'zhTW', '', '來吧，我們去收拾他！', 25549),
(125879, 'zhTW', '', '抱歉弄得一團亂。統領以為光靠寵物就能拖住我。', 25549),
(125878, 'zhTW', '大法師，你做得很好。不過你下一個要對抗的對象，可能沒那麼容易解決。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125877, 'zhTW', '傲慢的笨蛋！我已經吸收了無數靈魂的力量！', '', 25549),
(125876, 'zhTW', '', '大法師，我有新鮮的食物和繃帶，有需要就來找我。', 25549),
(125875, 'zhTW', '', '大法師，我有一些你可能用得上的球體，有需要就來找我。', 25549),
(125874, 'zhTW', '大法師，如果你需要修理裝備，我會為你服務。', '', 25549),
(125873, 'zhTW', '也許斯寇瓦德的血脈未絕。', '', 25549),
(125872, 'zhTW', '', '按照你的要求，我現在可以在一般程式設定之外提供各式服務，滿足主人的更多需求。', 25549),
(125871, 'zhTW', '', '我的標準程式設定經過修改，才能更加符合梅菲斯托大人的所有需求。', 25549),
(125870, 'zhTW', '', '沒問題，梅菲斯托大人。請稍待片刻，等我存取你上一次的使用者設定…', 25549),
(125869, 'zhTW', '我們準備好要離開了。', '我們準備好要離開了。', 25549),
(125868, 'zhTW', '我需要摧毀這艘船艦，你有好主意嗎？', '我需要摧毀這艘船艦，你有好主意嗎？', 25549),
(125867, 'zhTW', '你能告訴我我是誰嗎？誰是梅菲斯托領主？', '你能告訴我我是誰嗎？誰是梅菲斯托領主？', 25549),
(125866, 'zhTW', 'S.I.R.I.，告訴我你原先的設定。', 'S.I.R.I.，告訴我你原先的設定。', 25549),
(125865, 'zhTW', '感謝你解除玄鴉的詛咒。', '', 25549),
(125864, 'zhTW', '今天你做得很好。謝謝你。我們該回去了。', '', 25549),
(125862, 'zhTW', '正在掃描對手的帥氣等級。帥氣等級為零。', '', 25549),
(125861, 'zhTW', '你的放克等級不足。', '', 25549),
(125860, 'zhTW', '勇士，我們跟隨你。', '', 25549),
(125859, 'zhTW', '這件事，我們要攜手合作。', '', 25549),
(125858, 'zhTW', '你的節奏感真差。', '', 25549),
(125857, 'zhTW', '舞步亂七八糟。', '', 25549),
(125856, 'zhTW', '無聊。', '', 25549),
(125855, 'zhTW', '重新啟動放克驅動裝置。節奏協定設定為打臉。', '', 25549),
(125854, 'zhTW', '節奏能量電源關閉。垃圾話模式啟動。', '', 25549),
(125853, 'zhTW', '放克迴路已耗盡…', '', 25549),
(125852, 'zhTW', '你真行！', '你真行！', 25549),
(125851, 'zhTW', '你要被打敗了，音霸機器人！', '你要被打敗了，音霸機器人！', 25549),
(125850, 'zhTW', '看看那超級放克的舞步！', '看看那超級放克的舞步！', 25549),
(125849, 'zhTW', '你好，請準備好在強力節奏中被大卸八塊！', '', 25549),
(125848, 'zhTW', '做得好。我們現在要直搗黃龍，進入扭曲虛空。', '', 25549),
(125847, 'zhTW', '大德魯伊！用你的魔法把傳送門永遠關閉！', '', 25549),
(125846, 'zhTW', '我們得關閉傳送門！', '', 25549),
(125844, 'zhTW', '感受我軍隊的憤怒！', '', 25549),
(125843, 'zhTW', '', '存取成功。你好，梅菲斯托大人。我今天能幫你做什麼？', 25549),
(125842, 'zhTW', '來點奇怪的吧！', '', 25549),
(125841, 'zhTW', '', '偵測到能源中斷…執行系統恢復…', 25549),
(125840, 'zhTW', '', '惡意自動施虐助理系統，別名「瑪丹」，啟動完畢。你好啊，使用者。', 25549),
(125839, 'zhTW', '你們這是在找死。', '', 25549),
(125838, 'zhTW', '我開始不耐煩了。死吧，蟲子！', '', 25549),
(125837, 'zhTW', '你們都會死在主人的怒火之下。', '', 25549),
(125836, 'zhTW', '無窮無盡的火焰吞噬你們！去死吧！', '', 25549),
(125835, 'zhTW', '', '站住！是誰想靠近埃伊爾之殿？', 25549),
(125834, 'zhTW', '為了卡魯歐！為了燃燒軍團！', '', 25549),
(125833, 'zhTW', '', '我…是我把毒酒帶來這裡的。如果我先檢查過，就不會…', 25549),
(125832, 'zhTW', '白蘭琪！這是怎麼回事！大家都快死了！', '', 25549),
(125831, 'zhTW', '', '我趕來警告大家，但還是太遲了…', 25549),
(125830, 'zhTW', '', '釀酒大師？你想殺了我們！', 25549),
(125829, 'zhTW', '', '我一直對織霧很有興趣！再見了，釀酒大師。', 25549),
(125828, 'zhTW', '這些學徒在必要的時候可以幫忙。建議你多注意他們能提供的協助。', '', 25549),
(125827, 'zhTW', '安東尼達斯原本打算自己完成這個任務。他有耐心、有智慧，而且是法術大師。你必須證明你比他還強，才能貫徹他的意志。', '', 25549),
(125826, 'zhTW', '我先解除抑制稜碟的結界。我想如果透過神兵武器把力量傳進稜碟，應該會有反應。', '', 25549),
(125825, 'zhTW', '你們就只有這點戰力？還真可憐。', '', 25549),
(125824, 'zhTW', '安東尼達斯在稜碟裡灌注的能量，是我們一直想掌控的。但是，他和其他大法師都沒有辦法控制這麼強的能量，只好先按兵不動。', '', 25549),
(125823, 'zhTW', '', '你有看到釀酒大師嗎？', 25549),
(125822, 'zhTW', '', '我們好像喝太多了…等酒力消退會很難過的！至少現在關閉傳送門易如反掌！', 25549),
(125821, 'zhTW', '', '潮石是我們的！', 25549),
(125820, 'zhTW', '你會死在這裡！', '', 25549),
(125819, 'zhTW', '', '快成功了！堅持下去！', 25549),
(125818, 'zhTW', '', '小心！敵人又來了！', 25549),
(125817, 'zhTW', '', '你們偉大的自然之力是對抗不了惡魔的！', 25549),
(125816, 'zhTW', '', '卡魯歐會復活的！', 25549),
(125815, 'zhTW', '', '傳送門完成了。我來幫你了！', 25549),
(125814, 'zhTW', '瓦肅恩，殺死他們。我就快要重生了。', '', 25549),
(125813, 'zhTW', '我們要趕快擊敗指揮官，部隊快撐不住了！', '', 25549),
(125811, 'zhTW', '', '跟我們一起飛。穩定又快速！', 25549),
(125810, 'zhTW', '我的力量越來越強了。你們都得死！', '', 25549),
(125809, 'zhTW', '', '變異孢子就在這個峭壁的最上處。你必須一路戰鬥上去，祝你好運！', 25549),
(125808, 'zhTW', '末日使者打開了虛空裂隙！', '末日使者打開了虛空裂隙！', 25549),
(125807, 'zhTW', '', '再用神聖法術試試看，通常會很有效。', 25549),
(125806, 'zhTW', '', '在你被摧毀之後，如果你願意填寫一份簡短的問卷，就可以讓我們在未來為你提供更完善的協助。', 25549),
(125805, 'zhTW', '', '密碼錯誤。請稍候，警衛將立刻趕往您目前所在位置。', 25549),
(125803, 'zhTW', '', '這邊走，大德魯伊。她就在那座島上！', 25549),
(125802, 'zhTW', '這個維酷人是神御之王的繼承人。她想要見埃伊爾。', '這個維酷人是神御之王的繼承人。她想要見埃伊爾。', 25549),
(125801, 'zhTW', '', '大德魯伊，這裡！我們找到她了！', 25549),
(125800, 'zhTW', '', '你為什麼會回到斯寇亞胥，外來者？\n\n…跟你一起的維酷人是誰？', 25549),
(125799, 'zhTW', '朝主營進攻！', '', 25549),
(125798, 'zhTW', '$ct，側翼就交給我們吧！', '', 25549),
(125797, 'zhTW', '算了。再見！', '', 25549),
(125796, 'zhTW', '哼。什麼也想不出來。', '', 25549),
(125795, 'zhTW', '你們竟敢妄想踏入我的世界？那就來吧。', '', 25549),
(125794, 'zhTW', '呃…這比想像中的困難！你以前試過馬上就講出一句很棒的口號嗎？', '', 25549),
(125793, 'zhTW', '呃…等等。我在離開之前應該講點很酷的台詞。', '', 25549),
(125792, 'zhTW', '聽好。不管這場混亂誰造成的，就給你處理了。我要拍拍屁股閃人了。', '', 25549),
(125791, 'zhTW', '嘴巴要是有傷口，就很難大口吃肉。你懂我的意思嗎？', '', 25549),
(125790, 'zhTW', '我算不上什麼戰士。', '', 25549),
(125789, 'zhTW', '竟然吵我睡午覺。', '', 25549),
(125788, 'zhTW', '你不應該嚇人的。', '', 25549),
(125787, 'zhTW', '嘿！幹嘛！', '', 25549),
(125786, 'zhTW', '大德魯伊，協助我的部隊。我會找出它們的指揮官。', '', 25549),
(125785, 'zhTW', '我的部隊把燃燒軍團逼退到它們的據點，但是又憑空出現更多的惡魔。', '', 25549),
(125784, 'zhTW', '惡魔在破碎海岸肆虐了這麼久，也該到此為止了。', '', 25549),
(125783, 'zhTW', '', '愛瑪伊，你的戰鬥技巧變好了。我想你已經不再是個一般的釀酒師了。', 25549),
(125782, 'zhTW', '', '釀酒大師，很抱歉打擾到你！我會立刻讓大家返回工作崗位。', 25549),
(125781, 'zhTW', '', '宗師，我真是感激不盡。', 25549),
(125780, 'zhTW', '', '敵人來了！', 25549),
(125779, 'zhTW', '', '保持警戒。敵人很快就會再來。', 25549),
(125778, 'zhTW', '我們會…繼續反抗…', '我們會…繼續反抗…', 25549),
(125777, 'zhTW', '至少…我自由了…', '至少…我自由了…', 25549),
(125776, 'zhTW', '我為蘇拉瑪爾…而死。', '我為蘇拉瑪爾…而死。', 25549),
(125775, 'zhTW', '我要收服全部的寶貝！', '', 25549),
(125774, 'zhTW', '我們開始吧。', '我們開始吧。', 25549),
(125773, 'zhTW', '', '就算拼了命也要阻止燃燒軍團。', 25549),
(125772, 'zhTW', '', '站上去！快！', 25549),
(125771, 'zhTW', '', '釀酒大師！撐住！我們來了！', 25549),
(125770, 'zhTW', '我有好消息，也有壞消息。\n\n好消息是，我們可以使用這個傳送門進入我建立過連結的惡魔通道。\n\n壞消息是，我們不知道門的另一邊有什麼，因為魔法就是辦不到這一點。\n\n所以，你先請。祝你好運，「英雄」。', '', 25549),
(125769, 'zhTW', '選項3：用你的神兵武器砍電腦。', '選項3：用你的神兵武器砍電腦。', 25549),
(125768, 'zhTW', '選項2：對電腦發洩你滿腔的挫折，用力對它踢個不停。', '選項2：對電腦發洩你滿腔的挫折，用力對它踢個不停。', 25549),
(125767, 'zhTW', '選項1：拔起電腦的電源插頭，再插回去。', '選項1：拔起電腦的電源插頭，再插回去。', 25549),
(125766, 'zhTW', '輸入密碼：「霉非嘶拖大仁豪厲害」。', '輸入密碼：「霉非嘶拖大仁豪厲害」。', 25549),
(125765, 'zhTW', '輸入密碼：「密碼」。', '輸入密碼：「密碼」。', 25549),
(125764, 'zhTW', '輸入密碼：「燒光所有世界」。', '輸入密碼：「燒光所有世界」。', 25549),
(125763, 'zhTW', '朝勝利邁進！', '朝勝利邁進！', 25549),
(125762, 'zhTW', '卡魯歐的手下一定會衝上來保護他，祝你好運。', '', 25549),
(125761, 'zhTW', '博學者和她嘍囉一定會倒下！', '博學者和她嘍囉一定會倒下！', 25549),
(125760, 'zhTW', '我的家人需要我。謝謝你，英雄！', '我的家人需要我。謝謝你，英雄！', 25549),
(125759, 'zhTW', '', '在斯鐸海姆旅行時要格外小心。身為斯寇瓦德的女兒，我的敵人不少。', 25549),
(125758, 'zhTW', '', '接下來我會自己走。再會了，外來者。', 25549),
(125757, 'zhTW', '', '我傷得…太嚴重…', 25549),
(125756, 'zhTW', '', '諸神在對我微笑！', 25549),
(125755, 'zhTW', '', '這有風險，但只要一小口就能提高我們的戰力。乾杯！', 25549),
(125754, 'zhTW', '', '我從來沒看過那麼多惡魔！看來我們只能靠風暴蜜酒了。', 25549),
(125753, 'zhTW', '', '你會死在我的長矛底下！', 25549),
(125752, 'zhTW', '', '好，曦格琳，站起來！今天開始，你就是蔑潮的神御女王！', 25549),
(125751, 'zhTW', '', '我…我會的。就算要犧牲生命，也要再次統一蔑潮，然後把燃燒軍團從這裡趕出去！', 25549),
(125750, 'zhTW', '', '你能放下疑慮，為族人完成該做的事嗎？', 25549),
(125749, 'zhTW', '', '我終於知道我所預見的是真的了。你注定要團結蔑潮，對付燃燒軍團。', 25549),
(125748, 'zhTW', '', '你已經證明自己有克服惡魔的力量和意志…其他維酷人都做不到這件事！', 25549),
(125747, 'zhTW', '', '什麼？我犯了那麼多過錯，根本不配統領我們的族人！', 25549),
(125746, 'zhTW', '', '幸好你回來了。仔細聽好：你必須擔起統御眾人的責任。我現在宣佈你就是神御女王！', 25549),
(125745, 'zhTW', '', '我願意接受你的正義裁決。', 25549),
(125744, 'zhTW', '', '神聖的埃伊爾。我到這裡謙卑地請求你原諒我的作為。', 25549),
(125743, 'zhTW', '', '原諒我，埃伊爾…', 25549),
(125742, 'zhTW', '', '不…我絕不讓惡魔…控制我！', 25549),
(125741, 'zhTW', '', '曦格琳，復仇無濟於事，你的族人需要領袖。你死了，蔑潮不就完了嗎？', 25549),
(125740, 'zhTW', '', '可是…母親…我要為你報仇！', 25549),
(125739, 'zhTW', '', '曦格琳，你一定要克服黑暗！我相信你做得到！', 25549),
(125738, 'zhTW', '', '我…我在做什麼？這樣不對！', 25549),
(125737, 'zhTW', '', '好，你選擇死亡！', 25549),
(125736, 'zhTW', '', '我讓你選擇…離開這裡，否則就死。', 25549),
(125735, 'zhTW', '', '這是怎樣？外來者想阻止我？我欠你很多，但我不能容許你阻止我尋求正義！', 25549),
(125734, 'zhTW', '', '歐丁，你別想永遠躲在英靈殿裡！', 25549),
(125733, 'zhTW', '', '我只能暫時開啟傳送門。如果還需要使用，就得尋找其他的能量。', 25549),
(125732, 'zhTW', '', '曦格琳…你做了什麼？', 25549),
(125731, 'zhTW', '', '母親！我來為你報仇！', 25549),
(125730, 'zhTW', '', '我要讓歐丁見識真正的恐懼，就算必須拆掉英靈殿也在所不惜！', 25549),
(125729, 'zhTW', '', '曦格琳！不！別讓黑暗控制你！', 25549),
(125728, 'zhTW', '', '我弟弟是對的！泰坦看守者跟燃燒軍團一樣毫無榮譽可言！', 25549),
(125727, 'zhTW', '', '所以他決定讓斯寇瓦德的血脈…就此斷絕。', 25549),
(125726, 'zhTW', '', '歐丁一直擔心神御之王的子嗣會把蔑潮拱手讓給燃燒軍團。', 25549),
(125725, 'zhTW', '', '什麼？！', 25549),
(125724, 'zhTW', '', '好吧。下令殺了斯寇瓦德全家的人，就是歐丁。', 25549),
(125723, 'zhTW', '', '我想。', 25549),
(125722, 'zhTW', '', '噢，孩子…有些事不要知道比較好。你真的想知道嗎？', 25549),
(125721, 'zhTW', '', '告訴我…是誰下令殺死我母親？', 25549),
(125720, 'zhTW', '', '那就問吧，孩子。', 25549),
(125719, 'zhTW', '', '不過，在我正式成為女王之前，我想問你一件事。', 25549),
(125718, 'zhTW', '', '偉大的埃伊爾，如你所願，我已經擊敗所有想取得蔑潮統治權的挑戰者。', 25549),
(125717, 'zhTW', '這是真的…卡魯歐回來了。', '', 25549),
(125716, 'zhTW', '', '他…走了…', 25549),
(125715, 'zhTW', '', '不！弟弟！', 25549),
(125714, 'zhTW', '到時候…你就會懂…', '', 25549),
(125713, 'zhTW', '或許你該問問他們，那一晚的刺客是誰派來的…', '', 25549),
(125712, 'zhTW', '你…你以為你的主人才代表正義…', '', 25549),
(125711, 'zhTW', '', '對不起，弟弟。我不能讓燃燒軍團腐化維酷人。', 25549),
(125710, 'zhTW', '不…不可能的…', '', 25549),
(125709, 'zhTW', '', '不！我不要跟你一樣！', 25549),
(125708, 'zhTW', '屈服吧，姊姊！只有靠惡魔的力量才能打敗我！', '', 25549),
(125707, 'zhTW', '可憐的姊姊…要是不加入，你就是我的敵人！', '', 25549),
(125706, 'zhTW', '', '不，我不當燃燒軍團的工具！', 25549),
(125705, 'zhTW', '我們的血液會抵抗它產生的影響…可是它還留在體內。你只要向它屈服就行了！', '', 25549),
(125704, 'zhTW', '看來你不記得父親用魔化之血餵養過我們。這種血帶來的痛苦讓你不願去面對。', '', 25549),
(125703, 'zhTW', '', '喔不，特沃德…你向魔能屈服了！怎麼會這樣？', 25549),
(125702, 'zhTW', '怎麼打贏的？我接受了父親留下的禮物！就是你和母親極力拒絕的禮物！', '', 25549),
(125701, 'zhTW', '', '特沃德，真的是你！我不是故意要丟下你的，我那時候太弱了！你是怎麼打贏刺客的？', 25549),
(125700, 'zhTW', '姊姊…自從你丟下我等死，已經過了好久。', '', 25549),
(125699, 'zhTW', '', '把握時間，前往弗瑞科！', 25549),
(125698, 'zhTW', '', '你聽到了嗎？我們最好去外面看看！', 25549),
(125697, 'zhTW', '德雷克雅會支持你掌權。不過，你要擔心的還另有其人。', '', 25549),
(125696, 'zhTW', '等等！你已經證明自己的力量！我輸了。', '', 25549),
(125695, 'zhTW', '德雷克雅絕不投降！', '', 25549),
(125694, 'zhTW', '就算你是歐丁的親生女兒，我也不在乎。我要你為傲慢付出代價！', '', 25549),
(125693, 'zhTW', '', '你願意投降嗎？', 25549),
(125692, 'zhTW', '', '維伯蘭德統領！身為斯寇瓦德的後裔，奉埃伊爾之名，我擁有蔑潮的統治權！', 25549),
(125691, 'zhTW', '', '我會繼續前往赫德夏爾。我們到那裡見。', 25549),
(125690, 'zhTW', '我輸了。看來是我低估你了，女盾侍。', '', 25549),
(125689, 'zhTW', '放下武器！', '', 25549),
(125688, 'zhTW', '', '少廢話，符文先知！', 25549),
(125687, 'zhTW', '你繼承了父親的憤怒，女盾侍，但我也在你身上感覺到他的黑暗面。', '', 25549),
(125686, 'zhTW', '祖先們，幫助我！', '', 25549),
(125685, 'zhTW', '神御之王的兔崽子要來完成他的遺願嗎？斯寇瓦德的時代結束了，小女孩，你也馬上就會完蛋！', '', 25549),
(125684, 'zhTW', '', '符文先知法爾加！我是斯寇瓦德的女兒曦格琳。奉華爾琪拉之名，我要挑戰你統治蔑潮的權力！', 25549),
(125683, 'zhTW', '', '我會先去豪斯特沃。如果你能跟我會合，那就太好了。', 25549),
(125682, 'zhTW', '', '我會聽從你的指示。告訴我該怎麼做。', 25549),
(125681, 'zhTW', '', '好吧。如果我對蔑潮真的這麼重要，就不能拒絕這個任務。', 25549),
(125680, 'zhTW', '', '孩子，我知道這是個沉重的負擔，但你是我們唯一的希望了。', 25549),
(125679, 'zhTW', '', '失敗，蔑潮就會分裂，這樣一來就無法阻止燃燒軍團佔領斯鐸海姆了。', 25549),
(125678, 'zhTW', '', '身為斯寇瓦德的子嗣，你有權要求繼承王位。如果有人敢挑戰你，就讓他屈服吧。', 25549),
(125677, 'zhTW', '', '外來者說的沒錯。很久以前我就預見有位華爾琪拉聯合蔑潮的力量對付可怕的敵人。幻象中的領袖是神御之王的後裔，一位女盾侍。', 25549),
(125676, 'zhTW', '', '這個外來者說，我會團結蔑潮…', 25549),
(125675, 'zhTW', '', '斯寇瓦德的後裔回到華爾琪拉了？孩子，你知道這代表什麼嗎？', 25549),
(125674, 'zhTW', '', '大宗師埃伊爾，預言之子出現了！', 25549),
(125673, 'zhTW', '', '等等…那長相…跟我來，孩子！', 25549),
(125672, 'zhTW', '', '神御之王的後代？這太荒謬了吧？', 25549),
(125671, 'zhTW', '', '這些女人穿戴的護甲…讓我想起母親…', 25549),
(125670, 'zhTW', '', '斯寇亞胥！在我小時候，母親說過這裡的故事，還有強大的女盾侍。這個地方就跟她說的一樣壯觀！', 25549),
(125669, 'zhTW', '所以，保險起見，我不會提起神御之王是怎麼死的。', '', 25549),
(125668, 'zhTW', '啊，還有一件事。這個預言中的領導者如果真的是神御之王的後代，提到斯寇瓦德的死因可能會引發爭執。', '', 25549),
(125667, 'zhTW', '<冰冷的指揮臺就在前方。惡魔符文隱隱發光，在螢幕上閃爍。>\n\n密碼正確。', '', 25549),
(125666, 'zhTW', '<指揮臺就在前方。惡魔符文隱隱發光，在螢幕上閃爍。>\n\n請輸入密碼：', '', 25549),
(125664, 'zhTW', '', '最後一扇！快！', 25549),
(125663, 'zhTW', '', '這裡！我們得打開這扇門。', 25549),
(125662, 'zhTW', '', '到處都找不到釀酒大師。她已經安全脫困了嗎？', 25549),
(125661, 'zhTW', '', '他在那裡！', 25549),
(125660, 'zhTW', '你可憐的世界馬上就會嘗到卡魯歐的怒火！', '', 25549),
(125659, 'zhTW', '哈？我為什麼要躲？預言者，你老糊塗了。', '', 25549),
(125658, 'zhTW', '戰士，看來命運又讓我們相遇了。', '', 25549),
(125657, 'zhTW', '術士，看來命運又讓我們相遇了。', '', 25549),
(125656, 'zhTW', '薩滿，看來命運又讓我們相遇了。', '', 25549),
(125655, 'zhTW', '盜賊，看來命運又讓我們相遇了。', '', 25549),
(125654, 'zhTW', '大祭司，看來命運又讓我們相遇了。', '', 25549),
(125653, 'zhTW', '大領主，看來命運又讓我們相遇了。', '', 25549),
(125652, 'zhTW', '武僧，看來命運又讓我們相遇了。', '', 25549),
(125651, 'zhTW', '法師，看來命運又讓我們相遇了。', '', 25549),
(125650, 'zhTW', '獵人，看來命運又讓我們相遇了。', '', 25549),
(125649, 'zhTW', '德魯伊，看來命運又讓我們相遇了。', '', 25549),
(125648, 'zhTW', '惡魔獵人，看來命運又讓我們相遇了。', '', 25549),
(125647, 'zhTW', '死亡騎士，看來命運又讓我們相遇了。', '', 25549),
(125646, 'zhTW', '英雄，做得好！你救了許多高貴的靈魂，這樣燃燒軍團就不能再利用它們了。', '', 25549),
(125645, 'zhTW', '燃燒軍團在侵略斯鐸海姆的海岸！殺光所有惡魔！', '', 25549),
(125644, 'zhTW', '莫古力思停頓了一下，一面看著你，一面露出稍縱即逝、你只能猜想那是微笑的表情。', '', 25549),
(125643, 'zhTW', '呃啊…', '', 25549),
(125642, 'zhTW', '', '你覺得惡魔知道，它們喝了風暴蜜酒會怎麼樣嗎？', 25549),
(125641, 'zhTW', '', '我原本以為待在這裡會很安全。燃燒軍團到最近才發現我們。', 25549),
(125640, 'zhTW', '出來吧，惡魔。在聖光之下無處可躲！', '', 25549),
(125639, 'zhTW', '', '好多惡魔！', 25549),
(125638, 'zhTW', '我能感受到來自遠方的黑暗力量就在扭曲虛空中，我們來看看裡面到底藏了什麼。', '', 25549),
(125637, 'zhTW', '我想知道薩格拉斯之墓上方的虛空裡有什麼，我一直在尋找答案，卻連問題都不清楚。', '', 25549),
(125636, 'zhTW', '%s吸光了聚源虹膜的能量！你輸了！[PH]', '%s吸光了聚源虹膜的能量！你輸了！[PH]', 25549),
(125635, 'zhTW', '卡魯歐的心臟被燃燒軍團偷走了。', '卡魯歐的心臟被燃燒軍團偷走了。', 25549),
(125634, 'zhTW', '聖光不會背棄我們。', '', 25549),
(125633, 'zhTW', '你辦到了！我恢復了！', '', 25549),
(125632, 'zhTW', '我早就料到你會來了。你帶來的是壞消息。', '', 25549),
(125631, 'zhTW', '莫古力思指向南邊海岸的惡魔建築。', '', 25549),
(125630, 'zhTW', '嘎古嚕咕嚕古！', '', 25549),
(125629, 'zhTW', '這些生物會把你的靈魂撕成碎片！', '', 25549),
(125628, 'zhTW', '為什麼進度變慢了？！快把這些生物準備好，不要給我找藉口！', '', 25549),
(125627, 'zhTW', '', '快趁他出發前趕去平臺。走吧！', 25549),
(125626, 'zhTW', '', '預言者費倫一直在照顧傷者，我們可以先去「急救你優先」看看。', 25549),
(125625, 'zhTW', '', '他往卡薩斯平臺去了，喃喃自語地說什麼墓的。', 25549),
(125624, 'zhTW', '', '不好意思，預言者剛離開。', 25549),
(125623, 'zhTW', '', '本來就不該讓法師插手惡魔獵人的工作！', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125622, 'zhTW', '', '你已經毀了自己的世界，外來者。我不會讓你毀掉我的世界！', 25549),
(125621, 'zhTW', '', '嗯，那好像讓情況惡化了。改用暗影魔法試試看吧。', 25549),
(125620, 'zhTW', '謝謝你！我們去給那些惡魔好看吧！', '謝謝你！我們去給那些惡魔好看吧！', 25549),
(125619, 'zhTW', '謝謝你。我還以為燃燒軍團不會打到這裡來…', '謝謝你。我還以為燃燒軍團不會打到這裡來…', 25549),
(125618, 'zhTW', '朋友，祝福你！', '朋友，祝福你！', 25549),
(125617, 'zhTW', '呼，剛才好難過喔。謝謝你！', '呼，剛才好難過喔。謝謝你！', 25549),
(125616, 'zhTW', '莫古力思指著一條看起來不太健康的魚，然後看向你，似乎希望你拿那條魚做點什麼。', '', 25549),
(125615, 'zhTW', '', '糟了…卡魯歐大領主的心臟。', 25549),
(125614, 'zhTW', '莫咕嚕…咕嚕咕厄咕咕嚕嚕嗚嗚！', '', 25549),
(125613, 'zhTW', '', '附近可能還有惡魔，千萬別大意。', 25549),
(125612, 'zhTW', '', '%s獲得|cFFFF0404|Hspell:230981|h[分割之魂]|h|r的效果！', 25549),
(125611, 'zhTW', '剛剛那個傢伙拼命想保護這東西，一拿到就先溜了。', '', 25549),
(125610, 'zhTW', '那個東西長得像心臟。這樣說你有印象嗎？', '', 25549),
(125609, 'zhTW', '喂，快來，我剛剛看到惡魔拿走什麼了。', '', 25549),
(125608, 'zhTW', '', '我來告訴你燃燒軍團在找什麼 - 我的底線！親愛的，軍團級保護結界很貴的好嗎！', 25549),
(125607, 'zhTW', '一時恐怕無法確認，裡頭到處都是魔化烈焰！', '', 25549),
(125606, 'zhTW', '', '開口閉口都是保險庫，你關心過我們員工有沒有怎麼樣嗎？！除了六法議會的成員，通通不許進去！', 25549),
(125605, 'zhTW', '有什麼差別嗎？保險庫裡都是我們最珍貴的寶物！無論哪一個不見了後果都很嚴重！', '', 25549),
(125604, 'zhTW', '', '真可憐！化毒袪病應該可以治好他們。', 25549),
(125603, 'zhTW', '', '進去吧。', 25549),
(125602, 'zhTW', '', '宗師，謝謝你這麼快趕來。幫我打開這扇門！', 25549),
(125601, 'zhTW', '說吧，貪婪妮亞。燃燒軍團在找什麼？', '說吧，貪婪妮亞。燃燒軍團在找什麼？', 25549),
(125600, 'zhTW', '到底被搶走了什麼？', '到底被搶走了什麼？', 25549),
(125599, 'zhTW', '保險庫有沒有東西不見？', '保險庫有沒有東西不見？', 25549),
(125598, 'zhTW', '你知道被偷了什麼嗎？', '你知道被偷了什麼嗎？', 25549),
(125597, 'zhTW', '歡迎光臨。', '', 25549),
(125596, 'zhTW', '', '你好。', 25549),
(125595, 'zhTW', '有沒有什麼東西被偷了？', '有沒有什麼東西被偷了？', 25549),
(125594, 'zhTW', '我想看看銀行。', '我想看看銀行。', 25549),
(125593, 'zhTW', '有什麼事嗎？', '', 25549),
(125592, 'zhTW', '%s昏倒在地上了！', '', 25549),
(125591, 'zhTW', '姆咕嚕咕嚕！咕嚕莫咕嚕咕！', '', 25549),
(125590, 'zhTW', '嘎古咕嚕！', '', 25549),
(125589, 'zhTW', '', '希望這些武僧喜歡我的慶典佳釀！再見啦，宗師。', 25549),
(125588, 'zhTW', '姆咕嚕咕嚕！咕嚕莫咕嚕咕魯姆咕咕咕嚕！', '', 25549),
(125587, 'zhTW', '<<7.1 PTR>> Cheat me past all the 7.0 Nightfallen content! I want to test 7.1!', '<<7.1 PTR>> Cheat me past all the 7.0 Nightfallen content! I want to test 7.1!', 25549),
(125586, 'zhTW', '', '去死吧，外來者！', 25549),
(125585, 'zhTW', '這派得上用場！', '這派得上用場！', 25549),
(125584, 'zhTW', '淘氣的妖精恢復了真實的樣貌。', '', 25549),
(125583, 'zhTW', '麥迪文？是你嗎？', '麥迪文？是你嗎？', 25549),
(125582, 'zhTW', '前任守護者的幽靈在你上方盤旋。你覺得他好像在觀察你，希望得到你注意…', '前任守護者的幽靈在你上方盤旋。你覺得他好像在觀察你，希望得到你注意…', 25549),
(125581, 'zhTW', '英雄，謝謝你，我們必須維持和諧，才能生存下去。', '', 25549),
(125576, 'zhTW', '我們還需要更多酒桶。這東西不太穩定，普通的木桶恐怕撐不住。', '', 25549),
(125575, 'zhTW', '', '宗師！我們好好慶祝吧！', 25549),
(125574, 'zhTW', '$n宗師！我剛才跟釀酒大師白蘭琪討論破碎海岸的情勢。現在是集結艾澤拉斯的戰力，並且向燃燒軍團宣戰的時候了。', '', 25549),
(125572, 'zhTW', '我的氣息是狂怒的風暴！小傢伙，告訴我敵人在哪裡，我來幫你解決！', '', 25549),
(125571, 'zhTW', '那個惡魔要移動船艦攻擊英靈之門！我派了一個華爾琪協助你，英雄。一定要贏得這場戰鬥！', '', 25549),
(125570, 'zhTW', '我準備好把阿曼蘇爾之眼帶去達拉然了。', '我準備好把阿曼蘇爾之眼帶去達拉然了。', 25549),
(125569, 'zhTW', '艾澤拉斯的命運掌握在我們手中。', '', 25549),
(125568, 'zhTW', '', '$ct，你看起來很不安，有什麼問題嗎？', 25549),
(125567, 'zhTW', '帶我去風暴烈酒酒坊。', '帶我去風暴烈酒酒坊。', 25549),
(125566, 'zhTW', '', '謝謝。我們到那邊見！', 25549),
(125565, 'zhTW', '可惡！風暴蜜酒的生產線才剛起步而已！', '', 25549),
(125564, 'zhTW', '', '宗師！風暴烈酒酒坊受到燃燒軍團攻擊！請救救我們！', 25549),
(125563, 'zhTW', '', '準備好爪鉤，死亡領主，我們要爬到山頂上。', 25549),
(125562, 'zhTW', '', '以伊利丹之名，去死！', 25549),
(125561, 'zhTW', '', '銀行？怎麼會 - ', 25549),
(125560, 'zhTW', '我想去勇氣試煉(團隊)。', '我想去勇氣試煉(團隊)。', 25549),
(125559, 'zhTW', '把我傳送到破碎海岸。', '把我傳送到破碎海岸。', 25549),
(125558, 'zhTW', '<瑪洛尼用讚許的眼光看著你。>', '', 25549),
(125557, 'zhTW', '', '艾斯葛林姆！你這惡魔，你會為腐化付出代價！', 25549),
(125556, 'zhTW', '華爾琪，看看你們光榮的勇士！這場團聚一定會很動人…', '', 25549),
(125555, 'zhTW', '不過麻煩你…繼續垂死奮鬥。我喜歡看你們掙扎！', '', 25549),
(125554, 'zhTW', '可悲的凡人！連你的華爾琪都無法救你脫離毀滅的命運…', '', 25549),
(125553, 'zhTW', '你該立刻回到審判角。那裡出現了一些…怎麼說呢…新的發展。', '', 25549),
(125552, 'zhTW', '咕呀…', '咕呀…', 25549),
(125551, 'zhTW', '彌米倫，我想念哈提以前的樣子，你可以幫我換回來嗎？', '彌米倫，我想念哈提原本的樣子，可以換回去嗎？', 25549),
(125550, 'zhTW', '我要成為對戰大師！', '', 25549),
(125549, 'zhTW', '朋友，謝謝你！', '朋友，謝謝你！', 25549),
(125548, 'zhTW', '你逃不過毀滅！', '', 25549),
(125547, 'zhTW', '抵抗只是白費力氣！', '', 25549),
(125546, 'zhTW', '哈！盡管喊叫掙扎吧！讓你死前的怒吼響徹天空！', '', 25549),
(125545, 'zhTW', '他們總是好快就爆炸。', '', 25549),
(125544, 'zhTW', '哇，你整個爆炸了！', '', 25549),
(125543, 'zhTW', '這是主人的命令！', '', 25549),
(125542, 'zhTW', '血！到處都是血！', '', 25549),
(125541, 'zhTW', '抵抗…不了…', '', 25549),
(125540, 'zhTW', '怪物，到處都是怪物！', '', 25549),
(125539, 'zhTW', '祖先跟我說話了！他們說你必須死！', '', 25549),
(125538, 'zhTW', '這…這裡不是英靈殿！', '', 25549),
(125537, 'zhTW', '歐丁的鬍子啊…這是哪裡？', '', 25549),
(125536, 'zhTW', '謝謝你，小小的陌生人。', '', 25549),
(125535, 'zhTW', '詛咒這些惡魔！', '', 25549),
(125534, 'zhTW', '那些聲音…他們說謊！他們不是祖先！', '', 25549),
(125533, 'zhTW', '我自由了！', '', 25549),
(125532, 'zhTW', '我們先回我的塔裡。還有很多事要討論…', '', 25549),
(125531, 'zhTW', '…謝謝。謝謝你饒了我，英雄。我…失控了…', '', 25549),
(125530, 'zhTW', '糟了…地脈還太弱…沒有法力的話…艾澤拉斯就會…', '', 25549),
(125529, 'zhTW', '完成了。下一個目標是艾澤拉斯…', '', 25549),
(125528, 'zhTW', '看看什麼才叫無盡的力量！', '', 25549),
(125527, 'zhTW', '擋住他們！為了艾澤拉斯！', '', 25549),
(125526, 'zhTW', '你別想違抗燃燒軍團的意志，大法師。一切都會毀滅！', '', 25549),
(125525, 'zhTW', '我要用聚源虹膜把法力還回去！', '', 25549),
(125524, 'zhTW', '不…不能這樣！', '', 25549),
(125523, 'zhTW', '法力全都是我的！', '', 25549),
(125522, 'zhTW', '騙子，看我的！', '', 25549),
(125521, 'zhTW', '等我吸光你們世界的魔法，惡魔主人就會摧毀這個世界…到時候我會擁有無盡的力量！', '', 25549),
(125520, 'zhTW', '你太遲了！我已經拿到聚源虹膜，可以直接從艾澤拉斯的地脈吸取秘法能量，讓我變得更強大！', '', 25549),
(125519, 'zhTW', '帶我到破碎海岸的苦難之路。', '帶我到破碎海岸的苦難之路。', 25549),
(125518, 'zhTW', '傳送到深淵拱廊。', '傳送到深淵拱廊。', 25549),
(125517, 'zhTW', '傳送到宮殿中庭。', '傳送到宮殿中庭。', 25549),
(125516, 'zhTW', '享受爆炸性的樂趣吧！', '', 25549),
(125515, 'zhTW', '我有時候可是相當火爆的！', '', 25549),
(125514, 'zhTW', '帶著你所有的苦難…來我身邊！', '', 25549),
(125513, 'zhTW', '看來我得自己來了！', '看來我得自己來了！', 25549),
(125512, 'zhTW', '地上一有火就要閃的話，我的傷害怎麼可能打得高？', '', 25549),
(125511, 'zhTW', '我就是活在陰影裡。你問我為什麼？這是個人選擇，你不懂啦。', '', 25549),
(125510, 'zhTW', '我沒有被隊伍踢出來好嗎！是我不要他們，他們都遜斃了！', '', 25549),
(125509, 'zhTW', '你問我有什麼訣竅？去殺野豬，殺個十年，我都是這樣做的。你會變得很厲害…還能拿到上好的培根。', '', 25549),
(125508, 'zhTW', '你問我是不是一開始就打算殺掉那個獵人？沒有，我以為他只是假死，所以我才一直戳。誰知道他戳個兩下就死掉了！真遜。', '', 25549),
(125507, 'zhTW', '你要是惹毛我，怎麼死的都不知道。我讓你知道，你才會知道，你人生最後的畫面一定是我！', '', 25549),
(125506, 'zhTW', '你想知道我是什麼層級的？神級的，知道嗎？神級的。', '', 25549),
(125505, 'zhTW', '跟你說，活著就是要贏，贏到死！懂嗎？我就是這樣。', '', 25549),
(125504, 'zhTW', '喂，用過死亡謊言吧？你知道那招是我發明的嗎？', '', 25549),
(125503, 'zhTW', '…然後我說：「你看不到怎麼殺！」然後我就消失了！哈哈哈！你應該看看那個小朋友的表情。他差點連冰淇淋都掉了！', '', 25549),
(125502, 'zhTW', '…毒藥？幹嘛用藥，從背後上就好了啊！', '', 25549),
(125501, 'zhTW', '我之前退隊，因為他們都太遜了，每一個都遜！現在我重組一個新隊伍，這個隊伍很強，應該沒辦法讓你參加。總之幫我宣傳一下，知道嗎？', '', 25549),
(125500, 'zhTW', '死從天降？這招我用過1,979次啦！你想當第1,800次嗎？哼，諒你也不敢。', '', 25549),
(125499, 'zhTW', '…然後我就說：「這故事很酷，兄弟。」哈哈！', '', 25549),
(125498, 'zhTW', '羅索很樂意幫助朋友。你看，羅索不是壞惡魔！', '', 25549),
(125496, 'zhTW', '隱藏費羅米隆的烈焰之球', '隱藏費羅米隆的烈焰之球', 25549),
(125495, 'zhTW', '顯現費羅米隆的烈焰之球', '顯現費羅米隆的烈焰之球', 25549),
(125494, 'zhTW', '被時間困住了。$b$b你看，所以我才研究傳送術！時光法術太危險了。$b$b<歐庫雷斯沉默了一陣子。>$b$b他們有可能就這樣被困住了。永遠。我們必須阻止艾莉珊德！', '', 25549),
(125493, 'zhTW', '', '這就是夜井的力量…$b$b一定還有辦法，我們一定會想到辦法！', 25549),
(125492, 'zhTW', '', '艾莉珊德…你做了什麼？', 25549),
(125491, 'zhTW', '我還以為不可能！光是想到要用多少能量…', '', 25549),
(125490, 'zhTW', '離開副本會重置進度，確定要離開嗎？', '離開副本會重置進度，確定要離開嗎？', 25549),
(125489, 'zhTW', '我想離開哀嚎洞穴。', '我想離開哀嚎洞穴。', 25549),
(125488, 'zhTW', '帶我進入哀嚎洞穴。', '帶我進入哀嚎洞穴。', 25549),
(125487, 'zhTW', '', '哀嚎洞穴裡到處都是變異的生物。\n\n我們必須消滅這些生物，不能讓他們的數量繼續增加。', 25549),
(125486, 'zhTW', '只有受過充分訓練的人才能參加。\n\n當你把15隻寵物訓練到牠們的最高等級，就會被認為具備資格了。', '只有受過充分訓練的人才能參加。\n\n當你把15隻寵物訓練到牠們的最高等級，就會被認為具備資格了。', 25549),
(125485, 'zhTW', '參加條件是什麼？', '參加條件是什麼？', 25549),
(125482, 'zhTW', '馬上去那裡跟我的僕人，強大的維瑟碰頭。你們要讓燃燒軍團知道，斯鐸海姆會怎樣對待不速之客！', '', 25549),
(125481, 'zhTW', '英雄，艾蘇納的居民都欠你一命！', '', 25549),
(125480, 'zhTW', '', '或許吧。這個地點確實有些戰略優勢。', 25549),
(125479, 'zhTW', '派我上戰場，我準備好了。', '派我上戰場，我準備好了。', 25549),
(125478, 'zhTW', '為了對抗燃燒軍團，我們付出很高的代價。許多勇士因此犧牲生命。絕對不能讓這些人白白死去。\n\n我們不能浪費這個機會！', '', 25549),
(125477, 'zhTW', '', '我先把這裡收拾一下。待會見。', 25549),
(125476, 'zhTW', '', '嗯。看來才出油鍋又入火坑。至少這裡的位置比較適合對抗燃燒軍團。', 25549),
(125475, 'zhTW', '', '來看看我們到哪裡了，好嗎？', 25549),
(125474, 'zhTW', '諾丹尼爾之泉被燃燒軍團佔領了！快消滅這些惡魔，否則艾蘇納就會跟著淪陷！', '', 25549),
(125473, 'zhTW', '再次謝謝你，請幫我向祈倫托打個招呼！', '', 25549),
(125472, 'zhTW', '在把剩下的叛徒都趕走以前，還有很多事要做，幸好有你在，應該很快就能做好。', '', 25549),
(125471, 'zhTW', '我們已經重新獲得權限，可以控制大部分的核心系統，包括把你安全送回達拉然的傳送系統。', '', 25549),
(125470, 'zhTW', '你成功了！以後在這個城市不會看到希科‧瑟瑪普拉格的那顆醜頭了。', '', 25549),
(125469, 'zhTW', '你別想得逞！我可是有備而來！', '', 25549),
(125468, 'zhTW', '全部派出去！全部！你們這些蠢蛋快保護我！', '', 25549),
(125467, 'zhTW', '好極了！探測器顯示瑟瑪普拉格已經逃到樓下的大工匠殿堂。快乘勝追擊，解決瑟瑪普拉格！', '', 25549),
(125466, 'zhTW', '不！我的飛彈！！！', '', 25549),
(125465, 'zhTW', '你可以在完全附魔商店找到星移編織師圖維斯。', '你可以在完全附魔商店找到星移編織師圖維斯。', 25549),
(125464, 'zhTW', '夏多雷咒符充滿力量，宮殿的結界慢慢解除了。', '夏多雷咒符充滿力量，宮殿的結界慢慢解除了。', 25549),
(125463, 'zhTW', '放輕鬆，休息一下！根據我的計算，你們現在無論怎麼做都沒用了，好好準備等死吧。', '', 25549),
(125462, 'zhTW', '滴答，滴答，馬上就能發射啦！', '', 25549),
(125461, 'zhTW', '他們在這裡。', '', 25549),
(125460, 'zhTW', '以機電師領主之名，快停下來！', '', 25549),
(125459, 'zhTW', '準備開戰。', '', 25549),
(125458, 'zhTW', '發現目標。', '', 25549),
(125457, 'zhTW', '鎖定敵人。', '', 25549),
(125456, 'zhTW', '武器系統完成設定。', '', 25549),
(125455, 'zhTW', '本區發現侵略者。', '', 25549),
(125454, 'zhTW', '本區服從值過低，正在檢查問題來源。', '', 25549),
(125453, 'zhTW', '啟動威脅探測器。', '', 25549),
(125452, 'zhTW', '發現敵人。預備戰鬥迴圈。', '', 25549),
(125451, 'zhTW', '發現未授權人員。', '', 25549),
(125450, 'zhTW', '', '我們已經控制住場面了。斬魔者，請你去看看先知阿卡路的情況，好嗎？', 25549),
(125449, 'zhTW', '本區發現入侵者。', '', 25549),
(125448, 'zhTW', '機械齒狼看向你了！', '', 25549),
(125447, 'zhTW', '這裡有聲音。', '這裡有聲音。', 25549),
(125446, 'zhTW', '我不會讓你活著離開這裡。', '我不會讓你活著離開這裡。', 25549),
(125445, 'zhTW', '就拿你的頭來當大廳的裝飾吧！', '就拿你的頭來當大廳的裝飾吧！', 25549),
(125444, 'zhTW', '是誰闖進瑟瑪普拉格的地盤？', '是誰闖進瑟瑪普拉格的地盤？', 25549),
(125443, 'zhTW', '好像有其他人。', '好像有其他人。', 25549),
(125442, 'zhTW', '你剛剛看到了嗎？', '你剛剛看到了嗎？', 25549),
(125441, 'zhTW', '有人在附近。', '有人在附近。', 25549),
(125440, 'zhTW', '以瑟瑪普拉格之名，快出來！', '以瑟瑪普拉格之名，快出來！', 25549),
(125439, 'zhTW', '出來！讓我殺！', '', 25549),
(125438, 'zhTW', '那邊有啥？', '', 25549),
(125437, 'zhTW', '我看到啦！', '', 25549),
(125436, 'zhTW', '呃？剛剛是啥？', '', 25549),
(125435, 'zhTW', '快出來！', '', 25549),
(125434, 'zhTW', '穴居怪不笨！', '', 25549),
(125433, 'zhTW', '怎麼可能！我的計算這麼完美…', '', 25549),
(125432, 'zhTW', '這不算什麼，一切都很好，我可以做到的！只要把你殺了，把你弄壞的東西修一修，就可以把你那些可愛的朋友殺光光了。', '', 25549),
(125431, 'zhTW', '可惡，可惡，那該死的爆炸按鈕到底在哪？我明明記得我有裝啊！', '', 25549),
(125430, 'zhTW', '唉，想到你就快死了，一個人在這種地方等死…就像多年前的我一樣。', '', 25549),
(125429, 'zhTW', '高貴的英雄，加油，好嗎！我可是艾澤拉斯最偉大的發明家啊！', '', 25549),
(125428, 'zhTW', '看看這些盟友給我什麼力量！我是機電師領主瑟瑪普拉格，我就是你的末日！', '', 25549),
(125427, 'zhTW', '英雄，我很想為你鼓掌，但你真的是在浪費時間。我再造一個飛彈就好了啊，這次你絕對沒有辦法阻止我！', '', 25549),
(125426, 'zhTW', '', '他…就要來了…', 25549),
(125425, 'zhTW', '', '怎麼可能？你什麼也不是啊！', 25549),
(125424, 'zhTW', '', '你的世界、所有的世界都會燃燒！無法改變！', 25549),
(125423, 'zhTW', '', '你比我想的還要強，但這沒用的。', 25549),
(125422, 'zhTW', '', '別掙扎了。我們無所不在。我們是燃燒軍團！', 25549),
(125421, 'zhTW', '', '凡人，來不及了。艾澤拉斯的命運已定。', 25549),
(125420, 'zhTW', '', '小地精，你做得很好，馬上就不會有人能阻止偉大的燃燒軍團了！', 25549),
(125419, 'zhTW', '', '船艦的武器嚴重受損。如果現在啟動，可能連我們都會遭殃…如果從主要引擎核心引導能量…', 25549),
(125418, 'zhTW', '', '丹密爾，歡迎加入我們！死亡領主，上來吧，該回亞榭洛了。', 25549),
(125417, 'zhTW', '', '我們快要撐不住了。必須摧毀那些船艦！', 25549),
(125416, 'zhTW', '', '真不簡單，能夠抵抗夜井的誘惑很不容易。$b$b隨著時間過去，夜井的力量會漸漸消散。他們會像我們一樣，重新找到在世界上立足的方式。', 25549),
(125415, 'zhTW', '夜井…$b$b夜裔精靈在艾澤拉斯的歷史展開了新的一頁。現在夜裔精靈失去夜井和護盾，終於有空間生長、茁壯。我很期待他們接下來的表現。', '', 25549),
(125414, 'zhTW', '這才是正確的決定。$b$b這裡的力量太強大，包袱太沉重，連艾莉珊德都被摧毀了。我們應該放手。', '', 25549),
(125413, 'zhTW', '', '我永遠都會一直想，如果我們決定拯救夜井，會發生什麼事。沒有夜井的力量，我們又算什麼？$b$b無論如何，我相信薩莉瑟拉的決定。我知道她會帶領夜裔精靈走向新的命運。', 25549),
(125412, 'zhTW', '', '夜井沒了。$b$b夜裔精靈不能再依賴夜井的腐化能量了，必須想辦法活下去，否則就會從歷史中消失。希望他們能辦到。', 25549),
(125411, 'zhTW', '', '這是必須的。我們不需要夜井，不需要它的力量了。$b$b我們必須重新打造屬於自己的命運。', 25549),
(125410, 'zhTW', '真是困難重重！還好有你幫我。我擔心捷斯在控制房遇到麻煩了！', '', 25549),
(125409, 'zhTW', '', '馬爾頓失守，我覺得還不嚴重。要是連魔錘號都守不住可就大事不妙了。', 25549),
(125408, 'zhTW', '', '斬魔者$n，還好你趕回來了！它們這次是來真的！', 25549),
(125407, 'zhTW', '', '又有更多惡魔…雖然我確實希望船上多一點娛樂，但這跟我想像的不太一樣。', 25549),
(125406, 'zhTW', '', '魔錘號是我們的！去好好教訓一下這些惡魔！', 25549),
(125405, 'zhTW', '', '死亡領主，別想單獨挑戰索林姆之巔。前進！', 25549),
(125404, 'zhTW', '', '懷惡族母心懷惡念地瞪著珂娃絲。', 25549),
(125403, 'zhTW', '', '族母，我來了！', 25549),
(125402, 'zhTW', '我準備好了，歐庫雷斯。', '我準備好了，歐庫雷斯。', 25549),
(125401, 'zhTW', '呣咕！呣咕咕咕呣咕咕嚕！', '', 25549),
(125400, 'zhTW', '呣咕咕！呣咕咕咕！', '', 25549),
(125399, 'zhTW', '', '誰找到就是誰的！', 25549),
(125398, 'zhTW', '它…攻擊力很強！', '', 25549),
(125397, 'zhTW', '', '這惡魔真醜！', 25549),
(125396, 'zhTW', '我準備好進入聖所了。', '我準備好進入聖所了。', 25549),
(125395, 'zhTW', '', '你們竟敢囚禁我，真是找死！', 25549),
(125394, 'zhTW', '斬魔者$n，幫幫我！', '', 25549),
(125393, 'zhTW', '時候到了。突破聖所，進入暗夜堡！', '', 25549),
(125392, 'zhTW', '…不客氣。', '', 25549),
(125391, 'zhTW', '快逃啊小女孩，快逃！', '', 25549),
(125390, 'zhTW', '唉。好啦好啦…咳…', '', 25549),
(125389, 'zhTW', '拜託嘛！我是超級粉絲！', '拜託嘛！我是超級粉絲！', 25549),
(125388, 'zhTW', '吼，別這樣嘛！', '吼，別這樣嘛！', 25549),
(125387, 'zhTW', '我現在不走那種戲路了！', '', 25549),
(125386, 'zhTW', '呃。不好啦…', '', 25549),
(125385, 'zhTW', '說一下那句經典台詞！', '說一下那句經典台詞！', 25549),
(125384, 'zhTW', '暫時都清理乾淨了…保持警戒，燃燒軍團絕對不會善罷甘休。', '', 25549),
(125383, 'zhTW', '*咳咳咳咳咳*', '', 25549),
(125382, 'zhTW', '嗯…我已經太久沒有看到奧杜亞的廳堂了。或許我該拜訪其他的看守者兄弟們…我們有很多事要談。再見！', '', 25549),
(125381, 'zhTW', '勇猛的英雄們，好好享受勝利者的獎賞！總有一天，我還會需要你們的勇氣與武藝。', '', 25549),
(125380, 'zhTW', '我長久以來的死敵被擊敗了！把我困在英靈殿的詛咒終於解除了。', '', 25549),
(125379, 'zhTW', '我們絕不能眼睜睜看著燃燒軍團蹂躪我們的家園。保護法隆谷地！', '', 25549),
(125378, 'zhTW', '', '斬魔者，揮舞戰刃吧，我們需要你幫忙擊退這些惡魔！', 25549),
(125377, 'zhTW', '勇士除了力量也需要智慧！', '', 25549),
(125376, 'zhTW', '下一個試煉！保持警戒！', '', 25549),
(125375, 'zhTW', '', '|TInterface\\Icons\\SPELL_SHADOW_SHADETRUESIGHT.BLP:20|t %s開始施放|cFFFF0000|Hspell:228565\n|h[腐化吐息]|h|r！', 25549),
(125369, 'zhTW', '小偷！這艘船是我的！', '', 25549),
(125363, 'zhTW', '傳送到宮殿入口。', '傳送到宮殿入口。', 25549),
(125362, 'zhTW', '傳送到暗夜之泉。', '傳送到暗夜之泉。', 25549),
(125361, 'zhTW', '傳送到艾莉珊德的私人居所。', '傳送到艾莉珊德的私人居所。', 25549),
(125360, 'zhTW', '傳送到暗夜之塔。', '傳送到暗夜之塔。', 25549),
(125359, 'zhTW', '傳送門閃耀著暗夜之塔的景象。', '', 25549),
(125358, 'zhTW', '你聽見遠處一扇門解鎖的聲音。', '', 25549),
(125357, 'zhTW', '那是我的寶藏！', '那是我的寶藏！', 25549),
(125356, 'zhTW', '你好啊，$n。從聲音聽起來你好像成功打敗夜禍了。我想我們該讓這條龍永遠安息。你去收集骨頭，把它們放回原本的地方。', '', 25549),
(125349, 'zhTW', '言語無法表達我對你的感激。$b$b如果你沒有介入，我就會變成失去意志的空殼，永遠受夜井折磨。現在…我自由了。$b$b我一直都相信薩莉瑟拉能帶領我們得到救贖。現在我更加確定了，總有一天，夜裔一定能獲救。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125348, 'zhTW', '我準備好要攻城了。', '我準備好要攻城了。', 25549),
(125347, 'zhTW', '要讓軍隊團結起來，最快的方式就是擁有共同的敵人。$b$b一週前，這些精靈還在彼此攻擊，現在由於你的努力，我們已經準備好對暗夜堡發動最後一波攻擊。$b$b雖然我想打頭陣，但是泰蘭妲堅持要你和我待在這裡和夜落精靈一起守住後方。來吧，朋友，讓我們瞧瞧這些精靈如何解決紛爭。', '', 25549),
(125346, 'zhTW', '出發。', '出發。', 25549),
(125345, 'zhTW', '等你準備好調查時間之鎖法術時，告訴我一聲。', '', 25549),
(125344, 'zhTW', '', '我愛傳送門。', 25549),
(125343, 'zhTW', '', '燒吧…', 25549),
(125342, 'zhTW', '', '真恐怖！', 25549),
(125341, 'zhTW', '', '好熱！', 25549),
(125340, 'zhTW', '', '燃燒吧，寶貝！', 25549),
(125339, 'zhTW', '你好啊，我剛才巡視時發現這裡有某種法術會影響非鬼魂生物的大小。考慮到你垂直方面的行動限制，我們還是試著把這裡的書蠹龍清掉吧。', '', 25549),
(125338, 'zhTW', '謝謝你趕來，斬魔者$n！', '', 25549),
(125337, 'zhTW', '', '斬魔者！有一群惡魔登上魔錘號了！我們需要你的協助！', 25549),
(125336, 'zhTW', '卡爾侖，我有一箱馬蹄鐵要給你。', '卡爾侖，我有一箱馬蹄鐵要給你。', 25549),
(125335, 'zhTW', '深淵魔犬發出詭異的低吼聲。', '', 25549),
(125334, 'zhTW', '深淵魔犬感覺到附近有人。', '', 25549),
(125333, 'zhTW', '深淵魔犬抬頭嗅嗅。', '', 25549),
(125332, 'zhTW', '這是什麼？喔，我訂購的馬蹄鐵終於到貨了！等等…這是怎麼回事？根本都壞掉了啊！簡直就像放在外頭淋了十幾年的雨一樣。叫那個「法師」去找個新的供應商。', '', 25549),
(125331, 'zhTW', '敵人源源不絕…', '敵人源源不絕…', 25549),
(125330, 'zhTW', '我還以為要死了。謝謝，$n！', '我還以為要死了。謝謝，$n！', 25549),
(125329, 'zhTW', '好險啊。謝謝你！', '好險啊。謝謝你！', 25549),
(125328, 'zhTW', '非常感謝你！', '非常感謝你！', 25549),
(125327, 'zhTW', '', '$n，我和大法師艾特羅斯會阻止援軍抵達大門，但請你盡可能把他們擊退。$B$B如果他們的數量持續增加，恐怕我們也會撐不住。', 25549),
(125326, 'zhTW', '討厭的蜘蛛，還有叫個不停的蝙蝠，還有最最該死的惡魔怪物，竟然占據佣人區。還好那些大傢伙已經清掉了。', '', 25549),
(125325, 'zhTW', '該死的東西！你相信嗎？牠們竟然還在這裡！上次來的那群人根本一點用也沒有。嗯，你該不會碰巧有空可以幫我個忙吧？', '', 25549),
(125324, 'zhTW', '我們會好好面對接下來的日子。', '我們會好好面對接下來的日子。', 25549),
(125323, 'zhTW', '這種水果真的救了薩莉瑟拉？真是不可思議。', '這種水果真的救了薩莉瑟拉？真是不可思議。', 25549),
(125322, 'zhTW', 'Erana-dora isil. (我最真摯的情感。) 萬分感謝。', 'Erana-dora isil. (我最真摯的情感。) 萬分感謝。', 25549),
(125321, 'zhTW', '之前在城裡就被你救過一次，現在又…真不知道該怎麼感謝你。', '之前在城裡就被你救過一次，現在又…真不知道該怎麼感謝你。', 25549),
(125320, 'zhTW', '終於等到了，我想要自由。', '終於等到了，我想要自由。', 25549),
(125319, 'zhTW', '吃了這個真的就不會餓了嗎？', '吃了這個真的就不會餓了嗎？', 25549),
(125318, 'zhTW', '我們不會忘記你和薩莉瑟拉為我們所做的一切。', '我們不會忘記你和薩莉瑟拉為我們所做的一切。', 25549),
(125313, 'zhTW', '奧肯多耳是什麼？真的很多耳朵嗎？', '奧肯多耳是什麼？真的很多耳朵嗎？', 25549),
(125312, 'zhTW', '薇兒塔小姐說，如果我吃了這個，她就教我看地脈。我們打過勾勾了！', '薇兒塔小姐說，如果我吃了這個，她就教我看地脈。我們打過勾勾了！', 25549),
(125311, 'zhTW', '吃了這個可以跟薩莉瑟拉一樣強嗎？她好酷！', '吃了這個可以跟薩莉瑟拉一樣強嗎？她好酷！', 25549),
(125310, 'zhTW', '可以剝皮嗎？我不喜歡吃皮…', '可以剝皮嗎？我不喜歡吃皮…', 25549),
(125309, 'zhTW', '噁！我想要糖果！', '噁！我想要糖果！', 25549),
(125308, 'zhTW', '給我的？！謝謝你！', '給我的？！謝謝你！', 25549),
(125307, 'zhTW', '耶，魔法果實！', '耶，魔法果實！', 25549),
(125304, 'zhTW', '', '不！我不敢看…', 25549),
(125303, 'zhTW', '', '噢，不妙…', 25549),
(125302, 'zhTW', '', '真是悲劇！', 25549),
(125301, 'zhTW', '', '天啊！', 25549),
(125300, 'zhTW', '', '小心！', 25549),
(125299, 'zhTW', '你來得正是時候！', '你來得正是時候！', 25549),
(125298, 'zhTW', '', '你叫我？', 25549),
(125297, 'zhTW', '我們不會忘記你的大恩大德。', '我們不會忘記你的大恩大德。', 25549),
(125296, 'zhTW', '我欠你人情。', '我欠你人情。', 25549),
(125295, 'zhTW', '我自由了嗎？', '我自由了嗎？', 25549),
(125294, 'zhTW', '謝謝你，$c。', '謝謝你，$c。', 25549),
(125293, 'zhTW', '我想跟你談談關於秘法動量的知識。', '我想跟你談談關於秘法動量的知識。', 25549),
(125292, 'zhTW', '你真的想忘記秘法動量的相關知識嗎？', '你真的想忘記秘法動量的相關知識嗎？', 25549),
(125291, 'zhTW', '你真的想學習這個新技能嗎？', '你真的想學習這個新技能嗎？', 25549),
(125290, 'zhTW', '秘法動量讓法師改以物理移動方向決定閃現術的方向。這和比較基本，只能朝法師面對的方向施展的閃現術不太一樣。', '秘法動量讓法師改以物理移動方向決定閃現術的方向。這和比較基本，只能朝法師面對的方向施展的閃現術不太一樣。', 25549),
(125289, 'zhTW', '我想忘記秘法動量，往我面對的方向施展閃現術。', '我想忘記秘法動量，往我面對的方向施展閃現術。', 25549),
(125288, 'zhTW', '我想學習秘法動量，往我正在移動的方向施展閃現術。', '我想學習秘法動量，往我正在移動的方向施展閃現術。', 25549),
(125286, 'zhTW', '', '我們會找到他們。絲瑟諾女士呢？', 25549),
(125285, 'zhTW', '珂娃絲！斬魔者！這陣子都風平浪靜。燃燒軍團的傳送門突然出現，我們只能拼死奮戰！大部分的斥候都失蹤了。', '', 25549),
(125284, 'zhTW', '', '范德爾，我們趕來幫忙了。發生什麼事？', 25549),
(125282, 'zhTW', '引誘惡魔劫奪者到地雷上來摧毀它！', '', 25549),
(125280, 'zhTW', '綠色球被歸還到它的基地了！', '', 25549),
(125278, 'zhTW', '紫色球被歸還到它的基地了！', '', 25549),
(125276, 'zhTW', '橘色球被歸還到它的基地了！', '', 25549),
(125275, 'zhTW', '找到%s了！', '跳過特效，避免受到|cFFFF0404|Hspell:211901|h[融能加壓器]|h|r的傷害！', 25549),
(125274, 'zhTW', '', '我沒有多少時間，這次只能簡短報告。$b$b艾莉珊德很生氣。她準備了計畫，但我還不知道任何細節。$b$b我還在努力打聽，一旦知道計畫，就會與你聯絡。$b$b保重。', 25549),
(125273, 'zhTW', '', '你的新盟友還真是引人注目。$b$b不知道你從哪裡找來這群人，但他們混進漫步宏園的時候，我得努力才能藏住笑意。$b$b氣氛愈來愈詭異了，貴族似乎終於明白，戰事在所難免。艾莉珊德不會眼睜睜看著蘇拉瑪爾被外來者奪走，一定會要他們想辦法做些什麼。$b$b我的朋友，我們還沒獲得勝利。$b$b保重，堅持下去，我們很快就能見面了。', 25549),
(125272, 'zhTW', '', '聽到凡席爾安全了真令人高興，請幫我向他問好！好希望能親眼看到他。$b$b情勢愈來愈…緊張了。暮色百合讓貴族非常焦躁，他們正在討論怎麼解決問題，很有可能訴諸暴力。我擔心還困在城裡的人可能會有生命危險。$b$b聽說有漫步宏園的消息…他們打算加強警備。我會繼續觀察。$b$b有其他消息我再報告。', 25549),
(125271, 'zhTW', '', '應你要求，我調查了魔魂堡。目前看來，你們的行動確實打擊到販賣夏多雷的狀況，但如果沒有後續行動，販賣人口就會繼續下去。$b$b在艾斯特瓦港事件之後，到處都嚷著要掃蕩叛逃者，所以你們可以先準備了，近期會有更多人逃到你們那裡。$b$b來說一點輕鬆的，宮內的最新流行是把裝飾用的橘色小鳥放在頭頂上，時尚這種東西真的很奇妙。$b$b我還在尋找我們的朋友，有消息會直接聯絡你。$b$b別放棄希望，首席秘法師。', 25549),
(125270, 'zhTW', '綠色籃球被$n丟掉了！', '', 25549),
(125269, 'zhTW', '綠色籃球被$n丟掉了！', '', 25549),
(125268, 'zhTW', '紫色籃球被$n丟掉了！', '', 25549),
(125267, 'zhTW', '紫色籃球被$n丟掉了！', '', 25549),
(125266, 'zhTW', '橘色籃球被$n丟掉了！', '', 25549),
(125265, 'zhTW', '橘色籃球被$n丟掉了！', '', 25549),
(125264, 'zhTW', '得分！$n用綠色籃球拿下一分。', '', 25549),
(125263, 'zhTW', '得分！$n用綠色籃球拿下一分。', '', 25549),
(125262, 'zhTW', '得分！$n用紫色籃球拿下一分。', '', 25549),
(125261, 'zhTW', '得分！$n用紫色籃球拿下一分。', '', 25549),
(125260, 'zhTW', '得分！$n用橘色籃球拿下一分。', '', 25549),
(125259, 'zhTW', '<關閉訊息。>', '<關閉訊息。>', 25549),
(125258, 'zhTW', '得分！$n用橘色籃球拿下一分。', '', 25549),
(125257, 'zhTW', '紫色籃球被$n撿起來了！', '', 25549),
(125256, 'zhTW', '紫色籃球被$n撿起來了！', '', 25549),
(125255, 'zhTW', '橘色籃球被$n撿起來了！', '', 25549),
(125254, 'zhTW', '橘色籃球被$n撿起來了！', '', 25549),
(125253, 'zhTW', '綠色籃球被$n撿起來了！', '', 25549),
(125252, 'zhTW', '綠色籃球被$n撿起來了！', '', 25549),
(125251, 'zhTW', '做得好！謝謝你，絕對不能讓燃燒軍團奪走這片土地！', '', 25549),
(125250, 'zhTW', '<聽第五段訊息。>', '<聽第五段訊息。>', 25549),
(125249, 'zhTW', '<聽第四段訊息。>', '<聽第四段訊息。>', 25549),
(125248, 'zhTW', '<聽第三段訊息。>', '<聽第三段訊息。>', 25549),
(125247, 'zhTW', '<聽第二段訊息。>', '<聽第二段訊息。>', 25549),
(125246, 'zhTW', '<聽第一段訊息。>', '<聽第一段訊息。>', 25549),
(125245, 'zhTW', '', '沒有任何動靜。艾莉珊德應該對城裡目前的氣氛很滿意。或許大家太害怕了，沒有任何人提到弦月旅店的事…$b$b我找不到凡席爾。沒有任何人提起凡席爾。$b$b題外話，艾莉珊德應該是我見過最會遲到的人，幫她做事很累。$b$b我會盡快回報。薩莉瑟拉，保重。', 25549),
(125244, 'zhTW', '', '<黎利斯的影像急切地看著你。你想聽她帶來的訊息嗎？>', 25549),
(125243, 'zhTW', '艾莉珊德想拿我殺雞儆猴，但我們的反抗行動獲得前所未有的成功。$b$b她在弦月旅店所做的事不能原諒。', '', 25549),
(125242, 'zhTW', '好多來自弦月旅店的熟面孔！知道有那麼多人存活下來，我覺得如釋重負。$b$b同時也為那些已經不在的人而悲傷。', '', 25549),
(125241, 'zhTW', '奧肯多爾就是夜裔的未來…奧肯多爾果實讓我即使不依賴秘能酒，也能為族人效力。', '', 25549),
(125240, 'zhTW', '$n，你救了我的命。至於薩莉瑟拉…她救了我的未來。', '', 25549),
(125238, 'zhTW', '凡席爾勉強站起來。', '', 25549),
(125237, 'zhTW', '把我送到地面。', '帶我回馬爾頓。', 25549),
(125236, 'zhTW', '那我就不打擾你了。我會從遠處觀察。', '', 25549),
(125235, 'zhTW', '祝你好運。對了，別忘記…如果你離開這個地方，先前的努力就會歸零，要重新來過。', '', 25549),
(125234, 'zhTW', '', '不必跳下去，我們的魔化蝙蝠會很高興有機會伸展翅膀！', 25549),
(125233, 'zhTW', '周圍稍微變得暖和一些。', '周圍稍微變得暖和一些。', 25549),
(125232, 'zhTW', '一陣詭異的冷風吹了過來…', '一陣詭異的冷風吹了過來…', 25549),
(125231, 'zhTW', '卡雷克，我準備要回去了。', '卡雷克，我準備要回去了。', 25549),
(125230, 'zhTW', '大法師$n，你辦到了。這真值得恭喜，不過我想在職業大廳的大家面前恭喜你。$b$b等你準備好了，我們就傳送回去。', '', 25549),
(125228, 'zhTW', '', '伊利達瑞！馬爾頓需要支援。出動！', 25549),
(125227, 'zhTW', '你聽到高塔遺跡傳來的聲音了嗎？聽起來很不妙。千萬小心！', '', 25549),
(125226, 'zhTW', '愚蠢的凡人！今天是你的末日！', '', 25549),
(125222, 'zhTW', '', '西爾格林教了我各式各樣的知識，但我還有很多不懂的地方。$b$b希望靠這些知識足以面對艾莉珊德。', 25549),
(125221, 'zhTW', '', '他最近對魔典越來越著迷了。開始變得多疑又偏執。', 25549),
(125220, 'zhTW', '', '斬魔者！快來聽馬爾頓斥候傳來的緊急消息！', 25549),
(125219, 'zhTW', '小心！這裡要垮了！', '', 25549),
(125218, 'zhTW', '現在…發射！！！', '', 25549),
(125217, 'zhTW', '', '英雄，請留意。大法師今天心情不太好，可能會不太友善。', 25549),
(125209, 'zhTW', '', '你就這點實力？看來埃雷達爾的劍術不怎麼樣，是吧？', 25549),
(125208, 'zhTW', '你的力量只有如此？真可悲。', '你的力量只有如此？真可悲。', 25549),
(125207, 'zhTW', '噢噢！閃亮亮！給我嗎？', '', 25549),
(125206, 'zhTW', '你找到什麼了嗎？魔法寶物？喂！跟我說嘛！', '', 25549),
(125205, 'zhTW', '嘿！你找到好東西了？！珍貴的東西？', '', 25549),
(125204, 'zhTW', '我想交易。', '我想交易。', 25549),
(125203, 'zhTW', '你好啊！你有發現我終於晉升法師階級了嗎？雖然是死後才升的…但這仍然是莫大的榮耀。$b$b升遷之後我有了新責任：整理這座塔。果然還是該整理得體面一點，以免大法師卡德加以後還要用到。', '', 25549),
(125202, 'zhTW', '喂！你在幹嘛？', '喂！你在幹嘛？', 25549),
(125201, 'zhTW', '肉糰餓了！', '', 25549),
(125200, 'zhTW', '我們受到攻擊，損失慘重。到處都是燃燒軍團傳送門！我們需要援軍！', '', 25549),
(125199, 'zhTW', '', '絲瑟諾女士幾個小時前下去幫忙了，但情況聽起來很嚴重。我們該跟過去嗎？', 25549),
(125198, 'zhTW', '', '斬魔者！我們剛剛收到貝拉斯在馬爾頓的斥候傳來的緊急消息！', 25549),
(125196, 'zhTW', '然後混合一下！', '', 25549),
(125195, 'zhTW', '一份死亡…兩份毀滅…', '', 25549),
(125194, 'zhTW', '嘗嘗這個！', '', 25549),
(125193, 'zhTW', '加一點這個…加一點那個…', '', 25549),
(125191, 'zhTW', '這些新盟友送給我的禮物是你們無法想像的 - 你派「救世主」過來只是害他獨自送死罷了。', '', 25549),
(125190, 'zhTW', '傑爾賓，你老糊塗了。', '', 25549),
(125189, 'zhTW', '', '好久沒有玩得這麼開心了！', 25549),
(125188, 'zhTW', '', '我在騙誰，這才是真的我！', 25549),
(125187, 'zhTW', '', '看來是我…活該…', 25549),
(125186, 'zhTW', '', '永遠…都一樣…', 25549),
(125185, 'zhTW', '', '你肯定更喜歡我這個樣子！', 25549),
(125184, 'zhTW', '', '這是你自找的！', 25549),
(125183, 'zhTW', '', '我已經…沒救了…', 25549),
(125182, 'zhTW', '', '可恥啊…可恥…', 25549),
(125181, 'zhTW', '不！裂隙要關了！', '', 25549),
(125180, 'zhTW', '', '貞潔…我呸！', 25549),
(125179, 'zhTW', '', '屏除心中的邪念。謹記她的教誨！', 25549),
(125178, 'zhTW', '', '我一直在研究進階的魔法。說不定改天會去申請加入祈倫托！', 25549),
(125177, 'zhTW', '', '其實…我有點懷念過去的日子。', 25549),
(125176, 'zhTW', '', '真高興，聖女指引了我們正確的道路！', 25549),
(125175, 'zhTW', '', '當好人…沒好處…', 25549),
(125174, 'zhTW', '', '我讓…聖女…失望了…', 25549),
(125173, 'zhTW', '', '我也想當個好人…真的…', 25549),
(125172, 'zhTW', '', '要跟我玩？那就來玩吧！', 25549),
(125171, 'zhTW', '', '你這種貨色我已經看不上眼了！', 25549),
(125170, 'zhTW', '', '天啊…你真是誘人！', 25549),
(125169, 'zhTW', '', '聖女最討厭這樣了！', 25549),
(125168, 'zhTW', '', '蕾薇亞…是，我記得她。她偶爾會住在這裡，上次來是兩天前了。\n\n暗影魔法很危險，這也是為什麼祈倫托不願在城裡看到任何蹤跡，可是她涉及的這件事，又異常地危險。真希望她至少先離開城市再這麼做。\n\n你儘管上樓檢查，看看她有沒有留下任何東西。', 25549),
(125167, 'zhTW', '希望你喜歡我的作品，哥哥。我很遺憾事情演變成這樣…', '', 25549),
(125166, 'zhTW', '法師保險庫有各式各樣的魔法裝置。應該有些東西是達拉然用得上的…', '', 25549),
(125165, 'zhTW', '你知道蕾薇亞‧勞倫斯在哪裡嗎？', '你知道蕾薇亞‧勞倫斯在哪裡嗎？', 25549),
(125164, 'zhTW', '你根本無法理解我即將獲得的力量！看來是該讓你見識一下了…', '', 25549),
(125163, 'zhTW', '拜託你，弟弟！不要向黑暗屈服！', '', 25549),
(125162, 'zhTW', '愚蠢的哥哥，你太遲了。扭曲虛空在等著我，無窮的力量在等著我！全艾澤拉斯都會臣服在我的腳下！', '', 25549),
(125161, 'zhTW', '停止你的瘋狂行為，弟弟！你還可以回頭！', '', 25549),
(125160, 'zhTW', '對，沒錯，蕾薇亞。高個子的女孩，淺色的頭髮，對吧？她買走一些卷軸和墨水，好像說要用來製作某種儀式要用的符文。\n\n她想找某種特定類型的法杖，但是我們不賣那種東西。我叫她去軍事狂秘術店看看。\n\n或許你們應該去那裡問問？', '', 25549),
(125159, 'zhTW', '你知道蕾薇亞‧勞倫斯在哪裡嗎？', '你知道蕾薇亞‧勞倫斯在哪裡嗎？', 25549),
(125158, 'zhTW', '一！', '', 25549),
(125157, 'zhTW', '二！', '', 25549),
(125156, 'zhTW', '三！', '', 25549),
(125155, 'zhTW', '|cFFFF0000海爾珈|r回到戰鬥中！', '|cFFFF0000海爾珈|r回到戰鬥中！', 25549),
(125154, 'zhTW', '|cFFFF0404海姆達爾|r回到戰鬥中！', '|cFFFF0404海姆達爾|r回到戰鬥中！', 25549),
(125153, 'zhTW', '%s開始啟動了！', '', 25549),
(125152, 'zhTW', '', '跟我上樓啟動這個方塊，別讓好奇的顧客看到…', 25549),
(125151, 'zhTW', '', '你去啟動它吧…我先退到…適合觀察的距離外。', 25549),
(125150, 'zhTW', '', '有人來了…你是誰？！等等！別碰我！放肆！你知道我是誰嗎？！', 25549),
(125149, 'zhTW', '', '夜井底下好像有個缺口，可以直接通往宮殿！他們想把缺口封起來，但我想你一定可以…', 25549),
(125148, 'zhTW', '你在開玩笑嗎？', '', 25549),
(125147, 'zhTW', '音樂不要停！', '', 25549),
(125146, 'zhTW', '', '喵喵喵。', 25549),
(125145, 'zhTW', '', '喵喵。', 25549),
(125144, 'zhTW', '啟動記憶立方體！', '啟動記憶立方體！', 25549),
(125143, 'zhTW', '酷斃了，朋友。', '', 25549),
(125142, 'zhTW', '<記憶立方體發出嗡嗡嗡的聲音，好像有什麼事情就要發生。>', '', 25549),
(125141, 'zhTW', '一起上！', '', 25549),
(125140, 'zhTW', '', '千萬別從正門進攻，應該有其他辦法。安妲麗絲已經派了一群秘法師前往秩序聖所。', 25549),
(125139, 'zhTW', '這叫我怎麼樂觀得起來？', '', 25549),
(125138, 'zhTW', '如果你閉上眼…', '', 25549),
(125137, 'zhTW', '', '艾莉珊德有新的首席秘法師，一個叫安妲麗絲的可怕女人。她們準備用威力強大的魔法結界來瓦解攻勢。', 25549),
(125136, 'zhTW', '怎樣，夥伴？', '', 25549),
(125135, 'zhTW', '', '薩莉瑟拉，希望你看得到這個訊息。我剛開完緊急會議，會議中提到部落和聯盟的部隊在蘇拉瑪爾城外集結。', 25549),
(125134, 'zhTW', '', '喵。', 25549),
(125133, 'zhTW', '這些血精靈有豐富的戰鬥經驗而且紀律森嚴，他們將是不可或缺的力量。', '', 25549),
(125132, 'zhTW', '', '音樂別停啊！', 25549),
(125131, 'zhTW', '夜精靈用弓！蘇拉瑪爾已經好幾百年沒看過弓了。不知道他們是否願意讓我借一把來練習…', '', 25549),
(125130, 'zhTW', '真不敢相信我們源自同一種精靈。看來我們都無法抵抗時間造成的影響。', '', 25549),
(125129, 'zhTW', '需要經歷多年的訓練，才能成為魔劍士。薇可朵還是教反抗軍基礎戰鬥技能就好。', '', 25549),
(125128, 'zhTW', '真野蠻！', '', 25549),
(125127, 'zhTW', '祈倫托好像自以為是我們的保母。這樣也好，有他們在確實感覺比較安全。如果卡多雷真有什麼動作，祈倫托會出手嗎？', '', 25549),
(125126, 'zhTW', '哼，你們那群亂七八糟的烏合之眾也叫軍隊嗎！幸好這次行動的主角是我們血騎士和博學者，我們會直搗這座城市的核心。', '', 25549),
(125125, 'zhTW', '夜井…超乎想像的秘法泉源，如果這一切屬於辛多雷，我們又會變成怎樣呢？$b$b無論如何，我們已經掌握自己的命運，我們有屬於自己的榮耀，不再是魔法上癮的奴僕了。$b$b$n，這場戰役很重要，我們和遺失許久的親族…我們的敵人，一起對抗世界上最強大可怕的魔導師。這次行動將決定精靈的未來。', '', 25549),
(125124, 'zhTW', '我不會乖乖束手就擒！', '我不會乖乖束手就擒！', 25549),
(125123, 'zhTW', '你的判斷太荒謬了！', '你的判斷太荒謬了！', 25549),
(125122, 'zhTW', '你的判斷太荒謬了！燃燒軍團會摧毀白銀之手的！', '你的判斷太荒謬了！燃燒軍團會摧毀白銀之手的！', 25549),
(125121, 'zhTW', '我尊重你的判斷，大領主。等時機成熟，我就會證明我的價值。', '我尊重你的判斷，大領主。等時機成熟，我就會證明我的價值。', 25549),
(125120, 'zhTW', '我為你效勞。', '我為你效勞。', 25549),
(125119, 'zhTW', '你不會後悔做出這個選擇。', '你不會後悔做出這個選擇。', 25549),
(125118, 'zhTW', '我會效忠白銀之手。', '我會效忠白銀之手。', 25549),
(125117, 'zhTW', '大領主，我會心懷榮耀為你作戰。', '大領主，我會心懷榮耀為你作戰。', 25549),
(125116, 'zhTW', '結界消退了！我們衝進去大開殺戒吧！', '', 25549),
(125115, 'zhTW', '這裡！', '', 25549),
(125114, 'zhTW', '別忘了你的偽裝！', '別忘了你的偽裝！', 25549),
(125113, 'zhTW', '各位騎士，拿起武器！把剩下的敵人殺光吧！', '', 25549),
(125112, 'zhTW', '我先去前方探查，看看能在附近發現什麼。到破碎海岸來找我！', '', 25549),
(125111, 'zhTW', '那些夜裔對聖所做的事，我們一定加倍奉還。', '', 25549),
(125110, 'zhTW', '或許我該寫一本跟夜精靈歷史有關的書，他們的故事太有趣了…', '', 25549),
(125109, 'zhTW', '剛剛和辛多雷的魔導師聊天，他們說在故鄉有超大的圖書館。如果有機會真想去看看…', '', 25549),
(125108, 'zhTW', '月之守衛曾經發誓要保護這片土地。雖然現在我們所剩不多，但還是會盡力遵守誓言。', '', 25549),
(125106, 'zhTW', '這是什麼花招？', '', 25549),
(125105, 'zhTW', '祝你好運。', '', 25549),
(125104, 'zhTW', '大工匠，遵命！快把屏障降下。', '', 25549),
(125103, 'zhTW', '撬簧隊長，先把屏障降下來，謝謝。', '', 25549),
(125102, 'zhTW', '', '主人…我…讓你失望了…', 25549),
(125101, 'zhTW', '', '虛空之誓會給你們痛快！', 25549),
(125100, 'zhTW', '', '蠢蛋…你們以為這麼簡單就能脫身嗎？', 25549),
(125099, 'zhTW', '', '我剛剛看到哨兵在營地練習射擊，真的滿準的…$b$b我們不太用弓箭，如果你能改變世界的本質來施展魔法，還會想用這種原始武器嗎？', 25549),
(125098, 'zhTW', '1，2，3，跳！', '', 25549),
(125097, 'zhTW', '2…', '', 25549),
(125096, 'zhTW', '1…', '', 25549),
(125095, 'zhTW', '', '這些血精靈的法術很厲害，希望他們能對抗夜井的威力。', 25549),
(125094, 'zhTW', '', '暮衛軍非常強大。我們如果想達成目標，就必須善用所有的兵力。', 25549),
(125093, 'zhTW', '出手吧，亞拉涅斯，這樣我們的貴客才能變得更強大！', '', 25549),
(125092, 'zhTW', '', '所有大法師聽好了，善用你們的力量，讓這兩樣東西結合起來！', 25549),
(125091, 'zhTW', '風暴狂嘯，冰川如刀，冰靈亞拉涅斯，請聽我召喚！', '', 25549),
(125090, 'zhTW', '這些貴客來這裡就是想知道自己的能耐。那就讓他們知道吧，維斯勒瑟！', '', 25549),
(125089, 'zhTW', '掌管力量，穩固意志的法靈維斯勒瑟，起來吧！', '', 25549),
(125088, 'zhTW', '我等這一刻，等了上萬年！', '我等這一刻，等了上萬年！', 25549),
(125087, 'zhTW', '雜碎，去死吧！', '雜碎，去死吧！', 25549),
(125086, 'zhTW', '我們絕不會敗在燃燒軍團手上！', '我們絕不會敗在燃燒軍團手上！', 25549),
(125085, 'zhTW', '為了納薩拉斯！', '為了納薩拉斯！', 25549),
(125084, 'zhTW', '就算我死了…也還是一樣…', '就算我死了…也還是一樣…', 25549),
(125083, 'zhTW', '弟兄們會幫我報仇…', '弟兄們會幫我報仇…', 25549),
(125082, 'zhTW', '你無法阻止暗影…', '你無法阻止暗影…', 25549),
(125081, 'zhTW', '快滾…否則…', '快滾…否則…', 25549),
(125080, 'zhTW', '來大鬧一場吧！', '', 25549),
(125079, 'zhTW', '把秘法炸彈放在傳送門裡，應該就能摧毀它。傳送門一關閉，我們就去把惡魔殺光！', '', 25549),
(125078, 'zhTW', '那些惡魔不停地從傳送門進入毀棄聖所。守夜者就快撐不住了！', '', 25549),
(125077, 'zhTW', '愛插手就去死吧！', '愛插手就去死吧！', 25549),
(125076, 'zhTW', '入侵者，這裡不歡迎你！', '入侵者，這裡不歡迎你！', 25549),
(125075, 'zhTW', '失敗是改變的機會。等你比較能專心了，再回來挑戰試煉吧。', '', 25549),
(125074, 'zhTW', '你別想活著離開！', '你別想活著離開！', 25549),
(125073, 'zhTW', '我們雖然人數銳減，但還是會盡力幫助你。幫我們報仇吧，把燃燒軍團趕回地獄去！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125072, 'zhTW', '打得好！雖然年紀輕輕，但潛力無窮。', '', 25549),
(125070, 'zhTW', '你的調查到此為止！', '你的調查到此為止！', 25549),
(125069, 'zhTW', '奇瑪，讓這些貴客看看你的厲害！', '', 25549),
(125068, 'zhTW', '暗影…在呼喚我…', '暗影…在呼喚我…', 25549),
(125067, 'zhTW', '你贏不了的…', '你贏不了的…', 25549),
(125066, 'zhTW', '一切都會…屈服…', '一切都會…屈服…', 25549),
(125065, 'zhTW', '虛空之誓…為我報仇…', '虛空之誓…為我報仇…', 25549),
(125064, 'zhTW', '這個世界注定要滅亡！', '這個世界注定要滅亡！', 25549),
(125063, 'zhTW', '一切都會向虛空之誓屈服！', '一切都會向虛空之誓屈服！', 25549),
(125062, 'zhTW', '暗影會吞噬你！', '暗影會吞噬你！', 25549),
(125061, 'zhTW', '我為什麼要幫你？這不值得我冒這個險！', '我為什麼要幫你？這不值得我冒這個險！', 25549),
(125060, 'zhTW', '別來煩我！', '別來煩我！', 25549),
(125059, 'zhTW', '我什麼也不會告訴你！', '我什麼也不會告訴你！', 25549),
(125058, 'zhTW', '烈焰的化身，抑制的怒火，燃燒吧，火靈奇瑪！', '', 25549),
(125057, 'zhTW', '我們只能指望你了！你願意幫忙嗎？', '', 25549),
(125056, 'zhTW', '$p，你只能溜過去了，希科不知道在下面放了什麼東西，別被發現。解除飛彈，解決希科，就是這樣！', '', 25549),
(125055, 'zhTW', '沒時間了。我們不能等援軍到了再行動。', '', 25549),
(125054, 'zhTW', '送我去破碎海岸！', '送我去破碎海岸！', 25549),
(125053, 'zhTW', 'This is where Danuser''s epic, rallying speech will go. Now listen to Bolvar then go to Mograine upstairs!', '', 25549),
(125052, 'zhTW', '好棒的推理能力，真厲害，但已經來不及了。再過不久你派去破碎海岸的小小防衛者都會被輻射汙染！', '', 25549),
(125051, 'zhTW', '', '報告長官，我們認為瑟瑪普拉格很可能就是幕後黑手。他好像還裝備了某種飛彈！', 25549),
(125050, 'zhTW', '戰鬥領主$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125049, 'zhTW', '虛空領主$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125048, 'zhTW', '先知$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125047, 'zhTW', '影尊$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125046, 'zhTW', '大祭司$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125045, 'zhTW', '大領主$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125044, 'zhTW', '$p宗師！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125043, 'zhTW', '大法師$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125042, 'zhTW', '神獵手$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125041, 'zhTW', '大德魯伊$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125040, 'zhTW', '斬魔者$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125039, 'zhTW', '死亡領主$p！沒想到能在這裡看到部落最偉大的勇士，我們需要你幫忙！', '', 25549),
(125038, 'zhTW', '戰鬥領主$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125037, 'zhTW', '虛空領主$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125036, 'zhTW', '先知$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125035, 'zhTW', '影尊$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125034, 'zhTW', '大祭司$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125033, 'zhTW', '大領主$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125032, 'zhTW', '$p宗師！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125031, 'zhTW', '大法師$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125030, 'zhTW', '神獵手$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125029, 'zhTW', '大德魯伊$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125028, 'zhTW', '斬魔者$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125027, 'zhTW', '死亡領主$p！我沒想到密探鋼火有辦法把聯盟最偉大的英雄找來！', '', 25549),
(125026, 'zhTW', '好吧。收攝心神。我們會用傳統的方式來試試你。', '', 25549),
(125025, 'zhTW', '這是計時活動。確定要開始嗎？', '這是計時活動。確定要開始嗎？', 25549),
(125024, 'zhTW', '包在我身上。', '包在我身上。', 25549),
(125023, 'zhTW', '我們絕對不會再失去諾姆瑞根。', '', 25549),
(125022, 'zhTW', '|cFF0000FF+$1i枚金幣|r', '|cFF0000FF+$1i枚金幣|r', 25549),
(125021, 'zhTW', '|cFFFF0000+$1i枚金幣|r', '|cFFFF0000+$1i枚金幣|r', 25549),
(125020, 'zhTW', '結果…不會…改變', '結果…不會…改變', 25549),
(125019, 'zhTW', '我很佩服！大多數的凡人只要碰到靈魂裂片就會死。', '我很佩服！大多數的凡人只要碰到靈魂裂片就會死。', 25549),
(125018, 'zhTW', '我知道的就這麼多，我發誓！', '我知道的就這麼多，我發誓！', 25549),
(125017, 'zhTW', '他們的人給了我這個東西。拿去，我不想跟那些教徒扯上關係！', '他們的人給了我這個東西。拿去，我不想跟那些教徒扯上關係！', 25549),
(125016, 'zhTW', '你永遠不會知道我們的祕密！', '你永遠不會知道我們的祕密！', 25549),
(125015, 'zhTW', '我什麼都不知道！別吵我！', '我什麼都不知道！別來煩我！', 25549),
(125014, 'zhTW', '來，我們得在深淵領主發現沙亞蘭以前阻止他。', '', 25549),
(125013, 'zhTW', '帶我們去城底區吧，希望還來得及。', '', 25549),
(125012, 'zhTW', '', '|TInterface\\Icons\\inv_misc_monsterhorn_03.blp:20|t一個%s在離黑爾雅較遠的地方出現了！', 25549),
(125011, 'zhTW', '大法師，我們有訪客。請來我房間一趟。', '', 25549),
(125010, 'zhTW', '暗影…會吞噬一切…', '暗影…會吞噬一切…', 25549),
(125009, 'zhTW', '虛空之誓一定會回來，沒有人可以阻止我們！', '虛空之誓一定會回來，沒有人可以阻止我們！', 25549),
(125008, 'zhTW', '愚蠢的凡人！這麼薄弱的攻勢只會像上次一樣一敗塗地…而且這次你們絕對逃不了！', '', 25549),
(125007, 'zhTW', '擊退他們！他們今天別想打贏！', '', 25549),
(125006, 'zhTW', '愚蠢的凡人！你竟敢放走我們的俘虜？那你就代他們受苦吧！', '', 25549),
(125005, 'zhTW', '', '要是傳送器失去動力，我們就需要|Hitem:143653:0:0:0:0:0:0:0:90:0|h[強能鑰石]|h才能再讓它啟動。等你準備好了就站上去吧！', 25549),
(125004, 'zhTW', '', '成功！', 25549),
(125003, 'zhTW', '賽倫啟動了聚源虹膜！', '賽倫啟動了聚源虹膜！', 25549),
(125002, 'zhTW', '', '我要送你到城裡面。衰減器的能量只夠讓我們傳送一次，千萬別浪費這個機會！', 25549),
(125001, 'zhTW', '', '校正高壓波動器…調整微型加速裝置…', 25549),
(125000, 'zhTW', '', '你得立刻潛入諾姆瑞根！', 25549),
(124999, 'zhTW', '我就知道信得過你。如果部落又被祈倫托趕出去，我們的力量就會分散，燃燒軍團就會吞噬整個世界。', '', 25549),
(124998, 'zhTW', '只有你和幾個我信得過的副官…但我沒辦法一直不動聲色。', '', 25549),
(124997, 'zhTW', '我來開傳送門。大法師，我們待會見！', '', 25549),
(124996, 'zhTW', '英雄，小心！厄運領主來了！', '', 25549),
(124995, 'zhTW', '終端機狀態：未受到防護。關閉中。', '', 25549),
(124994, 'zhTW', '堅守陣線！斬魔者來了！', '', 25549),
(124993, 'zhTW', '堅守陣線！大德魯伊來了！', '', 25549),
(124992, 'zhTW', '堅守陣線！宗師來了！', '', 25549),
(124991, 'zhTW', '堅守陣線！虛空領主來了！', '', 25549),
(124990, 'zhTW', '堅守陣線！大法師來了！', '', 25549),
(124989, 'zhTW', '堅守陣線！先知來了！', '', 25549),
(124988, 'zhTW', '堅守陣線！死亡領主來了！', '', 25549),
(124987, 'zhTW', '堅守陣線！大祭司來了！', '', 25549),
(124986, 'zhTW', '堅守陣線！影尊來了！', '', 25549),
(124985, 'zhTW', '堅守陣線！神獵手來了！', '', 25549),
(124984, 'zhTW', '堅守陣線！大領主來了！', '', 25549),
(124983, 'zhTW', '堅守陣線！戰鬥領主來了！', '', 25549),
(124982, 'zhTW', '', '你什麼？！', 25549),
(124981, 'zhTW', '凱爾希，我的客人多到數不清。怎麼會記得什麼從諾姆瑞根來的傢伙？', '', 25549),
(124980, 'zhTW', '正在啟動終端機防護模組3B。', '', 25549),
(124979, 'zhTW', '系統狀態：啟動中。', '', 25549),
(124978, 'zhTW', '啊，太好了！艾澤拉斯的力量是我的了！', '', 25549),
(124977, 'zhTW', '我和大法師會想辦法修復達拉然的武器。一定會！', '', 25549),
(124976, 'zhTW', '這個消息如果傳出去，休戰協議就完了。還有誰知道？', '', 25549),
(124975, 'zhTW', '噢，這可不妙。部落有人背叛…', '', 25549),
(124974, 'zhTW', '-- CUTSCENE -- Camera pans across the broken shore, revealing countless demons. The Tomb of Sargeras looms in the background. Khadgar VO playing... "The fate of our world will be decided this day."', '', 25549),
(124973, 'zhTW', '卡上緊緊纏著一條細線！', '卡上緊緊纏著一條細線！', 25549),
(124966, 'zhTW', '祝你好運，老兄。塔納利斯沙漠的環境很殘酷的！', '', 25549),
(124965, 'zhTW', '這裡沒有獎勵，只有死亡！', '這裡沒有獎勵，只有死亡！', 25549),
(124964, 'zhTW', '嚴禁訪客！', '嚴禁訪客！', 25549),
(124963, 'zhTW', '終於…自由了。', '終於…自由了。', 25549),
(124962, 'zhTW', '該離開這裡了…', '該離開這裡了…', 25549),
(124956, 'zhTW', '', '嗯，你想幹嘛？', 25549),
(124955, 'zhTW', '我來打開通道。你在跟惡魔戰鬥的時候，我會切斷這座塔和其他世界的連結。我們最好動作快！', '', 25549),
(124954, 'zhTW', '麥迪文？', '', 25549),
(124953, 'zhTW', '戰鬥領主，我需要跟你談談。快來找我！時間緊迫。', '', 25549),
(124952, 'zhTW', '我們停止這種無關緊要的衝突吧，現在應該全力對付燃燒軍團！我們必須團結艾澤拉斯所有的主力部隊！', '', 25549),
(124951, 'zhTW', '我在這座塔裡留下了很多自己的碎片…', '', 25549),
(124950, 'zhTW', '很好。等你做好準備，就立刻前往破碎海岸。', '', 25549),
(124947, 'zhTW', '前線也用得上科瓦迪爾。他們只是一副空殼，還不如送去對付燃燒軍團。', '', 25549),
(124943, 'zhTW', '戰鬥領主！擊敗黑爾雅這個邪惡女巫之後，她就再也不能阻止我拿回屬於我的一切了！', '', 25549),
(124939, 'zhTW', '這是主人的命令！', '這是主人的命令！', 25549),
(124938, 'zhTW', '別想…抵抗！', '別想…抵抗！', 25549),
(124937, 'zhTW', '遵命。', '遵命。', 25549),
(124936, 'zhTW', '為了燃燒軍團！', '為了燃燒軍團！', 25549),
(124935, 'zhTW', '遵從主人的命令！', '遵從主人的命令！', 25549),
(124934, 'zhTW', '要不是當初被黑爾雅劫走，他們早就是我的華爾拉亞了。現在，見證他們的轉變吧！', '', 25549),
(124933, 'zhTW', '做得好，戰鬥領主。我被劫走的戰士回來了！', '', 25549),
(124932, 'zhTW', '<回想大酋長希瓦娜斯和吉恩‧葛雷邁恩之間的衝突>', '<回想大酋長希瓦娜斯和吉恩‧葛雷邁恩之間的衝突>', 25549),
(124931, 'zhTW', '<回想伊瑟拉最後的平靜>', '<回想伊瑟拉最後的平靜>', 25549),
(124930, 'zhTW', '<回想伊瑟拉腐化的經過>', '<回想伊瑟拉腐化的經過>', 25549),
(124929, 'zhTW', '<回想初次看到蘇拉瑪爾的那一刻>', '<回想初次看到蘇拉瑪爾的那一刻>', 25549),
(124928, 'zhTW', '<回想卡德加面對誘惑的那一刻>', '<回想卡德加面對誘惑的那一刻>', 25549),
(124927, 'zhTW', '<回想對伊利丹手下的伊利達瑞的故事>', '<回想對伊利丹手下的伊利達瑞的故事>', 25549),
(124926, 'zhTW', '<回想古爾丹的故事>', '<回想古爾丹的故事>', 25549),
(124925, 'zhTW', '<回想希瓦娜斯升任大酋長的那一刻>', '<回想希瓦娜斯升任大酋長的那一刻>', 25549),
(124924, 'zhTW', '<回想從破碎海岸撤退的情景>', '<回想從破碎海岸撤退的情景>', 25549),
(124923, 'zhTW', '<回想瓦里安·烏瑞恩國王死去的那一刻>', '<回想瓦里安·烏瑞恩國王死去的那一刻>', 25549),
(124922, 'zhTW', '<回想被關在看守者鐵獄的日子>', '<回想被關在看守者鐵獄的日子>', 25549),
(124921, 'zhTW', '<回想在馬爾頓的任務>', '<回想在馬爾頓的任務>', 25549),
(124920, 'zhTW', '<回想伊利丹殞落的那一刻>', '<回想伊利丹殞落的那一刻>', 25549),
(124919, 'zhTW', '<回想光縛之物>', '<回想光縛之物>', 25549),
(124918, 'zhTW', '<從記憶立方體發散出來的物質讓你的思緒回到破碎群島，想起過去經歷的重要事件。>', '', 25549),
(124917, 'zhTW', '那個買鎖定系統的人就是希科·瑟瑪普拉格？老天啊。', '', 25549),
(124916, 'zhTW', '<告訴莫克斯你在瑟瑪普拉格得到的消息。>', '<告訴莫克斯你在瑟瑪普拉格得到的消息。>', 25549),
(124915, 'zhTW', '我們離開這裡吧。', '我們離開這裡吧。', 25549),
(124914, 'zhTW', '', '請不要在這可怕的地方停留太久，$ct$n。多待一秒，我的心智就虛弱一分。', 25549),
(124913, 'zhTW', '15秒後重力消失！', '15秒後重力消失！', 25549),
(124912, 'zhTW', '喔，對了，我忘記說一件事，這個終端機再過一下就會自爆。再會了！', '', 25549),
(124911, 'zhTW', 'asdf', 'sdf', 25549),
(124910, 'zhTW', '如果你們沒有在破碎海岸的輻射汙染和燃燒軍團無情的侵略行動下死掉的話。', '', 25549),
(124909, 'zhTW', '如果你聽到這個消息，這就代表你有資格見證我即位成為艾澤拉斯凡人統治者的加冕大典！', '', 25549),
(124908, 'zhTW', '地面的居民，大家好！我是獨一無二的機電師領主瑟瑪普拉格！', '', 25549),
(124907, 'zhTW', '小心翼翼地拿起輸入卡。', '小心翼翼地拿起輸入卡。', 25549),
(124906, 'zhTW', '不行不行不行不行啊啊啊啊！', '', 25549),
(124905, 'zhTW', '我真的生氣了！', '', 25549),
(124904, 'zhTW', '', '他們沒料到我會來。我悄悄出擊，悄悄離去，就像暗影中的利刃，劃開他們的防備。', 25549),
(124903, 'zhTW', '嗚！我們用的是街頭規則嗎？有本事就斷法啊！', '', 25549),
(124902, 'zhTW', '', '<這一定就是莫克斯死去助手的遺骸。>$B$B<你注意到灰燼裡面有東西。一定就是她想還回去的那張輸入卡！>', 25549),
(124901, 'zhTW', '<你之前在燃燒軍團手裡見過類似的典籍。六法議會擔心他們有內奸不是沒有道理的。>', '', 25549),
(124900, 'zhTW', '<這架直升機看起來相當破舊，它通常是工程學作坊拿來運貨用的。>', '', 25549),
(124899, 'zhTW', '雖然他們一直說自己「潛心於秘法的研究」，但炎爆術真的轟到眼前，還是驚慌失措。我差一點就要同情他們了。差一點。', '', 25549),
(124898, 'zhTW', '插入輸入卡。', '插入輸入卡。', 25549),
(124897, 'zhTW', '<機器在待機時發出有節奏的答答聲。>', '', 25549),
(124896, 'zhTW', '<你注意到裝置的表面有個插槽，莫克斯說的輸入卡可能就是要插入這裡。>$B$B<前提是你找得到的話…>', '', 25549),
(124895, 'zhTW', '檢視信標', '檢視信標', 25549),
(124894, 'zhTW', '', '亞魯艾兒在花盆前放下一朵暮色紫花。', 25549),
(124892, 'zhTW', '這些維酷人竟敢褻瀆我的城塞。殺死他們！以巫妖王之名，把他們變成不死軍團！', '', 25549),
(124891, 'zhTW', '你想得到霜牙的韁繩，但是你來晚了。韁繩已經落到入侵的維酷人手裡，他們打算用來控制冰霜巨龍。', '', 25549),
(124890, 'zhTW', '在你的指揮之下，四騎士重創了惡魔。不過，現在又有一個獲得力量的機會。', '', 25549),
(124889, 'zhTW', '死亡領主，燃燒軍團的這場戰役，你做得乾淨俐落。我很滿意。', '', 25549),
(124888, 'zhTW', '$ct，只要有你帶領我們，燃燒軍團毫無勝算。', '', 25549),
(124887, 'zhTW', '這裡是偉大、古老的蘇拉瑪爾城外圍，夜落精靈在這裡努力生存，默默地對抗腐化…', '', 25549),
(124886, 'zhTW', '', '我要回到懼痕裂隙，把這個計畫告訴其他議會成員。', 25549),
(124885, 'zhTW', '', '這樣一來，這傢伙對我們就沒有用處了，你說對不對？', 25549),
(124884, 'zhTW', '要不是她的演技太爛，我們才不會失業！', '', 25549),
(124883, 'zhTW', '', '吼！受不了他了！那個混蛋！', 25549),
(124882, 'zhTW', '我其實還滿聰明，你會知道的。', '', 25549),
(124881, 'zhTW', '我其實沒有那麼害怕，真的沒有。我只是演技好，真的。', '', 25549),
(124880, 'zhTW', '別跟劇組的人說，但我還滿高興能休息一下…原本有點擔心，會被定型成「穿鋼鐵裝的人」。', '', 25549),
(124879, 'zhTW', '我們先去偵察前方。死亡領主，等等戰場見！', '', 25549),
(124878, 'zhTW', '哈！他們一點機會也沒有。', '', 25549),
(124877, 'zhTW', '', '他們的死，會洗清我們的罪。', 25549),
(124876, 'zhTW', '燃燒軍團沒有榮譽。所以它們必敗無疑。', '', 25549),
(124875, 'zhTW', '', '難道你還要我叫你「小美人」嗎？還是要我召喚龍捲風？親愛的，別鬧了，這些都是演戲，都是假的！', 25549),
(124874, 'zhTW', '', '噢，親愛的～真高興看到你，你把玫瑰花帶來了嗎？', 25549),
(124873, 'zhTW', '', '現在就算看到真正的玉女也認不得啦！這真是太…令人感傷了。', 25549),
(124872, 'zhTW', '做得好，英雄！只要我們聯手，燃燒軍團就別想拿下艾蘇納！', '', 25549),
(124871, 'zhTW', '', '大家都喜歡這些改「良」版，難道只剩我懂得經典的好嗎！', 25549),
(124870, 'zhTW', '', '噢，親愛的，別擔心。我不需要別人來幫我過台詞。我已經差不多都記住了。', 25549),
(124869, 'zhTW', '', '坎瑞薩德是上一任的虛空領主。他也是我們議會的創始人。\n\n他排除萬難說服我們互相合作、帶領我們追求超乎想像的強大力量。\n\n即便如此他也不滿足。伊利丹在黑暗神廟戰敗後，他開始念念不忘在那裡見識到的力量。他渴望控制伊利丹所擁有的惡魔能量，不惜付出任何代價。\n\n我對坎瑞薩德發了毒誓，答應如果他被試圖控制的力量腐化而失去了自我，我會將他逐出這個世界。我必須遵守誓言，為了他，也為了所有其他人。', 25549),
(124868, 'zhTW', '再次騎上丹密爾吧，死亡領主。帶我們衝向戰場。', '', 25549),
(124867, 'zhTW', '坎瑞薩德是誰？', '坎瑞薩德是誰？', 25549),
(124866, 'zhTW', '', '無論要付出什麼代價，絕不能讓坎瑞薩德重返這個世界。', 25549),
(124865, 'zhTW', '', '我得承認，我一直想看看蘇拉瑪爾以外的世界。$B$B我對遠古文化很有興趣！', 25549),
(124864, 'zhTW', '現在還來得及加入我們…', '現在還來得及加入我們…', 25549),
(124863, 'zhTW', '', '能變回原來的樣子，感覺真好。$B$B<薇兒塔用手背輕輕撫觸自己的顴骨。>$B$B如你所見，秘法真的對皮膚很好！', 25549),
(124862, 'zhTW', '', '想不到我們一直以來是這麼的依賴夜井。現在擺脫它的召喚，感覺很…自由。', 25549),
(124861, 'zhTW', '你不是他的對手！', '你不是他的對手！', 25549),
(124860, 'zhTW', '魔化烈焰會吞噬你！', '魔化烈焰會吞噬你！', 25549),
(124859, 'zhTW', '我要燒死你們！', '我要燒死你們！', 25549),
(124858, 'zhTW', '他才是黑穫議會真正的領袖！他一定會回來！', '他才是黑穫議會真正的領袖！他一定會回來！', 25549),
(124857, 'zhTW', '坎瑞薩德，我需要你的力量！', '坎瑞薩德，我需要你的力量！', 25549),
(124856, 'zhTW', '那位大人一定會回來的！', '那位大人一定會回來的！', 25549),
(124855, 'zhTW', '誰都擋不了我們！', '誰都擋不了我們！', 25549),
(124854, 'zhTW', '坎瑞薩德，我讓你失望了！', '坎瑞薩德，我讓你失望了！', 25549),
(124853, 'zhTW', '不…不可能！', '不…不可能！', 25549),
(124852, 'zhTW', '我不會白白犧牲！', '我不會白白犧牲！', 25549),
(124851, 'zhTW', '', '坎瑞薩德很快就會復活了！', 25549),
(124850, 'zhTW', '', '你太遲了！儀式就要完成了。', 25549),
(124849, 'zhTW', '<以繃帶包紮龍隼族母。>', '<以繃帶包紮龍隼族母。>', 25549),
(124848, 'zhTW', '', '<受傷的族母一直躲著，直到剛剛聞到孩子的氣味才跑出來。但是牠的傷勢過於嚴重，無法照顧孩子。>', 25549),
(124847, 'zhTW', '<Echoes of the past swirl throughout your mind. Visions appear slowly at first, but soon begin to rapidly flash into and out of existence.$B$BHolding your gaze, you peer into the eyes of the Fragment of Medivh. Worlds beyond appear, then quickly fade into darkness.>', '', 25549),
(124846, 'zhTW', '我想知道卡拉贊的狀況。', '我想知道卡拉贊的狀況。', 25549),
(124845, 'zhTW', '這座塔怎麼了？', '這座塔怎麼了？', 25549),
(124844, 'zhTW', '<Whispers cloud your mind. Your thoughts become erratic.>', '', 25549),
(124843, 'zhTW', '一旦離開就會進入戰鬥。\n\n建議你花一點時間整理快捷列上的技能。\n\n你準備好了嗎？', '一旦離開就會進入戰鬥。\n\n建議你花一點時間整理快捷列上的技能。\n\n你準備好了嗎？', 25549),
(124841, 'zhTW', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s開始施展|cFFFF0000|Hspell:227573|h[守護犬之息]|h|r！', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s開始施展|cFFFF0000|Hspell:227573|h[守護犬之息]|h|r！', 25549),
(124832, 'zhTW', '亞魯艾兒，跟我來。', '亞魯艾兒，跟我來。', 25549),
(124831, 'zhTW', '', '自從你把奧肯多爾果實帶來這裡，很多事情都變了。$b$b我很想念弟弟，但我知道，他也是為了這件事，才甘願犧牲生命。$b$b有件事必須拜託你。我想報答其他人，我想幫弟弟報仇。$b$b請帶我去找首席秘法師，讓我對她效忠。', 25549),
(124830, 'zhTW', '這會有點痛喔，$pc。', '這會有點痛喔，$pc。', 25549),
(124829, 'zhTW', '', '抓那隻。', 25549),
(124828, 'zhTW', '', '羽毛散了一地啊！', 25549),
(124827, 'zhTW', '', '俯衝！', 25549),
(124826, 'zhTW', '', '有時候輸贏就只差一支羽毛！', 25549),
(124825, 'zhTW', '', '別氣餒，再接再厲！', 25549),
(124824, 'zhTW', '', '正義從天而降！', 25549),
(124823, 'zhTW', '', '大酋長要我研究這個地區的鳥類，希望有一天能利用牠們向遠方傳遞訊息。由於這個地點位置非常好，離部落很多交易站都近，我找到很多稀有的鳥。想不想看看呢？', 25549),
(124821, 'zhTW', '燃燒軍團快把龍的法力吸光了。你要趕快出手幫忙！', '', 25549),
(124820, 'zhTW', '他已經盡全力逃跑了…我會陪他到最後一刻。$b$b謝謝你…你做的一切。我們都盡力了。', '', 25549),
(124819, 'zhTW', '', '如果要解救大門附近的盟友，就必須殺死這隻怪獸！', 25549),
(124818, 'zhTW', '', '這頭怪獸的身體不斷散發強大的力量。我猜艾莉珊德就是用牠來維持時光魔法。', 25549),
(124817, 'zhTW', '', '這裡可以通往宮殿的各處。我們可以從裡面把大門打開！', 25549),
(124816, 'zhTW', '', '時光魔法解除了！他們自由了！', 25549),
(124815, 'zhTW', '完美的計畫。英雄，祝你們好運。', '', 25549),
(124814, 'zhTW', '我們的部隊一定很困惑。我會告訴他們這裡發生什麼事，確保他們準備好繼續進攻。', '', 25549),
(124813, 'zhTW', '', '%s示意你跟著。', 25549),
(124812, 'zhTW', '', '我相信大法師賽倫善良的一面依然存在，只是此刻被瘋狂給蒙蔽了。', 25549),
(124811, 'zhTW', '', '我還有最後一個請求，$c。雖然賽倫不會對你手下留情，但是請不要殺死他。', 25549),
(124810, 'zhTW', '', '會花一點時間，不過我們或許能找到他。', 25549),
(124809, 'zhTW', '', '他的傳送門不穩定，但留下了一道蹤跡。', 25549),
(124804, 'zhTW', '吼！要是最近都沒有恢復演出的計畫，為什麼還要我一直穿著這件蠢戲服？！很癢耶…', '', 25549),
(124803, 'zhTW', '你必須跟著他通過傳送門。快！不然就來不及了！', '', 25549),
(124802, 'zhTW', '看來魔典控制了我，就像控制賽倫一樣…他現在還把虹膜也帶走了！', '', 25549),
(124801, 'zhTW', '夠了！放下武器…', '', 25549),
(124800, 'zhTW', '你太遲了！學徒薩納斯，解決他！', '', 25549),
(124799, 'zhTW', '嘿，看來你蠻厲害的？算了，還是別來阻止我好了！', '', 25549),
(124798, 'zhTW', '聚源虹膜會讓我成為有史以來最強大的法師！來阻止我看看啊！', '', 25549),
(124797, 'zhTW', '賽倫…你做了什麼好事？', '賽倫…你做了什麼好事？', 25549),
(124796, 'zhTW', '暗影…消失了？', '暗影…消失了？', 25549),
(124795, 'zhTW', '暗影…吞噬了我們…', '暗影…吞噬了我們…', 25549),
(124794, 'zhTW', '我差點…就死了…', '我差點…就死了…', 25549),
(124793, 'zhTW', '我…我在哪裡？', '我…我在哪裡？', 25549),
(124792, 'zhTW', '你需要加強訓練才行！', '你需要加強訓練才行！', 25549),
(124791, 'zhTW', '不對！你的姿勢完全錯誤！', '不對！你的姿勢完全錯誤！', 25549),
(124790, 'zhTW', '只有這點功夫，是無法擊敗燃燒軍團的！', '只有這點功夫，是無法擊敗燃燒軍團的！', 25549),
(124789, 'zhTW', '接班人…攻擊！', '', 25549),
(124788, 'zhTW', '等等…你不是這裡的學徒！你這冒牌貨，接招！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(124787, 'zhTW', '你要小心啊，弄錯答案有害健康。我可不是在開玩笑的！', '', 25549),
(124786, 'zhTW', '你很努力…但是徹頭徹尾，完全用錯方法了！', '', 25549),
(124785, 'zhTW', '你在…用蠻力對付屏障嗎？我可不是這樣教你的！', '', 25549),
(124784, 'zhTW', '次序很重要，學徒！你最好再複習一下你的筆記。', '', 25549),
(124783, 'zhTW', '玩夠了沒？！都被你弄得一團亂了！', '', 25549),
(124782, 'zhTW', '一定很痛。', '', 25549),
(124781, 'zhTW', '不對不對！不是那個啊！', '', 25549),
(124780, 'zhTW', '拜託，老是有人在門口死掉，叫我怎麼專心！', '', 25549),
(124779, 'zhTW', '那是什麼聲音？', '', 25549),
(124778, 'zhTW', '$ct，你能在離開前先過來一趟嗎？', '', 25549),
(124777, 'zhTW', '我不能丟下花瓶！它對主人太重要了！', '', 25549),
(124776, 'zhTW', '', '你們這些臭水狗出過海嗎？！', 25549),
(124775, 'zhTW', '', '臭巨魔，快回去工作！真不知道幹嘛要付你薪水！', 25549),
(124774, 'zhTW', '', '別再鬼混啦，這麼想走跳板嗎！', 25549),
(124773, 'zhTW', '看來你們沒事了，斯卡列斯。你應該趁還有機會的時候，帶著女兒盡快離開這裡。', '看來你們沒事了，斯卡列斯。你應該趁還有機會的時候，帶著女兒盡快離開這裡。', 25549),
(124772, 'zhTW', '', '我不會讓噁心的惡魔碰我的女兒。', 25549),
(124771, 'zhTW', '我沒辦法丟下我的孩子！他們一定還在躲…$b$b\n拜託，幫我找到他們！', '', 25549),
(124770, 'zhTW', '我就在你背後！走吧！', '', 25549),
(124769, 'zhTW', '注意背後！', '', 25549),
(124768, 'zhTW', '你以為能逃離艾莉珊德的掌控嗎？去死吧，叛徒！', '你以為能逃離艾莉珊德的掌控嗎？去死吧，叛徒！', 25549),
(124767, 'zhTW', '血精靈和$r坐在一起討論計策。嗯，這一點都不奇怪。', '', 25549),
(124766, 'zhTW', '很高興有其他人來幫忙。雖然用了隱形術，但我只能闖到這裡了。他們是不是有辦法偵測隱形生物？', '', 25549),
(124765, 'zhTW', '我會保護你們的。我們走吧！', '我會保護你們的。我們走吧！', 25549),
(124764, 'zhTW', '', '燃燒軍團在這裡勢力強大。盡量不要引起他們注意，$r。', 25549),
(124763, 'zhTW', '哼，好狗運！', '', 25549),
(124762, 'zhTW', '哈！再試一次。', '', 25549),
(124761, 'zhTW', '', '小心行動，這裡是燃燒軍團的勢力範圍。$b$b夜裔是不是忘記先祖之戰有多慘烈了？照這樣下去，只會毀滅和死亡。', 25549),
(124760, 'zhTW', '我猜它應該跟賽倫教導學徒的順序有關。\n\n但是我才剛開始學習秘法而已，所以我不知道其他的順序是什麼。', '', 25549),
(124759, 'zhTW', '等全部的酒桶都閃白光，就表示你可以選擇了。', '', 25549),
(124758, 'zhTW', '仔細看好，等酒桶停下來的時候再選擇正確的酒桶。', '', 25549),
(124757, 'zhTW', '我會亂轉這些酒桶，不過開始轉之前，裡面還有酒的酒桶會閃一下黃光。', '', 25549),
(124756, 'zhTW', '呃…你好。有什麼需要我幫忙的嗎？', '', 25549),
(124755, 'zhTW', '當然是要玩個遊戲囉！', '', 25549),
(124754, 'zhTW', '你好啊，$n。你想知道我們喝到剩下一桶酒的時候怎麼辦嗎？', '', 25549),
(124753, 'zhTW', '', '我？我什麼都不知道，我只知道千萬不要相信威克茲說的話。\n\n那個變態傢伙最喜歡看其他學徒被那個謎題給活活燒死。', 25549),
(124752, 'zhTW', '', '不管怎樣，除非你知道正確的順序，否則千萬不要亂碰那些寶石。\n\n我見過按錯的人會有什麼下場，那可真是悽慘啊。', 25549),
(124751, 'zhTW', '喔，那個啊？\n\n好吧，我就把我知道的事情告訴你：第一顆寶石絕對是火…\n\n<威克茲低聲笑著。>', '', 25549),
(124750, 'zhTW', '為什麼要騷擾我？\n\n你以為袍子比較帥氣就可以來欺負我們嗎？', '', 25549),
(124749, 'zhTW', '你要穿過屏障？祝你好運，$g老兄:伙計;。\n\n任何的水晶都不要碰兩次，聽清楚了嗎？碰兩次的人都會發生壞事。', '', 25549),
(124748, 'zhTW', '我整天都很認真在練習，希望大法師會注意到我，可是卻一點用也沒有！\n\n我甚至懷疑，他到底有沒有要再收學徒…', '', 25549),
(124747, 'zhTW', '有個學徒很肯定地告訴過我，正確的順序就是從右到左。\n\n他的名字好像是…亨里克？', '', 25549),
(124746, 'zhTW', '我相信只要我認真學習，賽倫就會讓我入塔。\n\n要是能找到一頂跟你一樣的帽子，那也沒什麼不好。', '', 25549),
(124745, 'zhTW', '', '我看過有個學徒進去，但是我只看見他在啟動紅色的寶石前，先啟動了白色的寶石。', 25549),
(124744, 'zhTW', '', '以前我也有一件跟你一樣帥氣的衣服，但是我已經厭倦了其他學徒的挑戰。\n\n我相信賽倫會因為我施法的本領而讓我入塔。', 25549),
(124743, 'zhTW', '', '有個高階學徒曾經告訴我，「必須先精通傳統的流派系別，才能深入暗影之境」。\n\n那應該是某種提示。', 25549),
(124742, 'zhTW', '你知道屏障謎題的事情嗎？', '你知道屏障謎題的事情嗎？', 25549),
(124741, 'zhTW', '', '沒錯，賽倫是有點不太正常，但他畢竟是個出名的大法師啊！想想看，我能從他身上學到多少東西！', 25549),
(124740, 'zhTW', '伊尼亞斯，你該走了。', '伊尼亞斯，你該走了。', 25549),
(124739, 'zhTW', '我的兒子在混亂中受傷了…我抬不動他。求求你，幫幫我們！', '', 25549),
(124738, 'zhTW', '你必須離開這裡。這裡不安全！', '你必須離開這裡。這裡不安全！', 25549),
(124737, 'zhTW', '他…他們突然出現。蘿內特…我的孩子！嗚…', '', 25549),
(124736, 'zhTW', '', '我在走了！', 25549),
(124735, 'zhTW', '爸爸！', '', 25549),
(124730, 'zhTW', '你爸爸會帶你去安全的地方。快點下樓！', '你爸爸會帶你去安全的地方。快點下樓！', 25549),
(124729, 'zhTW', '我聽到尖叫聲！我好怕！', '', 25549),
(124728, 'zhTW', '你爸爸在樓下等你…快啊！', '你爸爸在樓下等你…快啊！', 25549),
(124727, 'zhTW', '', '媽…媽媽叫我躲…躲起來。', 25549),
(124725, 'zhTW', '', '挑戰？好吧，但是我警告你。賽倫已經教我精通了冰系魔法。', 25549),
(124722, 'zhTW', '反正我一直覺得那頂帽子很蠢…', '', 25549),
(124721, 'zhTW', '哼，可惡！想要就拿走吧！', '', 25549),
(124720, 'zhTW', '來單挑吧，我想要你的帽子！', '來單挑吧，我想要你的帽子！', 25549),
(124719, 'zhTW', '先是什麼愚蠢的試煉，然後現在又要我挖掘積滿灰塵的古老廢墟。這東西最好真的有這個價值。\n\n什麼？你走開啦。我正在…考古…', '', 25549),
(124718, 'zhTW', '', '嘿，大德魯伊！這裡！', 25549),
(124712, 'zhTW', '喂，$r！你在找什麼東西嗎？', '', 25549),
(124710, 'zhTW', '燃燒軍團一定是想利用翡翠夢魘凋萎展開行動。我或許是它們第一個目標，但我想不會是最後一個。我們一定要找出領軍攻擊我們人民的惡魔，並且擊敗它。', '', 25549),
(124709, 'zhTW', '我們一定能解決這個問題。', '我們一定能解決這個問題。', 25549),
(124708, 'zhTW', '燃燒軍團想腐化我？$b$b人類國王之死讓我內心動盪。我選他成為我的勇士，不只是因為他的勇猛，更是因為他能克服嗜血本性、堅守信念並守護人民。他死後我進入翡翠夢境沉思。$b$b在這段時間，居然被燃燒軍團找到了。', '', 25549),
(124707, 'zhTW', '燃燒軍團想要腐化你。', '燃燒軍團想要腐化你。', 25549),
(124706, 'zhTW', '我…不太舒服。發生什麼事了？', '', 25549),
(124705, 'zhTW', '希望賽倫把你變成蟑螂…', '', 25549),
(124704, 'zhTW', '夠了！夠了！這麼想要這該死的長袍就拿走吧！', '', 25549),
(124703, 'zhTW', '你以為能打敗我？！那如果有五個我呢？！', '', 25549),
(124702, 'zhTW', '呃，我需要你的長袍…', '呃，我需要你的長袍…', 25549),
(124701, 'zhTW', '那些哥布林好像已經搜刮過這座遺跡了。\n\n照這個速度，我不知道什麼時候才能找到大法師看得上眼的東西！', '', 25549),
(124700, 'zhTW', '', '我跟艾露莉亞說你一定會來救我，她只是冷笑。看看現在是誰在笑！', 25549),
(124699, 'zhTW', '', '啊，終於自由了！謝謝你，外來者。', 25549),
(124698, 'zhTW', '', '夜井已經是過去式了。我們虧欠艾澤拉斯的人民太多，一定要記取教訓。', 25549),
(124697, 'zhTW', '嗯，應該讓你知道。來看看我們的新家吧…', '', 25549),
(124696, 'zhTW', '諾瑞莎！沒想到還能見到你…', '', 25549),
(124695, 'zhTW', '', '發生什麼事都告訴我。女兒怎麼樣了…', 25549),
(124694, 'zhTW', '', '阿布撒隆！你怎麼了？', 25549),
(124693, 'zhTW', '', '我可以去邊境，謝謝你！請幫我告訴阿布撒隆，我快到了！', 25549),
(124692, 'zhTW', '', '是…你！是你送信的！', 25549),
(124691, 'zhTW', '', '毀掉它吧。', 25549),
(124690, 'zhTW', '薩莉瑟拉？你決定吧…', '', 25549),
(124689, 'zhTW', '', '我們可以讓它穩定！雖然現在不需要夜井也能存活，但我們仍然可以利用這股力量…', 25549),
(124688, 'zhTW', '你的靈魂就是燃燒軍團的燃料！', '你的靈魂就是燃燒軍團的燃料！', 25549),
(124687, 'zhTW', '夜井快不行了。沒有阿曼蘇爾之眼，夜井變得很不穩定。', '', 25549),
(124686, 'zhTW', '', '我以為沒機會再看到它了！', 25549),
(124685, 'zhTW', '', '夜井…', 25549),
(124684, 'zhTW', '我拿到所有材料了。', '我拿到所有材料了。', 25549),
(124683, 'zhTW', '', '每次行動都讓我們離勝利更近一步。', 25549),
(124682, 'zhTW', '', '勇士，蘇拉瑪爾需要你挺身作戰。', 25549),
(124681, 'zhTW', '', '做得好，勇士。部落與你並肩作戰！', 25549),
(124680, 'zhTW', '', '敵人不休息，我們也不該休息！', 25549),
(124679, 'zhTW', '', '你真是可靠的盟友，謝謝你，勇士。', 25549),
(124678, 'zhTW', '', '夜落精靈需要你幫忙。你願意幫忙嗎？', 25549),
(124672, 'zhTW', '|TInterface\\Icons\\spell_warlock_demonicportal_green.blp:20|t%s開始開啟|cFFFF0000|Hspell:229610|h[惡魔傳送門]|h|r！跟著他傳過去！', '', 25549),
(124671, 'zhTW', '|TInterface\\Icons\\inv_legionadventure.blp:20|t%s下令|cFFFF0000|Hspell:229284|h[轟炸]|h|r！', '', 25549),
(124670, 'zhTW', '本來只是趟單純的跑腿。把貨物帶去群島，就能領到酬勞。$b$b現在這樣下去老闆一定會把我殺了！', '', 25549),
(124669, 'zhTW', '小心啊，掉下去可不得了。', '', 25549),
(124668, 'zhTW', '', '我懂了！', 25549),
(124667, 'zhTW', '', '這樣感覺好多了。', 25549),
(124666, 'zhTW', '握劍時手放輕鬆。不用抓這麼緊。', '', 25549),
(124665, 'zhTW', '控制呼吸，攻擊時用力吐氣。', '', 25549),
(124664, 'zhTW', '肩膀放鬆。這麼僵硬不行的。', '', 25549),
(124663, 'zhTW', '', '這樣如何？', 25549),
(124662, 'zhTW', '', '你覺得呢？', 25549),
(124661, 'zhTW', '', '我做對了嗎？', 25549),
(124660, 'zhTW', '', '知道了，西爾格林。', 25549),
(124657, 'zhTW', '', '我好像抓到感覺了。', 25549),
(124656, 'zhTW', '你站得不太穩，記得雙腳要與肩同寬。', '', 25549),
(124655, 'zhTW', '', '像這樣？', 25549),
(124654, 'zhTW', '我看不到滲透進來的敵人。卡德加，你可以幫我嗎？', '我看不到滲透進來的敵人。卡德加，你可以幫我嗎？', 25549),
(124653, 'zhTW', '絕對不能讓古爾丹使用夜井。', '', 25549),
(124652, 'zhTW', '這些精靈都好焦躁。祈倫托已經盡力維護秩序了。', '', 25549),
(124651, 'zhTW', '看來這種情況很不妙。我們要盡快出擊…', '', 25549),
(124650, 'zhTW', '', '好了，別再煩我。', 25549),
(124649, 'zhTW', '', '住手…你是比我更強的學徒。披肩給你…', 25549),
(124648, 'zhTW', '', '小心了！', 25549),
(124647, 'zhTW', '朋友，你惹錯哥布林了。看我的火球術！', '', 25549),
(124646, 'zhTW', '這工作真是有損我的格調。', '', 25549),
(124645, 'zhTW', '炫炫，回到我身邊！', '', 25549),
(124644, 'zhTW', '我想要你的披肩。', '我想要你的披肩。', 25549),
(124643, 'zhTW', '不！', '', 25549),
(124642, 'zhTW', '', '這座塔已經荒廢了很多年，裡面一定有數不清的寶物。\n\n等我拿到寶物，賽倫就會對我另眼相看，收我當他的上級弟子。好了，現在我只需要打開這個門…', 25549),
(124641, 'zhTW', '快看我！', '', 25549),
(124640, 'zhTW', '祝你好運！', '', 25549),
(124639, 'zhTW', '避開不穩定的能量團，還有…盡量別掉下去，好嗎？', '', 25549),
(124638, 'zhTW', '記得要穿過光球，才能補充能量，繼續使用我給你的穿梭能力。噢，還有…', '', 25549),
(124637, 'zhTW', '我會在你身上施法，讓你可以在空中衝刺穿梭。努力飛往遠處的目的地吧。', '', 25549),
(124636, 'zhTW', '我們又見面了，$n。你有沒有發現這個地方的地脈能量似乎漫無章法？', '', 25549),
(124635, 'zhTW', '逃吧，小老鼠！', '', 25549),
(124634, 'zhTW', '逃跑的，殺無赦！', '', 25549),
(124633, 'zhTW', '想活著就別出來！', '', 25549),
(124632, 'zhTW', '待在屋子裡！', '', 25549),
(124631, 'zhTW', '誰在那裡？', '誰在那裡？', 25549),
(124630, 'zhTW', '似乎有些不對勁…', '似乎有些不對勁…', 25549),
(124629, 'zhTW', '是幻象！你在隱藏什麼？', '是幻象！你在隱藏什麼？', 25549),
(124628, 'zhTW', '燃燒軍團讓這個地方面目全非，幸好有你，這裡才能夠恢復和平。', '', 25549),
(124626, 'zhTW', '我的防禦…應該無懈可擊…', '', 25549),
(124622, 'zhTW', '燃燒軍團已經入侵到維爾薩拉的核心了！防衛者需要你的幫忙，才有擊退惡魔的希望。', '', 25549),
(124621, 'zhTW', '他們從哪裡來的？', '他們從哪裡來的？', 25549),
(124620, 'zhTW', '這種事一定有報應的。', '這種事一定有報應的。', 25549),
(124619, 'zhTW', '其他人！先幫其他人！', '其他人！先幫其他人！', 25549),
(124618, 'zhTW', '我不要這樣…', '我不要這樣…', 25549),
(124617, 'zhTW', '盡你所能，$n，但請務必小心。', '盡你所能，$n，但請務必小心。', 25549),
(124616, 'zhTW', '', '卡多雷，進攻集合場！伊露恩引領我們淨化這座城市！', 25549),
(124615, 'zhTW', '', '辛多雷，保衛漫步宏園，堅守陣線！今天聖光會把敵人就地正法！', 25549),
(124614, 'zhTW', '', '夏多雷，時候到了，我們奪回屬於我們的城市吧！前進！Anath''ashar! (為榮耀而戰！)', 25549),
(124613, 'zhTW', '薩莉瑟拉，你可以發動攻擊了。', '', 25549),
(124612, 'zhTW', '', '或許可以破例一下。', 25549),
(124611, 'zhTW', '', '我撐得住。多年來的訓練讓我很有毅力。', 25549),
(124610, 'zhTW', '', '我遇過更糟的。', 25549),
(124609, 'zhTW', '', '我們一起對抗燃燒軍團。', 25549),
(124608, 'zhTW', '', '我的忠誠毋庸置疑。', 25549),
(124607, 'zhTW', '', '不能放過艾莉珊德。', 25549),
(124606, 'zhTW', '', '我只對蘇拉瑪爾效忠。', 25549),
(124605, 'zhTW', '', '嗯？', 25549),
(124604, 'zhTW', '', 'Tenu''balah. (你好。)', 25549),
(124603, 'zhTW', '', '哈囉。', 25549),
(124602, 'zhTW', '', '你好。', 25549),
(124601, 'zhTW', '', '這比凋萎的過程更難忍受。', 25549),
(124600, 'zhTW', '', '我沒有東西能給你。', 25549),
(124599, 'zhTW', '', '我不知道你為什麼還在對我說話。', 25549),
(124598, 'zhTW', '', '再會。', 25549),
(124597, 'zhTW', '', '再見。', 25549),
(124596, 'zhTW', '', '明白。', 25549),
(124595, 'zhTW', '', '你好。', 25549),
(124594, 'zhTW', '', '嗯？', 25549),
(124593, 'zhTW', '', '你說，我在聽。', 25549),
(124592, 'zhTW', '', '你好。', 25549),
(124591, 'zhTW', '', '哈囉。', 25549),
(124590, 'zhTW', '', '你為什麼會在這種時候來沙亞蘭？', 25549),
(124589, 'zhTW', '看他變成這個樣子，真讓我心痛。', '', 25549),
(124588, 'zhTW', '我們的老友就躺在裡面休息。', '', 25549),
(124587, 'zhTW', '火力全開！', '', 25549),
(124586, 'zhTW', '為了黑暗女王！', '', 25549),
(124585, 'zhTW', '把這些惡魔送回地獄！開火！', '', 25549),
(124584, 'zhTW', '找到目標了！開火！', '', 25549),
(124583, 'zhTW', '所有砲台，朝目標攻擊！', '', 25549),
(124582, 'zhTW', '砲彈就緒了…發射！', '', 25549),
(124581, 'zhTW', '', '我們已經做好萬全的準備。一切就看薇兒塔了。如果她順利完成任務，一定第一個讓你知道。', 25549),
(124580, 'zhTW', '好吧。收攝心神。我們會用傳統的方式來試試你。', '', 25549),
(124579, 'zhTW', '我尋求月之守衛的智慧。', '我尋求月之守衛的智慧。', 25549),
(124578, 'zhTW', '這裡是月之爐，我們最偉大的法師都曾經在這裡接受試煉。你來這裡做什麼？', '', 25549),
(124577, 'zhTW', '外來者，你闖入聖地了。我希望你有正當的理由。', '', 25549),
(124576, 'zhTW', '你在找什麼，智慧？還是力量？還是你都想要？', '', 25549),
(124575, 'zhTW', '別擔心。我跟他們說要強化結界說了幾百年，一直沒人理我…', '', 25549),
(124574, 'zhTW', '他們的結界不會妨礙你傳送嗎？', '', 25549),
(124573, 'zhTW', '我想到了！可以集體傳送…不過我需要幫忙。', '', 25549),
(124572, 'zhTW', '', '泰亞恩已經完全失控了。要不是有你在，怪獸就會毀掉整個露臺。', 25549),
(124571, 'zhTW', '', '泰亞恩的實驗太過火了！竟然讓怪獸在露臺撒野。', 25549),
(124570, 'zhTW', '', '那些叛徒罪有應得。他們的惡行不會被歷史抹滅。', 25549),
(124569, 'zhTW', '', '艾莉珊德的佞臣跟侍女常常在暗夜之塔頂端的房間逗留。絕對不能給他們任何機會向燃燒軍團通報！', 25549),
(124568, 'zhTW', '', '我們就快了結混亂的局面了。艾莉珊德的時代到此為止！', 25549),
(124567, 'zhTW', '', '我們要是控制暗夜之塔，就能直取宮殿。快阻止儀式！', 25549),
(124566, 'zhTW', '', '只要切斷補給路線，宮殿就會陷入混亂！做得好。', 25549),
(124565, 'zhTW', '', '觀察宮殿裡的補給線，設法切斷。飛行管理員應該就在隊長營區附近。', 25549),
(124564, 'zhTW', '', '這是給那些濫用權力的人一個教訓。', 25549),
(124563, 'zhTW', '', '艾莉珊德的傀儡就在附近。如果它發生什麼意外，那就太不幸了…', 25549),
(124562, 'zhTW', '', '應該沒有人發現我們。快點，找到艾露莉亞，攻進大門！', 25549),
(124561, 'zhTW', '', '法多雷已經闖進宮殿裡了！在守衛發現之前阻止他們！', 25549),
(124560, 'zhTW', '', '願他們安息。夜井曾經維繫我們的生命，卻也在很多方面...變成痛苦的泉源。', 25549),
(124559, 'zhTW', '', '我祖先的靈魂被夜井困住了。一定要釋放他們，別再讓他們繼續受苦。', 25549),
(124558, 'zhTW', '', '光是想到被夜井強化的雙頭巨人，我就渾身發抖。謝謝你救了我們。', 25549),
(124557, 'zhTW', '', '有個雙頭巨人在地下墓穴亂闖！快阻止他，別再讓他繼續破壞！', 25549),
(124556, 'zhTW', '', '幾萬年來，我從不相信燃燒軍團會有辦法攻進這片林地。\n\n但無論如何，我絕不會讓它們越雷池一步！', 25549),
(124555, 'zhTW', '|TInterface\\Icons\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t海爾珈準備對|cFFFF0000$n|r施放|cFFFF0404|Hspell:228162|h[光明之盾]|h|r！', '|TInterface\\Icons\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t海爾珈準備對|cFFFF0000$n|r施放|cFFFF0404|Hspell:228162|h[光明之盾]|h|r！', 25549),
(124552, 'zhTW', '', '不！傳送門…', 25549),
(124551, 'zhTW', '', '見證無窮盡的燃燒軍團！', 25549),
(124550, 'zhTW', '', '又有靈魂給傳送門用了！', 25549),
(124549, 'zhTW', '不可能！你做了什麼？', '', 25549),
(124548, 'zhTW', '把結界準備好！', '', 25549),
(124546, 'zhTW', '我們會護送他到安全的地點。告訴薩莉瑟拉，我們成功了。', '', 25549),
(124545, 'zhTW', '<咳咳。>我需要…休息。謝謝。感謝你所做的一切。', '', 25549),
(124544, 'zhTW', '所有人的希望…都寄託在…暮色百合上。', '', 25549),
(124543, 'zhTW', '他們想拿我殺雞儆猴，我們要反過來利用他們。', '', 25549),
(124542, 'zhTW', '歡迎回來，老朋友。', '', 25549),
(124541, 'zhTW', 'Aran''ethil... (終於結束了…) 噩夢結束了！', '', 25549),
(124540, 'zhTW', '終於…解脫了…', '', 25549),
(124539, 'zhTW', '', '他不會有事的。吃顆果實就會好了。', 25549),
(124538, 'zhTW', '別動，朋友。我們會把你救出去。', '', 25549),
(124537, 'zhTW', '', '我不知道，希望不會太遲。', 25549),
(124536, 'zhTW', '', '我們還有多少時間？', 25549),
(124535, 'zhTW', '', '大博學者打算用他來殺雞儆猴。', 25549),
(124534, 'zhTW', '我會永遠感謝這份恩情！', '我會永遠感謝這份恩情！', 25549),
(124533, 'zhTW', '我讚美你，英雄！', '我讚美你，英雄！', 25549),
(124532, 'zhTW', '啊，好多了。謝謝你！', '啊，好多了。謝謝你！', 25549),
(124531, 'zhTW', '這…這只是皮肉之傷！我還能…啊！算了，我會重回防守的陣線。', '這…這只是皮肉之傷！我還能…啊！算了，我會重回防守的陣線。', 25549),
(124530, 'zhTW', '', '這比我想的還要好！我會為了接下來的步驟繼續改善的。', 25549),
(124528, 'zhTW', '我欠你一命！我會重回防守的陣線。', '我欠你一命！我會重回防守的陣線。', 25549),
(124527, 'zhTW', '', '我不想再看了。我應該可以降低惡魔法術對凋萎者的影響。先去靈魂引擎吧，我會再派新的實驗對象給你。', 25549),
(124526, 'zhTW', '謝謝你…我會重回防守的陣線。', '謝謝你…我會重回防守的陣線。', 25549),
(124525, 'zhTW', '或許吧。首席秘法師知道該怎麼辦。我們先把這些人帶去沙亞蘭。', '', 25549),
(124524, 'zhTW', '', '這些惡魔水晶有燃燒軍團的力量。我們應該看看凋萎者會怎麼反應。', 25549),
(124523, 'zhTW', '不！…我會變成…燃料…', '', 25549),
(124522, 'zhTW', '你什麼也不是！渺小的蟲子！', '', 25549),
(124521, 'zhTW', 'Shaza-kiel! (交出你的靈魂吧！)', '', 25549),
(124520, 'zhTW', '我很高興能碾碎你的靈魂！', '', 25549),
(124519, 'zhTW', '哈！你這是自找死路，凡人！', '', 25549),
(124517, 'zhTW', '這些傳送之球已經可以正常使用了，但我們最好保守秘密，等時機到了再用。', '', 25549),
(124516, 'zhTW', '', '我們不能再放任不管了。', 25549),
(124515, 'zhTW', '', '在弦月旅店事件後，對這種事我一點都不意外。', 25549),
(124514, 'zhTW', '', '我們被發現了！', 25549),
(124513, 'zhTW', '這樣應該可以了，座標數據應該可以調…啊，別管我，總之你做得不錯。', '', 25549),
(124512, 'zhTW', '很好，準備好就開始吧。記得用勘測係數代入調校基準，然後…呃，光，跟著光就對了！', '', 25549),
(124511, 'zhTW', '', '好，我派你去找西爾格林。經過他的訓練，你會變得更強。', 25549),
(124510, 'zhTW', '', '你一定是亞魯因的姊姊。我們欠他太多。他的犧牲不會白費。', 25549),
(124509, 'zhTW', '', '首席秘法師，很榮幸終於能見到你。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(124507, 'zhTW', '', '我弟弟在這裡安息。我叫亞魯艾兒。', 25549),
(124506, 'zhTW', '', '奧肯多爾的果實讓我恢復神智，免於瘋狂。我已經恢復了，我要戰鬥。', 25549),
(124505, 'zhTW', '', '還記得我嗎，外來者？', 25549),
(124504, 'zhTW', '', '她就在外頭等你。', 25549),
(124503, 'zhTW', '你來得正好，德林。', '', 25549),
(124502, 'zhTW', '這裡！大家上船！', '', 25549),
(124501, 'zhTW', '希望她能看到…', '', 25549),
(124500, 'zhTW', '你稍微休息一下。但我們不能耽擱太久。', '', 25549),
(124499, 'zhTW', 'DELETE', '', 25549),
(124498, 'zhTW', '', '請讓凋萎者準備好，以防萬一。祝你好運。', 25549),
(124497, 'zhTW', '我來負責傳送。他們一定會嚇一大跳！', '', 25549),
(124496, 'zhTW', '', '好了，屏障應該解除了。', 25549),
(124495, 'zhTW', '', '嗯，那我就開始了。我完成的時候，剛剛「調整」過的設備都會停止運作。', 25549),
(124494, 'zhTW', '', '目前我不敢輕舉妄動。我想先回沙亞蘭好好研究一下。', 25549),
(124493, 'zhTW', '', '嗯…看來他們正在把部分的地脈能量重新導向秩序聖所。', 25549),
(124492, 'zhTW', '', '我不懂…', 25549),
(124491, 'zhTW', '', '這種低俗的行為，簡直跟矮人一樣…', 25549),
(124490, 'zhTW', '', '哼，還真幼稚。', 25549),
(124489, 'zhTW', '', '嗯...精巧的掩護法術，不過這個裝置是什麼？繼續調查。', 25549),
(124488, 'zhTW', '', '誰會把這麼羞辱人的東西扔在這裡？', 25549),
(124487, 'zhTW', '', '那些住在城裡又親近惡魔的自戀狂！', 25549),
(124486, 'zhTW', '', '有人在汲取這裡的地脈能量，但我看不出來…啊！我有個主意。', 25549),
(124485, 'zhTW', '朋友，為了蘇拉瑪爾，請你一定要幫忙。我的族人生死存亡都看你了。', '', 25549),
(124484, 'zhTW', '勇士！我需要你的協助，有一件非常重要的事情。', '', 25549),
(124483, 'zhTW', '勇士！再次展現力量與技巧的時候到了！', '', 25549),
(124482, 'zhTW', '聽到牠們安全了，我很欣慰。嗯，或許我應該考慮領養幾隻…', '', 25549),
(124481, 'zhTW', '梟羽獸王釉倫想把幼獸帶回家，卻遇到了問題。看看那些水汪汪的眼睛，勇士。絕對不能讓這些幼獸遭遇危險！', '', 25549),
(124480, 'zhTW', '', '我來幫你吧。這個形態下不適合在這麼小的地方戰鬥，而且我們已經有這位厲害的勇士了。', 25549),
(124479, 'zhTW', '', '大德魯伊，我跟我的部下會隨你作戰。一定要恢復世界的平衡！', 25549),
(124478, 'zhTW', '', '你最大的試煉就在眼前。你一定要為艾澤拉斯永久斬除燃燒軍團這個毒瘤。', 25549),
(124477, 'zhTW', '', '大德魯伊，我看得出來你每克服一次試煉，力量就更進一步。', 25549),
(124476, 'zhTW', '這種程度的腐化已經無法消除，但至少你暫時遏止擴散了…', '', 25549),
(124473, 'zhTW', '蘇拉瑪爾還有夏達希爾腐化的餘孽。邪惡薩特的角應該派得上用場。', '', 25549),
(124471, 'zhTW', '勇士，我知道你已經為這場戰爭犧牲很多，但情勢恐怕不妙。', '', 25549),
(124470, 'zhTW', '看來你們有某種牽絆。無論有多小…夥伴就是夥伴！', '', 25549),
(124469, 'zhTW', '岸邊有個不尋常的生物在挑戰當地的龍蝦人。牠似乎跟你有某種關聯…去幫助牠吧，勇士！', '', 25549),
(124468, 'zhTW', '看來跳舞真的很危險！你可別腳癢亂來。', '', 25549),
(124467, 'zhTW', '黑羽在上次的…事件之後，推舉了新的酋長。看來他們還想再試一次那個儀式。', '', 25549),
(124466, 'zhTW', '幹得好，勇士。你確實擁有風暴之力！', '', 25549),
(124465, 'zhTW', '有一場凜冽風暴在公羊山頂醞釀。消滅風暴的源頭，否則整片大地都會陷入寒冰之中！', '', 25549),
(124464, 'zhTW', '', '這是最後的了。鬆開這個結，能量就可以再度自由流動。$b$b希望你已經準備好了。', 25549),
(124463, 'zhTW', '', '解決了一個，還剩下兩個。你準備好了就告訴我。', 25549),
(124462, 'zhTW', '', '啊，你來了。我以為可以在這裡找到線索，但是…', 25549),
(124461, 'zhTW', '', '我記得這種力量…克爾巴洛！我們得去緋紅灌木林一趟。', 25549),
(124460, 'zhTW', '', '嗯？你想知道什麼？', 25549),
(124459, 'zhTW', '', '沒錯。匯聚的地脈能為夜井提供非常豐沛的能量。操控這種能量非常危險，要是她能辦到…', 25549),
(124458, 'zhTW', '', '謝謝你，勇士。絕對不能讓卓格巴破壞我們的生活方式。高嶺永存！', 25549),
(124457, 'zhTW', '', '放肆的卓格巴把我們的補給箱都丟到谷底了。幸好我們有個好辦法可以拿回來…', 25549),
(124456, 'zhTW', '', '秩序恢復了！非常感謝你的協助，勇士。為了高嶺！', 25549),
(124455, 'zhTW', '', '卓格巴在雷霆圖騰部族那裡撒野，破壞我們重要的鼓，追趕我們的牲畜。一定要阻止他們！', 25549),
(124454, 'zhTW', '', '你引導這股龐大法力的方式非常高明。這可不是件容易的事。', 25549),
(124453, 'zhTW', '%s查看了碎片。', '', 25549),
(124452, 'zhTW', '', '你真的能「看見」地脈嗎？或者只是一種感覺？是隨時都能感應到，還是你可以…呃，打開或關掉？', 25549),
(124451, 'zhTW', '', '你先去通知薩莉瑟拉。我有幾件事想請教我們這位朋友。', 25549),
(124450, 'zhTW', '', '我很清楚她有什麼能耐。所以，我們才要阻止她。', 25549),
(124449, 'zhTW', '', '你真是個不錯的幫手。你對地脈的了解可以說跟我不相上下。', 25549),
(124448, 'zhTW', '', '回沙亞蘭之前我得先休息一下。這比我原本想的還要累…', 25549),
(124447, 'zhTW', '%s很崇拜你。', '', 25549),
(124446, 'zhTW', '%s開心地叫著。', '', 25549),
(124445, 'zhTW', '%s看起來很滿足。', '', 25549),
(124444, 'zhTW', '呼嚕…', '呼嚕…', 25549),
(124443, 'zhTW', '%s在冒險後感到疲倦。', '', 25549),
(124442, 'zhTW', '', '勇士小心，它來了！', 25549),
(124441, 'zhTW', '', '不管你有什麼計畫，動作要快。我感覺到好像有什麼東西...很餓！', 25549),
(124440, 'zhTW', 'unused do not translate', '', 25549),
(124438, 'zhTW', '那些…那些…夜精靈！', '那些…那些…夜精靈！', 25549),
(124437, 'zhTW', '那些落後的卡多雷臭猴子。', '那些落後的卡多雷臭猴子。', 25549),
(124436, 'zhTW', '他們去哪裡找材料來做這種東西？', '他們去哪裡找材料來做這種東西？', 25549),
(124435, 'zhTW', '我想跟隨機的敵人戰鬥！', '我想跟隨機的敵人戰鬥！', 25549),
(124434, 'zhTW', '我連這是什麼做的都不知道。', '我連這是什麼做的都不知道。', 25549),
(124433, 'zhTW', '這是在開玩笑嗎？！', '這是在開玩笑嗎？！', 25549),
(124432, 'zhTW', '', '凋萎者…一碰到魔能就不行了。求求你…盡量救他們。別管我…我的傷口不要緊！', 25549),
(124431, 'zhTW', '', '我才不會親自對付你。魔裔，殺光他們！', 25549),
(124430, 'zhTW', '', '讓我來看看反抗軍的膽識！把你最強的勇士派來黎利斯的莊園找我，否則我就繼續找居民來...問話了！', 25549),
(124429, 'zhTW', '', '可憐的薩莉瑟拉…你這麼努力想救族人，卻害他們不能接近夜井，不能恢復原狀！黎利斯只好為你的狂妄付出代價。', 25549),
(124428, 'zhTW', '', '你就看看這些「殭屍」的厲害吧。攻擊！', 25549),
(124427, 'zhTW', '', '哈！你就帶了這些人？一個外來者和一群連法力都沒得吸的殭屍？看來你過得很慘啊！', 25549),
(124426, 'zhTW', '', '艾莉珊德選你當首席秘法師？看來她手下沒什麼人才了。快放了黎利斯！', 25549),
(124425, 'zhTW', '吧嚕！', '吧嚕！', 25549),
(124424, 'zhTW', '咿？', '咿？', 25549),
(124423, 'zhTW', '呃…', '呃…', 25549),
(124422, 'zhTW', '我對這個只是稍微感興趣。', '', 25549),
(124421, 'zhTW', '我準備好了，薇兒塔。', '我準備好了，薇兒塔。', 25549),
(124420, 'zhTW', '', '$n，你準備好開始進行儀式了嗎？', 25549),
(124419, 'zhTW', '', '這個洞穴真的很隱密。我很驚訝歐庫雷斯竟然能把我們安全送過來。', 25549),
(124418, 'zhTW', '', '溫暖舒適，沒人打擾，還有充沛的秘法能量。說不定我該在這裡設個研究室…', 25549),
(124417, 'zhTW', '戰鬥領主，你再次挺身而出，拯救了艾澤拉斯。我代表全體議會成員感謝你。', '', 25549),
(124416, 'zhTW', '虛空領主，你再次挺身而出，拯救了艾澤拉斯。我代表全體議會成員感謝你。', '', 25549),
(124415, 'zhTW', '先知，你再次挺身而出，拯救了艾澤拉斯。我代表全體議會成員感謝你。', '', 25549),
(124414, 'zhTW', '影尊，你再次挺身而出，拯救了艾澤拉斯。我代表全體議會成員感謝你。', '', 25549),
