INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(123154, 'zhTW', '召喚寵物，讓你的寵物幫你作戰。', '', 25549),
(123152, 'zhTW', '有忠實的寵物在身邊，你就能克服任何環境阻礙。召喚寵物可以把寵物呼喚到你身邊。', '', 25549),
(123151, 'zhTW', '生存獵人擅長近戰攻擊，可以利用多種招式的組合攻擊來壓制對手。', '', 25549),
(123150, 'zhTW', '生存獵人擅長近戰攻擊，可以利用多種招式的組合攻擊來壓制對手。', '', 25549),
(123149, 'zhTW', '時間不夠了！這種環境怎麼工作！', '時間不夠了！這種環境怎麼工作！', 25549),
(123148, 'zhTW', '再這樣下去，我們會需要更多塗料。', '再這樣下去，我們會需要更多塗料。', 25549),
(123147, 'zhTW', '', '只要我們還受到詛咒，就不可能和法隆迪斯和平共處！', 25549),
(123146, 'zhTW', '', '我們受到詛咒都是法隆迪斯害的…他必須付出代價！', 25549),
(123145, 'zhTW', '使用薩滿之怒！', '', 25549),
(123144, 'zhTW', '', '使用薩滿之怒！', 25549),
(123143, 'zhTW', '如果你把你的凋萎者留在後方，他們會迷路！', '如果你把你的凋萎者留在後方，他們會迷路！', 25549),
(123142, 'zhTW', '賓客注意：殺！殺！殺！', '', 25549),
(123141, 'zhTW', '已經消滅！', '', 25549),
(123140, 'zhTW', '正在超載。準備 - 清除！清除！清除！', '', 25549),
(123139, 'zhTW', '館長無法…運…作…了。', '', 25549),
(123138, 'zhTW', '展示廳只對來賓 - 消滅！消滅！', '', 25549),
(123135, 'zhTW', '秘能酒發酸了…你必須從頭來過！', '秘能酒發酸了…你必須從頭來過！', 25549),
(123134, 'zhTW', '風中充斥血腥味。', '這就是你要搭的船，$n。願聖光與你同在。', 25549),
(123133, 'zhTW', '你確定想要跳過破碎海岸的劇情嗎？\n你之後可以在破碎群島的達拉然找到古卷管理者伊萊席娜，重新接受這個任務。', '你確定想要跳過破碎海岸的劇情嗎？\n你之後可以在破碎群島的達拉然找到古卷管理者伊萊席娜，重新接受這個任務。', 25549),
(123132, 'zhTW', '我聽過這個故事了…<跳過《軍臨天下》起始任務，直接開始達拉然的冒險。>', '我聽過這個故事了…<跳過《軍臨天下》起始任務，直接開始達拉然的冒險。>', 25549),
(123126, 'zhTW', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t歐丁開始從符文|cFFFF0404|Hspell:227503|h[吸取能量]|h|r！', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t歐丁開始從符文|cFFFF0404|Hspell:227503|h[吸取能量]|h|r！', 25549),
(123124, 'zhTW', '', '咕嚕莫咕莫莫咕！', 25549),
(123123, 'zhTW', '', '莫咕莫咕嚕咕嚕姆。', 25549),
(123122, 'zhTW', '', '莫咕嚕咕嚕莫咕嚕莫咕嚕咕嘎。', 25549),
(123121, 'zhTW', '真不敢相信，你不是在開玩笑吧？', '', 25549),
(123120, 'zhTW', '', '莫咕嚕莫咕嚕。', 25549),
(123119, 'zhTW', '我就知道會發生從來沒看過的事，絕對會。但這超乎我的想像了。', '', 25549),
(123118, 'zhTW', '', '咕嚕莫咕莫嚕咕嚕莫嚕。', 25549),
(123117, 'zhTW', '或者我們見過面？', '', 25549),
(123116, 'zhTW', '', '莫咕嚕咕嚕嘎咕。', 25549),
(123115, 'zhTW', '你把我認成其他人了？', '', 25549),
(123114, 'zhTW', '好了！你們已證明自己的價值！由你們擔任我的勇士，黑爾雅必敗無疑，我的詛咒也會破除。', '', 25549),
(123113, 'zhTW', '我沒辦法到逆風小徑上方的達拉然協助你。請直接將我傳送到破碎群島上方的達拉然。', '我沒辦法到逆風小徑上方的達拉然協助你。請直接將我傳送到破碎群島上方的達拉然。', 25549),
(123112, 'zhTW', '燃燒軍團正在逆風小徑大舉進攻達拉然。這似乎佔據了他們所有的注意力。\n\n我直接在這裡完成儀式，我們再到破碎群島上放碰頭如何？', '', 25549),
(123111, 'zhTW', '', '我沒有朋友…嗯...只有你，嘉琳德。', 25549),
(123110, 'zhTW', '', '我們都應該體驗一下飛翔！嘿，你覺得巫師有辦法幫我們嗎？', 25549),
(123109, 'zhTW', '', '當然啦，親愛的！不過最好還是把你那件舊長袍…喔！有新朋友來拜訪我們了。', 25549),
(123108, 'zhTW', '', '艾菲拉，快下來！你這樣到處亂飛，就跟那些糟糕的猴人沒兩樣！', 25549),
(123106, 'zhTW', '準備開戰吧，英雄！', '', 25549),
(123105, 'zhTW', '海姆達爾！海爾珈！測試一下這些凡人的能耐。我要知道他們有足夠的勇氣和本事面對未來的挑戰。', '', 25549),
(123104, 'zhTW', '各位勇士！你們擊敗了黑爾雅的手下。現在該是勇闖黑爾海姆，終結這個邪惡海巫的時候了！在此之前…還有最後的考驗！', '', 25549),
(123103, 'zhTW', '目前表現不錯…不過，我要來親自看看你們夠不夠資格！', '', 25549),
(123102, 'zhTW', '看來我下手太輕了。試試這個！', '', 25549),
(123101, 'zhTW', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t%s正在施展|cFFFF0000|Hspell:227508|h[群體懺悔]|h|r！', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t%s正在施展|cFFFF0000|Hspell:227508|h[群體懺悔]|h|r！', 25549),
(123100, 'zhTW', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t%s正在對你施展|cFFFF0000|Hspell:227789|h[神聖之地]|h|r！', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t%s正在對你施展|cFFFF0000|Hspell:227789|h[神聖之地]|h|r！', 25549),
(123099, 'zhTW', '|cffADFF2F+$1i夜落精靈聲望|r', '|cffADFF2F+$1i夜落精靈聲望|r', 25549),
(123098, 'zhTW', '除非能找出對付它們的辦法。', '', 25549),
(123097, 'zhTW', '進攻艾澤拉斯的只是燃燒軍團的一小部分。', '', 25549),
(123096, 'zhTW', '', '我失敗了，薩格拉斯…', 25549),
(123095, 'zhTW', '我們分頭行動比較好。我去解除這座塔的魔法防禦機制。你可以考慮用更…直接的方式前進。', '', 25549),
(123078, 'zhTW', '我會讓你死得痛快，入侵者。', '我會讓你死得痛快，入侵者。', 25549),
(123077, 'zhTW', '在你之前，我已經殺了幾百個惡魔。你會變成我腰帶上的一個小記號。', '在你之前，我已經殺了幾百個惡魔。你會變成我腰帶上的一個小記號。', 25549),
(123076, 'zhTW', '你跟其他惡魔的鮮血會沾滿我的刀刃！', '你跟其他惡魔的鮮血會沾滿我的刀刃！', 25549),
(123075, 'zhTW', '這裡不歡迎你們這種雜碎！', '這裡不歡迎你們這種雜碎！', 25549),
(123074, 'zhTW', '這世界容不下你，惡魔！', '這個世界容不下你，惡魔！', 25549),
(123073, 'zhTW', '你別想再前進，入侵者！', '你別想再前進，入侵者！', 25549),
(123072, 'zhTW', '我受訓就是為了這一刻！', '我受訓就是為了這一刻！', 25549),
(123071, 'zhTW', '有人入侵！快發出警報！', '有人入侵！快發出警報！', 25549),
(123069, 'zhTW', '', '真是一團亂！', 25549),
(123068, 'zhTW', '', '我第一次覺得…壞壞。', 25549),
(123067, 'zhTW', '', '你是不是忘了你邪惡的一面啊？', 25549),
(123066, 'zhTW', '', '這個需要再補點妝。', 25549),
(123065, 'zhTW', '', 'elekkamomen otunbuntu rotu kelaramen! (召喚咒語。)', 25549),
(123064, 'zhTW', '', '看看我的手下，聽聽他們的聲音！', 25549),
(123063, 'zhTW', '', '你應該體驗一下飛翔！', 25549),
(123062, 'zhTW', '', '抱歉讓你受傷了！', 25549),
(123061, 'zhTW', '', '照我的方式做，保證你人見人愛！', 25549),
(123060, 'zhTW', '', '我們一起，就有無限可能！', 25549),
(123055, 'zhTW', '', '|TInterface\\Icons\\spell_arcane_arcanetorrent_nightborne:20|t嘉琳德正在施展|cFFFF0404|Hspell:227776|h[華麗的魔法]|h|r！善用|TInterface\\Icons\\spell_priest_void blast:20|t|cFFFF0404|Hspell:227405|h[反重力]|h|r的渦流以逃脫！', 25549),
(123054, 'zhTW', '我們出發吧。', '我們出發吧。', 25549),
(123053, 'zhTW', '', '你準備好開始了嗎？', 25549),
(123052, 'zhTW', '壞女巫？她沒那麼壞。是另一個女巫先做怪。', '', 25549),
(123051, 'zhTW', '今晚有場猴人秀，怪怪人看怪怪秀。', '', 25549),
(123050, 'zhTW', '演戲人別說話！美猴王有計劃！', '', 25549),
(123049, 'zhTW', '先生女士，歡迎光臨我們的 - 啊！', '', 25549),
(123048, 'zhTW', '是什麼樣的任務？', '是什麼樣的任務？', 25549),
(123047, 'zhTW', '', '別讓我失望，$n。', 25549),
(123046, 'zhTW', '', '這還真是…淒美啊。', 25549),
(123045, 'zhTW', '', '這個地方可以變得更嘉琳德一點！', 25549),
(123044, 'zhTW', '', '接下來，是最神奇的！', 25549),
(123043, 'zhTW', '%s的星座失效了，造成大三角！', '%s的星座失效了，造成大三角！', 25549),
(123042, 'zhTW', '%s和$n相撞，造成大三角！', '%s和$n相撞，造成大三角！', 25549),
(123040, 'zhTW', '跳過特效，避免受到|cFFFF0404|Hspell:211901|h[融能加壓器]|h|r的傷害！', '跳過特效，避免受到|cFFFF0404|Hspell:211901|h[融能加壓器]|h|r的傷害！', 25549),
(123039, 'zhTW', '<騎乘峇嘴。>', '<騎乘峇嘴。>', 25549),
(123038, 'zhTW', '<峇嘴謹慎地望著你。>', '', 25549),
(123037, 'zhTW', '愛情只是經過理想包裝的老掉牙動物本能！', '愛情只是經過理想包裝的老掉牙動物本能！', 25549),
(123036, 'zhTW', '我不想回到收發室！', '我不想回到收發室！', 25549),
(123035, 'zhTW', '我才領多少錢，竟然要做這種事！', '我才領多少錢，竟然要做這種事！', 25549),
(123033, 'zhTW', '你感受到傳送門另一端有個令人戰慄的存在，僅在一瞬間就撼動了你的身心…', '你感受到傳送門另一端有個令人戰慄的存在，僅在一瞬間就撼動了你的身心…', 25549),
(123030, 'zhTW', '可以再給我一個飛行管理員的哨子嗎？', '可以再給我一個飛行管理員的哨子嗎？', 25549),
(123029, 'zhTW', '你的等級必須低於101才能參與燃燒軍團入侵事件。', '你的等級必須低於101才能參與燃燒軍團入侵事件。', 25549),
(123028, 'zhTW', '|TInterface\\Icons\\ability_mage_arcanebarrage_nightborne:20|t你成為|cFFF00000|Hspell:220871|h[不穩定的法力]|h|r的目標！', '', 25549),
(123027, 'zhTW', '我必須跳進競技場殺死那頭怪物。月之女神啊，賜我力量。', '', 25549),
(123026, 'zhTW', '黯刃騎士團將戰無不勝。膽敢阻擾我們之人…殺無赦。', '', 25549),
(123024, 'zhTW', '陶土議會與你同在，先知！我們會不惜一切代價，與你一起對抗燃燒軍團！', '', 25549),
(123023, 'zhTW', '我想徵召一些黑穫部隊。', '我想徵召一些黑穫部隊。', 25549),
(123021, 'zhTW', '我們進去吧！', '我們進去吧！', 25549),
(123020, 'zhTW', '你準備進入星穹渾天儀了嗎？', '', 25549),
(123019, 'zhTW', '我已準備好前往卡拉贊。', '我已準備好前往卡拉贊。', 25549),
(123018, 'zhTW', '你必須跟卡德加一起走，找到創世之柱，$n！', '', 25549),
(123017, 'zhTW', '我們去拯救麥格尼！', '我們去拯救麥格尼！', 25549),
(123016, 'zhTW', '你準備好讓我驅散這道屏障了嗎？', '', 25549),
(123014, 'zhTW', '布萊恩‧銅鬚！？哇，真叫人意外。', '', 25549),
(123013, 'zhTW', '給我們一點時間準備，$n。$b$b保護這座城市不受燃燒軍團的攻擊，或是查詢地圖，前去阻止惡魔的入侵。$b$b等開始的時機到了，我會再找你過來。', '', 25549),
(123012, 'zhTW', '我會盡我所能提供協助。能為祈倫托效力是我的榮幸。', '', 25549),
(123011, 'zhTW', '', '我們從來沒有在短時間內二度移動達拉然。', 25549),
(123010, 'zhTW', '我們必須匯聚眾人的力量，移動城市的法術會耗費相當大的法力。', '', 25549),
(123009, 'zhTW', '我現在必須去招待其他訪客。祝你好運，$n！', '', 25549),
(123008, 'zhTW', '我聽到關於強大神器的傳言，或許對你有幫助。請隨時留意有用的線索！', '', 25549),
(123007, 'zhTW', '達拉然的資源隨你使用。從現在開始，不管是聯盟還是部落的英雄都會開始搜尋創世之柱！', '', 25549),
(123006, 'zhTW', '', '|TInterface\\Icons\\Spell_Shadow_Possession:20|t %s開始施放|cFFFF0000|Hspell:227233|h[腐化怒吼]|h|r。小心！', 25549),
(123005, 'zhTW', '來獵殺我啊…', '', 25549),
(123004, 'zhTW', '再會…祝你好運。或許你下次就會跪在地上求他們饒你一命。', '', 25549),
(123003, 'zhTW', '只要懦夫依然在位，就不可能擊敗燃燒軍團。', '', 25549),
(123002, 'zhTW', '你是個蠢貨，黑羽！無所謂，你對我已經沒有用處了。', '', 25549),
(123001, 'zhTW', '你們卻只會批判我的做法？我的法師為了拯救世界犧牲。你們付出了什麼？你們犧牲了什麼？', '', 25549),
(123000, 'zhTW', '這只是個入侵行動，但他們幾乎毀掉了整個蘇拉瑪爾。', '', 25549),
(122999, 'zhTW', '還能怎麼樣？你瞎了，黑羽！你們全都瞎了！', '', 25549),
(122998, 'zhTW', '總是有其他辦法！我們還能…', '', 25549),
(122997, 'zhTW', '不然你要我怎麼辦，克塔羅斯？對燃燒軍團唯唯諾諾，讓他們把這個世界燒成灰？', '', 25549),
(122996, 'zhTW', '我們跟那些怪物有什麼分別？', '', 25549),
(122995, 'zhTW', '如此野蠻…', '', 25549),
(122994, 'zhTW', '這不可能！', '', 25549),
(122993, 'zhTW', '伊利丹，不行！', '', 25549),
(122992, 'zhTW', '月神原諒我做的一切…', '', 25549),
(122991, 'zhTW', '快想辦法，伊利丹！我們要被撕裂了！堡壘快撐不住了！', '', 25549),
(122990, 'zhTW', '我竭盡所能地攻擊這個怪物，卻毫無作用。我必須請求月之守衛最後一次提供協助。', '', 25549),
(122989, 'zhTW', '我們必須加入競技場的戰鬥！怒風隊長，帶領衝鋒！', '', 25549),
(122988, 'zhTW', '伊利丹奪回庭園了！玄鴉衛士，進攻！', '', 25549),
(122987, 'zhTW', '我是全宇宙最強大的法師獵人！你們根本沒有機會，小精靈！', '', 25549),
(122986, 'zhTW', '你還需要訓練嗎？', '', 25549),
(122985, 'zhTW', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t%s開始施放|cFFFF0000|Hspell:199193|h[驚懼領主之詐]|h|r！', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t%s開始施放|cFFFF0000|Hspell:199193|h[驚懼領主之詐]|h|r！', 25549),
(122984, 'zhTW', '', '別擔心，孩子。我是你們的大酋長。', 25549),
(122983, 'zhTW', '', '我會守護部落的。', 25549),
(122982, 'zhTW', '', '大使，我不需要為自己辯解。年輕人，大酋長雖然是很重的責任，但我是被選來承擔這個責任的。', 25549),
(122981, 'zhTW', '孤兒院的朋友說，你一定會為了被遺忘者背叛部落，還會丟下我們，這是真的嗎？', '', 25549),
(122980, 'zhTW', '等你準備好就來找我，$n。', '', 25549),
(122979, 'zhTW', '謝謝你，小夥子。希望你是對的。', '', 25549),
(122978, 'zhTW', '他不只是個寶石。他是我們的王。', '', 25549),
(122977, 'zhTW', '小傢伙，他走了。他去做更重要的事了。', '', 25549),
(122976, 'zhTW', '如果他真的是鑽石，應該沒事吧？鑽石很硬的！', '', 25549),
(122975, 'zhTW', '大鑽石走掉了？', '', 25549),
(122974, 'zhTW', '大鑽石在哪裡？', '', 25549),
(122973, 'zhTW', '你必須盡快找到它們。要是落到燃燒軍團手中，創世之柱的力量會毀滅這個世界。祝你好運。', '', 25549),
(122972, 'zhTW', '守護者，謝謝你再次幫助艾澤拉斯。', '', 25549),
(122971, 'zhTW', '', '至少這是一個方向。有必要的話，我們會搜遍破碎群島每一吋的土地。', 25549),
(122970, 'zhTW', '好吧。我的研究指向破碎群島，但我一直無法找到確切的位置。我認為創世之柱就在當地居民手裡。', '', 25549),
(122969, 'zhTW', '我們必須盡快找到這些聖物。只有創世之柱才能封印燃燒軍團在薩格拉斯之墓的傳送門。', '', 25549),
(122968, 'zhTW', '當然沒有！創世之柱蘊含原始能量。身為守護者，我也不敢把它們視同兒戲。', '', 25549),
(122967, 'zhTW', '', '我們想找到五個名為創世之柱的遠古聖物。你的著作中並沒有提到該怎麼找到它們。', 25549),
(122966, 'zhTW', '可惜看不到斯鐸海姆了。', '', 25549),
(122965, 'zhTW', '你讀過我的著作？我以為年輕一代都不看書了，只會玩遊戲或是到處去冒險…', '', 25549),
(122964, 'zhTW', '燃燒軍團回來了。為了阻止他們，我們在卡拉贊的圖書館中搜尋一本由你所寫的書，名為《遠古艾澤拉斯的著名古物》。', '', 25549),
(122963, 'zhTW', '我知道你是誰。你就是拒絕當守護者的那名學徒。你為什麼召喚我？', '', 25549),
(122962, 'zhTW', '你好，艾洛岱。我是卡德加，祈倫托的大法…', '', 25549),
(122961, 'zhTW', '居然是召喚！距離上次有人召喚我，已經過了好久好久。', '', 25549),
(122960, 'zhTW', '我在此召喚第一任守護者的靈魂！', '', 25549),
(122959, 'zhTW', '我的力量快耗盡了。我需要找個傳送門休息，或是吸取月之守衛的精華。', '', 25549),
(122958, 'zhTW', '我從未感受過這種力量…這種痛苦…', '', 25549),
(122957, 'zhTW', '有個叫巴拉杜爾的埃雷達爾在保護奈厄拉姆傳送門。一般的法術對它沒有用，我必須召喚宇宙之怒才能破壞傳送門。然後，我要親自解決這個惡魔。', '', 25549),
(122956, 'zhTW', '太多惡魔了。我…我需要更多月之守衛的力量。我太過火了嗎？不，我必須專注！人民的命運都掌握在我手中！', '', 25549),
(122955, 'zhTW', '你竟敢對抗偉大的燃燒之影！手下們，殺了這個「英雄」！', '', 25549),
(122954, 'zhTW', '又來了好幾千個！看來惡魔是從庭園的傳送門來的。我們想活命就要摧毀它，但我需要月之守衛幫忙。', '', 25549),
(122953, 'zhTW', '我叫伊利丹，惡魔！記住我的名字，我會是你的末日！', '', 25549),
(122952, 'zhTW', '我必須...做個了結！', '', 25549),
(122951, 'zhTW', '有任何東西能抵擋這種力量嗎？', '', 25549),
(122950, 'zhTW', '我必須想辦法關閉傳送門！', '', 25549),
(122949, 'zhTW', '每殺一個惡魔，就又多出兩個！', '', 25549),
(122948, 'zhTW', '它們永無止盡！', '', 25549),
(122947, 'zhTW', '也許是風吹散迷霧。', '', 25549),
(122946, 'zhTW', '從這裡可以看見整個蘇拉瑪爾！', '', 25549),
(122945, 'zhTW', '不要再有下一次了！', '不要再有下一次了！', 25549),
(122944, 'zhTW', '因為粗心大意，我只好暫時撤退。我會記取這次的教訓，再回來報仇。', '', 25549),
(122943, 'zhTW', '瑪法里恩能成為第一位德魯伊，是因為他總是專心致志。你，卻不是這樣。', '', 25549),
(122942, 'zhTW', '我會召喚艾洛岱，第一任提里斯法守護者。你想開始的時候就讓我知道。', '', 25549),
(122941, 'zhTW', '開始召喚吧。', '開始召喚吧。', 25549),
(122940, 'zhTW', '我們會戰勝燃燒軍團。', '', 25549),
(122939, 'zhTW', '達拉然絕對不會淪陷，$n。', '', 25549),
(122938, 'zhTW', '一定要消滅燃燒軍團！', '', 25549),
(122937, 'zhTW', '這怎麼可能會是壞主意呢？', '這怎麼可能會是壞主意呢？', 25549),
(122936, 'zhTW', '六眼主人看到了你的命運，$n！你會失敗，而世界會付之一炬！', '', 25549),
(122935, 'zhTW', '如果你還想了解大自然的知識，可以向你兄長學習。', '', 25549),
(122934, 'zhTW', '我把超大的石頭都帶來啦，給投石車用的。格雷想加入部落！', '這就是你要搭的船，$n。願聖光與你同在。', 25549),
(122933, 'zhTW', '$n偷偷地在莊嚴之夜藥劑裡面加入毒藥。', '$n偷偷地在莊嚴之夜藥劑裡面加入毒藥。', 25549),
(122932, 'zhTW', '$n摧毀了秘法能量導體，使所有的守護者傀儡超載！', '$n摧毀了秘法能量導體，使所有的守護者傀儡超載！', 25549),
(122930, 'zhTW', '$n解讀浸水的卷軸，使大家的移動速度提高！', '$n解讀浸水的卷軸，使大家的移動速度提高！', 25549),
(122929, 'zhTW', '$n使魔法燈籠的能量暢通，讓大家的傷害提高！', '$n使魔法燈籠的能量暢通，讓大家的傷害提高！', 25549),
(122928, 'zhTW', '$n使用夜影餐點，讓大家的生命力提高！', '$n使用夜影餐點，讓大家的生命力提高！', 25549),
(122927, 'zhTW', '$n放出了暗影之花的孢子，使大家的加速提高！', '$n放出了暗影之花的孢子，使大家的加速提高！', 25549),
(122926, 'zhTW', '$n吸取了魔化火球的能量，使大家的致命一擊機率提高！', '$n吸取了魔化火球的能量，使大家的致命一擊機率提高！', 25549),
(122925, 'zhTW', '$n摧毀了煉獄秘典，使大家受到的傷害降低！', '$n摧毀了煉獄秘典，使大家受到的傷害降低！', 25549),
(122924, 'zhTW', '$n使用星輝玫瑰酒，讓大家恢復生命力跟法力！', '$n使用星輝玫瑰酒，讓大家恢復生命力跟法力！', 25549),
(122923, 'zhTW', '$n，你聽見戰鬥的怒吼聲了嗎？它正在呼喚你！', '', 25549),
(122912, 'zhTW', '$n，戰爭實在叫人熱血沸騰！你的斧頭渴望著戰鬥！', '', 25549),
(122911, 'zhTW', '鮮血與雷霆，$n。你的船隻與光榮的勝利正等待著你。', '這就是你要搭的船，$n。願聖光與你同在。', 25549),
(122908, 'zhTW', '嗯…我有一個想法…等你把那些異常體解決了，我們再來討論。', '', 25549),
(122907, 'zhTW', '我和大法師莫德菈會繼續研究從卡拉贊帶回來的書。我們一定會找到創世之柱，$n！', '', 25549),
(122906, 'zhTW', '幸好我們都能活著離開卡拉贊。', '', 25549),
(122900, 'zhTW', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t海爾珈開始施放|cFFFF0404|Hspell:192206|h[庇護]|h|r！', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t海爾珈開始施放|cFFFF0404|Hspell:192206|h[庇護]|h|r！', 25549),
(122899, 'zhTW', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t 海爾珈開始施放 |cFFFF0404|Hspell:192305|h[風暴之眼]|h|r！', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t 海爾珈開始施放 |cFFFF0404|Hspell:192305|h[風暴之眼]|h|r！', 25549),
(122898, 'zhTW', '你說得沒錯。魔能確實比秘法強大，但你使用的方式太笨拙！容我向你展示，什麼才是真正的毀滅力量！', '', 25549),
(122897, 'zhTW', '', '你竟敢反抗燃燒軍團？在魔能的力量前面跪下！', 25549),
(122896, 'zhTW', '啊，還有什麼選擇嗎？如果我失敗了，蘇拉瑪爾也會殞落。為了我所愛的泰蘭妲，我必須行動！', '', 25549),
(122895, 'zhTW', '她的惡魔法術太強大了。我可以吸取月之守衛的力量來對她釋放毀滅之力，但這樣會害死我手下的法師。', '', 25549),
(122894, 'zhTW', '大法師，我們該走了。', '大法師，我們該走了。', 25549),
(122893, 'zhTW', '我們聽候差遣，隊長！', '我們聽候差遣，隊長！', 25549),
(122892, 'zhTW', '降下閘門，準備迎戰！旋刃投擲器預備！', '', 25549),
(122891, 'zhTW', '我準備好了，黑羽堡主！降下閘門！', '', 25549),
(122890, 'zhTW', '好極了！只要我在傳送門附近，就能獲得源源不絕的力量。要是我開始力不從心，一定要利用傳送門恢復力量。', '', 25549),
(122889, 'zhTW', '伊利丹陷入沉思。', '', 25549),
(122888, 'zhTW', '如果我能修好那個被關閉的傳送門，就能把援軍傳進來，也能為我注入新的力量。', '', 25549),
(122887, 'zhTW', '光是造出保護屏障，就耗盡我們全部的力量。要是再逼迫這些月之守衛，他們一定會死。', '', 25549),
(122886, 'zhTW', '我不會讓你失望，堡主！', '', 25549),
(122884, 'zhTW', '而我，會找到辦法。', '', 25549),
(122883, 'zhTW', '我們都會死…', '', 25549),
(122882, 'zhTW', '就算在這裡擊退它們，也沒有意義。', '', 25549),
(122881, 'zhTW', '惡魔的軍隊…永遠…無窮…無盡…', '', 25549),
(122880, 'zhTW', '我們…被蒙蔽了。', '', 25549),
(122879, 'zhTW', '不管怎麼掙扎，世界都會毀滅。', '', 25549),
(122878, 'zhTW', '<痛苦哀號>', '', 25549),
(122877, 'zhTW', '這就是燃燒軍團的力量。', '', 25549),
(122876, 'zhTW', '弟弟 - ', '', 25549),
(122875, 'zhTW', '走上這條路，就必須犧牲。伊利丹…這件事，你還沒有學會。', '', 25549),
(122874, 'zhTW', '你必須學會尊重。', '', 25549),
(122873, 'zhTW', '要指導我的，是學徒…而不是老師？', '', 25549),
(122872, 'zhTW', '所以…', '', 25549),
(122871, 'zhTW', '我沒有。你可以留在這裡，但我不再是你的老師了。', '', 25549),
(122870, 'zhTW', '是你趕我走，塞納留斯！', '', 25549),
(122869, 'zhTW', '伊利丹，你不應該怪我。我沒有侮辱你。', '', 25549),
(122868, 'zhTW', '', '沒有錯。他注定成就大事。他的名字是…伊利丹。', 25549),
(122867, 'zhTW', '你看他！他的眼睛是金色的！', '', 25549),
(122866, 'zhTW', '', '真美啊。簡直一模一樣，除了 - ', 25549),
(122865, 'zhTW', '', '怒風雙胞胎。', 25549),
(122864, 'zhTW', '兩個？', '', 25549),
(122862, 'zhTW', '', '快逃吧，小黑羽，快逃！現在開始跑的話，你或許還有機會能夠躲在樹上度過悲慘的一生！', 25549),
(122861, 'zhTW', '', '臭小鬼…還挺強的…', 25549),
(122860, 'zhTW', '', '你…你竟然殺死自己的戰友？！你這個瘋子！你這是在自尋死路！', 25549),
(122859, 'zhTW', '', '搞什麼？黑羽派了一個臭小鬼對付我？小朋友，我會教你什麼叫做禮貌！', 25549),
(122858, 'zhTW', '$n！卡德加！感謝熔爐，我找到你了！你絕對不會相信！我哥哥麥格尼回來了！', '', 25549),
(122857, 'zhTW', '怒風隊長讓我們有機會反擊！玄鴉衛士，守住城牆！前進！', '', 25549),
(122856, 'zhTW', '做你該做的！要是連玄鴉堡都撐不住，整個蘇拉瑪爾都完了！', '', 25549),
(122855, 'zhTW', '', '%s漠然地聳聳肩，一腳將你踢上天。', 25549),
(122854, 'zhTW', '', '今天就是你的忌日。', 25549),
(122853, 'zhTW', '', '小偷！你居然敢偷我的東西？！', 25549),
(122852, 'zhTW', '你是我們最後的希望，伊利丹！', '', 25549),
(122851, 'zhTW', '燃燒軍團殺了我們大半部隊，倖存者四處流散。能防衛堡壘的只剩下你眼前的這幾位玄鴉衛士了。', '', 25549),
(122850, 'zhTW', '我想再度挑戰隕落魔，女士。', '我想再度挑戰隕落魔，女士。', 25549),
(122849, 'zhTW', '做得好，伊利丹，但戰爭才剛開始。', '', 25549),
(122848, 'zhTW', '這是你名字的縮寫嗎？', '這是你名字的縮寫嗎？', 25549),
(122847, 'zhTW', '', '$r，你找我有什麼事？', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122846, 'zhTW', '', '還不只一個，是兩個健康的男孩。', 25549),
(122845, 'zhTW', '', '感謝月神，今晚，她為我們帶來新的生命。', 25549),
(122844, 'zhTW', '伊利丹死了，聖光軍團為了我們跨越宇宙，去打那場永無止盡的戰爭…', '', 25549),
(122843, 'zhTW', '至於聖光軍團和伊利丹的事，我不知道該怎麼辦。我從來沒有這麼無助過。', '', 25549),
(122842, 'zhTW', '我們就像孤兒一樣。造物者在我們出生前就都死了。', '', 25549),
(122841, 'zhTW', '這確實可以說明很多事，但我還是覺得…心裡有股被掏空的悲傷。', '', 25549),
(122840, 'zhTW', '死了？泰坦都死了？', '', 25549),
(122838, 'zhTW', '', '你說吧。', 25549),
(122837, 'zhTW', '<讓薇兒塔看薩莉瑟拉的徽印。>', '<讓薇兒塔薩莉瑟拉的徽印。>', 25549),
(122836, 'zhTW', '', '魔法漸漸消散了。謝謝你。', 25549),
(122835, 'zhTW', '', '那些鬼靈法師，用魔法召喚了某種生物！去教訓他們。', 25549),
(122834, 'zhTW', '', '呼，我們暫時…可以放心了。', 25549),
(122833, 'zhTW', '', '有個巨大的海怪出現了。把它送回海底！', 25549),
(122832, 'zhTW', '我都看見了！伊利丹！黑羽要我接手！我們得互相合作，恢復部隊的秩序！', '', 25549),
(122831, 'zhTW', '這裡不需要你了，伊利丹！羅甯，月之守衛改由你來指揮！', '', 25549),
(122830, 'zhTW', '伊利丹，你做了什麼！你害死他們了！', '', 25549),
(122829, 'zhTW', '隨時注意影歌隊長以及兩位外來盟友的下落！我們在一開始的襲擊時走散了。希望他們沒事！', '', 25549),
(122828, 'zhTW', '更糟的是，如果不立刻制止在競技場內的怪獸，火焰就會從內部延燒，毀滅整個玄鴉堡！立刻帶月之守衛阻止惡魔侵襲！', '', 25549),
(122827, 'zhTW', '', '泰蘭妲…一個世界有沒有意義，要看那裡住了什麼人。即使到最後，伊利丹看著泰蘭妲的樣子，自始至終都沒有改變過。他對這個世界，從來沒有轉移過目光。你得問自己，願意為自己的世界付出多少？', 25549),
(122826, 'zhTW', '', '即使雙眼因為看清真相而灼傷，伊利丹仍然無所畏懼。即使在燃燒軍團之王的注視之下，他仍然意志堅定，傲然不屈。', 25549),
(122825, 'zhTW', '', '就算再難也要做出決定，我們如果想完成任務，就一定要學會從伊利丹的角度看事情。換成你的話，你會怎麼做？', 25549),
(122824, 'zhTW', '', '像他這樣飽受失敗和挫折的人少之又少。一般人會選擇放棄，但伊利丹會跟隨命運的指引，繼續堅持下去。命運對他有別的安排。', 25549),
(122823, 'zhTW', '', '伊利丹的潛力無窮。他的命運早已注定，就算在無盡的宇宙之中漂泊，也終究會被帶回他的家園艾澤拉斯。命運之輪也會因為他而再次轉動。', 25549),
(122822, 'zhTW', '', '有個古老的記憶慢慢成形。如果你準備好了，就讓我知道。我們一起發掘伊利丹的過去。', 25549),
(122821, 'zhTW', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|t用瑪法里恩的|cFF00FFFF|Hspell:212630|h[淨化地面]|h|r以避開來自|cFFFF0000|Hspell:210279|h[蔓延夢魘]|h|r的傷害。', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|t用瑪法里恩的|cFF00FFFF|Hspell:212630|h[淨化地面]|h|r以避開來自|cFFFF0000|Hspell:210279|h[蔓延夢魘]|h|r的傷害。', 25549),
(122820, 'zhTW', '在天空翱翔真是暢快無比！', '', 25549),
(122819, 'zhTW', '我就知道！我早就感覺到了！$B$B疏散這座城市，$n！我們必須擋住他們！', '', 25549),
(122818, 'zhTW', '', '把他們擊退！我們必須保住達拉然！', 25549),
(122817, 'zhTW', '願你死得乾淨俐落。', '', 25549),
(122816, 'zhTW', '你不可能成功的！', '', 25549),
(122815, 'zhTW', '我跟你一樣驚訝，$n。', '', 25549),
(122814, 'zhTW', '你的死期到了！', '', 25549),
(122813, 'zhTW', '看劍！', '', 25549),
(122812, 'zhTW', '', '加油，$n。我們會盡量擋住惡魔攻勢。', 25549),
(122811, 'zhTW', '我是大法師卡德加，祈倫托的首領。惡魔獵人啊，艾澤拉斯需要你們幫忙。', '', 25549),
(122810, 'zhTW', '我準備了一份精美的越獄計畫，但你的動作比較快。', '', 25549),
(122809, 'zhTW', '我們都完了！', '我們都完了！', 25549),
(122808, 'zhTW', '你還不懂嗎？聖光拋棄我們了！', '你還不懂嗎？聖光拋棄我們了！', 25549),
(122807, 'zhTW', '', '這些傢伙源源不絕！', 25549),
(122806, 'zhTW', '你沒辦法阻止他們！', '你沒辦法阻止他們！', 25549),
(122805, 'zhTW', '如果失去他，我們就失去方向！', '如果失去他，我們就失去方向！', 25549),
(122804, 'zhTW', '你完蛋了，$n！', '', 25549),
(122803, 'zhTW', '滾出我們的店！', '', 25549),
(122802, 'zhTW', '喔你想都別想！', '', 25549),
(122801, 'zhTW', '', '祝福你…', 25549),
(122800, 'zhTW', '', '我將回到…混沌黑暗…', 25549),
(122799, 'zhTW', '', '終於…自由了…', 25549),
(122798, 'zhTW', '', '謝…謝…你…', 25549),
(122797, 'zhTW', '', '全然…迷失…', 25549),
(122796, 'zhTW', '', '聖光消逝了…', 25549),
(122795, 'zhTW', '', '毫無希望…', 25549),
(122794, 'zhTW', '', '幫…我…', 25549),
(122793, 'zhTW', '都沒有人來幫忙嗎？', '都沒有人來幫忙嗎？', 25549),
(122792, 'zhTW', '快阻止這個怪東西！', '快阻止這個怪東西！', 25549),
(122791, 'zhTW', '別讓我接近這東西！', '別讓我接近這東西！', 25549),
(122790, 'zhTW', '戰鬥開始了，伊利丹大人！', '', 25549),
(122789, 'zhTW', '[%s]坦承：我在拍賣場賣東西時，總是賤價拍賣，因為我玩得起。', '[%s]坦承：我在拍賣場賣東西時，總是賤價拍賣，因為我玩得起。', 25549),
(122788, 'zhTW', '[%s]坦承：我不喜歡跟古羅打，總覺得牠們一直在瞪我。', '[%s]坦承：我不喜歡跟古羅打，總覺得牠們一直在瞪我。', 25549),
(122787, 'zhTW', '終於有值得我用斧頭的敵人了！', '', 25549),
(122786, 'zhTW', '[%s]坦承：我覺得小地獄吼其實人還不錯。', '[%s]坦承：我覺得小地獄吼其實人還不錯。', 25549),
(122785, 'zhTW', '[%s]坦承：我真的非常喜歡閃金鎮旅店。', '[%s]坦承：我真的非常喜歡閃金鎮旅店。', 25549),
(122784, 'zhTW', '[%s]坦承：我不懂為何這裡要叫破碎群島。這座大島是哪裡破碎了？', '[%s]坦承：我不懂為何這裡要叫破碎群島。這座大島是哪裡破碎了？', 25549),
(122783, 'zhTW', '[%s]坦承：我曾暗地希望我船塢裡的一艘船任務失敗。但它總是成功。', '[%s]坦承：我曾暗地希望我船塢裡的一艘船任務失敗。但它總是成功。', 25549),
(122782, 'zhTW', '[%s]坦承：我很久沒去要塞了。希望我的追隨者一切平安。', '[%s]坦承：我很久沒去要塞了。希望我的追隨者一切平安。', 25549),
(122781, 'zhTW', '[%s]坦承：我比較喜歡舊達拉然。不是你想的那個，是另外一個。', '[%s]坦承：我比較喜歡舊達拉然。不是你想的那個，是另外一個。', 25549),
(122780, 'zhTW', '[%s]坦承：我就是那個沒關豹群守護的傢伙。', '[%s]坦承：我就是那個沒關豹群守護的傢伙。', 25549),
(122779, 'zhTW', '[%s]坦承：我在隊長講解新首領打法時從來沒專心過。', '[%s]坦承：我在隊長講解新首領打法時從來沒專心過。', 25549),
(122778, 'zhTW', '[%s]坦承：我時常在想維酷人的鬍鬚是否比貓咪的觸感還柔軟。', '[%s]坦承：我時常在想維酷人的鬍鬚是否比貓咪的觸感還柔軟。', 25549),
(122777, 'zhTW', '[%s]坦承：我不需要的東西全賣給商人，因為我懶得用拍賣場。', '[%s]坦承：我不需要的東西全賣給商人，因為我懶得用拍賣場。', 25549),
(122776, 'zhTW', '[%s]坦承：我很不想承認，但我花了不少時間在海裡尋找愛濕蘭。', '[%s]坦承：我很不想承認，但我花了不少時間在海裡尋找愛濕蘭。', 25549),
(122775, 'zhTW', '[%s]坦承：我不敢相信牛頭人武器有多麼龐大。', '[%s]坦承：我不敢相信牛頭人武器有多麼龐大。', 25549),
(122774, 'zhTW', '[%s]坦承：我以為我們已經打敗軍團了。', '[%s]坦承：我以為我們已經打敗軍團了。', 25549),
(122773, 'zhTW', '[%s]坦承：我不知道治療石是什麼，事到如今我也不敢問了。', '[%s]坦承：我不知道治療石是什麼，事到如今我也不敢問了。', 25549),
(122772, 'zhTW', '別鬧了，惡魔！你們知道沒辦法打敗我！', '', 25549),
(122771, 'zhTW', '燃燒軍團想偷襲我們，但我們已經準備好了。', '', 25549),
(122770, 'zhTW', '他們從空中殞落再撞擊地面的聲音，啊，真是好聽。', '', 25549),
(122769, 'zhTW', '我把達拉然爐石弄丟了，可以再給我一個嗎？', '我把達拉然爐石弄丟了，可以再給我一個嗎？', 25549),
(122768, 'zhTW', '你們的犧牲會名留千古。', '', 25549),
(122767, 'zhTW', '我必須這麼做。', '', 25549),
(122766, 'zhTW', '你打得很好，亞羅德。跟我來打完這場仗！', '', 25549),
(122765, 'zhTW', '我只希望他們沒有白白犧牲。', '', 25549),
(122764, 'zhTW', '當初設計時，就希望這地方能抵擋所有攻擊。但我們低估了燃燒軍團。', '', 25549),
(122763, 'zhTW', '伊利丹大人，你真是太厲害了！', '', 25549),
(122762, 'zhTW', '隊長，我不是英雄，但我願意跟你並肩作戰。', '', 25549),
(122761, 'zhTW', '我不確定這樣做對不對，伊利丹大人。', '', 25549),
(122760, 'zhTW', '打得真好。我一個人絕對不可能打敗驚懼領主。', '', 25549),
(122759, 'zhTW', '伊利丹！墓塚裡面有個驚懼領主。要是你能幫忙就太好了。', '', 25549),
(122758, 'zhTW', '惡魔，被火焰淨化吧！', '', 25549),
(122757, 'zhTW', '我會維持空中優勢，隊長。地面上的戰局需要你。', '', 25549),
(122756, 'zhTW', '我還以為這波攻擊沒完沒了！', '', 25549),
(122755, 'zhTW', '伊利丹！想不到你也知道要怎麼騎龍！', '', 25549),
(122754, 'zhTW', '我的戰斧為你效力。', '', 25549),
(122753, 'zhTW', '伊利丹，能與你一起作戰，我學到很多。', '', 25549),
(122752, 'zhTW', '你願意幫忙擊退敵人，我很感激。', '', 25549),
(122751, 'zhTW', '伊利丹，你兼具優雅和力量。能看見你戰鬥是我的榮幸。', '', 25549),
(122750, 'zhTW', '你做了該做的事。真的是非常令人欽佩。', '', 25549),
(122749, 'zhTW', '你是哪種法師？', '', 25549),
(122748, 'zhTW', '這場戰鬥不公平！惡魔這麼少，塞牙縫都不夠！', '', 25549),
(122747, 'zhTW', '有機會再讓你鑑賞一下我收藏的外袍！', '', 25549),
(122746, 'zhTW', '有機會再讓你鑑賞一下我收藏的坐騎！', '', 25549),
(122745, 'zhTW', '有機會再讓你鑑賞一下我收藏的硬幣！', '', 25549),
(122744, 'zhTW', '有機會再讓你鑑賞一下我收藏的卷軸！', '', 25549),
(122743, 'zhTW', '有機會再讓你鑑賞一下我收藏的寵物！', '', 25549),
(122742, 'zhTW', '有機會再讓你鑑賞一下我收藏的杯子！', '', 25549),
(122741, 'zhTW', '有空我一定要讓你看看我收藏的玩具！', '', 25549),
(122740, 'zhTW', '我喝得越多，戰術就越高明…嗝！', '', 25549),
(122739, 'zhTW', '上週的犛牛賽跑比賽，我拿到第二名。我需要速度更快的犛牛！', '', 25549),
(122738, 'zhTW', '每天早上我都繞著漂流島跑步…跑兩圈！我不能在訓練上懈怠。', '', 25549),
(122737, 'zhTW', '有機會再讓你鑑賞一下我收藏的樹葉！', '', 25549),
(122736, 'zhTW', '我等下要吃第二份晚餐！', '我等下要吃第二份晚餐！', 25549),
(122735, 'zhTW', '$n！我有好東西給你！來吧！', '', 25549),
(122734, 'zhTW', '', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', 25549),
(122733, 'zhTW', '沒有什麼異常狀況。只有偶爾的能量波動，但我不認為會構成危險。', '沒有什麼異常狀況。只有偶爾的能量波動，但我不認為會構成危險。', 25549),
(122732, 'zhTW', '', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', 25549),
(122731, 'zhTW', '', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', 25549),
(122730, 'zhTW', '', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', 25549),
(122729, 'zhTW', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', '', 25549),
(122728, 'zhTW', '', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', 25549),
(122727, 'zhTW', '', '如果我們發現什麼，會向你報告的。', 25549),
(122726, 'zhTW', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', '', 25549),
(122725, 'zhTW', '我沒有時間閒聊，惡魔獵人。$b$b我和其他伊利達瑞說過了，我有很多事情必須思考。$b$b我必須籌備大軍迎戰燃燒軍團，而我的盟友中又有人只渴望對部落復仇。', '', 25549),
(122724, 'zhTW', '', '目前為止，這裡似乎一切正常！', 25549),
(122723, 'zhTW', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', '', 25549),
(122722, 'zhTW', '大人！我有好東西。過來看看吧。', '', 25549),
(122721, 'zhTW', '', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', 25549),
(122720, 'zhTW', '', '別擔心。她很快就會幫你離開這裡！', 25549),
(122719, 'zhTW', '', '$n！能借我一點時間嗎？我有些貨物你應該會有興趣。', 25549),
(122718, 'zhTW', '', '看來你已經把場面控制住了。', 25549),
(122717, 'zhTW', '', '喂，葛林多…喔，天啊。我連說都懶得說了。這個全是你的錯。', 25549),
(122716, 'zhTW', '白銀之手騎士團在你的領導之下重組了，我們也獲得了新的方向與指引。$B$B還有很多工作等著我們完成。', '', 25549),
(122715, 'zhTW', '', '這裡的狀況如何？有任何不尋常的騷動嗎？', 25549),
(122714, 'zhTW', '', '你們兩個有發現什麼不對勁的事情嗎？聽說這個區域出現不穩定的能量。', 25549),
(122713, 'zhTW', '再跟我說說卡德加的事。', '再跟我說說卡德加的事。', 25549),
(122712, 'zhTW', '再跟我說一次古爾丹的事。', '再跟我說說古爾丹的事。', 25549),
(122711, 'zhTW', '再跟我說說伊利丹的事。', '再跟我說說伊利丹的事。', 25549),
(122710, 'zhTW', '祈倫托感謝你的協助。', '', 25549),
(122709, 'zhTW', '我們得收復神聖的家園。', '', 25549),
(122708, 'zhTW', '', '你有勇氣協助我們擊敗燃燒軍團嗎？', 25549),
(122707, 'zhTW', '你能感覺到這片森林的生命力嗎？多年來我們一直保護這片土地，但現在我們沒辦法獨自保護這個地方了。你願意幫助我們嗎？', '你能感覺到這片森林的生命力嗎？多年來我們一直保護這片土地，但現在我們沒辦法獨自保護這個地方了。你願意幫助我們嗎？', 25549),
(122706, 'zhTW', '', '提高警覺，$n。$B$B杜賓或許是個頑固的矮人，但是他跟我都有一個共識 - 這裡有些不對勁。', 25549),
(122705, 'zhTW', '', '我們必須再撐一下。', 25549),
(122704, 'zhTW', '', '我相信議會一定有計畫的！', 25549),
(122703, 'zhTW', '', '他們一定很快就要移動這座城市！我們沒辦法再繼續這樣下去！', 25549),
(122702, 'zhTW', '', '不能這樣繼續下去！我們快不行了！', 25549),
(122701, 'zhTW', '', '沒完沒了！他們一直來！', 25549),
(122700, 'zhTW', '', '我們撐不下去了！', 25549),
(122699, 'zhTW', '你還活著！你的勇士發現沒辦法把你喚醒時，就把你帶來這裡。我們將你安置在醫護站裡照顧。發生什麼事了？', '', 25549),
(122698, 'zhTW', '', '你好！剛來這座城市嗎？你似乎沒有被副作用影響。', 25549),
(122697, 'zhTW', '', '你好，$n。今天感覺如何？有些人說最近常覺得頭暈噁心。', 25549),
(122696, 'zhTW', '', '你現在的痛苦只是暫時的，勇士。你身上帶著我的印記，透過印記，你看見的，感受到的，我都會知道。有空就回來吧，還有很多事要做。', 25549),
(122695, 'zhTW', '啊哈哈哈哈哈！', '', 25549),
(122694, 'zhTW', '看看是誰死而復生啦！$g老兄:女士;，你已經昏迷3天了。如果卡德加聽到你醒來的消息，一定很高興。你說我？還是一隻該死的海獅。', '', 25549),
(122693, 'zhTW', '你躲不過我的法眼，惡魔！', '你躲不過我的法眼，惡魔！', 25549),
(122692, 'zhTW', '我們這趟去奧杜亞做了很多事，不過眼前還有工作等著我們。', '', 25549),
(122691, 'zhTW', '你先走，我馬上就會跟上。我只需要一點時間…整理一下思緒。', '', 25549),
(122690, 'zhTW', '我改變主意了。請再說一次還有哪些神兵武器可以選擇。', '我改變主意了。請再說一次還有哪些神兵武器可以選擇。', 25549),
(122686, 'zhTW', '沒人可以阻擾暮光之錘！', '沒人可以阻擾暮光之錘！', 25549),
(122685, 'zhTW', '我們帶來毀滅！', '我們帶來毀滅！', 25549),
(122684, 'zhTW', '大聲叫吧…沒有人會來幫你的！', '大聲叫吧…沒有人會來幫你的！', 25549),
(122683, 'zhTW', '暮光找上你了！', '暮光找上你了！', 25549),
(122682, 'zhTW', '我要殺了你！', '我要殺了你！', 25549),
(122681, 'zhTW', '', '我不懂這些花到底發生了什麼事！我有一陣子沒採集它們了，因為它們…呃，會自己採集自己！$B$B真的很奇怪，對不對？', 25549),
(122680, 'zhTW', '那邊的老頭費瑪夫是怎麼回事？', '那邊的老頭費瑪夫是怎麼回事？', 25549),
(122679, 'zhTW', '經過了好多年，我們為北裂境戰役把整座城市移往寒冰皇冠。$b$b突然有一天，老頭費瑪夫出現在紫羅蘭之塔。他就這樣大剌剌地走進來！他什麼都沒有說，自顧自地開始整理書籍，編排書稿，好像什麼都沒發生過。從那個時候開始就一直整理到現在。$b$b<瓦瑞薩斯靠過來對你低語：>$b$b我不確定他是不是知道自己已經死了。', '', 25549),
(122678, 'zhTW', '誰，費瑪夫？那個老古董？他當達拉然的古卷管理員幾十年了。我對他的第一印象是從我當學生的時候開始。他老是埋首在書堆裡，什麼東西他都找得到。$b$b然後發生了第三次戰爭，阿薩斯毀了這座城市。失蹤的人民無數，費瑪夫也在那時失蹤了 - 變成了其中一具無名屍。當時沒有人想太多。', '', 25549),
(122677, 'zhTW', '所以阿雷希斯中了那個埃雷達爾的埋伏？那大概就是巴拉杜爾把法杖拿走了…\n\n經過這場侵略行動，我敢說他要不是在這裡，就是在監視這一切。我有一個…大膽的提議。\n\n我們來重現阿雷希斯的儀式！在侵略地點展開儀式，巴拉杜爾一定會襲擊，但我們可以預先準備好。', '', 25549),
(122676, 'zhTW', '<他眼神戒備，瞪著你一句話也不說。>', '<她眼神戒備，瞪著你一句話也不說。>', 25549),
(122675, 'zhTW', '隨便你。', '隨便你。', 25549),
(122674, 'zhTW', '你嚇不倒我的。', '你嚇不倒我的。', 25549),
(122673, 'zhTW', '不然來打架啊。', '不然來打架啊。', 25549),
(122672, 'zhTW', '我沒有答案。', '我沒有答案。', 25549),
(122671, 'zhTW', '走開。', '走開。', 25549),
(122670, 'zhTW', '幹嘛？', '幹嘛？', 25549),
(122669, 'zhTW', '呵。', '呵。', 25549),
(122668, 'zhTW', '讓我靜一靜。', '讓我靜一靜。', 25549),
(122667, 'zhTW', '我知道你的秘密。', '我知道你的秘密。', 25549),
(122666, 'zhTW', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t伊蓋諾斯快要完成|cFFFF0000|Hspell:223121|h[最終長眠]|h|r了！', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t伊蓋諾斯快要完成|cFFFF0000|Hspell:223121|h[最終長眠]|h|r了！', 25549),
(122665, 'zhTW', '如果你真的想得到風暴之王的武器，那就進去吧，了解他的事蹟，還有失敗的原因…', '', 25549),
(122664, 'zhTW', '我問了問題，快回答我！', '我問了問題，快回答我！', 25549),
(122663, 'zhTW', '哈囉，朋友！我不是真正的卡德加。在你眼前的只是我粗獷的俊帥臉龐，以及我廣大無邊的知識。如果有任何你需要知道答案的問題，儘管跟我說，我就會為你解惑。\n\n我的精神領域太過廣大，因此在這個裝置中只剩下一點點魔法空間，容納少數回應句法，所以請務必提出精準明確的問題。', '', 25549),
(122662, 'zhTW', '這件事不能等。你的部隊裡面有惡魔！讓我證明給你看。', '這件事不能等。你的部隊裡面有惡魔！讓我證明給你看。', 25549),
(122661, 'zhTW', '<亞度恩顯然遭到囚禁，臉色慘白。>$B$B我…掙脫…逃出來…$B$B我…差點就成功了…$B$B$n，請你救救…其他…伊利達瑞…', '', 25549),
(122660, 'zhTW', '奧杜亞有眾多秘密。', '', 25549),
(122659, 'zhTW', '', '祝你們好運。', 25549),
(122658, 'zhTW', '', 'XXXX', 25549),
(122657, 'zhTW', '趁法力怨靈不注意時快移動！', '趁法力怨靈不注意時快移動！', 25549),
(122656, 'zhTW', '', '不用害怕，凡人。你的意識只是被傳送到我在星外暗界的靈體而已。', 25549),
(122655, 'zhTW', '', '我是瑟拉，在宇宙初生秩序之時，我是最早被創造的那魯之一。', 25549),
(122654, 'zhTW', '說一聲我們就出發！', '', 25549),
(122653, 'zhTW', '我們會立刻前往虛空之光神殿。', '', 25549),
(122652, 'zhTW', '我一聽到預言實現，就立刻趕回達拉然。\n\n你統一了聖光，就跟我之前見到的一樣。希望你所做的一切能賦予我們足夠的力量，好讓我們一舉擊敗巴納札爾。', '', 25549),
(122651, 'zhTW', '<席里斯‧黯翼看起來蒼白得像鬼一樣，不斷發抖。>', '', 25549),
(122650, 'zhTW', '<凱西爾‧夜棘的遺體幾乎無法辨識。他慘遭折磨，最後因傷而死。>', '', 25549),
(122649, 'zhTW', '', '$n，是你啊。\n\n我們正在追蹤危險的驚懼領主。很不幸地，他把我們引到陷阱裡了。', 25549),
(122648, 'zhTW', '這隻惡魔挺能打的！', '這隻惡魔挺能打的！', 25549),
(122647, 'zhTW', '我們沒有力量…', '我們沒有力量…', 25549),
(122646, 'zhTW', '它太強了！這簡直是瘋了！', '它太強了！這簡直是瘋了！', 25549),
(122645, 'zhTW', '', '他的名字是伊利丹·怒風。', 25549),
(122644, 'zhTW', '', '我急切地來這裡執行一個任務。我來尋找光與影之子，一個注定會結束惡魔作亂的男孩。', 25549),
(122643, 'zhTW', '', '現在，聖光軍團在阿古斯的戰役接近尾聲，他們幾乎全軍覆沒。如果他們真的潰不成軍，燃燒軍團就有機會重整旗鼓大舉進犯，整個宇宙會為此顫抖。', 25549),
(122642, 'zhTW', '', '從這些被燃燒軍團摧毀的世界之中，有些生還者決定集結起來對抗惡魔。他們組成了聖光軍團。', 25549),
(122641, 'zhTW', '', '從此之後，沒有人能夠抵擋薩格拉斯，這位黑暗泰坦率領燃燒軍團吞噬一個又一個世界，所向無敵。', 25549),
(122640, 'zhTW', '', '很久以前，一場重要的戰役，決定了所有世界的命運。在這場戰役中，萬神殿被同是泰坦的薩格拉斯擊潰。', 25549),
(122639, 'zhTW', '', '你來到萬物創始的搖籃尋求答案。耐心聆聽，你就會受到啟迪。', 25549),
(122638, 'zhTW', '老朋友，安息吧。', '老朋友，安息吧。', 25549),
(122637, 'zhTW', '這裡沒有夢魘的一席之地，我們必須盡一切所能保護瑪洛尼。少了他，整個大自然的平衡都會被破壞。$B$B恐怕再也沒有比救他更重要的事…就算犧牲生命，也在所不惜。', '', 25549),
(122636, 'zhTW', '', '對荒野神靈來說，重新面對這段時光想必很痛苦。燃燒軍團入侵時的恐怖場面，我想都不敢想。', 25549),
(122635, 'zhTW', '', '我完全不喜歡這個地方。我們去消滅那些入侵的怪物，大德魯伊！', 25549),
(122634, 'zhTW', '', '散佈夢魘的敵人非常狡猾。數千年前，他們選擇荒野神靈為了艾澤拉斯起身對抗燃燒軍團，而戰死沙場的那一刻出手。', 25549),
(122633, 'zhTW', '席里斯，你沒事吧？', '席里斯，你沒事吧？', 25549),
(122632, 'zhTW', '雅夏，你自由了。', '雅夏，你自由了。', 25549),
(122631, 'zhTW', '賈岡諾斯會…解決你…', '', 25549),
(122630, 'zhTW', '有小偷！', '', 25549),
(122629, 'zhTW', '$c，你小心點…', '', 25549),
(122628, 'zhTW', '', '我早就跟他們說過會發生這種事。\n\n我早就說過了。\n\n他們聽進去了嗎？！', 25549),
(122627, 'zhTW', '告訴我，$c，你看過達拉然各種千奇百怪的商品了嗎？如果你還是找不到需要的東西，或許我認識幫得上忙的人。', '', 25549),
(122626, 'zhTW', '', '你擋到我的箱子了，快滾吧！', 25549),
(122625, 'zhTW', '', '我就歐歐歐知道你是燃安安安燒軍團的人。我在學你。你的聲音就像那樣。', 25549),
(122624, 'zhTW', '你好啊，好市民。有什麼問題嗎？', '', 25549),
(122623, 'zhTW', '賴瑞要把你打成好吃的肉醬！', '', 25549),
(122622, 'zhTW', '喝！這傢伙完了！', '', 25549),
(122621, 'zhTW', '為了榮耀！', '為了榮耀！', 25549),
(122620, 'zhTW', '他們會屈服於我們的怒火。', '他們會屈服於我們的怒火。', 25549),
(122619, 'zhTW', '為歐丁奮戰至死！', '為歐丁奮戰至死！', 25549),
(122618, 'zhTW', '維爾薩拉', '維爾薩拉', 25549),
(122617, 'zhTW', '我的戰矛，供您差遣。', '我的戰矛，供您差遣。', 25549),
(122616, 'zhTW', '華爾琪，該是我們表現的時候了！開戰吧！', '華爾琪，該是我們表現的時候了！開戰吧！', 25549),
(122615, 'zhTW', '華爾琪！戰爭要開始了！準備應戰！', '華爾琪！戰爭要開始了！準備應戰！', 25549),
(122614, 'zhTW', '高嶺', '高嶺', 25549),
(122613, 'zhTW', '艾蘇納', '艾蘇納', 25549),
(122612, 'zhTW', '請立刻幫我安排飛行坐騎離開這裡！', '請立刻幫我安排飛行坐騎離開這裡！', 25549),
(122611, 'zhTW', '我看到一名$c在城裡找你，還提到關於遠古武器的事。在你前往破碎群島之前，應該先去聊聊。盡量多找點幫手，會用得到的。\n\n我的意思是…如果你真的要，我可以幫你找到航班立刻飛過去。不過我不建議。', '', 25549),
(122610, 'zhTW', '我們的傷應該恢復得差不多了。我會繼續偵察。照顧自己，莉爾芮雅。', '', 25549),
(122609, 'zhTW', '', '啊！這下子我真的生氣了！', 25549),
(122608, 'zhTW', '', '我們為何而戰？', 25549),
(122607, 'zhTW', '我們能獲得瑪洛尼警告真的很幸運。他所說的實在令人害怕。我擔心翡翠夢境，如果夢境腐化了，一定會對艾澤拉斯造成莫大的影響。', '', 25549),
(122606, 'zhTW', '', '打得好！這就是與守夜者為敵的下場！', 25549),
(122605, 'zhTW', '準備好進攻赫德夏爾了。', '準備好進攻赫德夏爾了。', 25549),
(122604, 'zhTW', '', '那些強大的法師密謀在想辦法對付守夜者。讓他們知道我們都怎麼對付敵人的！', 25549),
(122603, 'zhTW', '', '連靈魂都知道要服從力量。做得好！', 25549),
(122602, 'zhTW', '', '千燈神廟裡到處都是發狂的靈魂。該是教訓他們的時候了。', 25549),
(122601, 'zhTW', '<使用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力啟動模組。>', '<使用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力啟動模組。>', 25549),
(122600, 'zhTW', '這個模組似乎失去能量來源很久了。', '', 25549),
(122599, 'zhTW', '如果你需要前往達拉然，我的蝙蝠隨時待命。', '', 25549),
(122598, 'zhTW', '搞什咚咚？', '', 25549),
(122597, 'zhTW', '先知，海達希亞水元素與你同在。燃燒軍團不會得逞的！', '', 25549),
(122596, 'zhTW', '前方的洞窟傳來一陣詭異的吼聲。', '前方的洞窟傳來一陣詭異的吼聲。', 25549),
(122595, 'zhTW', '備感光榮。', '備感光榮。', 25549),
(122594, 'zhTW', '我的護盾，供您差遣。', '我的護盾，供您差遣。', 25549),
(122593, 'zhTW', '保護弱者。', '保護弱者。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122592, 'zhTW', '你從樓下的傳送門聽見一陣奇異的嘎響聲。', '你從樓下的傳送門聽見一陣奇異的嘎響聲。', 25549),
(122591, 'zhTW', '', '無冕者是達到目的的手段。而目的是消滅燃燒軍團。', 25549),
(122590, 'zhTW', '恐角龍', '恐角龍', 25549),
(122589, 'zhTW', '多頭蛇', '多頭蛇', 25549),
(122588, 'zhTW', '河獸', '河獸', 25549),
(122587, 'zhTW', '萊拉克', '萊拉克', 25549),
(122586, 'zhTW', '機械', '機械', 25549),
(122585, 'zhTW', '我準備好動身尋找最後的神兵了。', '我準備好動身尋找最後的神兵了。', 25549),
(122584, 'zhTW', '', '冷靜一點，我們很快就能回家。', 25549),
(122583, 'zhTW', '', '要是你打破了，媽媽就得買下來。', 25549),
(122582, 'zhTW', '', '不可以碰玻璃，記住我們說好的。', 25549),
(122581, 'zhTW', '', '保持安靜，讓媽媽好好瀏覽。', 25549),
(122580, 'zhTW', '', '小子，小手不要到處亂摸。', 25549),
(122579, 'zhTW', '', '別給我打破任何東西。', 25549),
(122578, 'zhTW', '我想回顧我們目前針對剩下的神兵武器所獲得的資訊。', '我想回顧我們目前針對剩下的神兵武器所獲得的資訊。', 25549),
(122577, 'zhTW', '裂隙核心充能完畢，請審慎部署裂隙加農砲。', '裂隙核心充能完畢，請審慎部署裂隙加農砲。', 25549),
(122576, 'zhTW', '命令既出，我們將立即開始為裂隙核心充能。', '命令既出，我們將立即開始為裂隙核心充能。', 25549),
(122575, 'zhTW', '彌米倫給了我一個傳送器，以防有緊急情況。我想這就算緊急情況了吧！', '', 25549),
(122574, 'zhTW', '我很期待再次看見麥格尼。已經好久不見了。', '', 25549),
(122573, 'zhTW', '召喚船夫，付船費，放棄靈魂不後悔！', '', 25549),
(122572, 'zhTW', '你想去黑爾海姆？那就祝你一路好走！哈哈哈哈！', '', 25549),
(122571, 'zhTW', '你敢叫船夫過來，就得付出代價！', '', 25549),
(122570, 'zhTW', '眾魂哪！把這些凡人推入海潮！！！', '', 25549),
(122569, 'zhTW', '雄鹿', '雄鹿', 25549),
(122568, 'zhTW', '這個舉動會耗費50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。你要繼續嗎？', '這個舉動會耗費50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。你要繼續嗎？', 25549),
(122567, 'zhTW', '<花費50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力，釋放魔縛法力刃豹。>', '<花費50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力，釋放魔縛法力刃豹。>', 25549),
(122566, 'zhTW', '聖光會懲罰你！', '', 25549),
(122565, 'zhTW', '你知道我是國王吧？', '', 25549),
(122564, 'zhTW', '蘇拉瑪爾會重見天日。', '蘇拉瑪爾會重見天日。', 25549),
(122563, 'zhTW', '<這隻法力刃豹被燃燒軍團囚禁起來，不過用上古法力使水晶超載就能釋放這隻野獸。>', '', 25549),
(122562, 'zhTW', '你在考驗我的耐心。', '', 25549),
(122561, 'zhTW', '現在真的不是時候。', '', 25549),
(122560, 'zhTW', '聖光會帶來勝利。', '', 25549),
(122559, 'zhTW', '旅途平安。', '', 25549),
(122558, 'zhTW', '別放棄希望。', '', 25549),
(122557, 'zhTW', '暴風城永遠歡迎你。', '', 25549),
(122556, 'zhTW', '保持警戒。', '', 25549),
(122555, 'zhTW', '國王的高貴取決於他內心的信念。', '', 25549),
(122554, 'zhTW', '一切都是為了聯盟。', '', 25549),
(122553, 'zhTW', '正義是值得捍衛的。', '', 25549),
(122552, 'zhTW', '有時候我們必須為自己的信念而戰。', '', 25549),
(122551, 'zhTW', '你好啊，朋友。', '', 25549),
(122550, 'zhTW', '暴風城不會倒下。', '', 25549),
(122549, 'zhTW', '暴風城感激你為聯盟所做的一切。', '', 25549),
(122548, 'zhTW', '燃燒軍團將會在四騎士的力量之前顫抖！', '', 25549),
(122547, 'zhTW', '各位騎士！命運的一刻即將來臨！', '', 25549),
(122546, 'zhTW', '不！我不會讓黯刃騎士團失敗！', '', 25549),
(122545, 'zhTW', '我還太有錢，不該就這樣死掉！', '我還太有錢，不該就這樣死掉！', 25549),
(122544, 'zhTW', '守衛，發什麼呆？快殺掉這頭野獸！', '守衛，發什麼呆？快殺掉這頭野獸！', 25549),
(122543, 'zhTW', '蘇艾許掙脫了！快逃！', '蘇艾許掙脫了！快逃！', 25549),
(122542, 'zhTW', '我們都要死掉了！', '我們都要死掉了！', 25549),
(122541, 'zhTW', '你想搶我的島！好啊！我就用你的血來裝飾！', '', 25549),
(122540, 'zhTW', '', '能為白銀之手騎士團效力是我的光榮，$ct。', 25549),
(122539, 'zhTW', '什麼？！', '幹嘛？！', 25549),
(122538, 'zhTW', '哈！你的法力惡魔現在在哪啊？', '哈！你的法力惡魔現在在哪啊？', 25549),
(122537, 'zhTW', '需要清理什麼嗎？', '', 25549),
(122536, 'zhTW', '我沒空跟你聊。必須好好清理。', '', 25549),
(122535, 'zhTW', '忙，好忙。必、必須回去工作。', '', 25549),
(122534, 'zhTW', '我準備好出發去奧杜亞了！', '我準備好出發去奧杜亞了！', 25549),
(122533, 'zhTW', '我們得加快腳步，$n！', '', 25549),
(122532, 'zhTW', '我絕不會讓你搶走我的島！', '', 25549),
(122531, 'zhTW', '真是令人不快的工作，然而是必須的。我來準備傳送伊露恩之淚。到紫羅蘭城塞找我。', '', 25549),
(122530, 'zhTW', '為什麼你不去自己的島！', '', 25549),
(122529, 'zhTW', '這個島是我的！', '', 25549),
(122528, 'zhTW', '守衛嗅嗅你，然後輕輕哼了一聲。', '', 25549),
(122527, 'zhTW', '樂意之至。', '樂意之至。', 25549),
(122526, 'zhTW', '好極了！每次看到像你這樣的年輕英雄願意花時間研讀歷史，我就感到欣慰。畢竟能通過時間考驗的事才是重要的事。\n\n我有個東西…為了感謝你的努力，我想送你一本完全不一樣的書。有興趣嗎？', '', 25549),
(122525, 'zhTW', '我已經收集到每一本書了。', '我已經收集到每一本書了。', 25549),
(122524, 'zhTW', '勇士，找你找好久！喔，你說為什麼把頭裝在水晶球裡嗎？我在嘗試新東西。', '', 25549),
(122523, 'zhTW', '<這位孤單的冒險者慘遭不幸。>\n\n<很不幸地，沒有辦法能救他。>', '', 25549),
(122522, 'zhTW', '<這位孤單的冒險者慘遭不幸。>', '', 25549),
(122521, 'zhTW', '招募白銀之手聖殿騎士', '招募白銀之手聖殿騎士', 25549),
(122520, 'zhTW', '招募白銀之手騎士', '招募白銀之手騎士', 25549),
(122519, 'zhTW', '有我可以幫忙的嗎？', '有我可以幫忙的嗎？', 25549),
(122518, 'zhTW', 'Gamer timer', 'Gamer timer', 25549),
(122517, 'zhTW', 'End current round', 'End current round', 25549),
(122516, 'zhTW', 'Tier 4 Defended', 'Tier 4 Defended', 25549),
(122515, 'zhTW', 'Tier 3 Defended', 'Tier 3 Defended', 25549),
(122514, 'zhTW', 'Tier 2 Defended', 'Tier 2 Defended', 25549),
(122513, 'zhTW', '<為其中一把三叉戟注入25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', '<為其中一把三叉戟注入25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', 25549),
(122512, 'zhTW', 'Tier 1 Defended', 'Tier 1 Defended', 25549),
(122511, 'zhTW', '這些看似平凡的武器有隱藏的力量。', '', 25549),
(122510, 'zhTW', '你從前往辛特蘭的通道聽見一陣奇異、野蠻的尖嘯聲。', '你從前往辛特蘭的通道聽見一陣奇異、野蠻的尖嘯聲。', 25549),
(122509, 'zhTW', '你從前往菲拉斯的通道聽見一陣奇異、野蠻的尖嘯聲。', '你從前往菲拉斯的通道聽見一陣奇異、野蠻的尖嘯聲。', 25549),
(122508, 'zhTW', '你從前往暮色森林的通道聽見一陣奇異、野蠻的尖嘯聲。', '你從前往暮色森林的通道聽見一陣奇異、野蠻的尖嘯聲。', 25549),
(122507, 'zhTW', '', '有時候想做對一件事，只能親自下手…', 25549),
(122506, 'zhTW', '', '讓你看看燃燒軍團的力量！', 25549),
(122505, 'zhTW', '我為聖光奉獻生命。', '我為聖光奉獻生命。', 25549),
(122504, 'zhTW', '我願意為你戰鬥。', '我願意為你戰鬥。', 25549),
(122503, 'zhTW', '你聽見某種東西從你身後跑走…然後就一片寂靜。', '你聽見某種東西從你身後跑走…然後就一片寂靜。', 25549),
(122502, 'zhTW', '好樣的…', '', 25549),
(122501, 'zhTW', '詛咒…你…', '', 25549),
(122500, 'zhTW', '你對我而言只是暖身的暖身。', '', 25549),
(122499, 'zhTW', '我是主人的兒子。你不是我的對手。', '', 25549),
(122498, 'zhTW', '讓我們為了聖光一同奮戰，保衛虛空之光神殿。走，去傳送門！', '', 25549),
(122497, 'zhTW', '我們已經武裝就緒，隨時可以出戰，大祭司。', '', 25549),
(122496, 'zhTW', '燃燒軍團開始進攻了。我們必須守護虛空之光神殿！', '燃燒軍團開始進攻了。我們必須守護虛空之光神殿！', 25549),
(122495, 'zhTW', '看來我們來得正是時候。', '', 25549),
(122494, 'zhTW', '炸藥！更多炸藥！我還要更多炸藥！', '', 25549),
(122493, 'zhTW', '篡位者！諾姆瑞根是我的！', '', 25549),
(122492, 'zhTW', '騎士們！我們的時代降臨了！', '', 25549),
(122491, 'zhTW', '死亡領主，你準備好了就來上層找我。', '', 25549),
(122490, 'zhTW', '是該由我出馬來帶領四騎士了。', '', 25549),
(122489, 'zhTW', '主宰，懼痕聽你號令。\n\n願敵人的世界全都臣服在你腳下。', '', 25549),
(122488, 'zhTW', '', '侍從！保護我們，別讓他們打擾儀式！', 25549),
(122487, 'zhTW', '別害怕，我會抽取夜井的力量來消滅他們！', '', 25549),
(122486, 'zhTW', '入侵者！', '', 25549),
(122485, 'zhTW', '我知道你們來了。但儀式會繼續下去。', '我知道你們來了。但儀式會繼續下去。', 25549),
(122484, 'zhTW', '|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s召喚了一道|cFFFF0000|Hspell:226089|h[暗影影像]|h|r！快將它放逐！', '|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s召喚了一道|cFFFF0000|Hspell:226089|h[暗影影像]|h|r！快將它放逐！', 25549),
(122483, 'zhTW', '我準備好了。', '我準備好了。', 25549),
(122482, 'zhTW', '大德魯伊，和我一起去找遠古種子。我們可以在那裡解開武器的秘密。', '', 25549),
(122481, 'zhTW', '夢魘奪取你的意志！', '夢魘奪取你的意志！', 25549),
(122480, 'zhTW', '是時候了！白銀之手先鋒，上戰場吧！', '是時候了！白銀之手先鋒，上戰場吧！', 25549),
(122479, 'zhTW', '為了榮耀！', '為了榮耀！', 25549),
(122478, 'zhTW', '嗯，把我送回去吧。我還沒準備好。', '嗯，把我送回去吧。我還沒準備好。', 25549),
(122477, 'zhTW', '我們在這裡的任務至關緊要。但如果你需要更多時間準備，我可以把你送回蒼穹殿。你想回去嗎？', '我們在這裡的任務至關緊要。但如果你需要更多時間準備，我可以把你送回蒼穹殿。你想回去嗎？', 25549),
(122476, 'zhTW', '我還沒準備好。', '我還沒準備好。', 25549),
(122475, 'zhTW', '<傳送門因為魔法而嗡嗡作響。>', '', 25549),
(122474, 'zhTW', '解碼', '解碼', 25549),
(122473, 'zhTW', '我會為你效力，大人。', '我會為你效力，大人。', 25549),
(122472, 'zhTW', '白銀之手的聖騎士！整裝閱兵！', '白銀之手的聖騎士！整裝閱兵！', 25549),
(122471, 'zhTW', '來吧。來守護者熔爐找我。', '', 25549),
(122470, 'zhTW', '這些惡魔派出了什麼樣的怪物！？月神救救我們！', '', 25549),
(122469, 'zhTW', '到逆風小徑上方的達拉然找我。我有個計畫。一個可怕、危險的計畫…但至少是個計畫！', '', 25549),
(122468, 'zhTW', '我們需要創世之柱的力量才能把惡魔送回扭曲虛空，拯救這個世界。', '', 25549),
(122467, 'zhTW', '達拉然遭受攻擊了，英雄！燃燒軍團想把我們從空中擊落！', '', 25549),
(122466, 'zhTW', '', '驕傲地穿上外袍吧，$n。穿著我們紅色的布料，敵人就看不見你流血。', 25549),
(122465, 'zhTW', '哈！七個字，不寫了。', '', 25549),
(122464, 'zhTW', '你寫過什麼。', '你寫過什麼。', 25549),
(122463, 'zhTW', '讓我們休息吧，主人。', '讓我們休息吧，主人。', 25549),
(122462, 'zhTW', '月之守衛，把力量集中傳給我！我們要讓這些怪物嚐嚐秘法的力量！', '', 25549),
(122461, 'zhTW', '大人，在你背後！又有惡魔來了！', '', 25549),
(122460, 'zhTW', '所以我常說魔法很麻煩，你永遠不知道什麼時候會被反咬一口！', '', 25549),
(122459, 'zhTW', '我向來討厭水元素…尤其是這麼大隻的！', '', 25549),
(122458, 'zhTW', '別再釣魚了，快幫我解決這個元素生物！', '', 25549),
(122457, 'zhTW', '你要動手嗎，還是像個懦夫瞪著我就好？', '', 25549),
(122456, 'zhTW', '', '來吧，骯髒的外來者。第一下讓你，好好把握吧。', 25549),
(122455, 'zhTW', '祈求祝福', '祈求祝福', 25549),
(122454, 'zhTW', '', '教團與你同在。', 25549),
(122453, 'zhTW', '', '艾莉珊德會為她的不義付出代價。', 25549),
(122452, 'zhTW', '我們攻陷監獄大門了！朝達拉然前進！', '', 25549),
(122451, 'zhTW', '他們早該聽我的，把薩特殺光就沒這些事了。\n\n$p，謝謝你幫我脫離薩維斯的瘋狂。', '', 25549),
(122450, 'zhTW', '', '夜井的能量在向我呼喚。', 25549),
(122449, 'zhTW', '', '我一直等待回家的那天到來…', 25549),
(122448, 'zhTW', '<使用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力，萃取一些地脈能量。>', '<使用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力，萃取一些地脈能量。>', 25549),
(122447, 'zhTW', '繼續前進，這裡不宜久留。', '', 25549),
(122446, 'zhTW', '結界脈動著滿滿的能量。', '', 25549),
(122445, 'zhTW', '燃燒軍團今天必敗，勇士。', '', 25549),
(122444, 'zhTW', '我們得在儀式完成前阻止古爾丹。', '', 25549),
(122443, 'zhTW', '苟雅女士把東西收了，叫我好好看守這裡。她提到會飛的城市。哈哈！城市怎麼可能會飛！', '', 25549),
(122441, 'zhTW', '我們能用明晰精華的力量進入夢魘深處嗎？', '我們能用明晰精華的力量進入夢魘深處嗎？', 25549),
(122440, 'zhTW', '我準備好開始保衛虛空之光神殿。', '我準備好開始保衛虛空之光神殿。', 25549),
(122439, 'zhTW', '我們不能再等下去了。是迎擊燃燒軍團的時候了。', '', 25549),
(122438, 'zhTW', '我們應該繼續巡邏。在這片土地上，不知道還有多少像這樣的攻擊行動。', '', 25549),
(122437, 'zhTW', '我還以為這些惡魔有多厲害。或許我們能找到一個深淵領主。我一直想束縛深淵領主的精華。', '', 25549),
(122436, 'zhTW', '儀式中斷了。夜井封印的生物醒了。', '儀式中斷了。夜井封印的生物醒了。', 25549),
(122435, 'zhTW', '你在塔中聽見節奏穩定的咒語呢喃聲。', '你在塔中聽見節奏穩定的咒語呢喃聲。', 25549),
(122434, 'zhTW', '夢魘的守護者已經倒下，還要怎麼做才能找到薩維斯呢？', '夢魘的守護者已經倒下，還要怎麼做才能找到薩維斯呢？', 25549),
(122433, 'zhTW', '你做到了，勇士！魔瞳的封印解開了，跟我說一聲，我就會把它開啟。', '', 25549),
(122432, 'zhTW', '<提供20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', '<提供20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', 25549),
(122431, 'zhTW', '艾修，艾索洛圖斯之子，新的霜火之怒，希望賜福於你。', '', 25549),
(122430, 'zhTW', '$ct，我們需要你。跟我來。', '', 25549),
(122429, 'zhTW', '這祭壇好像很久沒用了。', '', 25549),
(122421, 'zhTW', '聯盟的英雄，我在艾澤拉斯最黑暗的時刻寫了這封信給你們。燃燒軍團從地獄深淵回來了。', '', 25549),
(122420, 'zhTW', '太厲害了，你的武器與經歷證明了即使是華爾拉亞，也能從其他年輕的種族學到新東西。我已歷經多年戰鬥，但還有許多敵人與戰鬥方式是我沒見過的。你讓我有很多東西能研究，謝謝你。', '', 25549),
(122419, 'zhTW', '擋住他們！不能讓這座城市失守！', '', 25549),
(122418, 'zhTW', '他們突然出現！我們得想辦法把他們一次解決！', '', 25549),
(122417, 'zhTW', '如果不阻止薩維斯，夢魘就會吞噬艾澤拉斯。', '', 25549),
(122416, 'zhTW', '晚到總比不到好，是吧？只要我們還有一口氣，就會戰鬥下去！你準備好…', '', 25549),
(122415, 'zhTW', '別發呆，$n！光站著殺不了惡魔！', '', 25549),
(122414, 'zhTW', '督軍！', '', 25549),
(122413, 'zhTW', '|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|t$n死亡時會|cFFFF0000|Hspell:202663|h[引爆]|h|r！', '', 25549),
(122412, 'zhTW', '走開！', '走開！', 25549),
(122411, 'zhTW', '', '快把魔精調好，我們得送去破碎海岸！', 25549),
(122410, 'zhTW', '快讓我從夢魘中醒來！', '快讓我從夢魘中醒來！', 25549),
(122409, 'zhTW', '這個地方…比我想得還糟。', '', 25549),
(122408, 'zhTW', '|TInterface\\Icons\\sha_spell_shadow_shadesofdarkness_nightmare:20|t%s開始施放|cFFFF0000|Hspell:214876|h[夢魘野獸]|h|r！', '', 25549),
(122407, 'zhTW', '', '銀月城與你同在，$n。請讓我們用神聖的力量幫你的武器加持。', 25549),
(122406, 'zhTW', '$n，護甲只要有一點縫隙，就會讓惡魔有機可乘。不想死，就修修裝吧！', '', 25549),
(122405, 'zhTW', '<將20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力投入防禦矩陣。>', '<將20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力投入防禦矩陣。>', 25549),
(122404, 'zhTW', '<防禦法陣似乎沒有動力。>', '', 25549),
(122403, 'zhTW', '我必須回到地面。', '我必須回到地面。', 25549),
(122402, 'zhTW', '如果你不確定接下來的方向，我可以帶你回地面。你確定要這麼做嗎？', '', 25549),
(122401, 'zhTW', '', '我的技術絕對無人能匹敵！$b$b不過聽說來了一個競爭者，他在城外做跟我一樣的鍛造工作。$b$b我喜歡挑戰。放馬過來吧！哈哈哈！', 25549),
(122400, 'zhTW', '', '糟糕。$b$b你的護甲似乎需要修理了。', 25549),
(122399, 'zhTW', '歡迎光臨。你想喝點什麼？', '', 25549),
(122398, 'zhTW', '', '坐下來，放輕鬆！', 25549),
(122397, 'zhTW', '', '我們沒酒了，但是還有不少食物、飲料，還有很多空間讓你歇歇腳！', 25549),
(122396, 'zhTW', '', '親愛的，你好啊！$b$b你想點什麼？', 25549),
(122395, 'zhTW', '', '水晶已充能完畢。請好好使用。', 25549),
(122394, 'zhTW', '<爛腸轉身看著你，然後打了一個巨大的嗝。>$b$b爛腸…爛…腸！', '', 25549),
(122393, 'zhTW', '', '咒術師，開始引導吧！', 25549),
(122392, 'zhTW', '是格哈尼爾守護者！$n，我們就仰賴你了。', '是格哈尼爾守護者！$n，我們就仰賴你了。', 25549),
(122391, 'zhTW', '是$n！淨化格哈尼爾的英雄！', '是$n！淨化格哈尼爾的英雄！', 25549),
(122390, 'zhTW', '拿到格哈尼爾的是好人，這真是太好了。', '拿到格哈尼爾的是好人，這真是太好了。', 25549),
(122389, 'zhTW', '是格哈尼爾守護者！願伊露恩祝福你，$n！', '是格哈尼爾守護者！願伊露恩祝福你，$n！', 25549),
(122388, 'zhTW', '尖牙持有者，很高興你和塞納里奧議會同一陣線！', '尖牙持有者，很高興你和塞納里奧議會同一陣線！', 25549),
(122387, 'zhTW', '達拉然為了保衛東部王國，現在已經移到逆風小徑這一帶，就在卡拉贊上方。我懇請你加入我的行列。', '', 25549),
(122386, 'zhTW', '$n，我認得出那對匕首。那是亞夏曼之牙，對吧？你一定做了很厲害的事，讓亞夏曼願意把匕首交給你。', '$n，我認得出那對匕首。那是亞夏曼之牙，對吧？你一定做了很厲害的事，讓亞夏曼願意把匕首交給你。', 25549),
(122385, 'zhTW', '我也不願耽擱你的重要工作，但我有個…外交任務，需要你幫忙。我可能快激怒一位老朋友了。', '', 25549),
(122384, 'zhTW', '你好，英雄。我的情報來源指出你一直致力於對抗燃燒軍團的侵略。', '', 25549),
(122383, 'zhTW', '亞夏曼之牙！我還以為亞夏曼德魯伊不會把它們交給任何人！', '亞夏曼之牙！我還以為亞夏曼德魯伊不會把它們交給任何人！', 25549),
(122382, 'zhTW', '那對匕首看起來真奇怪。那是…牙齒嗎？', '那對匕首看起來真奇怪。那是…牙齒嗎？', 25549),
(122381, 'zhTW', '是亞夏曼之牙！看來亞夏曼神殿被攻擊的事是真的了！', '是亞夏曼之牙！看來亞夏曼神殿被攻擊的事是真的了！', 25549),
(122380, 'zhTW', '', '瑟希斯會替我們備妥一艘船，做為我們的運輸工具。我們會駛離陸地，然後當黑暗降臨或是水面上起大霧時，他會再載我們靠岸。\n\n等你準備好啟程的時候就讓我知道，$n。', 25549),
(122379, 'zhTW', '為大德魯伊$n歡呼！厄索克的勇士！', '為大德魯伊$n歡呼！厄索克的勇士！', 25549),
(122378, 'zhTW', '我們的勇士得到了厄索克之爪！燃燒軍團的末日不遠了！', '我們的勇士得到了厄索克之爪！燃燒軍團的末日不遠了！', 25549),
(122377, 'zhTW', '傳言是真的。厄索克之爪在$n手上！', '傳言是真的。厄索克之爪在$n手上！', 25549),
(122376, 'zhTW', '那些爪子看起來還真銳利。幸好你跟我們同一陣線！', '那些爪子看起來還真銳利。幸好你跟我們同一陣線！', 25549),
(122375, 'zhTW', '尊師，歡迎。能見到鐮刀的主人是我的榮幸。', '尊師，歡迎。能見到鐮刀的主人是我的榮幸。', 25549),
(122374, 'zhTW', '是伊露恩之鐮！居然得動用那把武器的力量才能打這場仗，看來危急存亡的時刻真的到了。', '是伊露恩之鐮！居然得動用那把武器的力量才能打這場仗，看來危急存亡的時刻真的到了。', 25549),
(122373, 'zhTW', '你身上那把是伊露恩之鐮嗎？它真的會讓你變成野獸嗎？', '你身上那把是伊露恩之鐮嗎？它真的會讓你變成野獸嗎？', 25549),
(122372, 'zhTW', '尊師，你必須小心使用那把鐮刀。畢竟誰都不想失去自我。', '尊師，你必須小心使用那把鐮刀。畢竟誰都不想失去自我。', 25549),
(122371, 'zhTW', '願伊露恩與你同…等等，你手上拿的是伊露恩之鐮嗎？太厲害了！', '願伊露恩與你同…等等，你手上拿的是伊露恩之鐮嗎？太厲害了！', 25549),
(122370, 'zhTW', '', '儀式完成，快點控制它！', 25549),
(122369, 'zhTW', '', '很好，很好，成功了！', 25549),
(122368, 'zhTW', '', '召喚師，展開儀式吧！', 25549),
(122367, 'zhTW', '', '我過去的罪行與旁人無關，只能由我獨自肩負。然而，燃燒軍團腐化了血色十字軍，讓我們偏離正道。$b$b我要讓燃燒軍團為其背叛付出代價！', 25549),
(122366, 'zhTW', '這個舉動會耗費20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。你要繼續嗎？', '這個舉動會耗費20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。你要繼續嗎？', 25549),
(122365, 'zhTW', '<給夜裔鄙惡者5份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', '<給夜裔鄙惡者5份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', 25549),
(122364, 'zhTW', '你想把沙亞蘭設定為你的新家嗎？', '你想把沙亞蘭設定為你的新家嗎？', 25549),
(122363, 'zhTW', '我想將我的爐石綁定在這裡。', '我想將我的爐石綁定在這裡。', 25549),
(122362, 'zhTW', '我想要進行交易。', '我想要進行交易。', 25549),
(122361, 'zhTW', '', '走開！髒東西！', 25549),
(122360, 'zhTW', '飛艇動起來了！救命啊！', '', 25549),
(122359, 'zhTW', '快散開！這艘飛艇完全不受控制！', '', 25549),
(122358, 'zhTW', '小心！我好像沒辦法控制這東西！', '', 25549),
(122357, 'zhTW', '別擋路！這東西一點也不安全！', '', 25549),
(122356, 'zhTW', '離遠一點！誰知道這個東西在搞什麼花樣！', '', 25549),
(122355, 'zhTW', '你在找什麼？', '', 25549),
(122354, 'zhTW', '', '有什麼能幫你的嗎？', 25549),
(122353, 'zhTW', '破碎之手會帶領部落重返昔日的榮耀。', '', 25549),
(122352, 'zhTW', '需要什麼嗎，潛影$n？', '', 25549),
(122351, 'zhTW', '', '這些元素生物會是我們對抗燃燒軍團的利器。', 25549),
(122350, 'zhTW', '你好。', '', 25549),
(122349, 'zhTW', '你在找什麼？', '', 25549),
(122348, 'zhTW', '我能為你做什麼？', '', 25549),
(122347, 'zhTW', '', '希望這些小鬼能派上用場，虛空領主。', 25549),
(122346, 'zhTW', '', '放心，這些弓箭手不會讓目標逃走的。', 25549),
(122345, 'zhTW', '這些華爾拉亞志士會是我們對抗燃燒軍團的助力！', '', 25549),
(122344, 'zhTW', '卑賤的小蟲！', '', 25549),
(122343, 'zhTW', '煉獄現世！', '', 25549),
(122342, 'zhTW', '卑微的地精！你的傲慢將使你喪命！', '', 25549),
(122341, 'zhTW', '焚肉挫骨！', '', 25549),
(122340, 'zhTW', '你面對的是賈拉克瑟斯，燃燒軍團的埃雷達爾領主!', '', 25549),
(122339, 'zhTW', '吉！…吉！…能不能請你提醒出納員吉，我還在這裡，我一直在等著恢復原狀。萬分感激。', '', 25549),
(122338, 'zhTW', '啊，又來了一位貴客！歡迎！歡迎！', '', 25549),
(122337, 'zhTW', '沒有任何問題！你就跟平常一樣去做你的事吧。一切都在我們的掌控當中！', '', 25549),
(122336, 'zhTW', '請幫我提醒吉，我需要他付加班費。因為就技術上而言，我還在工作崗位。', '', 25549),
(122335, 'zhTW', '我們很快就會解決這個問題！請稍安勿躁。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122334, 'zhTW', '這個現象完全正常。請不要驚慌！', '', 25549),
(122333, 'zhTW', '我們很清楚這裡的狀況，一切都在掌控中！', '', 25549),
(122332, 'zhTW', '', '準備好再打一場了嗎，$n？我隨時隨地奉陪。', 25549),
(122330, 'zhTW', '我會去安全的地方。不會再被抓到了！', '我會去安全的地方。不會再被抓到了！', 25549),
(122329, 'zhTW', '我…謝謝你。牠們聽起來很餓…', '我…謝謝你。牠們聽起來很餓…', 25549),
(122328, 'zhTW', '謝謝你把我從這可怕的地方救出來。$b$b我很會修理裝備。你有東西需要修理的嗎？', '', 25549),
(122327, 'zhTW', '一、二、三。測試，測試。', '', 25549),
(122326, 'zhTW', '前景不太明朗，去收集4289個頂尖水晶後，再來問我。', '', 25549),
(122325, 'zhTW', '這條時間線…不太可能。', '', 25549),
(122324, 'zhTW', '讓我問問我的消息來源…是。', '', 25549),
(122323, 'zhTW', '讓我問問我的消息來源…不。', '', 25549),
(122322, 'zhTW', '你有機會活下來。有機會啦。', '', 25549),
(122321, 'zhTW', '收訊…不清楚…再試一次？', '', 25549),
(122320, 'zhTW', '必敗無疑。', '', 25549),
(122319, 'zhTW', '毫無疑問。死定了！', '', 25549),
(122318, 'zhTW', '不行…才怪，當然好。', '', 25549),
(122317, 'zhTW', '', '我重生化為守護弱者的寶盾，捍衛信仰的使者，懲戒惡徒的利劍。', 25549),
(122316, 'zhTW', '我辜負了我的國家和人民…但我不會再辜負我們的世界。', '', 25549),
(122315, 'zhTW', '請過幾天再回來。我們非常重視有你這位客人…', '', 25549),
(122314, 'zhTW', '我們的員工都在不眠不休地確保你們的財物安然無恙！完全沒有必要擔心。', '', 25549),
(122313, 'zhTW', '完全沒有什麼需要擔心的。只不過是移動這麼巨大又充滿魔法的城市，一定會出現的副作用。', '', 25549),
(122312, 'zhTW', '沒錯，沒錯。我們知道情況看起來很糟。等我們恢復營業，你們託付給我們的所有財物都會好好地在這裡。我向你們保證。', '', 25549),
(122311, 'zhTW', '各位！各位！請聽我說…雖然看起來很怪，但是一切都已經控制住了。我們已經加派守衛，確保不會有東西不見。', '', 25549),
(122310, 'zhTW', '請大家退後一步！這只是移動城市的副作用。我們馬上就會恢復營業！', '', 25549),
(122309, 'zhTW', '讓我們看看你有什麼。', '讓我們看看你有什麼。', 25549),
(122308, 'zhTW', '向你致敬，$n。我有一些你可能派得上用場的東西。', '', 25549),
(122307, 'zhTW', '', '只要有黃金，連這種黑暗的地方都能變得明亮。', 25549),
(122306, 'zhTW', '你有什麼東西要賣嗎？', '你有什麼東西要賣嗎？', 25549),
(122305, 'zhTW', '你有什麼東西要賣嗎？', '你有什麼東西要賣嗎？', 25549),
(122304, 'zhTW', '', '你的生命之焰今天燒得很明亮，$n。', 25549),
(122303, 'zhTW', '別*嗝* 打斷！我們需要夜井的力量…', '別*嗝* 打斷！我們需要夜井的力量…', 25549),
(122302, 'zhTW', '不管你做什麼，千萬不要吃果盤裡的水果。$b$b那東西的味道糟透了。如果你想品嘗蘇拉瑪爾最美味的食物，我來幫你介紹。', '', 25549),
(122301, 'zhTW', '讓我們看看你有什麼。', '讓我們看看你有什麼。', 25549),
(122300, 'zhTW', '', '嗨啊，$n！今天有什麼事呢？', 25549),
(122299, 'zhTW', '讓我們看看你有什麼。', '讓我們看看你有什麼。', 25549),
(122298, 'zhTW', '', '嗨啊，$n！今天有什麼事呢？', 25549),
(122297, 'zhTW', '', '我們不會讓你通過的，凱萊翠絲女士！', 25549),
(122296, 'zhTW', '讓我們看看你有什麼。', '讓我們看看你有什麼。', 25549),
(122295, 'zhTW', '歡迎，$n。我有一些你可能派得上用場的東西。', '', 25549),
(122294, 'zhTW', '成功！', '', 25549),
(122293, 'zhTW', '願元素讓你無往不利。', '', 25549),
(122292, 'zhTW', '', '歡迎，$n。願天尊保佑你。', 25549),
(122291, 'zhTW', '讓我們看看你有什麼。', '讓我們看看你有什麼。', 25549),
(122290, 'zhTW', '嗯…今天沒有特別的羊嗎？可惡！也許明天運氣會好一些，對吧？', '', 25549),
(122289, 'zhTW', '', '侍從通常得花點時間才能訓練好，但我這次破例為你加緊腳步。', 25549),
(122288, 'zhTW', '', '他們怎麼會聽信信使的謊言？等著看好了 - 一定和黑暗魔法有關。\n\n拜託你，如果你有辦法阻止這一切，立刻動手吧。已經犧牲好多無辜的性命了…', 25549),
(122287, 'zhTW', '既然托莉爾說你是來幫我們的，那你可以在我們的爐火前休息，跟我們一起享用鮮肉與美酒！', '', 25549),
(122286, 'zhTW', '唉唉！真是滄海桑田。', '', 25549),
(122285, 'zhTW', '在我那個年代，樹比現在綠得多了。', '', 25549),
(122283, 'zhTW', '讓我們看看你有什麼。', '讓我們看看你有什麼。', 25549),
(122282, 'zhTW', '$n，我有一些東西，可能對你有用。', '', 25549),
(122281, 'zhTW', '請原諒我的詭計，戰鬥領主。就算是我自己選的勇士，我也不會干涉試煉！', '', 25549),
(122280, 'zhTW', '這些食屍鬼都會聽你號令，死亡領主。', '', 25549),
(122279, 'zhTW', '徵募一個天尊分身', '徵募一個天尊分身', 25549),
(122278, 'zhTW', '嗨！', '嗨！', 25549),
(122277, 'zhTW', '讓我們看看你有什麼。', '讓我們看看你有什麼。', 25549),
(122276, 'zhTW', '我能幫什麼忙嗎，$n？', '', 25549),
(122275, 'zhTW', '華爾拉亞，歐丁的榮光與你同在。', '', 25549),
(122274, 'zhTW', '徵募戰爭古樹', '徵募戰爭古樹', 25549),
(122273, 'zhTW', '<樹葉的窸窣聲>', '<樹葉的窸窣聲>', 25549),
(122272, 'zhTW', '來這裡，$c朋友！這傢伙有亮晶晶的東西。來看看吧！', '', 25549),
(122271, 'zhTW', '開始儀式', '開始儀式', 25549),
(122270, 'zhTW', '冰霜巨龍想被釋放。', '', 25549),
(122269, 'zhTW', '我聽說過你的豐功偉業。來看看你是不是名符其實，如何？', '', 25549),
(122268, 'zhTW', '喔，這可不是歐丁的勇士嗎！', '', 25549),
(122266, 'zhTW', '你已經救我兩次了…我的財產不多，但只要是我的東西，你都可以盡管拿走。', '', 25549),
(122265, 'zhTW', '如果你喜歡你的鞋子，最好往後站一點。', '', 25549),
(122264, 'zhTW', '讓我們看看你有什麼。', '讓我們看看你有什麼。', 25549),
(122263, 'zhTW', '', '歡迎光臨節瘤樹枝，$n。', 25549),
(122262, 'zhTW', '看看這團亂！我們的東西被到處亂拋！書掉在地上，工具也到處都是…我真希望能在城市移動之前收到通知！$B$B你看那裡的多里安。可憐的傢伙，他還在恢復中。', '', 25549),
(122261, 'zhTW', '', '很抱歉，$n，不過我們被要求暫時不收新學徒。等我們抵達最終目的地，相信一切都能恢復原狀。', 25549),
(122260, 'zhTW', '下一張勇士武裝的訂單', '下一張勇士武裝的訂單', 25549),
(122259, 'zhTW', '把死人帶來給我，我會想辦法派上用場。', '', 25549),
(122258, 'zhTW', '是凋萎者！他們打過來了。拜託你，幫我！', '', 25549),
(122257, 'zhTW', '等等…你聽到了嗎？', '', 25549),
(122256, 'zhTW', '讓我們看看你有什麼。', '讓我們看看你有什麼。', 25549),
(122255, 'zhTW', '謝…謝謝你…我…我不知道該怎麼活下去…我失去了一切。', '', 25549),
(122254, 'zhTW', '你需要什麼嗎，小傢伙？', '', 25549),
(122253, 'zhTW', '<給洛里安25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', '<給洛里安25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', 25549),
(122252, 'zhTW', '下一張勇士武裝的訂單', '下一張勇士武裝的訂單', 25549),
(122251, 'zhTW', '', '願聖光保佑你。', 25549),
(122250, 'zhTW', '他們殺了她…那些凋萎者殺了我的露妮兒。我…我一無所有了。', '', 25549),
(122249, 'zhTW', '我想聽聽這位惡魔獵人有什麼話要說。', '', 25549),
(122248, 'zhTW', '我需要完成這些樣品，$n！最後一批非常不穩定，差點在移動的過程中害死我們！$B$B最後那句話別跟其他人說。', '', 25549),
(122247, 'zhTW', '開始儀式', '開始儀式', 25549),
(122246, 'zhTW', '', '時候到了嗎？', 25549),
(122244, 'zhTW', '開始為魔錘號充能', '開始為魔錘號充能', 25549),
(122243, 'zhTW', '', '嗯？', 25549),
(122241, 'zhTW', '下一張勇士武裝的訂單。', '下一張勇士武裝的訂單。', 25549),
(122240, 'zhTW', '有什麼是我能幫忙的？', '有什麼是我能幫忙的？', 25549),
(122239, 'zhTW', '開始呼喚', '開始呼喚', 25549),
(122238, 'zhTW', '', '有什麼事嗎？', 25549),
(122237, 'zhTW', '露妮兒…親愛的露妮兒…我怎麼會讓你發生這種事？', '', 25549),
(122236, 'zhTW', '下一張勇士武裝的訂單。', '下一張勇士武裝的訂單。', 25549),
(122235, 'zhTW', '怎樣？', '', 25549),
(122232, 'zhTW', '送出消息召集白銀之手先鋒', '送出消息召集白銀之手先鋒', 25549),
(122231, 'zhTW', '你的命令是？', '', 25549),
(122230, 'zhTW', '|TInterface\\Icons\\spell_deathknight_necroticplague.blp:20|t你受到了|cFFF00000|Hspell:206480|h[腐屍瘟疫]|h|r的影響！', '', 25549),
(122229, 'zhTW', '拜託你…把這些怪物全部殺死。', '拜託你…把這些怪物全部殺死。', 25549),
(122228, 'zhTW', '自由了…終於自由了。我該怎麼離開這裡？', '自由了…終於自由了。我該怎麼離開這裡？', 25549),
(122227, 'zhTW', '我…我想我會撐過去的。謝謝你。', '我…我想我會撐過去的。謝謝你。', 25549),
(122226, 'zhTW', '好可怕…太可怕了。', '好可怕…太可怕了。', 25549),
(122225, 'zhTW', '我沒辦法繼續…', '我沒辦法繼續…', 25549),
(122224, 'zhTW', '我…已經這麼虛弱了…', '我…已經這麼虛弱了…', 25549),
(122223, 'zhTW', '如果你還沒學會在潘達利亞飛行，你可以先借用葛雷達克前往恆春谷。', '', 25549),
(122222, 'zhTW', '盒子又閃了一下。只要再一步就能啟動它了！', '盒子又閃了一下。只要再一步就能啟動它了！', 25549),
(122221, 'zhTW', '音樂的聲音變大了。', '音樂的聲音變大了。', 25549),
(122220, 'zhTW', '盒子發出一連串悅耳的聲音。', '盒子發出一連串悅耳的聲音。', 25549),
(122219, 'zhTW', '盒子閃了一下。', '盒子閃了一下。', 25549),
(122218, 'zhTW', '下次再有人想用魔法移動城市，你最好做好準備，什麼事都有可能發生！真的什麼事都有可能發生！', '', 25549),
(122217, 'zhTW', '你去按下那個紅色大按鈕，寫著「別押這個按鈕」的那個。', '', 25549),
(122216, 'zhTW', '這也可能是一個…系統全面故障的小問題。', '', 25549),
(122215, 'zhTW', '如果你想找桃樂西，她就在裡面。不過如果你需要補給品，我們目前無法處理任何訂單。我很抱歉。', '', 25549),
(122214, 'zhTW', '', '有很多人來問解除副作用的方法。$B$B要是我能找到那些老配方就好了…我很確定就放在這附近！', 25549),
(122213, 'zhTW', '', '喔，別理他。他這個人很健忘。所有古老的物品早在我們移動之前就妥善存放好了。$B$B等我們重新開張的時候，請再度光臨！我相信我們一定很快就會抵達目的地！', 25549),
(122212, 'zhTW', '我的起司只傳送過來一半！一半！$B$B於是現在我有一大堆酒和只能塞牙縫的美味起司屑，這讓我怎麼經營葡萄酒起司店啦！我無法接受！這簡直就是荒唐！荒唐！而且…$B$B喔，天啊！我開始頭暈了。這個世界到底怎麼了？', '', 25549),
(122211, 'zhTW', '', '幾乎都處理完畢了！誰能料到移動達拉然竟然會造成這麼多問題！還剩最後一個獸欄，還有鳥，然後一切就都恢復正常了！$B$B<環視著房間>。$B$B除了那個在魚缸旁的可憐傢伙以外。希望他們能快點解決那個問題。', 25549),
(122210, 'zhTW', '', '這地方簡直一團亂！', 25549),
(122209, 'zhTW', '', '保護弱者，主持正義，走上真理之道。', 25549),
(122208, 'zhTW', '', '化為守護弱者的寶盾，捍衛信仰的使者，懲戒惡徒的利劍。', 25549),
(122207, 'zhTW', '', '化為聖光的勇士。', 25549),
(122206, 'zhTW', '', '此誓以後，我將重生。', 25549),
(122205, 'zhTW', '', '並謙恭地對待所有兄弟姊妹。', 25549),
(122204, 'zhTW', '', '我將生命獻給白銀之手騎士團。', 25549),
(122202, 'zhTW', '', '我，在眾位勇士跟前，立下這個神聖的誓言：', 25549),
(122201, 'zhTW', '<給法力刃豹10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', '<給法力刃豹10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', 25549),
(122200, 'zhTW', '<法力刃豹看著你，彷彿你身上有牠想吃的東西。>', '', 25549),
(122198, 'zhTW', '好在魚缸在我們移動之前就清空了，不然我們的麻煩會更大！', '', 25549),
(122197, 'zhTW', '我目前還沒有頭緒。再撐一下！我們會想出辦法的。', '', 25549),
(122196, 'zhTW', '我需要一點時間思考。這種狀況挺特殊的。這不是那種可以做到一半就放著的工作…', '', 25549),
(122195, 'zhTW', '別擔心，我們轉眼就能讓你離開那裡…你。為什麼我老是跟這個東西說話？', '', 25549),
(122194, 'zhTW', '如果我們往順時鐘轉一點點，就能…不對。或許是逆時鐘才對…', '', 25549),
(122193, 'zhTW', '當你準備好時，在祭壇念出誓言。', '當你準備好時，在祭壇念出誓言。', 25549),
(122192, 'zhTW', '呃，也許等等我們就能動了。誰知道呢？也許問題會自己解決！', '', 25549),
(122191, 'zhTW', '', '凡席爾認為我們在這裡比較安全。在我親愛的可琳發生那件事之後，我開始認為他說得對。\n\n夜落精靈的日子很苦，但是我們會撐過去。\n\n再次謝謝你救了我女兒。', 25549),
(122190, 'zhTW', '為水晶法器充能', '為水晶法器充能', 25549),
(122189, 'zhTW', '', '我們隨時可以開始。', 25549),
(122188, 'zhTW', '剛剛是誰？快住手！有人在從另一邊戳我！', '', 25549),
(122187, 'zhTW', '什麼叫「等我們再度閃現」？我不能待在這裡啊！我還有事情要做！', '', 25549),
(122186, 'zhTW', '我之前沒注意過，地板上這些石頭保養得真好。', '', 25549),
(122185, 'zhTW', '好啦，但出現惡魔的話，記得保護我！我不太能保護自己，你懂我的意思吧。', '', 25549),
(122184, 'zhTW', '喔，你看。又來一個旁觀者。好極了…好好享受這場秀。全都過來看我這可憐的地精。等我有機會從這裡下去就讓你們好看…', '', 25549),
(122183, 'zhTW', '喂！慢一點好不好！可以的話，我還想留住雙腿…等等嘛！如果我在這裡，那我身體的其他部分又在哪！？', '', 25549),
(122182, 'zhTW', '專家，是吧？我已經困在這裡好幾個小時了！', '', 25549),
(122181, 'zhTW', '法力刃豹親熱地發出呼嚕聲，呼喚你靠近。', '', 25549),
(122180, 'zhTW', '', '我為了幫助他人而成為牧師，但近來我常常思考，有沒有辦法再做更多。', 25549),
(122179, 'zhTW', '徵募卓越者', '徵募卓越者', 25549),
(122178, 'zhTW', '你無法指揮卓越者，只能釋放他們毀滅敵人。', '你無法指揮卓越者，只能釋放他們毀滅敵人。', 25549),
(122177, 'zhTW', '<給織焰者歐芬25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', '<給織焰者歐芬25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', 25549),
(122176, 'zhTW', '我的火焰…消散了。我在這個世界撐不了多久…', '', 25549),
(122175, 'zhTW', '下一張破碎命運徽印的訂單。', '下一張破碎命運徽印的訂單。', 25549),
(122174, 'zhTW', '戴上超有型的間諜眼鏡找出血跡！', '戴上超有型的間諜眼鏡找出血跡！', 25549),
(122173, 'zhTW', '無冕者必須使出所有擅長的手段對付燃燒軍團，包含各種詭計、狡黠、詐欺，當然還有政治手段。\n\n在擊敗燃燒軍團之前，大家能不能通力合作是我最重視的事情，$n。我相信對你來說也是。', '', 25549),
(122172, 'zhTW', '<給時光法師維林亞25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', '<給時光法師維林亞25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', 25549),
(122171, 'zhTW', '', '幫幫我…拜託。我的思緒…好混亂。', 25549),
(122170, 'zhTW', '我們樂意接受你的協助，德菈絲。聖光齊心照耀時最明亮。', '', 25549),
(122169, 'zhTW', '我找到一個了！立刻加強這一區的防守。', '', 25549),
(122168, 'zhTW', '燃燒軍團會在我面前顫抖！萬物都會在我面前顫抖！', '', 25549),
(122167, 'zhTW', '你們的生命能量讓我變強了！我無人能擋！', '', 25549),
(122166, 'zhTW', '我要成為艾澤拉斯復仇的化身！', '', 25549),
(122165, 'zhTW', '你們必須死，我才能活著！我有我的命運！我必須拯救世界！', '', 25549),
(122164, 'zhTW', '謝謝你們的犧牲，你們的死不會白費。', '', 25549),
(122163, 'zhTW', '如果有其他辦法就好了。但我必須有保護世界的力量。', '', 25549),
(122162, 'zhTW', '你們的生命力讓這個世界有反擊的機會。', '', 25549),
(122161, 'zhTW', '我也不想肩負這個重擔，但命運已經注定…', '', 25549),
(122160, 'zhTW', '你選擇的路很黑暗，伊利丹。這是一條不歸路…', '你選擇的路很黑暗，伊利丹。這是一條不歸路…', 25549),
(122159, 'zhTW', '月神救我！', '月神救我！', 25549),
(122158, 'zhTW', '伊利丹…為什麼？', '伊利丹…為什麼？', 25549),
(122157, 'zhTW', '難道你們沒看見我為了守護族人所做的犧牲？', '', 25549),
(122156, 'zhTW', '朋友，我保證你的家人會受到良好的照顧。', '', 25549),
(122155, 'zhTW', '抵禦燃燒軍團，勢必需要有人犧牲！', '', 25549),
(122154, 'zhTW', '你們不能批判我！我做的一切都是為了艾澤拉斯！', '', 25549),
(122153, 'zhTW', '為了拯救這世界，只能犧牲你們了！', '', 25549),
(122152, 'zhTW', '有這樣的機會奉獻，你們應該心懷感激！', '', 25549),
(122151, 'zhTW', '看看你周圍！這是唯一的辦法！', '', 25549),
(122150, 'zhTW', '忠心的侍從，你們是為了崇高的理想犧牲！', '', 25549),
(122149, 'zhTW', '我必須這麼做！', '', 25549),
(122148, 'zhTW', '你要我的魔力？馬上讓你嘗嘗！', '你要我的魔力？馬上讓你嘗嘗！', 25549),
(122147, 'zhTW', '你會受到制裁，伊利丹！', '你會受到制裁，伊利丹！', 25549),
(122146, 'zhTW', '背叛者！', '背叛者！', 25549),
(122145, 'zhTW', '你跟那些襲擊我們的惡魔沒兩樣！', '你跟那些襲擊我們的惡魔沒兩樣！', 25549),
(122144, 'zhTW', '你要我的生命力？有種就來拿啊！', '你要我的生命力？有種就來拿啊！', 25549),
(122143, 'zhTW', '你背叛了所有人！', '你背叛了所有人！', 25549),
(122142, 'zhTW', '你不配當隊長，伊利丹！去死吧！', '你不配當隊長，伊利丹！去死吧！', 25549),
(122141, 'zhTW', '玄鴉衛士，將這些混帳送回他們主人身邊！為了艾薩拉！為了卡林多！', '', 25549),
(122140, 'zhTW', '我不會束手就擒的！', '我不會束手就擒的！', 25549),
(122139, 'zhTW', '伊利丹，你這個怪物！', '伊利丹，你這個怪物！', 25549),
(122138, 'zhTW', '我的鎖鏈會禁錮你。', '', 25549),
(122137, 'zhTW', '下一張勇士武裝的訂單。', '下一張勇士武裝的訂單。', 25549),
(122136, 'zhTW', '我能幫你取得一些珍貴物品。', '我能幫你取得一些珍貴物品。', 25549),
(122135, 'zhTW', '快住手！我們快死了！', '快住手！我們快死了！', 25549),
(122134, 'zhTW', '你不能這麼作，伊利丹。', '你不能這麼作，伊利丹。', 25549),
(122133, 'zhTW', '不能動…無力…', '不能動…無力…', 25549),
(122132, 'zhTW', '力量沒了…', '力量沒了…', 25549),
(122131, 'zhTW', '主…主人，我快死了…', '主…主人，我快死了…', 25549),
(122130, 'zhTW', '下水道鯊魚？那是很兇惡的生物，我之前只見到過一次！', '', 25549),
(122129, 'zhTW', '好好享用溫啤酒跟冷香腸吧！去找老滑，告訴他是阿喬派你來的！', '', 25549),
(122128, 'zhTW', '有人看到我的兄弟，戴瑞嗎？', '', 25549),
(122127, 'zhTW', '那是什麼味道？', '', 25549),
(122126, 'zhTW', '狀況不會再變得更糟了。你說呢？', '', 25549),
(122125, 'zhTW', '往右邊抖抖！然後往左邊抖抖！', '', 25549),
(122123, 'zhTW', '有人見到臭坦基嗎？我開始擔心了。', '', 25549),
(122122, 'zhTW', '抖抖舞可不是免費的！', '', 25549),
(122120, 'zhTW', '我的妻子為了一條比目魚而離開我。', '', 25549),
(122119, 'zhTW', '朋友，下面的路可長得很。\n\n需要幫忙嗎？', '', 25549),
(122118, 'zhTW', '', '喔，你好啊，親愛的。你有任何需要，或是要我找別人幫你做什麼嗎？\n\n或是，你知道的，就算你只是想找人聊一聊，都可以到這裡來找妮琪。', 25549),
(122117, 'zhTW', '嗯？什麼事？$B$B抱歉，我剛態度不好，但我已經提出好幾次要求，希望能在決定移動城市以前先收到通知。現在你看看我的店…東西散得到處都是！伊爾汀跟凡妮莎得忙好幾個月才能整理完畢！$B$B總之，我先回去忙了，我得在城市再次移動以前完成這些附魔！', '', 25549),
(122116, 'zhTW', '謝謝你！', '', 25549),
(122115, 'zhTW', '只要一聲令下，我就會揭露敵人！', '', 25549),
(122114, 'zhTW', '', '苦難與你同在，$n。等你需要我們的時候，我們會準備好的。', 25549),
(122113, 'zhTW', '', '就算是最認真的工匠，偶爾也需要休息一下。拉個睡袋，來安全的壁爐旁休息吧。', 25549),
(122112, 'zhTW', '最好立刻趕往葛羅瑪許堡，$n。', '', 25549),
(122111, 'zhTW', '這個動作會耗費25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。你要繼續嗎？', '這個動作會耗費25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。你要繼續嗎？', 25549),
(122110, 'zhTW', '<給織能師克羅林25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', '<給織能師克羅林25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>', 25549),
(122109, 'zhTW', '這裡的感覺不太一樣。空氣很正常，但是有什麼不太對勁。$B$B自從我們來到這裡之後，所有人的表現都很反常。我說的不光只是閃現所造成的暈眩，而是大家的行為舉止和偶爾會聽到的耳語。', '', 25549),
(122108, 'zhTW', '我的腦袋…逐漸凋萎…誰來…幫我。', '', 25549),
(122107, 'zhTW', '[PH] And then a killer finale cinematic plays! [PH]', '[PH] And then a rad finale cinematic plays! [PH]', 25549),
(122106, 'zhTW', '等我付得起的時候，我會再回來的，亞魯因。', '等我付得起的時候，我會再回來的，亞魯因。', 25549),
(122105, 'zhTW', '我寫故我在。', '', 25549),
(122104, 'zhTW', '', '卓格巴入侵之後，我們能提供的資源不多了。但不管我們有什麼，你都能任意使用，英雄。', 25549),
(122103, 'zhTW', '', '歡迎你，外地人。$b$b很少看到你們族人來到這麼高的山上，但還是很歡迎你。', 25549),
(122102, 'zhTW', '下一個換誰來嚐嚐我的戰刃？', '', 25549),
(122100, 'zhTW', '什麼？喔，我沒發現你在這裡！你們這些$c什麼時候變得那麼神出鬼沒？$B$B我想知道，我們是不是很快就要離開，才好收拾東西。', '', 25549),
(122099, 'zhTW', '來吧，旅行者。和我們一起。$b$b請把這裡當自己家。$b$b停下腳步，和我們一起。$b$b和我們一起…', '', 25549),
(122098, 'zhTW', '一名惡魔獵人？令人作嘔！你的翅膀像皮做的，很詭異。', '一名惡魔獵人？啊 - 你的翅膀像皮做的，很詭異。', 25549),
(122097, 'zhTW', '', '你沒說謊，伊利亞斯。惡魔獵人在附近出沒。小心點…$n那種眼睛什麼都看得見。', 25549),
(122096, 'zhTW', '很高興又見到你，$n。希望你最近都好。\n\n<馬迪亞斯環顧四周，接著講話的聲音放低。>\n\n你和無冕者的進展如何？身為軍情七處的首領，我不能公開支援你。\n\n但，在對抗燃燒軍團的戰爭結束前，我保證會竭盡所能提供協助，就算只能在陰影中偷偷進行。\n\n後會有期。', '', 25549),
(122095, 'zhTW', '我希望徵募女盾侍。', '我希望徵募女盾侍。', 25549),
(122094, 'zhTW', '我希望徵募華爾琪。', '我希望徵募華爾琪。', 25549),
(122093, 'zhTW', '卜魯，拉塊石頭來休息吧。納瓦羅格允許你在這裡休息。', '', 25549),
(122092, 'zhTW', '', '你是惡魔獵人！太好了，我正好需要你幫忙。', 25549),
(122091, 'zhTW', '$n，你是燃燒軍團的人嗎？還是我們的盟友？好龐大的惡魔能量啊…', '', 25549),
(122090, 'zhTW', '', '我希望你在這個神聖的地方能好好控制你的…能力，「惡魔獵人」。我們會盯著你的。', 25549),
(122089, 'zhTW', '你對自己做了什麼，$n？比起$r你現在更接近惡魔。', '你對自己做了什麼，$n？比起$r你現在更接近惡魔。', 25549),
(122088, 'zhTW', '<嘀咕>', '', 25549),
(122087, 'zhTW', '', '我看，是一個擅長找藉口的勇士！', 25549),
(122086, 'zhTW', '我是你的勇士，黑暗女王。我的職責就是成就你的榮耀。', '', 25549),
(122085, 'zhTW', '$n，捷斯‧暗織者說得沒錯，奧達奇戰刃在你手上！有你帶領我們，伊利達瑞無人能敵。', '$n，捷斯‧暗織者說得沒錯，奧達奇戰刃在你手上！有你帶領我們，伊利達瑞無人能敵。', 25549),
(122084, 'zhTW', '', '我殺的敵人比你多太多了，納薩諾斯。你不中用了！', 25549),
(122083, 'zhTW', '$n！我看到你拿回了瓦瑞迪斯‧魔魂的雙刃。希望你比他能善加控制內心的惡魔。', '$n！我看到你拿回了瓦瑞迪斯‧魔魂的雙刃。希望你比他能善加控制內心的惡魔。', 25549),
(122082, 'zhTW', '你可以盡量使用光杖。聖光無限，有求必應。', '', 25549),
(122081, 'zhTW', '歡迎登船，$n。\n\n我們物資都準備好了，你好了隨時可以出發。', '', 25549),
(122080, 'zhTW', '如同費倫的水晶，你的法杖是我們為了救助瀕臨滅絕的種族，所給予的禮物。這些禮物剩下不多了。別讓它落入虛無。', '', 25549),
(122079, 'zhTW', '德萊尼是最適合使用光杖的種族。德萊尼能在其他種族無法存活的環境堅持下去。', '', 25549),
(122078, 'zhTW', '光杖沉寂了一段時間，也沒向我們求助。幸好你把它復原了。', '', 25549),
(122077, 'zhTW', '媽媽…爸爸…', '', 25549),
(122076, 'zhTW', '', '我聽過這兩位英雄的許多事蹟。但在我心裡還是有點懷疑，他們帶來的訊息真的是最重要的嗎？', 25549),
(122075, 'zhTW', '阿拉特是對的。圖拉揚和艾蘭里亞走了這麼長的一段路過來，就是為了警告我們。大領主，我們都靠你了，現在該怎麼做？', '', 25549),
(122074, 'zhTW', '如果不是親眼看到，我根本沒辦法相信。', '', 25549),
(122073, 'zhTW', '', '圖拉揚和艾蘭里亞…真不敢相信他們在這麼多年之後還活著…', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122072, 'zhTW', '', '以聖光之名…這代表什麼？', 25549),
(122071, 'zhTW', '', '只要你一聲令下，我就會揭露那些惡魔！', 25549),
(122070, 'zhTW', '為什麼這個可可脂這麼滑？給我毛巾！買可可脂的蠢蛋聽好了，你被開除了！', '', 25549),
(122069, 'zhTW', '歡迎光臨我的店，$n。抱歉這裡這麼亂，我們還在整理當中。$B$B上一次閃現真的給我們造成不少損失！', '', 25549),
(122068, 'zhTW', '', '你得原諒我。我最近常常突然頭暈。這個狀況在我們抵達不久後開始出現。', 25549),
(122067, 'zhTW', '', '這麼多的紙。之前都怎麼整理的？現在散得到處都是。$B$B看來得花好幾個禮拜才能把它們重新歸類！', 25549),
(122066, 'zhTW', '', '喔，我沒看到你在那！$B$B我們一直都在忙著整理。等我們整理好了，再來看我們吧。', 25549),
(122065, 'zhTW', '真抱歉這裡一團亂。我們已經整理一段時間了。$B$B<環顧他的店>。但好像沒什麼進展。這地方看起來像是被颱風掃過。我的貨物都受損了，這樣還有誰會來買東西呢？$B$B下次我會在移動整座城市之前，把所有東西都固定起來。', '', 25549),
(122064, 'zhTW', '呃…我什麼都沒有，$n。所有產品都延宕了，我們需要等候通知。$B$B這整個地方都毀了。閃現整座城市…到底是誰的主意？這地方要好幾個星期才能再回到正軌。', '', 25549),
(122063, 'zhTW', '', '目前最好暫且不要把這座旅店設為你的家。你下次回來的時候，我們可能不會在現在的這個確切位置上。', 25549),
(122062, 'zhTW', '', '啊！', 25549),
(122061, 'zhTW', '你知道發生什麼事了嗎？', '你知道發生什麼事了嗎？', 25549),
(122060, 'zhTW', '', '你也感覺到了嗎？我起雞皮疙瘩了…', 25549),
(122059, 'zhTW', '', '啊，那把劍，你拿的是什麼東西？疾病與腐敗隨你而來，死亡騎士！', 25549),
(122058, 'zhTW', '', '你手中的惡魔武器散發出腐化的惡臭，死亡騎士。辦完你該辦的事，就帶著那把武器遠離這座神殿。', 25549),
(122057, 'zhTW', '死亡騎士，你的武器有種疾病與瘟疫的氣息。你最好離賽諾苟斯遠一點。', '', 25549),
(122056, 'zhTW', '', '傳遍幽暗城的謠言看來是真的。你們重鑄了霜之哀傷！$n，小心點。那些刀刃也許有自己的意志。', 25549),
(122055, 'zhTW', '$n，你為何做出這種褻瀆的行為？你竟敢重鑄那把詛咒之劍，那把讓羅德隆及其王子萬劫不復的武器。我警告過阿薩斯不要碰觸霜之哀傷，現在我把同樣的話再對你說一次：把那些東西丟進海裡，別讓悲劇重演。', '', 25549),
(122054, 'zhTW', '', '那是…遭譴者之顎嗎？以軍團之矛反攻軍團之盾嗎？我喜歡你思考的方式，$n！', 25549),
(122053, 'zhTW', '去給我找出是誰幹的！他完蛋了！完蛋了！', '', 25549),
(122052, 'zhTW', '等等…我的鑰匙…有人偷走我保險櫃的鑰匙！', '', 25549),
(122051, 'zhTW', '呼…這裡可真熱。也許我該睡一覺…', '', 25549),
(122050, 'zhTW', '好了，我們去打破敵人的頭吧！', '', 25549),
(122049, 'zhTW', '蠢蛋們！我的可可脂呢？！你們是聽不懂「可可」還是聽不懂「脂」啊？！', '', 25549),
(122048, 'zhTW', '好啦，我要去三溫暖好好放鬆一下…記得幫我帶杯冰鎮雞尾酒和可可脂！', '', 25549),
(122047, 'zhTW', '你手中的斧頭…是燃燒軍團的武器。你確定自己能夠控制它的飢渴嗎？', '', 25549),
(122046, 'zhTW', 'Placeholder text.', '', 25549),
(122045, 'zhTW', '聽好，蠢蛋們！歡樂宮殿是私人土地！任何閒雜人等都不准踏進這裡！', '', 25549),
(122044, 'zhTW', 'No text', '', 25549),
(122043, 'zhTW', '只要潛入三溫暖，就能趁他沒把鑰匙帶在身上的時候，偷走鑰匙！', '', 25549),
(122042, 'zhTW', '今天是你的幸運日，朋友！加里維克斯現在就在他的個人專用三溫暖享受蒸汽浴。', '', 25549),
(122041, 'zhTW', '燃燒軍團去死吧。', '', 25549),
(122040, 'zhTW', '', '你所持的那對武器…它們受到詛咒。請不要將死亡的寒意帶進這個聖地！', 25549),
(122039, 'zhTW', '', '艾澤拉斯不能亡。', 25549),
(122038, 'zhTW', '', '如果他閉口不談，就提醒他，他「那時候」欠我的「那筆帳」還沒還…懂嗎？', 25549),
(122037, 'zhTW', '', '去找『酒保』伊札克，他應該知道怎樣拿到保險箱的鑰匙。', 25549),
(122036, 'zhTW', '', '伊利丹大人會帶領我們。', 25549),
(122035, 'zhTW', '', '每次我們閃現，我都得花好幾天的時間重新擺好我的商品。真希望有個更輕鬆的方式來整理這一團混亂。', 25549),
(122034, 'zhTW', '我敢打賭那些蠢蛋一定會來排隊搶購的！', '', 25549),
(122033, 'zhTW', '這可是一生一次的好機會！', '', 25549),
(122032, 'zhTW', '', '只有我們能阻止燃燒軍團毀掉一切。', 25549),
(122031, 'zhTW', '', '拜託你，死亡騎士。不要用你手中的邪惡斧頭玷污這個聖地。我站在這裡都能感受到它的飢渴。', 25549),
(122030, 'zhTW', '', '不是你的…那把權杖不是你的…', 25549),
(122029, 'zhTW', '', '你竟敢將我們尊貴女王的權杖據為己有…', 25549),
(122028, 'zhTW', '偷偷摸摸的傢伙，你完蛋了！', '', 25549),
(122027, 'zhTW', '', '那把權杖屬於我們的女王…', 25549),
(122026, 'zhTW', '有人混進來了！', '', 25549),
(122025, 'zhTW', '你不該出現在這裡的！', '', 25549),
(122024, 'zhTW', '', '那把權杖不是你的，薩滿。把它還回去！', 25549),
(122023, 'zhTW', '你鬼鬼祟祟讓我好生氣！', '', 25549),
(122022, 'zhTW', '我要把你打成肉醬！', '', 25549),
(122021, 'zhTW', '我找到你了！去死吧！', '', 25549),
(122020, 'zhTW', '我看到你了！你完了！！', '', 25549),
(122019, 'zhTW', '有人在附近！', '', 25549),
(122018, 'zhTW', '我知道你在那裡…快出來！', '', 25549),
(122017, 'zhTW', '出來讓我看看你！懦夫！', '', 25549),
(122016, 'zhTW', '有人躲在附近！', '', 25549),
(122015, 'zhTW', '陛下！有個陌生人過來了。他手上的武器有艾薩拉女王的印記。', '陛下！有個陌生人過來了。他手上的武器有艾薩拉女王的印記。', 25549),
(122014, 'zhTW', '那什麼聲音？', '', 25549),
(122013, 'zhTW', '有人躲在這附近！', '', 25549),
(122012, 'zhTW', '誰在那裡偷偷摸摸的？！', '', 25549),
(122011, 'zhTW', '保重。', '', 25549),
(122010, 'zhTW', '我準備好了。', '我準備好了。', 25549),
(122009, 'zhTW', '空氣中有股不祥的氣味。自從我們抵達之後，人們就出現各種怪異的行為。而議會…他們一直一直開會。希望一切都沒問題。', '', 25549),
(122008, 'zhTW', '', '自從我們移到這裡之後，這地方就變得很安靜。或許他們身上的副作用還沒有消退。畢竟移動整個達拉然可不是件簡單的事！$B$B希望一切快點恢復正常。', 25549),
(122007, 'zhTW', '瘋狂在呼喚我…', '', 25549),
(122006, 'zhTW', '深淵低聲說著你的名字。', '', 25549),
(122005, 'zhTW', '夢魘在翻動，無法捉摸…也不會死。', '', 25549),
(122004, 'zhTW', '沒有希望，就不會絕望。', '', 25549),
(122003, 'zhTW', '愚蠢的凡人！你是贏不了的…', '', 25549),
(122002, 'zhTW', '主人會摧毀…你的靈魂！', '', 25549),
(122001, 'zhTW', '無邊的黑暗…等著我。', '', 25549),
(122000, 'zhTW', '我的生命…獻給主人…', '', 25549),
(121999, 'zhTW', '我要是無法控制你的心智，那就摧毀你的肉體。', '', 25549),
(121998, 'zhTW', '我來讓你看看逞英雄的下場。', '', 25549),
(121997, 'zhTW', '來點樂子…大聲呼救吧！', '', 25549),
(121996, 'zhTW', '你無法阻止將到來的黑暗。連在夢中也不行。', '', 25549),
(121995, 'zhTW', '夢魘會吞噬你！', '', 25549),
(121994, 'zhTW', '準備承受無盡的折磨！', '', 25549),
(121993, 'zhTW', '我會讓你陷入永恆的長眠。', '', 25549),
(121992, 'zhTW', '', '抱歉，$n。發生了這麼多事，看來我應該有好一陣子沒辦法剪頭髮了。大多數的商人也都關了他們的店。$B$B<看向周遭的其他商人。>$B$B大家都在說，有大事要發生了，而且不僅僅是這裡。城市本身就充滿了…嗯，我也不知道，而且我也不該說太多。我不希望大家開始恐慌。我們要應付的事已經夠多了。', 25549),
(121991, 'zhTW', '你就是黑暗的獵物！', '', 25549),
(121990, 'zhTW', '崔希妮派我來的。我需要保險庫的鑰匙…她說你「欠她的。」', '崔希妮派我來的。我需要保險庫的鑰匙…她說你「欠她的。」', 25549),
(121989, 'zhTW', '蠢蛋…這片土地注定會被毀滅…', '', 25549),
(121988, 'zhTW', '如果你是來這裡找麻煩的，請恕我不能奉陪…我在幹嘛？別的什麼東西都比這個好多了！', '', 25549),
(121987, 'zhTW', '歡迎來到你的夢魘！', '', 25549),
(121986, 'zhTW', '夢魘…等著我…', '', 25549),
(121985, 'zhTW', '你願意為這片破土地送死？', '', 25549),
(121984, 'zhTW', '真可惜。你明明可以加入我們的…', '', 25549),
(121983, 'zhTW', '想打架？讓我來…', '', 25549),
(121982, 'zhTW', '我在想，夜精靈會不會為你哀悼呢？', '', 25549),
(121981, 'zhTW', '你別想阻止我們。我們是燃燒軍團！', '', 25549),
(121980, 'zhTW', '我警告過你了。', '', 25549),
(121979, 'zhTW', '你現在還不明白，但你會懂的。', '', 25549),
(121978, 'zhTW', '你這是無謂的抵抗！', '', 25549),
(121977, 'zhTW', '諾格弗格派我來的。我必須侵入保險庫。', '諾格弗格派我來的。我必須侵入保險庫。', 25549),
(121976, 'zhTW', '這片土地完蛋了！', '', 25549),
(121975, 'zhTW', '你逃不出夢魘之王的掌握！', '', 25549),
(121974, 'zhTW', '主人…', '', 25549),
(121973, 'zhTW', '', '噓…小聲一點！要是被發現在交談，我們就死定了！', 25549),
(121972, 'zhTW', '你的世界…注定毀滅…', '', 25549),
(121971, 'zhTW', '放棄吧！這個世界沒有希望…', '', 25549),
(121970, 'zhTW', '死亡無法…阻止我們…', '', 25549),
(121969, 'zhTW', '你的雙手…也染滿了鮮血…', '', 25549),
(121968, 'zhTW', '呃啊啊…', '', 25549),
(121967, 'zhTW', '恐懼…正…等著…你…', '', 25549),
(121966, 'zhTW', '主人會燒毀這個世界，還有你！', '', 25549),
(121965, 'zhTW', '你很快就會張開雙手，迎接死亡！', '', 25549),
(121964, 'zhTW', '你無法…逃離…你的夢境…', '', 25549),
(121963, 'zhTW', '我好像…弄髒褲子了！拜託…別殺我！', '', 25549),
(121962, 'zhTW', '你在外奮戰時，我們也會試著拿下更靠近神殿的區域。願伊露恩指引你，$n。', '', 25549),
(121961, 'zhTW', '是軍情七處！他們要用暴風城的財富交換琥珀‧吉爾妮！', '', 25549),
(121960, 'zhTW', '喔天啊！我聽過你的名聲…饒了我吧！', '', 25549),
(121959, 'zhTW', '聽你這麼說…我好像有點想起來了。', '', 25549),
(121958, 'zhTW', '我…我才不說哩！', '', 25549),
(121957, 'zhTW', '把她的頭帶來，血刃海盜就可以在暴風港隨意進出，過去的罪行也一併赦免！', '', 25549),
(121956, 'zhTW', '我，馬迪亞斯·肖爾，在此授權血刃海盜追殺叛逃特務，琥珀‧吉爾妮。', '', 25549),
(121955, 'zhTW', '你必須待在神廟頂層！', '你必須待在神廟頂層！', 25549),
(121954, 'zhTW', '白銀之手…', '', 25549),
(121953, 'zhTW', '真理之盾…', '', 25549),
(121952, 'zhTW', '我們準備好進行任務了。', '我們準備好進行任務了。', 25549),
(121951, 'zhTW', '說得好！', '', 25549),
(121950, 'zhTW', '該當如此。', '', 25549),
(121949, 'zhTW', '', '我願意接受你的忠誠，$n。部落永存！', 25549),
(121948, 'zhTW', '眼睛睜大點，$n…前方有一群海盜！', '', 25549),
(121947, 'zhTW', '大人，燃燒軍團破壞了長程傳送網路，要旅行到其他地方…變難了。', '', 25549),
(121946, 'zhTW', '忠心耿耿的月之守衛，我需要你們的生命力。', '', 25549),
(121945, 'zhTW', '需要更多力量才能打贏這場戰爭…', '', 25549),
(121944, 'zhTW', '請原諒我做的一切。', '', 25549),
(121943, 'zhTW', '我的死期未到，但很遺憾，你們的到了。', '', 25549),
(121942, 'zhTW', '<蠍尾獅揮舞著雙翅，期待著接下來的戰鬥>', '<蠍尾獅揮舞著雙翅，期待著接下來的戰鬥>', 25549),
(121941, 'zhTW', '願樹林保護你。', '', 25549),
(121940, 'zhTW', '好好思考吧，朋友。', '', 25549),
(121939, 'zhTW', '很久沒有好好聊聊了。', '', 25549),
(121938, 'zhTW', '你在找什麼？', '', 25549),
(121937, 'zhTW', '不要急。', '', 25549),
(121936, 'zhTW', '我來讓你看看逞英雄的下場。', '', 25549),
(121935, 'zhTW', '我警告過你了。', '', 25549),
