INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(116167, 'zhTW', '那就讓我們來測試你的歷史知識吧！在敦霍爾德城堡囚禁索爾的人類叫什麼名字？', '', 25549),
(116166, 'zhTW', '小心！綠綠人勢如洪流！打爛他們！不留活口！', '', 25549),
(116165, 'zhTW', '燻木牧場。', '燻木牧場。', 25549),
(116164, 'zhTW', '', '血肉之子，收拾自己造成的爛攤子，也別再把垃圾扔到我的地盤！', 25549),
(116163, 'zhTW', '卡亞羅貿易公司。', '卡亞羅貿易公司。', 25549),
(116162, 'zhTW', '風險投資公司。', '風險投資公司。', 25549),
(116161, 'zhTW', '黑水強盜。', '黑水強盜。', 25549),
(116160, 'zhTW', '那就讓我們來測試你的歷史知識吧！哪一個哥布林公司經常四處掠奪艾澤拉斯的自然資源？', '', 25549),
