UPDATE `broadcast_text_locale` SET `MaleText_lang`='這就是地獄吼最終的下場。$b$b<沃金小心翼翼地看著你。>$b$b下一步是什麼，$r？', `VerifiedBuild`=25549 WHERE (`ID`=77371 AND `locale`='zhTW');
