UPDATE `broadcast_text_locale` SET `MaleText_lang`='|TInterface\\Icons\\inv_misc_bomb_05:20|t你獲得|cFFFF0000|Hspell:145996|h[引爆]|h|r！使用|cFFFF0000|Hspell:146364|h[投擲炸彈]|h|r來投擲炸彈！', `VerifiedBuild`=25549 WHERE (`ID`=77369 AND `locale`='zhTW');
