UPDATE `broadcast_text_locale` SET `MaleText_lang`='巴琳達·石爐上尉已經死啦！打敗范達爾，勝利就屬於我們的了！', `VerifiedBuild`=25549 WHERE (`ID`=9308 AND `locale`='zhTW');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='戰爭情式惡化，我們的隊長和敵人的隊長都被殺死了！$B$B現在，德雷克塔爾領導著來自霜狼要塞的部隊，而矮人范達爾·雷矛則藏在丹巴達爾。殺死范達爾，為了部落的勝利而戰！', `VerifiedBuild`=25549 WHERE (`ID`=9307 AND `locale`='zhTW');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='雷矛將軍倒下了！戰鬥獲勝啦！$B$B嘲笑那些趕著收復他們最後據點的聯盟部隊吧。', `VerifiedBuild`=25549 WHERE (`ID`=9306 AND `locale`='zhTW');
