UPDATE `broadcast_text_locale` SET `MaleText_lang`='六名中尉指揮著前線的防禦事務。必須迅速解決他們！我們絕不能讓他們的任何一名牧師活著逃回去。$B$B要是我們能很快結果掉所有的中尉，前線的士氣將大跌！戰線也會很快攻破！他們的軍隊將落荒而逃，留守的士兵將失去後援。', `VerifiedBuild`=25549 WHERE (`ID`=9083 AND `locale`='zhTW');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=9082 AND `locale`='zhTW');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='那麼聽好了，$c。$B$B你能感知到從我身上散發出的力量嗎？你的士氣不夠？是的，對另一方來說也是這樣。要破壞瓦解他們的軍隊並不容易，但是必須完成任務！勝利是屬於我們的！', `VerifiedBuild`=25549 WHERE (`ID`=9081 AND `locale`='zhTW');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=9080 AND `locale`='zhTW');
